
      
    // ================= [TOOLKIT_v6.1.1_START] =================
    // [物品分类模块] 全局变量 & 辅助函数
    // 使用 window 挂载，确保重复注入时不报错且保留已有值

    window.inventoryItems = window.inventoryItems || [];
    window.currentInvFilter = window.currentInvFilter || 'all';
    window.isInventorySorted = window.isInventorySorted || false;

    async function loadFabShortcutConfig() {
        try {
            if (typeof window !== 'undefined' && window && typeof window.loadFabShortcutConfig === 'function' && window.loadFabShortcutConfig !== loadFabShortcutConfig) {
                return await window.loadFabShortcutConfig();
            }
        } catch (_) {}
        return {};
    }

    if (typeof window !== 'undefined' && window && typeof window.loadFabShortcutConfig !== 'function') {
        window.loadFabShortcutConfig = loadFabShortcutConfig;
    }

    function ensureToolboxPlayerRowFallback() {
        try {
            const state = (typeof currentState !== 'undefined' && currentState)
                ? currentState
                : ((typeof window !== 'undefined' && window.currentState) ? window.currentState : null);
            if (!state || !state['0'] || typeof state['0'] !== 'object') return null;
            if (state['0']['B1'] && typeof state['0']['B1'] === 'object') return state['0']['B1'];

            let fallback = null;
            try {
                if (typeof currentPlayerData !== 'undefined' && currentPlayerData && typeof currentPlayerData === 'object') {
                    fallback = currentPlayerData;
                }
            } catch (e) {}
            if (!fallback && typeof window !== 'undefined' && window.currentPlayerData && typeof window.currentPlayerData === 'object') {
                fallback = window.currentPlayerData;
            }
            if (!fallback || typeof fallback !== 'object') fallback = {};
            state['0']['B1'] = fallback;
            return state['0']['B1'];
        } catch (e) {
            return null;
        }
    }

    function syncLegacyInventoryArray(nextItems) {
        const normalized = Array.isArray(nextItems) ? nextItems.slice() : [];
        window.inventoryItems = normalized;
        try {
            inventoryItems = normalized.slice();
        } catch(e) {}
        return normalized;
    }

    function getInventoryCacheSnapshot(targetObject = null) {
        if (targetObject && Array.isArray(targetObject.inventoryItems)) {
            return normalizeInventoryList(targetObject.inventoryItems);
        }

        if (typeof inventoryItems !== 'undefined' && Array.isArray(inventoryItems)) {
            return normalizeInventoryList(inventoryItems);
        }

        if (Array.isArray(window.inventoryItems)) {
            return normalizeInventoryList(window.inventoryItems);
        }

        const api = typeof window.getTheaterAPI === 'function' ? window.getTheaterAPI() : null;
        if (api) {
            try {
                let invData = typeof api.getInventory === 'function' ? api.getInventory() : null;
                if ((!invData || (Array.isArray(invData) && invData.length === 0)) && typeof api.getPlayerData === 'function') {
                    const playerData = api.getPlayerData();
                    if (playerData) {
                        invData = playerData.inventory || playerData.items ||
                            (playerData.detailedAttributes && playerData.detailedAttributes.inventory) || null;
                    }
                }
                if (Array.isArray(invData) || (invData && typeof invData === 'object')) {
                    return normalizeInventoryList(invData);
                }
            } catch(e) {}
        }

        return [];
    }

    function escapeInventoryHtml(str) {
        return String(str || '')
            .replace(/&/g, '&' + 'amp;')
            .replace(/</g, '&' + 'lt;')
            .replace(/>/g, '&' + 'gt;')
            .replace(/"/g, '&' + 'quot;')
            .replace(/'/g, '&#' + '39;');
    }

    function normalizeInventoryColorToken(token) {
        const value = String(token || '').trim().replace(/["']/g, '').toLowerCase();
        const colorMap = {
            'green': '#66bb6a',
            'limegreen': '#66bb6a',
            'dodgerblue': '#42a5f5',
            'deepskyblue': '#42a5f5',
            'mediumorchid': '#ab47bc',
            'purple': '#ab47bc',
            'crimson': '#ef5350',
            'red': '#ef5350',
            'orangered': '#ef5350',
            'gold': '#ffd700',
            'yellow': '#ffd54f',
            'orange': '#ffa726',
            'white': '#f5f5f5'
        };
        return colorMap[value] || (value ? value : '#8c7853');
    }

    function softenInventoryAccentColor(color) {
        const raw = String(color || '').trim();
        if (!raw) return '#8c7853';

        let r = 140;
        let g = 120;
        let b = 83;
        let parsed = false;

        const hexMatch = raw.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
        if (hexMatch) {
            let hex = hexMatch[1];
            if (hex.length === 3) {
                hex = hex.split('').map(function(ch) { return ch + ch; }).join('');
            }
            r = parseInt(hex.slice(0, 2), 16);
            g = parseInt(hex.slice(2, 4), 16);
            b = parseInt(hex.slice(4, 6), 16);
            parsed = true;
        } else {
            const rgbMatch = raw.match(/^rgbs*(s*(d{1,3})s*,s*(d{1,3})s*,s*(d{1,3})s*)$/i);
            if (rgbMatch) {
                r = Math.max(0, Math.min(255, Number(rgbMatch[1]) || 0));
                g = Math.max(0, Math.min(255, Number(rgbMatch[2]) || 0));
                b = Math.max(0, Math.min(255, Number(rgbMatch[3]) || 0));
                parsed = true;
            }
        }

        if (!parsed) return raw;

        function mix(channel, target, ratio) {
            return Math.round(channel * (1 - ratio) + target * ratio);
        }

        const avg = Math.round((r + g + b) / 3);
        r = mix(r, avg, 0.42);
        g = mix(g, avg, 0.42);
        b = mix(b, avg, 0.42);

        r = mix(r, 72, 0.18);
        g = mix(g, 62, 0.18);
        b = mix(b, 48, 0.18);

        r = mix(r, 170, 0.10);
        g = mix(g, 146, 0.10);
        b = mix(b, 98, 0.10);

        return '#' + [r, g, b].map(function(channel) {
            return channel.toString(16).padStart(2, '0');
        }).join('');
    }

    function stripInventoryHtml(rawName) {
        return String(rawName || '')
            .replace(/<br\s*\/?>/ig, ' ')
            .replace(/<[^>]+>/g, '')
            .replace(/\[\/color\]/ig, '')
            .replace(/\[color\s*=\s*[^\]]+\]/ig, '')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function extractInventoryColor(rawName) {
        const name = String(rawName || '');
        const patterns = [
            /style\s*=\s*["'][^"']*color\s*:\s*([^;"']+)/i,
            /<font[^>]*color\s*=\s*["']?([^"'>\s]+)/i,
            /\[color\s*=\s*([^\]]+)\]/i,
            /color\s*=\s*["']?([^"'<>\s;]+)/i,
            /color\s*:\s*([^;"'<>]+)/i
        ];
        for (const pattern of patterns) {
            const match = name.match(pattern);
            if (match && match[1]) {
                return normalizeInventoryColorToken(match[1]);
            }
        }
        if (name.indexOf('color:green') !== -1) return '#66bb6a';
        if (name.indexOf('color:dodgerblue') !== -1) return '#42a5f5';
        if (name.indexOf('color:mediumorchid') !== -1) return '#ab47bc';
        if (name.indexOf('color:crimson') !== -1) return '#ef5350';
        return '#8c7853';
    }

    function buildInventoryDisplayName(rawName, maxChinese) {
        const plainName = stripInventoryHtml(rawName) || '未知物品';
        const color = extractInventoryColor(rawName);
        const maxCount = Number(maxChinese) > 0 ? Number(maxChinese) : 5;
        let chineseCount = 0;
        let truncateIndex = plainName.length;
        for (let i = 0; i < plainName.length; i++) {
            const char = plainName[i];
            if (/[一-龥]/.test(char)) {
                chineseCount++;
                if (chineseCount > maxCount) {
                    truncateIndex = i;
                    break;
                }
            }
        }
        const displayText = chineseCount > maxCount ? (plainName.substring(0, truncateIndex) + '..') : plainName;
        return {
            plainName,
            color,
            displayText,
            html: '<span style="color:' + color + '">' + escapeInventoryHtml(displayText) + '</span>'
        };
    }

    function getInventoryRarityColor(item) {
        try {
            if (window.FrItemPresentation) return window.FrItemPresentation.rarity(item).color;
            const readColor = window.frContainerEquipmentColor || window.parent.frContainerEquipmentColor;
            if (typeof readColor === 'function') return readColor(item);
        } catch (_) {}
        return '';
    }

    function normalizeInventoryItem(rawItem, fallbackId) {
        const item = rawItem || {};
        const id = item.id || item['0'] || fallbackId || ('unknown_' + Math.random().toString(36).substr(2, 9));
        const name = item.name || item['1'] || '未知物品';
        const type = item.type || item.category || item['2'] || '杂物';
        const description = item.description || item.desc || item['3'] || '';
        const effect = item.effect || item.attr || item['4'] || '';
        const qtyRaw = item.quantity || item.count || item['5'] || 1;
        const quantity = Number(qtyRaw) > 0 ? Number(qtyRaw) : 1;

        return {
            ...item,
            id,
            name,
            type,
            description,
            effect,
            quantity
        };
    }

    function normalizeInventoryList(rawList) {
        if (!rawList) return [];
        if (Array.isArray(rawList)) {
            return rawList.map((it, idx) => normalizeInventoryItem(it, idx));
        }
        return Object.keys(rawList).map(id => normalizeInventoryItem(rawList[id], id));
    }

    function getLatestInventoryItems(candidates) {
        const arr = Array.isArray(candidates) ? candidates : [candidates];
        let sawExplicitArray = false;
        let firstExplicitArray = null;

        for (let i = 0; i < arr.length; i++) {
            if (!Array.isArray(arr[i])) continue;
            sawExplicitArray = true;
            const candidateItems = normalizeInventoryList(arr[i]);
            if (!firstExplicitArray) {
                firstExplicitArray = candidateItems;
            }
            if (candidateItems.length > 0) {
                return syncLegacyInventoryArray(candidateItems);
            }
        }

        const cacheSnapshot = getInventoryCacheSnapshot();
        if (cacheSnapshot.length > 0) {
            console.log('【物品分类】检测到空数组入参，已回退到缓存物品:', cacheSnapshot.length);
            return syncLegacyInventoryArray(cacheSnapshot);
        }

        if (sawExplicitArray) {
            return syncLegacyInventoryArray(firstExplicitArray || []);
        }

        return syncLegacyInventoryArray([]);
    }

    let theaterAPI = null;
    const __toolkitNativeSyncStateFromTables = typeof syncStateFromTables === 'function' ? syncStateFromTables : null;

    const INV_FILTERS = {
        'all': [],
        'equip': ['装备', '武器', '护甲', '法宝', '灵宝', '宝器'],
        'consumable': ['消耗', '消耗品', '丹药', '符箓', '灵兽丹', '药剂', '食物'],
        'book': ['功法', '神通', '秘籍', '玉简', '法术书', '心法', '术法', '道法'],
        'material': ['材料', '妖丹', '矿石', '草药', '灵药', '种子', '锻材', '灵材'],
        'rare': ['重要物品', '珍宝', '任务物品', '信物', '钥匙', '地图', '宝物'],
        'misc': ['其他物品', '杂物', '货币兑换物', '其他']
    };

    function matchInventoryFilterType(item, allowedTypes) {
        if (window.FrEquipmentRuntime && Array.isArray(allowedTypes)) {
            const info = window.FrEquipmentRuntime.classify(item);
            const filterKey = Object.keys(INV_FILTERS).find(key => INV_FILTERS[key] === allowedTypes);
            if (filterKey) return {equip:['equipment','treasure'],consumable:['consumable'],book:['technique'],material:['material'],rare:['rare'],misc:['misc']}[filterKey]?.includes(info.category) || false;
        }
        const rawType = String((item && (item.type || item.category || item.kind || item['2'])) || '').trim();
        if (!rawType || !Array.isArray(allowedTypes) || allowedTypes.length === 0) return false;
        return allowedTypes.some(function(allowed) {
            const normalized = String(allowed || '').trim();
            return normalized && (rawType === normalized || rawType.indexOf(normalized) !== -1 || normalized.indexOf(rawType) !== -1);
        });
    }

    function getInventorySlotResolvedType(slot, runtimeItems) {
        if (!slot) return '';
        const itemId = slot.dataset && slot.dataset.itemId ? String(slot.dataset.itemId) : '';
        if (itemId && Array.isArray(runtimeItems) && runtimeItems.length > 0) {
            const matched = runtimeItems.find(function(entry) {
                return entry && String(entry.id) === itemId;
            });
            if (matched) {
                return String((matched.type || matched.category || matched.kind || matched['2']) || '').trim();
            }
        }
        const titleText = String(slot.title || '');
        const typeMark = '类型:';
        const typeAltMark = '类型：';
        let startIdx = titleText.indexOf(typeMark);
        let markLength = typeMark.length;
        if (startIdx === -1) {
            startIdx = titleText.indexOf(typeAltMark);
            markLength = typeAltMark.length;
        }
        if (startIdx !== -1) {
            return titleText.slice(startIdx + markLength).split('\n')[0].trim();
        }
        return '';
    }

    window.applyInventoryFilterToGrid = function() {
        const grid = document.getElementById('inventory-grid');
        if (!grid) return false;

        Array.from(grid.querySelectorAll('.toolkit-filter-pad-slot')).forEach(function(slot) {
            if (slot && slot.parentNode) {
                slot.parentNode.removeChild(slot);
            }
        });

        const slots = Array.from(grid.querySelectorAll('.inventory-slot'));
        if (!slots.length) return false;

        const runtimeItems = (window.inventoryItems && window.inventoryItems.length > 0)
            ? window.inventoryItems
            : ((typeof inventoryItems !== 'undefined' && Array.isArray(inventoryItems)) ? inventoryItems : []);
        const activeFilter = window.currentInvFilter || 'all';
        const allowedTypes = INV_FILTERS[activeFilter] || [];
        const emptySlots = [];
        let visibleItemCount = 0;
        const minVisibleSlots = 15;

        slots.forEach(function(slot) {
            if (slot.classList && slot.classList.contains('empty-slot')) {
                emptySlots.push(slot);
                return;
            }
            const resolvedType = getInventorySlotResolvedType(slot, runtimeItems);
            const resolvedItem = runtimeItems.find(item => String(item.id || item['0']) === String(slot.dataset.itemId)) || { type: resolvedType };
            const visible = activeFilter === 'all'
                ? true
                : matchInventoryFilterType(resolvedItem, allowedTypes);
            slot.style.display = visible ? '' : 'none';
            if (visible) visibleItemCount++;
        });

        let shownSlotCount = visibleItemCount;
        const emptySlotsToShow = Math.max(minVisibleSlots - visibleItemCount, 0);
        emptySlots.forEach(function(slot, index) {
            const visible = index < emptySlotsToShow;
            slot.style.display = visible ? '' : 'none';
            if (visible) shownSlotCount++;
        });

        const padSlotsNeeded = Math.max(minVisibleSlots - shownSlotCount, 0);
        for (let i = 0; i < padSlotsNeeded; i++) {
            const emptySlot = document.createElement('div');
            emptySlot.className = 'inventory-slot empty-slot toolkit-filter-pad-slot';
            grid.appendChild(emptySlot);
        }

        return true;
    };

    window.getTheaterAPI = function() {
        if (theaterAPI) return theaterAPI;

        if (window.TheaterAPI) {
            theaterAPI = window.TheaterAPI;
        } else if (window.api) {
            theaterAPI = window.api;
        } else if (window.parent && window.parent.TheaterAPI) {
            theaterAPI = window.parent.TheaterAPI;
        } else if (window.parent && window.parent.api) {
            theaterAPI = window.parent.api;
        }

        if (theaterAPI && !theaterAPI.getCurrentState) {
            theaterAPI.getCurrentState = function() {
                if (typeof currentState !== 'undefined' && currentState !== null) {
                    return currentState;
                }
                if (window.parent && typeof window.parent.currentState !== 'undefined') {
                    return window.parent.currentState;
                }
                if (window.top && typeof window.top.currentState !== 'undefined') {
                    return window.top.currentState;
                }
                return null;
            };
            console.log('【物品分类】已为 TheaterAPI 添加 getCurrentState 方法');
        }

        return theaterAPI;
    };

    window.syncStateFromTables = function(stateToSync = (typeof currentState !== 'undefined' ? currentState : null), targetObject = null) {
        if (__toolkitNativeSyncStateFromTables) {
            __toolkitNativeSyncStateFromTables(stateToSync, targetObject);
            const normalizedItems = syncLegacyInventoryArray(getInventoryCacheSnapshot(targetObject));

            if (targetObject) {
                targetObject.inventoryItems = normalizedItems.slice();
                return targetObject;
            }

            if (window.isInventorySorted && normalizedItems.length > 0) {
                window.sortInventory(true);
                return normalizedItems;
            }

            if (typeof window.renderInventory === 'function') {
                window.renderInventory(normalizedItems);
            } else if (typeof renderInventory === 'function') {
                renderInventory(normalizedItems);
            }
            setTimeout(function() {
                try {
                    if (typeof window.applyInventoryFilterToGrid === 'function') {
                        window.applyInventoryFilterToGrid();
                    }
                } catch(e) {}
            }, 0);
            return normalizedItems;
        }

        let rawTable1 = null;

        if (stateToSync && stateToSync['1']) {
            rawTable1 = stateToSync['1'];
            console.log("【物品分类】使用 stateToSync['1'] 实时数据源");
        }
        else if (typeof currentState !== 'undefined' && currentState && currentState['1']) {
            rawTable1 = currentState['1'];
            console.log("【物品分类】使用 currentState['1'] 实时数据源");
        }
        else if (window.parent && window.parent.currentState && window.parent.currentState['1']) {
            rawTable1 = window.parent.currentState['1'];
            console.log("【物品分类】使用 window.parent.currentState['1'] 数据源");
        }
        else {
            const api = window.getTheaterAPI();
            if (api) {
                try {
                    if (api.getCurrentState) {
                        const state = api.getCurrentState();
                        if (state && state['1']) {
                            rawTable1 = state['1'];
                            console.log("【物品分类】使用 api.getCurrentState()['1'] 数据源");
                        }
                    }

                    if (!rawTable1) {
                        let invData = api.getInventory ? api.getInventory() : null;

                        if (!invData || (Array.isArray(invData) && invData.length === 0)) {
                            const playerData = api.getPlayerData ? api.getPlayerData() : null;
                            if (playerData) {
                                invData = playerData.inventory ||
                                          playerData.items ||
                                          (playerData.detailedAttributes && playerData.detailedAttributes.inventory) ||
                                          [];
                            }
                        }

                        if (invData && (Array.isArray(invData) ? invData.length > 0 : Object.keys(invData).length > 0)) {
                            window.inventoryItems = normalizeInventoryList(invData);
                            syncLegacyInventoryArray(window.inventoryItems);
                            console.log("【物品分类】从 TheaterAPI 读取物品:", window.inventoryItems.length, "件");

                            if (window.isInventorySorted && window.inventoryItems.length > 0) {
                                console.log("【物品分类】检测到已整理标志，自动重新排序...");
                                window.sortInventory(true);
                                return;
                            }

                            if (typeof renderInventory === 'function') {
                                renderInventory(window.inventoryItems);
                            }
                            return;
                        }
                    }
                } catch(e) {
                    console.warn("【物品分类】TheaterAPI 读取失败:", e);
                }
            }

            if (!rawTable1) {
                for (let key in window) {
                    try {
                        if (window[key] && typeof window[key] === 'object' &&
                            (window[key]['I138'] || window[key]['I140'])) {
                            rawTable1 = window[key];
                            console.log("【物品分类】使用 window['" + key + "'] 数据源（遍历查找）");
                            break;
                        }
                    } catch(e) {}
                }
            }
        }

        if (!rawTable1) {
            if (typeof warnToolboxInventoryTablePending === 'function') {
                warnToolboxInventoryTablePending();
            } else {
                console.warn("【物品分类】启动期暂未找到物品表数据，已跳过本次同步并等待后续重试。");
            }
            return;
        }

        let rawItems2 = normalizeInventoryList(rawTable1);
        window.inventoryItems = rawItems2;
        syncLegacyInventoryArray(window.inventoryItems);
        console.log("【物品分类】从 currentState 读取物品:", window.inventoryItems.length, "件");

        if (window.isInventorySorted && window.inventoryItems.length > 0) {
            console.log("【物品分类】检测到已整理标志，自动重新排序...");
            window.sortInventory(true);
            return;
        }

        if (typeof window.renderInventory === 'function') {
            window.renderInventory(window.inventoryItems);
        } else if (typeof renderInventory === 'function') {
            renderInventory(window.inventoryItems);
        }
        setTimeout(function() {
            try {
                if (typeof window.applyInventoryFilterToGrid === 'function') {
                    window.applyInventoryFilterToGrid();
                }
            } catch(e) {}
        }, 0);
    };

    window.showInventoryMessage = function(msg, type) {
        if (typeof showDanmaku === 'function') {
            showDanmaku(msg, type);
            return;
        }
        const api = window.getTheaterAPI ? window.getTheaterAPI() : null;
        if (api && api.showToast) {
            api.showToast(msg, type);
            return;
        }
        console.log('【物品分类】' + msg);
    };

    window.sortInventory = function(silent = false) {
        if (!silent) {
            const titleEl = document.getElementById('inventory-title-text');
            if (titleEl) {
                titleEl.classList.add('active');
                setTimeout(() => titleEl.classList.remove('active'), 200);
            }
        }

        if (!window.inventoryItems || window.inventoryItems.length === 0) {
            if (!silent && typeof window.syncStateFromTables === 'function') {
                window.syncStateFromTables();
            }
            if (!window.inventoryItems || window.inventoryItems.length === 0) {
                if (!silent) window.showInventoryMessage('暂无可分类物品', 'info');
                return;
            }
        }

        const typeOrder = {
            '重要物品': 1, '珍宝': 2, '任务物品': 3,
            '武器': 10, '护甲': 11, '法宝': 12,
            '功法': 20, '神通': 21, '秘籍': 22, '玉简': 23, '法术书': 24, '心法': 25,
            '丹药': 30, '符箓': 31, '消耗品': 32,
            '材料': 40, '妖丹': 41, '矿石': 42, '灵药': 43, '种子': 44,
            '其他物品': 90, '杂物': 91
        };

        window.inventoryItems.sort((a, b) => {
            const typeA = typeOrder[a.type] || 99;
            const typeB = typeOrder[b.type] || 99;
            if (typeA !== typeB) return typeA - typeB;
            return (a.name || '').localeCompare(b.name || '', 'zh-CN');
        });

        window.isInventorySorted = true;
        syncLegacyInventoryArray(window.inventoryItems);

        if (typeof currentState !== 'undefined' && currentState) {
            currentState['1'] = {};
            window.inventoryItems.forEach(item => {
                currentState['1'][item.id] = item;
            });
            if (typeof saveCurrentState === 'function') {
                saveCurrentState();
            }
        }

        if (typeof window.renderInventory === 'function') {
            window.renderInventory(window.inventoryItems);
        } else if (typeof renderInventory === 'function') {
            renderInventory(window.inventoryItems);
        }
        setTimeout(function() {
            try {
                if (typeof window.applyInventoryFilterToGrid === 'function') {
                    window.applyInventoryFilterToGrid();
                }
            } catch(e) {}
        }, 0);
        if (!silent) window.showInventoryMessage('✨ 储物袋已整理', 'success');
    };

    window.initInventoryUI = function() {
        const section = document.getElementById('inventory-section');
        if (!section) {
            console.warn("【物品分类】找不到 inventory-section 容器");
            return;
        }

        const oldHeader = section.querySelector('h3');
        if (oldHeader) oldHeader.remove();

        const headerHTML = '<div id="inventory-header-container">' +
            '<div id="inventory-header-row">' +
                '<span id="inventory-title-text" title="点击整理储物袋">整理储物袋</span>' +
            '</div>' +
            '<div id="inv-tabs-normal" class="inventory-tabs-row">' +
                '<button class="inv-tab-btn active" data-filter="all">全部</button>' +
                '<button class="inv-tab-btn" data-filter="equip">装备</button>' +
                '<button class="inv-tab-btn" data-filter="consumable">消耗</button>' +
                '<button class="inv-tab-btn" data-filter="book">功法</button>' +
                '<button class="inv-tab-btn" data-filter="material">材料</button>' +
                '<button class="inv-tab-btn" data-filter="rare">珍宝</button>' +
                '<button class="inv-tab-btn" data-filter="misc">其他</button>' +
            '</div>' +
        '</div>' +
        '<div class="inventory-grid-container" id="inventory-grid"></div>';

        section.innerHTML = headerHTML;

        section.querySelectorAll('.inv-tab-btn').forEach(btn => {
            btn.addEventListener('click', function(ev) {
                ev.preventDefault();
                ev.stopPropagation();
                const filterType = this.getAttribute('data-filter') || 'all';
                window.switchInvFilter(filterType);
            });
        });

        const titleEl = document.getElementById('inventory-title-text');
        if (titleEl) {
            let clickTimer = null;
            let preventClick = false;

            titleEl.addEventListener('click', () => {
                if (preventClick) {
                    return;
                }

                if (clickTimer) {
                    clearTimeout(clickTimer);
                }

                clickTimer = setTimeout(() => {
                    console.log('【物品分类】点击标题整理物品');

                    titleEl.classList.add('active');
                    setTimeout(() => titleEl.classList.remove('active'), 200);

                    if (typeof window.syncStateFromTables === 'function') {
                        window.syncStateFromTables();
                    }

                    if (window.inventoryItems && window.inventoryItems.length > 0) {
                        window.sortInventory();
                    } else {
                        window.showInventoryMessage('暂无可分类物品', 'info');
                    }

                    clickTimer = null;
                }, 250);
            });

            titleEl.addEventListener('dblclick', () => {
                if (clickTimer) {
                    clearTimeout(clickTimer);
                    clickTimer = null;
                }
                preventClick = true;
                setTimeout(() => { preventClick = false; }, 300);

                console.log('【物品分类】双击标题，刷新数据');
                if (typeof window.syncStateFromTables === 'function') {
                    window.syncStateFromTables();
                }
                window.showInventoryMessage('📜 储物袋视图已刷新', 'success');
            });
        }

        console.log("【物品分类】UI 初始化完成");
        setTimeout(() => {
            if (typeof window.syncStateFromTables === 'function') {
                window.syncStateFromTables();
            }
        }, 50);
    };

    window.switchInvFilter = function(type) {
        window.currentInvFilter = type || 'all';
        document.querySelectorAll('.inv-tab-btn').forEach(btn => {
            const btnFilter = btn.getAttribute('data-filter') || 'all';
            btn.classList.toggle('active', btnFilter === window.currentInvFilter);
        });

        const domApplied = typeof window.applyInventoryFilterToGrid === 'function'
            ? window.applyInventoryFilterToGrid()
            : false;
        if (domApplied) {
            return;
        }

        const runtimeItems = (window.inventoryItems && window.inventoryItems.length > 0)
            ? window.inventoryItems
            : ((typeof inventoryItems !== 'undefined' && Array.isArray(inventoryItems)) ? inventoryItems : []);

        if (runtimeItems.length > 0) {
            if (typeof window.renderInventory === 'function') {
                window.renderInventory(runtimeItems);
            } else if (typeof renderInventory === 'function') {
                renderInventory(runtimeItems);
            }
        } else if (typeof window.syncStateFromTables === 'function') {
            window.syncStateFromTables();
        }
    }

    function getFilterName(type) {
        const map = { 'equip': '装备', 'consumable': '消耗', 'book': '功法', 'material': '材料', 'rare': '珍宝', 'misc': '其他' };
        return map[type] || '全部';
    }
