        function recursivelyParseJsonStrings(data) {
// 1. 基础类型直接返回，减少栈调用
if (typeof data !== 'string' && typeof data !== 'object') return data;
if (data === null) return null;

if (typeof data === 'string') {

const trimmed = data.trim();
const firstChar = trimmed.charAt(0);
const lastChar = trimmed.charAt(trimmed.length - 1);

if (!((firstChar === '{' && lastChar === '}') || (firstChar === '[' && lastChar === ']'))) {
return data;
}

try {
const parsedData = JSON.parse(trimmed);
return recursivelyParseJsonStrings(parsedData);
} catch (e) {

try {
if (trimmed.includes("'")) {
const fixedString = trimmed.replace(/'/g, '"');
const parsedData = JSON.parse(fixedString);
return recursivelyParseJsonStrings(parsedData);
}
} catch (e2) {
return data;
}
return data;
}
} else if (Array.isArray(data)) {

const len = data.length;
const newArr = new Array(len);
for (let i = 0; i < len; i++) {
newArr[i] = recursivelyParseJsonStrings(data[i]);
}
return newArr;
} else if (typeof data === 'object') {

const newObj = {};
for (const key in data) {
if (Object.prototype.hasOwnProperty.call(data, key)) {
newObj[key] = recursivelyParseJsonStrings(data[key]);
}
}
return newObj;
}
return data;
}

        async function dbGet(key) {
          const setting = await db.settings.get(key);
          return setting ? setting.value : null;
        }

        async function dbSet(key, value, options) {
          const result = await db.settings.put({ key, value });
          if (typeof frApiConfigDidSave === 'function') frApiConfigDidSave(key, value, options);
          return result;
        }

        // === Character Detail Navigator (prev/next + dropdown) ===

var __charNavState = (typeof window !== 'undefined' && window.__charNavState) || {
  type: null,
  entries: [],
  index: -1,
};
if (typeof window !== 'undefined') window.__charNavState = __charNavState;

var __charNavIgnoreSelectChange = false;
var __charNavLastPatchedRef = (typeof window !== 'undefined' && window.__charNavLastPatchedRef) || null;
var __charNavLastListRef = (typeof window !== 'undefined' && window.__charNavLastListRef) || null;
var __charNavSchedulerStarted = (typeof window !== 'undefined' && window.__charNavSchedulerStarted) || false;
if (typeof window !== 'undefined') window.__charNavSchedulerStarted = __charNavSchedulerStarted;
if (typeof window !== 'undefined') window.__charNavLastPatchedRef = __charNavLastPatchedRef;
if (typeof window !== 'undefined') window.__charNavLastListRef = __charNavLastListRef;

function getCharNavTabsContainer() {
  return document.querySelector('#surrounding-characters-overlay .char-modal-tabs');
}

function ensureCharNavControls() {
  const tabs = getCharNavTabsContainer();
  if (!tabs) return null;

  let controls = tabs.querySelector('.char-nav-controls');
  if (!controls) {
    controls = document.createElement('div');
    controls.className = 'char-nav-controls hidden';
    controls.innerHTML = `
      <button class="char-nav-btn char-nav-prev" title="上一个角色" aria-label="上一个角色">
        <i class="fas fa-chevron-left"></i>
      </button>
      <select class="char-nav-select" title="选择角色"></select>
      <button class="char-nav-btn char-nav-next" title="下一个角色" aria-label="下一个角色">
        <i class="fas fa-chevron-right"></i>
      </button>
    `;
    tabs.appendChild(controls);
  }

  if (!controls.dataset.bound) {
    const prevBtn = controls.querySelector('.char-nav-prev');
    const nextBtn = controls.querySelector('.char-nav-next');
    const selectEl = controls.querySelector('.char-nav-select');

    prevBtn.addEventListener('click', () => navigateCharByOffset(-1));
    nextBtn.addEventListener('click', () => navigateCharByOffset(1));

    selectEl.addEventListener('change', e => {
      if (__charNavIgnoreSelectChange) return;
      const idx = parseInt(e.target.value, 10);
      if (Number.isNaN(idx)) return;
      showCharByIndex(idx);
    });

    // 监听 tab 切换以更新显示状态
    const tabsButtons = document.querySelectorAll('#surrounding-characters-overlay .char-modal-tab');
    tabsButtons.forEach(tab => {
      if (tab.dataset.charNavBound) return;
      tab.dataset.charNavBound = 'true';
      tab.addEventListener('click', () => {
        setTimeout(updateCharNavVisibility, 0);
      });
    });

    controls.dataset.bound = 'true';
  }

  return controls;
}

function updateCharNavHeader(isFromWorldBook) {
  const headerEl = document.querySelector('#surrounding-characters-overlay .characters-modal-header h4');
  if (!headerEl) return;
  if (!headerEl.dataset.defaultTitle) {
    headerEl.dataset.defaultTitle = headerEl.textContent || '周围人物';
  }
  headerEl.textContent = isFromWorldBook ? '世界档案' : headerEl.dataset.defaultTitle;
}

function getSortedSurroundingCharacters() {
  if (typeof surroundingCharacters === 'undefined' || !Array.isArray(surroundingCharacters)) return [];
  return [...surroundingCharacters]
    .filter(c => c && c.id !== 'B1')
    .sort((a, b) => {
      if (a.isBonded && !b.isBonded) return -1;
      if (!a.isBonded && b.isBonded) return 1;
      return 0;
    });
}

function getSurroundingNavEntries() {
  const chars = getSortedSurroundingCharacters();
  return chars.map(char => ({
    id: char.id,
    name: char.name || char.id || '未知',
    char,
  }));
}

function getWorldBookNavEntries() {
  const archiveRef = typeof getCurrentArchiveRef === 'function'
    ? getCurrentArchiveRef()
    : (typeof window !== 'undefined' && typeof window.getCurrentArchiveRef === 'function' ? window.getCurrentArchiveRef() : null);
  let sourceEntries = archiveRef?.data?.state?.worldBookEntries;
  if (!Array.isArray(sourceEntries)) {
    // 回退到当前 UI 已加载的内存列表，避免在某些页面时序下按钮失效
    const memoryEntries = (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries))
      ? allBiographyEntries
      : (typeof window !== 'undefined' && Array.isArray(window.allBiographyEntries) ? window.allBiographyEntries : null);
    if (Array.isArray(memoryEntries)) {
      sourceEntries = memoryEntries;
      console.warn('[人物详情导航] 使用内存世界档案回退源(allBiographyEntries)');
    } else {
      console.error('[人物详情导航] 世界档案不可用: archive.data.state.worldBookEntries / allBiographyEntries');
      return [];
    }
  }

  const listContainer = document.getElementById('world-book-entries-list');
  const filterType = listContainer?.dataset?.currentCategory || 'all';

  const focusList =
    (typeof currentState !== 'undefined' && currentState?.state?.worldEvolutionFocusList) || [];

  const searchTerm = (typeof biographySearchTerm === 'string' ? biographySearchTerm.trim() : '').toLowerCase();

  let entries = sourceEntries.filter(entry => {
    let entryTitle = entry.title || entry.key;
    if ((!entryTitle || entryTitle === '未知姓名') && typeof entry.content === 'string') {
      try {
        const contentData = JSON.parse(entry.content);
        entryTitle = contentData.title || contentData['1']?.split('|')[0] || '';
      } catch (e) {}
    }

    const matchesSearch = !searchTerm || (entryTitle && entryTitle.toLowerCase().includes(searchTerm));

    let matchesType = false;
    if (filterType === 'all') {
      matchesType = true;
    } else if (filterType === '人物') {
      matchesType = entry.type === '人物' || !entry.type;
    } else {
      matchesType = entry.type === filterType;
    }

    const matchesFocus = !worldBookShowFocusOnly || focusList.includes(entry.key);

    return matchesSearch && matchesType && matchesFocus;
  });

  entries.sort((a, b) => {
    if (worldBookSortBy === 'name') {
      const valA = a.title || a.key || '';
      const valB = b.title || b.key || '';
      return worldBookSortOrder === 'asc'
        ? valA.localeCompare(valB, 'zh')
        : valB.localeCompare(valA, 'zh');
    }
    const indexA = sourceEntries.indexOf(a);
    const indexB = sourceEntries.indexOf(b);
    return worldBookSortOrder === 'desc' ? indexB - indexA : indexA - indexB;
  });

  entries = entries.filter(entry => entry.type === '人物' || !entry.type);

  return entries.map(entry => {
    let charObj = null;
    if (typeof createCharacterObjectFromWorldBookEntry === 'function') {
      try {
        charObj = createCharacterObjectFromWorldBookEntry(entry);
      } catch (e) {
        charObj = null;
      }
    }

    const name = charObj?.name || entry.title || entry.key || '未知';
    const id = charObj?.id || entry.key || entry.id || name;

    return {
      id,
      name,
      entry,
      char: charObj,
    };
  });
}

function updateCharNavForChar(char, isFromWorldBook) {
  const controls = ensureCharNavControls();
  if (!controls) return;

  updateCharNavHeader(!!isFromWorldBook);

  let entries = isFromWorldBook ? getWorldBookNavEntries() : getSurroundingNavEntries();
  let index = entries.findIndex(e => e.id === char?.id);
  if (index === -1 && char?.name) {
    index = entries.findIndex(e => e.name === char.name);
  }

  if (index === -1 && char) {
    entries = [{ id: char.id, name: char.name || char.id || '未知', char }, ...entries];
    index = 0;
  }

  __charNavState = {
    type: isFromWorldBook ? 'worldbook' : 'surrounding',
    entries,
    index,
  };
  if (typeof window !== 'undefined') window.__charNavState = __charNavState;

  updateCharNavSelect(controls, entries, index);
  updateCharNavButtons(controls, entries, index);
  updateCharNavVisibility();
}

function updateCharNavSelect(controls, entries, index) {
  const selectEl = controls.querySelector('.char-nav-select');
  if (!selectEl) return;

  __charNavIgnoreSelectChange = true;
  selectEl.innerHTML = '';

  if (!entries || entries.length === 0) {
    const option = document.createElement('option');
    option.textContent = '暂无角色';
    option.value = '';
    selectEl.appendChild(option);
    selectEl.disabled = true;
  } else {
    entries.forEach((entry, idx) => {
      const option = document.createElement('option');
      option.value = String(idx);
      option.textContent = entry.name || entry.id || `角色 ${idx + 1}`;
      selectEl.appendChild(option);
    });
    selectEl.disabled = false;
    if (index >= 0) selectEl.value = String(index);
  }

  __charNavIgnoreSelectChange = false;
}

function updateCharNavButtons(controls, entries, index) {
  const prevBtn = controls.querySelector('.char-nav-prev');
  const nextBtn = controls.querySelector('.char-nav-next');

  if (!prevBtn || !nextBtn) return;

  const hasEntries = entries && entries.length > 0;
  prevBtn.disabled = !hasEntries || index <= 0;
  nextBtn.disabled = !hasEntries || index < 0 || index >= entries.length - 1;
}

function updateCharNavVisibility() {
  const controls = ensureCharNavControls();
  if (!controls) return;

  const detailView = document.getElementById('character-detail-view');
  const listTab = document.querySelector('#surrounding-characters-overlay .char-modal-tab[data-tab="list"]');

  const shouldShow =
    detailView && !detailView.classList.contains('hidden') && listTab && listTab.classList.contains('active');

  controls.classList.toggle('hidden', !shouldShow);
}

function showCharByIndex(idx) {
  if (!__charNavState || !Array.isArray(__charNavState.entries)) return;

  const entry = __charNavState.entries[idx];
  if (!entry) return;

  if (__charNavState.type === 'worldbook') {
    const charObj = entry.char ||
      (typeof createCharacterObjectFromWorldBookEntry === 'function' && entry.entry
        ? createCharacterObjectFromWorldBookEntry(entry.entry)
        : null);

    if (!charObj) {
      if (typeof showCustomAlert === 'function') {
        showCustomAlert('无法解析该人物档案数据。');
      }
      return;
    }

    if (typeof showCharacterDetailPanel === 'function') {
      showCharacterDetailPanel(charObj, null, true);
    }
  } else {
    let charObj = entry.char;
    if (!charObj && typeof characterDatabase === 'object' && characterDatabase) {
      charObj = characterDatabase[entry.id];
    }
    if (!charObj && Array.isArray(surroundingCharacters)) {
      charObj = surroundingCharacters.find(c => c.id === entry.id);
    }

    if (!charObj) {
      if (typeof showCustomAlert === 'function') {
        showCustomAlert('该人物已不存在或无法读取。');
      }
      return;
    }

    if (typeof showCharacterDetailPanel === 'function') {
      showCharacterDetailPanel(charObj);
    }
  }
}

function navigateCharByOffset(offset) {
  if (!__charNavState || !Array.isArray(__charNavState.entries)) return;
  const nextIndex = __charNavState.index + offset;
  if (nextIndex < 0 || nextIndex >= __charNavState.entries.length) return;
  showCharByIndex(nextIndex);
}

function hookCharNavFunctions() {
  let hooked = false;

  if (typeof showCharacterDetailPanel === 'function') {
    if (!showCharacterDetailPanel.__charNavPatched) {
      const originalShow = showCharacterDetailPanel;
      const patchedShow = function (char, listItemElement, isFromWorldBook) {
        const result = originalShow.apply(this, arguments);
        try {
          updateCharNavForChar(char, !!isFromWorldBook);
        } catch (e) {
          console.warn('[人物导航] 更新失败:', e);
        }
        return result;
      };

      for (const key in originalShow) {
        patchedShow[key] = originalShow[key];
      }
      patchedShow.__charNavPatched = true;
      patchedShow.__charNavOriginal = originalShow;
      showCharacterDetailPanel = patchedShow;
      __charNavLastPatchedRef = patchedShow;
      if (typeof window !== 'undefined') window.__charNavLastPatchedRef = __charNavLastPatchedRef;
      hooked = true;
    } else {
      __charNavLastPatchedRef = showCharacterDetailPanel;
      if (typeof window !== 'undefined') window.__charNavLastPatchedRef = __charNavLastPatchedRef;
    }
  }

  if (typeof showCharacterListView === 'function') {
    if (!showCharacterListView.__charNavPatched) {
      const originalListView = showCharacterListView;
      const patchedListView = function () {
        const result = originalListView.apply(this, arguments);
        updateCharNavHeader(false);
        updateCharNavVisibility();
        return result;
      };

      for (const key in originalListView) {
        patchedListView[key] = originalListView[key];
      }
      patchedListView.__charNavPatched = true;
      patchedListView.__charNavOriginal = originalListView;
      showCharacterListView = patchedListView;
      __charNavLastListRef = patchedListView;
      if (typeof window !== 'undefined') window.__charNavLastListRef = __charNavLastListRef;
      hooked = true;
    } else {
      __charNavLastListRef = showCharacterListView;
      if (typeof window !== 'undefined') window.__charNavLastListRef = __charNavLastListRef;
    }
  }

  return hooked;
}

function initCharacterDetailNavigator() {
  ensureCharNavControls();
  hookCharNavFunctions();
  updateCharNavVisibility();
  return typeof showCharacterDetailPanel === 'function' && showCharacterDetailPanel.__charNavPatched;
}

function scheduleCharacterDetailNavigator() {
  if (__charNavSchedulerStarted) return;
  __charNavSchedulerStarted = true;
  if (typeof window !== 'undefined') window.__charNavSchedulerStarted = true;

  const checkAndHook = () => {
    const detailChanged =
      typeof showCharacterDetailPanel === 'function' &&
      showCharacterDetailPanel !== __charNavLastPatchedRef &&
      !showCharacterDetailPanel.__charNavPatched;
    const listChanged =
      typeof showCharacterListView === 'function' &&
      showCharacterListView !== __charNavLastListRef &&
      !showCharacterListView.__charNavPatched;

    if (detailChanged || listChanged) {
      hookCharNavFunctions();
    }

    ensureCharNavControls();
    updateCharNavVisibility();
  };

  checkAndHook();
  setInterval(checkAndHook, 2000);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', scheduleCharacterDetailNavigator, { once: true });
} else {
  scheduleCharacterDetailNavigator();
}

// === Body Part Status Formatter (身体部位状态格式化显示) ===

function _escapeHtml(str) {
  if (!str && str !== 0) return '';
  var div = document.createElement('div');
  div.textContent = String(str);
  return div.innerHTML;
}

/**
 * 将人物状态文本换行显示
 * 每个状态以 ) 结尾，状态之间用空格分隔，替换为 <br> 换行
 * @param {string} rawStatus - 原始状态文本
 * @returns {string} 带换行的状态文本
 */
function formatStatusWithBreaks(rawStatus) {
  if (!rawStatus || rawStatus.includes('一切正常') || rawStatus.trim() === '无') return _escapeHtml(rawStatus);
  return _escapeHtml(rawStatus).replace(/\)\s+/g, ')<br>');
}

// === AI 肖像生成系统 (Portrait Generation) ===

var PORTRAIT_GEN_CONFIG_KEY = 'CULTIVATION_PORTRAIT_GEN_CONFIG_V1';
var SCENE_AVATAR_STRIP_CONFIG_KEY = 'CULTIVATION_SCENE_AVATAR_STRIP_CONFIG_V1';
var SCENE_AVATAR_STRIP_DEFAULT_CONFIG = { enabled: false };
var COMMERCIAL_AUTO_PORTRAIT_CONFIG_KEY = 'CULTIVATION_COMMERCIAL_AUTO_PORTRAIT_CONFIG_V1';
var COMMERCIAL_AUTO_PORTRAIT_DEFAULT_CONFIG = { enabled: false };
var _sceneAvatarStripConfigCache = null;
var _sceneAvatarStripRenderSeq = 0;
var _sceneAvatarStripInitialized = false;
var _commercialAutoPortraitConfigCache = null;
var _commercialAutoPortraitTasks = {};
var _commercialAutoPortraitLastAttemptLayerByChar = {};
var _commercialAutoPortraitLastAttemptTsByChar = {};
var _commercialAutoPortraitAttemptTtlMs = 15000;
var _commercialAutoPortraitSweepSeq = 0;
var _commercialAutoPortraitSweepTimer = null;
var _commercialAutoPortraitDebugDefaultEnabled = true;
var _commercialAutoPortraitPromptCache = {};
var _commercialAutoPortraitPromptLog = [];
var _commercialAutoPortraitPromptLogMax = 60;
var _portraitCropRuntime = {
  char: null,
  imageDataUrl: '',
  baseScale: 1,
  zoom: 1,
  offsetX: 0,
  offsetY: 0,
  dragging: false,
  pointerId: null,
  dragStartX: 0,
  dragStartY: 0
};

function _commercialAutoPortraitIsDebugEnabled() {
  try {
    if (typeof window !== 'undefined' && typeof window.__COMMERCIAL_AUTO_PORTRAIT_DEBUG__ === 'boolean') {
      return !!window.__COMMERCIAL_AUTO_PORTRAIT_DEBUG__;
    }
  } catch (e) {}
  return !!_commercialAutoPortraitDebugDefaultEnabled;
}

function _commercialAutoPortraitDebugLog(eventName, payload) {
  if (!_commercialAutoPortraitIsDebugEnabled()) return;
  try {
    if (typeof payload === 'undefined') {
      console.log('[commercial-auto-portrait]', eventName);
    } else {
      console.log('[commercial-auto-portrait]', eventName, payload);
    }
  } catch (e) {}
}

function _portraitConsoleLogFull(tag, text) {
  try {
    var body = String(text || '');
    console.log('[portrait-commercial]', tag + '\n' + body);
  } catch (e) {}
}

function _commercialAutoPortraitResetAttemptCache(reason) {
  var count = 0;
  try {
    count = Object.keys(_commercialAutoPortraitLastAttemptLayerByChar || {}).length;
  } catch (e) {}
  _commercialAutoPortraitLastAttemptLayerByChar = {};
  _commercialAutoPortraitLastAttemptTsByChar = {};
  _commercialAutoPortraitDebugLog('attemptCache:reset', {
    reason: String(reason || ''),
    count: count
  });
  return count;
}

function _commercialAutoPortraitFormatTime(ts) {
  var date = ts ? new Date(ts) : new Date();
  var pad = function(num) { return num < 10 ? '0' + num : String(num); };
  return (
    date.getFullYear() + '-' +
    pad(date.getMonth() + 1) + '-' +
    pad(date.getDate()) + ' ' +
    pad(date.getHours()) + ':' +
    pad(date.getMinutes()) + ':' +
    pad(date.getSeconds())
  );
}

function _commercialAutoPortraitGetPromptEntries() {
  if (Array.isArray(_commercialAutoPortraitPromptLog) && _commercialAutoPortraitPromptLog.length > 0) {
    return _commercialAutoPortraitPromptLog.slice();
  }
  var entries = [];
  try {
    var keys = Object.keys(_commercialAutoPortraitPromptCache || {});
    for (var i = 0; i < keys.length; i++) {
      if (_commercialAutoPortraitPromptCache[keys[i]]) entries.push(_commercialAutoPortraitPromptCache[keys[i]]);
    }
  } catch (e) {}
  return entries;
}

function _commercialAutoPortraitRecordPrompt(entry) {
  if (!entry || !entry.charId) return;
  var record = {
    charId: String(entry.charId || ''),
    charName: String(entry.charName || entry.charId || ''),
    llmPrompt: String(entry.llmPrompt || ''),
    finalPrompt: String(entry.finalPrompt || ''),
    updatedAt: entry.updatedAt || Date.now()
  };
  _commercialAutoPortraitPromptCache[record.charId] = record;
  if (!Array.isArray(_commercialAutoPortraitPromptLog)) _commercialAutoPortraitPromptLog = [];
  for (var i = 0; i < _commercialAutoPortraitPromptLog.length; i++) {
    if (_commercialAutoPortraitPromptLog[i] && _commercialAutoPortraitPromptLog[i].charId === record.charId) {
      _commercialAutoPortraitPromptLog.splice(i, 1);
      break;
    }
  }
  _commercialAutoPortraitPromptLog.unshift(record);
  if (_commercialAutoPortraitPromptLog.length > _commercialAutoPortraitPromptLogMax) {
    _commercialAutoPortraitPromptLog.length = _commercialAutoPortraitPromptLogMax;
  }
  _commercialAutoPortraitRenderPromptOverlay();
}

function _commercialAutoPortraitRenderPromptOverlay() {
  var overlay = document.getElementById('commercial-auto-prompt-overlay');
  if (!overlay) return;
  var list = overlay.querySelector('#commercial-auto-prompt-list');
  if (!list) return;
  list.innerHTML = '';

  var entries = _commercialAutoPortraitGetPromptEntries();
  if (!entries || entries.length === 0) {
    var empty = document.createElement('div');
    empty.className = 'auto-prompt-empty';
    empty.textContent = '暂无记录';
    list.appendChild(empty);
    return;
  }

  for (var i = 0; i < entries.length; i++) {
    var entry = entries[i];
    if (!entry) continue;

    var item = document.createElement('div');
    item.className = 'auto-prompt-item';
    item.setAttribute('data-char-id', entry.charId || '');

    var header = document.createElement('div');
    header.className = 'auto-prompt-header';

    var nameEl = document.createElement('div');
    nameEl.className = 'auto-prompt-name';
    nameEl.textContent = entry.charName || entry.charId || '未知角色';

    var metaEl = document.createElement('div');
    metaEl.className = 'auto-prompt-meta';
    metaEl.textContent = _commercialAutoPortraitFormatTime(entry.updatedAt);

    header.appendChild(nameEl);
    header.appendChild(metaEl);

    var llmBlock = document.createElement('div');
    llmBlock.className = 'auto-prompt-block';
    var llmLabel = document.createElement('div');
    llmLabel.className = 'auto-prompt-label';
    llmLabel.textContent = 'LLM 提示词';
    var llmText = document.createElement('pre');
    llmText.className = 'auto-prompt-text';
    llmText.textContent = entry.llmPrompt || '';
    llmBlock.appendChild(llmLabel);
    llmBlock.appendChild(llmText);

    var finalBlock = document.createElement('div');
    finalBlock.className = 'auto-prompt-block';
    var finalLabel = document.createElement('div');
    finalLabel.className = 'auto-prompt-label';
    finalLabel.textContent = '完整生图提示词';
    var finalText = document.createElement('pre');
    finalText.className = 'auto-prompt-text';
    finalText.textContent = entry.finalPrompt || '';
    finalBlock.appendChild(finalLabel);
    finalBlock.appendChild(finalText);

    item.appendChild(header);
    item.appendChild(llmBlock);
    item.appendChild(finalBlock);
    list.appendChild(item);
  }
}

function _commercialAutoPortraitOpenPromptOverlay() {
  var overlay = document.getElementById('commercial-auto-prompt-overlay');
  if (!overlay) return;
  _commercialAutoPortraitRenderPromptOverlay();
  overlay.classList.add('visible');
}

function _commercialAutoPortraitClosePromptOverlay() {
  var overlay = document.getElementById('commercial-auto-prompt-overlay');
  if (!overlay) return;
  overlay.classList.remove('visible');
}

function _commercialAutoPortraitBindPromptOverlay() {
  var overlay = document.getElementById('commercial-auto-prompt-overlay');
  if (!overlay || overlay._commercialPromptBound) return;
  overlay._commercialPromptBound = true;

  var closeBtn = overlay.querySelector('.auto-prompt-close-btn');
  if (closeBtn) {
    closeBtn.addEventListener('click', function() {
      _commercialAutoPortraitClosePromptOverlay();
    });
  }
  overlay.addEventListener('click', function(e) {
    if (e && e.target === overlay) {
      _commercialAutoPortraitClosePromptOverlay();
    }
  });
}

