function _portraitNormalizeProvider(provider) {
  var key = String(provider || '').trim().toLowerCase();
  if (key === 'openai' || key === 'gemini' || key === 'grok' || key === 'doubao' || key === 'custom_openai') {
    return key;
  }
  return 'doubao';
}

function _portraitShouldEnforceAdultPrompt(config) {
  if (!config) return true;
  return config.enforceAdultPrompt !== false;
}

function _portraitGetProviderLabel(provider) {
  var normalized = _portraitNormalizeProvider(provider);
  for (var i = 0; i < PORTRAIT_PROVIDER_OPTIONS.length; i++) {
    if (PORTRAIT_PROVIDER_OPTIONS[i].value === normalized) return PORTRAIT_PROVIDER_OPTIONS[i].label;
  }
  return '商用模型生图';
}

function _portraitSyncLegacyConfigFields(config) {
  if (!config || !config.providers || !config.providers.doubao) return;
  var doubaoCfg = config.providers.doubao;
  config.apiKey = doubaoCfg.apiKey || '';
  config.apiUrl = doubaoCfg.apiUrl || PORTRAIT_PROVIDER_DEFAULTS.doubao.apiUrl;
  config.apiModel = doubaoCfg.apiModel || PORTRAIT_PROVIDER_DEFAULTS.doubao.apiModel;
  config.resolution = doubaoCfg.resolution || PORTRAIT_PROVIDER_DEFAULTS.doubao.resolution;
  config.aspectRatio = doubaoCfg.aspectRatio || PORTRAIT_PROVIDER_DEFAULTS.doubao.aspectRatio;
  config.size = doubaoCfg.size || PORTRAIT_PROVIDER_DEFAULTS.doubao.size;
  config.responseFormat = doubaoCfg.responseFormat || PORTRAIT_PROVIDER_DEFAULTS.doubao.responseFormat;
}

function _portraitEnsureProviderConfigs(config) {
  if (!config) return;
  config.provider = _portraitNormalizeProvider(config.provider);
  if (!config.providers || typeof config.providers !== 'object') {
    config.providers = {};
  }

  var providerKeys = Object.keys(PORTRAIT_PROVIDER_DEFAULTS);
  for (var i = 0; i < providerKeys.length; i++) {
    var provider = providerKeys[i];
    var defaults = PORTRAIT_PROVIDER_DEFAULTS[provider];
    var current = config.providers[provider] || {};
    config.providers[provider] = Object.assign({}, defaults, current);
  }

  // 迁移旧版本仅豆包字段
  var legacyHasAny = !!(
    config.apiKey ||
    config.apiUrl ||
    config.apiModel ||
    config.resolution ||
    config.aspectRatio ||
    config.size ||
    config.responseFormat
  );
  if (legacyHasAny) {
    var doubaoCfg = config.providers.doubao || {};
    if (config.apiKey) doubaoCfg.apiKey = config.apiKey;
    if (config.apiUrl) doubaoCfg.apiUrl = config.apiUrl;
    if (config.apiModel) doubaoCfg.apiModel = config.apiModel;
    if (config.resolution) doubaoCfg.resolution = config.resolution;
    if (config.aspectRatio) doubaoCfg.aspectRatio = config.aspectRatio;
    if (config.size) doubaoCfg.size = config.size;
    if (config.responseFormat) doubaoCfg.responseFormat = config.responseFormat;
    config.providers.doubao = Object.assign({}, PORTRAIT_PROVIDER_DEFAULTS.doubao, doubaoCfg);
  }

  _portraitSyncLegacyConfigFields(config);
}

function _portraitGetProviderConfig(config, provider) {
  if (!config) return Object.assign({}, PORTRAIT_PROVIDER_DEFAULTS.doubao);
  _portraitEnsureProviderConfigs(config);
  var key = _portraitNormalizeProvider(provider || config.provider);
  if (!config.providers[key]) {
    config.providers[key] = Object.assign({}, PORTRAIT_PROVIDER_DEFAULTS[key] || PORTRAIT_PROVIDER_DEFAULTS.doubao);
  }
  return config.providers[key];
}

function _portraitNormalizeOpenAiModel(model) {
  var normalized = String(model || '').trim();
  if (!normalized) return PORTRAIT_PROVIDER_DEFAULTS.openai.apiModel;
  if (normalized === 'gpt-image-1.5-high-fidelity') return 'gpt-image-1.5';
  return normalized;
}

