        function parseRemarksString(str) {
          if (typeof str === 'object' && str !== null) {
            return { ...str };
          }
          if(typeof str==='string'&&str.trim().startsWith('{')){
            try{const parsed=JSON.parse(str);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))return {...parsed};}catch(_){}
          }
          // 备注外层用|分栏；装备/技能JSON内部的容器公式和描述也能含|，只能在JSON外分栏。
          const text = String(str || '');
          const parts = [];
          // 只有完整合法的JSON值才跳过内部|。普通备注以[或引号开头时仍按旧标量处理。
          const jsonEndAt = offset => {
            let depth = 0, quoted = false, escaped = false;
            for (let j = offset; j < text.length; j++) {
              const ch = text[j];
              if (quoted) {
                if (escaped) escaped = false;
                else if (ch === '\\') escaped = true;
                else if (ch === '"') quoted = false;
              } else if (ch === '"') quoted = true;
              else if (ch === '{' || ch === '[') depth++;
              else if (ch === '}' || ch === ']') depth--;
              if (depth === 0 && !quoted) {
                try { JSON.parse(text.slice(offset, j + 1)); } catch (_) { return -1; }
                let next = j + 1;
                while (next < text.length && /\s/.test(text[next])) next++;
                return next === text.length || text[next] === '|' ? j : -1;
              }
            }
            return -1;
          };
          let start = 0, hasColon = false;
          for (let i = 0; i < text.length; i++) {
            const ch = text[i];
            if (!hasColon && ch === ':') {
              hasColon = true;
              let valueAt = i + 1;
              while (valueAt < text.length && /\s/.test(text[valueAt])) valueAt++;
              if ('[{"'.includes(text[valueAt] || '\0')) {
                const end = jsonEndAt(valueAt);
                if (end >= valueAt) i = end;
              }
              continue;
            }
            if (ch === '|') {
              parts.push(text.slice(start, i));
              start = i + 1; hasColon = false;
            }
          }
          parts.push(text.slice(start));
          return parts.reduce((acc, part) => {
            const firstColonIndex = part.indexOf(':');
            if (firstColonIndex > -1) {
              const key = part.substring(0, firstColonIndex).trim();
              const value = part.substring(firstColonIndex + 1).trim();
              if (key) acc[key] = value;
            }
            return acc;
          }, {});
        }

        function serializeRemarksObject(remarksObj) {
          return Object.entries(remarksObj)
            .filter(([key, value]) => value !== undefined && value !== null)
            .map(([key, value]) => {
              if (typeof value === 'object' && value !== null) {
                value = JSON.stringify(value);
              }
              return `${key}:${value}`;
            })
            .join('|');
        }

        function serializeCharacterRemarks(char, forAI = false) {
          const remarks = {};

          // 1. 先把所有自定义的、存储在备注列的变量从角色对象中提取出来
          if (playerDisplaySettings && Array.isArray(playerDisplaySettings.customFields)) {
            playerDisplaySettings.customFields.forEach(field => {
              if (
                field.isEnabled &&
                field.column === 9 &&
                field.variableName &&
                char.hasOwnProperty(field.variableName)
              ) {
                remarks[field.variableName] = char[field.variableName];
              }
            });
          }

          // 2. 然后，再添加所有预设的标准属性，这会覆盖上面可能存在的同名属性，确保标准属性的权威性
          remarks['年龄'] = char.age;
          remarks['寿元'] = char.shouyuan;
          if (char.cultivationArts !== undefined) remarks.cultivationArts = char.cultivationArts;

          if (char.id === 'B1') {
            remarks['灵根'] = char.linggen;
            remarks['修为进度'] = `${char.progress || 0}%`;
            if (char.hp && char.hp.current !== undefined) {
              remarks['hp'] = `${char.hp.current}/${char.hp.max}`;
            }
            remarks['traits'] = JSON.stringify(char.playerTraits || []);
            remarks['avatar'] = char.avatarAppearance;
            if (!forAI) {
              remarks['equipment'] = JSON.stringify({
                weapon: char.weapon,
                armor: char.armor,
                technique: char.technique,
                treasure: char.treasure,
              });
              remarks['isExtreme'] = char.isExtreme;
              remarks['warehouse'] = JSON.stringify(char.warehouse || []);
              remarks['deathCount'] = char.deathCount;
            }
          } else {
            remarks['equipment'] = JSON.stringify({
              weapon: char.weapon,
              armor: char.armor,
              technique: char.technique,
              treasure: char.treasure,
            });
            remarks['inventory'] = JSON.stringify(char.inventoryItems || []);
            remarks['skills'] = JSON.stringify(char.skills || []);
            remarks['traits'] = JSON.stringify(char.npcTraits || []);
          }

          if (char.isBonded) {
            remarks['isBonded'] = 'true';
          }
          if (char.deeds) {
            remarks['deeds'] = char.deeds;
          }

          return serializeRemarksObject(remarks);
        }

// Retired character-only columns stay in legacy saves for recovery, never in active UI/model writes.
function frIsRetiredCharacterColumn(key) {
  return ['8','17','18','20','21','22','23','24','sexExperience','publicKink','privateKink','sensitiveParts','genitalStatus','eroticValue','pleasureValue','sexualConception','性经验','性经历','表性癖','里性癖','敏感点','敏感部位','生殖器状态','生殖器官状态','情欲值','快感值','性观念'].includes(String(key));
}
function frStatusWorldTime(state = typeof currentState === 'undefined' ? null : currentState) {
  return ceExtractOriginalTimelineTimeLocationInfoFromStateLike(state).timeText;
}

function frNormalizeStatusText(value, at = frStatusWorldTime()) {
  const status = typeof CE_CORE !== 'undefined' && CE_CORE['character-status'];
  return status && typeof value === 'string' ? status.normalizeCharacterStatus(value, at) : value;
}

function frProjectCharacterColumns(row, at = frStatusWorldTime()) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) return row;
  if (typeof frNumericProjectRedCompanion === 'function') row = frNumericProjectRedCompanion(row);
  const core = typeof CE_CORE !== 'undefined' && CE_CORE['character-profile'];
  const projected = core ? core.projectCharacterColumns(row) : Object.fromEntries(Object.entries(row).filter(([key]) => !frIsRetiredCharacterColumn(key)));
  if (typeof projected['4'] === 'string') projected['4'] = frNormalizeStatusText(projected['4'], at);
  return projected;
}
function frVariablePresentation() {
  return typeof CE_CORE === 'object' ? CE_CORE['character-profile'] : null;
}

function frCleanVariableCharacter(row) {
  const core = frVariablePresentation();
  if (!core || !row || row['0'] === 'SCENE_MAP') return row;
  const projected = core.cleanVariableCharacterColumns(row);
  const raw = projected['9'];
  if (typeof raw !== 'string' || raw.trimStart().startsWith('{')) return projected;
  const remarks = parseRemarksString(raw);
  const clean = core.cleanVariableRemarks(remarks);
  return clean === remarks ? projected : {...projected, '9':serializeRemarksObject(clean)};
}

function frCleanVariableCommand(op) {
  return frVariablePresentation()?.cleanVariableCommand(op, frCleanVariableCharacter) ?? op;
}

function frProjectPromptState(state) {
  if (!state || typeof state !== 'object' || !state['0']) return state;
  const at = frStatusWorldTime(state);
  const projection = {...state, '0':Object.fromEntries(Object.entries(state['0']).map(([id,row]) => [id,id==='SCENE_MAP'?row:frCleanVariableCharacter(frProjectCharacterColumns(row, at))]))};
  if (state['1'] && typeof window !== 'undefined' && window.FrItemPresentation) {
    projection['1'] = Object.fromEntries(Object.entries(state['1']).map(([id, item]) => [id, window.FrItemPresentation.projectMiracleBottle(item)]));
  }
  return projection;
}

        function getTableIndexFromId(id) {
          if (!id) return null;
          if (id === 'SCENE_MAP') return '10';
          const prefix = id.charAt(0);
          switch (prefix) {
            case 'B':
            case 'C':
            case 'G':
              return '0';
            case 'I':
              return '1';
            case 'E':
              return '9';
            case 'T':
              return '6';
            case 'S':
              return '8';
            case 'W':
              return '5';
            case 'P':
              return '7';
            default:
              return null;
          }
        }

        
// 羁绊标记由玩家设置。AI只可补缺省false，不能借年龄/库存等更新翻转已有选择。
function frReadBondedFlag(value) {
  if (value === true || value === 'true') return true;
  if (value === false || value === 'false') return false;
  return null;
}

function frReadBondedRemarks(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return { ...value };
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return { ...parsed };
    } catch (_) {}
  }
  return parseRemarksString(value || '');
}

function frProtectBondedRemarks(existingRemarks, incomingRemarks) {
  const next = frReadBondedRemarks(incomingRemarks);
  delete next['善恶值'];
  delete next.shanE;
  const stored = frReadBondedRemarks(existingRemarks);
  const previous = frReadBondedFlag(stored.isBonded);
  next.isBonded = previous === null ? false : previous;
  if (stored.canonActorId) next.canonActorId = stored.canonActorId;
  else delete next.canonActorId;
  return next;
}

function frFindBondedSourceRow(state, archive, id) {
  if (state && state['0'] && state['0'][id]) return state['0'][id];
  const entries = archive && archive.data && archive.data.state && archive.data.state.worldBookEntries;
  const entry = Array.isArray(entries) && entries.find(item => item && (item.key === id || item.id === id));
  if (entry) {
    try { return typeof entry.content === 'string' ? JSON.parse(entry.content) : entry.content; } catch (_) {}
  }
  return null;
}

