function renderTraitCards(grid, traits) {
  grid.classList.add('fr-trait-grid');
  if (!traits.length) {
    const empty = document.createElement('p');
    empty.className = 'fr-trait-list-empty';
    empty.textContent = '暂无气运特质。';
    grid.appendChild(empty);
    return;
  }
  for (const trait of traits) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'fr-trait-card';
    button.setAttribute('aria-haspopup', 'dialog');
    const rarity = trait.rarity || '普通';
    button.dataset.rarity = rarity;
    const emblem = document.createElement('span');
    emblem.className = 'fr-trait-emblem';
    emblem.setAttribute('aria-hidden', 'true');
    emblem.textContent = '✦';
    const text = document.createElement('span');
    text.className = 'fr-trait-card-text';
    const title = document.createElement('strong');
    title.textContent = trait.name || '未知特质';
    const badge = document.createElement('span');
    badge.className = 'fr-trait-rarity';
    badge.textContent = rarity;
    text.append(title, badge);
    const chevron = document.createElement('span');
    chevron.className = 'fr-trait-chevron';
    chevron.setAttribute('aria-hidden', 'true');
    chevron.textContent = '›';
    button.append(emblem, text, chevron);
    button.addEventListener('click', () => showTraitDetail(trait));
    grid.appendChild(button);
  }
}

        
function __toolkitEnsureStatusFloatingTooltip() {
    let popup = document.getElementById('toolkit-status-floating-tooltip');
    if (!popup) {
        popup = document.createElement('div');
        popup.id = 'toolkit-status-floating-tooltip';
        popup.setAttribute('tabindex', '-1');
        popup.setAttribute('role', 'dialog');
        popup.addEventListener('click', function(ev) {
            ev.stopPropagation();
        });
        popup.addEventListener('pointerdown', function(ev) {
            ev.stopPropagation();
        });
        document.body.appendChild(popup);
    }
    return popup;
}
window.__toolkitEnsureStatusFloatingTooltip = __toolkitEnsureStatusFloatingTooltip;

function __toolkitHideStatusFloatingTooltip() {
    const popup = document.getElementById('toolkit-status-floating-tooltip');
    if (popup) {
        popup.classList.remove('visible');
        popup.innerHTML = '';
        popup.style.removeProperty('visibility');
        popup.style.removeProperty('pointer-events');
        popup.style.setProperty('left', '-9999px', 'important');
        popup.style.setProperty('top', '-9999px', 'important');
        popup.__toolkitAnchorRect = null;
    }
    if (window.__toolkitStatusActivePill && window.__toolkitStatusActivePill.classList) {
        window.__toolkitStatusActivePill.classList.remove('show-tooltip');
    }
    window.__toolkitStatusActivePill = null;
}
window.__toolkitHideStatusFloatingTooltip = __toolkitHideStatusFloatingTooltip;

function __toolkitCaptureStatusPillRect(pill) {
    if (!pill || typeof pill.getBoundingClientRect !== 'function') return null;
    const rect = pill.getBoundingClientRect();
    const left = Number(rect.left) || 0;
    const top = Number(rect.top) || 0;
    const width = Number(rect.width) || Math.max(0, (Number(rect.right) || 0) - left);
    const height = Number(rect.height) || Math.max(0, (Number(rect.bottom) || 0) - top);
    const right = Number(rect.right) || (left + width);
    const bottom = Number(rect.bottom) || (top + height);
    const valid = width > 0 || height > 0 || right > left || bottom > top;
    return valid ? { left, top, right, bottom, width, height } : null;
}
window.__toolkitCaptureStatusPillRect = __toolkitCaptureStatusPillRect;

function __toolkitPositionStatusFloatingTooltip(pill, popup, anchorRect) {
    if (!popup) return false;
    const rect = anchorRect || __toolkitCaptureStatusPillRect(pill) || popup.__toolkitAnchorRect || null;
    if (!rect) return false;

    popup.__toolkitAnchorRect = rect;
    const popupRect = popup.getBoundingClientRect();
    const popupWidth = Math.max(1, Number(popupRect.width) || popup.offsetWidth || 0);
    const popupHeight = Math.max(1, Number(popupRect.height) || popup.offsetHeight || 0);
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
    const gap = 10;

    let left = rect.right + gap;
    if (left + popupWidth > viewportWidth - 12) {
        left = rect.left - popupWidth - gap;
    }

    if (left < 12) {
        left = rect.left + (rect.width / 2) - (popupWidth / 2);
        left = Math.max(12, Math.min(left, viewportWidth - popupWidth - 12));
    }

    let top = rect.top + (rect.height / 2) - (popupHeight / 2);
    if (top + popupHeight > viewportHeight - 12) {
        top = viewportHeight - popupHeight - 12;
    }
    if (top < 12) {
        top = 12;
    }

    popup.style.setProperty('left', Math.round(left) + 'px', 'important');
    popup.style.setProperty('top', Math.round(top) + 'px', 'important');
    return true;
}
window.__toolkitPositionStatusFloatingTooltip = __toolkitPositionStatusFloatingTooltip;

function __toolkitShowStatusFloatingTooltip(pill) {
    if (!pill) return;
    const detail = pill.querySelector('.status-tooltip');
    if (!detail) return;

    if (window.__toolkitStatusActivePill === pill) {
        __toolkitHideStatusFloatingTooltip();
        return;
    }

    const anchorRect = __toolkitCaptureStatusPillRect(pill);
    __toolkitHideStatusFloatingTooltip();
    const popup = __toolkitEnsureStatusFloatingTooltip();
    popup.innerHTML = detail.innerHTML;
    popup.setAttribute('aria-label', detail.querySelector('h5')?.textContent || '状态详情');
    popup.scrollTop = 0;
    popup.style.setProperty('left', '-9999px', 'important');
    popup.style.setProperty('top', '-9999px', 'important');
    popup.style.setProperty('visibility', 'hidden', 'important');
    popup.style.setProperty('pointer-events', 'none', 'important');
    popup.__toolkitAnchorRect = anchorRect || null;
    popup.classList.add('visible');
    pill.classList.add('show-tooltip');
    window.__toolkitStatusActivePill = pill;

    const finalize = function(fallbackRect) {
        if (!window.__toolkitStatusActivePill || window.__toolkitStatusActivePill !== pill) return;
        if (__toolkitPositionStatusFloatingTooltip(pill, popup, fallbackRect || anchorRect)) {
            popup.style.setProperty('visibility', 'visible', 'important');
            popup.style.setProperty('pointer-events', 'auto', 'important');
        }
    };

    finalize(anchorRect);
    requestAnimationFrame(function() {
        finalize(anchorRect);
        setTimeout(function() {
            finalize();
        }, 40);
    });
}
window.__toolkitShowStatusFloatingTooltip = __toolkitShowStatusFloatingTooltip;

function __toolkitBindStatusPillEvents(root) {
    const scope = root || document;
    const pills = scope.querySelectorAll('.status-pill[data-toolkit-status-pill]');
    pills.forEach(function(pill) {
        if (pill.dataset.toolkitBound === '1') return;
        pill.dataset.toolkitBound = '1';
        pill.addEventListener('click', function(ev) {
            ev.preventDefault();
            ev.stopPropagation();
            __toolkitShowStatusFloatingTooltip(pill);
        });
        pill.addEventListener('keydown', function(ev) {
            if (ev.key !== 'Enter' && ev.key !== ' ') return;
            ev.preventDefault();
            ev.stopPropagation();
            __toolkitShowStatusFloatingTooltip(pill);
        });
    });

    if (!window.__toolkitStatusGlobalClickBound) {
        document.addEventListener('click', function(ev) {
            const target = ev.target;
            if (target && target.closest && (target.closest('.status-pill') || target.closest('#toolkit-status-floating-tooltip'))) {
                return;
            }
            __toolkitHideStatusFloatingTooltip();
        }, true);

        window.addEventListener('resize', function() {
            if (!window.__toolkitStatusActivePill) return;
            const popup = document.getElementById('toolkit-status-floating-tooltip');
            if (popup && popup.classList.contains('visible')) {
                __toolkitPositionStatusFloatingTooltip(window.__toolkitStatusActivePill, popup);
            }
        });

        document.addEventListener('scroll', function() {
            if (!window.__toolkitStatusActivePill) return;
            const popup = document.getElementById('toolkit-status-floating-tooltip');
            if (popup && popup.classList.contains('visible')) {
                __toolkitPositionStatusFloatingTooltip(window.__toolkitStatusActivePill, popup);
            }
        }, true);

        document.addEventListener('keydown', function(ev) {
            if (ev.key === 'Escape') __toolkitHideStatusFloatingTooltip();
        }, true);

        window.__toolkitStatusGlobalClickBound = true;
    }
}
window.__toolkitBindStatusPillEvents = __toolkitBindStatusPillEvents;

function __toolkitApplyStatusVisualsCompat(root) {
    if (typeof window.__toolkitRenderStatusVisualsCompat !== 'function') {
        if (typeof renderStatusVisuals === 'function') {
            window.__toolkitRenderStatusVisualsCompat = function(rawStatusString, isPlayer) {
                return renderStatusVisuals(rawStatusString, !!isPlayer);
            };
        } else {
            return;
        }
    }
    const scope = root || document;
    if (window.__toolkitStatusActivePill && !document.body.contains(window.__toolkitStatusActivePill)) {
        __toolkitHideStatusFloatingTooltip();
    }

    const statusEl = document.getElementById('modal-player-status');
    if (statusEl && !statusEl.querySelector('.status-grid')) {
        const raw = (statusEl.textContent || statusEl.innerText || '').trim();
        if (raw) {
            const normalized = raw.indexOf('当前状态:') === 0 ? raw : ('当前状态: ' + raw);
            statusEl.innerHTML = '<i class="fas fa-info-circle"></i>' + window.__toolkitRenderStatusVisualsCompat(normalized, true);
            statusEl.style.display = 'flex';
        }
    }

    const wraps = scope.querySelectorAll('.char-detail-status-display');
    wraps.forEach(function(wrap) {
        if (wrap.querySelector('.status-grid')) return;
        const raw = (wrap.textContent || wrap.innerText || '').trim();
        if (!raw) return;
        const normalized = raw.indexOf('当前状态:') === 0 ? raw : ('当前状态: ' + raw);
        wrap.innerHTML = '<i class="fas fa-info-circle"></i>' + window.__toolkitRenderStatusVisualsCompat(normalized, false);
    });

    __toolkitBindStatusPillEvents(scope);
}
window.__toolkitApplyStatusVisualsCompat = __toolkitApplyStatusVisualsCompat;

if (!window.__toolkitStatusCompatRuntimeBound) {
    window.__toolkitStatusCompatRuntimeBound = true;
    setTimeout(function() {
        try { __toolkitApplyStatusVisualsCompat(document); } catch(e) {}
    }, 80);

    document.addEventListener('click', function() {
        setTimeout(function() {
            try { __toolkitApplyStatusVisualsCompat(document); } catch(e) {}
        }, 0);
    }, true);

    /* ★★ 2026-11-01 玩家：「怎么一卡一卡的了？」
     *              「就是能看到那个计时器和气泡的跑秒间歇性的在卡顿，之前没有。」
     *
     * 原来这里是：
     *     new MutationObserver(function() {
     *         __toolkitApplyStatusVisualsCompat(document);      // 每次都全文档扫描
     *     }).observe(document.body, { childList:true, subtree:true });
     *
     * 问题（实测数据）：
     *   · __toolkitApplyStatusVisualsCompat 每次要 querySelectorAll 全文档
     *   · 实测每次 DOM 变更白花 1.51ms
     *   · 而 .char-detail-status-display / .status-grid 命中数 **都是 0**
     *     —— 也就是说绝大多数时候它扫了一圈什么都没找到，纯空转
     *   · 正文流式输出时 DOM 每秒变更几十次 → 这些空转把主线程切碎
     *     → setInterval 的计时器和气泡跑秒被挤掉 → 玩家看到「一卡一卡」
     *
     * 改法（不减少功能，只去掉空转）：
     *   ① 用 MutationObserver 的回调参数 records 先做**廉价预筛**：
     *      只有当新增节点里真的出现 .char-detail-status-display / .status-grid
     *      或 #modal-player-status 时，才调那个重函数；
     *   ② 预筛只看 record.addedNodes，不碰 getComputedStyle、不查全文档；
     *   ③ 合并同一批变更（microtask 内只跑一次），避免连击。
     *
     * 为什么不是直接删掉观察器：状态栏在角色详情弹窗打开时才会动态生成，
     * 没有观察器就抓不到那个时机（玩家会看到状态没上色）。所以是**精准化**而非移除。
     */
    if (typeof MutationObserver !== 'undefined' && document.body) {
        var __toolkitStatusObserverPending = false;
        var __toolkitStatusObserver = new MutationObserver(function(records) {
            if (__toolkitStatusObserverPending) return;
            // 廉价预筛：只看新增节点本身，不做全文档查询
            var hit = false;
            for (var i = 0; i < records.length && !hit; i++) {
                var added = records[i].addedNodes;
                if (!added || !added.length) continue;
                for (var j = 0; j < added.length; j++) {
                    var n = added[j];
                    if (!n || n.nodeType !== 1) continue;
                    if (n.id === 'modal-player-status' ||
                        (n.classList && (n.classList.contains('char-detail-status-display') ||
                                         n.classList.contains('status-grid')))) {
                        hit = true;
                        break;
                    }
                    // 新增的是容器时，才做一次限定范围的查询（仍在廉价侧）
                    if (n.querySelector && (n.querySelector('.char-detail-status-display') ||
                                            n.querySelector('.status-grid'))) {
                        hit = true;
                        break;
                    }
                }
            }
            if (!hit) return;
            __toolkitStatusObserverPending = true;
            // 合批：同一轮 DOM 变更只跑一次
            Promise.resolve().then(function() {
                __toolkitStatusObserverPending = false;
                try { __toolkitApplyStatusVisualsCompat(document); } catch(e) {}
            });
        });
        __toolkitStatusObserver.observe(document.body, { childList: true, subtree: true });
    }
}


        
function __toolkitRenderStatusVisualsCompat(rawStatusString, isPlayer) {
    const gridClass = isPlayer ? 'status-grid' : 'status-grid npc-grid';
    const sizeClass = isPlayer ? 'player-style' : 'npc-style';

    const entries = CE_CORE['character-status'].characterStatusCards(
        String(rawStatusString || '').replace(/^当前状态[:：]\s*/u, ''), frStatusWorldTime()
    );
    if (!entries.length) entries.push({name:'一切正常'});
    const html = entries.map(function(entry) {
        const { name, icon, effectText, ending, activation, source, negative, pending } = entry;
        const e = _escapeHtml;
        const tone = pending ? 'pending' : negative ? 'negative' : 'positive';
        const details = [['效果',effectText],['生效',activation==='待激活'?'待生效':activation],
            ['结束',ending],['来源',source]].filter(([,value])=>value);
        const footer = details.map(([label,value]) => '<p><strong>' + label + '</strong>　' + e(value) + '</p>').join('') ||
            (name==='一切正常' ? '' : '<p>暂无更多状态详情</p>');
        return '<div class="status-pill fr-status-card ' + tone + ' ' + sizeClass + '"' +
            (footer ? ' data-toolkit-status-pill="1" role="button" aria-haspopup="dialog" tabindex="0"' : '') + '>' +
            '<div class="fr-status-heading">' + (icon ? '<span class="status-emoji">' + e(icon) + '</span>' : '') +
            '<span class="status-name">' + e(name) + '</span></div>' +
            (footer ? '<div class="status-tooltip"><h5>' + e(name) + '</h5>' + footer + '</div>' : '') + '</div>';
    }).join('');
    return '<div class="' + gridClass + ' fr-status-cards">' + html + '</div>';
}
window.__toolkitRenderStatusVisualsCompat = __toolkitRenderStatusVisualsCompat;


        function openCharacterDetail() {
          updateAvatar(currentPlayerData);

          const statusEl = document.getElementById('modal-player-status');
          const statusText =
            currentPlayerData.status && currentPlayerData.status !== '无' ? currentPlayerData.status : '一切正常';
          if (statusEl) {
            if (typeof window.__toolkitRenderStatusVisualsCompat === 'function') {
              statusEl.innerHTML = '<i class="fas fa-info-circle"></i>' + window.__toolkitRenderStatusVisualsCompat(`当前状态: ${statusText}`, true);
            } else if (typeof renderStatusVisuals === 'function') {
              statusEl.innerHTML = '<i class="fas fa-info-circle"></i>' + renderStatusVisuals(`当前状态: ${statusText}`, true);
            } else {
              statusEl.textContent = `当前状态: ${statusText}`;
            }
            statusEl.style.display = 'flex';
            if (window.__toolkitBindStatusPillEvents) window.__toolkitBindStatusPillEvents(document);
          }

          const progress = parseInt(currentPlayerData.progress) || 0;
          updateGourdProgress(progress);
          updateCharacterDetailView();
          characterDetailOverlay.classList.add('visible');
        }

        function updateCharacterDetailView() {
          renderDetailGrid('weapon-grid', 'weapon');
          renderDetailGrid('armor-grid', 'armor');
          renderDetailGrid('technique-grid', 'technique');
          renderDetailGrid('treasure-grid', 'treasure');
          renderDetailedAttributes(currentPlayerData);
          renderPlayerTraits(currentPlayerData);
          frRenderCultivationArts(document.getElementById('player-cultivation-arts'), currentPlayerData);

          const detailPane = document.querySelector('.detail-left-pane');
          let label = detailPane.querySelector('.extreme-label');
          if (currentPlayerData.isExtreme) {
            if (!label) {
              label = document.createElement('div');
              label.className = 'extreme-label';
              label.textContent = '极限';
              detailPane.appendChild(label);
            }
          } else {
            if (label) label.remove();
          }

          const deathCounter = document.getElementById('death-counter');
          if (currentPlayerData.isExtreme) {
            deathCounter.textContent = `死亡次数: ${currentPlayerData.deathCount}`;
            deathCounter.style.display = 'block';
          } else {
            deathCounter.style.display = 'none';
          }
        }

        function closeCharacterDetail() {
          characterDetailOverlay.classList.remove('visible');
        }

        function updateGourdProgress(percentage) {
    var fillElement = document.getElementById('gourd-fill-progress');
    var textElement = document.getElementById('gourd-progress-text');
    if (!fillElement || !textElement) { return; }
    fillElement.style.width = percentage + '%';
    fillElement.style.height = '100%';
    if (parseInt(percentage) >= 100) {
        fillElement.classList.add('full');
        textElement.textContent = '境界圆满';
        textElement.style.color = '#e0f7fa';
        textElement.style.textShadow = '0 0 8px #00e5ff, 0 0 15px #00bcd4';
        textElement.style.fontSize = '0.95em';
    } else {
        fillElement.classList.remove('full');
        textElement.textContent = '当前境界进度: ' + percentage + '%';
        textElement.style.color = '#fff';
        textElement.style.textShadow = '0 1px 2px rgba(0,0,0,0.8)';
        textElement.style.fontSize = '0.85em';
    }
}

        function renderDetailGrid(gridId, slotKey) {
          const gridContainer = document.getElementById(gridId);
          const slotTypeMap = { weapon: '武器', armor: '护甲', technique: '功法', treasure: '法宝' };
          const slotType = slotTypeMap[slotKey];
          FrEquipmentView.render(gridContainer,{slotKey,slots:FrEquipmentRuntime.slots(slotKey),items:currentPlayerData[slotKey]||[],lockedSlots:FrEquipmentRuntime.lockedSlots(currentState['0']?.B1,slotKey),onEmpty:index=>openEquipmentPicker(slotType,index),onItem:(item,index)=>showItemDetail(item,{isEquipped:true,slotType,slotIndex:index})});
          if(gridContainer.previousElementSibling?.tagName==='H4')gridContainer.previousElementSibling.classList.add('fr-equipment-old-heading');
        }

        function openEquipmentPicker(slotType, slotIndex) {
          const slotKey = {武器:'weapon',护甲:'armor',功法:'technique',法宝:'treasure'}[slotType];
          const ownerRow = currentState['0']?.B1;
          const locked = FrEquipmentRuntime.lockedSlots(ownerRow,slotKey)[slotIndex];
          if (locked) { showCustomAlert(locked); return; }
          currentPickingSlot = { type: slotType, index: slotIndex };
          pickerTitle.textContent = `选择${FrEquipmentRuntime.slots(slotKey)[slotIndex].label}`;
          pickerGrid.innerHTML = '';

          const equipmentSlots = ['weapon', 'armor', 'technique', 'treasure'];
          const equippedItemIds = new Set(
            equipmentSlots.flatMap(key => (currentPlayerData[key] || []).filter(item => item).map(item => item.id || item['0'])),
          );

          const selectableItems = inventoryItems.filter(
            item => !equippedItemIds.has(item.id || item['0']) && FrEquipmentRuntime.classify(item).slotKey === slotKey && FrEquipmentRuntime.eligibility(ownerRow,slotKey,slotIndex,item).allowed,
          );

          if (selectableItems.length === 0) {
            pickerGrid.innerHTML = `<p style="grid-column: 1 / -1; text-align: center; opacity: 0.7;">储物袋中没有可装备的${slotType}</p>`;
          } else {
            selectableItems.forEach(item => {
              const slot = document.createElement('div');
              slot.className = 'inventory-slot';
              slot.title = `${item.name}\n类型: ${item.type}\n描述: ${item.description}\n效果: ${item.effect}`;
              const presentation = window.FrItemPresentation.rarity(item);
              slot.style.color = presentation.color;
              window.FrItemPresentation.decorate(slot,item);
              slot.innerHTML = window.FrItemPresentation.icon(item,'inventory-slot-icon') + `<span class="inventory-slot-name">${item.name}</span>`;
              slot.addEventListener('click', () => equipItem(item, slotType, slotIndex));
              pickerGrid.appendChild(slot);
            });
          }
          pickerOverlay.classList.add('visible');
        }

        function closeEquipmentPicker() {
          pickerOverlay.classList.remove('visible');
        }

        function addAction(type, data, context = {}, isSilent = false) {
          // 【修改点1：去重逻辑】针对灵兽进阶，同一ID只能保留最后一条指令，防止刷屏
          if (type === 'beast_evolve') {
            actionQueue = actionQueue.filter(a => !(a.type === 'beast_evolve' && a.data.beastId === data.beastId));
          }

          let actionText = '';
          const silentTag = isSilent ? ' (隐秘)' : '';
          switch (type) {
            case 'use':
              const existingAction = actionQueue.find(a => a.type === 'use' && a.data.name === data.name);
              if (existingAction) {
                existingAction.quantity = (existingAction.quantity || 1) + 1;
                renderActionQueue();
                closeItemDetail();
                return;
              }
              actionText = `使用 ${data.name}${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, quantity: 1, isSilent });
              break;
            case 'discard':
              actionText = `你从储物袋中丢弃了[${data.name}]${silentTag}`;
              actionQueue.push({ type: 'discard', text: actionText, data: data, isSilent });
              break;
            case 'equip':
              actionQueue = actionQueue.filter(a => !['equip','unequip'].includes(a.type) || a.context?.slotKey !== context.slotKey || a.context?.slotIndex !== context.slotIndex);
              actionText = `装备 ${data.name}${silentTag}（持有者B1，物品ID:${data.id || data['0']}，位置:${context.slotLabel}，slot:${context.slotKey}，index:${context.slotIndex}；本轮行动意图，按剧情成立后更新装备）`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'unequip':
              actionQueue = actionQueue.filter(a => !['equip','unequip'].includes(a.type) || a.context?.slotKey !== context.slotKey || a.context?.slotIndex !== context.slotIndex);
              actionText = `卸下 ${data.name}${silentTag}（持有者B1，物品ID:${data.id || data['0']}，位置:${context.slotLabel}，slot:${context.slotKey}，index:${context.slotIndex}；按剧情成立后更新装备）`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'toggle_bond':
              actionText = data.isBonded ? `已将 ${data.charName} 标记为羁绊人物` : `已取消与 ${data.charName} 的羁绊`;
              actionText += silentTag;
              actionQueue.push({ type: 'toggle_bond', text: actionText, data: data, isSilent });
              break;
            case 'travel':
              actionText = `玩家 前往 ${data.location}，相距${data.distance}公里${silentTag}`;
              actionQueue = actionQueue.filter(a => a.type !== 'travel');
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'communicate':
              actionText = `对${context.charName}说：“${data}”${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'gift':
              actionText = `将[${data.name}]赠送给${context.charName}${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'spar':
              actionText = `向${context.charName}发起切磋请求${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'accompany':
              actionText = `邀请${context.charName}与你同行${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'cultivate':
              actionText = `邀请${context.charName}进行双修${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'publish_sect_task':
              actionText = `${data.fullText}${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            case 'submit_sect_task':
              actionText = `${data.fullText}${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;

            case 'accept_task':
              // 优先使用 fullText (携带详情)，否则回退到简单文本
              if (data.fullText) {
                actionText = data.fullText + silentTag;
              } else {
                actionText = `我决定接取宗门任务：“${data.title}”${silentTag}`;
              }
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;

            case 'abandon_task':
              actionText = `我决定放弃宗门任务：“${data.title}”${silentTag}`;
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              break;
            // 【修改点2：灵兽进阶指令增强】包含完整面板数据和清晰的突破描述
            case 'beast_evolve':
              const beastStats = `[当前面板] 等级:${data.level}, 血量:${data.hp}, 法力:${data.mp}, 好感:${data.favor}, 性格:${data.personality}`;
              actionText = `(系统通知) 灵兽[${data.beastName}](ID:${data.beastId}) 发生血脉返祖！\n${beastStats}\n【资质突破】: 从 [${data.oldTier}] ➔ 晋升为 [${data.newTier}]！\n请在剧情中详细描述其外观发生的奇异蜕变、散发的威压变化以及觉醒的新特征。`;
              // isSilent: true 确保它是隐式的
              actionQueue.push({ type, text: actionText, data: data, context: context, isSilent: true });
              break;
            default:
              if (actionText !== '') {
                actionQueue.push({ type, text: actionText, data: data, context: context, isSilent });
              }
          }

          renderActionQueue();

          if (type === 'use') closeItemDetail();
          if (type === 'travel') {
            worldMapOverlay.classList.remove('visible');
          }
        }

        function renderActionQueue() {
          commandList.innerHTML = '';
          actionQueue.forEach(action => {
            const li = document.createElement('li');
            li.textContent = action.text;
            commandList.appendChild(li);
          });
          undoCommandBtn.disabled = actionQueue.length === 0;
          clearCommandsBtn.disabled = actionQueue.length === 0;
          document.getElementById('action-queue-indicator').style.display = actionQueue.length > 0 ? 'flex' : 'none';
        }

