function wtRefreshFeatureToggleUI() {
  var toggleEl = document.getElementById('world-evolution-timeline-enable-toggle');
  var concurrentSendToggleEl = document.getElementById('world-evolution-timeline-concurrent-send-toggle');
  var concurrentSendModeWrapEl = document.getElementById('world-evolution-timeline-concurrent-send-mode-wrap');
  var concurrentSendModeBriefEl = document.getElementById('world-evolution-timeline-concurrent-send-mode-brief');
  var concurrentSendModeBothEl = document.getElementById('world-evolution-timeline-concurrent-send-mode-both');
  var concurrentSendModeOriginalEl = document.getElementById('world-evolution-timeline-concurrent-send-mode-original');
  var featureEnabled = !!(wtPromptConfig && wtPromptConfig.enabled !== false);
  var concurrentSendEnabled = wtParseBoolean(
    wtPromptConfig && typeof wtPromptConfig === 'object' ? wtPromptConfig.concurrent_evolution_send_enabled : WT_DEFAULT_PROMPT_CONFIG.concurrent_evolution_send_enabled,
    WT_DEFAULT_PROMPT_CONFIG.concurrent_evolution_send_enabled
  );
  var concurrentSendMode = wtNormalizeConcurrentEvolutionSendMode(
    wtPromptConfig && typeof wtPromptConfig === 'object' ? wtPromptConfig.concurrent_evolution_send_mode : WT_DEFAULT_PROMPT_CONFIG.concurrent_evolution_send_mode,
    WT_DEFAULT_PROMPT_CONFIG.concurrent_evolution_send_mode
  );
  if (toggleEl) toggleEl.checked = featureEnabled;
  if (concurrentSendToggleEl) concurrentSendToggleEl.checked = !!concurrentSendEnabled;
  if (concurrentSendModeBriefEl) concurrentSendModeBriefEl.checked = concurrentSendMode === 'brief';
  if (concurrentSendModeBothEl) concurrentSendModeBothEl.checked = concurrentSendMode === 'both';
  if (concurrentSendModeOriginalEl) concurrentSendModeOriginalEl.checked = concurrentSendMode === 'original';
  if (concurrentSendModeWrapEl) concurrentSendModeWrapEl.style.display = concurrentSendEnabled ? '' : 'none';
}

async function wtSetFeatureEnabled(enabled) {
  await wtEnsurePromptConfigLoaded();
  var cfg = wtClone(wtPromptConfig && typeof wtPromptConfig === 'object' ? wtPromptConfig : WT_DEFAULT_PROMPT_CONFIG);
  cfg.enabled = !!enabled;
  try{await wtSavePromptConfig(cfg);}catch(error){wtRefreshFeatureToggleUI();await wtAlert('设置保存失败：'+String(error.message||error));return;}
  wtRefreshFeatureToggleUI();
  await frTimelineRefreshUI();
}

async function wtSetConcurrentEvolutionSendConfig(patch) {
  await wtEnsurePromptConfigLoaded();
  var cfg = wtClone(wtPromptConfig && typeof wtPromptConfig === 'object' ? wtPromptConfig : WT_DEFAULT_PROMPT_CONFIG);
  var nextPatch = patch && typeof patch === 'object' ? patch : {};
  if (Object.prototype.hasOwnProperty.call(nextPatch, 'enabled')) {
    cfg.concurrent_evolution_send_enabled = !!nextPatch.enabled;
  }
  if (Object.prototype.hasOwnProperty.call(nextPatch, 'mode')) {
    cfg.concurrent_evolution_send_mode = wtNormalizeConcurrentEvolutionSendMode(
      nextPatch.mode,
      WT_DEFAULT_PROMPT_CONFIG.concurrent_evolution_send_mode
    );
  }
  try{await wtSavePromptConfig(cfg);}catch(error){wtRefreshFeatureToggleUI();await wtAlert('设置保存失败：'+String(error.message||error));return;}
  wtRefreshFeatureToggleUI();
  await frTimelineRefreshUI();
}

function wtResetFilters() {
  var startEl = document.getElementById('world-evolution-timeline-filter-start');
  var endEl = document.getElementById('world-evolution-timeline-filter-end');
  if (startEl) startEl.value = '';
  if (endEl) endEl.value = '';
}

function wtEnsureListScrollBinding() {
  var listEl = document.getElementById('world-evolution-timeline-list');
  if (!listEl || listEl.__wtLoadMoreBound) return;

  listEl.addEventListener('scroll', function() {
    var nearBottom = listEl.scrollTop + listEl.clientHeight >= listEl.scrollHeight - 80;
    if (nearBottom) {
      wtReadVisibleInputsBack();
      wtAppendMoreRows();
    }
  }, { passive: true });

  listEl.__wtLoadMoreBound = true;
}

function wtScrollToEntryForEdit(entryIndex) {
  var listEl = document.getElementById('world-evolution-timeline-list');
  if (!listEl) return;

  var targetPos = wtFilteredIndices.indexOf(entryIndex);
  if (targetPos === -1) return;

  while (wtRenderedCount <= targetPos && wtRenderedCount < wtFilteredIndices.length) {
    wtAppendMoreRows();
  }

  requestAnimationFrame(function() {
    var row = listEl.querySelector('[data-wt-item-index="' + entryIndex + '"]');
    if (!row) return;
    row.scrollIntoView({ behavior: 'smooth', block: 'center' });
    var firstEditor = row.querySelector('input[type="text"], textarea, input[type="number"]');
    if (firstEditor) firstEditor.focus();
  });
}

function wtDebugFilterInputLayout() {
  var startEl = document.getElementById('world-evolution-timeline-filter-start');
  var endEl = document.getElementById('world-evolution-timeline-filter-end');
  [startEl, endEl].forEach(function(el) {
    if (!el) return;
    var cs = window.getComputedStyle(el);
    console.log('[年表筛选输入框布局]', el.id, {
      className: el.className,
      width: cs.width,
      minWidth: cs.minWidth,
      maxWidth: cs.maxWidth,
      flex: cs.flex,
      boxSizing: cs.boxSizing,
      paddingLeft: cs.paddingLeft,
      paddingRight: cs.paddingRight
    });
  });
}

async function openWorldEvolutionTimelineModal() {
  if (!worldEvolutionTimelineInitialized) {
    var loaded = await loadWorldEvolutionTimelineConfig();
    worldEvolutionTimelineEntries = loaded.entries || [];
    worldEvolutionTimelineFieldOrder = loaded.fieldOrder || worldEvolutionTimelineFieldOrder;
    worldEvolutionTimelineInitialized = true;
  }

  await wtEnsurePromptConfigLoaded();
  wtEnsureListScrollBinding();
  wtRenderInitialList(true);
  wtRefreshFeatureToggleUI();
  frTimelineShowTab('data');
  if(typeof frTimelineMaterialMode==='function')await frTimelineMaterialMode();
  wtFillPromptModal(wtPromptConfig);
  showWorldEvolutionTimelineOverlay();
  await frTimelineRefreshUI();
  setTimeout(wtDebugFilterInputLayout, 0);
}

function wtBuildBlankEntry() {
  var entry = {};
  worldEvolutionTimelineFieldOrder.forEach(function(key) { entry[key] = ''; });
  if (entry.time_start === undefined) entry.time_start = '';
  if (entry.time_end === undefined) entry.time_end = '';
  return entry;
}

async function wtHandlePrebuiltFiles(files) {
  if(!files.length)return;
  const status=document.getElementById('fr-timeline-prebuilt-status');
  const overwrite=document.getElementById('fr-timeline-prebuilt-overwrite').checked;
  try{
    const inputs=await Promise.all(files.map(async file=>JSON.parse((await file.text()).replace(/^\uFEFF/,''))));
    if(!wtHasDbApi())throw new Error('年表数据库不可用');
    if(!frTimelineCanSave()||wtTimelineSaving)throw new Error('本轮或年表保存正在进行，请结束后再导入');
    wtTimelineSaving=true;
    let applied=0,skipped=0;
    try{
      const storage=await wtReadTimelineStorage();
      const core=ceBridgeCore()['canon-prebuilt'];
      const next=core.mergePrebuiltImports(wtNormalizeEntries(storage.entries,{requireCompleteTimes:false}),inputs);
      const products=new Map(wtStoredPrebuiltProducts(storage).map(row=>[row.eventId,row]));
      for(const row of core.buildPrebuiltExchange(next.entries,next.ids)){
        if(!overwrite&&products.has(row.eventId)){skipped++;continue;}
        products.set(row.eventId,row);
        applied++;
      }
      if(applied){
        if(!frTimelineCanSave())throw new Error('本轮刚开始运行，请结束后再导入');
        const saved={...storage.saved,prebuiltProducts:[...products.values()]};
        if(Array.isArray(saved.entries))saved.entries=saved.entries.map(({prebuilt,...entry})=>entry);
        await dbSet(WORLD_EVOLUTION_TIMELINE_CONFIG_V1,saved);
      }
    }finally{wtTimelineSaving=false;}
    await wtRenderPrebuiltLibrary();
    status.textContent='已导入 '+applied+' 条'+(skipped?'，保留已有成品 '+skipped+' 条':'')+'。';
  }catch(error){status.textContent='预制成品未导入：'+String(error.message||error)+
    (!document.getElementById('fr-timeline-use-builtin').hidden?'。若成品按新版内置年表制作，可先切换年表，再导入同一文件。':'');}
}

async function wtUseBuiltinTimeline() {
  const status=document.getElementById('fr-timeline-prebuilt-status');
  if(!await showCustomConfirm('切换到当前内置年表？编辑区未保存的改动会放弃；已保存年表会备份，已导入成品会保留。'))return;
  if(wtTimelineSaving||!frTimelineCanSave()){status.textContent='请等本轮运行或保存结束后再切换年表。';return;}
  wtTimelineSaving=true;
  try{
    const storage=await wtReadTimelineStorage();
    if(!Array.isArray(storage.saved.entries))return;
    wtNormalizeEntries((await frLoadDefaultAssets()).timeline,{requireCompleteTimes:false});
    if(!frTimelineCanSave())throw new Error('本轮已开始运行，请结束后再切换');
    const saved={...storage.saved,prebuiltProducts:wtStoredPrebuiltProducts(storage)};
    await dbSet(WORLD_EVOLUTION_TIMELINE_CONFIG_V1+'_BEFORE_BUILTIN', {entries:saved.entries,fieldOrder:saved.fieldOrder});
    delete saved.entries;
    if(!frTimelineCanSave())throw new Error('本轮已开始运行，请结束后再切换');
    await dbSet(WORLD_EVOLUTION_TIMELINE_CONFIG_V1,saved);
    const loaded=await loadWorldEvolutionTimelineConfig();
    worldEvolutionTimelineEntries=loaded.entries;
    worldEvolutionTimelineFieldOrder=loaded.fieldOrder;
    wtResetFilters();
    wtRenderInitialList(true);
    _wtCachedTimelinePromptBlock=null;_wtCachedConcurrentEvolutionTimelinePromptBlock=null;
    await frTimelineRefreshUI();
    await wtRenderPrebuiltLibrary();
    status.textContent='已切换到新版内置年表。现在可以导入按这份年表制作的成品。';
  }catch(error){status.textContent='切换年表失败：'+String(error.message||error);}
  finally{wtTimelineSaving=false;}
}

function wtRenderPrebuiltChanges(product) {
  const details=document.createElement('details'),summary=document.createElement('summary');
  details.className='fr-prebuilt-changes';
  const data=product.prebuilt;
  const deltas=Array.isArray(data.eventVariableChanges)?data.eventVariableChanges:[];
  summary.textContent='变量增减 · '+(deltas.length?deltas.length+' 项':'无');
  details.append(summary);
  const labels={gain:'获得',lose:'失去',remove:'移除',consume:'消耗',transfer:'交付',equip:'装备',unequip:'卸下',add:'数值变化'};
  const arts = new Map((ceBridgeCore()?.['cultivation-arts']?.CULTIVATION_ARTS || [])
    .map(art => ['cultivationArts.' + art.key, art.name]));
  const describe = (value, isArt) => {
    if (value == null) return '';
    if (typeof value === 'boolean') return value ? '是' : '否';
    if (typeof value !== 'object') return String(value);
    if (isArt && typeof value.tier === 'string') {
      return value.tier + (Number.isFinite(value.progress) ? ' ' + value.progress + '%' : '');
    }
    return '';
  };
  const personName=row=>row.name||row.actor||'';
  const nodes=new Map((data.nodes||[]).map(node=>[node.id,node]));
  const groups=new Map();
  for(const row of deltas){if(!groups.has(row.nodeId))groups.set(row.nodeId,[]);groups.get(row.nodeId).push(row);}
  if(!groups.size){
    const empty=document.createElement('p');empty.textContent='无可登记的变量增减。';details.append(empty);
  }
  for(const [nodeId,changes] of groups){
    const group=document.createElement('section'),heading=document.createElement('h5'),list=document.createElement('ul'),node=nodes.get(nodeId);
    heading.textContent=[node?.at,node?.title||nodeId].filter(Boolean).join(' · ');
    for(const row of changes){
      const li=document.createElement('li'),tag=document.createElement('small'),value=document.createElement('span');
      const amount=typeof row.value==='number'?(row.action==='add'&&row.value>0?'+':'')+row.value:'';
      const art = arts.get(row.subject);
      const before = describe(row.previousValue ?? row.beforeValue, art);
      const after = describe(row.terminalValue ?? (art ? row.value : undefined), art);
      tag.textContent = art ? (before ? '百艺变化' : '百艺确认') : labels[row.action] || '变化';
      const transition = before && after ? before + ' → ' + after : art ? after || before : '';
      value.textContent = [personName(row), art || row.subject, amount].filter(Boolean).join(' · ') +
        (transition ? '　' + transition : '');
      li.append(tag,value);list.append(li);
    }
    group.append(heading,list);details.append(group);
  }
  return details;
}

async function wtRenderPrebuiltLibrary() {
  const list=document.getElementById('fr-timeline-prebuilt-list');
  if(!list)return;
  const status=document.getElementById('fr-timeline-prebuilt-status');
  try{
    const storage=await wtReadTimelineStorage();
    const {entries,prebuiltProducts}=await loadWorldEvolutionTimelineConfig();
    const matched=new Set(ceBridgeCore()['canon-prebuilt'].buildPrebuiltExchange(entries).map(row=>row.eventId));
    const titles=new Map(entries.map(entry=>[entry.eventId,entry.title]));
    document.getElementById('fr-timeline-prebuilt-source').textContent=Array.isArray(storage.saved.entries)?
      '当前使用已保存的年表 · '+entries.length+' 条':'当前使用内置年表 · '+entries.length+' 条';
    document.getElementById('fr-timeline-use-builtin').hidden=!Array.isArray(storage.saved.entries);
    const selectedIds = new Set(wtPrebuiltSelectedIds());
    const rows=document.createDocumentFragment();
    for(const row of prebuiltProducts){
      const card=document.createElement('article'),header=document.createElement('div');
      const label=document.createElement('label'),check=document.createElement('input'),title=document.createElement('strong'),code=document.createElement('small');
      const badge=document.createElement('span'),remove=document.createElement('button');
      header.className='fr-prebuilt-card-head';
      check.type='checkbox';check.value=row.eventId;check.checked=selectedIds.has(row.eventId);
      code.textContent=row.eventId;
      title.textContent=(titles.get(row.eventId)||row.title||row.eventId).replace(/^【[^】]+】\s*/,'');
      label.append(check,code,title);
      badge.className='fr-prebuilt-match';
      badge.dataset.match=String(matched.has(row.eventId));
      badge.textContent=matched.has(row.eventId)?'已匹配':'年表已变或缺失';
      remove.type='button';remove.className='fr-prebuilt-danger';remove.dataset.prebuiltRemove=row.eventId;
      remove.textContent='删除';remove.setAttribute('aria-label','删除成品 '+row.eventId);
      header.append(label,badge,remove);card.append(header,wtRenderPrebuiltChanges(row));rows.append(card);
    }
    if(!prebuiltProducts.length){
      const empty=document.createElement('div');
      empty.className='fr-prebuilt-empty';empty.textContent='成品库为空。导入预制成品后，可在这里查看匹配状态与变量增减。';
      rows.append(empty);
    }
    list.replaceChildren(rows);
    list.dataset.matched=String(matched.size);
    wtUpdatePrebuiltSelection();
    status.textContent='';
  }catch(error){status.textContent='成品读取失败：'+error.message;}
}

function wtPrebuiltSelectedIds() {
  return Array.from(document.querySelectorAll('#fr-timeline-prebuilt-list input:checked'), input => input.value);
}

function wtUpdatePrebuiltSelection() {
  const list=document.getElementById('fr-timeline-prebuilt-list');
  const total=list.querySelectorAll('input[type="checkbox"]').length;
  const selected=wtPrebuiltSelectedIds().length;
  const all=document.getElementById('fr-timeline-prebuilt-select-all');
  all.disabled=!total;all.checked=total>0&&selected===total;all.indeterminate=selected>0&&selected<total;
  document.getElementById('fr-timeline-prebuilt-count').textContent=total+' 条成品 · '+(list.dataset.matched||0)+' 条匹配 · 已选 '+selected+' 条';
  for(const id of ['export-selected','delete-selected'])document.getElementById('fr-timeline-prebuilt-'+id).disabled=!selected;
  for(const id of ['export-all','delete-all'])document.getElementById('fr-timeline-prebuilt-'+id).disabled=!total;
}

async function wtDeletePrebuiltProducts(ids) {
  const status=document.getElementById('fr-timeline-prebuilt-status');
  try {
    if(!wtHasDbApi()||wtTimelineSaving||!frTimelineCanSave())throw new Error('请等本轮运行或保存结束后再删除');
    const initial=await wtReadTimelineStorage();
    const idSet=new Set(ids || wtStoredPrebuiltProducts(initial).map(row=>row.eventId));
    const targets=wtStoredPrebuiltProducts(initial).filter(row=>idSet.has(row.eventId));
    if(!targets.length)return;
    const name=targets.length===1?targets[0].eventId+' 成品':targets.length+' 条预制成品';
    if(!await showCustomConfirm('确定删除 '+name+'？可从导出文件重新导入。对应年表和已经写入存档的补演结果会保留。'))return;
    if(wtTimelineSaving||!frTimelineCanSave())throw new Error('请等本轮运行或保存结束后再删除');
    wtTimelineSaving=true;
    try {
      const current=await wtReadTimelineStorage(),products=wtStoredPrebuiltProducts(current);
      if(JSON.stringify(products.filter(row=>idSet.has(row.eventId)))!==JSON.stringify(targets)
        || (ids===null&&products.length!==targets.length))throw new Error('成品库已变化，请重新选择');
      const saved={...current.saved,prebuiltProducts:products.filter(row=>!idSet.has(row.eventId))};
      if(Array.isArray(saved.entries))saved.entries=saved.entries.map(({prebuilt,...entry})=>entry);
      if(!frTimelineCanSave())throw new Error('本轮刚开始运行，请结束后再删除');
      await dbSet(WORLD_EVOLUTION_TIMELINE_CONFIG_V1,saved);
    } finally {wtTimelineSaving=false;}
    await wtRenderPrebuiltLibrary();
    status.textContent='已删除 '+targets.length+' 条预制成品。';
  } catch(error) {status.textContent='未删除成品：'+String(error.message||error);}
}

async function wtExportPrebuiltLibrary(onlySelected) {
  const status=document.getElementById('fr-timeline-prebuilt-status');
  const ids=onlySelected?wtPrebuiltSelectedIds():null;
  try{
    const saved=await wtReadTimelineStorage();
    const products=ceBridgeCore()['canon-prebuilt'].buildPrebuiltExchange(wtStoredPrebuiltProducts(saved),ids);
    if(!products.length)return;
    wtDownloadTimelineJson(products,products.length===1?'预制成品-'+products[0].eventId+'.json':'预制成品-批量.json');
  }catch(error){status.textContent='成品导出失败：'+error.message;}
}

function wtMergeTimelineImportEntries(normalized) {
  wtReadVisibleInputsBack();
  wtSortEntriesInPlace(normalized);
  const keyToIndex = new Map(worldEvolutionTimelineEntries.map((row, index) => [wtBuildEntryMergeKey(row), index]));

  let added = 0;
  let merged = 0;
  for (const incoming of normalized) {
    const key = wtBuildEntryMergeKey(incoming);
    const existingIdx = keyToIndex.get(key);
    if (existingIdx === undefined) {
      keyToIndex.set(key, worldEvolutionTimelineEntries.length);
      worldEvolutionTimelineEntries.push(incoming);
      added++;
      continue;
    }
    const target = worldEvolutionTimelineEntries[existingIdx];
    for (const [field, value] of Object.entries(incoming)) {
      if (WT_BASE_TIMELINE_FIELD_ORDER.includes(field)) {
        if (wtSafeString(value).trim()) target[field] = value;
      } else if (!wtSafeString(target[field]).trim()) {
        target[field] = value;
      }
    }
    merged++;
  }

  wtSortEntriesInPlace(worldEvolutionTimelineEntries);
  return '已导入编辑区：新增 ' + added + ' 条，合并 ' + merged + ' 条。';
}

async function wtReadTimelineImportFile(file, mode) {
  const text = await file.text();
  let input;
  try {
    input = JSON.parse(text.replace(/^\uFEFF/, ''));
  } catch {
    throw new Error(file.name + ' 不是合法 JSON。');
  }
  let rows = input;
  if (input?.format === 'fanren-timeline-exchange-v1') {
    if (mode !== 'selected') throw new Error('这是单条或批次年表，请用「按编号替换」导入。');
    rows = input.events;
    if (!Array.isArray(rows) || !rows.length ||
        (input.scope !== 'batch' && (input.scope !== 'single' || rows.length !== 1))) {
      throw new Error('单条或批次年表格式无效。');
    }
  } else if (mode === 'selected' && !Array.isArray(rows) && rows && typeof rows === 'object') {
    rows = [rows];
  }
  if ((input && Object.hasOwn(input, 'prebuilt')) ||
      (Array.isArray(rows) && rows.some(row => row && Object.hasOwn(row, 'prebuilt')))) {
    throw new Error('文件包含预制成品，请在「预制成品」页导入。');
  }
  const sourceHint = file.name.includes('原著') ? 'original' : 'brief';
  return wtNormalizeEntries(rows, { requireCompleteTimes: true, sourceHint });
}

function wtReplaceTimelineEntriesById(entries, incoming) {
  const replacements = new Map();
  for (const row of incoming) {
    if (!row.eventId) throw new Error('按编号替换要求每条资料都带有有效的事件编号。');
    if (replacements.has(row.eventId)) throw new Error('导入的事件编号重复：' + row.eventId + '。');
    replacements.set(row.eventId, row);
  }
  const matched = new Set();
  const next = entries.map(row => {
    const id = wtResolveTimelineEventId(row);
    if (!replacements.has(id)) return row;
    if (matched.has(id)) throw new Error('编辑区的事件编号重复：' + id + '。');
    matched.add(id);
    return replacements.get(id);
  });
  for (const id of replacements.keys()) {
    if (!matched.has(id)) throw new Error('编辑区没有事件 ' + id + '，本次未替换任何条目。');
  }
  return next;
}

async function wtHandleTimelineImport(files, mode) {
  if (!files.length || wtTimelineImporting) return;
  wtTimelineImporting = true;
  try {
    const incoming = [];
    for (const file of files) {
      const rows = await wtReadTimelineImportFile(file, mode);
      for (const row of rows) incoming.push(row);
    }
    let message;
    if (mode === 'merge') {
      message = wtMergeTimelineImportEntries(incoming);
    } else {
      const check = wtValidateBeforeSaveOrExport(incoming);
      if (!check.ok) throw new Error(check.reason);
      if (mode === 'all') {
        if (!await showCustomConfirm('将用 ' + incoming.length + ' 条资料替换编辑区整张年表。确定继续？点击保存后才会生效。')) return;
        wtSortEntriesInPlace(incoming);
        worldEvolutionTimelineEntries = incoming;
        message = '已替换整表：共 ' + incoming.length + ' 条。';
      } else {
        worldEvolutionTimelineEntries = wtReplaceTimelineEntriesById(worldEvolutionTimelineEntries, incoming);
        message = '已替换 ' + incoming.length + ' 条年表资料。';
      }
    }
    worldEvolutionTimelineInitialized = true;
    wtResetFilters();
    wtRenderInitialList(true);
    await wtAlert(message + '点击保存后才会作为新补演资料生效。');
  } catch (error) {
    await wtAlert('导入失败：' + String(error.message || error));
  } finally {
    wtTimelineImporting = false;
  }
}

async function wtHandleSave(){
  if(!frTimelineCanSave()){await wtAlert('本轮正文、演化或局部重跑尚未结束，请结束后保存年表。编辑草稿仍保留。');return;}
  try{
    wtReadVisibleInputsBack();var check=wtValidateBeforeSaveOrExport();if(!check.ok)throw new Error(check.reason);
    await saveWorldEvolutionTimelineConfig();wtRenderInitialList(false);
    if(typeof frTimelineRefreshUI==='function')await frTimelineRefreshUI();
    await wtAlert('年表已保存。后续原著指导与补演读取本次资料；未保存的编辑不作为补演依据。');
  }catch(error){await wtAlert('保存失败：'+String(error.message||error)+'。草稿已保留，实际供料仍为上次保存内容。');}
}

async function wtHandleExport() {
  wtReadVisibleInputsBack();
  var check = wtValidateBeforeSaveOrExport();
  if (!check.ok) {
    await wtAlert('导出失败：' + check.reason);
    return;
  }

  wtDownloadTimelineJson(worldEvolutionTimelineEntries.map(({prebuilt,...entry})=>entry),'world-evolution-timeline.json');
}

function wtDownloadTimelineJson(data,name) {
  var payload = JSON.stringify(data, null, 2);
  var blob = new Blob([payload], { type: 'application/json;charset=utf-8' });
  var url = URL.createObjectURL(blob);

  var a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}

async function wtOpenPromptModal() {
  await wtEnsurePromptConfigLoaded();
  wtFillPromptModal(wtPromptConfig);
  wtShowPromptOverlay();
  await frTimelineRefreshUI();
}

async function wtSavePromptModal() {
  var cfg = wtReadPromptModalConfig();
  if (!cfg.prompt) {
    await wtAlert('提示词不能为空。');
    return;
  }
  var check = wtValidatePromptConfig(cfg);
  if (!check.ok) {
    await wtAlert(check.reason || '提示词设置无效。');
    return;
  }
  var previous=wtClone(wtPromptConfig),commonBefore=typeof ceBridgeLoadConfig==='function'?await ceBridgeLoadConfig():null,sharedMode=document.getElementById('fr-timeline-shared-material');
  try{
    await wtSavePromptConfig(cfg);
    if(sharedMode&&commonBefore&&commonBefore.enabled===false){var selectedMode=sharedMode.querySelector('input[name="fr-timeline-material"]:checked')?.value;if(selectedMode&&selectedMode!==commonBefore.materialMode&&!await ceBridgeSaveConfig({...commonBefore,materialMode:selectedMode}))throw Error('共用材料设置保存失败');}
  }catch(error){try{await wtSavePromptConfig(previous);}catch(rollback){await wtAlert('设置回退失败：'+rollback.message);return;}await wtAlert('设置保存失败：'+String(error.message||error));return;}
  wtRefreshFeatureToggleUI();
  wtHidePromptOverlay();
  await wtAlert('提示词设置已保存。');
}

async function wtConfirmDeleteAllEntries() {
  worldEvolutionTimelineEntries = [];
  wtResetFilters();
  wtRenderInitialList(true);
  wtHideDeleteAllOverlay();
  await wtAlert('编辑区条目已清空，尚未写入数据库。点击保存后新补演才会读取空表；未保存前仍沿用上次资料。');
}

function wtApplyFilterFromInputs() {
  wtReadVisibleInputsBack();
  wtRenderInitialList(true);
}

function initWorldEvolutionTimelineFeature() {
  if (window.__worldEvolutionTimelineFeatureInited) return;
  window.__worldEvolutionTimelineFeatureInited = true;

  document.addEventListener('click', function(e) {
    var target = e.target;

    if (target.closest('#open-world-evolution-timeline-btn')) {
      openWorldEvolutionTimelineModal();
      return;
    }

    if (target.closest('#world-evolution-timeline-close-btn')) {
      hideWorldEvolutionTimelineOverlay();
      return;
    }

    if(target.closest('#fr-timeline-prebuilt-import-btn')){
      const input=document.getElementById('fr-timeline-prebuilt-import');
      if(input){input.value='';input.click();}
      return;
    }
    if(target.closest('#fr-timeline-use-builtin')){wtUseBuiltinTimeline();return;}
    if(target.closest('#fr-timeline-prebuilt-export-selected,#fr-timeline-prebuilt-export-all')){
      wtExportPrebuiltLibrary(!!target.closest('#fr-timeline-prebuilt-export-selected'));
      return;
    }
    const prebuiltRemove=target.closest('[data-prebuilt-remove]');
    if(prebuiltRemove){wtDeletePrebuiltProducts([prebuiltRemove.dataset.prebuiltRemove]);return;}
    if(target.closest('#fr-timeline-prebuilt-delete-selected,#fr-timeline-prebuilt-delete-all')){
      wtDeletePrebuiltProducts(target.closest('#fr-timeline-prebuilt-delete-all')?null:wtPrebuiltSelectedIds());
      return;
    }
    const timelineImport = target.closest('[data-wt-import-mode]');
    if (timelineImport) {
      var input = document.getElementById('world-evolution-timeline-import-input');
      if (input && !wtTimelineImporting) {
        input.dataset.mode = timelineImport.dataset.wtImportMode;
        input.multiple = input.dataset.mode === 'selected';
        input.value = '';
        input.click();
      }
      return;
    }

    if (target.closest('#world-evolution-timeline-add-btn')) {
      wtReadVisibleInputsBack();
      wtResetFilters();
      worldEvolutionTimelineEntries.unshift(wtBuildBlankEntry());
      var newIndex = 0;
      wtRenderInitialList(true);
      wtScrollToEntryForEdit(newIndex);
      return;
    }

    if (target.closest('#world-evolution-timeline-resort-btn')) {
      wtReadVisibleInputsBack();
      wtSortEntriesInPlace(worldEvolutionTimelineEntries);
      wtRenderInitialList(false);
      return;
    }

    if (target.closest('#world-evolution-timeline-save-btn')) {
      wtHandleSave();
      return;
    }

    if (target.closest('#world-evolution-timeline-export-btn')) {
      wtHandleExport();
      return;
    }

    if (target.closest('#world-evolution-timeline-delete-all-btn')) {
      wtShowDeleteAllOverlay();
      return;
    }

    if (target.closest('#world-evolution-timeline-filter-clear-btn')) {
      wtResetFilters();
      wtApplyFilterFromInputs();
      return;
    }

    if (target.closest('#world-evolution-timeline-prompt-btn')) {
      wtOpenPromptModal();
      return;
    }

    if (target.closest('#world-evolution-timeline-prompt-close-btn') || target.closest('#world-evolution-timeline-prompt-cancel-btn')) {
      wtHidePromptOverlay();
      return;
    }

    if (target.closest('#world-evolution-timeline-delete-all-close-btn') || target.closest('#world-evolution-timeline-delete-all-cancel-btn')) {
      wtHideDeleteAllOverlay();
      return;
    }

    if (target.closest('#world-evolution-timeline-delete-all-confirm-btn')) {
      wtConfirmDeleteAllEntries();
      return;
    }

    if (target.closest('#world-evolution-timeline-prompt-default-btn')) {
      var _wtCurrentModalCfg = wtReadPromptModalConfig();
      var _wtDefaultPromptCfg = wtClone(WT_DEFAULT_PROMPT_CONFIG);
      _wtDefaultPromptCfg.time_infer_enabled = wtParseBoolean(_wtCurrentModalCfg.time_infer_enabled, WT_DEFAULT_PROMPT_CONFIG.time_infer_enabled);
      _wtDefaultPromptCfg.time_infer_api_url = wtSafeString(_wtCurrentModalCfg.time_infer_api_url || '');
      _wtDefaultPromptCfg.time_infer_api_key = wtSafeString(_wtCurrentModalCfg.time_infer_api_key || '');
      _wtDefaultPromptCfg.time_infer_api_model = wtSafeString(_wtCurrentModalCfg.time_infer_api_model || '');
      wtFillPromptModal(_wtDefaultPromptCfg);
      return;
    }

    if (target.closest('#world-evolution-timeline-prompt-save-btn')) {
      wtSavePromptModal();
      return;
    }

    if (target.closest('#world-evolution-timeline-time-infer-fetch-models-btn')) {
      if (typeof fetchModelsForPanel === 'function') {
        fetchModelsForPanel(
          'world-evolution-timeline-time-infer-api-url',
          'world-evolution-timeline-time-infer-api-key',
          'world-evolution-timeline-time-infer-api-model',
          target.closest('#world-evolution-timeline-time-infer-fetch-models-btn')
        );
      } else {
        wtAlert('当前环境未找到 fetchModelsForPanel，无法自动拉取模型。请手动填写模型名称。');
      }
      return;
    }

    var actionBtn = target.closest('[data-wt-action]');
    if (actionBtn) {
      var action = actionBtn.getAttribute('data-wt-action');
      var idx = parseInt(actionBtn.getAttribute('data-wt-index'), 10);

      if (action === 'delete' && worldEvolutionTimelineEntries[idx]) {
        wtReadVisibleInputsBack();
        worldEvolutionTimelineEntries.splice(idx, 1);
        wtRenderInitialList(false);
      } else if (action === 'toggle-same-time' && worldEvolutionTimelineEntries[idx]) {
        wtReadVisibleInputsBack();
        var item = worldEvolutionTimelineEntries[idx];
        var ts = wtParseTimelinePointStrict(item.time_start);
        if (actionBtn.checked) item.time_end = ts ? wtFormatTimelinePoint(ts) : item.time_start;
        wtRenderInitialList(false);
      }
      return;
    }

    var overlay = document.getElementById('world-evolution-timeline-overlay');
    if (overlay && target === overlay) {
      hideWorldEvolutionTimelineOverlay();
      return;
    }

    var promptOverlay = document.getElementById('world-evolution-timeline-prompt-overlay');
    if (promptOverlay && target === promptOverlay) {
      wtHidePromptOverlay();
      return;
    }

    var deleteAllOverlay = document.getElementById('world-evolution-timeline-delete-all-overlay');
    if (deleteAllOverlay && target === deleteAllOverlay) {
      wtHideDeleteAllOverlay();
      return;
    }
  });

  document.addEventListener('input', function(e) {
    var target = e.target;

    if (target && (target.id === 'world-evolution-timeline-filter-start' || target.id === 'world-evolution-timeline-filter-end')) {
      var normalized = wtNormalizeTimelineInputValue(target.value);
      if (target.value !== normalized) target.value = normalized;
      wtApplyFilterFromInputs();
      return;
    }

    if (!target.matches('[data-wt-index][data-wt-key]')) return;

    var idx = parseInt(target.getAttribute('data-wt-index'), 10);
    var key = target.getAttribute('data-wt-key');
    if (!worldEvolutionTimelineEntries[idx]) return;

    if (key === 'time_single') {
      var t = wtParseTimelinePointStrict(target.value);
      var v = t ? wtFormatTimelinePoint(t) : target.value;
      worldEvolutionTimelineEntries[idx].time_start = v;
      worldEvolutionTimelineEntries[idx].time_end = v;
      return;
    }

    if (key === 'time_start' || key === 'time_end') {
      var parsed = wtParseTimelinePointStrict(target.value);
      worldEvolutionTimelineEntries[idx][key] = parsed ? wtFormatTimelinePoint(parsed) : target.value;
    } else if (key === 'title') {
      wtUpdateTimelineEntryTitle(worldEvolutionTimelineEntries[idx], target.value);
    } else {
      worldEvolutionTimelineEntries[idx][key] = target.value;
    }
  });

  document.addEventListener('change', function(e) {
    var target = e.target;
    if (target && (
      target.id === 'world-evolution-timeline-prompt-inject-original-toggle' ||
      target.id === 'world-evolution-timeline-time-infer-enabled-toggle' ||
      target.id === 'world-evolution-timeline-inject-mode-time' ||
      target.id === 'world-evolution-timeline-inject-mode-event'
    )) {
  if (typeof frHydrateLibraryConfig === 'function' && wtPromptConfig) frHydrateLibraryConfig('WORLD_EVOLUTION_TIMELINE_PROMPT_CONFIG_V1', wtPromptConfig);
  wtRefreshPromptModalConditionalUI();
      return;
    }
    if (target && target.id === 'world-evolution-timeline-enable-toggle') {
      wtSetFeatureEnabled(!!target.checked);
      return;
    }
    if (target && target.id === 'world-evolution-timeline-concurrent-send-toggle') {
      wtSetConcurrentEvolutionSendConfig({ enabled: !!target.checked });
      return;
    }
    if (target && (
      target.id === 'world-evolution-timeline-concurrent-send-mode-brief' ||
      target.id === 'world-evolution-timeline-concurrent-send-mode-both' ||
      target.id === 'world-evolution-timeline-concurrent-send-mode-original'
    )) {
      if (target.checked) {
        wtSetConcurrentEvolutionSendConfig({ mode: target.value || 'brief' });
      }
      return;
    }
    if(target?.id==='fr-timeline-prebuilt-import'){
      wtHandlePrebuiltFiles(Array.from(target.files||[]));return;
    }
    if(target?.id==='fr-timeline-prebuilt-select-all'){
      document.querySelectorAll('#fr-timeline-prebuilt-list input[type="checkbox"]').forEach(input=>{input.checked=target.checked;});
      wtUpdatePrebuiltSelection();
      return;
    }
    if(target?.closest('#fr-timeline-prebuilt-list')){
      wtUpdatePrebuiltSelection();
      return;
    }
    if (!target || target.id !== 'world-evolution-timeline-import-input') return;
    wtHandleTimelineImport(Array.from(target.files || []), target.dataset.mode || 'merge');
  });

  wtEnsureListScrollBinding();
}

setTimeout(function() {
  initWorldEvolutionTimelineFeature();
}, 100);

