var concurrentEvolutionAbortController = null;
var concurrentEvolutionProgressData = null;
var concurrentEvolutionStatusItem = null;  // Danmaku status 元素引用
var concurrentEvolutionWholeProcessStatusItem = null;
var offscreenTagCalibrationStatusItem = null;
var offscreenTagCalibrationAbortController = null;
var offscreenTagCalibrationRunning = false;
