// ===== Thinking内容提取 =====
function ceExtractThinkingContent(responseText) {
  if (!responseText || typeof responseText !== 'string') return '';
  const match = responseText.match(/<thinking>([\s\S]*?)<\/thinking>/i);
  if (match) {
    return match[1].trim();
  }
  // 无thinking标签时，返回去掉<upstore>...</upstore>后的内容
  return responseText.replace(/<upstore>[\s\S]*?<\/upstore>/gi, '').trim();
}

// ===== Thinking内容HTML转义 =====
function ceEscapeHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ===== 生图提示词处理 =====


var CE_IMAGE_GRID_ALLOWED_COUNTS = [4, 9];











function ceStripImagePromptBlocksFromHtml(html) {
  if (!html || typeof html !== 'string') return html || '';
  return html
    .replace(/<p[^>]*data-ce-image-prompt[^>]*>[\s\S]*?<\/p>/gi, '')
    .replace(/<div[^>]*data-ce-image-prompt[^>]*>[\s\S]*?<\/div>/gi, '');
}

function ceStripGeneratedImageBlocksFromHtml(html) {
  if (!html || typeof html !== 'string') return html || '';
  return html
    .replace(/<figure[^>]*data-ce-generated-image[^>]*>[\s\S]*?<\/figure>/gi, '')
    .replace(/<p[^>]*data-ce-generated-image-error[^>]*>[\s\S]*?<\/p>/gi, '');
}

function ceStoryImageParagraphs(body) {
  const paragraphs = [];
  let text = '', endpoint;
  const finish = () => {
    if (text.trim() && endpoint) paragraphs.push({text,endpoint});
    text = '';
    endpoint = null;
  };
  const walk = element => {
    for (const node of element.childNodes) {
      if (node.nodeType === Node.TEXT_NODE) {
        let start = 0;
        for (const newline of node.data.matchAll(/\r?\n/g)) {
          text += node.data.slice(start,newline.index);
          endpoint = [node,newline.index];
          finish();
          start = newline.index + newline[0].length;
        }
        if (start < node.length) {
          text += node.data.slice(start);
          endpoint = [node,node.length];
        }
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        if (node.matches('ui_sys,.fr-story-status,[hidden],think,script,style,[data-evolution-detail],[data-ce-generated-image],[data-ce-image-prompt]')) {
          finish();
        } else if (node.matches('br,hr')) {
          finish();
        } else if (node.matches('p,blockquote,li,h1,h2,h3,h4,h5,h6')) {
          finish();
          text = node.textContent;
          endpoint = [node];
          finish();
        } else if (node.matches('div,section,article,content,ul,ol')) {
          finish();
          walk(node);
          finish();
        } else walk(node);
      }
    }
  };
  walk(body);
  finish();
  return paragraphs;
}

function ceMatchStoryImageParagraph(paragraphs, anchor) {
  const exact = paragraphs.findIndex(paragraph => paragraph.text.includes(anchor));
  if (exact >= 0) return exact;
  const normalize = value => value.replace(/[\s，。！？；：、,.!?;:'"“”‘’（）()《》〈〉【】\[\]—…·\-]/gu,'');
  const key = normalize(anchor);
  return key ? paragraphs.findIndex(paragraph => normalize(paragraph.text).includes(key)) : -1;
}



function ceBuildSafeDetailedEvolutionHtmlFragment(fragmentHtml) {
  // 人物故事由专用阅读窗承载；兼容旧存档，仅过滤正文下方的重复呈现。
  const raw = String(fragmentHtml || '').replace(/<!--FR_CANON_START-->[\s\S]*?<!--FR_CANON_END-->/g, '').trim();
  if (!raw || typeof document === 'undefined') return '';
  try {
    const container = document.createElement('div');
    container.innerHTML = raw;
    container.querySelectorAll('[data-fr-canon]').forEach(function(node) { node.remove(); });
    const hasElementNode = Array.from(container.childNodes).some(function(node) {
      return node && node.nodeType === 1;
    });
    if (!hasElementNode) return '';
    return '<div class="ce-evolution-detail" data-evolution-detail="true">' + container.innerHTML + '</div>';
  } catch (e) {
    console.warn('[并发演化] 详情HTML片段校验失败，已跳过追加:', e);
    return '';
  }
}



function ceGetPendingCol19Map() {
  if (typeof window === 'undefined') return null;
  if (!window._cePendingCol19ById || !(window._cePendingCol19ById instanceof Map)) {
    window._cePendingCol19ById = new Map();
  }
  return window._cePendingCol19ById;
}

function ceIsCol19NpcId(id, targetMap) {
  if (!id) return false;
  const strId = String(id);
  if (strId === 'B1') return false;
  if (ceIsBeastId(strId)) return false;
  if (targetMap && targetMap.get) {
    const target = targetMap.get(strId);
    if (target && target.type) return target.type === 'npc';
  }
  return /^C\d+/.test(strId) || (currentState && currentState['0'] && !!currentState['0'][strId]);
}

async function ceApplyPendingCol19ForTargetId(targetId, targetMap) {
  const pendingMap = ceGetPendingCol19Map();
  if (!pendingMap || !pendingMap.has(targetId)) return false;
  if (!ceIsCol19NpcId(targetId, targetMap)) {
    pendingMap.delete(targetId);
    return false;
  }
  let target = targetMap && targetMap.get ? targetMap.get(targetId) : null;
  if (!target && currentState && currentState['0'] && currentState['0'][targetId]) {
    const row = currentState['0'][targetId];
    target = {
      id: targetId,
      type: 'npc',
      name: ((row['1'] || '').split('|')[0] || targetId).replace(/<[^>]*>/g, ''),
      data: row,
      biography: null,
      sceneType: 'onscene'
    };
  }
  if (!target || target.type !== 'npc') return false;
  const col19Text = pendingMap.get(targetId);
  if (!col19Text) return false;

  const op = { command: 'add', id: targetId, data: { '19': col19Text } };
  const applied = await applyConcurrentEvolutionDelta(op, target);
  if (applied) {
    pendingMap.delete(targetId);
    console.log(`[生图演化][列19] 已应用列19: ${targetId}`);
  }
  return applied;
}

function ceQueueCol19Updates(col19Data, options = {}) {
  if (!Array.isArray(col19Data) || col19Data.length === 0) return;
  const targetMap = options.targetMap || null;
  const pendingMap = ceGetPendingCol19Map();
  if (!pendingMap) return;

  col19Data.forEach(item => {
    if (!item || !item.id || !item.value) return;
    const targetId = String(item.id);
    if (!ceIsCol19NpcId(targetId, targetMap)) return;
    pendingMap.set(targetId, String(item.value));
  });
}

function cePeekPendingCol19OpForTarget(target, targetMap) {
  if (!target || !target.id) return null;
  if (target.type !== 'npc') return null;
  if (!ceIsCol19NpcId(target.id, targetMap)) return null;
  const pendingMap = ceGetPendingCol19Map();
  if (!pendingMap || !pendingMap.has(target.id)) return null;
  return { command: 'add', id: target.id, data: { '19': pendingMap.get(target.id) } };
}

function ceTakePendingCol19OpForTarget(target, targetMap) {
  if (!target || !target.id) return null;
  if (target.type !== 'npc') return null;
  if (!ceIsCol19NpcId(target.id, targetMap)) return null;
  const pendingMap = ceGetPendingCol19Map();
  if (!pendingMap || !pendingMap.has(target.id)) return null;
  const value = pendingMap.get(target.id);
  pendingMap.delete(target.id);
  return { command: 'add', id: target.id, data: { '19': value } };
}

async function ceApplyPendingCol19ForProcessedTargets(processedIds, targetMap) {
  const pendingMap = ceGetPendingCol19Map();
  if (!pendingMap || pendingMap.size === 0) return { applied: 0 };
  if (!processedIds || processedIds.size === 0) return { applied: 0 };
  let applied = 0;
  const ids = Array.from(pendingMap.keys());
  for (const id of ids) {
    if (!processedIds.has(id)) continue;
    const ok = await ceApplyPendingCol19ForTargetId(id, targetMap);
    if (ok) applied++;
  }
  return { applied };
}

function ceGetTypeLabel(type) {
  var map = { player: '\u73A9\u5BB6', npc: 'NPC', beast: '\u7075\u517D' };
  return map[type] || '';
}

function ceIsBeastId(id) {
  if (typeof id !== 'string') return false;
  return /^P(?:_|\d+)/.test(id);
}

function ceSanitizeCharacterName(name) {
  return String(name || '').replace(/<[^>]*>/g, '').trim();
}

function ceExtractCharacterNameFromRow(row) {
  if (!row || typeof row !== 'object') return '';
  var rawName = row['1'];
  if (rawName === undefined || rawName === null) rawName = row[1];
  return ceSanitizeCharacterName(String(rawName || '').split('|')[0]);
}

function ceParseWorldBookEntryContentForName(entry) {
  if (!entry || typeof entry !== 'object') return null;
  if (typeof ceParseWorldbookEntryContent === 'function') {
    return ceParseWorldbookEntryContent(entry);
  }
  var content = entry.content;
  if (!content) return null;
  if (typeof content === 'object') return content;
  if (typeof content !== 'string') return null;
  try {
    return JSON.parse(content);
  } catch (e) {
    return null;
  }
}

function ceFindCharacterNameInWorldBookEntries(targetId, entries) {
  if (!targetId || !Array.isArray(entries) || entries.length === 0) return '';
  for (var i = 0; i < entries.length; i++) {
    var entry = entries[i];
    if (!entry || typeof entry !== 'object') continue;
    var content = ceParseWorldBookEntryContentForName(entry) || {};
    var entryId = entry.key || entry.id || entry.characterId || entry.charId || '';
    var contentId = content['0'] || content[0] || '';
    if (String(entryId || '').trim() !== targetId && String(contentId || '').trim() !== targetId) continue;
    var titleName = ceSanitizeCharacterName(entry.title || entry.name || entry.displayName || '');
    if (titleName) return titleName;
    var rowName = ceExtractCharacterNameFromRow(content);
    if (rowName) return rowName;
  }
  return '';
}

// @CUSTOM-START: 角色 id 归一化（玩家 2026-10-30：韩立明明在，却说档案不存在）
//
// 现象：补演提交时报「离场物品角色档案不存在：C_HanLi」。
// 根因：C_HanLi 这个 id 在代码里根本不存在——系统分配的 id 一律是 C1/C2 这种纯数字。
//       模型在补演时想给韩立加物品，没去抄真实 id，而是照着名字拼音自己造了一个。
//       于是 prepareItemManagementFallbackRows 拿假 id 去 currentState['0'] 和世界书里查，
//       两处都查不到，strict 模式直接抛错，整轮补演作废。
//
// 修法（玩家 2026-10-30 定：加一层兼容）：
//   拿到的 id 如果查不到，就把它当「名字线索」去反查真实角色。
//   C_HanLi → 去掉 C_ 前缀 → HanLi → 拼音匹配「韩立」→ 返回 C7 这样的真实 id。
//   查不到就原样返回，让上层照旧报错——不能因为归一化失败就静默放过，
//   那会把玩家真该拿到的物品弄丢。
function ceNormalizeCharacterId(rawId) {
  var id = rawId == null ? '' : String(rawId).trim();
  if (!id) return '';
  // B1 是玩家，不参与归一化。
  if (id === 'B1') return id;
  // 真实 id 直接返回：C12 这种纯数字，或当前状态里确实存在的键。
  if (/^C\d+$/.test(id)) return id;
  if (currentState && currentState['0'] && currentState['0'][id]) return id;
  if (currentState && currentState['7'] && currentState['7'][id]) return id;
  if (typeof itemManagementFallbackRows !== 'undefined' && itemManagementFallbackRows && itemManagementFallbackRows.has && itemManagementFallbackRows.has(id)) return id;

  // ---- 到这里说明是个查不到的 id，尝试按名字线索反查 ----
  // 提取线索：C_HanLi → HanLi；C_韩立 → 韩立；韩立 → 韩立
  var clue = id.replace(/^[Cc][_\-]?/, '').trim();
  if (!clue) return id;

  var candidates = [];
  var pushCand = function (cid, cname) {
    if (!cid || !cname) return;
    var sname = String(cname).trim();
    if (!sname) return;
    candidates.push({ id: String(cid), name: sname });
  };

  // 候选来源一：当前在场人物
  try {
    if (currentState && currentState['0']) {
      Object.keys(currentState['0']).forEach(function (cid) {
        if (cid === 'B1') return;
        var row = currentState['0'][cid];
        var name = '';
        try {
          name = typeof ceExtractCharacterNameFromRow === 'function'
            ? ceExtractCharacterNameFromRow(row)
            : String((row && row['1']) || '').split('|')[0];
        } catch (_) {}
        pushCand(cid, name);
      });
    }
  } catch (_) {}
  // 候选来源二：灵兽
  try {
    if (currentState && currentState['7']) {
      Object.keys(currentState['7']).forEach(function (cid) {
        var row = currentState['7'][cid];
        var name = '';
        try {
          name = typeof ceExtractCharacterNameFromRow === 'function'
            ? ceExtractCharacterNameFromRow(row)
            : String((row && row['1']) || '').split('|')[0];
        } catch (_) {}
        pushCand(cid, name);
      });
    }
  } catch (_) {}

  /* 候选来源三：原著人物名单（年表/设定集里出现过的人）。
   *
   * ★★ 2026-11-01 玩家截图报错：「补演提交：离场物品角色档案不存在：C_HanLi」
   *
   * 上面两个来源只查「存档里已建档的人」。可开局时一个人都没建档，
   * candidates 为空 → 直接 return id → C_HanLi 原样传给下游 → 报错整轮作废。
   *
   * 但 C_HanLi 指向的「韩立」在原著里明明白白存在，只是玩家还没遇到过、
   * 所以还没建档。这种情况不该让整轮补演失败。
   *
   * 这里补上第三个来源：从原著年表/设定集的人物名里认人。
   * 认出来之后交给下游按「尚无档案」处理（跳过该条，不硬塞 id）。
   */
  try {
    if (typeof ceBridgeCanonSearchScope === 'function' || typeof currentTimelineEntries === 'function') {
      var canonNames = [];
      try {
        var scope = typeof ceBridgeCanonSearchScope === 'function'
          ? ceBridgeCanonSearchScope(typeof currentTimelineEntries === 'function' ? currentTimelineEntries() : [], [])
          : null;
        canonNames = (scope && scope.allowlist) || [];
      } catch (_) {}
      // 年表里出现的人物名也算原著人物
      try {
        var entries = typeof currentTimelineEntries === 'function' ? currentTimelineEntries() : [];
        (Array.isArray(entries) ? entries : []).forEach(function (entry) {
          var names = typeof collectTitleNames === 'function' ? collectTitleNames([entry]) : [];
          (names || []).forEach(function (name) { canonNames.push(name); });
        });
      } catch (_) {}
      var seenName = {};
      canonNames.forEach(function (name) {
        var sname = String(name || '').trim();
        if (!sname || seenName[sname]) return;
        seenName[sname] = true;
        // 用 'canon:' 前缀标记「原著里有人，但存档没有档案」
        candidates.push({ id: 'canon:' + sname, name: sname, unarchived: true });
      });
    }
  } catch (_) {}

  if (!candidates.length) return id;

  var clueLower = clue.toLowerCase();
  var clueNoSep = clueLower.replace(/[_\-]/g, '');

  // 匹配优先级：
  //   1. 名字完全等于线索
  //   2. 线索是名字的拼音/英文形态（HanLi vs 韩立 —— 用长度+子串兜底）
  //   3. 名字包含线索，或线索包含名字
  var exact = candidates.filter(function (c) { return c.name === clue; });
  if (exact.length === 1) return exact[0].id;
  if (exact.length > 1) return exact[0].id; // 同名多人取第一个，至少不报错

  var nameLower = candidates.map(function (c) {
    return { id: c.id, name: c.name, lower: c.name.toLowerCase(), noSep: c.name.toLowerCase().replace(/[_\-]/g, '') };
  });

  var byNoSep = nameLower.filter(function (c) { return c.noSep === clueNoSep || c.lower === clueLower; });
  if (byNoSep.length) return byNoSep[0].id;

  var byContains = nameLower.filter(function (c) {
    return c.lower.indexOf(clueLower) >= 0 || clueLower.indexOf(c.lower) >= 0;
  });
  if (byContains.length === 1) return byContains[0].id;
  if (byContains.length > 1) {
    // 多个都包含，取名字最长的那个（信息量最大）
    byContains.sort(function (a, b) { return b.name.length - a.name.length; });
    return byContains[0].id;
  }

  return id;
}
// @CUSTOM-END

function ceResolveCharacterName(id, preferredName) {
  var safeId = id ? String(id).trim() : '';
  var safePreferredName = ceSanitizeCharacterName(preferredName);
  if (safePreferredName) return safePreferredName;
  if (!safeId) return '';

  if (typeof window !== 'undefined' && window._concurrentEvolutionProcessedNames && typeof window._concurrentEvolutionProcessedNames.get === 'function') {
    var cachedName = ceSanitizeCharacterName(window._concurrentEvolutionProcessedNames.get(safeId));
    if (cachedName) return cachedName;
  }

  if (currentState && currentState['0'] && currentState['0'][safeId]) {
    var currentRow = currentState['0'][safeId];
    var currentName = ceExtractCharacterNameFromRow(currentRow);
    if (currentName) return currentName;
  }

  if (currentState && currentState['7'] && currentState['7'][safeId]) {
    var beastRow = currentState['7'][safeId];
    var beastName = ceExtractCharacterNameFromRow(beastRow);
    if (beastName) return beastName;
  }

  if (typeof getItemManagementCharacterRow === 'function') {
    var fallbackRow = getItemManagementCharacterRow(safeId);
    if (fallbackRow) {
      var fallbackName = ceExtractCharacterNameFromRow(fallbackRow);
      if (fallbackName) return fallbackName;
    }
  }

  var archiveRef = typeof getCurrentArchiveRef === 'function' ? getCurrentArchiveRef() : null;
  if (archiveRef) {
    if (typeof ceCollectWorldBookEntriesFromSources === 'function') {
      try {
        var mergedEntries = ceCollectWorldBookEntriesFromSources(archiveRef);
        var mergedName = ceFindCharacterNameInWorldBookEntries(safeId, mergedEntries);
        if (mergedName) return mergedName;
      } catch (e) {}
    }

    if (typeof ceGetLatestBiographySnapshot === 'function') {
      var snapshotEntries = ceGetLatestBiographySnapshot(archiveRef);
      var snapshotName = ceFindCharacterNameInWorldBookEntries(safeId, snapshotEntries);
      if (snapshotName) return snapshotName;
    }

    var archiveEntries = archiveRef && archiveRef.data && archiveRef.data.state
      ? archiveRef.data.state.worldBookEntries
      : null;
    var archiveName = ceFindCharacterNameInWorldBookEntries(safeId, archiveEntries);
    if (archiveName) return archiveName;
  }

  var globalEntries = typeof cePickWorldBookEntriesFromGlobals === 'function'
    ? cePickWorldBookEntriesFromGlobals()
    : [];
  var globalName = ceFindCharacterNameInWorldBookEntries(safeId, globalEntries);
  if (globalName) return globalName;

  if (typeof getNpcDataForQuickChat === 'function') {
    var npcInfo = getNpcDataForQuickChat(safeId);
    var npcName = ceSanitizeCharacterName(npcInfo && npcInfo.name);
    if (npcName && npcName !== '未知') return npcName;
  }

  if (typeof resolveCharName === 'function') {
    var resolvedName = ceSanitizeCharacterName(resolveCharName(safeId));
    if (resolvedName && resolvedName !== safeId && resolvedName !== '未知') return resolvedName;
  }

  return '';
}

function ceFormatCharacterLabel(id, preferredName) {
  var safeId = id ? String(id).trim() : '';
  var safeName = ceResolveCharacterName(safeId, preferredName);
  if (safeName && safeId && safeName !== safeId) {
    return safeName + '（' + safeId + '）';
  }
  return safeName || safeId || '未知角色';
}

function ceRenderOffscreenTagCalibrationCandidateItems(items, options = {}) {
  const list = Array.isArray(items) ? items : [];
  if (list.length === 0) return '';

  const badgeLabel = String(options.badgeLabel || '送校');
  const badgeClass = String(options.badgeClass || 'ce-badge-reentry');
  const resultPrefix = String(options.resultPrefix || '结果');
  let html = '';

  list.forEach(function(item) {
    if (!item || !item.id) return;

    const label = ceFormatCharacterLabel(item.id, item.name);
    const detailParts = [];
    if (Number.isFinite(item.priority)) {
      detailParts.push('优先级 ' + item.priority);
    }
    if (Array.isArray(item.reasons) && item.reasons.length > 0) {
      detailParts.push(item.reasons.join('；'));
    }

    const provisional = item.provisional && typeof item.provisional === 'object'
      ? item.provisional
      : null;
    if (provisional) {
      const provisionalText = [
        ceTranslateOffscreenTagValue('narrativeRole', provisional.narrativeRole),
        ceTranslateOffscreenTagValue('arcStatus', provisional.arcStatus),
        ceTranslateOffscreenTagValue('relationLevel', provisional.relationLevel),
        ceTranslateOffscreenTagValue('plotLevel', provisional.plotLevel)
      ].join(' / ');
      detailParts.push('预估标签：' + provisionalText);
      if (provisional.freezeReason) {
        detailParts.push('冻结依据：' + provisional.freezeReason);
      }
    }

    const sourceText = item.resultLabel || ceTranslateOffscreenTagSource(item.resultSource, item.needsModelReview === true);
    if (sourceText) {
      detailParts.push(resultPrefix + '：' + sourceText);
    }
    if (item.resultError) {
      detailParts.push('说明：' + item.resultError);
    }

    html += '<div class="ce-entry-item" style="align-items:flex-start">'
      + '<span class="ce-entry-badge ' + badgeClass + '">' + ceEscapeHtml(badgeLabel) + '</span>'
      + '<span style="font-weight:600">' + ceEscapeHtml(label) + '</span>'
      + (detailParts.length > 0
        ? '<span style="max-width:100%;word-break:break-all;opacity:0.75;font-size:12px">' + ceEscapeHtml(detailParts.join(' ｜ ')) + '</span>'
        : '')
      + '</div>';
  });

  return html;
}

function ceBuildOffscreenTagCalibrationPlayerFragments(provisional) {
  const normalized = provisional && typeof provisional === 'object' ? provisional : {};
  const parts = [];

  const role = String(normalized.narrativeRole || '').trim().toLowerCase();
  if (role === 'bond_core') parts.push('更像与你命运紧连的关键人物');
  else if (role === 'plot_core') parts.push('更像当前主线里的关键人物');
  else if (role === 'important') parts.push('更像近期值得留意的重要人物');
  else if (role === 'normal') parts.push('更像会反复出现的常规人物');
  else if (role === 'transient') parts.push('更像一段剧情里的过场人物');
  else if (role === 'tool') parts.push('更像推动情节的功能型人物');

  const arcStatus = String(normalized.arcStatus || '').trim().toLowerCase();
  if (arcStatus === 'open') parts.push('这条故事线仍在继续');
  else if (arcStatus === 'idle') parts.push('最近暂时没有新的波澜');
  else if (arcStatus === 'wrapped') parts.push('这条故事线已接近收束');
  else if (arcStatus === 'finished') parts.push('这条故事线目前已经走完');
  else if (arcStatus === 'closed') parts.push('这条故事线目前处于封存状态');

  const relationLevel = String(normalized.relationLevel || '').trim().toLowerCase();
  if (relationLevel === 'life_bound') parts.push('与你的牵连极深');
  else if (relationLevel === 'core') parts.push('与你仍有强关联');
  else if (relationLevel === 'close') parts.push('与你关系密切');
  else if (relationLevel === 'linked') parts.push('与你还保持联系');
  else if (relationLevel === 'distant') parts.push('与你的联系已较远');

  const plotLevel = String(normalized.plotLevel || '').trim().toLowerCase();
  if (plotLevel === 'high') parts.push('近期戏份热度较高');
  else if (plotLevel === 'normal') parts.push('近期仍有一定存在感');
  else if (plotLevel === 'low') parts.push('近期戏份较弱');

  return parts;
}

function ceBuildOffscreenTagCalibrationPlayerText(item, options = {}) {
  const provisional = item && item.provisional && typeof item.provisional === 'object'
    ? item.provisional
    : null;
  const resultLabel = String(item && item.resultLabel || '').trim();
  const resultError = String(item && item.resultError || '').trim();
  const fragments = [];

  if (resultLabel === '冻结跳过') {
    const freezeReason = provisional && provisional.freezeReason
      ? String(provisional.freezeReason).trim()
      : '当前剧情已经收束';
    fragments.push('当前因' + freezeReason + '，这一轮暂不推进后台后续');
  } else if (resultLabel === '超过单轮上限，延后到后续轮次') {
    fragments.push('这一轮先记入后续补看名单');
  } else if (resultLabel === '本地判定') {
    fragments.push('这一轮先按现有剧情整理其后台状态');
  } else if (resultLabel === '模型校准') {
    fragments.push('这一轮已重新梳理其后台动向');
  } else if (resultLabel === '异常兜底') {
    fragments.push('这一轮先按已有线索补齐其后台状态');
  } else if (resultLabel) {
    fragments.push(resultLabel);
  }

  if (provisional) {
    const playerFragments = ceBuildOffscreenTagCalibrationPlayerFragments(provisional);
    if (playerFragments.length > 0) {
      fragments.push(playerFragments.join('，'));
    }
  }

  if (resultError) {
    const clippedError = typeof ceClipOriginalTimelinePlayerText === 'function'
      ? ceClipOriginalTimelinePlayerText(resultError, 60)
      : resultError;
    fragments.push(clippedError);
  }

  return fragments.filter(Boolean).join('；');
}

function ceRenderOffscreenTagCalibrationTextDetail(title, content) {
  const text = String(content || '').trim();
  if (!text) return '';
  return '<details style="margin-top:6px">'
    + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">' + ceEscapeHtml(title) + '</summary>'
    + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
    + ceEscapeHtml(text)
    + '</pre></details>';
}

function ceRenderOffscreenTagCalibrationBatchItems(batches) {
  const list = Array.isArray(batches) ? batches : [];
  if (list.length === 0) return '';

  let html = '';
  list.forEach(function(batch, index) {
    if (!batch || typeof batch !== 'object') return;

    const summaryParts = ['第' + (index + 1) + '批'];
    if (Array.isArray(batch.ids) && batch.ids.length > 0) {
      summaryParts.push(batch.ids.join('、'));
    }
    if (typeof batch.modelResolvedCount === 'number') {
      summaryParts.push('模型写回 ' + batch.modelResolvedCount);
    }
    if (typeof batch.fallbackCount === 'number') {
      summaryParts.push('兜底 ' + batch.fallbackCount);
    }
    if (batch.error) {
      summaryParts.push('异常：' + batch.error);
    }

    html += '<div class="ce-entry-item" style="align-items:flex-start">'
      + '<span class="ce-entry-badge ce-badge-reentry">批次</span>'
      + '<span style="max-width:100%;word-break:break-all">' + ceEscapeHtml(summaryParts.join(' ｜ ')) + '</span>'
      + '</div>';

    if (Array.isArray(batch.modelResolved) && batch.modelResolved.length > 0) {
      html += ceRenderOffscreenTagCalibrationCandidateItems(batch.modelResolved, {
        badgeLabel: '模型写回',
        badgeClass: 'ce-badge-in',
        resultPrefix: '来源'
      });
    }
    if (Array.isArray(batch.fallbackResolved) && batch.fallbackResolved.length > 0) {
      html += ceRenderOffscreenTagCalibrationCandidateItems(batch.fallbackResolved, {
        badgeLabel: '兜底',
        badgeClass: 'ce-badge-out',
        resultPrefix: '来源'
      });
    }

    html += ceRenderOffscreenTagCalibrationTextDetail('送校Prompt', batch.requestPrompt || '');
    html += ceRenderOffscreenTagCalibrationTextDetail('送校Payload', batch.requestPayload || '');
    html += ceRenderOffscreenTagCalibrationTextDetail('模型推理过程', batch.thinking || '');
    html += ceRenderOffscreenTagCalibrationTextDetail('原始模型返回', batch.rawResponse || '');
  });

  return html;
}

function ceSetThinkingStageVisibility(patch = null) {
  if (typeof window === 'undefined') return null;
  if (!patch || typeof patch !== 'object') {
    window._ceThinkingStageVisibility = null;
    return null;
  }
  const previous = window._ceThinkingStageVisibility && typeof window._ceThinkingStageVisibility === 'object'
    ? window._ceThinkingStageVisibility
    : {};
  const next = Object.assign({}, previous, patch);
  window._ceThinkingStageVisibility = next;
  return next;
}

function ceCanRenderOrdinaryThinkingSection() {
  if (typeof window === 'undefined') return true;
  const state = window._ceThinkingStageVisibility;
  if (!state || state.active !== true) return true;
  return state.ordinaryCompleted === true;
}

function ceCanRenderOriginalTimelineThinkingSection() {
  if (typeof window === 'undefined') return true;
  const state = window._ceThinkingStageVisibility;
  if (!state || state.active !== true) return true;
  return state.originalTimelineCompleted === true;
}

// ===== Thinking内容渲染到变量思维tab =====
function ceRenderThinkingToStreamTab(thinkingResults, entryDecisionResult, viewOptions = {}) {
  const el = viewOptions.container || document.getElementById('thinking-stream-content');
  if (!el) return;

  thinkingResults = Array.isArray(thinkingResults) ? thinkingResults : [];
  if (!viewOptions.container && typeof window !== 'undefined') {
    window._ceLastThinkingResults = thinkingResults.map(function(item) {
      return item && typeof item === 'object' ? Object.assign({}, item) : item;
    });
  }

  const htmlParts = [];
  const view = viewOptions.snapshot || window;
  const canRenderOrdinarySections = viewOptions.container ? true : ceCanRenderOrdinaryThinkingSection();
  const canRenderOriginalTimelineSection = viewOptions.container ? false : ceCanRenderOriginalTimelineThinkingSection();
  const resolveEntryDecisionDisplayName = function(id, fallbackName) {
    var rawId = String(id || '').trim();
    var rawFallback = String(fallbackName || '').trim();
    if (!rawId) return rawFallback || '未知角色';
    if(viewOptions.container)return view.names?.[rawId]||thinkingResults.find(function(r){return r.id===rawId;})?.name||rawFallback||rawId;
    if (rawFallback && rawFallback !== rawId) return rawFallback;

    var resolvedName = '';
    if (typeof ceResolveCharacterName === 'function') {
      try {
        resolvedName = String(ceResolveCharacterName(rawId, rawFallback) || '').trim();
        if (resolvedName === rawId) resolvedName = '';
      } catch (e) {}
    }

    if (!resolvedName) {
      try {
        var thinkingHit = thinkingResults.find(function(item) {
          return item && String(item.id || '') === rawId && item.name;
        });
        if (thinkingHit && thinkingHit.name) {
          resolvedName = String(thinkingHit.name || '').trim();
        }
      } catch (e) {}
    }

    if (!resolvedName && window._concurrentEvolutionProcessedNames instanceof Map) {
      resolvedName = String(window._concurrentEvolutionProcessedNames.get(rawId) || '').trim();
    }

    if (!resolvedName) {
      try {
        var row = currentState && currentState['0'] ? currentState['0'][rawId] : null;
        if (row) {
          resolvedName = ceStripHtmlTagsLite((row['1'] || '').split('|')[0] || rawId);
        }
      } catch (e) {}
    }

    if (!resolvedName) {
      try {
        var beastRow = currentState && currentState['7'] ? currentState['7'][rawId] : null;
        if (beastRow) {
          resolvedName = ceStripHtmlTagsLite((beastRow['1'] || '').split('|')[0] || rawId);
        }
      } catch (e) {}
    }

    return resolvedName || rawFallback || rawId || '未知角色';
  };
  const buildEntryDecisionStatusBadges = function(tags) {
    return (Array.isArray(tags) ? tags : []).map(function(tag) {
      if (!tag || !tag.label) return '';
      var className = tag.className ? (' ' + tag.className) : '';
      return '<span class="ce-entry-badge' + className + '">' + ceEscapeHtml(tag.label) + '</span>';
    }).join('');
  };
  const buildEntryDecisionTagClassName = function(label) {
    var normalizedLabel = String(label || '').trim();
    if (normalizedLabel === '退场') return 'ce-badge-out';
    if (normalizedLabel === '登场' || normalizedLabel === '在场') return 'ce-badge-in';
    return 'ce-badge-reentry';
  };
  const buildEntryDecisionTagList = function(labels) {
    var seen = new Set();
    return (Array.isArray(labels) ? labels : []).map(function(label) {
      return String(label || '').trim();
    }).filter(function(label) {
      if (!label || seen.has(label)) return false;
      seen.add(label);
      return true;
    }).map(function(label) {
      return {
        label: label,
        className: buildEntryDecisionTagClassName(label)
      };
    });
  };
  const buildEntryDecisionListHasId = function(list, targetId) {
    var normalizedId = String(targetId || '').trim();
    if (!normalizedId || !Array.isArray(list)) return false;
    return list.some(function(item) {
      if (typeof item === 'string') {
        return String(item || '').trim() === normalizedId;
      }
      return item && String(item.id || '').trim() === normalizedId;
    });
  };
  var entryDecisionEntries = [];
  var entryDecisionExits = [];
  var entryDecisionCeDeletions = [];
  const buildEntryDecisionDeedTags = function(id) {
    var normalizedId = String(id || '').trim();
    if (!normalizedId) return [];
    var labels = [];
    if (buildEntryDecisionListHasId(entryDecisionEntries, normalizedId)) labels.push('登场');
    if (buildEntryDecisionListHasId(entryDecisionExits, normalizedId) || buildEntryDecisionListHasId(entryDecisionCeDeletions, normalizedId)) labels.push('退场');
    var isOnscreen = false;
    try {
      isOnscreen = !!(
        (currentState && currentState['0'] && Object.prototype.hasOwnProperty.call(currentState['0'], normalizedId))
        || (currentState && currentState['7'] && Object.prototype.hasOwnProperty.call(currentState['7'], normalizedId))
      );
    } catch (e) {}
    if (isOnscreen) labels.push('在场');
    var focusIds = Array.isArray(entryDecisionResult && entryDecisionResult.focusCharacterIds)
      ? entryDecisionResult.focusCharacterIds
      : [];
    if (buildEntryDecisionListHasId(focusIds, normalizedId)) labels.push('重点关注');
    var backstageIds = Array.isArray(entryDecisionResult && entryDecisionResult.requiredDeedsTargetIds)
      ? entryDecisionResult.requiredDeedsTargetIds
      : [];
    if (!isOnscreen && buildEntryDecisionListHasId(backstageIds, normalizedId)) labels.push('幕后牵动');
    return buildEntryDecisionTagList(labels);
  };
  const buildEntryDecisionIdentityHtml = function(id, fallbackName, tags) {
    var displayId = String(id || '').trim();
    var displayName = resolveEntryDecisionDisplayName(displayId, fallbackName);
    var normalizedTags = Array.isArray(tags) ? tags.filter(Boolean) : [];
    if (typeof ceResolveImportantOriginalRoleName === 'function') {
      try {
        var originalCanonicalName = ceResolveImportantOriginalRoleName(displayId)
          || ceResolveImportantOriginalRoleName(displayName)
          || ceResolveImportantOriginalRoleName(fallbackName);
        if (originalCanonicalName && !normalizedTags.some(function(tag) { return tag && tag.label === '原著'; })) {
          normalizedTags.push({ label: '原著', className: 'ce-badge-reentry' });
        }
      } catch (e) {}
    }
    var idSuffix = displayId && displayName !== displayId
      ? '<span style="opacity:0.78">(' + ceEscapeHtml(displayId) + ')</span>'
      : '';
    return buildEntryDecisionStatusBadges(normalizedTags)
      + '<span style="font-weight:600">' + ceEscapeHtml(displayName) + '</span>'
      + idSuffix;
  };;

  var tagCalibrationResult = view.lastOffscreenTagCalibrationResult;
  if (canRenderOrdinarySections && tagCalibrationResult && typeof tagCalibrationResult === 'object') {
    var calibrationSummary = tagCalibrationResult.summary && typeof tagCalibrationResult.summary === 'object'
      ? tagCalibrationResult.summary
      : {};
    var calibrationSummaryParts = [];
    if (tagCalibrationResult.message) {
      calibrationSummaryParts.push(String(tagCalibrationResult.message));
    }
    calibrationSummaryParts.push('待处理 ' + (tagCalibrationResult.pendingCount || 0) + ' / 总候选 ' + (tagCalibrationResult.totalCandidateCount || 0));
    if (Number.isFinite(tagCalibrationResult.calibrationLimit)) {
      calibrationSummaryParts.push('单轮上限 ' + tagCalibrationResult.calibrationLimit);
    }
    if (tagCalibrationResult.modelEnabled !== false && Number.isFinite(tagCalibrationResult.batchSize) && tagCalibrationResult.batchSize > 0) {
      calibrationSummaryParts.push('单次请求 ' + tagCalibrationResult.batchSize);
    }
    if (typeof calibrationSummary.modelResolvedCount === 'number') {
      calibrationSummaryParts.push('模型写回 ' + calibrationSummary.modelResolvedCount);
    }
    if (typeof calibrationSummary.fallbackCount === 'number') {
      calibrationSummaryParts.push('兜底 ' + calibrationSummary.fallbackCount);
    }
    if (typeof calibrationSummary.localCount === 'number') {
      calibrationSummaryParts.push('本地直判 ' + calibrationSummary.localCount);
    }
    if (typeof calibrationSummary.deferredCount === 'number') {
      calibrationSummaryParts.push('延期 ' + calibrationSummary.deferredCount);
    }
    if (typeof calibrationSummary.skippedCount === 'number') {
      calibrationSummaryParts.push('冻结跳过 ' + calibrationSummary.skippedCount);
    }

    var calibrationItems = '<div class="ce-entry-item" style="opacity:0.65;font-size:12px">'
      + ceEscapeHtml(calibrationSummaryParts.join(' • '))
      + '</div>';

    if (tagCalibrationResult.modelEnabled === false) {
      calibrationItems += ceRenderOffscreenTagCalibrationCandidateItems(tagCalibrationResult.localResolved || [], {
        badgeLabel: '本地直判',
        badgeClass: 'ce-badge-reentry',
        resultPrefix: '来源'
      });
    } else {
      calibrationItems += ceRenderOffscreenTagCalibrationCandidateItems(tagCalibrationResult.selectedNow || [], {
        badgeLabel: '送校',
        badgeClass: 'ce-badge-reentry',
        resultPrefix: '结果'
      });
      if (Array.isArray(tagCalibrationResult.deferred) && tagCalibrationResult.deferred.length > 0) {
        calibrationItems += '<details style="margin-top:6px">'
          + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">延期 ' + tagCalibrationResult.deferred.length + ' 个</summary>'
          + '<div style="margin-top:4px">'
          + ceRenderOffscreenTagCalibrationCandidateItems(tagCalibrationResult.deferred, {
            badgeLabel: '延期',
            badgeClass: 'ce-badge-out',
            resultPrefix: '状态'
          })
          + '</div></details>';
      }
      if (Array.isArray(tagCalibrationResult.skippedFrozen) && tagCalibrationResult.skippedFrozen.length > 0) {
        calibrationItems += '<details style="margin-top:6px">'
          + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">跳过 ' + tagCalibrationResult.skippedFrozen.length + ' 个</summary>'
          + '<div style="margin-top:4px">'
          + ceRenderOffscreenTagCalibrationCandidateItems(tagCalibrationResult.skippedFrozen, {
            badgeLabel: '跳过',
            badgeClass: 'ce-badge-out',
            resultPrefix: '状态'
          })
          + '</div></details>';
      }
    }

    if (!calibrationItems) {
      calibrationItems = '<div class="ce-entry-item" style="opacity:0.5">本轮无标签校准信息</div>';
    }

    var calibrationRulesHtml = '';
    var calibrationRules = Array.isArray(tagCalibrationResult.ruleSummary)
      ? tagCalibrationResult.ruleSummary
      : [];
    if (calibrationRules.length > 0) {
      calibrationRulesHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">优先送校规则</summary>'
        + '<div style="margin-top:4px">'
        + calibrationRules.map(function(rule) {
          return '<div class="ce-entry-item" style="opacity:0.75;font-size:12px">' + ceEscapeHtml(rule) + '</div>';
        }).join('')
        + '</div></details>';
    }

    var calibrationBatchHtml = '';
    if (Array.isArray(tagCalibrationResult.batchResults) && tagCalibrationResult.batchResults.length > 0) {
      calibrationBatchHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">批次结果</summary>'
        + '<div style="margin-top:4px">'
        + ceRenderOffscreenTagCalibrationBatchItems(tagCalibrationResult.batchResults)
        + '</div></details>';
    }

    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-entry-decision">'
      + '<div class="ce-thinking-section-header">标签校准</div>'
      + '<div class="ce-thinking-section-body">' + calibrationItems + calibrationRulesHtml + calibrationBatchHtml + '</div>'
      + '</div>'
    );
  }

  // 1. 登场/退场区域
  // 注意：只有在登场判断真正执行并把结果写入 lastEntryDecisionResult 后，
  // 才允许渲染这一块；否则早期 UI 刷新会错误显示“无登场人物变化”。
  const hasEntryDecisionSnapshot = !!(entryDecisionResult && typeof entryDecisionResult === 'object' && (
    Object.prototype.hasOwnProperty.call(entryDecisionResult, 'timestamp')
    || Object.prototype.hasOwnProperty.call(entryDecisionResult, 'noEntry')
    || Object.prototype.hasOwnProperty.call(entryDecisionResult, 'noExit')
    || Array.isArray(entryDecisionResult.entries)
    || Array.isArray(entryDecisionResult.exits)
    || entryDecisionResult.globalResult
    || (entryDecisionResult.deedsUpdates && typeof entryDecisionResult.deedsUpdates === 'object')
  ));
  if (canRenderOrdinarySections && hasEntryDecisionSnapshot) {
    const entries = entryDecisionResult?.entries || [];
    const exits = entryDecisionResult?.exits || [];
    entryDecisionEntries = entries;
    entryDecisionExits = exits;
    const deedsUpdates = (entryDecisionResult && entryDecisionResult.deedsUpdates && typeof entryDecisionResult.deedsUpdates === 'object')
      ? entryDecisionResult.deedsUpdates
      : {};
    const deedsUpdateIds = Object.keys(deedsUpdates);
    const deedsUpdatesApplied = (entryDecisionResult && entryDecisionResult.deedsUpdatesApplied instanceof Set)
      ? entryDecisionResult.deedsUpdatesApplied
      : null;
    const entryParseFailures = entryDecisionResult?.entryParseFailures || [];
    const entryParseFailureSet = new Set(entryParseFailures.map(function(e) { return e.id; }));

    // 收集并发演化中产生的 de 离场（去除已在 exits 中的）
    const exitIds = new Set(exits.map(function(e) { return e.id; }));
    const ceDeletions = [];
    if (!viewOptions.container && window._concurrentEvolutionDeletedIds && window._concurrentEvolutionDeletedIds.size > 0) {
      window._concurrentEvolutionDeletedIds.forEach(function(id) {
        if (!exitIds.has(id)) {
          var name = '';
          var found = thinkingResults.find(function(t) { return t.id === id; });
          if (found) name = found.name;
          else if (window._concurrentEvolutionProcessedNames) name = window._concurrentEvolutionProcessedNames.get(id) || '';
          ceDeletions.push({ id: id, name: name || id });
        }
      });
    }
    entryDecisionCeDeletions = ceDeletions;

    var entryItems = '';
    if (entries.length > 0 || exits.length > 0 || ceDeletions.length > 0 || deedsUpdateIds.length > 0) {
      entries.forEach(function(e) {
        var entryTypeLabel = '\u767b\u573a';
        var badgeClass = 'ce-badge-in';
        if (e.type === 'new') {
          entryTypeLabel = '\u65b0\u767b\u573a';
        } else if (e.type === 'reentry') {
          entryTypeLabel = '\u91cd\u65b0\u8fd4\u573a';
          badgeClass = 'ce-badge-reentry';
        }
        var identityHtml = buildEntryDecisionIdentityHtml(e.id, e.name, buildEntryDecisionTagList(['登场', '在场']));
        entryItems += '<div class="ce-entry-item">'
          + identityHtml
          + '<span style="opacity:0.7;font-size:12px">' + ceEscapeHtml(e.reason || '(\u65e0\u539f\u56e0)') + '</span>';
        if (entryParseFailureSet.has(e.id)) {
          entryItems += '<span style="opacity:0.6;font-size:12px;margin-left:6px">\u6307\u4ee4\u89e3\u6790\u5931\u8d25\uff0c\u6570\u636e\u672a\u5199\u5165</span>';
        }
        entryItems += '</div>';
      });
      exits.forEach(function(e) {
        var identityHtml = buildEntryDecisionIdentityHtml(e.id, e.name, buildEntryDecisionTagList(['退场']));
        entryItems += '<div class="ce-entry-item">'
          + identityHtml
          + '<span style="opacity:0.7;font-size:12px">' + ceEscapeHtml(e.reason || '(\u65e0\u539f\u56e0)') + '</span>'
          + '<span style="opacity:0.5;font-size:11px;margin-left:4px">[\u767b\u573a\u5224\u5b9a]</span>'
          + '</div>';
      });
      ceDeletions.forEach(function(e) {
        var deletionLabel = ceFormatCharacterLabel(e.id, e.name);
        entryItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-out">\u9000\u573a</span>'
          + '<span style="font-weight:600">' + ceEscapeHtml(deletionLabel) + '</span>'
          + '<span style="opacity:0.5;font-size:11px;margin-left:4px">[\u91cd\u70b9\u6f14\u5316]</span>'
          + '</div>';
      });
      deedsUpdateIds.forEach(function(id) {
        var deedText = typeof deedsUpdates[id] === 'string' ? deedsUpdates[id] : String(deedsUpdates[id] || '');
        var deedHtml = ceEscapeHtml(deedText).replace(/\n/g, '<br>');
        var applied = deedsUpdatesApplied ? deedsUpdatesApplied.has(id) : true;
        var appliedText = applied ? '[\u5df2\u5199\u5165]' : '[\u5199\u5165\u5931\u8d25]';
        var appliedStyle = applied ? 'opacity:0.5' : 'opacity:0.75;color:#ef9a9a';
        var identityHtml = buildEntryDecisionIdentityHtml(id, '', buildEntryDecisionDeedTags(id));
        entryItems += '<div class="ce-entry-item" style="align-items:flex-start">'
          + identityHtml
          + '<span style="max-width:100%;word-break:break-all">' + deedHtml + '</span>'
          + '<span style="font-size:11px;' + appliedStyle + ';margin-left:4px">' + appliedText + '</span>'
          + '</div>';
      });
    } else {
      entryItems = '<div class="ce-entry-item" style="opacity:0.5">\u65e0\u767b\u573a\u4eba\u7269\u53d8\u5316</div>';
    }

    var globals = entryDecisionResult && entryDecisionResult.globalResult;
    if (globals) {
      var worldState = entryDecisionResult.worldState;
      var globalText = entryDecisionResult.error || (globals.appliedCount > 0 ? ((worldState && worldState.fullText) || '已更新 ' + globals.appliedCount + ' 条全局变量') : '本轮无时间地点指令');
      entryItems += '<div class="ce-entry-item" style="align-items:flex-start"><span class="ce-tag" style="color:' + (entryDecisionResult.error ? '#ef9a9a' : '#81c784') + '">时间 / 地点</span><span>' + ceEscapeHtml(globalText) + '</span></div>';
    }

    // 登场判断模型推理过程（可折叠）
    var entryThinkingHtml = '';
    var entryThinking = entryDecisionResult?.thinking || '';
    if (entryThinking) {
      entryThinkingHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">\u6A21\u578B\u63A8\u7406\u8FC7\u7A0B</summary>'
        + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
        + ceEscapeHtml(entryThinking)
        + '</pre></details>';
    }

    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-entry-decision">'
      + '<div class="ce-thinking-section-header">\u767b\u573a\u5224\u65ad</div>'
      + '<div class="ce-thinking-section-body">' + entryItems + entryThinkingHtml + '</div>'
      + '</div>'
    );
  }

  // 1.5 物品管理阶段（紧随登场判断）
  var itemManagementResult = view.lastItemManagementResult;
  if (canRenderOrdinarySections && itemManagementResult) {
    var itemManagementHtml = ceRenderItemManagementResultHtml(itemManagementResult, {
      characterLabelResolver: function(id) {
        return viewOptions.container?resolveEntryDecisionDisplayName(id,''):ceFormatCharacterLabel(id);
      },
      emptyText: itemManagementResult.noOperations
        ? '本轮无物品/灵石操作'
        : '无物品管理结果',
      thinkingTitle: '模型推理过程'
    });
    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-item-management">'
      + '<div class="ce-thinking-section-header">\u7269\u54c1\u7ba1\u7406</div>'
      + '<div class="ce-thinking-section-body">' + itemManagementHtml + '</div>'
      + '</div>'
    );
  }

  // 1.6 杂项演化阶段（总结/任务/地图/世界事件）
  var miscEvolutionResult = view.lastMiscEvolutionResult;
  if (canRenderOrdinarySections && miscEvolutionResult) {
    var miscItems = '';
    var requestedDelta = Array.isArray(miscEvolutionResult.requestedDelta)
      ? miscEvolutionResult.requestedDelta
      : [];
    var miscBlocked = Array.isArray(miscEvolutionResult.blockedOps)
      ? miscEvolutionResult.blockedOps
      : [];
    var miscCommandsString = typeof miscEvolutionResult.commandsString === 'string'
      ? miscEvolutionResult.commandsString
      : '';
    var stringifyBrief = function(value, maxLen) {
      var limit = typeof maxLen === 'number' ? maxLen : 220;
      try {
        var txt = JSON.stringify(value);
        if (txt.length > limit) return txt.slice(0, limit) + ' ...';
        return txt;
      } catch (e) {
        return '';
      }
    };

    if (miscEvolutionResult.error) {
      miscItems += '<div class="ce-entry-item">'
        + '<span class="ce-entry-badge ce-badge-out">失败</span>'
        + '<span>' + ceEscapeHtml(miscEvolutionResult.error) + '</span>'
        + '</div>';
    } else if (requestedDelta.length === 0 && !miscEvolutionResult.smallSummary && !miscEvolutionResult.largeSummary) {
      miscItems += '<div class="ce-entry-item" style="opacity:0.5">本轮无杂项变更</div>';
    } else {
      requestedDelta.forEach(function(op) {
        var cmd = op?.command || 'op';
        var badge = '指令';
        var headline = cmd;
        var detail = '';
        if (cmd === 'add') {
          var addId = op.id || '?';
          headline = addId;
          if (addId === 'TIME_LOCATION_ROW') {
            badge = '时间地点';
            detail = (op && op.data && op.data['0']) ? String(op.data['0']) : '更新时间地点行';
          } else if (addId === 'SCENE_MAP') {
            badge = '小地图';
            var mapData = ceParseSceneMapConfig(op?.data?.['1']);
            var mapDetails = [];
            if (Array.isArray(mapData?.terrain)) mapDetails.push('地形 ' + mapData.terrain.length + ' 行');
            if (Array.isArray(mapData?.terrain_patches)) mapDetails.push('地形修订 ' + mapData.terrain_patches.length + ' 项');
            if (Array.isArray(mapData?.elements)) mapDetails.push('场景要素 ' + mapData.elements.length + ' 项');
            detail = mapDetails.join(' · ') || '场景地图更新';
          } else if (ceIsMiscTaskId(addId)) {
            badge = '任务更新';
            var addCols = op && op.data && typeof op.data === 'object' ? Object.keys(op.data) : [];
            detail = addCols.length > 0 ? ('更新列: ' + addCols.join(', ')) : '任务字段更新';
          } else {
            detail = stringifyBrief(op && op.data, 180);
          }
        } else if (cmd === 'set') {
          var setId = (op && op.data && op.data['0']) || '?';
          headline = setId;
          if (ceIsMiscTaskId(setId)) {
            badge = '任务创建';
            var taskName = op && op.data ? (op.data['1'] || '') : '';
            var taskState = op && op.data ? (op.data['5'] || '') : '';
            detail = (taskName ? ('名称: ' + taskName + ' ') : '') + (taskState ? ('状态: ' + taskState) : '');
          } else {
            badge = 'set';
            detail = stringifyBrief(op && op.data, 180);
          }
        } else if (cmd === 'de') {
          badge = '任务删除';
          headline = op.id || '?';
          detail = '删除任务';
        } else if (cmd === 'addWorldEvent' || cmd === 'updateWorldEvent' || cmd === 'deleteWorldEvent') {
          badge = '世界大事';
          headline = cmd;
          detail = stringifyBrief(op, 220);
        } else if (cmd === 'createLocation' || cmd === 'updateRegion' || cmd === 'deleteLocation') {
          badge = '地图结构';
          headline = cmd;
          detail = stringifyBrief(op, 220);
        } else {
          badge = cmd;
          headline = cmd;
          detail = stringifyBrief(op, 180);
        }
        miscItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-reentry">' + ceEscapeHtml(badge) + '</span>'
          + '<span>' + ceEscapeHtml(headline) + '</span>'
          + (detail ? '<span style="opacity:0.75;font-size:12px;white-space:pre-wrap;word-break:break-all">' + ceEscapeHtml(detail) + '</span>' : '')
          + '</div>';
      });
      if (miscEvolutionResult.smallSummary) {
        miscItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-in">小总结</span>'
          + '<span style="white-space:pre-wrap;word-break:break-all">' + ceEscapeHtml(miscEvolutionResult.smallSummary) + '</span>'
          + '</div>';
      }
      if (miscEvolutionResult.largeSummary) {
        miscItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-in">大总结</span>'
          + '<span style="white-space:pre-wrap;word-break:break-all">' + ceEscapeHtml(miscEvolutionResult.largeSummary) + '</span>'
          + '</div>';
      }
    }

    if (miscBlocked.length > 0) {
      miscItems += '<div class="ce-entry-item" style="opacity:0.65">'
        + '<span class="ce-entry-badge ce-badge-out">过滤</span>'
        + '<span>已过滤超范围指令 ' + miscBlocked.length + ' 条</span>'
        + '</div>';
    }

    var miscSummaryLine = '<div class="ce-entry-item" style="opacity:0.65;font-size:12px">'
      + '应用结果: '
      + (miscEvolutionResult.committed === true ? (miscEvolutionResult.noOperations ? '无需变更' : '已保存' + (miscEvolutionResult.stateChanged === false ? '（状态无新增变化）' : '')) : typeof miscEvolutionResult.appliedCount === 'number' ? ('应用 ' + miscEvolutionResult.appliedCount + ' 条') : '未应用')
      + (miscEvolutionResult.skipped ? ' • 已跳过' : '')
      + '</div>';

    var miscThinkingHtml = '';
    var miscThinking = miscEvolutionResult.thinking || '';
    if (miscThinking) {
      miscThinkingHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">模型推理过程</summary>'
        + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
        + ceEscapeHtml(miscThinking)
        + '</pre></details>';
    }
    var miscRawHtml = '';
    if (miscCommandsString) {
      miscRawHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">原始upstore输出</summary>'
        + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
        + ceEscapeHtml(miscCommandsString)
        + '</pre></details>';
    }

    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-item-management">'
      + '<div class="ce-thinking-section-header">杂项演化</div>'
      + '<div class="ce-thinking-section-body">' + miscSummaryLine + miscItems + miscThinkingHtml + miscRawHtml + '</div>'
      + '</div>'
    );
  }

  // 1.7 生图演化阶段
  var imageEvolutionResult = view.lastImageEvolutionResult;
  if (canRenderOrdinarySections && imageEvolutionResult && !imageEvolutionResult.skipped) {
    var imageItems = '';

    if (imageEvolutionResult.error) {
      imageItems += '<div class="ce-entry-item">'
        + '<span class="ce-entry-badge ce-badge-out">\u5931\u8d25</span>'
        + '<span>' + ceEscapeHtml(imageEvolutionResult.error) + '</span>'
        + '</div>';
    } else {
      // 列19数据
      var col19Data = Array.isArray(imageEvolutionResult.col19Data) ? imageEvolutionResult.col19Data : [];
      if (col19Data.length > 0) {
        col19Data.forEach(function(item) {
          imageItems += '<div class="ce-entry-item">'
            + '<span class="ce-entry-badge ce-badge-in">\u521719 ' + ceEscapeHtml(item.id) + '</span>'
            + '<span style="font-size:12px;white-space:pre-wrap;word-break:break-all">' + ceEscapeHtml(item.content) + '</span>'
            + '</div>';
        });
      }

      // 正文提示词
      var imagePrompts = Array.isArray(imageEvolutionResult.imagePrompts) ? imageEvolutionResult.imagePrompts : [];
      if (imagePrompts.length > 0) {
        imagePrompts.forEach(function(img, idx) {
          var anchorText = img.anchor ? ('\u951A\u70B9: ' + img.anchor) : '';
          var displayPrompt = img.prompt || '';
          imageItems += '<div class="ce-entry-item">'
            + '<span class="ce-entry-badge ce-badge-reentry">\u56FE' + (idx + 1) + '</span>'
            + '<span style="font-size:12px;white-space:pre-wrap;word-break:break-all">'
            + (anchorText ? (ceEscapeHtml(anchorText) + '<br>') : '')
            + ceEscapeHtml(displayPrompt)
            + '</span></div>';
        });
      }

      if (col19Data.length === 0 && imagePrompts.length === 0) {
        imageItems = '<div class="ce-entry-item" style="opacity:0.5">\u672c\u8f6e\u65e0\u751f\u56fe\u7ed3\u679c</div>';
      }
    }

    var imageThinkingHtml = '';
    var imageThinking = imageEvolutionResult.thinking || '';
    if (imageThinking) {
      imageThinkingHtml = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">\u6A21\u578B\u63A8\u7406\u8FC7\u7A0B</summary>'
        + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
        + ceEscapeHtml(imageThinking)
        + '</pre></details>';
    }

    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-item-management">'
      + '<div class="ce-thinking-section-header">\u751F\u56FE\u6F14\u5316</div>'
      + '<div class="ce-thinking-section-body">' + imageItems + imageThinkingHtml + '</div>'
      + '</div>'
    );
  }

  var originalTimelineEvolutionHtml = canRenderOriginalTimelineSection ? ceRenderOriginalTimelineLedgerThinkingSection(window.lastOriginalTimelineEvolutionResult) : '';
  if (canRenderOriginalTimelineSection && window.lastOriginalTimelineEvolutionResult?.linkageEnabled === true && originalTimelineEvolutionHtml) {
    htmlParts.push(originalTimelineEvolutionHtml);
  }

  // 2. 按ID排序: B1最前，然后按字母数字排序
  const sorted = [...thinkingResults].sort((a, b) => {
    if (a.id === 'B1') return -1;
    if (b.id === 'B1') return 1;
    return a.id.localeCompare(b.id, undefined, { numeric: true });
  });

  // 3. 渲染每个角色的thinking内容与结果
  if (canRenderOrdinarySections) {
    sorted.forEach(function(item) {
    var typeLabel = ceGetTypeLabel(item.type);
    var typeBadge = typeLabel
      ? ' <span class="ce-thinking-type-badge">' + ceEscapeHtml(typeLabel) + '</span>'
      : '';

    var resultItems = '';
    var commandEntries = [];
    var parseFailures = [];

    if (item.commandsString) {
      var commandText = String(item.commandsString);
      var cmdRegex = /([a-zA-Z_]+)\s*\(/g;
      var cmdMatch;
      while ((cmdMatch = cmdRegex.exec(commandText)) !== null) {
        var cmdName = cmdMatch[1];
        var cmdStart = cmdMatch.index + cmdMatch[0].length;
        var cmdEnd = findMatchingParen(commandText, cmdStart);
        if (cmdEnd === -1) {
          parseFailures.push({
            reason: '未找到匹配的右括号',
            raw: commandText.slice(cmdMatch.index).trim(),
            name: cmdName
          });
          break;
        }
        var cmdRaw = commandText.slice(cmdMatch.index, cmdEnd + 1).trim();
        var cmdArgs = commandText.slice(cmdStart, cmdEnd).trim();
        commandEntries.push({ name: cmdName, raw: cmdRaw, args: cmdArgs });
        cmdRegex.lastIndex = cmdEnd + 1;
      }
    }

    if (item.parseErrors && Array.isArray(item.parseErrors) && item.parseErrors.length > 0) {
      item.parseErrors.forEach(function(err) {
        var msg = err.details || err.title || '\u89e3\u6790\u9519\u8bef';
        resultItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-out">\u89e3\u6790\u5931\u8d25</span>'
          + '<span>' + ceEscapeHtml(msg) + '</span>'
          + '</div>';
      });
    }

    if (parseFailures.length > 0) {
      parseFailures.forEach(function(fail) {
        resultItems += '<div class="ce-entry-item">'
          + '<span class="ce-entry-badge ce-badge-out">\u89e3\u6790\u5931\u8d25</span>'
          + '<span>' + ceEscapeHtml((fail.name || '\u6307\u4ee4') + ': ' + (fail.reason || '\u683c\u5f0f\u9519\u8bef')) + '</span>'
          + (fail.raw ? '<span style="opacity:0.7;font-size:12px">' + ceEscapeHtml(fail.raw) + '</span>' : '')
          + '</div>';
      });
    }

    var columnNameMap = {
      '0': 'ID',
      '1': '\u540d\u79f0|\u6027\u522b',
      '2': '\u5883\u754c|\u8eab\u4efd',
      '3': '\u6027\u683c',
      '4': '\u5f53\u524d\u72b6\u6001/Buffs',
      '5': '\u7075\u6839',
      '6': '\u7279\u6b8a\u4f53\u8d28/\u5185\u5fc3\u60f3\u6cd5(\u7075\u517d)',
      '7': '\u54c1\u9636|\u7f81\u7eca\u7b49\u7ea7(\u7075\u517d)',
      '8': '\u5f53\u524dHP/\u6700\u5927HP(\u7075\u517d)',
      '9': '\u5907\u6ce8',
      '10': '\u80cc\u666f\u7b80\u4ecb',
      '11': '\u8be6\u7ec6\u5c5e\u6027',
      '12': '\u5185\u5fc3\u60f3\u6cd5/\u52a8\u673a',
      '13': '\u4eba\u9645\u5173\u7cfb',
      '14': '\u53cc\u4fee\u5907\u6ce8',
      '15': '\u597d\u611f\u5ea6',
      '16': '\u52a8\u4f5c|\u7a7f\u7740|\u4f4d\u7f6e|\u8eab\u6bb5|\u6837\u8c8c',
      '20': '\u654f\u611f\u70b9',
      '21': '\u6027\u5668\u72b6\u6001',
      '22': '\u60c5\u6b32\u503c',
      '23': '\u5feb\u611f\u503c',
      '26': '\u5f53\u524d\u7075\u77f3',
      '27': '\u5f53\u524d\u52a8\u673a',
      '28': '\u77ed\u671f\u76ee\u6807',
      '29': '\u957f\u671f\u76ee\u6807',
      '30': '\u73a9\u5bb6\u7075\u517d\u5217\u8868',
      '31': '\u6218\u6597\u72b6\u6001',
      '33': '\u5f3a\u5236\u6f14\u5316',
      '35': '\u751f\u5e73\u7ecf\u5386'
    };

    var formatDisplayValue = function(value) {
      if (value === null) return 'null';
      if (value === undefined) return '';
      if (typeof value === 'string') return value;
      if (typeof value === 'number' || typeof value === 'boolean') return String(value);
      try {
        return JSON.stringify(value);
      } catch (e) {
        return String(value);
      }
    };

    var normalizeColumnBadge = function(key, fallbackLabel) {
      var keyStr = String(key || '');
      if (/^-?\d+$/.test(keyStr)) {
        var colName = columnNameMap[keyStr] || '';
        return '\u5217' + keyStr + (colName ? ('(' + colName + ')') : '');
      }
      return fallbackLabel || keyStr || '\u66f4\u65b0';
    };

    var parseQuotedStringAt = function(text, startIndex) {
      if (!text || text[startIndex] !== '"') return null;
      var escaped = false;
      var raw = '';
      for (var i = startIndex + 1; i < text.length; i++) {
        var ch = text[i];
        if (escaped) {
          raw += ch;
          escaped = false;
          continue;
        }
        if (ch === '\\') {
          raw += ch;
          escaped = true;
          continue;
        }
        if (ch === '"') {
          try {
            return { value: JSON.parse('"' + raw + '"'), end: i };
          } catch (e) {
            return { value: raw, end: i };
          }
        }
        raw += ch;
      }
      return null;
    };

    var extractQuotedStrings = function(text) {
      var out = [];
      if (!text || typeof text !== 'string') return out;
      for (var i = 0; i < text.length; i++) {
        if (text[i] !== '"') continue;
        var parsed = parseQuotedStringAt(text, i);
        if (!parsed) continue;
        out.push(parsed.value);
        i = parsed.end;
      }
      return out;
    };

    var formatTraitDisplay = function(traitObj) {
      if (!traitObj || typeof traitObj !== 'object') return '';
      var name = traitObj.name || traitObj['name'] || '';
      var rarity = traitObj.rarity || traitObj['rarity'] || '';
      var effect = traitObj.effect || traitObj['effect'] || '';
      var desc = traitObj.desc || traitObj['desc'] || '';
      var parts = [];
      if (name) parts.push(String(name));
      if (rarity) parts.push('[' + String(rarity) + ']');
      if (effect) parts.push(String(effect));
      if (desc) parts.push(String(desc));
      if (parts.length > 0) return parts.join(' | ');
      return formatDisplayValue(traitObj);
    };

    var formatGongfaDisplay = function(gongfaObj) {
      if (!gongfaObj || typeof gongfaObj !== 'object') return '';
      var name = gongfaObj.name || gongfaObj['name'] || gongfaObj['1'] || '';
      var grade = gongfaObj.grade || gongfaObj['grade'] || gongfaObj['2'] || gongfaObj['6'] || '';
      var rarity = gongfaObj.rarity || gongfaObj['rarity'] || '';
      var realmEffects =
        gongfaObj.realmEffects ||
        gongfaObj['8'] ||
        gongfaObj.effects ||
        gongfaObj['effects'] ||
        '';
      var desc = gongfaObj.desc || gongfaObj.description || gongfaObj['desc'] || gongfaObj['3'] || '';
      var parts = [];
      if (name) parts.push(String(name));
      if (grade) parts.push('[' + String(grade) + ']');
      if (rarity) parts.push('(' + String(rarity) + ')');
      if (realmEffects) parts.push(String(realmEffects));
      if (desc) parts.push(String(desc));
      if (parts.length > 0) return parts.join(' | ');
      return formatDisplayValue(gongfaObj);
    };

    var parsedResultItems = [];
    var parsedResultOrder = 0;

    var queueResultItem = function(badge, content, badgeClass, columnKey) {
      var safeBadge = badge || '\u66f4\u65b0';
      var safeContent = content;
      if (safeContent === undefined || safeContent === null || safeContent === '') safeContent = '(\u7a7a)';
      var keyStr = (columnKey === undefined || columnKey === null) ? '' : String(columnKey);
      var colNum = /^-?\d+$/.test(keyStr) ? parseInt(keyStr, 10) : null;
      parsedResultItems.push({
        badge: String(safeBadge),
        content: String(safeContent),
        badgeClass: badgeClass || 'ce-entry-badge ce-badge-in',
        column: colNum,
        order: parsedResultOrder++
      });
    };

    if (commandEntries.length > 0) {
      commandEntries.forEach(function(cmd) {
        if (!cmd || !cmd.raw) return;
        var cmdName = String(cmd.name || '').trim();

        if (cmdName === 'add' || cmdName === 'set') {
          var jsonChunk = extractFirstJsonObject(cmd.args);
          if (!jsonChunk) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', cmdName + ' \u6307\u4ee4\u89e3\u6790\u5931\u8d25', 'ce-entry-badge ce-badge-out');
            return;
          }
          var payload;
          try {
            payload = JSON.parse(jsonChunk);
          } catch (e) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', cmdName + ' JSON\u89e3\u6790\u5931\u8d25: ' + e.message, 'ce-entry-badge ce-badge-out');
            return;
          }

          var keys = Object.keys(payload || {});
          if (keys.length === 0) {
            queueResultItem(cmdName === 'set' ? 'set' : 'add', '(\u7a7a\u66f4\u65b0)');
            return;
          }

          keys.sort(function(a, b) {
            var na = parseInt(a, 10);
            var nb = parseInt(b, 10);
            var aNum = !isNaN(na);
            var bNum = !isNaN(nb);
            if (aNum && bNum) return na - nb;
            if (aNum) return -1;
            if (bNum) return 1;
            return String(a).localeCompare(String(b));
          });

          keys.forEach(function(key) {
            queueResultItem(normalizeColumnBadge(key, cmdName), formatDisplayValue(payload[key]), null, key);
          });
          return;
        }

        if (cmdName === 'updateAttribute') {
          var attrMatch = cmd.raw.match(/updateAttribute\s*\(\s*\"[^\"]+\"\s*,\s*\"([^\"]+)\"/);
          var attrName = attrMatch ? attrMatch[1] : '\u5c5e\u6027';
          var attrChunk = extractFirstJsonObject(cmd.args);
          if (!attrChunk) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', 'updateAttribute \u6307\u4ee4\u89e3\u6790\u5931\u8d25', 'ce-entry-badge ce-badge-out');
            return;
          }
          try {
            var attrValue = JSON.parse(attrChunk);
            var currentText = (attrValue && Object.prototype.hasOwnProperty.call(attrValue, 'current')) ? attrValue.current : '?';
            var maxText = (attrValue && Object.prototype.hasOwnProperty.call(attrValue, 'max')) ? attrValue.max : '?';
            queueResultItem(normalizeColumnBadge('11', 'updateAttribute'), attrName + ': ' + currentText + '/' + maxText, null, '11');
          } catch (e) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', 'updateAttribute JSON\u89e3\u6790\u5931\u8d25: ' + e.message, 'ce-entry-badge ce-badge-out');
          }
          return;
        }

        if (cmdName === 'addTrait') {
          var traitChunk = extractFirstJsonObject(cmd.args);
          if (!traitChunk) {
            var traitRaw = String(cmd.args || '').replace(/^\s*"(?:\\.|[^"\\])*"\s*,\s*/, '');
            queueResultItem('\u6c14\u8fd0', traitRaw || '\u65b0\u589e\u6c14\u8fd0', 'ce-entry-badge ce-badge-in');
            return;
          }
          try {
            var traitObj = JSON.parse(traitChunk);
            queueResultItem('\u6c14\u8fd0', formatTraitDisplay(traitObj), 'ce-entry-badge ce-badge-in');
          } catch (e) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', 'addTrait JSON\u89e3\u6790\u5931\u8d25: ' + e.message, 'ce-entry-badge ce-badge-out');
          }
          return;
        }

        if (cmdName === 'deTrait' || cmdName === 'removeTrait') {
          var quoted = extractQuotedStrings(cmd.args || '');
          var traitName = quoted.length >= 2 ? quoted[1] : (quoted.length >= 1 ? quoted[quoted.length - 1] : '');
          var removedText = traitName ? ('\u79fb\u9664: ' + traitName) : (cmd.args || '\u79fb\u9664\u6c14\u8fd0');
          queueResultItem('\u6c14\u8fd0', removedText, 'ce-entry-badge ce-badge-out');
          return;
        }

        if (cmdName === 'addGongfa' || cmdName === 'setGongfa') {
          var gongfaChunk = extractFirstJsonObject(cmd.args);
          if (!gongfaChunk) {
            var gongfaRaw = String(cmd.args || '').replace(/^\s*"(?:\\.|[^"\\])*"\s*,\s*/, '');
            queueResultItem('\u529f\u6cd5', gongfaRaw || '\u66f4\u65b0\u529f\u6cd5', 'ce-entry-badge ce-badge-in');
            return;
          }
          try {
            var gongfaObj = JSON.parse(gongfaChunk);
            queueResultItem('\u529f\u6cd5', formatGongfaDisplay(gongfaObj), 'ce-entry-badge ce-badge-in');
          } catch (e) {
            queueResultItem('\u89e3\u6790\u5931\u8d25', cmdName + ' JSON\u89e3\u6790\u5931\u8d25: ' + e.message, 'ce-entry-badge ce-badge-out');
          }
          return;
        }

        if (cmdName === 'deGongfa' || cmdName === 'removeGongfa') {
          var gongfaQuoted = extractQuotedStrings(cmd.args || '');
          var gongfaName = gongfaQuoted.length >= 2 ? gongfaQuoted[1] : (gongfaQuoted.length >= 1 ? gongfaQuoted[gongfaQuoted.length - 1] : '');
          var gongfaRemovedText = gongfaName ? ('\u79fb\u9664: ' + gongfaName) : (cmd.args || '\u79fb\u9664\u529f\u6cd5');
          queueResultItem('\u529f\u6cd5', gongfaRemovedText, 'ce-entry-badge ce-badge-out');
          return;
        }

        if (cmdName === 'appendBiography') {
          var bioMatch = cmd.raw.match(/appendBiography\s*\(\s*\"[^\"]+\"\s*,\s*(\"(?:\\.|[^\"\\])*\")\s*\)$/);
          if (bioMatch && bioMatch[1]) {
            try {
              queueResultItem(normalizeColumnBadge('35', 'appendBiography'), JSON.parse(bioMatch[1]), null, '35');
              return;
            } catch (e) {}
          }
          queueResultItem(normalizeColumnBadge('35', 'appendBiography'), cmd.args || cmd.raw, null, '35');
          return;
        }

        var label = cmdName || '\u6307\u4ee4';
        queueResultItem(label, cmd.args || cmd.raw);
      });
    }

    if (parsedResultItems.length > 0) {
      parsedResultItems.sort(function(a, b) {
        var aHasColumn = typeof a.column === 'number' && !isNaN(a.column);
        var bHasColumn = typeof b.column === 'number' && !isNaN(b.column);
        if (aHasColumn && bHasColumn) {
          if (a.column !== b.column) return a.column - b.column;
          return a.order - b.order;
        }
        if (aHasColumn) return -1;
        if (bHasColumn) return 1;
        return a.order - b.order;
      });

      parsedResultItems.forEach(function(entry) {
        resultItems += '<div class="ce-entry-item">'
          + '<span class="' + entry.badgeClass + '">' + ceEscapeHtml(entry.badge) + '</span>'
          + '<span style="white-space:pre-wrap;word-break:break-all">' + ceEscapeHtml(entry.content) + '</span>'
          + '</div>';
      });
    }

    if (!resultItems) {
      var fallback = '\u65e0\u7ed3\u679c\u6570\u636e';
      if (!resultItems) {
        if (item.emptyUpstore) fallback = '\u65e0\u6307\u4ee4\uff08\u7a7a upstore\uff09';
        else if (item.noUpstore) fallback = '\u65e0\u6307\u4ee4\uff08\u65e0 upstore\uff09';
        else if (item.skipped) fallback = '\u672c\u8f6e\u8df3\u8fc7\u6216\u65e0\u53d8\u5316';
        else if (item.error) fallback = '\u6267\u884c\u5931\u8d25: ' + item.error;
        resultItems = '<div class="ce-entry-item" style="opacity:0.5">' + ceEscapeHtml(fallback) + '</div>';
      }
    }

    var thinkingBlock = '';
    if (item.thinkingContent) {
      thinkingBlock = '<details style="margin-top:6px">'
        + '<summary style="cursor:pointer;opacity:0.7;font-size:12px">\u601d\u8003\u8fc7\u7a0b</summary>'
        + '<pre class="ce-thinking-content" style="margin-top:4px;white-space:pre-wrap;word-break:break-all;font-size:12px;opacity:0.85">'
        + ceEscapeHtml(item.thinkingContent)
        + '</pre></details>';
    } else {
      thinkingBlock = '<div style="opacity:0.5;font-size:12px;margin-top:6px">(\u65e0\u601d\u8003\u5185\u5bb9)</div>';
    }

    htmlParts.push(
      '<div class="ce-thinking-section ce-thinking-character" data-char-type="' + ceEscapeHtml(item.type || '') + '">'
      + '<div class="ce-thinking-section-header">'
        + '<span>' + ceEscapeHtml(item.id) + '</span>'
        + '<span style="font-weight:700">' + ceEscapeHtml(item.name) + '</span>'
        + typeBadge
      + '</div>'
      + '<div class="ce-thinking-section-body">'
        + '<div style="font-size:12px;opacity:0.75;margin-bottom:4px">\u7ed3\u679c</div>'
        + resultItems
        + thinkingBlock
      + '</div>'
      + '</div>'
    );
    });
  }

  el.innerHTML = htmlParts.join('');
  el.classList.add('ce-structured');
}

// ===== 占位符定义表 =====
