// 默认预设已移除：必须通过“导入预设”提供并发演化提示词。

// ===== 配置管理函数 =====

function ceNormalizeStringIdList(list) {
  if (!Array.isArray(list)) return [];
  const seen = new Set();
  return list
    .map(id => String(id || '').trim())
    .filter(Boolean)
    .filter(id => {
      if (seen.has(id)) return false;
      seen.add(id);
      return true;
    });
}

function ceNormalizeOffscreenActiveLimit(value) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return 30;
  return Math.max(0, num);
}

function ceNormalizeOffscreenRecentTurns(value, fallback = 2) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return fallback;
  return Math.max(0, Math.min(20, num));
}

function ceNormalizeOffscreenTagAuditCandidateLimit(value, fallback = CE_OFFSCREEN_TAG_AUDIT_MAX_CANDIDATES_PER_TURN) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return fallback;
  return Math.max(1, Math.min(50, num));
}

function ceNormalizeOffscreenTagAuditBatchSize(value, fallback = CE_OFFSCREEN_TAG_AUDIT_BATCH_SIZE) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return fallback;
  return Math.max(1, Math.min(20, num));
}

function ceNormalizeOffscreenTagAuditRetryCount(value, fallback = CE_OFFSCREEN_TAG_AUDIT_MAX_RETRY) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return fallback;
  return Math.max(0, Math.min(5, num));
}

function ceNormalizeOffscreenTagAuditRequestTimeout(value, fallback = CE_OFFSCREEN_TAG_AUDIT_REQUEST_TIMEOUT) {
  const num = parseInt(value, 10);
  if (!Number.isFinite(num)) return fallback;
  return Math.max(10000, Math.min(180000, num));
}

async function loadConcurrentEvolutionConfig() {
  const defaultConfig = {
    enabled: true,
    // [简化] mode 字段已移除，硬编码为 all_focus 行为
    focusSelectionMode: 'manual',  // manual | all
    variableUpdateMode: 'staged', // staged | merged；旧配置沿用分阶段
    mergedIndependentTargetIds: [],
    mergedNpcBatchLimit: 6,
    skipDeadInAllFocus: false,
    focusAllOnscreen: true,  // 手动模式是否默认演化所有在场人物
    apiUrl: '',
    apiKey: '',
    apiModel: '',
    apiModels: [],
    originalTimelineApiUrl: '',
    originalTimelineApiKey: '',
    originalTimelineApiModel: '',
    originalTimelineApiModels: [],
    maxConcurrency: 5,
    originalTimelineBatchLimit: 8,
    requestTimeout: 60000,
    retryCount: 2,
    retryDelay: 1000,
    parseRetryCount: 2,
    enableMiscEvolution: true,
    summaryWriterMode: 'concurrent_evolution',
    enableOriginalTimelineLinkage: false,
    enableOriginalTimelineThinkingSection: true,
    focusCharacterIds: [],  // 手动模式：变量演化角色ID列表，空=不演化
    enableOffscreenActiveSelection: true,  // 是否启用离场活跃筛选
    enableOffscreenFreeze: true,  // 是否启用离场冻结机制
    enableOffscreenTagModelAudit: true,  // 是否启用离场标签模型校准
    offscreenActivePolicy: 'strict-v2',  // 旧0仅显式兼容，新规则统一总上限
    offscreenActiveLimit: 30,  // 离场活跃名单上限
    offscreenFreezeExcludeDead: true,  // 是否默认冻结死亡角色
    offscreenRecentExitProtectTurns: 2,  // 最近退场保护轮数
    offscreenRecentMentionProtectTurns: 2,  // 最近提及保护轮数
    offscreenTagAuditPerTurnLimit: CE_OFFSCREEN_TAG_AUDIT_MAX_CANDIDATES_PER_TURN,  // 单轮最多校准人数
    offscreenTagAuditBatchSize: CE_OFFSCREEN_TAG_AUDIT_BATCH_SIZE,  // 单次请求校准人数
    offscreenTagAuditRequestTimeout: CE_OFFSCREEN_TAG_AUDIT_REQUEST_TIMEOUT,  // 标签校准超时（毫秒）
    offscreenTagAuditRetryCount: CE_OFFSCREEN_TAG_AUDIT_MAX_RETRY,  // 标签校准重试次数
    manualFrozenCharacterIds: [],  // 手动冻结NPC列表
    activePresetId: '',
    showErrorModal: true,
    continueOnError: true,
    showProgressModal: false,
    debugLogging: false,  // 调试日志开关，默认关闭
    enableImageEvolution: false,  // 生图演化开关，默认关闭
    imageStyleMode: '', // 未选择时采用当前正文生图的内置画风
    imageStyleProfiles: ceNormalizeImageStyleProfiles(null), // 画风配置（内置+自定义）
    imagePromptTemplateOverrides: { // 生图提示词模板覆盖（为空=使用预设默认）
      sd_keywords: '',
      natural_language: ''
    },
    imageApiUrl: 'https://ark.cn-beijing.volces.com/api/v3/images/generations',
    imageApiKey: '',
    imageApiModel: 'doubao-seedream-5-0-260128',
    imageApiResolution: '2K',
    imageApiAspectRatio: 'auto',
    imageApiSize: '2048x2048',
    imageApiResponseFormat: 'url',
    imageApiProvider: 'doubao',
    imageProviderConfigs: {
      doubao: {
        apiUrl: 'https://ark.cn-beijing.volces.com/api/v3/images/generations',
        apiKey: '',
        apiModel: 'doubao-seedream-5-0-260128',
        resolution: '2K',
        aspectRatio: 'auto',
        responseFormat: 'url'
      },
      openai: {
        apiUrl: 'https://api.openai.com/v1',
        apiKey: '',
        apiModel: 'gpt-image-2',
        size: 'auto',
        quality: 'auto',
        outputFormat: 'png'
      },
      gemini: {
        apiUrl: 'https://generativelanguage.googleapis.com/v1beta/models',
        apiKey: '',
        apiModel: 'gemini-3.1-flash-image-preview',
        aspectRatio: '1:1',
        imageSize: '2K'
      },
      custom_openai: {
        apiUrl: '',
        apiKey: '',
        apiModel: '',
        apiModels: []
      }
    },
    backupApiConfigs: []  // 备用API配置列表 [{apiUrl, apiKey, apiModel, apiModels}]
    // 注: 现在仅支持 all_focus 模式 - 只处理变量演化列表中的角色
  };
  try {
    const saved = await dbGet(CONCURRENT_EVOLUTION_CONFIG_KEY);
    const merged = saved ? { ...defaultConfig, ...saved } : { ...defaultConfig };
    // [简化] 迁移检查：如果旧配置有 compat 模式，提示一次性警告
    if (saved && saved.mode === 'compat' && !saved._compatWarningShown) {
      console.warn('[并发演化] compat 模式已移除，系统已自动切换为 all_focus 模式');
      merged._compatWarningShown = true;
      // 保存更新后的配置以标记警告已显示
      try { await dbSet(CONCURRENT_EVOLUTION_CONFIG_KEY, merged); } catch (e) {}
    }
    delete merged.mode; // 移除废弃字段
    merged.focusSelectionMode = normalizeFocusSelectionMode(merged.focusSelectionMode);
    merged.variableUpdateMode = merged.variableUpdateMode === 'merged' ? 'merged' : 'staged';
    merged.mergedIndependentTargetIds = ceNormalizeStringIdList(merged.mergedIndependentTargetIds);
    merged.mergedNpcBatchLimit = FrMergedEvolution.npcBatchLimit(merged.mergedNpcBatchLimit);
    merged.focusCharacterIds = ceNormalizeStringIdList(merged.focusCharacterIds);
    merged.manualFrozenCharacterIds = ceNormalizeStringIdList(merged.manualFrozenCharacterIds);
    merged.enableOffscreenActiveSelection = merged.enableOffscreenActiveSelection !== false;
    merged.enableOffscreenFreeze = merged.enableOffscreenFreeze !== false;
    merged.enableOffscreenTagModelAudit = merged.enableOffscreenTagModelAudit !== false;
    merged.summaryWriterMode = ceNormalizeSummaryWriterMode(merged.summaryWriterMode);
    merged.enableOriginalTimelineLinkage = false; // 旧末轮已迁出，独立补演由自己的开关控制
    merged.enableOriginalTimelineThinkingSection = merged.enableOriginalTimelineThinkingSection !== false;
    merged.originalTimelineApiUrl = String(merged.originalTimelineApiUrl || '').trim();
    merged.originalTimelineApiKey = String(merged.originalTimelineApiKey || '').trim();
    merged.originalTimelineApiModel = String(merged.originalTimelineApiModel || '').trim();
    merged.originalTimelineApiModels = Array.isArray(merged.originalTimelineApiModels)
      ? merged.originalTimelineApiModels.map(item => String(item || '').trim()).filter(Boolean)
      : [];
    merged.offscreenActivePolicy = ceNormalizeOffscreenActivePolicy(saved || {}, saved);
    merged.offscreenActiveLimit = ceNormalizeOffscreenActiveLimit(merged.offscreenActiveLimit);
    merged.offscreenFreezeExcludeDead = merged.offscreenFreezeExcludeDead !== false;
    merged.offscreenRecentExitProtectTurns = ceNormalizeOffscreenRecentTurns(merged.offscreenRecentExitProtectTurns, 2);
    merged.offscreenRecentMentionProtectTurns = ceNormalizeOffscreenRecentTurns(merged.offscreenRecentMentionProtectTurns, 2);
    merged.offscreenTagAuditPerTurnLimit = ceNormalizeOffscreenTagAuditCandidateLimit(merged.offscreenTagAuditPerTurnLimit);
    merged.offscreenTagAuditBatchSize = ceNormalizeOffscreenTagAuditBatchSize(merged.offscreenTagAuditBatchSize);
    merged.offscreenTagAuditRequestTimeout = ceNormalizeOffscreenTagAuditRequestTimeout(merged.offscreenTagAuditRequestTimeout);
    merged.offscreenTagAuditRetryCount = ceNormalizeOffscreenTagAuditRetryCount(merged.offscreenTagAuditRetryCount);
    merged.originalTimelineBatchLimit = Math.min(50, Math.max(1, Math.floor(Number(merged.originalTimelineBatchLimit) || 8)));
    merged.imageStyleProfiles = ceNormalizeImageStyleProfiles(merged.imageStyleProfiles);
    merged.imageStyleMode = ceNormalizeImageStyleMode(merged.imageStyleMode,merged);
    merged.imageApiUrl = String(merged.imageApiUrl || '').trim() || defaultConfig.imageApiUrl;
    merged.imageApiModel = String(merged.imageApiModel || '').trim() || defaultConfig.imageApiModel;
    merged.imageApiResolution = String(merged.imageApiResolution || '').trim().toUpperCase() || defaultConfig.imageApiResolution;
    merged.imageApiAspectRatio = String(merged.imageApiAspectRatio || '').trim() || defaultConfig.imageApiAspectRatio;
    merged.imageApiSize = String(merged.imageApiSize || '').trim() || defaultConfig.imageApiSize;
    merged.imageApiResponseFormat = String(merged.imageApiResponseFormat || '').trim() || defaultConfig.imageApiResponseFormat;
    // 多提供商配置初始化与向后兼容迁移
    merged.imageApiProvider = ceNormalizeImageApiProvider(merged.imageApiProvider);
    if (!merged.imageProviderConfigs || typeof merged.imageProviderConfigs !== 'object') {
      merged.imageProviderConfigs = JSON.parse(JSON.stringify(defaultConfig.imageProviderConfigs));
      // 迁移旧的 flat 字段到 doubao 配置
      if (merged.imageApiUrl || merged.imageApiKey || merged.imageApiModel) {
        merged.imageProviderConfigs.doubao.apiUrl = merged.imageApiUrl || defaultConfig.imageProviderConfigs.doubao.apiUrl;
        merged.imageProviderConfigs.doubao.apiKey = merged.imageApiKey || '';
        merged.imageProviderConfigs.doubao.apiModel = merged.imageApiModel || defaultConfig.imageProviderConfigs.doubao.apiModel;
        merged.imageProviderConfigs.doubao.resolution = merged.imageApiResolution || defaultConfig.imageProviderConfigs.doubao.resolution;
        merged.imageProviderConfigs.doubao.aspectRatio = merged.imageApiAspectRatio || defaultConfig.imageProviderConfigs.doubao.aspectRatio;
        merged.imageProviderConfigs.doubao.responseFormat = merged.imageApiResponseFormat || 'url';
      }
    } else {
      // 确保各提供商子配置存在
      var defProviders = defaultConfig.imageProviderConfigs;
      Object.keys(defProviders).forEach(function(p) {
        if (!merged.imageProviderConfigs[p] || typeof merged.imageProviderConfigs[p] !== 'object') {
          merged.imageProviderConfigs[p] = JSON.parse(JSON.stringify(defProviders[p]));
        }
      });
    }
    return frResolveLibraryConfig(CONCURRENT_EVOLUTION_CONFIG_KEY, merged);
  } catch (e) {
    console.error('[并发演化] 加载配置失败:', e);
    return defaultConfig;
  }
}

async function saveConcurrentEvolutionConfig(config) {
  try {
    await dbSet(CONCURRENT_EVOLUTION_CONFIG_KEY, config);
    frHydrateLibraryConfig(CONCURRENT_EVOLUTION_CONFIG_KEY, config);
  } catch (e) {
    console.error('[并发演化] 保存配置失败:', e);
  }
}

async function ceLoadOriginalTimelineSummaryStore() {
  try {
    const saved = await dbGet(CONCURRENT_EVOLUTION_ORIGINAL_TIMELINE_SUMMARY_STORE_KEY);
    return saved && typeof saved === 'object' ? saved : {};
  } catch (e) {
    console.error('[原著年表] 加载专用剧情摘要缓存失败:', e);
    return {};
  }
}

async function ceSaveOriginalTimelineSummaryStore(store) {
  try {
    await dbSet(CONCURRENT_EVOLUTION_ORIGINAL_TIMELINE_SUMMARY_STORE_KEY, store);
  } catch (e) {
    console.error('[原著年表] 保存专用剧情摘要缓存失败:', e);
  }
}

function ceGetOriginalTimelineSummaryStoreMeta(store, archiveName) {
  if (!store.__meta) store.__meta = {};
  if (!store.__meta[archiveName]) {
    store.__meta[archiveName] = {
      lastUpdatedAt: '',
      lastGeneratedLogId: '',
      version: 1
    };
  }
  return store.__meta[archiveName];
}

function ceGetOriginalTimelineSummaryStoreEntries(store, archiveName, create = false) {
  if (!store || typeof store !== 'object') return [];
  const normalizedArchiveName = String(archiveName || '').trim();
  if (!normalizedArchiveName) return [];
  if (!store[normalizedArchiveName]) {
    if (!create) return [];
    store[normalizedArchiveName] = { entries: [] };
  }
  const bucket = store[normalizedArchiveName];
  if (!Array.isArray(bucket.entries)) {
    if (!create) return [];
    bucket.entries = [];
  }
  return bucket.entries;
}

function ceNormalizeApiPriorityConfigs(config) {
  const primary = {
    apiPresetId: config && config.apiPresetId || '',
    apiPresetIdManual: !!(config && config.apiPresetIdManual),
    apiPresetSnapshot: config && config.apiPresetSnapshot || null,
    apiUrl: String(config && config.apiUrl || '').trim(),
    apiKey: String(config && config.apiKey || '').trim(),
    apiModel: String(config && config.apiModel || '').trim(),
    apiModels: Array.isArray(config && config.apiModels) ? [...config.apiModels] : []
  };
  const backups = Array.isArray(config && config.backupApiConfigs) ? config.backupApiConfigs : [];
  const list = [primary].concat(backups.map(item => ({
    ...item,
    apiUrl: String(item && item.apiUrl || '').trim(),
    apiKey: String(item && item.apiKey || '').trim(),
    apiModel: String(item && item.apiModel || '').trim(),
    apiModels: Array.isArray(item && item.apiModels) ? [...item.apiModels] : []
  })));
  return list.length > 0 ? list : [{ apiUrl: '', apiKey: '', apiModel: '', apiModels: [] }];
}

function ceApplyApiPriorityConfigs(config, list) {
  const normalized = Array.isArray(list) ? list.map(item => ({
    ...item,
    apiUrl: String(item && item.apiUrl || '').trim(),
    apiKey: String(item && item.apiKey || '').trim(),
    apiModel: String(item && item.apiModel || '').trim(),
    apiModels: Array.isArray(item && item.apiModels) ? [...item.apiModels] : []
  })) : [];
  const ensured = normalized.length > 0 ? normalized : [{ apiUrl: '', apiKey: '', apiModel: '', apiModels: [] }];
  const primary = ensured[0];
  config.apiUrl = primary.apiUrl;
  config.apiKey = primary.apiKey;
  config.apiModel = primary.apiModel;
  config.apiModels = primary.apiModels;
  config.apiPresetId = primary.apiPresetId || '';
  config.apiPresetIdManual = primary.apiPresetIdManual === true;
  config.apiPresetSnapshot = primary.apiPresetSnapshot || null;
  config.backupApiConfigs = ensured.slice(1).map(item => ({
    ...item,
    apiUrl: item.apiUrl,
    apiKey: item.apiKey,
    apiModel: item.apiModel,
    apiModels: item.apiModels
  }));
}

// 返回按优先级过滤后的 API 配置数组（首个为主调用）
function getApiConfigsToTry(config) {
  const routes = typeof frApiRoutes === 'function' && frApiRoutes('CULTIVATION_CONCURRENT_EVOLUTION_CONFIG_V1');
  if(routes)return typeof frAiPrioritizeRoutes==='function'?frAiPrioritizeRoutes(routes):routes;
  try {
    const pack = (typeof CE_CORE === 'object' && CE_CORE) ? CE_CORE['api-library'] : null;
    if (pack && pack.resolveConsumerConfig) config = pack.resolveConsumerConfig('CULTIVATION_CONCURRENT_EVOLUTION_CONFIG_V1', config);
  } catch (_) {}
  const legacy=ceNormalizeApiPriorityConfigs(config).filter(item => item.apiUrl && item.apiKey && item.apiModel);
  return typeof frAiPrioritizeRoutes==='function'?frAiPrioritizeRoutes(legacy):legacy;
}

function ceHasOriginalTimelineDedicatedApiConfig(config) {
  if (!config || typeof config !== 'object') return false;
  return !!(
    String(config.originalTimelineApiUrl || '').trim()
    || String(config.originalTimelineApiKey || '').trim()
    || String(config.originalTimelineApiModel || '').trim()
    || (Array.isArray(config.originalTimelineApiModels) && config.originalTimelineApiModels.some(item => String(item || '').trim()))
  );
}

function ceResolveOriginalTimelineApiConfig(config) {
  const dedicatedModels = Array.isArray(config && config.originalTimelineApiModels)
    ? config.originalTimelineApiModels.map(item => String(item || '').trim()).filter(Boolean)
    : [];
  const dedicatedModel = String(config && config.originalTimelineApiModel || '').trim();
  const apiModels = dedicatedModels.length > 0
    ? [...dedicatedModels]
    : (dedicatedModel ? [dedicatedModel] : []);
  if (dedicatedModel && !apiModels.includes(dedicatedModel)) {
    apiModels.unshift(dedicatedModel);
  }
  return {
    apiUrl: String(config && config.originalTimelineApiUrl || '').trim(),
    apiKey: String(config && config.originalTimelineApiKey || '').trim(),
    apiModel: dedicatedModel,
    apiModels
  };
}

function ceGetOriginalTimelineApiConfigsToTry(config) {
  const routes = typeof frApiRoutes === 'function' && frApiRoutes('CULTIVATION_CONCURRENT_EVOLUTION_CONFIG_V1','originalTimelineApiPresetId');
  if(routes)return routes;
  if (ceHasOriginalTimelineDedicatedApiConfig(config)) {
    const dedicated = ceResolveOriginalTimelineApiConfig(config);
    return dedicated.apiUrl && dedicated.apiKey && dedicated.apiModel ? [dedicated] : [];
  }
  return getApiConfigsToTry(config);
}

function ceExtractApiFailureMessage(responseText) {
  if (!responseText || typeof responseText !== 'string') return '';
  const text = responseText.trim();
  if (!text) return '';

  const bracketMatch = text.match(/\[\s*请求失败\s*:\s*([^\]]+)\]/i);
  if (bracketMatch && bracketMatch[1]) {
    return bracketMatch[1].trim();
  }

  const patterns = [
    /No capacity available for model/i,
    /API\s*请求失败/i,
    /\b(rate limit|too many requests)\b/i,
    /\bservice unavailable\b/i,
    /\btemporarily unavailable\b/i,
    /\boverloaded\b/i,
    /\bupstream\b.*\berror\b/i,
    /\btimeout\b/i
  ];
  if (patterns.some(re => re.test(text))) {
    return text.slice(0, 400);
  }
  return '';
}

function ceThrowIfApiFailureText(responseText, contextLabel = '') {
  const msg = ceExtractApiFailureMessage(responseText);
  if (!msg) return;
  const prefix = contextLabel ? `[${contextLabel}] ` : '';
  throw new Error(`${prefix}上游API错误: ${msg}`);
}

// [简化] normalizeConcurrentEvolutionMode 和 getConcurrentEvolutionMode 已移除
// 系统现在硬编码为 all_focus 行为

function normalizeFocusSelectionMode(mode) {
  const raw = String(mode || '').trim().toLowerCase();
  if (raw === 'all' || raw === 'all_select' || raw === 'all-select' || raw === 'allselect') {
    return 'all';
  }
  return 'manual';
}

function getFocusSelectionMode(config) {
  return normalizeFocusSelectionMode(config && config.focusSelectionMode);
}

function ceNormalizeSummaryWriterMode(mode) {
  const value = String(mode || '').trim().toLowerCase();
  if (value === 'segmented_memory' || value === 'segmented-memory' || value === 'segmentedmemory' || value === 'memory') {
    return 'segmented_memory';
  }
  return 'concurrent_evolution';
}

function ceGetSummaryWriterMode(config) {
  if (config && typeof config === 'object' && Object.prototype.hasOwnProperty.call(config, 'summaryWriterMode')) {
    return ceNormalizeSummaryWriterMode(config.summaryWriterMode);
  }
  if (typeof window !== 'undefined' && window._ceCurrentSummaryWriterMode !== undefined && window._ceCurrentSummaryWriterMode !== null) {
    return ceNormalizeSummaryWriterMode(window._ceCurrentSummaryWriterMode);
  }
  return 'concurrent_evolution';
}

function ceShouldConcurrentEvolutionOwnSummaries(config) {
  return ceGetSummaryWriterMode(config) === 'concurrent_evolution';
}

function ceShouldSkipSegmentedMemoryStandaloneApi(config) {
  return ceShouldConcurrentEvolutionOwnSummaries(config);
}

function ceBuildMiscSummaryWriterPromptOverride(config) {
  if (ceShouldConcurrentEvolutionOwnSummaries(config)) {
    return [
      '---',
      '# 大小总结写入来源（最高优先级覆盖）',
      '当前模式：变量演化负责小总结/大总结。',
      '1. 无论本轮是否有其他杂项指令，每次回复都必须同时输出 addSmallSummary("...") 与 addLargeSummary("...")。',
      '2. 两条总结必须同轮同时出现，禁止只输出一条，也不要把是否输出总结交给模型自行判断。',
      '3. 你只负责产出小总结/大总结文本；深度总结与自动记忆审计仍由前端分段记忆系统继续执行。'
    ].join('\n');
  }
  return [
    '---',
    '# 大小总结写入来源（最高优先级覆盖）',
    '当前模式：分段记忆系统负责小总结/大总结。',
    '1. 本轮严禁输出 addSmallSummary("...") 或 addLargeSummary("...")。',
    '2. 变量演化只处理任务、世界大事、小地图等杂项指令；小总结/大总结交给前端分段记忆独立API。',
    '3. 深度总结与自动记忆审计仍由前端分段记忆系统继续执行，你不要接管也不要关闭这些流程。'
  ].join('\n');
}

function ceNormalizeImagePromptMode(mode) {
  const value = String(mode || '').trim().toLowerCase();
  return value === 'natural_language' ? 'natural_language' : 'sd_keywords';
}

function ceBuildDefaultImageStyleDescription(styleName) {
  const safeName = String(styleName || '').trim() || '自定义画风';
  return [
    safeName + '：',
    '保持主体辨识度与角色一致性，强调稳定的造型语言、材质细节、镜头构图和环境氛围。',
    '输出时将该风格贯穿人物、服装、光影、背景与色彩。'
  ].join('');
}

