function ceNormalizeImportantOriginalRoleToken(value) {
  return String(value || '')
    .replace(/[\u3000\s]+/g, '')
    .replace(/[“”"'‘’《》〈〉【】\[\]（）()]/g, '')
    .trim();
}

function ceResolveImportantOriginalRoleName(value) {
  const normalized = ceNormalizeImportantOriginalRoleToken(value);
  if (!normalized) return '';
  if(typeof ceBridgeActiveRoleRoster==='function' && typeof ceBridgeLastConfig==='object' && ceBridgeLastConfig?.importantRoleLists?.activeId && ceBridgeLastConfig.importantRoleLists.activeId!=='default'){
    const roster=ceBridgeActiveRoleRoster();
    for(const [name,aliases]of Object.entries(roster))if([name,...(aliases||[])].some(alias=>ceNormalizeImportantOriginalRoleToken(alias)===normalized))return name;
    return '';
  }
  return CE_IMPORTANT_ORIGINAL_ROLE_ALIAS_LOOKUP[normalized] || '';
}

function ceResolveImportantOriginalRoleFromTokens(tokens) {
  const list = Array.isArray(tokens) ? tokens : [];
  for (const token of list) {
    const canonicalName = ceResolveImportantOriginalRoleName(token);
    if (canonicalName) return canonicalName;
  }
  return '';
}

function ceGetImportantOriginalRoleAliases(value) {
  const canonicalName = ceResolveImportantOriginalRoleName(value) || String(value || '').trim();
  const roster=typeof ceBridgeActiveRoleRoster==='function'?ceBridgeActiveRoleRoster():CE_IMPORTANT_ORIGINAL_ROLE_ALIAS_MAP;
  const aliases = canonicalName ? roster[canonicalName] : null;
  return Array.isArray(aliases) ? aliases.slice() : [];
}

function ceExtractOffscreenCandidateName(entry, data, fallbackId) {
  const rawName = (data && data['1'] ? String(data['1']).split('|')[0] : '') || entry?.title || entry?.name || entry?.displayName || fallbackId;
  if (typeof ceStripHtmlTags === 'function') return ceStripHtmlTags(rawName);
  return String(rawName || '').replace(/<[^>]*>/g, '');
}

function ceCollectOffscreenCandidateTokens(entry, data, candidateName, candidateId) {
  const tokenSet = new Set();
  const push = (value) => {
    const token = String(value || '').trim();
    if (!token) return;
    tokenSet.add(token.replace(/\s+/g, ''));
  };

  push(candidateId);
  push(candidateName);
  push(entry?.title);
  push(entry?.name);
  push(entry?.displayName);

  const rawName = String(data && data['1'] || '').split('|')[0] || '';
  push(rawName);

  const canonicalImportantRoleName =
    ceResolveImportantOriginalRoleName(candidateName) ||
    ceResolveImportantOriginalRoleName(rawName) ||
    ceResolveImportantOriginalRoleName(entry?.title) ||
    ceResolveImportantOriginalRoleName(entry?.name) ||
    ceResolveImportantOriginalRoleName(entry?.displayName);

  if (canonicalImportantRoleName) {
    push(canonicalImportantRoleName);
    ceGetImportantOriginalRoleAliases(canonicalImportantRoleName).forEach(push);
  }

  return Array.from(tokenSet).filter(token => token.length >= 2 || /^C\d+$/i.test(token));
}

function ceFindMentionedOffscreenIds(text, candidates) {
  const normalizedText = String(text || '').replace(/<[^>]*>/g, '').replace(/\s+/g, '');
  const hits = new Set();
  if (!normalizedText || !Array.isArray(candidates) || candidates.length === 0) return hits;

  candidates.forEach(candidate => {
    if (!candidate || !candidate.id) return;
    const tokens = Array.isArray(candidate.matchTokens) ? candidate.matchTokens : [];
    for (const token of tokens) {
      if (!token) continue;
      if (/^C\d+$/i.test(token)) {
        const matcher = new RegExp(`(^|[^A-Z0-9_])${token}([^A-Z0-9_]|$)`, 'i');
        if (matcher.test(normalizedText)) {
          hits.add(candidate.id);
          return;
        }
      } else if (normalizedText.includes(token)) {
        hits.add(candidate.id);
        return;
      }
    }
  });

  return hits;
}

function ceInferOffscreenNpcTagState(tagState, data) {
  const next = ceNormalizeOffscreenNpcTagState(tagState || {});
  if (next.tagSource === 'model' && next.needsModelReview !== true && ceIsOffscreenTagStateCoreComplete(next)) {
    return next;
  }

  const remarks = ceParseOffscreenRemarks(data);
  const relationInfo = ceAnalyzeOffscreenRelation(data, remarks);
  const statusText = String(data && data['4'] || '').trim();
  const isDead = statusText.includes('已死亡') || next.freezeReason === '已死亡';

  if (next.relationLevel === 'unknown') {
    next.relationLevel = relationInfo.relationLevel;
  }

  if (next.plotLevel === 'unknown') {
    next.plotLevel = ceInferOffscreenPlotLevel(next, data, relationInfo);
  }

  if (next.narrativeRole === 'unknown') {
    next.narrativeRole = ceInferOffscreenNarrativeRole(next, relationInfo, next.plotLevel, data);
  }

  if (next.arcStatus === 'unknown') {
    if (isDead) {
      next.arcStatus = 'finished';
    } else if (next.plotLevel === 'low' && next.relationLevel === 'distant') {
      next.arcStatus = 'idle';
    } else {
      next.arcStatus = 'open';
    }
  }

  if (!next.freezeReason) {
    if (isDead) {
      next.freezeReason = '已死亡';
    } else if (['wrapped', 'finished', 'closed'].includes(next.arcStatus)) {
      next.freezeReason = '剧情已杀青';
    } else if (['transient', 'tool'].includes(next.narrativeRole)) {
      next.freezeReason = '剧情工具角色';
    }
  }

  next.tagSource = 'fallback';
  next.needsModelReview = true;
  return next;
}

var CE_OFFSCREEN_TAG_AUDIT_SYSTEM_PROMPT = [
  '你是严格的NPC标签校准器。',
  '任务：只根据提供的角色资料，为每个角色输出 offscreenTags。',
  '',
  '硬性规则：',
  '1. 必须优先依据第13列中与B1的关系文本，再用第15列好感度修正。',
  '2. 器灵、道侣、生死契、主从、师徒、血亲、长期宿敌等强关系，不得压成 linked。',
  '3. narrativeRole 只能是 bond_core / plot_core / important / normal / transient / tool。',
  '4. arcStatus 只能是 open / idle / wrapped / finished / closed。',
  '5. relationLevel 只能是 life_bound / core / close / linked / distant。',
  '6. plotLevel 只能是 high / normal / low。',
  '7. freezeReason 仅在确有依据时填写“已死亡”“剧情工具角色”“剧情已杀青”，否则填空字符串。',
  '8. 只输出严格JSON，不要解释，不要代码块。',
  '',
  '输出格式：',
  '{"characters":[{"id":"C1","offscreenTags":{"narrativeRole":"important","arcStatus":"open","relationLevel":"close","plotLevel":"normal","freezeReason":""}}]}'
].join('\n');

function ceChunkOffscreenTagAuditCandidates(list, chunkSize) {
  const normalizedList = Array.isArray(list) ? list : [];
  const size = Number.isFinite(chunkSize) ? Math.max(1, Math.floor(chunkSize)) : CE_OFFSCREEN_TAG_AUDIT_BATCH_SIZE;
  const chunks = [];
  for (let i = 0; i < normalizedList.length; i += size) {
    chunks.push(normalizedList.slice(i, i + size));
  }
  return chunks;
}

function ceBuildOffscreenTagAuditRequestPayload(batchCandidates) {
  return (Array.isArray(batchCandidates) ? batchCandidates : []).map(candidate => ({
    id: candidate.id,
    name: candidate.name || candidate.id,
    status: String(candidate.data && candidate.data['4'] || '').trim(),
    relationColumn13: String(candidate.data && candidate.data['13'] || '').trim(),
    favorabilityColumn15: String(candidate.data && candidate.data['15'] || '').trim(),
    goal27: String(candidate.data && candidate.data['27'] || '').trim(),
    goal28: String(candidate.data && candidate.data['28'] || '').trim(),
    goal29: String(candidate.data && candidate.data['29'] || '').trim(),
    biographyColumn35: ceNormalizeBiographyText(candidate.data && candidate.data['35'] || '').slice(-4000),
    existingOffscreenTags: ceBuildPersistedOffscreenTags(candidate.tagState || {})
  }));
}

function ceBuildOffscreenTagAuditPrompt(batchCandidates, options = {}) {
  const payload = ceBuildOffscreenTagAuditRequestPayload(batchCandidates);
  const storyText = String(options.storyText || '')
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .slice(-5000);
  const userInput = String(options.userInput || '')
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .slice(-2000);

  return [
    '当前剧情正文（截断）：',
    storyText || '（无正文）',
    '',
    '当前用户输入（截断）：',
    userInput || '（无用户输入）',
    '',
    '请为以下 NPC 逐个输出 offscreenTags：',
    JSON.stringify(payload, null, 2)
  ].join('\n');
}

function ceExtractOffscreenTagAuditJson(responseText) {
  if (!responseText || typeof responseText !== 'string') return null;
  let cleaned = responseText
    .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .trim();

  const fencedMatch = cleaned.match(/```json\s*([\s\S]*?)\s*```/i) || cleaned.match(/```\s*([\s\S]*?)\s*```/i);
  if (fencedMatch && fencedMatch[1]) {
    cleaned = fencedMatch[1].trim();
  }

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const jsonChunk = extractFirstJsonObject(cleaned);
    if (!jsonChunk) return null;
    try {
      return JSON.parse(jsonChunk);
    } catch (err) {
      return null;
    }
  }
}

async function ceRequestOffscreenTagAuditBatch(options = {}) {
  const batchCandidates = Array.isArray(options.batchCandidates) ? options.batchCandidates : [];
  const config = options.config || {};
  const apiCaller = (typeof genericApiCall === 'function' && genericApiCall.__ceOriginal)
    ? genericApiCall.__ceOriginal
    : genericApiCall;
  const maxRetries = ceNormalizeOffscreenTagAuditRetryCount(config.offscreenTagAuditRetryCount, CE_OFFSCREEN_TAG_AUDIT_MAX_RETRY);
  const timeoutMs = ceNormalizeOffscreenTagAuditRequestTimeout(config.offscreenTagAuditRequestTimeout, CE_OFFSCREEN_TAG_AUDIT_REQUEST_TIMEOUT);
  const requestPrompt = ceBuildOffscreenTagAuditPrompt(batchCandidates, options);
  const requestPayload = ceBuildOffscreenTagAuditRequestPayload(batchCandidates);

  if (batchCandidates.length === 0) {
    return { parsed: { characters: [] }, response: '', rawResponse: '', thinking: '', requestPrompt, requestPayload };
  }
  if (typeof apiCaller !== 'function') {
    throw new Error('genericApiCall 不可用，无法进行离场标签校准');
  }

  const messages = [
    { role: 'system', content: CE_OFFSCREEN_TAG_AUDIT_SYSTEM_PROMPT },
    { role: 'user', content: requestPrompt }
  ];

  let lastError = null;
  let lastResponse = '';
  let lastThinking = '';
  const routes=options.routes??(typeof getApiConfigsToTry==='function'?getApiConfigsToTry(config):[config]);
  for(const [index,route] of routes.entries()) {
  const hasNextRoute=index<routes.length-1;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    options.signal?.throwIfAborted();
    const controller = new AbortController();
    if(options.signal){frCanonTraceLinkSignal(options.signal,controller.signal,{stageKey:'tags',subject:batchCandidates.map(x=>x.name||x.id).join('、'),targetId:batchCandidates.length===1?String(batchCandidates[0].id||''):'',targetIds:batchCandidates.map(x=>String(x.id||'')).filter(Boolean)});if(options.signal.aborted)controller.abort();else options.signal.addEventListener('abort',()=>controller.abort(),{once:true});}
    controller._isTimeoutAbort = false;
    const timeoutId = setTimeout(() => {
      controller._isTimeoutAbort = true;
      controller.abort();
    }, timeoutMs);

    let modelResponded=false;
    try {
      const response = await apiCaller(
        route.apiUrl,
        route.apiKey,
        route.apiModel,
        messages,
        controller.signal,{route,hasNextRoute}
      );
      clearTimeout(timeoutId);

      lastResponse = typeof response === 'string' ? response : String(response || '');
      const hasThinkingTag = /<thinking>[\s\S]*?<\/thinking>|<think>[\s\S]*?<\/think>/i.test(lastResponse);
      lastThinking = hasThinkingTag ? (ceExtractThinkingContent(lastResponse) || '') : '';
      ceThrowIfApiFailureText(lastResponse, '标签校准');
      modelResponded=true;
      if (!lastResponse.trim()) {
        throw new Error('离场标签校准响应为空');
      }

      const parsed = ceExtractOffscreenTagAuditJson(lastResponse);
      if (!parsed) {
        throw new Error('离场标签校准响应解析失败');
      }

      return {
        parsed,
        response: lastResponse,
        rawResponse: lastResponse,
        thinking: lastThinking,
        requestPrompt,
        requestPayload
      };
    } catch (e) {
      clearTimeout(timeoutId);
      if(options.signal?.aborted||e?.name==='AbortError'&&!controller._isTimeoutAbort)throw e;
      const wrappedError = e instanceof Error ? e : new Error(String(e));
      wrappedError.ceRawResponse = lastResponse || wrappedError.ceRawResponse || '';
      wrappedError.ceThinking = lastThinking || wrappedError.ceThinking || '';
      wrappedError.ceRequestPrompt = requestPrompt;
      wrappedError.ceRequestPayload = requestPayload;
      lastError = wrappedError;
      const canRetry = (modelResponded||!hasNextRoute)&&attempt<maxRetries;
      if (!canRetry) break;
    }
  }
  }

  throw lastError || new Error('离场标签校准失败');
}

function ceShouldAuditOffscreenTagState(tagState) {
  const normalized = ceNormalizeOffscreenNpcTagState(tagState || {});
  if (normalized.needsModelReview === true) return true;
  if (normalized.tagSource !== 'model') return true;
  return !ceIsOffscreenTagStateCoreComplete(normalized);
}

function ceSetLastOffscreenTagCalibrationResult(value) {
  if (typeof window === 'undefined') return;
  if (!value) {
    window.lastOffscreenTagCalibrationResult = null;
    return;
  }
  try {
    window.lastOffscreenTagCalibrationResult = JSON.parse(JSON.stringify(value));
  } catch (e) {
    window.lastOffscreenTagCalibrationResult = value;
  }
}

function ceBuildOffscreenTagCalibrationPriorityReasons(candidate, provisional, storyMentionIds, userMentionIds) {
  const reasons = [];
  if (userMentionIds && userMentionIds.has(candidate.id)) reasons.push('用户输入直提 +400');
  if (storyMentionIds && storyMentionIds.has(candidate.id)) reasons.push('正文直提 +260');
  if (provisional.relationLevel === 'life_bound') reasons.push('生死绑定 +240');
  else if (provisional.relationLevel === 'core') reasons.push('核心纠葛 +180');
  else if (provisional.relationLevel === 'close') reasons.push('密切关系 +90');
  if (provisional.narrativeRole === 'bond_core') reasons.push('关系核心 +160');
  else if (provisional.narrativeRole === 'plot_core') reasons.push('主线核心 +140');
  else if (provisional.narrativeRole === 'important') reasons.push('重要人物 +70');
  if (provisional.plotLevel === 'high') reasons.push('高热度 +60');
  else if (provisional.plotLevel === 'normal') reasons.push('普通热度 +20');
  if (candidate && candidate.isDead) reasons.push('已死亡 -80');
  return reasons;
}

function ceBuildOffscreenTagCalibrationCandidateSummary(candidate, provisional, priority, storyMentionIds, userMentionIds) {
  const normalized = ceNormalizeOffscreenNpcTagState(provisional || candidate?.tagState || {});
  return {
    id: String(candidate?.id || '').trim(),
    name: String(candidate?.name || candidate?.id || '').trim(),
    priority: Number.isFinite(priority) ? Math.round(priority) : 0,
    isDead: candidate?.isDead === true,
    reasons: ceBuildOffscreenTagCalibrationPriorityReasons(candidate, normalized, storyMentionIds, userMentionIds),
    provisional: {
      narrativeRole: normalized.narrativeRole,
      arcStatus: normalized.arcStatus,
      relationLevel: normalized.relationLevel,
      plotLevel: normalized.plotLevel,
      freezeReason: normalized.freezeReason || ''
    },
    resultSource: normalized.tagSource,
    needsModelReview: normalized.needsModelReview === true
  };
}

function ceHasOffscreenTagCalibrationWakeSignal(text, candidate) {
  const normalizedText = String(text || '').replace(/<[^>]*>/g, '').replace(/\s+/g, '').trim();
  if (!normalizedText) return false;
  if (!/(返场|返場|复活|复生|复苏|复原|归来|回归|再登场|重新登场|再出场|重新出现|救活|救回|苏醒)/.test(normalizedText)) {
    return false;
  }
  const tokens = Array.isArray(candidate && candidate.matchTokens) ? candidate.matchTokens : [];
  return tokens.some(token => {
    const normalizedToken = String(token || '').replace(/\s+/g, '').trim();
    return normalizedToken && normalizedText.includes(normalizedToken);
  });
}

function ceGetOffscreenTagCalibrationSkipInfo(candidate, provisional, options = {}) {
  const manualFrozenSet = options.manualFrozenSet instanceof Set ? options.manualFrozenSet : new Set();
  const isManualFrozen = manualFrozenSet.has(String(candidate && candidate.id || ''));
  const isDead = candidate && candidate.isDead === true;
  const roleFrozen = !candidate?.canonTier && ['transient', 'tool'].includes(String(provisional && provisional.narrativeRole || '').trim());
  const arcFrozen = ['wrapped', 'finished', 'closed'].includes(String(provisional && provisional.arcStatus || '').trim());
  const freezeReason = String(
    provisional && provisional.freezeReason
      || (isManualFrozen ? '手动冻结' : '')
      || (isDead ? '已死亡' : '')
      || (arcFrozen ? '剧情已杀青' : '')
      || (roleFrozen ? '剧情工具角色' : '')
  ).trim();
  const hasWakeSignal = !isManualFrozen && (
    candidate && candidate.isOnscreen === true
    || ceHasOffscreenTagCalibrationWakeSignal(options.storyText, candidate)
    || ceHasOffscreenTagCalibrationWakeSignal(options.userInput, candidate)
  );
  const isFrozen = isManualFrozen || isDead || roleFrozen || arcFrozen;
  return {
    isFrozen,
    isManualFrozen,
    hasWakeSignal,
    freezeReason,
    skip: isFrozen && !hasWakeSignal
  };
}

async function ceEnsureOffscreenRosterModelTagStates(options = {}) {
  const archive = options.archive;
  const state = options.state;
  let candidates = Array.isArray(options.candidates) ? options.candidates : [];
  const tagReplaySession=typeof frReplaySessionBySignal==='function'?frReplaySessionBySignal(options.signal,'ce'):null;
  if(tagReplaySession){
    const picked=new Set((tagReplaySession.selection?.scopes||[]).filter(scope=>String(scope).startsWith('tags:')).map(scope=>String(scope).slice(5)).filter(Boolean));
    if(picked.size)candidates=candidates.filter(candidate=>picked.has(String(candidate.id))||picked.has(String(candidate.name||'')));
  }
  const turnIndex = Number.isFinite(options.turnIndex) ? options.turnIndex : -1;
  const storyText = String(options.storyText || '');
  const userInput = String(options.userInput || '');
  const config = options.config || {};
  const scopeLabel = String(options.scopeLabel || '当前相关 NPC');
  const manualBackfill = options.manualBackfill === true;
  const activePriorityIdSet = options.activePriorityIdSet instanceof Set
    ? new Set(Array.from(options.activePriorityIdSet).map(id => String(id || '').trim()).filter(Boolean))
    : new Set(Array.isArray(options.activePriorityIdSet)
      ? options.activePriorityIdSet.map(id => String(id || '').trim()).filter(Boolean)
      : []);
  const activeCandidateIdSet = options.activeCandidateIdSet instanceof Set
    ? new Set(Array.from(options.activeCandidateIdSet).map(id => String(id || '').trim()).filter(Boolean))
    : new Set(Array.isArray(options.activeCandidateIdSet)
      ? options.activeCandidateIdSet.map(id => String(id || '').trim()).filter(Boolean)
      : []);
  const calibrationResult = {
    scopeLabel,
    turnIndex,
    totalCandidateCount: candidates.length,
    pendingCount: 0,
    modelEnabled: config.enableOffscreenTagModelAudit !== false,
    canUseModel: false,
    calibrationLimit: ceNormalizeOffscreenTagAuditCandidateLimit(config.offscreenTagAuditPerTurnLimit),
    batchSize: 0,
    message: '',
    status: 'idle',
    ruleSummary: [
      '用户输入直接提及 +400，正文直接提及 +260。',
      '关系层级：生死绑定 +240，核心纠葛 +180，密切关系 +90。',
      '叙事定位：关系核心 +160，主线核心 +140，重要人物 +70。',
      '剧情热度：高热度 +60，普通热度 +20。',
      '封存/冻结/死亡默认跳过，不进入送校或延期；仅在正文或用户输入明确提到返场/复活时才重新纳入。'
    ],
    selectedNow: [],
    deferred: [],
    skippedFrozen: [],
    localResolved: [],
    batchResults: [],
    summary: {
      modelResolvedCount: 0,
      fallbackCount: 0,
      localCount: 0,
      deferredCount: 0,
      skippedCount: 0
    }
  };
  const previousCalibrationResult = typeof window !== 'undefined' && window.lastOffscreenTagCalibrationResult && typeof window.lastOffscreenTagCalibrationResult === 'object'
    ? window.lastOffscreenTagCalibrationResult
    : null;

  if (!archive || !state || candidates.length === 0) {
    calibrationResult.status = 'no_candidates';
    calibrationResult.message = '本轮没有可校准的' + scopeLabel;
    ceSetLastOffscreenTagCalibrationResult(calibrationResult);
    return false;
  }

  let changed = false;
  const modelAuditEnabled = calibrationResult.modelEnabled;
  const manualFrozenSet = new Set(ceNormalizeStringIdList(config.manualFrozenCharacterIds || state.manualFrozenIds || []));
  const storyMentionIds = ceFindMentionedOffscreenIds(storyText, candidates);
  const userMentionIds = ceFindMentionedOffscreenIds(userInput, candidates);

  const applyResolvedLocalState = (candidate, options = {}) => {
    const current = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id] || candidate.tagState || {});
    const localState = ceInferOffscreenNpcTagState(current, candidate.data);
    localState.tagSource = options.tagSource || 'fallback';
    localState.needsModelReview = options.needsModelReview === true;
    localState.lastAuditAttemptTurn = turnIndex;
    localState.updatedAtTurn = turnIndex;
    if (Object.prototype.hasOwnProperty.call(options, 'lastModelAuditTurn')) {
      localState.lastModelAuditTurn = options.lastModelAuditTurn;
    }
    state.npcTagState[candidate.id] = localState;
    candidate.tagState = localState;
    changed = true;
    return localState;
  };

  const countManualBackfillActiveRemaining = () => {
    if (!manualBackfill || activeCandidateIdSet.size === 0) return 0;
    let remaining = 0;
    activeCandidateIdSet.forEach(id => {
      const tagState = ceNormalizeOffscreenNpcTagState(state.npcTagState[id]);
      if (ceShouldAuditOffscreenTagState(tagState)) {
        remaining += 1;
      }
    });
    return remaining;
  };

  const updateManualBackfillProgressStatus = (completed, total) => {
    if (!manualBackfill || typeof updateOffscreenTagCalibrationDanmakuStatus !== 'function') return;
    const safeCompleted = Math.max(0, Number.isFinite(completed) ? completed : 0);
    const safeTotal = Math.max(0, Number.isFinite(total) ? total : 0);
    const activeRemaining = countManualBackfillActiveRemaining();
    const text = `NPC标签校对中，已完成 ${safeCompleted} / ${safeTotal}，活跃未模型校对剩余 ${activeRemaining}`;
    updateOffscreenTagCalibrationDanmakuStatus(text, {
      completed: safeCompleted,
      roundTotal: safeTotal,
      activeRemaining
    });
  };

  const updateAutoCalibrationProgressStatus = (completed, total, deferredCount) => {
    if (manualBackfill || typeof updateOffscreenTagCalibrationDanmakuStatus !== 'function') return;
    const safeCompleted = Math.max(0, Number.isFinite(completed) ? completed : 0);
    const safeTotal = Math.max(0, Number.isFinite(total) ? total : 0);
    const safeDeferred = Math.max(0, Number.isFinite(deferredCount) ? deferredCount : 0);
    const text = `NPC标签校对中，已完成 ${safeCompleted} / ${safeTotal}，延期 ${safeDeferred}`;
    updateOffscreenTagCalibrationDanmakuStatus(text, {
      completed: safeCompleted,
      roundTotal: safeTotal,
      deferredCount: safeDeferred
    });
  };

  const prioritizedPendingCandidates = [];
  candidates.forEach(candidate => {
    const current = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id] || candidate.tagState || {});
    if (!manualBackfill && current.lastAuditAttemptTurn === turnIndex) return;

    const provisional = ceInferOffscreenNpcTagState(current, candidate.data);
    const wakeSignal = ceHasOffscreenTagCalibrationWakeSignal(storyText, candidate)
      || ceHasOffscreenTagCalibrationWakeSignal(userInput, candidate);
    const shouldAudit = manualBackfill
      ? (wakeSignal || ceShouldAuditOffscreenTagState(current))
      : (
        wakeSignal
        || ceShouldAuditOffscreenTagState(current)
        || (modelAuditEnabled && current.lastModelAuditTurn !== turnIndex)
      );
    if (!shouldAudit) return;

    const skipInfo = ceGetOffscreenTagCalibrationSkipInfo(candidate, provisional, {
      manualFrozenSet,
      storyText,
      userInput
    });
    if (skipInfo.skip) {
      const skippedState = applyResolvedLocalState(candidate, {
        tagSource: 'local',
        needsModelReview: false,
        lastModelAuditTurn: current.lastModelAuditTurn
      });
      if (!skippedState.freezeReason && skipInfo.freezeReason) {
        skippedState.freezeReason = skipInfo.freezeReason;
      }
      calibrationResult.skippedFrozen.push(Object.assign(
        {},
        ceBuildOffscreenTagCalibrationCandidateSummary(candidate, skippedState, 0, storyMentionIds, userMentionIds),
        {
          resultSource: skippedState.tagSource,
          needsModelReview: false,
          resultLabel: '冻结跳过',
          resultError: skipInfo.isManualFrozen
            ? '手动冻结，跳过校准'
            : ((skipInfo.freezeReason || '已冻结') + '，且本轮无明确返场/复活信号，跳过校准')
        }
      ));
      return;
    }

    const isDirectPriority = candidate.isOnscreen === true || userMentionIds.has(candidate.id) || storyMentionIds.has(candidate.id);
    const isActiveBackfillPriority = !manualBackfill
      && !isDirectPriority
      && activePriorityIdSet.has(candidate.id)
      && ceShouldAuditOffscreenTagState(current);
    let priorityBand = 0;
    if (isDirectPriority) priorityBand = 2;
    else if (isActiveBackfillPriority) priorityBand = 1;

    let priority = 0;
    if (candidate.isOnscreen === true) priority += 520;
    if (userMentionIds.has(candidate.id)) priority += 400;
    if (storyMentionIds.has(candidate.id)) priority += 260;
    if (provisional.relationLevel === 'life_bound') priority += 240;
    else if (provisional.relationLevel === 'core') priority += 180;
    else if (provisional.relationLevel === 'close') priority += 90;
    if (provisional.narrativeRole === 'bond_core') priority += 160;
    else if (provisional.narrativeRole === 'plot_core') priority += 140;
    else if (provisional.narrativeRole === 'important') priority += 70;
    if (provisional.plotLevel === 'high') priority += 60;
    else if (provisional.plotLevel === 'normal') priority += 20;
    if (candidate.isDead) priority -= 80;
    if (wakeSignal) priority += 500;
    if (isActiveBackfillPriority) priority += 320;

    prioritizedPendingCandidates.push({
      candidate,
      provisional,
      priorityBand,
      priority,
      summary: ceBuildOffscreenTagCalibrationCandidateSummary(candidate, provisional, priority, storyMentionIds, userMentionIds)
    });
  });

  calibrationResult.summary.skippedCount = calibrationResult.skippedFrozen.length;
  calibrationResult.pendingCount = prioritizedPendingCandidates.length;
  if (prioritizedPendingCandidates.length === 0) {
    const canReusePreviousResult = !manualBackfill
      && previousCalibrationResult
      && Number(previousCalibrationResult.turnIndex) === turnIndex
      && String(previousCalibrationResult.scopeLabel || '') === scopeLabel
      && (
        (Array.isArray(previousCalibrationResult.selectedNow) && previousCalibrationResult.selectedNow.length > 0)
        || (Array.isArray(previousCalibrationResult.deferred) && previousCalibrationResult.deferred.length > 0)
        || (Array.isArray(previousCalibrationResult.batchResults) && previousCalibrationResult.batchResults.length > 0)
      );
    if (canReusePreviousResult) {
      return changed;
    }

    calibrationResult.status = calibrationResult.skippedFrozen.length > 0 ? 'skipped_frozen_only' : 'no_pending';
    if (manualBackfill) {
      calibrationResult.message = calibrationResult.skippedFrozen.length > 0
        ? '当前可送校 NPC 已全部完成模型校对，其余冻结/封存/死亡对象按设置跳过'
        : '当前所有可送校 NPC 都已完成模型校对';
    } else {
      calibrationResult.message = calibrationResult.skippedFrozen.length > 0
        ? '本轮需校准对象均已因冻结/封存/死亡被跳过'
        : '本轮没有需要标签校准的' + scopeLabel;
    }
    ceSetLastOffscreenTagCalibrationResult(calibrationResult);
    return changed;
  }

  prioritizedPendingCandidates.sort((a, b) => {
    const bandDiff = (b.priorityBand || 0) - (a.priorityBand || 0);
    if (bandDiff !== 0) return bandDiff;
    const priorityDiff = b.priority - a.priority;
    if (priorityDiff !== 0) return priorityDiff;
    if (a.candidate.sourceIndex !== b.candidate.sourceIndex) {
      return a.candidate.sourceIndex - b.candidate.sourceIndex;
    }
    return String(a.candidate.id || '').localeCompare(String(b.candidate.id || ''), 'zh');
  });

  if (!modelAuditEnabled) {
    prioritizedPendingCandidates.forEach(item => {
      const localState = applyResolvedLocalState(item.candidate, {
        tagSource: 'local',
        needsModelReview: false
      });
      calibrationResult.localResolved.push(Object.assign({}, item.summary, {
        resultSource: localState.tagSource,
        needsModelReview: localState.needsModelReview === true,
        resultLabel: '本地判定'
      }));
    });
    calibrationResult.status = 'local_only';
    calibrationResult.message = '模型标签校准已关闭，本轮直接使用本地判定';
    calibrationResult.summary.localCount = calibrationResult.localResolved.length;
    ceSetLastOffscreenTagCalibrationResult(calibrationResult);
    return changed;
  }

  const auditLimit = calibrationResult.calibrationLimit;
  const auditCandidates = prioritizedPendingCandidates.slice(0, auditLimit);
  const deferredCandidates = prioritizedPendingCandidates.slice(auditLimit);

  if (auditCandidates.length > 0) {
    if (manualBackfill) {
      updateManualBackfillProgressStatus(0, auditCandidates.length);
    } else {
      updateAutoCalibrationProgressStatus(0, auditCandidates.length, deferredCandidates.length);
    }
  }

  const refreshSelectedNowResults = () => {
    const resolvedById = new Map();
    calibrationResult.batchResults.forEach(batch => {
      const merged = [];
      if (Array.isArray(batch && batch.modelResolved)) merged.push(...batch.modelResolved);
      if (Array.isArray(batch && batch.fallbackResolved)) merged.push(...batch.fallbackResolved);
      merged.forEach(item => {
        const id = String(item && item.id || '').trim();
        if (!id) return;
        resolvedById.set(id, Object.assign({}, item));
      });
    });
    calibrationResult.selectedNow = auditCandidates.map(item => Object.assign(
      {},
      item.summary,
      resolvedById.get(String(item.candidate && item.candidate.id || '')) || {}
    ));
  };

  refreshSelectedNowResults();
  calibrationResult.deferred = deferredCandidates.map(item => Object.assign({}, item.summary, {
    resultLabel: '超过单轮上限，延后到后续轮次',
    resultSource: 'fallback',
    needsModelReview: true
  }));
  calibrationResult.summary.deferredCount = calibrationResult.deferred.length;

  if (deferredCandidates.length > 0) {
    console.log('[离场标签校准] 本轮校准限流，剩余候选延后:', {
      totalPending: prioritizedPendingCandidates.length,
      auditNow: auditCandidates.length,
      deferred: deferredCandidates.length
    });
    deferredCandidates.forEach(({ candidate, provisional }) => {
      provisional.tagSource = 'fallback';
      provisional.needsModelReview = true;
      provisional.lastAuditAttemptTurn = turnIndex;
      provisional.updatedAtTurn = turnIndex;
      state.npcTagState[candidate.id] = provisional;
      candidate.tagState = provisional;
      changed = true;
    });
  }

  if (auditCandidates.length === 0) {
    calibrationResult.status = 'deferred_only';
    calibrationResult.message = '本轮未发送标签校准请求';
    ceSetLastOffscreenTagCalibrationResult(calibrationResult);
    return changed;
  }

  auditCandidates.forEach(({ candidate }) => {
    const pendingState = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id] || candidate.tagState || {});
    pendingState.lastAuditAttemptTurn = turnIndex;
    pendingState.updatedAtTurn = turnIndex;
    pendingState.needsModelReview = true;
    state.npcTagState[candidate.id] = pendingState;
    candidate.tagState = pendingState;
    changed = true;
  });

  const apiCaller = (typeof genericApiCall === 'function' && genericApiCall.__ceOriginal)
    ? genericApiCall.__ceOriginal
    : genericApiCall;
  const tagRoutes=typeof getApiConfigsToTry==='function'?getApiConfigsToTry(config):
    config.apiUrl&&config.apiModel?[config]:[];
  const canUseModel = typeof apiCaller === 'function' && tagRoutes.length>0;
  calibrationResult.canUseModel = canUseModel;

  const applyFallbackState = (candidate, reasonText) => {
    const fallbackState = applyResolvedLocalState(candidate, {
      tagSource: 'fallback',
      needsModelReview: true
    });
    return Object.assign(
      {},
      ceBuildOffscreenTagCalibrationCandidateSummary(candidate, fallbackState, 0, storyMentionIds, userMentionIds),
      {
        resultSource: fallbackState.tagSource,
        needsModelReview: fallbackState.needsModelReview === true,
        resultLabel: '异常兜底',
        resultError: reasonText || ''
      }
    );
  };

  if (!canUseModel) {
    console.warn('[离场标签校准] 标签校准API配置不完整，回退为本地兜底');
    const batchReport = {
      ids: auditCandidates.map(item => item.candidate.id),
      status: 'config_incomplete',
      modelResolved: [],
      fallbackResolved: [],
      error: '标签校准API配置不完整',
      modelResolvedCount: 0,
      fallbackCount: 0,
      requestPrompt: '',
      requestPayload: '',
      thinking: '',
      rawResponse: ''
    };
    auditCandidates.forEach(({ candidate }) => {
      batchReport.fallbackResolved.push(applyFallbackState(candidate, '标签校准 API 配置不完整'));
    });
    batchReport.fallbackCount = batchReport.fallbackResolved.length;
    calibrationResult.batchResults.push(batchReport);
    refreshSelectedNowResults();
    calibrationResult.summary.fallbackCount += batchReport.fallbackCount;
    calibrationResult.status = 'config_incomplete';
    calibrationResult.message = '标签校准 API 配置不完整，本轮已回退为本地兜底';
    ceSetLastOffscreenTagCalibrationResult(calibrationResult);
    return changed;
  }

  const auditBatchSize = ceNormalizeOffscreenTagAuditBatchSize(config.offscreenTagAuditBatchSize);
  calibrationResult.batchSize = auditBatchSize;
  const batches = ceChunkOffscreenTagAuditCandidates(auditCandidates.map(item => item.candidate), auditBatchSize);
  let processedCount = 0;
  for (const batchCandidates of batches) {
    const batchReport = {
      ids: batchCandidates.map(candidate => candidate.id),
      status: 'pending',
      modelResolved: [],
      fallbackResolved: [],
      error: '',
      modelResolvedCount: 0,
      fallbackCount: 0,
      requestPrompt: '',
      requestPayload: '',
      thinking: '',
      rawResponse: ''
    };

    try {
      const batchResult = await ceRequestOffscreenTagAuditBatch({
        batchCandidates,
        storyText,
        userInput,
        signal: options.signal,
        config,routes:tagRoutes
      });
      batchReport.requestPrompt = String(batchResult.requestPrompt || '');
      batchReport.requestPayload = batchResult.requestPayload
        ? (typeof batchResult.requestPayload === 'string'
          ? batchResult.requestPayload
          : JSON.stringify(batchResult.requestPayload, null, 2))
        : '';
      batchReport.thinking = String(batchResult.thinking || '');
      batchReport.rawResponse = String(batchResult.rawResponse || batchResult.response || '');
      const parsedList = Array.isArray(batchResult.parsed)
        ? batchResult.parsed
        : (Array.isArray(batchResult.parsed?.characters) ? batchResult.parsed.characters : []);
      const parsedMap = new Map();
      parsedList.forEach(item => {
        if (!item || typeof item !== 'object') return;
        const id = String(item.id || '').trim();
        if (!id || !item.offscreenTags || typeof item.offscreenTags !== 'object') return;
        parsedMap.set(id, item.offscreenTags);
      });

      batchCandidates.forEach(candidate => {
        const current = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id] || candidate.tagState || {});
        const rawTags = parsedMap.get(candidate.id);
        if (rawTags && typeof rawTags === 'object') {
          const modelState = ceNormalizeOffscreenNpcTagState(Object.assign({}, current, rawTags, {
            tagSource: 'model',
            needsModelReview: false,
            lastModelAuditTurn: turnIndex,
            lastAuditAttemptTurn: turnIndex,
            updatedAtTurn: turnIndex
          }));
          if (ceIsOffscreenTagStateCoreComplete(modelState)) {
            ceApplyExplicitOffscreenTagsToData(candidate.data, modelState);
            if (candidate.entry && typeof candidate.entry === 'object') {
              candidate.entry.content = JSON.stringify(candidate.data || {}, null, 2);
            }
            state.npcTagState[candidate.id] = modelState;
            candidate.tagState = modelState;
            changed = true;
            batchReport.modelResolved.push(Object.assign(
              {},
              ceBuildOffscreenTagCalibrationCandidateSummary(candidate, modelState, 0, storyMentionIds, userMentionIds),
              {
                resultSource: modelState.tagSource,
                needsModelReview: modelState.needsModelReview === true,
                resultLabel: '模型校准'
              }
            ));
            return;
          }
        }

        batchReport.fallbackResolved.push(applyFallbackState(
          candidate,
          rawTags ? '模型返回字段不完整，已回退为本地兜底' : '模型未返回该角色结果，已回退为本地兜底'
        ));
      });
      batchReport.status = 'success';
    } catch (e) {
      console.warn('[离场标签校准] 模型标签校准失败，回退为本地兜底:', e);
      batchReport.status = 'failed';
      batchReport.error = e && e.message ? e.message : String(e);
      batchReport.requestPrompt = String(e && e.ceRequestPrompt || '');
      batchReport.requestPayload = e && e.ceRequestPayload
        ? (typeof e.ceRequestPayload === 'string'
          ? e.ceRequestPayload
          : JSON.stringify(e.ceRequestPayload, null, 2))
        : '';
      batchReport.thinking = String(e && e.ceThinking || '');
      batchReport.rawResponse = String(e && e.ceRawResponse || '');
      batchCandidates.forEach(candidate => {
        batchReport.fallbackResolved.push(applyFallbackState(candidate, '请求失败：' + batchReport.error));
      });
    }

    batchReport.modelResolvedCount = batchReport.modelResolved.length;
    batchReport.fallbackCount = batchReport.fallbackResolved.length;
    if(typeof frReplaySession==='object'&&frReplaySession&&(batchReport.status==='failed'||batchReport.fallbackCount>0))frReplayFail('标签校准未完整成功',new Error(batchReport.error||'部分人物缺少有效标签'), options.signal);
    calibrationResult.summary.modelResolvedCount += batchReport.modelResolvedCount;
    calibrationResult.summary.fallbackCount += batchReport.fallbackCount;
    calibrationResult.batchResults.push(batchReport);
    refreshSelectedNowResults();
    processedCount += batchCandidates.length;
    if (manualBackfill) {
      updateManualBackfillProgressStatus(processedCount, auditCandidates.length);
    } else {
      updateAutoCalibrationProgressStatus(processedCount, auditCandidates.length, deferredCandidates.length);
    }
  }

  calibrationResult.status = 'completed';
  if (manualBackfill) {
    const activeRemaining = countManualBackfillActiveRemaining();
    calibrationResult.message = activeRemaining === 0
      ? 'NPC标签校对完成：当前活跃NPC已全部完成模型校对'
      : `NPC标签校对完成：本轮处理 ${auditCandidates.length} 人，活跃未模型校对剩余 ${activeRemaining}`;
  } else {
    calibrationResult.message = '标签校准完成';
  }
  ceSetLastOffscreenTagCalibrationResult(calibrationResult);
  return changed;
}

function ceBuildRotatedOffscreenSelection(pool, cursor, count) {
  const normalizedPool = Array.isArray(pool) ? pool.slice() : [];
  if (normalizedPool.length === 0 || count <= 0) {
    return { selected: [], nextCursor: 0 };
  }
  const total = normalizedPool.length;
  const start = ((cursor % total) + total) % total;
  const limit = Math.min(count, total);
  const selected = [];
  for (let i = 0; i < limit; i += 1) {
    selected.push(normalizedPool[(start + i) % total]);
  }
  return {
    selected,
    nextCursor: (start + limit) % total
  };
}

// 普通后台选人复用当前名单、别名与三档待遇；不决定本轮补演范围。
function ceNormalizeOffscreenActivePolicy(config, saved) {
  if (config?.offscreenActivePolicy === 'legacy-zero') return 'legacy-zero';
  if (config?.offscreenActivePolicy === 'strict-v2') return 'strict-v2';
  return saved && !saved.offscreenActivePolicy && Number(saved.offscreenActiveLimit) === 0
    ? 'legacy-zero' : 'strict-v2';
}

function ceBuildOffscreenCanonPriorityContext(candidates, timeline, canonConfig) {
  const roster = typeof ceBridgeActiveRoleRoster === 'function' ? ceBridgeActiveRoleRoster(canonConfig) : {};
  const resolve = value => {
    const token = ceNormalizeImportantOriginalRoleToken(value);
    for (const [name, aliases] of Object.entries(roster)) {
      if ([name, ...(aliases || [])].some(alias => ceNormalizeImportantOriginalRoleToken(alias) === token)) return name;
    }
    return '';
  };
  const known = typeof ceBridgeKnownPeople === 'function' ? ceBridgeKnownPeople(timeline).canonNames : new Set();
  const knownTokens = new Set(Array.from(known || [], ceNormalizeImportantOriginalRoleToken));
  const dispatch = typeof ceBridgeProseDispatchConfig === 'function' ? ceBridgeProseDispatchConfig(canonConfig || {}) : {};
  const tiers = {}, names = {};
  for (const candidate of candidates) {
    const tokens = candidate.matchTokens || [candidate.name];
    const name = tokens.map(resolve).find(Boolean) || tokens.find(token => knownTokens.has(ceNormalizeImportantOriginalRoleToken(token)));
    if (!name) continue;
    names[candidate.id] = name;
    tiers[candidate.id] = dispatch.castTierResolver?.([name])?.get(name) || 'minor';
  }
  return { tiers, names, roster, coreNames: canonConfig?.coreCharacterNames || [], known: Array.from(known || []).sort() };
}

function ceCompareOffscreenActivePriority(a, b, context) {
  const rank = { core: 0, major: 1, minor: 2 };
  const band = (rank[context.tiers?.[a.id]] ?? 3) - (rank[context.tiers?.[b.id]] ?? 3);
  if (band) return band;
  const explicit = Number(context.explicitIds?.has(b.id)) - Number(context.explicitIds?.has(a.id));
  if (explicit) return explicit;
  const score = (context.scores[b.id] || 0) - (context.scores[a.id] || 0);
  if (score) return score;
  const recency = (a.tagState?.lastSelectedTurn ?? -1) - (b.tagState?.lastSelectedTurn ?? -1);
  if (recency) return recency;
  if (a.sourceIndex !== b.sourceIndex) return a.sourceIndex - b.sourceIndex;
  return String(a.id || '').localeCompare(String(b.id || ''), 'zh');
}

function ceSelectOffscreenActiveCandidates(eligible, context, config, cursor) {
  const limit = ceNormalizeOffscreenActiveLimit(config.offscreenActiveLimit);
  const ranked = eligible.slice().sort((a, b) => ceCompareOffscreenActivePriority(a, b, context));
  const protectedCandidates = ranked.filter(candidate => context.scores[candidate.id] > 0 || context.tiers[candidate.id] || context.explicitIds?.has(candidate.id));
  if (limit === 0 && ceNormalizeOffscreenActivePolicy(config) === 'legacy-zero') {
    return { selected: config.enableOffscreenActiveSelection === false ? ranked : protectedCandidates, nextCursor: cursor };
  }
  const selected = protectedCandidates.slice(0, limit);
  const selectedIds = new Set(selected.map(candidate => candidate.id));
  const pool = ranked.filter(candidate => !selectedIds.has(candidate.id));
  const remainSlots = Math.max(0, limit - selected.length);
  const rotation = ceBuildRotatedOffscreenSelection(pool, cursor, remainSlots);
  return { selected: selected.concat(rotation.selected), nextCursor: remainSlots > 0 ? rotation.nextCursor : cursor };
}

async function ceResolveOffscreenActiveRoster(options = {}) {
  const config = options.config || await loadConcurrentEvolutionConfig();
  const readOnly = options.readOnly === true;
  const abortSignal = options.signal || null;
  if (typeof ceThrowIfConcurrentEvolutionAborted === 'function') {
    ceThrowIfConcurrentEvolutionAborted(abortSignal);
  }
  if (!db?.archives?.get || !currentArchiveName) {
    return { activeIds: [], protectedIds: [], hardFrozenIds: [], softFrozenIds: [], candidates: [], activeReasonMap: {} };
  }

  const storyText = options.storyText !== undefined && options.storyText !== null
    ? String(options.storyText || '')
    : String(await getLastStoryFromArchive() || '');
  const userInput = options.userInput !== undefined && options.userInput !== null
    ? String(options.userInput || '')
    : String(typeof ceResolveUserInput === 'function' ? ceResolveUserInput('') : '');

  const loadedArchive = await db.archives.get(currentArchiveName);
  // Preview mutates only offscreen bookkeeping; history/images/worldbook stay read-only.
  const archive = readOnly && loadedArchive?.data?.state ? { ...loadedArchive, data: { ...loadedArchive.data,
    state: { ...loadedArchive.data?.state,
      concurrentEvolutionOffscreenState: structuredClone(loadedArchive.data?.state?.concurrentEvolutionOffscreenState || {}) }
  } } : loadedArchive;
  if (!archive?.data?.state) {
    return { activeIds: [], protectedIds: [], hardFrozenIds: [], softFrozenIds: [], candidates: [], activeReasonMap: {} };
  }

  const turnIndex = ceGetOffscreenArchiveTurnIndex(archive);
  const canonConfig = typeof ceBridgeLoadConfig === 'function' ? await ceBridgeLoadConfig() : (typeof ceBridgeLastConfig === 'object' ? ceBridgeLastConfig : {});
  // 读取整份既有年表身份；当前事件之外的已建档核心仍可普通后台演化。
  const timelineData = typeof wtLoadTimelineEntriesForInjection === 'function' ? await wtLoadTimelineEntriesForInjection() : { entries: [] };
  const canonPriority = ceBuildOffscreenCanonPriorityContext([], timelineData.entries || [], canonConfig);
  const cacheKey = ceBuildOffscreenRosterCacheKey(currentArchiveName, turnIndex, storyText, userInput, config)
    + JSON.stringify([canonPriority.roster, canonPriority.coreNames, canonPriority.known, config.offscreenActivePolicy]);
  if ((readOnly || (!options.skipModelCalibration && !options.forceRefresh)) && typeof window !== 'undefined' && window._ceOffscreenRosterCache?.key === cacheKey) {
    return JSON.parse(JSON.stringify(window._ceOffscreenRosterCache.value));
  }

  const resolvedState = ceEnsureOffscreenArchiveState(archive);
  const state = resolvedState;
  const beforeState = JSON.stringify(state);
  state.manualFrozenIds = ceNormalizeStringIdList(config.manualFrozenCharacterIds);
  const deletedIdSet = ceGetDeletedWorldBookIdSet() || new Set();
  const onScreenIds = new Set();
  if (currentState && currentState['0']) {
    Object.keys(currentState['0']).forEach(key => {
      if (key !== 'TIME_LOCATION_ROW') onScreenIds.add(String(key));
    });
  }
  if (currentState && currentState['7']) {
    Object.keys(currentState['7']).forEach(key => onScreenIds.add(String(key)));
  }

  const worldBookEntries = Array.isArray(archive.data.state.worldBookEntries)
    ? archive.data.state.worldBookEntries
    : [];
  const worldBookEntryMap = new Map();
  worldBookEntries.forEach(entry => {
    const entryId = String(entry && (entry.key || entry.id || entry.characterId || entry.charId) || '').trim();
    if (entryId) {
      worldBookEntryMap.set(entryId, entry);
    }
  });
  const candidates = [];
  worldBookEntries.forEach((entry, sourceIndex) => {
    if (!entry || typeof entry !== 'object') return;
    const entryId = String(entry.key || entry.id || entry.characterId || entry.charId || '').trim();
    if (!entryId || entryId === 'B1' || String(entryId).startsWith('P_')) return;
    if (ceIsWorldBookEntryDeleted(entry, deletedIdSet)) return;
    if (onScreenIds.has(entryId)) return;

    const entryType = String(entry.type || entry.category || '').trim().toLowerCase();
    if (entryType && !['人物', 'npc', '角色', 'character', ''].includes(entryType)) return;

    let data = null;
    try {
      data = typeof entry.content === 'string' ? JSON.parse(entry.content || '{}') : (entry.content || {});
    } catch (e) {
      data = null;
    }
    if (!data || typeof data !== 'object') return;

    const name = ceExtractOffscreenCandidateName(entry, data, entryId) || entryId;
    const explicitStateResult = ceResolveExplicitOffscreenTagState(state.npcTagState[entryId], data, { turnIndex });
    const currentTagState = explicitStateResult.tagState;
    const isDead = typeof isCharacterDead === 'function' ? isCharacterDead(entryId, 'npc', data) : String(data['4'] || '').includes('已死亡');
    candidates.push({
      id: entryId,
      entry,
      data,
      name,
      sourceIndex,
      tagState: currentTagState,
      isDead,
      isOnscreen: false,
      matchTokens: ceCollectOffscreenCandidateTokens(entry, data, name, entryId)
    });
    state.npcTagState[entryId] = currentTagState;
  });

  Object.assign(canonPriority, ceBuildOffscreenCanonPriorityContext(candidates, timelineData.entries || [], canonConfig));
  candidates.forEach(candidate => { candidate.canonTier = canonPriority.tiers[candidate.id] || ''; });
  const calibrationCandidates = candidates.slice();
  const calibrationCandidateIdSet = new Set(calibrationCandidates.map(candidate => candidate.id));
  let calibrationSourceIndex = worldBookEntries.length;
  if (currentState && currentState['0']) {
    Object.entries(currentState['0']).forEach(([key, row]) => {
      const entryId = String(row && row['0'] || key || '').trim();
      if (!entryId || entryId === 'B1' || entryId === 'TIME_LOCATION_ROW') return;
      if (calibrationCandidateIdSet.has(entryId)) return;
      if (ceIsBeastId(entryId)) return;
      const data = row && typeof row === 'object' ? row : null;
      if (!data) return;
      const entry = worldBookEntryMap.get(entryId) || null;
      const name = ceExtractOffscreenCandidateName(entry, data, entryId) || entryId;
      const explicitStateResult = ceResolveExplicitOffscreenTagState(state.npcTagState[entryId], data, { turnIndex });
      const currentTagState = explicitStateResult.tagState;
      const isDead = typeof isCharacterDead === 'function' ? isCharacterDead(entryId, 'npc', data) : String(data['4'] || '').includes('已死亡');
      calibrationCandidates.push({
        id: entryId,
        entry,
        data,
        name,
        sourceIndex: calibrationSourceIndex++,
        tagState: currentTagState,
        isDead,
        isOnscreen: true,
        matchTokens: ceCollectOffscreenCandidateTokens(entry, data, name, entryId)
      });
      calibrationCandidateIdSet.add(entryId);
      state.npcTagState[entryId] = currentTagState;
    });
  }

  let previewActiveIds = [];
  let previewActivePriorityIds = [];
  if (!options.skipModelCalibration && candidates.length > 0) {
    const previewStoryMentionIds = ceFindMentionedOffscreenIds(storyText, candidates);
    const previewUserMentionIds = ceFindMentionedOffscreenIds(userInput, candidates);
    const previewManualFrozenSet = new Set(state.manualFrozenIds || []);
    const previewProtectedIds = [];
    const previewProtectedPriorityMap = {};
    const previewImportantOriginalIds = new Set();
    const previewHardFrozenIds = [];
    const previewSoftFrozenIds = [];
    const previewProtectedTurnsMention = ceNormalizeOffscreenRecentTurns(config.offscreenRecentMentionProtectTurns, 2);
    const previewProtectedTurnsExit = ceNormalizeOffscreenRecentTurns(config.offscreenRecentExitProtectTurns, 2);

    candidates.forEach(candidate => {
      const tagState = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id]);
      let protectedScore = 0;

      if (previewUserMentionIds.has(candidate.id)) protectedScore += 300;
      if (previewStoryMentionIds.has(candidate.id)) protectedScore += 200;
      if (tagState.relationLevel === 'life_bound') protectedScore += 260;
      else if (tagState.relationLevel === 'core') protectedScore += 180;
      else if (tagState.relationLevel === 'close') protectedScore += 80;
      if (tagState.narrativeRole === 'bond_core') protectedScore += 160;
      else if (tagState.narrativeRole === 'plot_core') protectedScore += 140;
      else if (tagState.narrativeRole === 'important' || tagState.plotLevel === 'high') protectedScore += 70;
      if (tagState.lastExitTurn >= 0 && turnIndex - tagState.lastExitTurn <= previewProtectedTurnsExit) protectedScore += 120;
      if (tagState.lastMentionTurn >= 0 && turnIndex - tagState.lastMentionTurn <= previewProtectedTurnsMention) protectedScore += 80;
      const previewImportantOriginalRole = canonPriority.names[candidate.id] || '';
      const previewOriginalRoleProtected = !!previewImportantOriginalRole && !candidate.isDead && !['wrapped', 'finished', 'closed'].includes(tagState.arcStatus);
      if(previewOriginalRoleProtected)previewImportantOriginalIds.add(candidate.id);
      if (previewOriginalRoleProtected) protectedScore += 90;

      if (protectedScore > 0) {
        previewProtectedIds.push(candidate.id);
        previewProtectedPriorityMap[candidate.id] = protectedScore;
      }

      if (config.enableOffscreenFreeze !== false) {
        if (previewManualFrozenSet.has(candidate.id)) {
          previewHardFrozenIds.push(candidate.id);
          return;
        }
        if (config.offscreenFreezeExcludeDead !== false && candidate.isDead) {
          previewHardFrozenIds.push(candidate.id);
          return;
        }

        const roleFrozen = ['transient', 'tool'].includes(tagState.narrativeRole);
        const arcFrozen = ['wrapped', 'finished', 'closed'].includes(tagState.arcStatus);
        if (arcFrozen) {
          previewHardFrozenIds.push(candidate.id);
          return;
        }
        if (roleFrozen && protectedScore === 0 && !previewOriginalRoleProtected) {
          previewSoftFrozenIds.push(candidate.id);
        }
      }
    });

    const previewHardFrozenSet = new Set(previewHardFrozenIds);
    const previewSoftFrozenSet = new Set(previewSoftFrozenIds);
    const previewProtectedSet = new Set(previewProtectedIds);
    const previewEligibleCandidates = candidates.filter(candidate => {
      if (previewHardFrozenSet.has(candidate.id)) return false;
      if (previewSoftFrozenSet.has(candidate.id) && !previewProtectedSet.has(candidate.id)) return false;
      return true;
    });

    const previewStableEligible = previewEligibleCandidates.slice().sort((a, b) => {
      if (a.sourceIndex !== b.sourceIndex) return a.sourceIndex - b.sourceIndex;
      return String(a.id || '').localeCompare(String(b.id || ''), 'zh');
    });

    const previewSelection = ceSelectOffscreenActiveCandidates(previewStableEligible, {
      tiers: canonPriority.tiers,
      explicitIds: new Set([...(config.focusCharacterIds || []), ...previewUserMentionIds, ...previewStoryMentionIds]),
      scores: previewProtectedPriorityMap
    }, config, state.rotationCursor || 0);
    const previewActiveCandidates = previewSelection.selected;

    previewActiveIds = previewActiveCandidates.map(candidate => candidate.id);
    previewActivePriorityIds = options.manualBackfill
      ? []
      : previewActiveCandidates
        .filter(candidate => !previewUserMentionIds.has(candidate.id) && !previewStoryMentionIds.has(candidate.id))
        .map(candidate => candidate.id);
  }

  if (!readOnly && !options.skipModelCalibration && calibrationCandidates.length > 0) {
    if (typeof ceThrowIfConcurrentEvolutionAborted === 'function') {
      ceThrowIfConcurrentEvolutionAborted(abortSignal);
    }
    await ceEnsureOffscreenRosterModelTagStates({
      archive,
      state,
      candidates: calibrationCandidates,
      turnIndex,
      storyText,
      userInput,
      config,
      scopeLabel: options.scopeLabel || '当前相关 NPC',
      manualBackfill: options.manualBackfill === true,
      activePriorityIdSet: previewActivePriorityIds,
      activeCandidateIdSet: previewActiveIds,
      signal: abortSignal
    });
    if (typeof ceThrowIfConcurrentEvolutionAborted === 'function') {
      ceThrowIfConcurrentEvolutionAborted(abortSignal);
    }
  }

  const storyMentionIds = ceFindMentionedOffscreenIds(storyText, candidates);
  const userMentionIds = ceFindMentionedOffscreenIds(userInput, candidates);
  const manualFrozenSet = new Set(state.manualFrozenIds || []);
  const hardFrozenIds = [];
  const softFrozenIds = [];
  const protectedIds = [];
  const protectedPriorityMap = {};
  const importantOriginalIds = new Set();
  const activeReasonMap = {};

  const protectedTurnsMention = ceNormalizeOffscreenRecentTurns(config.offscreenRecentMentionProtectTurns, 2);
  const protectedTurnsExit = ceNormalizeOffscreenRecentTurns(config.offscreenRecentExitProtectTurns, 2);

  candidates.forEach(candidate => {
    const tagState = ceNormalizeOffscreenNpcTagState(state.npcTagState[candidate.id]);
    let protectedScore = 0;
    const reasons = [];

    if (userMentionIds.has(candidate.id)) {
      protectedScore += 300;
      reasons.push('用户直提');
      tagState.lastMentionTurn = turnIndex;
    }
    if (storyMentionIds.has(candidate.id)) {
      protectedScore += 200;
      reasons.push('正文直提');
      tagState.lastMentionTurn = turnIndex;
    }
    if (tagState.relationLevel === 'life_bound') {
      protectedScore += 260;
      reasons.push('生死绑定');
    } else if (tagState.relationLevel === 'core') {
      protectedScore += 180;
      reasons.push('核心纠葛');
    } else if (tagState.relationLevel === 'close') {
      protectedScore += 80;
      reasons.push('密切关系');
    }
    if (tagState.narrativeRole === 'bond_core') {
      protectedScore += 160;
      reasons.push('关系核心');
    } else if (tagState.narrativeRole === 'plot_core') {
      protectedScore += 140;
      reasons.push('主线核心');
    } else if (tagState.narrativeRole === 'important' || tagState.plotLevel === 'high') {
      protectedScore += 70;
      reasons.push('剧情牵引');
    }
    if (tagState.lastExitTurn >= 0 && turnIndex - tagState.lastExitTurn <= protectedTurnsExit) {
      protectedScore += 120;
      reasons.push('最近退场保护');
    }
    if (tagState.lastMentionTurn >= 0 && turnIndex - tagState.lastMentionTurn <= protectedTurnsMention) {
      protectedScore += 80;
      reasons.push('最近提及保护');
    }

    const importantOriginalRole = canonPriority.names[candidate.id] || '';
    const originalRoleProtected = !!importantOriginalRole && !candidate.isDead && !['wrapped', 'finished', 'closed'].includes(tagState.arcStatus);
    if(originalRoleProtected)importantOriginalIds.add(candidate.id);
    tagState.isImportantOriginalRole = !!importantOriginalRole;
    tagState.importantOriginalRoleName = importantOriginalRole || '';
    if (originalRoleProtected) {
      protectedScore += 90;
      reasons.push('原著重要角色/' + (canonPriority.tiers[candidate.id] || 'minor'));
    }
    tagState.updatedAtTurn = turnIndex;
    state.npcTagState[candidate.id] = tagState;

    if (protectedScore > 0) {
      protectedIds.push(candidate.id);
      protectedPriorityMap[candidate.id] = protectedScore;
      activeReasonMap[candidate.id] = reasons.join('、');
    }

    if (config.enableOffscreenFreeze !== false) {
      if (manualFrozenSet.has(candidate.id)) {
        hardFrozenIds.push(candidate.id);
        activeReasonMap[candidate.id] = '手动冻结';
        return;
      }
      if (config.offscreenFreezeExcludeDead !== false && candidate.isDead) {
        hardFrozenIds.push(candidate.id);
        activeReasonMap[candidate.id] = '死亡冻结';
        return;
      }

      const roleFrozen = ['transient', 'tool'].includes(tagState.narrativeRole);
      const arcFrozen = ['wrapped', 'finished', 'closed'].includes(tagState.arcStatus);
      if (arcFrozen) {
        hardFrozenIds.push(candidate.id);
        activeReasonMap[candidate.id] = '剧情已杀青';
        return;
      }
      if (roleFrozen && protectedScore === 0 && !originalRoleProtected) {
        softFrozenIds.push(candidate.id);
        activeReasonMap[candidate.id] = arcFrozen ? '剧情已杀青' : '剧情工具角色';
      }
    }
  });

  const hardFrozenSet = new Set(hardFrozenIds);
  const softFrozenSet = new Set(softFrozenIds);
  const protectedSet = new Set(protectedIds);
  const eligibleCandidates = candidates.filter(candidate => {
    if (hardFrozenSet.has(candidate.id)) return false;
    if (softFrozenSet.has(candidate.id) && !protectedSet.has(candidate.id)) return false;
    return true;
  });

  const stableEligible = eligibleCandidates.slice().sort((a, b) => {
    if (a.sourceIndex !== b.sourceIndex) return a.sourceIndex - b.sourceIndex;
    return String(a.id || '').localeCompare(String(b.id || ''), 'zh');
  });

  const selection = ceSelectOffscreenActiveCandidates(stableEligible, {
    tiers: canonPriority.tiers,
    explicitIds: new Set([...(config.focusCharacterIds || []), ...userMentionIds, ...storyMentionIds]),
    scores: protectedPriorityMap
  }, config, state.rotationCursor || 0);
  const activeCandidates = selection.selected;
  const nextCursor = selection.nextCursor;

  const activeIds = ceNormalizeStringIdList(activeCandidates.map(candidate => candidate.id));
  activeIds.forEach(id => {
    const tagState = ceNormalizeOffscreenNpcTagState(state.npcTagState[id]);
    tagState.lastSelectedTurn = turnIndex;
    tagState.updatedAtTurn = turnIndex;
    state.npcTagState[id] = tagState;
    if (!activeReasonMap[id]) activeReasonMap[id] = '轮转补位';
  });

  state.activeIds = activeIds;
  state.rotationCursor = nextCursor;
  state.lastProtectedIds = ceNormalizeStringIdList(protectedIds);
  state.lastHardFrozenIds = ceNormalizeStringIdList(hardFrozenIds);
  state.lastSoftFrozenIds = ceNormalizeStringIdList(softFrozenIds);
  state.activeReasonMap = activeReasonMap;
  state.lastComputedTurn = turnIndex;
  state.lastStoryDigest = String(storyText || '').replace(/\s+/g, ' ').slice(-240);
  state.lastUserInputDigest = String(userInput || '').replace(/\s+/g, ' ').slice(-120);

  const afterState = JSON.stringify(state);
  if (typeof ceThrowIfConcurrentEvolutionAborted === 'function') {
    ceThrowIfConcurrentEvolutionAborted(abortSignal);
  }
  if (!readOnly && afterState !== beforeState) {
    await db.archives.put(archive);
  }

  const hardFrozenSetForResult = new Set(state.lastHardFrozenIds || []);
  const softFrozenSetForResult = new Set(state.lastSoftFrozenIds || []);
  const manualFrozenSetForResult = new Set(state.manualFrozenIds || []);
  const tagStateMap = {};
  Object.keys(state.npcTagState || {}).forEach(id => {
    tagStateMap[id] = ceNormalizeOffscreenNpcTagState(state.npcTagState[id]);
  });
  const result = {
    activeIds,
    protectedIds: state.lastProtectedIds,
    hardFrozenIds: state.lastHardFrozenIds,
    softFrozenIds: state.lastSoftFrozenIds,
    manualFrozenIds: state.manualFrozenIds,
    candidates: candidates.map(candidate => ({
      id: candidate.id,
      name: candidate.name,
      isDead: candidate.isDead,
      sourceIndex: candidate.sourceIndex,
      tagState: state.npcTagState[candidate.id] || ceNormalizeOffscreenNpcTagState(),
      isActive: activeIds.includes(candidate.id),
      isProtected: protectedSet.has(candidate.id),
      isHardFrozen: hardFrozenSetForResult.has(candidate.id),
      isSoftFrozen: softFrozenSetForResult.has(candidate.id),
      isManualFrozen: manualFrozenSetForResult.has(candidate.id)
    })),
    tagStateMap,
    activeReasonMap: Object.assign({}, activeReasonMap),
    turnIndex,
    activePolicy: ceNormalizeOffscreenActivePolicy(config),
    selectionEnabled: config.enableOffscreenActiveSelection !== false,
    freezeEnabled: config.enableOffscreenFreeze !== false,
    limit: ceNormalizeOffscreenActiveLimit(config.offscreenActiveLimit)
  };

  if (!readOnly && !options.skipModelCalibration && typeof window !== 'undefined') {
    window._ceOffscreenRosterCache = {
      key: cacheKey,
      value: JSON.parse(JSON.stringify(result))
    };
  }

  return result;
}

async function ceGetOffscreenActiveIdSet(options = {}) {
  const roster = await ceResolveOffscreenActiveRoster(options);
  return new Set(Array.isArray(roster.activeIds) ? roster.activeIds : []);
}

async function ceRecordOffscreenExitTurn(targetId) {
  const normalizedId = String(targetId || '').trim();
  if (!normalizedId || normalizedId === 'B1' || ceIsBeastId(normalizedId)) return false;
  if (!db?.archives?.get || !currentArchiveName) return false;

  try {
    const archive = await db.archives.get(currentArchiveName);
    if (!archive) return false;
    const state = ceEnsureOffscreenArchiveState(archive);
    const turnIndex = ceGetOffscreenArchiveTurnIndex(archive);
    const next = ceNormalizeOffscreenNpcTagState(state.npcTagState[normalizedId]);
    next.lastExitTurn = turnIndex;
    next.updatedAtTurn = turnIndex;
    state.npcTagState[normalizedId] = next;
    await db.archives.put(archive);
    ceClearOffscreenRosterCache();
    return true;
  } catch (e) {
    console.warn('[并发演化] 记录离场角色最近退场轮次失败:', normalizedId, e);
    return false;
  }
}

function ceApplyNpcTagStateToArchive(archive, targetId, charData, options = {}) {
  const normalizedId = String(targetId || '').trim();
  if (!normalizedId || normalizedId === 'B1' || ceIsBeastId(normalizedId)) return false;
  if (!archive || !charData || typeof charData !== 'object') return false;

  const state = ceEnsureOffscreenArchiveState(archive);
  const turnIndex = ceGetOffscreenArchiveTurnIndex(archive);
  const previous = ceNormalizeOffscreenNpcTagState(state.npcTagState[normalizedId]);
  const resolved = ceResolveExplicitOffscreenTagState(previous, charData, { turnIndex, markReviewed: true });
  const next = resolved.tagState;
  next.updatedAtTurn = turnIndex;

  if (!resolved.hasExplicitTags || !resolved.isComplete) {
    next.needsModelReview = true;
  }

  const shouldMarkOnscreen = options.markOnscreen === true || (
    options.markOnscreen !== false &&
    !!(currentState && currentState['0'] && currentState['0'][normalizedId])
  );
  if (shouldMarkOnscreen) {
    next.lastOnscreenTurn = turnIndex;
  }
  if (options.markExit === true) {
    next.lastExitTurn = turnIndex;
  }
  if (Object.prototype.hasOwnProperty.call(options, 'freezeReason')) {
    next.freezeReason = String(options.freezeReason || '').trim();
  }
  if (resolved.hasExplicitTags && resolved.isComplete) {
    next.tagSource = 'model';
    next.needsModelReview = false;
    next.lastModelAuditTurn = turnIndex;
  }

  if (JSON.stringify(previous) === JSON.stringify(next)) {
    return false;
  }
  state.npcTagState[normalizedId] = next;
  return true;
}

async function loadConcurrentEvolutionPresets() {
  var saved=await dbGet(CONCURRENT_EVOLUTION_PRESETS_KEY);
  var defaults=await frLoadDefaultAssets();
  /* ★★ 2026-11-06 玩家：「之前那一份预设就不要内置了，避免误导。之前那份可以说是废弃了。」
   *
   * 原来这里的兜底和适配基线都用 defaults.preset —— 那是旧的变量演化预设。
   * 旧预设已删除，变量演化预设的唯一内置来源改为 evolution-presets.json 的四套。
   *
   * 兜底与基线统一取「DS轻量版」（玩家当前实际在用的那一套）。
   * 找不到时退回四套里的第一套，避免任何情况下 undefined。
   *
   * 基线（referencePreset）的用途只是判断某条规则「是否仍是出厂原文」：
   * 未改过才允许自动升级，改过的记 custom_rule_preserved 原样保留。
   * 所以基线必须是与玩家内置预设同源的一份，换成新预设正好符合这个语义。
   */
  var builtinPresets=Array.isArray(defaults.evolutionPresets)?defaults.evolutionPresets:[];
  var baseline=builtinPresets.find(function(p){return p&&p.id==='fr-builtin-container:ds-light';})||builtinPresets[0]||null;
  if(!baseline){
    throw new Error('内置变量演化预设缺失：evolution-presets.json 未打入或为空，请重新导入完整安装包。');
  }
  var source=saved&&Array.isArray(saved.presets)?{...saved,presets:saved.presets.length?saved.presets:[baseline]}:{presets:[baseline],activePresetId:baseline.id};
  // 仅返回适配副本；升级读取不覆盖玩家存储，导出/主动保存沿原管理入口。
  var adapted={...source,presets:source.presets.map(function(p){return frAdaptEvolutionPreset(p,baseline);})};
  return frMergeEvolutionPresetCatalog(adapted, builtinPresets.map(function(p){return frAdaptEvolutionPreset(p,baseline);}));
}

async function saveConcurrentEvolutionPresets(presetsData) {
  try {
    await dbSet(CONCURRENT_EVOLUTION_PRESETS_KEY, frEvolutionPresetsForStorage(presetsData));
  } catch (e) {
    console.error('[并发演化] 保存预设失败:', e);
    throw e;
  }
}

// ===== Overlay 显示/隐藏辅助函数 =====
function showConcurrentEvolutionOverlay(overlay) {
  if (!overlay) return;
  overlay.classList.remove('hidden');
  overlay.classList.add('visible');
}

function hideConcurrentEvolutionOverlay(overlay) {
  if (!overlay) return;
  overlay.classList.remove('visible');
  overlay.classList.add('hidden');
}

function normalizeConcurrentEvolutionPresetName(name) {
  return String(name || '').trim().toLowerCase();
}

async function showConcurrentEvolutionPresetOverwriteConfirm(presetName, existingPreset) {
  const overlay = document.getElementById('concurrent-evo-preset-confirm-overlay');
  const titleEl = document.getElementById('ce-preset-confirm-title');
  const messageEl = document.getElementById('ce-preset-confirm-message');
  const hintEl = document.getElementById('ce-preset-confirm-hint');
  const okBtn = document.getElementById('ce-preset-confirm-ok');
  const cancelBtn = document.getElementById('ce-preset-confirm-cancel');
  const closeBtn = document.getElementById('ce-preset-confirm-close');

  const safeName = String(presetName || '').trim() || '未命名预设';
  const message = `检测到同名预设「${safeName}」。是否覆盖现有预设？`;

  if (!overlay || !titleEl || !messageEl || !okBtn || !cancelBtn || !closeBtn) {
    if (typeof showCustomConfirm === 'function') {
      return await showCustomConfirm(message);
    }
    return confirm(message);
  }

  titleEl.textContent = '覆盖同名预设';
  messageEl.textContent = message;
  if (hintEl) {
    hintEl.textContent = existingPreset && existingPreset.isBuiltIn
      ? '该预设为内置项，覆盖后将直接替换内容。'
      : '覆盖后将以导入内容替换现有预设，无法恢复。';
  }

  return new Promise(resolve => {
    const handleConfirm = () => finish(true);
    const handleCancel = () => finish(false);
    const handleOverlay = (e) => {
      if (e.target === overlay) {
        finish(false);
      }
    };

    function finish(result) {
      okBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
      closeBtn.removeEventListener('click', handleCancel);
      overlay.removeEventListener('click', handleOverlay);
      hideConcurrentEvolutionOverlay(overlay);
      resolve(result);
    }

    okBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
    closeBtn.addEventListener('click', handleCancel);
    overlay.addEventListener('click', handleOverlay);

    showConcurrentEvolutionOverlay(overlay);
  });
}

// Resolve per API-card rules without changing the globally selected preset.
const ceEvolutionRoutePresetFallbacks = new WeakMap();
async function ceResolveEvolutionRoutePreset(route, fallbackPreset, config) {
  // Dedicated canon conversion carries extra immutable scope rules.
  if (fallbackPreset?._frCanonConversionPreset === true) return fallbackPreset;
  const id = String(route && route.id || '');
  let boundId = '';
  try {
    const map = JSON.parse(localStorage.getItem('FR_EVOLUTION_ROUTE_PRESETS_V1') || '{}');
    boundId = id && typeof map[id] === 'string' ? map[id] : '';
  } catch (_) {}
  const base = fallbackPreset && ceEvolutionRoutePresetFallbacks.get(fallbackPreset) || fallbackPreset;
  if (!boundId) return base;
  const data = await loadConcurrentEvolutionPresets();
  const selected = (data?.presets || []).find(row => row.id === boundId);
  if (!selected) throw new Error('接口绑定的变量预设不存在，请重新选择：' + boundId);
  const mode = config?.variableUpdateMode === 'merged' ? 'merged' : 'staged';
  if (typeof frEvolutionPresetSupportsMode === 'function' && !frEvolutionPresetSupportsMode(selected, mode)) {
    throw new Error('接口绑定的变量预设与当前演化方式不兼容，请选择匹配预设');
  }
  const resolved = {...selected};
  if (base && typeof base === 'object') ceEvolutionRoutePresetFallbacks.set(resolved, base);
  return resolved;
}

async function getActiveConcurrentEvolutionPreset(options = {}) {
  const presetsData = await loadConcurrentEvolutionPresets();
  const config = await loadConcurrentEvolutionConfig();
  const presets = Array.isArray(presetsData?.presets) ? presetsData.presets : [];
  if (presets.length === 0) {
    throw new Error('未检测到并发演化预设。请先在“变量演化设置”中点击“导入预设”。');
  }
  const activeId = config.activePresetId || presetsData.activePresetId || '';
  let preset = presets.find(p => p.id === activeId);
  const mode=config.variableUpdateMode==='merged'?'merged':'staged';
  if(!frEvolutionPresetSupportsMode(preset,mode)){
    if(preset&&!frIsBuiltinEvolutionPreset(preset))throw new Error('当前自定义预设与'+(mode==='merged'?'合并':'分阶段')+'演化不兼容，请在变量演化设置中选择匹配的预设。');
    const compatible=frEvolutionModePreset(presets,activeId,mode);
    if(!compatible)throw new Error('没有与当前演化方式兼容的预设，请检查预设规则。');
    preset=compatible;config.activePresetId=preset.id;await saveConcurrentEvolutionConfig(config);
  }
  if (!preset) {
    preset = presets[0];
    config.activePresetId = preset.id;
    await saveConcurrentEvolutionConfig(config);
  }
  ensurePromptConfig(preset, 'original_timeline_evolution');
  return options.resolveRoute === false ? preset : ceResolveEvolutionRoutePreset(getApiConfigsToTry(config)[0], preset, config);
}

// ===== 检查函数 =====

async function isConcurrentEvolutionEnabled() {
  const config = await loadConcurrentEvolutionConfig();
  return !!(config && config.enabled === true && getApiConfigsToTry(config).length > 0);
}

// ===== 目标收集函数 =====

/**
 * 收集演化目标
 * @param {Object} config - 配置对象
 * @returns {Array} 演化目标数组，每个目标包含 sceneType 字段
 * 注: 手动模式仅处理重点列表；全选模式处理所有角色
 */
async function collectEvolutionTargets(config, options = {}) {
  const silent = options && options.silent === true;
  const log = (...args) => { if (!silent) console.log(...args); };
  const allTargets = [];
  const deletedIdSet = ceGetDeletedWorldBookIdSet();

  // 获取在场角色ID集合（用于判断sceneType）
  const onScreenIds = new Set();
  if (currentState && currentState['0']) {
    Object.keys(currentState['0']).forEach(key => {
      if (key !== 'B1') onScreenIds.add(key);
    });
  }
  // 灵兽也算在场
  if (currentState && currentState['7']) {
    Object.keys(currentState['7']).forEach(key => onScreenIds.add(key));
  }

  // 1. 主角 B1（始终在场）
  if (currentState && currentState['0'] && currentState['0']['B1']) {
    const playerData = currentState['0']['B1'];
    allTargets.push({
      id: 'B1',
      type: 'player',
      name: (playerData['1'] || '').split('|')[0] || '主角',
      data: playerData,
      biography: null,
      sceneType: 'onscene'  // 主角始终在场
    });
  }

  // 构建 pending ID 集合：登场判断刚创建/返场的角色，不应被删除过滤跳过
  const pendingNewIds = new Set();
  if (Array.isArray(window.pendingNewCharacterForConcurrentEvolution)) {
    window.pendingNewCharacterForConcurrentEvolution.forEach(e => {
      if (e && e.id) pendingNewIds.add(String(e.id));
    });
  }
  if (Array.isArray(window.pendingReentryForConcurrentEvolution)) {
    window.pendingReentryForConcurrentEvolution.forEach(e => {
      if (e && e.id) pendingNewIds.add(String(e.id));
    });
  }

  // 2. 灵兽（currentState['7']）- 始终在场
  if (currentState && currentState['7']) {
    Object.entries(currentState['7']).forEach(([id, beastData]) => {
      if (deletedIdSet && deletedIdSet.has(String(id))) {
        if (pendingNewIds.has(String(id))) {
          log(`[并发演化] 登场判断覆盖已删除灵兽标记: ${id}`);
        } else {
          log(`[并发演化] 跳过已删除灵兽: ${id}`);
          return;
        }
      }
      allTargets.push({
        id,
        type: 'beast',
        name: ((beastData['1'] || '').split('|')[0] || id).replace(/<[^>]*>/g, ''),  // 去除HTML标签
        data: beastData,
        biography: null,
        sceneType: 'onscene'  // 灵兽始终在场
      });
    });
  }

  // 2.5 在场NPC（从 currentState['0']，确保收集在场但可能没有传记的NPC）
  const addedIds = new Set(['B1']);  // 已添加的ID集合（主角已添加）
  // 记录已添加的灵兽ID
  if (currentState && currentState['7']) {
    Object.keys(currentState['7']).forEach(id => addedIds.add(id));
  }

  if (currentState && currentState['0']) {
    Object.entries(currentState['0']).forEach(([key, row]) => {
      const charId = row?.['0'] || key;
      if (addedIds.has(charId)) return;  // 跳过已添加的（主角、灵兽）
      if (charId === 'B1') return;  // 双重保险
      if (deletedIdSet && deletedIdSet.has(String(charId))) {
        if (pendingNewIds.has(String(charId))) {
          log(`[并发演化] 登场判断覆盖已删除标记: ${charId}`);
        } else {
          log(`[并发演化] 跳过已删除在场NPC: ${charId}`);
          return;
        }
      }

      const rawName = (row['1'] || '').split('|')[0] || charId;
      const name = rawName.replace(/<[^>]*>/g, '');  // 去除HTML标签

      allTargets.push({
        id: charId,
        type: 'npc',
        name: name,
        data: row,
        biography: null,  // 在场NPC可能没有传记
        sceneType: 'onscene'
      });
      addedIds.add(charId);
    });
  }

  // 3. NPC（从世界档案，补充离场NPC - 多数据源查询）
  // [简化] 移除 cacheIdSet 过滤，存档是唯一数据源
  const watchIds = ceGetDebugWatchIds();
  const watchSet = watchIds ? new Set(watchIds) : null;
  if (watchSet) {
    log(`[并发演化][watch] IDs: ${watchIds.join(', ')}`);
    ceLogWorldBookCacheWatchHits('并发演化', watchSet);
  }
  if (typeof currentArchiveName !== 'undefined' && currentArchiveName) {
    try {
      const worldBookEntries = await ceGetAuthoritativeWorldBookEntries({
        context: 'collectEvolutionTargets',
        throwOnMissing: true
      });
      const biographySources = [
        { key: 'archive.data.state.worldBookEntries', entries: worldBookEntries }
      ];

      log(`[并发演化] 世界档案数据源: archive.data.state.worldBookEntries(${worldBookEntries.length})`);

      for (const source of biographySources) {
        const stats = {
          total: 0,
          kept: 0,
          typeSkipped: 0,
          dupSkipped: 0,
          deletedSkipped: 0,
          parseFail: 0,
          watchHits: new Set()
        };
        for (const bio of source.entries) {
          stats.total++;
          // 支持多种键名（key/id/characterId）
          const bioKey = bio.key || bio.id || bio.characterId;
          if (!bioKey) continue;
          if (watchSet && watchSet.has(String(bioKey))) {
            log(`[并发演化][watch] source=${source.key} raw=${bioKey}`);
            stats.watchHits.add(String(bioKey));
          }

          // 类型过滤
          if (bio.type && bio.type !== '人物' && bio.type !== 'NPC' && bio.type !== '角色') {
            stats.typeSkipped++;
            continue;
          }
          if (deletedIdSet && ceIsWorldBookEntryDeleted(bio, deletedIdSet)) {
            if (pendingNewIds.has(String(bioKey))) {
              log(`[并发演化] 登场判断覆盖已删除世界档案标记: ${bioKey}`);
            } else {
              stats.deletedSkipped++;
              continue;
            }
          }
          // 跳过已添加的
          if (addedIds.has(bioKey)) {
            stats.dupSkipped++;
            continue;
          }

          try {
            const data = JSON.parse(bio.content || '{}');
            const isOnScreen = onScreenIds.has(bioKey);
            allTargets.push({
              id: bioKey,
              type: 'npc',
              name: bio.title || bio.name || bioKey,
              data,
              biography: bio,
              sceneType: isOnScreen ? 'onscene' : 'offscene'
            });
            addedIds.add(bioKey);
            log(`[并发演化] 从档案添加NPC: ${bioKey} (${isOnScreen ? '在场' : '离场'})`);
            stats.kept++;
          } catch (e) {
            stats.parseFail++;
            console.warn(`[并发演化] 解析角色档案失败: ${bioKey}`, e);
          }
        }
        const watchHitList = stats.watchHits.size > 0 ? Array.from(stats.watchHits).join(', ') : '无';
        log(`[并发演化] 源统计 ${source.key}: total=${stats.total}, kept=${stats.kept}, typeSkipped=${stats.typeSkipped}, dupSkipped=${stats.dupSkipped}, deletedSkipped=${stats.deletedSkipped}, parseFail=${stats.parseFail}, watchHits=${watchHitList}`);
      }
    } catch (e) {
      console.error('[并发演化] 读取权威世界档案失败:', e);
      throw e;
    }
  }

  // 登退场身份候选不受后台轮转/关注预算限制；这里只读收集，不授予变量写权。
  // 沿用上面的权威档案、类型、删除标记和可解析性筛选。
  if (options.entryCandidatesOnly === true) return allTargets;

  // 4. 根据变量演化模式过滤目标
  let targets = allTargets;
  const focusMode = getFocusSelectionMode(config);
  const focusIds = Array.isArray(config.focusCharacterIds) ? config.focusCharacterIds : [];

  if (options.backgroundActiveIds instanceof Set || Array.isArray(options.backgroundActiveIds)) {
    const activeIds = new Set(Array.from(options.backgroundActiveIds).map(String));
    targets = allTargets.filter(target => {
      if (target.id === 'B1' || target.type === 'beast' || target.sceneType === 'onscene') return true;
      if (pendingNewIds.has(String(target.id))) {
        target.ordinaryForeground = true;
        return true;
      }
      return activeIds.has(String(target.id));
    });
    log('[变量演化] 后台目标沿本轮限额名单收集，手动关注只参与选位优先。');
  } else if (focusMode === 'manual') {
    const focusSet = new Set(focusIds);
    focusSet.add('B1'); // 主角必选
    // 在场角色强制加入变量演化
    var onsceneAdded = 0;
    allTargets.forEach(function(t) {
      if (t.sceneType === 'onscene' && !focusSet.has(t.id)) {
        focusSet.add(t.id);
        onsceneAdded++;
      }
    });
    if (onsceneAdded > 0) {
      log('[变量演化] ' + onsceneAdded + ' 个在场角色自动加入变量演化');
    }
    // 返场角色强制加入（set命令被延迟，sceneType 仍为 offscene）
    if (window.lastEntryDecisionResult && Array.isArray(window.lastEntryDecisionResult.entries)) {
      window.lastEntryDecisionResult.entries.forEach(function(e) {
        if (e && e.id && e.type === 'reentry' && !focusSet.has(e.id)) {
          focusSet.add(e.id);
          log('[变量演化] 返场角色 ' + e.id + ' 自动加入变量演化');
        }
      });
    }
    // 新创建角色（含原著年表冷启动）强制加入，否则 manual 模式下会丢失 targetMap，后续只会留下摘要文本而不会真正按离场档案链落地
    if (Array.isArray(window.pendingNewCharacterForConcurrentEvolution)) {
      window.pendingNewCharacterForConcurrentEvolution.forEach(function(e) {
        if (e && e.id && !focusSet.has(e.id)) {
          focusSet.add(e.id);
          log('[变量演化] 新创建角色 ' + e.id + ' 自动加入变量演化');
        }
      });
    }
    targets = allTargets.filter(t => focusSet.has(t.id));
    if (focusSet.size > 0) {
      log('[变量演化] 手动模式，已选 ' + focusSet.size + ' 个角色');
    } else {
      log('[变量演化] 手动模式，未选择角色');
    }
  } else {
    if (config.skipDeadInAllFocus === true) {
      targets = allTargets.filter(t => !isCharacterDead(t.id, t.type, t.data));
      log(`[变量演化] 全选模式，跳过已死亡角色: ${allTargets.length} → ${targets.length}`);
    } else {
      targets = allTargets;
      log('[变量演化] 全选模式，包含所有角色');
    }
  }

  // 统计信息
  const onsceneCount = targets.filter(t => t.sceneType === 'onscene').length;
  const offsceneCount = targets.filter(t => t.sceneType === 'offscene').length;

  const focusSummary = focusMode === 'manual'
    ? (focusIds.length > 0 ? `(手动模式: ${focusIds.length} 个)` : '(手动模式: 0 个)')
    : (config.skipDeadInAllFocus === true ? '(全选模式: 跳过已死亡)' : '(全选模式)');

  log(`[并发演化] 收集到 ${targets.length} 个演化目标:`,
    `主角=${targets.filter(t => t.type === 'player').length}`,
    `灵兽=${targets.filter(t => t.type === 'beast').length}`,
    `NPC=${targets.filter(t => t.type === 'npc').length}`,
    `(在场=${onsceneCount}, 离场=${offsceneCount})`,
    focusSummary
  );

  return targets;
}

// ===== 上下文构建函数 =====

function ceResolveUserInputInfo(preferred) {
  if (preferred && preferred !== '无') {
    return { value: preferred, source: 'preferred' };
  }
  if (typeof window !== 'undefined' && window._ceLastUserInputFromDom && window._ceLastUserInputFromDom !== '无') {
    return { value: window._ceLastUserInputFromDom, source: 'dom_tracker' };
  }
  if (typeof lastUserInput !== 'undefined' && lastUserInput && lastUserInput !== '无') {
    return { value: lastUserInput, source: 'lastUserInput' };
  }
  if (typeof window !== 'undefined' && window.lastUserInput && window.lastUserInput !== '无') {
    return { value: window.lastUserInput, source: 'window.lastUserInput' };
  }
  if (typeof userInputCache !== 'undefined' && userInputCache && userInputCache !== '无') {
    return { value: userInputCache, source: 'userInputCache' };
  }
  if (typeof globalAddons !== 'undefined' && globalAddons.user_input_after) {
    return { value: globalAddons.user_input_after, source: 'globalAddons.user_input_after' };
  }
  try {
    if (typeof chat !== 'undefined' && Array.isArray(chat)) {
      for (let i = chat.length - 1; i >= 0; i--) {
        if (chat[i].is_user && chat[i].mes) {
          return { value: chat[i].mes, source: `chat[${i}]` };
        }
      }
    }
  } catch (e) {
    // 忽略获取失败
  }
  return { value: '', source: 'none' };
}

function ceResolveUserInput(preferred) {
  return ceResolveUserInputInfo(preferred).value;
}

function setupConcurrentEvolutionUserInputTracker() {
  if (typeof window === 'undefined' || window._ceUserInputTrackerAttached) return;

  const isTargetInput = (el) => {
    if (!el) return false;
    if (el instanceof HTMLTextAreaElement || el instanceof HTMLInputElement) {
      const placeholder = (el.placeholder || '').trim();
      const ariaLabel = (el.getAttribute('aria-label') || '').trim();
      const dataPlaceholder = (el.getAttribute('data-placeholder') || '').trim();
      return (
        placeholder.includes('输入你的行为或想法') ||
        ariaLabel.includes('输入你的行为或想法') ||
        dataPlaceholder.includes('输入你的行为或想法')
      );
    }
    if (el.isContentEditable) {
      const ariaLabel = (el.getAttribute('aria-label') || '').trim();
      const dataPlaceholder = (el.getAttribute('data-placeholder') || '').trim();
      return (
        ariaLabel.includes('输入你的行为或想法') ||
        dataPlaceholder.includes('输入你的行为或想法')
      );
    }
    return false;
  };

  const readValue = (el) => {
    if (!el) return '';
    if (el instanceof HTMLTextAreaElement || el instanceof HTMLInputElement) {
      return el.value || '';
    }
    if (el.isContentEditable) {
      return el.innerText || el.textContent || '';
    }
    return '';
  };

  const handler = (e) => {
    const target = e.target;
    if (!isTargetInput(target)) return;
    const value = readValue(target).trim();
    if (!value) return;
    window._ceLastUserInputFromDom = value;
  };

  document.addEventListener('input', handler, true);
  document.addEventListener('change', handler, true);
  document.addEventListener('keyup', handler, true);
  window._ceUserInputTrackerAttached = true;
  // console.log('[并发演化][user_input] 已挂载输入监听器');
}

// 从存档日志获取最后一条正文（用于测试面板）
async function getLastStoryFromArchive() {
  try {
    /* ★★★ 2026-11-03 玩家报：「正文提示词也没了」。
     *
     * 日志证据（render.log L5132）：
     *   [08:12:18][ERR] [并发演化] 获取存档正文失败: ReferenceError: getCurrentArchive is not defined
     *
     * `getCurrentArchive` 全项目**只有这一处用到，从来没有定义过**。
     * 这个函数一抛错就被 catch 吞成 ''，于是所有调用方拿到的正文是空串 ——
     * 「正文提示词」面板因此永远显示「还没有发出过正文请求」，
     * 补演/演化拿到的 storyText 也是空的。
     *
     * 修法：改用项目里通用的读档写法（db.archives.get(currentArchiveName)），
     * 全项目其它 20 多处都是这么读的。 */
    const archive = await db.archives.get(currentArchiveName);
    if (!archive?.data?.logs) return '';

    const validStoryLogs = archive.data.logs.filter(log =>
      log.type === 'ai' &&
      log.content &&
      typeof log.content === 'string' &&
      log.content.trim().length > 0
    );

    if (validStoryLogs.length === 0) return '';
    const raw = validStoryLogs[validStoryLogs.length - 1].content;
    return ceStripImagePromptBlocksFromHtml(raw);
  } catch (e) {
    console.warn('[并发演化] 获取存档正文失败:', e);
    return '';
  }
}

function buildSharedEvolutionContext(storyText, userInputOverride) {
  const userInputInfo = ceResolveUserInputInfo(userInputOverride);
  const cleanedStoryText = ceStripImagePromptBlocksFromHtml(storyText || '');
  const context = {
    storyText: cleanedStoryText || '',
    userInput: userInputInfo.value,
    currentTime: '',
    currentLocation: '',
    timeLocationRow: '',
    worldEvents: '',
    worldFactors: '',
    stateSnapshot: '',
    worldTimelineContext: '',
    originalTimelineContext: null,
    originalTimelineRawBlock: '',
    originalTimelineEvents: '',
    originalTimelineDigest: '',
    originalTimelineRange: '',
    originalTimelineMode: '',
    originalTimelineAnchor: '',
    originalTimelineSourceLabel: '',
    originalTimelinePlayerImpact: '',
    originalTimelineAudit: '',
    originalTimelineColdStartSummary: '',
    originalTimelineUnresolvedEntities: '',
    originalTimelineColdStartResult: null,
    originalTimelineCharacterCandidates: null,
    originalTimelineReferenceCandidates: null,
    originalTimelineEventTags: [],
    originalTimelineTriggerSource: '',
    originalTimelinePacket: null,
    originalTimelinePackets: [],
    originalTimelineLedgerSummary: '',
    originalEventAudit: '',
    originalEventLedgerState: '',
    originalReferenceVectorResults: null,
    originalCharacterVectors: '',
    originalItemVectors: '',
    originalTechniqueVectors: '',
    originalFactionVectors: '',
    originalLocationVectors: '',
    originalBeastVectors: '',
    originalReferenceVectors: '',
    _originalReferenceVectorCache: null,
    originalTimelineBasePacket: null,
    originalTimelineBatchReplayHistory: [],
    originalTimelineBatchReplayInstruction: '',
    originalTimelineProgressPointer: null,
    originalTimelineProgressKey: '',
    originalTimelineProgressSummary: '',
    originalTimelineReplayBoundary: null,
    originalTimelineReplayMode: '',
    originalTimelineReplayDeadline: '',
    originalTimelineReplayStoryReview: '',
    originalTimelineTurnSummaryHistory: []
  };

  // try {
  //   const preview = (context.userInput || '').toString().replace(/\s+/g, ' ').slice(0, 120);
  //   console.log(`[并发演化][user_input] source=${userInputInfo.source} length=${(context.userInput || '').length} preview="${preview}"`);
  // } catch (e) {
  //   console.log('[并发演化][user_input] 记录用户输入失败:', e);
  // }

  // 获取当前时间和地点
  if (currentState && currentState['4']) {
    const timeData = currentState['4'];
    let timeVal = timeData['0'] || '';

    // 处理对象格式（兜底）
    if (typeof timeVal === 'object' && timeVal !== null) {
      if (timeVal.year !== undefined) {
        timeVal = `${timeVal.year}年${timeVal.month || 1}月${timeVal.day || 1}日`;
      } else if (timeVal.time) {
        timeVal = timeVal.time;
      } else {
        // 避免格式化整个对象，只取第一个非id键的值
        const valueKeys = Object.keys(timeVal).filter(k => k !== 'id');
        if (valueKeys.length > 0) {
          timeVal = String(timeVal[valueKeys[0]]);
        } else {
          timeVal = JSON.stringify(timeVal);
        }
      }
    }

    // 从完整字符串中解析时间和地点
    // 格式: "0001年 05月 01日 14:15/天南/天罗国（合欢宗外门杂役区柴房地窖） 3850,2050"
    const fullTimeStr = String(timeVal);
    context.timeLocationRow = fullTimeStr;
    const slashIdx = fullTimeStr.indexOf('/');
    if (slashIdx > 0) {
      // 有分隔符，提取时间和地点
      context.currentTime = fullTimeStr.substring(0, slashIdx).trim();
      // 地点部分：去除末尾的坐标（如 "3850,2050"）
      let locationPart = fullTimeStr.substring(slashIdx + 1).trim();
      locationPart = locationPart.replace(/\s+\d+,\d+\s*$/, '').trim();
      context.currentLocation = locationPart;
    } else {
      // 无分隔符，尝试从 timeData['1'] 获取地点
      context.currentTime = fullTimeStr.replace(/\s+\d+,\d+\s*$/, '').trim();
      context.currentLocation = timeData['1'] || '未知';
    }
  }

  // 获取世界事件（如果有）
  if (currentState && currentState.state && currentState.state.worldEvents) {
    const events = currentState.state.worldEvents;
    if (Array.isArray(events)) {
      context.worldEvents = events.slice(-5).map(e => e.content || e).join('\n');
    }
  }

  try {
    if (typeof generatePrettySnapshotForAI === 'function') {
      context.stateSnapshot = generatePrettySnapshotForAI() || '';
    }
  } catch (e) {
    console.warn('[并发演化] 生成状态快照失败:', e);
  }

  return context;
}

function ceGetIndependentSimStateSafe() {
  try {
    if (typeof ensureIndependentState === 'function') {
      const sim = ensureIndependentState();
      if (sim && typeof sim === 'object') return sim;
    }
  } catch (e) {
    console.warn('[物品管理] 读取独立推演状态失败:', e);
  }

  const sim = currentState?.state?.independentSim;
  return sim && typeof sim === 'object' ? sim : null;
}

function ceReadCultivationBridgeRemarks(row) {
  if (!row || typeof row !== 'object') return {};
  try {
    if (typeof parseRemarksString === 'function') {
      return parseRemarksString(row['9'] || '');
    }
  } catch (e) {
    console.warn('[物品管理] 读取修炼桥接备注失败:', e);
  }
  try {
    return JSON.parse(row['9'] || '{}');
  } catch (e) {
    return {};
  }
}

function ceExtractCultivationBridgeNumber(value, fallback = 0) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const raw = String(value ?? '').trim();
  if (!raw) return fallback;
  const match = raw.match(/-?\d+(?:\.\d+)?/);
  if (!match) return fallback;
  const normalized = Number(match[0]);
  return Number.isFinite(normalized) ? normalized : fallback;
}

function ceNormalizeCultivationBridgeProgress(value, fallback = 0) {
  const normalized = ceExtractCultivationBridgeNumber(value, fallback);
  return Math.max(0, Math.min(100, Math.round(normalized)));
}

function ceNormalizeCultivationBridgeReserve(value, fallback = 0) {
  const normalized = ceExtractCultivationBridgeNumber(value, fallback);
  if (!Number.isFinite(normalized)) return fallback;
  return Math.max(0, Number(normalized.toFixed(2)));
}

function ceNormalizeCultivationBridgeRealm(realmRaw = '') {
  const raw = String(realmRaw || '').trim();
  if (!raw) return '';
  try {
    if (typeof ceNormalizeDisplayedRealmText === 'function') {
      return String(ceNormalizeDisplayedRealmText(raw, { mode: 'threshold' }) || raw).trim();
    }
  } catch (e) {
    console.warn('[物品管理] 规范修炼境界显示失败:', e);
  }
  return raw;
}

function ceIsCultivationMajorBarrierRealm(realmRaw = '') {
  const t = ceNormalizeCultivationBridgeRealm(realmRaw).replace(/\s+/g, '');
  if (!t) return false;
  if (/炼气/.test(t)) return /炼气(?:期)?(?:十三|13)层|炼气圆满|炼气巅峰/.test(t);
  return /(筑基|结丹|金丹|元婴|化神|炼虚|返虚|合体|大乘|渡劫)(?:大)?圆满|巅峰/.test(t);
}

function ceResolveCultivationBreakthroughThreshold(realmRaw = '') {
  return ceIsCultivationMajorBarrierRealm(realmRaw) ? 99 : 100;
}

function ceGetCultivationBaselineByRealm(realmRaw = '') {
  const t = ceNormalizeCultivationBridgeRealm(realmRaw).replace(/\s+/g, '');
  if (!t) {
    return { key: 'fallback', label: '未知小境界', baseDays: 1080 };
  }
  if (/凡人|凡躯|未入道/.test(t)) return { key: 'mortal_intro', label: '凡人引气入体', baseDays: 60 };
  if (/炼气/.test(t)) return { key: 'qi_stage', label: '炼气小境界', baseDays: 1080 };
  if (/筑基/.test(t)) return { key: 'zhuji_stage', label: '筑基小境界', baseDays: 5400 };
  if (/(结丹|金丹)/.test(t)) return { key: 'jiedan_stage', label: '结丹小境界', baseDays: 21600 };
  if (/元婴/.test(t)) return { key: 'yuanying_stage', label: '元婴小境界', baseDays: 72000 };
  if (/化神/.test(t)) return { key: 'huashen_stage', label: '化神小境界', baseDays: 288000 };
  if (/(炼虚|返虚|合体|大乘|渡劫|真仙|天仙|金仙|太乙|大罗|圣)/.test(t)) {
    return { key: 'high_realm', label: '炼虚及以上小境界', baseDays: 1200000 };
  }
  return { key: 'fallback', label: '未知小境界', baseDays: 1080 };
}

function ceNormalizeCultivationTimeAsciiText(rawText = '') {
  return String(rawText || '')
    .replace(/[０-９]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 65248))
    .replace(/：/g, ':')
    .replace(/\s+/g, ' ')
    .trim();
}

function ceInferCultivationRelativeDay(asciiText) {
  const text = String(asciiText || '');
  if (!text) return '';
  if (/月初|初旬|上旬|上半月|月前期/.test(text)) return '05';
  if (/月中|中旬|中期/.test(text)) return '15';
  if (/月末|月底|下旬|末旬|下半月|月后期/.test(text)) return '25';
  return '';
}

function ceInferCultivationRelativeHour(asciiText) {
  const text = String(asciiText || '');
  if (!text) return '';
  if (/凌晨|拂晓/.test(text)) return '03';
  if (/清晨|早晨|一早/.test(text)) return '06';
  if (/上午|早间/.test(text)) return '09';
  if (/中午|午时/.test(text)) return '12';
  if (/下午|午后/.test(text)) return '15';
  if (/傍晚|黄昏/.test(text)) return '18';
  if (/夜间|夜里|晚间/.test(text)) return '21';
  if (/深夜|午夜/.test(text)) return '23';
  return '';
}

function ceExtractCultivationComparableTimeInfo(rawText) {
  const asciiText = ceNormalizeCultivationTimeAsciiText(rawText);
  const match = asciiText.match(/(\d{4})\s*(?:年|[.\/-])\s*(\d{1,2})(?:\s*(?:月|[.\/-])\s*(\d{1,2}))?\s*(?:日|号)?/);
  if (!match) {
    return {
      value: '',
      monthValue: '',
      hasDay: false,
      hasTime: false,
      year: '',
      month: '',
      day: '',
      hour: '',
      minute: ''
    };
  }

  const year = String(match[1] || '').padStart(4, '0');
  const month = String(match[2] || '').padStart(2, '0');
  let day = match[3] ? String(match[3] || '').padStart(2, '0') : '';
  if (!day) {
    day = ceInferCultivationRelativeDay(asciiText);
  }

  const timeMatch = asciiText.match(/(?:\s|^)(\d{1,2})\s*(?::|点|时)\s*(\d{1,2})?/);
  let hour = timeMatch && timeMatch[1] ? String(timeMatch[1] || '').padStart(2, '0') : '';
  let minute = timeMatch && timeMatch[2] ? String(timeMatch[2] || '').padStart(2, '0') : '';
  if (!hour) {
    hour = ceInferCultivationRelativeHour(asciiText);
  }
  if (hour && !minute) {
    minute = '00';
  }

  return {
    value: [year, month, day || '00', hour || '00', minute || '00'].join('.'),
    monthValue: year + '.' + month,
    hasDay: !!day,
    hasTime: !!hour,
    year,
    month,
    day: day || '',
    hour: hour || '',
    minute: minute || ''
  };
}

function ceResolveCultivationElapsedDays(startText, endText) {
  const startInfo = ceExtractCultivationComparableTimeInfo(startText);
  const endInfo = ceExtractCultivationComparableTimeInfo(endText);
  if (!startInfo.monthValue || !endInfo.monthValue) return NaN;

  const startMonthIndex = Number(startInfo.year || 0) * 12 + Number(startInfo.month || 0);
  const endMonthIndex = Number(endInfo.year || 0) * 12 + Number(endInfo.month || 0);
  const monthDiff = endMonthIndex - startMonthIndex;
  if (!Number.isFinite(monthDiff) || monthDiff < 0) return NaN;

  if (startInfo.hasDay && endInfo.hasDay) {
    const startDate = Date.UTC(
      Number(startInfo.year || 0),
      Math.max(0, Number(startInfo.month || 1) - 1),
      Number(startInfo.day || 1),
      Number(startInfo.hour || 0),
      Number(startInfo.minute || 0)
    );
    const endDate = Date.UTC(
      Number(endInfo.year || 0),
      Math.max(0, Number(endInfo.month || 1) - 1),
      Number(endInfo.day || 1),
      Number(endInfo.hour || 0),
      Number(endInfo.minute || 0)
    );
    const diffMs = endDate - startDate;
    if (!Number.isFinite(diffMs) || diffMs < 0) return NaN;
    return diffMs / 86400000;
  }

  if (monthDiff === 0) return 0;
  return monthDiff * 30;
}

function ceGetCultivationAuthoritativeTimeText(stateToSync = currentState) {
  let raw = '';
  try {
    if (typeof ceGetAuthoritativeTimeLocationInfo === 'function') {
      const info = ceGetAuthoritativeTimeLocationInfo(stateToSync);
      raw = String(info?.timeText || info?.fullText || '').trim();
    }
  } catch (e) {}

  if (!raw && typeof window !== 'undefined') {
    try {
      raw = String(window.__ceAuthoritativeTimeLocationInfo?.timeText || window.__ceAuthoritativeTimeLocationInfo?.fullText || '').trim();
    } catch (e) {}
  }

  if (!raw) return '';
  const slashIndex = raw.indexOf('/');
  return slashIndex >= 0 ? raw.substring(0, slashIndex).trim() : raw;
}

function ceResolveCultivationProgressTimeGuard(currentProgress, nextProgress, runtimeState = null, options = {}) {
  const remarks = runtimeState?.remarks && typeof runtimeState.remarks === 'object'
    ? runtimeState.remarks
    : {};
  const authoritativeFloor = ceGetCultivationAuthoritativeProgressFloor(null, runtimeState);
  const normalizedCurrent = ceNormalizeCultivationBridgeProgress(currentProgress, 0);
  const normalizedNext = ceNormalizeCultivationBridgeProgress(nextProgress, normalizedCurrent);
  const guardedCurrent = Number.isFinite(authoritativeFloor)
    ? Math.max(authoritativeFloor, normalizedCurrent)
    : normalizedCurrent;
  const guardedNext = Number.isFinite(authoritativeFloor)
    ? Math.max(authoritativeFloor, normalizedNext)
    : normalizedNext;
  const progressDelta = guardedNext - guardedCurrent;
  const currentRealm = ceNormalizeCultivationBridgeRealm(runtimeState?.realmRaw || runtimeState?.currentRealm || '');
  const storedRealm = ceNormalizeCultivationBridgeRealm(
    options.lastRealm
    ?? remarks.lastCultivationProgressRealm
    ?? remarks.cultivationProgressRealm
    ?? ''
  );
  const currentTimeText = String(
    options.currentTimeText
    ?? runtimeState?.currentTimeText
    ?? ceGetCultivationAuthoritativeTimeText()
    ?? ''
  ).trim();
  const lastTimeText = String(
    options.lastTimeText
    ?? remarks.lastCultivationProgressTime
    ?? remarks.cultivationProgressTime
    ?? ''
  ).trim();

  const result = {
    progress: guardedNext,
    blocked: false,
    reason: '',
    currentTimeText,
    effectiveTimeText: lastTimeText || '',
    realm: currentRealm || storedRealm || '',
    requiredDays: 0,
    elapsedDays: NaN
  };

  if (progressDelta <= 0) {
    if (!result.effectiveTimeText && currentTimeText) {
      result.effectiveTimeText = currentTimeText;
    }
    return result;
  }

  if (options?.bypassTimeGuard === true) {
    result.effectiveTimeText = currentTimeText || lastTimeText;
    return result;
  }

  if (!currentTimeText) {
    result.progress = guardedCurrent;
    result.blocked = true;
    result.reason = 'missing_authoritative_time';
    return result;
  }

  if (!lastTimeText) {
    result.progress = guardedCurrent;
    result.blocked = true;
    result.reason = 'missing_progress_anchor';
    result.effectiveTimeText = currentTimeText;
    return result;
  }

  if (storedRealm && currentRealm && storedRealm !== currentRealm) {
    result.progress = guardedCurrent;
    result.blocked = true;
    result.reason = 'realm_changed_anchor_reset';
    result.effectiveTimeText = currentTimeText;
    return result;
  }

  const baseline = ceGetCultivationBaselineByRealm(currentRealm || runtimeState?.realmRaw || '');
  const majorBarrierMultiplier = ceIsCultivationMajorBarrierRealm(currentRealm || runtimeState?.realmRaw || '') ? 3 : 1;
  const requiredDays = Math.max(1, Math.ceil((Number(baseline?.baseDays || 1080) * majorBarrierMultiplier * progressDelta) / 100));
  const elapsedDays = ceResolveCultivationElapsedDays(lastTimeText, currentTimeText);
  result.requiredDays = requiredDays;
  result.elapsedDays = elapsedDays;

  if (!Number.isFinite(elapsedDays)) {
    result.progress = guardedCurrent;
    result.blocked = true;
    result.reason = 'unresolved_elapsed_time';
    return result;
  }

  if (elapsedDays < requiredDays) {
    result.progress = guardedCurrent;
    result.blocked = true;
    result.reason = 'insufficient_elapsed_time';
    return result;
  }

  result.effectiveTimeText = currentTimeText;
  return result;
}

function ceGetCultivationAuthoritativeProgressFloor(sim = null, runtimeState = null) {
  const remarks = runtimeState?.remarks && typeof runtimeState.remarks === 'object'
    ? runtimeState.remarks
    : {};
  const raw = Number(
    sim?.cultivationSession?.authoritativeStoryProgress
    ?? remarks.authoritativeStoryProgress
  );
  if (!Number.isFinite(raw)) return NaN;
  const lockedRealm = ceNormalizeCultivationBridgeRealm(
    sim?.cultivationSession?.authoritativeStoryRealm
    ?? remarks.authoritativeStoryRealm
    ?? ''
  );
  const currentRealm = ceNormalizeCultivationBridgeRealm(
    runtimeState?.realmRaw
    ?? sim?.cultivationSession?.entryRealmSnapshot
    ?? ''
  );
  if (lockedRealm && currentRealm && lockedRealm !== currentRealm) return NaN;
  return Math.max(0, Math.min(100, Math.round(raw)));
}

function ceExtractCultivationBridgeRuntimeState(sim = null) {
  const playerRow = currentState && currentState['0'] && currentState['0']['B1'];
  const remarks = ceReadCultivationBridgeRemarks(playerRow);
  const currentRealmRaw = (() => {
    try {
      if (typeof getCurrentCultivationRealmRaw === 'function') {
        return String(getCurrentCultivationRealmRaw() || '').trim();
      }
    } catch (e) {
      console.warn('[物品管理] 读取当前修炼境界失败:', e);
    }
    return String(sim?.cultivationSession?.entryRealmSnapshot || '').trim();
  })();
  const progressRaw = sim && sim.cultivationProgressSnapshot !== undefined && sim.cultivationProgressSnapshot !== null && sim.cultivationProgressSnapshot !== ''
    ? sim.cultivationProgressSnapshot
    : (remarks['修为进度'] ?? remarks.cultivationProgressSnapshot ?? remarks.cultivationProgress ?? 0);
  const reserveRaw = sim?.cultivationSession?.npcCultivationReserve ?? remarks.npcCultivationReserve ?? remarks.cultivationReserve ?? remarks.cultivationReserveSnapshot ?? 0;
  const authoritativeStoryProgress = Number(
    sim?.cultivationSession?.authoritativeStoryProgress
    ?? remarks.authoritativeStoryProgress
  );
  const authoritativeStoryRealm = String(
    sim?.cultivationSession?.authoritativeStoryRealm
    ?? remarks.authoritativeStoryRealm
    ?? ''
  ).trim();
  const authoritativeStorySource = String(
    sim?.cultivationSession?.authoritativeStorySource
    ?? remarks.authoritativeStorySource
    ?? ''
  ).trim();
  const runtimeState = {
    remarks,
    row: playerRow || null,
    realmRaw: currentRealmRaw,
    currentRealm: ceNormalizeCultivationBridgeRealm(currentRealmRaw),
    reserve: ceNormalizeCultivationBridgeReserve(reserveRaw, 0),
    authoritativeStoryProgress: Number.isFinite(authoritativeStoryProgress)
      ? Math.max(0, Math.min(100, Math.round(authoritativeStoryProgress)))
      : NaN,
    authoritativeStoryRealm: ceNormalizeCultivationBridgeRealm(authoritativeStoryRealm),
    authoritativeStorySource,
  };
  const authoritativeFloor = ceGetCultivationAuthoritativeProgressFloor(sim, runtimeState);
  const progress = ceNormalizeCultivationBridgeProgress(progressRaw, 0);
  runtimeState.authoritativeFloor = authoritativeFloor;
  runtimeState.breakthroughThreshold = ceResolveCultivationBreakthroughThreshold(runtimeState.currentRealm || currentRealmRaw);
  runtimeState.progress = Number.isFinite(authoritativeFloor) ? Math.max(authoritativeFloor, progress) : progress;
  return runtimeState;
}

function ceBuildIndependentCultivationBridgeText() {
  const sim = ceGetIndependentSimStateSafe();
  if (!sim || String(sim.mode || '').trim() !== 'cultivation') return '';

  const cultivationRuntime = ceExtractCultivationBridgeRuntimeState(sim);
  const actionKey = String(sim?.selectedAction || '').trim() || 'daily';
  const progress = cultivationRuntime.progress;
  const breakthroughThreshold = cultivationRuntime.breakthroughThreshold;
  const authoritativeFloor = cultivationRuntime.authoritativeFloor;
  const authoritativeRealm = String(cultivationRuntime.authoritativeStoryRealm || '').trim();
  const authoritativeSource = String(cultivationRuntime.authoritativeStorySource || '').trim();
  const session = sim?.cultivationSession || {};
  const currentRealm = (() => {
    try {
      if (typeof getCurrentCultivationRealmRaw === 'function') {
        return String(getCurrentCultivationRealmRaw() || '').trim();
      }
    } catch (e) {
      console.warn('[物品管理] 读取当前修炼境界失败:', e);
    }
    return String(session?.entryRealmSnapshot || '').trim();
  })();
  const displayRealm = String(cultivationRuntime.currentRealm || currentRealm || '未知境界').trim() || '未知境界';
  const consumptionDigest = String(
    sim?.lastCultivationConsumptionDigestSticky
    || sim?.lastCultivationConsumptionDigest
    || ''
  ).trim();
  const actionExt = String(sim?.lastCultivationActionExt || sim?.pendingCultivationActionExt || '').trim();
  const lastLingshiConsumedLower = Math.max(0, Math.round(Number(session?.lastRoundLingshiConsumedLower || 0)));

  const slotSnapshot = (() => {
    try {
      if (typeof getCultivationConsumableSlotSnapshot === 'function') {
        const list = getCultivationConsumableSlotSnapshot(sim);
        if (Array.isArray(list)) return list;
      }
    } catch (e) {
      console.warn('[物品管理] 读取修炼消耗槽快照失败:', e);
    }
    return [];
  })();

  const aggregateBlock = (() => {
    try {
      if (typeof buildCultivationSessionAggregateBlock === 'function') {
        return String(buildCultivationSessionAggregateBlock(sim) || '').trim();
      }
    } catch (e) {
      console.warn('[物品管理] 读取闭关聚合摘要失败:', e);
    }
    return '';
  })();

  const materialDigest = (() => {
    try {
      if (typeof buildCultivationMaterialEffectDigest === 'function') {
        return String(buildCultivationMaterialEffectDigest(sim, actionKey) || '').trim();
      }
    } catch (e) {
      console.warn('[物品管理] 读取材料生效摘要失败:', e);
    }
    return '';
  })();

  const slotLines = slotSnapshot.length > 0
    ? slotSnapshot.map((meta) => {
        const slotLabel = String(meta?.slotLabel || meta?.slot || '材料位').trim() || '材料位';
        const itemId = String(meta?.itemId || '').trim() || '未知ID';
        const name = String(meta?.name || itemId).trim() || itemId;
        const quantity = Math.max(0, Math.round(Number(meta?.quantity || 0)));
        const type = String(meta?.type || '未知').trim() || '未知';
        const quality = String(meta?.quality || '未知').trim() || '未知';
        return `- ${slotLabel} | ID:${itemId} | 名称:${name} | 数量:${quantity} | 类型:${type} | 品阶:${quality}`;
      }).join('\n')
    : '（当前无已装配消耗槽物品）';

  const lines = [
    '---',
    '【独立修炼桥接信息】',
    '- 若下述“真实消耗 / 灵石结算”已明确出现，本轮物品管理必须把它视为已发生事实。只能补齐对应的 consumeItem(...) / transferSpiritStones(...) / refreshItemData(...)，禁止反向补回库存。',
    '- 若某件物品不在“当前已装配消耗槽位”列表内，禁止仅凭模型猜测直接消耗背包中的其他丹药或材料。',
    '- 若剧情/快照已明确给出更高修为进度，必须把它视为 authoritative floor；禁止把角色修为回写到更低值。',
    `- 当前修炼动作:${actionKey}`,
    `- 当前修炼境界:${displayRealm}`,
    `- 当前修为进度:${progress}%`,
    `- 当前冲关阈值:${breakthroughThreshold}%`,
    `- 本回合灵石已结算:${lastLingshiConsumedLower > 0 ? `${lastLingshiConsumedLower}下品灵石` : '无'}`,
    '- 当前已装配消耗槽位：',
    slotLines,
  ];

  if (Number.isFinite(authoritativeFloor)) {
    lines.push(`- 剧情锁定保底进度:${authoritativeFloor}%${authoritativeRealm ? `（锁定境界:${authoritativeRealm}）` : ''}${authoritativeSource ? `｜来源:${authoritativeSource}` : ''}`);
  }
  if (cultivationRuntime.reserve > 0) {
    lines.push(`- 当前后台修炼储备:${cultivationRuntime.reserve}进度点`);
  }
  if (actionExt) {
    lines.push(`- 本轮补充说明:${actionExt}`);
  }
  if (consumptionDigest) {
    lines.push(`- 真实消耗摘要:${consumptionDigest}`);
  }
  if (materialDigest) {
    lines.push('【材料生效摘要】');
    lines.push(materialDigest);
  }
  if (aggregateBlock) {
    lines.push(aggregateBlock);
  }

  lines.push('- 若需要输出物品操作，优先使用上述槽位中的准确 itemId；灵石扣减优先使用 transferSpiritStones({"from":"B1","amount":N}) 形式。');
  return lines.join('\n');
}

function ceAddOriginalReferenceTypeScore(typeScores, type, delta) {
  if (!typeScores || !type) return;
  if (!Object.prototype.hasOwnProperty.call(typeScores, type)) {
    typeScores[type] = 0;
  }
  typeScores[type] += Number(delta || 0);
}

function ceApplyOriginalTimelineContextValues(values, sharedContext) {
  const targetValues = values || {};
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || null;
  targetValues['world_timeline_context'] = ctx.worldTimelineContext || ctx.originalTimelineRawBlock || (originalCtx && originalCtx.rawBlock) || '';
  targetValues['original_timeline_events'] = ctx.originalTimelineEvents || (originalCtx && originalCtx.eventTextBlock) || '';
  targetValues['original_timeline_digest'] = ctx.originalTimelineDigest || (originalCtx && originalCtx.eventDigest) || '';
  targetValues['original_timeline_range'] = ctx.originalTimelineRange || (originalCtx && originalCtx.rangeText) || '';
  targetValues['original_timeline_mode'] = ctx.originalTimelineMode || (originalCtx && originalCtx.modeText) || '';
  targetValues['original_timeline_anchor'] = ctx.originalTimelineAnchor || (originalCtx && originalCtx.anchorTime) || '';
  targetValues['original_timeline_source'] = ctx.originalTimelineSourceLabel || (originalCtx && originalCtx.sourceLabel) || '';
  targetValues['original_timeline_player_impact'] = ctx.originalTimelinePlayerImpact || (originalCtx && originalCtx.playerImpactSummary) || '待后续阶段判定';
  targetValues['original_timeline_audit'] = ctx.originalTimelineAudit || (originalCtx && originalCtx.auditSeed) || '';
  targetValues['original_timeline_cold_start_summary'] = ctx.originalTimelineColdStartSummary || '';
  targetValues['original_timeline_unresolved_entities'] = ctx.originalTimelineUnresolvedEntities || '';
  const originalReferenceEventValues = ceBuildOriginalReferenceEventPlaceholderValues(ctx);
  Object.keys(originalReferenceEventValues).forEach(key => {
    targetValues[key] = originalReferenceEventValues[key] || '';
  });
  targetValues['original_character_vectors'] = ctx.originalCharacterVectors || '';
  targetValues['original_item_vectors'] = ctx.originalItemVectors || '';
  targetValues['original_technique_vectors'] = ctx.originalTechniqueVectors || '';
  targetValues['original_faction_vectors'] = ctx.originalFactionVectors || '';
  targetValues['original_location_vectors'] = ctx.originalLocationVectors || '';
  targetValues['original_beast_vectors'] = ctx.originalBeastVectors || '';
  targetValues['original_reference_vectors'] = ctx.originalReferenceVectors || '';
  targetValues['original_character_vectors_full'] = ctx.originalCharacterVectorsFull || '';
  targetValues['original_item_vectors_full'] = ctx.originalItemVectorsFull || '';
  targetValues['original_technique_vectors_full'] = ctx.originalTechniqueVectorsFull || '';
  targetValues['original_faction_vectors_full'] = ctx.originalFactionVectorsFull || '';
  targetValues['original_location_vectors_full'] = ctx.originalLocationVectorsFull || '';
  targetValues['original_beast_vectors_full'] = ctx.originalBeastVectorsFull || '';
  targetValues['original_reference_full_blocks'] = ctx.originalReferenceFullBlocks || '';
  return targetValues;
}

function ceClearOriginalTimelineContextValues(values) {
  const targetValues = ceApplyOriginalTimelineContextValues(values, {});
  targetValues['original_timeline_player_impact'] = '';
  return targetValues;
}

function ceHasOriginalTimelinePromptContext(sharedContext) {
  const ctx = sharedContext || {};
  return !!(
    ctx.originalTimelineContext
    || String(ctx.worldTimelineContext || '').trim()
    || String(ctx.originalTimelineRawBlock || '').trim()
    || String(ctx.originalTimelineEvents || '').trim()
    || String(ctx.originalTimelineDigest || '').trim()
    || String(ctx.originalTimelineAnchor || '').trim()
  );
}

function ceShouldInjectOriginalTimelineContext(targetOrType, sharedContext) {
  const ctx = sharedContext || {};
  const type = String(typeof targetOrType === 'string'
    ? targetOrType
    : (targetOrType && targetOrType.type) || '').trim();
  if (!type) return false;
  if (type === 'original_timeline_evolution') return true;
  if (type === 'player') return false;
  if (ctx.originalTimelinePhaseReuseEnabled !== true) return false;
  if (!ceHasOriginalTimelinePromptContext(ctx)) return false;
  const allowedTypes = Array.isArray(ctx.originalTimelinePhaseReuseTypes) && ctx.originalTimelinePhaseReuseTypes.length > 0
    ? ctx.originalTimelinePhaseReuseTypes.map(function(item) {
        return String(item || '').trim();
      }).filter(Boolean)
    : ['npc', 'beast', 'item_management', 'misc_management', 'entry'];
  return allowedTypes.includes(type);
}

