function ceBuildOriginalReferenceSemanticTokens(values, options = {}) {
  const queue = Array.isArray(values) ? values.slice() : [values];
  const maxTokens = Math.max(8, Number(options.maxTokens || 48));
  const tokens = [];
  const seen = new Set();

  const pushToken = (value) => {
    if (tokens.length >= maxTokens) return;
    const normalized = ceNormalizeOriginalReferenceName(value);
    if (!normalized || normalized.length < 2 || normalized.length > 18) return;
    if (CE_ORIGINAL_REFERENCE_STOPWORDS.has(normalized)) return;
    if (seen.has(normalized)) return;
    seen.add(normalized);
    tokens.push(normalized);
  };

  while (queue.length > 0 && tokens.length < maxTokens) {
    const current = queue.shift();
    if (Array.isArray(current)) {
      current.forEach(item => queue.push(item));
      continue;
    }

    const raw = String(current || '').trim();
    if (!raw) continue;

    const normalized = ceNormalizeOriginalReferenceName(raw);
    if (normalized) {
      if (normalized.length <= 18) pushToken(normalized);
      const gramSource = normalized.length > 24
        ? (normalized.slice(0, 14) + normalized.slice(-8))
        : normalized;
      [2, 3].forEach(size => {
        if (gramSource.length < size) return;
        for (let i = 0; i <= gramSource.length - size && tokens.length < maxTokens; i++) {
          pushToken(gramSource.slice(i, i + size));
        }
      });
    }

    const rawTokens = raw.match(/[\u4e00-\u9fa5]{2,8}|[A-Za-z0-9_-]{2,24}/g) || [];
    rawTokens.forEach(token => {
      if (tokens.length >= maxTokens) return;
      pushToken(token);
    });
  }

  return tokens;
}

function ceComputeOriginalReferenceTokenOverlap(leftTokens, rightTokens) {
  const normalizeList = (input) => Array.from(new Set(
    (Array.isArray(input) ? input : [input])
      .map(item => ceNormalizeOriginalReferenceName(item))
      .filter(Boolean)
  ));
  const left = normalizeList(leftTokens);
  const right = normalizeList(rightTokens);
  if (!left.length || !right.length) return 0;

  let shared = 0;
  const rightSet = new Set(right);
  left.forEach(token => {
    if (rightSet.has(token)) shared += 1;
  });
  return shared > 0 ? (2 * shared) / (left.length + right.length) : 0;
}

function ceScoreOriginalReferenceSemanticAlignment(candidate, entry, candidateSemanticTokens = null) {
  if (!candidate || !entry) return 0;
  const candidateTokens = Array.isArray(candidateSemanticTokens) && candidateSemanticTokens.length
    ? candidateSemanticTokens
    : ceBuildOriginalReferenceSemanticTokens([
      candidate.raw,
      candidate.normalized,
      candidate.variants,
      candidate.matchedTitles,
      candidate.categoryTokens
    ], { maxTokens: 36 });
  const entryTokens = Array.isArray(entry.semanticTokens) && entry.semanticTokens.length
    ? entry.semanticTokens
    : ceBuildOriginalReferenceSemanticTokens([
      entry.title,
      entry.sourceLeaf,
      entry.sourceSegments,
      entry.variants,
      entry.categoryTokens,
      String(entry.content || '').slice(0, 240)
    ], { maxTokens: 60 });
  if (!candidateTokens.length || !entryTokens.length) return 0;

  const tokenOverlap = ceComputeOriginalReferenceTokenOverlap(candidateTokens, entryTokens);
  const categoryOverlap = ceComputeOriginalReferenceTokenOverlap(candidate.categoryTokens, entry.categoryTokens);
  const typeOverlap = ceComputeOriginalReferenceTokenOverlap(candidate.typeHints, entry.types);
  let score = 0;

  if (tokenOverlap >= 0.22) {
    score = 0.64 + Math.min((tokenOverlap - 0.22) * 0.35, 0.1);
  }
  if (categoryOverlap >= 0.34) {
    score = Math.max(score, 0.7 + Math.min((categoryOverlap - 0.34) * 0.2, 0.08));
  }
  if (score <= 0) return 0;
  if (typeOverlap > 0) score += Math.min(typeOverlap * 0.04, 0.04);
  return Math.min(Number(score.toFixed(4)), 0.82);
}

function ceBuildOriginalReferenceEventPlaceholderValues(sharedContext) {
  const ctx = sharedContext || {};
  const parsed = ceGetOriginalReferenceCandidatesFromContext(ctx, {
    referenceEntries: Array.isArray(ctx._originalReferenceVectorCache) ? ctx._originalReferenceVectorCache : []
  });
  const byType = parsed && parsed.byType ? parsed.byType : ceBuildEmptyOriginalReferenceBuckets();
  const personCandidates = ceGetOriginalTimelineCharacterCandidatesFromContext(ctx);
  const auditText = ceBuildOriginalTimelineAuditText(ctx);
  const ledgerStateText = ceBuildOriginalTimelineLedgerStateText(ctx);
  ctx.originalEventAudit = auditText;
  ctx.originalEventLedgerState = ledgerStateText;
  return {
    original_event_persons: ceFormatOriginalTimelineCharacterCandidateList(personCandidates, { limit: 8 }),
    original_event_items: ceFormatOriginalReferenceCandidateList(byType.item, { limit: 8 }),
    original_event_techniques: ceFormatOriginalReferenceCandidateList(byType.technique, { limit: 8 }),
    original_event_factions: ceFormatOriginalReferenceCandidateList(byType.faction, { limit: 8 }),
    original_event_locations: ceFormatOriginalReferenceCandidateList(byType.location, { limit: 8 }),
    original_event_beasts: ceFormatOriginalReferenceCandidateList(byType.beast, { limit: 8 }),
    original_event_audit: auditText,
    original_event_ledger_state: ledgerStateText
  };
}

async function ceBuildOriginalReferenceVectorCache(options = {}) {
  if (Array.isArray(options.referenceVectorCache)) {
    return options.referenceVectorCache;
  }

  if (!options.force) {
    const cached = ceBuildOriginalReferenceVectorCache._cache
      || (typeof window !== 'undefined' ? window._ceOriginalReferenceVectorCache : null);
    if (Array.isArray(cached)) return cached;
  }

  if (typeof db === 'undefined' || !db || !db.vectors) return [];

  const cache = [];
  try {
    await db.vectors.each(v => {
      const entry = ceBuildOriginalReferenceVectorEntry(v, options);
      if (entry) cache.push(entry);
    });
  } catch (e) {
    console.warn('[原著年表] 构建非人物全图鉴向量缓存失败:', e);
    return [];
  }

  ceBuildOriginalReferenceVectorCache._cache = cache;
  if (typeof window !== 'undefined') {
    window._ceOriginalReferenceVectorCache = cache;
  }
  return cache;
}

function ceBuildOriginalReferenceVectorEntry(vector, options = {}) {
  const item = vector || {};
  if (!item || item.outdatedTimestamp) return null;

  const sourceText = String(item.source || '').trim();
  if (sourceText.startsWith('人物传记')) return null;

  const rawSourceSegments = sourceText.split(/[\/\\]/).map(value => String(value || '').trim()).filter(Boolean);
  const sourceLeaf = rawSourceSegments.length > 0 ? rawSourceSegments[rawSourceSegments.length - 1] : sourceText;
  const titleText = String(item.title || '').trim() || sourceLeaf;
  const contentText = String(item.content || '').trim();
  if (!titleText || !contentText) return null;

  const parsedCategory = ceParseOriginalReferenceCategory(contentText, sourceText, titleText);
  const sourceTypes = ceResolveOriginalReferenceTypesFromSource(sourceText);
  let types = ceNormalizeOriginalReferenceTypes([...(parsedCategory.types || []), ...sourceTypes]);
  if (!types.length) {
    types = ceNormalizeOriginalReferenceTypes([
      ...sourceTypes,
      ...ceInferOriginalReferenceTypesFromName(titleText),
      ...ceInferOriginalReferenceTypesFromName(sourceLeaf),
      ...ceInferOriginalReferenceTypesFromName(sourceText)
    ]);
  }
  if (!types.length) return null;

  const normalizedTitle = ceNormalizeOriginalReferenceName(titleText);
  if (!normalizedTitle) return null;

  const sourceSegments = Array.from(new Set(
    rawSourceSegments
      .map(value => ceNormalizeOriginalReferenceName(value))
      .filter(Boolean)
      .filter(value => value !== normalizedTitle)
      .filter(value => value.length >= 2 && !CE_ORIGINAL_REFERENCE_STOPWORDS.has(value))
  ));

  const variants = Array.from(new Set([
    titleText,
    sourceLeaf,
    sourceText,
    ...rawSourceSegments
  ].map(value => ceNormalizeOriginalReferenceName(value)).filter(Boolean)));
  const scope = ceInferOriginalReferenceScope(item, sourceText);

  return {
    source: sourceText,
    sourceLeaf,
    sourceSegments,
    title: titleText,
    normalizedTitle,
    content: contentText,
    textBlock: '### ' + titleText + '\n' + contentText,
    types,
    primaryType: parsedCategory.primaryType || types[0] || '',
    categoryTokens: Array.isArray(parsedCategory.categoryTokens) ? parsedCategory.categoryTokens.slice() : [],
    variants,
    semanticTokens: ceBuildOriginalReferenceSemanticTokens([
      titleText,
      sourceLeaf,
      sourceSegments,
      Array.isArray(parsedCategory.categoryTokens) ? parsedCategory.categoryTokens : [],
      sourceText,
      contentText.slice(0, 240)
    ], { maxTokens: 60 }),
    scope,
    scopePriority: ceGetOriginalReferenceScopePriority(scope)
  };
}

function ceBuildOriginalTimelineAuditText(sharedContext) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const packet = ctx.originalTimelinePacket || ceBuildOriginalTimelinePacket(ctx);
  const personCandidates = ceGetOriginalTimelineCharacterCandidatesFromContext(ctx);
  const referenceCandidates = ceGetOriginalReferenceCandidatesFromContext(ctx);
  const byType = referenceCandidates && referenceCandidates.byType ? referenceCandidates.byType : ceBuildEmptyOriginalReferenceBuckets();
  const packetCodes = Array.isArray(packet && packet.eventCodes) ? packet.eventCodes : [];
  const packetTags = packet && packet.entityCandidates && Array.isArray(packet.entityCandidates.eventTags)
    ? packet.entityCandidates.eventTags
    : [];
  return [
    '审计种子: ' + (ctx.originalTimelineAudit || originalCtx.auditSeed || ''),
    '时间锚点: ' + (ctx.originalTimelineAnchor || originalCtx.anchorTime || ''),
    '注入模式: ' + (ctx.originalTimelineMode || originalCtx.modeText || ''),
    '命中范围: ' + (ctx.originalTimelineRange || originalCtx.rangeText || ''),
    packet && packet.source ? ('触发来源: ' + packet.source) : '',
    packetCodes.length ? ('事件编码: ' + packetCodes.slice(0, 4).join('、') + (packetCodes.length > 4 ? ' …' : '')) : '',
    packetTags.length ? ('事件标签: ' + packetTags.join('、')) : '',
    packet && packet.dedupeHash ? ('去重哈希: ' + packet.dedupeHash) : '',
    personCandidates.length ? ('人物候选: ' + personCandidates.slice(0, 8).map(item => item.raw || item.normalized).filter(Boolean).join('、')) : '',
    '非人物候选计数: 物品' + ((byType.item || []).length) + ' / 功法' + ((byType.technique || []).length) + ' / 势力' + ((byType.faction || []).length) + ' / 地点' + ((byType.location || []).length) + ' / 灵兽' + ((byType.beast || []).length)
  ].filter(Boolean).join('\n');
}

function ceBuildOriginalTimelineColdStartDeed(sharedContext, canonicalName, candidate) {
  const ctx = sharedContext || {};
  const packet = ctx.originalTimelinePacket || ctx.originalTimelineBasePacket || null;
  const timeText = String(
    ctx.originalTimelineAnchor
      || (packet && (packet.anchorTime || packet.rangeStart || packet.rangeEnd))
      || '未知时间'
  ).trim() || '未知时间';
  const nameVariants = Array.from(new Set([
    ...ceBuildOriginalTimelineNameVariants(canonicalName || ''),
    ...ceBuildOriginalTimelineNameVariants(candidate && (candidate.raw || candidate.name || candidate.normalized) || '')
  ])).filter(Boolean);
  const normalizeNarrativeText = function(rawText) {
    const cleanedLines = String(rawText || '')
      .replace(/^###\s+[^\n]+\n?/, '')
      .replace(/\r/g, '')
      .split(/\n+/)
      .map(function(line) {
        return String(line || '').trim();
      })
      .filter(function(line) {
        if (!line) return false;
        return !/^(?:时间|起始时间|结束时间|标题|简略版|原著版|关键人物|关键物品|关键地点|关键势力|关键功法|关键灵兽\/妖兽|触发条件|预期结果|后续状态|变异关注点|来源备注)\s*[:：]/.test(line);
      });
    return cleanedLines.join('；')
      .replace(/\[(?:E|e)-?\d+[^\]]*\]/g, '')
      .replace(/\b(?:E|e)-\d+\b/g, '')
      .replace(/\s+/g, ' ')
      .replace(/^[：:；;、，,\-\s]+|[：:；;、，,\-\s]+$/g, '')
      .trim();
  };
  const matchesCharacterText = function(rawText) {
    const normalized = ceNormalizeOriginalTimelineName(rawText);
    if (!normalized) return false;
    return nameVariants.some(function(variant) {
      return variant && normalized.includes(variant);
    });
  };
  const normalizedCanonicalName = ceNormalizeOriginalTimelineName(canonicalName || '');
  const familyRoleSuffix = ['父', '母', '兄', '弟', '姐', '妹', '嫂', '姑', '婶', '伯', '叔', '翁', '爷'].find(function(suffix) {
    return normalizedCanonicalName.endsWith(suffix);
  }) || '';
  const surnameHint = normalizedCanonicalName ? normalizedCanonicalName.charAt(0) : '';
  const matchesCharacterSubjectText = function(rawText) {
    const normalized = ceNormalizeOriginalTimelineName(rawText);
    if (!normalized) return false;
    if (matchesCharacterText(normalized)) return true;
    if (familyRoleSuffix && normalized.endsWith('之' + familyRoleSuffix)) {
      return !surnameHint || normalized.includes(surnameHint);
    }
    if (familyRoleSuffix && surnameHint && normalized.includes(surnameHint) && normalized.endsWith(familyRoleSuffix)) {
      return true;
    }
    return false;
  };
  const splitMinimalNarrativeSentences = function(rawText) {
    const normalized = normalizeNarrativeText(rawText);
    if (!normalized) return [];
    return normalized
      .replace(/([。！？；;])/g, '$1\n')
      .split(/\r?\n/)
      .map(function(line) {
        return String(line || '').trim();
      })
      .filter(function(line) {
        return !!line && line.length >= 2;
      });
  };
  const sanitizeBiographyLocationText = function(rawText) {
    return String(rawText || '')
      .replace(/\s+\d+,\d+\s*$/, '')
      .replace(/[，,]\s*\d+,\d+\s*$/, '')
      .replace(/\s+/g, ' ')
      .trim();
  };
  const hasPersonalActionCue = function(rawText) {
    const text = String(rawText || '').trim();
    if (!text) return false;
    return /(?:结识|目送|坐在|坐于|守在|赶往|赶到|赶回|乘着|乘坐|躺在|缩在|藏(?:进|起)?|收(?:起|下)?|交给|听着|望着|看着|担忧|准备|起身|出发|返回|跟随|遇见|见状|示意|收下|沉默|叹息|等候|照料|采|晒|收拾|记下|修炼|寻|奔|逃|赶|拿|带|说|想着|念着|盼着|忧心|期盼|惦念|伏在|卧在|站在|行至|走到|看见|听见|问起|答应|扶住|背着|抱着|送别|归家|离去|离村|赴|留意|盘算|蜷缩|驾车|赶车|编织|晾晒|交谈|照看)/.test(text);
  };
  const looksLikeWorldStateLine = function(rawText) {
    const text = String(rawText || '').trim();
    if (!text) return true;
    if (/^(?:家乡|故乡|村中|村外|村口|家中|屋内|屋外|院中|深夜的|夜色中的|暮色中的|晨雾里的|细雨中的|风雪中的|山路上|途中|路上|车厢内|洞内|洞外|四周|周围|空气里|天色|局势|世道|五里坡|青牛镇|无名山洞)/.test(text) && !hasPersonalActionCue(text)) {
      return true;
    }
    if (/(?:因[^，。；;]*而[^，。；;]*(?:生计艰难|人心惶惶|局势紧绷|草木皆兵)|细雨连绵|风声呜咽|夜色沉沉|气氛凝重|世道艰难|局势动荡)/.test(text) && !hasPersonalActionCue(text)) {
      return true;
    }
    return false;
  };
  const collectMinimalNarrativeCandidates = function(rawText, priority, source) {
    return splitMinimalNarrativeSentences(rawText)
      .map(function(sentence) {
        return String(sentence || '').trim();
      })
      .filter(function(sentence) {
        if (!sentence) return false;
        if (typeof ceIsBiographyDirtyMetaLine === 'function' && ceIsBiographyDirtyMetaLine(sentence)) {
          return false;
        }
        return matchesCharacterSubjectText(sentence) || matchesCharacterText(sentence);
      })
      .map(function(sentence) {
        let text = String(sentence || '').replace(/^[：:；;、，,\-\s]+|[：:；;、，,\-\s]+$/g, '').trim();
        if (!text) return null;
        if (typeof ceNormalizeBiographyContentText === 'function') {
          text = ceNormalizeBiographyContentText(text, canonicalName);
        }
        if (!text || ceIsBiographyTitleResidueText(text)) return null;
        if (looksLikeWorldStateLine(text)) return null;
        if (typeof ceIsBiographyDirtyMetaLine === 'function' && ceIsBiographyDirtyMetaLine(text)) {
          return null;
        }
        return {
          text,
          priority: Number(priority || 0),
          source: String(source || '').trim() || 'minimal_narrative'
        };
      })
      .filter(Boolean);
  };
  const collectMinimalStructuredCandidates = function(rawLine, priority, source) {
    const parsed = typeof ceParseOriginalTimelineStructuredResultLine === 'function'
      ? ceParseOriginalTimelineStructuredResultLine(rawLine)
      : null;
    if (!parsed) return [];
    const subjectText = String(parsed.subject || '').trim();
    if (!matchesCharacterSubjectText(subjectText)) return [];
    const compactText = typeof ceBuildOriginalTimelineStructuredCompactText === 'function'
      ? ceBuildOriginalTimelineStructuredCompactText(parsed)
      : [String(parsed.action || '').trim(), String(parsed.detail || '').trim()].filter(Boolean).join('，');
    let text = String(compactText || '').trim();
    if (!text) return [];
    if (typeof ceNormalizeBiographyContentText === 'function') {
      text = ceNormalizeBiographyContentText(text, canonicalName);
    }
    if (!text || ceIsBiographyTitleResidueText(text)) return [];
    if (looksLikeWorldStateLine(text)) return [];
    if (!matchesCharacterSubjectText(text) && !matchesCharacterText(text)) return [];
    return [{
      text,
      priority: Number(priority || 0),
      source: String(source || '').trim() || 'minimal_structured'
    }];
  };
  const buildCurrentEventFallbackCandidate = function(resolved) {
    const fallbackText = [
      resolved && resolved.brief,
      resolved && resolved.original,
      resolved && resolved.rawText
    ].map(function(text) {
      return splitMinimalNarrativeSentences(text)
        .map(function(sentence) {
          return String(sentence || '').replace(/^[：:；;、，,\-\s]+|[：:；;、，,\-\s]+$/g, '').trim();
        })
        .find(function(sentence) {
          if (!sentence) return false;
          if (typeof ceIsBiographyDirtyMetaLine === 'function' && ceIsBiographyDirtyMetaLine(sentence)) {
            return false;
          }
          const normalizedSentence = typeof ceNormalizeBiographyContentText === 'function'
            ? ceNormalizeBiographyContentText(sentence, canonicalName)
            : sentence;
          return !!normalizedSentence
            && !looksLikeWorldStateLine(normalizedSentence)
            && (matchesCharacterSubjectText(normalizedSentence) || matchesCharacterText(normalizedSentence));
        }) || '';
    }).find(Boolean);
    if (!fallbackText) return null;
    const text = typeof ceNormalizeBiographyContentText === 'function'
      ? ceNormalizeBiographyContentText(fallbackText, canonicalName)
      : fallbackText;
    if (!text || ceIsBiographyTitleResidueText(text) || looksLikeWorldStateLine(text) || (typeof ceIsBiographyDirtyMetaLine === 'function' && ceIsBiographyDirtyMetaLine(text))) {
      return null;
    }
    return {
      text,
      priority: 1,
      source: 'current_event_fallback'
    };
  };
  const matchedMinimalEvents = [];

  (Array.isArray(packet && packet.events) ? packet.events : []).forEach(function(item) {
    const resolved = typeof ceResolveOriginalTimelineEventDisplayData === 'function'
      ? ceResolveOriginalTimelineEventDisplayData(item)
      : (item || {});
    const keyCharacters = Array.isArray(resolved.keyCharacters) ? resolved.keyCharacters : [];
    const hasCharacterHit = keyCharacters.some(function(name) {
      return matchesCharacterSubjectText(name);
    }) || matchesCharacterSubjectText([
      resolved.title,
      resolved.brief,
      resolved.original,
      resolved.rawText
    ].filter(Boolean).join(' '));
    if (!hasCharacterHit) return;

    const locationText = (Array.isArray(resolved.keyLocations) && resolved.keyLocations.length > 0
      ? sanitizeBiographyLocationText(resolved.keyLocations[0])
      : '') || sanitizeBiographyLocationText(String(ctx.currentLocation || '').trim()) || '原著相关地点';
    const minimalCandidates = [];
    (Array.isArray(resolved.expectedResults) ? resolved.expectedResults : []).forEach(function(line) {
      minimalCandidates.push.apply(minimalCandidates, collectMinimalStructuredCandidates(line, 40, 'expected_result'));
    });
    (Array.isArray(resolved.followupState) ? resolved.followupState : []).forEach(function(line) {
      minimalCandidates.push.apply(minimalCandidates, collectMinimalStructuredCandidates(line, 30, 'followup_state'));
    });
    minimalCandidates.push.apply(minimalCandidates, collectMinimalNarrativeCandidates(resolved.brief, 20, 'brief'));
    minimalCandidates.push.apply(minimalCandidates, collectMinimalNarrativeCandidates(resolved.original, 15, 'original'));
    minimalCandidates.push.apply(minimalCandidates, collectMinimalNarrativeCandidates(resolved.rawText, 10, 'raw'));

    if (minimalCandidates.length === 0) {
      const fallbackCandidate = buildCurrentEventFallbackCandidate(resolved);
      if (fallbackCandidate) {
        minimalCandidates.push(fallbackCandidate);
      }
    }
    if (minimalCandidates.length === 0) return;

    minimalCandidates.sort(function(a, b) {
      const priorityDiff = Number(b && b.priority || 0) - Number(a && a.priority || 0);
      if (priorityDiff !== 0) return priorityDiff;
      const qualityDiff = ceScoreBiographyNarrativeQuality(String(b && b.text || '')) - ceScoreBiographyNarrativeQuality(String(a && a.text || ''));
      if (qualityDiff !== 0) return qualityDiff;
      return String(b && b.text || '').length - String(a && a.text || '').length;
    });
    const best = minimalCandidates[0] || null;
    if (!best) return;
    matchedMinimalEvents.push({
      locationText,
      summary: ceTruncateOriginalTimelineText(String(best.text || '').trim(), 140),
      priority: Number(best.priority || 0),
      source: String(best.source || '').trim() || 'minimal_event'
    });
  });

  if (matchedMinimalEvents.length > 0) {
    matchedMinimalEvents.sort(function(a, b) {
      const priorityDiff = Number(b && b.priority || 0) - Number(a && a.priority || 0);
      if (priorityDiff !== 0) return priorityDiff;
      const qualityDiff = ceScoreBiographyNarrativeQuality(String(b && b.summary || '')) - ceScoreBiographyNarrativeQuality(String(a && a.summary || ''));
      if (qualityDiff !== 0) return qualityDiff;
      return String(b && b.summary || '').length - String(a && a.summary || '').length;
    });
    const bestMatch = matchedMinimalEvents[0] || {};
    const locationText = sanitizeBiographyLocationText(String(bestMatch.locationText || '').trim()) || '原著相关地点';
    let summary = String(bestMatch.summary || '').trim();
    if (summary && typeof ceNormalizeBiographyContentText === 'function') {
      summary = ceNormalizeBiographyContentText(summary, canonicalName);
    }
    if (!summary || ceIsBiographyTitleResidueText(summary) || looksLikeWorldStateLine(summary)) return '';
    return '[' + timeText + '@' + locationText + '] ' + summary;
  }

  console.warn('[并发演化][原著人物诊断] cold_start_deed_missing_subject_bound_event', {
    canonicalName,
    candidateRaw: String(candidate && (candidate.raw || candidate.name || candidate.normalized) || '').trim() || canonicalName,
    timeText,
    packetEventCount: Array.isArray(packet && packet.events) ? packet.events.length : 0,
    reason: 'matched_event_without_current_event_record'
  });
  return '';
}

function ceBuildOriginalTimelineColdStartNpcRow(options) {
  const opts = options || {};
  const candidate = opts.candidate || {};
  const vectorMatch = opts.vectorMatch || {};
  const sharedContext = opts.sharedContext || {};
  const canonicalName = String(vectorMatch.canonicalName || candidate.raw || opts.targetId || '未知人物').trim() || '未知人物';
  const rawVectorContent = String(vectorMatch.content || '').replace(/^###\s+[^\n]+\n?/, '');
  const vectorSummary = ceTruncateOriginalTimelineText(rawVectorContent, 1200);
  const aliases = Array.from(new Set([
    ...ceBuildOriginalTimelineNameVariants(candidate.raw || canonicalName),
    ...ceBuildOriginalTimelineNameVariants(canonicalName)
  ])).filter(function(name) {
    return name && name !== ceNormalizeOriginalTimelineName(canonicalName);
  });
  const nameVariants = Array.from(new Set([
    ...ceBuildOriginalTimelineNameVariants(candidate.raw || canonicalName),
    ...ceBuildOriginalTimelineNameVariants(canonicalName)
  ])).filter(Boolean);
  const matchesCharacterText = function(rawText) {
    const normalized = ceNormalizeOriginalTimelineName(rawText);
    if (!normalized) return false;
    return nameVariants.some(function(variant) {
      return variant && normalized.includes(variant);
    });
  };
  const sourceText = [
    String(candidate.raw || candidate.name || candidate.normalized || '').trim(),
    String(vectorMatch.title || '').trim(),
    vectorSummary,
    String(sharedContext.originalTimelineDigest || '').trim(),
    String(sharedContext.originalTimelineEvents || '').trim()
  ].filter(Boolean).join('\n');
  const narrativeSentences = sourceText
    .replace(/\r/g, '\n')
    .split(/[\n。！？；;]+/)
    .map(function(line) {
      return String(line || '').trim();
    })
    .filter(function(line) {
      return !!line;
    });
  const trustedVectorText = (matchesCharacterText(vectorMatch.title || '')
    || ceNormalizeOriginalTimelineName(vectorMatch.title || '') === ceNormalizeOriginalTimelineName(canonicalName))
    ? rawVectorContent
    : '';
  const characterEvidenceSentences = narrativeSentences.filter(function(line) {
    return matchesCharacterText(line);
  });
  const attributeEvidenceText = [trustedVectorText, characterEvidenceSentences.join('\n')]
    .map(function(part) {
      return String(part || '').trim();
    })
    .filter(Boolean)
    .join('\n');
  const pickFirstMatch = function(regex) {
    const match = attributeEvidenceText.match(regex);
    return match ? String(match[1] || match[0] || '').trim() : '';
  };
  const nameHintText = [canonicalName, String(candidate.raw || candidate.name || '').trim()].filter(Boolean).join('|');
  const inferGenderText = function() {
    if (/(?:母|娘|夫人|婶|婆|姑|嫂|姐|妹|师姐|师妹|圣女|侍女)/.test(nameHintText)) return '女';
    if (/(?:父|爹|公|叔|伯|翁|爷|哥|弟|师兄|师弟|少主|公子|老者|老翁)/.test(nameHintText)) return '男';
    if (/(女修|女子|少女|仙子|师姐|师妹|圣女|夫人|娘子|她|其女)/.test(attributeEvidenceText)) return '女';
    if (/(男修|男子|少年|青年|老者|老翁|师兄|师弟|公子|少主|他|其子)/.test(attributeEvidenceText)) return '男';
    return '';
  };
  const extractExplicitIdentityText = function() {
    return pickFirstMatch(/(外门弟子|内门弟子|亲传弟子|核心弟子|杂役弟子|杂役|执事|护法|长老|峰主|阁主|谷主|宫主|殿主|堂主|家主|掌门|宗主|老祖|供奉|客卿|散修|医师|炼丹师|炼器师|阵法师|店主|掌柜|侍女|侍从|护卫|修士|凡人)/);
  };
  const extractExplicitRealmText = function() {
    const explicit = pickFirstMatch(/((?:凡人|炼气(?:期)?(?:[零一二两三四五六七八九十\d]{1,3}层)?|筑基(?:初期|中期|后期|大圆满|圆满|巅峰)?|(?:结丹|金丹)(?:初期|中期|后期|大圆满|圆满|巅峰)?|元婴(?:初期|中期|后期|大圆满|圆满|巅峰)?|化神(?:初期|中期|后期|大圆满|圆满|巅峰)?|(?:炼虚|返虚|合体|大乘|渡劫)(?:初期|中期|后期|大圆满|圆满|巅峰)?))/);
    if (!explicit) return '';
    return typeof ceNormalizeDisplayedRealmText === 'function'
      ? (ceNormalizeDisplayedRealmText(explicit) || explicit)
      : explicit;
  };
  const extractExplicitLinggenText = function() {
    return pickFirstMatch(/((?:天灵根|异灵根|[金木水火土风雷冰暗光]{1,5}灵根|双灵根|三灵根|杂灵根|资质[^\n，。；;]{0,12}))/);
  };
  const extractExplicitSpecialConstitutionText = function() {
    return pickFirstMatch(/((?:先天道体|剑体|灵体|圣体|宝体|毒体|战体|雷体|火体|寒体|冰体|阴体|阳体|真灵血脉|天妖血脉|龙族血脉|凤族血脉))/);
  };
  const extractExplicitPersonalityText = function() {
    const traits = ['沉稳', '谨慎', '冷静', '凌厉', '温婉', '豪迈', '孤僻', '老练', '机敏', '克制', '果决', '强势', '爽朗', '寡言', '敏锐', '坚毅', '冷峻', '圆滑'];
    const matched = traits.filter(function(tag) {
      return attributeEvidenceText.indexOf(tag) >= 0;
    });
    if (matched.length >= 2) return matched.slice(0, 2).join('、');
    if (matched.length === 1) return matched[0];
    return '';
  };

  const genderText = inferGenderText();
  let identityText = extractExplicitIdentityText();
  let realmText = extractExplicitRealmText();
  const linggenText = extractExplicitLinggenText();
  const specialConstitutionText = extractExplicitSpecialConstitutionText();
  const personalityText = extractExplicitPersonalityText();
  const primaryColdStartDeed = ceBuildOriginalTimelineColdStartDeed(sharedContext, canonicalName, candidate);
  if (!primaryColdStartDeed) {
    console.warn('[并发演化][原著人物诊断] cold_start_deed_missing_current_event_record', {
      canonicalName,
      targetId: String(opts.targetId || '').trim() || null,
      currentAnchor: String(sharedContext.originalTimelineAnchor || sharedContext.currentTime || '').trim() || null
    });
  }
  const biographyLines = [
    primaryColdStartDeed
  ].filter(Boolean);
  const deedSummary = biographyLines.length > 0
    ? String(biographyLines[0] || '').replace(/^\[[^\]]+\]\s*/, '').trim()
    : '';
  const deriveConservativeRoleDefaults = function() {
    const evidenceText = [
      nameHintText,
      attributeEvidenceText,
      deedSummary,
      String(sharedContext.originalTimelineDigest || '').trim(),
      String(sharedContext.originalTimelineEvents || '').trim()
    ].filter(Boolean).join('\n');
    const hasCultivatorSignal = /(?:炼气|筑基|结丹|金丹|元婴|化神|炼虚|返虚|合体|大乘|渡劫|修士|女修|男修|同门|师兄|师姐|师弟|长老|掌门|宗主|峰主|谷主|宫主|殿主|堂主|护法|执事|外门弟子|内门弟子|亲传弟子|核心弟子)/.test(evidenceText);
    const familySignal = /(?:父|爹|母|娘|兄|哥|弟|姐|妹|嫂|姑|婶|伯|叔|翁|爷)/.test(nameHintText);
    const mundaneSignal = /(?:凡人|村民|农户|乡民|百姓|平民|车夫|樵夫|猎户|店家|掌柜|伙计|家属|农家|贫户|居民)/.test(evidenceText);
    const deriveMundaneIdentityText = function() {
      const directVillageIdentityMatch = evidenceText.match(/((?:[\u4e00-\u9fa5A-Za-z0-9]{1,12}(?:村|镇|乡|屯|庄|堡))(?:村民|居民|百姓|农户|乡民))/);
      if (directVillageIdentityMatch) return String(directVillageIdentityMatch[1] || '').trim();
      const directUrbanIdentityMatch = evidenceText.match(/((?:[\u4e00-\u9fa5A-Za-z0-9]{1,12}(?:城|县|郡))(?:居民|百姓|平民))/);
      if (directUrbanIdentityMatch) return String(directUrbanIdentityMatch[1] || '').trim();
      const locationMatch = evidenceText.match(/([\u4e00-\u9fa5A-Za-z0-9]{1,12}(?:村|镇|乡|屯|庄|堡))/);
      if (locationMatch) return String(locationMatch[1] || '').trim() + '村民';
      if (/农户|农家|贫户/.test(evidenceText)) return '农户';
      if (/乡民/.test(evidenceText)) return '乡民';
      if (/百姓/.test(evidenceText)) return '百姓';
      if (/平民/.test(evidenceText)) return '平民';
      if (/村民/.test(evidenceText)) return '村民';
      if (/居民/.test(evidenceText)) return '居民';
      if (/凡人/.test(evidenceText)) return '凡人';
      return '';
    };
    const mundaneIdentityText = !hasCultivatorSignal ? deriveMundaneIdentityText() : '';
    const defaults = {
      realmText: '',
      identityText: ''
    };
    if (!hasCultivatorSignal && (familySignal || mundaneSignal || mundaneIdentityText)) {
      defaults.realmText = '凡人';
    }
    if (!hasCultivatorSignal && mundaneIdentityText) {
      defaults.identityText = mundaneIdentityText;
    } else if (!hasCultivatorSignal && mundaneSignal) {
      defaults.identityText = '凡人';
    }
    if (familySignal || mundaneSignal || defaults.identityText || defaults.realmText) {
      console.log('[并发演化][原著人物诊断] cold_start_identity_default', {
        canonicalName,
        familySignal,
        mundaneSignal,
        hasCultivatorSignal,
        mundaneIdentityText,
        selectedRealm: defaults.realmText || '',
        selectedIdentity: defaults.identityText || '',
        evidenceExcerpt: typeof ceTruncateOriginalTimelineText === 'function'
          ? ceTruncateOriginalTimelineText(evidenceText, 160)
          : String(evidenceText || '').slice(0, 160)
      });
    }
    return defaults;
  };
  const conservativeRoleDefaults = deriveConservativeRoleDefaults();
  if (!realmText && conservativeRoleDefaults.realmText) {
    realmText = conservativeRoleDefaults.realmText;
  }
  if (!identityText && conservativeRoleDefaults.identityText) {
    identityText = conservativeRoleDefaults.identityText;
  } else if (
    conservativeRoleDefaults.identityText
    && /^(?:凡人|家属)$/.test(String(identityText || '').trim())
    && conservativeRoleDefaults.identityText !== String(identityText || '').trim()
  ) {
    identityText = conservativeRoleDefaults.identityText;
  }
  if (!realmText && /^(?:家属|凡人|店主|掌柜|侍女|侍从|护卫)$/.test(identityText)) {
    realmText = '凡人';
  }
  const extractSafeStatusText = function() {
    const statusEvidence = [attributeEvidenceText, deedSummary].filter(Boolean).join('；');
    if (!statusEvidence) return '一切正常';
    if (/(重伤|奄奄一息|濒死)/.test(statusEvidence)) return '身受重伤';
    if (/(轻伤|负伤|伤势|擦伤|带伤)/.test(statusEvidence)) return '身上带伤';
    if (/(昏迷|昏厥)/.test(statusEvidence)) return '昏迷中';
    if (/(中毒)/.test(statusEvidence)) return '中毒';
    if (/(疲惫|劳累|困倦|乏力|虚弱)/.test(statusEvidence)) return '略显疲惫';
    if (/(警惕|戒备|提防)/.test(statusEvidence)) return '保持警惕';
    if (/(惊魂未定|受惊|慌乱)/.test(statusEvidence)) return '惊魂未定';
    if (/(焦急|焦躁)/.test(statusEvidence)) return '心绪焦急';
    if (/(悲伤|悲痛|哀伤|忧虑)/.test(statusEvidence)) return '情绪低落';
    if (/(愤怒|恼怒)/.test(statusEvidence)) return '情绪激动';
    if (/(发热|寒冷|寒意|不适)/.test(statusEvidence)) return '身体不适';
    return '一切正常';
  };
  const seedStatusText = extractSafeStatusText();
  const eventAnchor = ceTruncateOriginalTimelineText(
    deedSummary || narrativeSentences[0] || (canonicalName + '与当前原著事件存在直接关联'),
    90
  );
  const backgroundSummaryParts = [
    vectorSummary || '',
    narrativeSentences.slice(0, 2).join('；') || '',
    identityText ? ('身份：' + identityText) : '',
    realmText ? ('修为：' + realmText) : ''
  ].map(function(part) {
    return String(part || '').trim();
  }).filter(Boolean).filter(function(part, index, arr) {
    return arr.indexOf(part) === index;
  });
  const backgroundSummary = ceTruncateOriginalTimelineText(
    backgroundSummaryParts.join('；') || (canonicalName + '相关背景暂缺'),
    600
  );
  const actionAnchor = ceTruncateOriginalTimelineText([
    sharedContext.currentLocation ? ('位置锚点：' + String(sharedContext.currentLocation || '').trim()) : '',
    sharedContext.originalTimelineAnchor ? ('时间锚点：' + String(sharedContext.originalTimelineAnchor || '').trim()) : '',
    deedSummary || ''
  ].filter(Boolean).join('|'), 200);
  const actionAppearanceText = (function() {
    const locationText = (String(sharedContext.currentLocation || '').trim() || '原著相关地点').replace(/\|/g, '／');
    let actionText = String(deedSummary || '').replace(/^\[[^\]]+\]\s*/, '').trim();
    if (actionText.startsWith(canonicalName)) {
      actionText = actionText.slice(canonicalName.length).trim();
    }
    actionText = actionText.replace(/^[：:；;、，,\-\s]+/, '').replace(/\|/g, '／').trim();
    if (!actionText) {
      actionText = '正在当前原著事件对应的时间点活动';
    }
    actionText = ceTruncateOriginalTimelineText(actionText, 40);
    return [actionText, '衣着未详', locationText, '身形待察', '样貌待察'].join('|');
  })();
  const remarks = {
    source_origin: 'original_timeline_seed',
    source_event_code: sharedContext.originalTimelineAudit || '',
    source_event_time: sharedContext.originalTimelineAnchor || '',
    source_vector_path: vectorMatch.source || '',
    source_vector_title: vectorMatch.title || '',
    canonical_name: canonicalName,
    aliases,
    cold_start_confidence: Number(vectorMatch.confidence || 0),
    first_seen_via: 'original_timeline_seed',
    original_timeline_cold_start: true,
    original_timeline_seed_mode: 'skeleton_only',
    pending_model_fill: true,
    schema_version: 'ce_original_timeline_seed_v5',
    background_anchor: backgroundSummary,
    action_anchor: actionAnchor,
    isBonded: false,
    equipment: JSON.stringify({}),
    inventory: JSON.stringify([]),
    skills: JSON.stringify([]),
    traits: JSON.stringify([]),
    gongfa: JSON.stringify([])
  };
  const remarksText = typeof serializeRemarksObject === 'function'
    ? serializeRemarksObject(remarks)
    : JSON.stringify(remarks);

  const row = {
    '0': opts.targetId,
    '1': genderText ? (canonicalName + '|' + genderText) : canonicalName,
    '4': seedStatusText,
    '9': remarksText,
    '10': backgroundSummary || (canonicalName + '与当前原著事件存在直接关联'),
    '16': actionAppearanceText,
    '35': biographyLines.join('\n\n')
  };

  if (realmText || identityText) {
    row['2'] = identityText
      ? ((realmText || '未知') + '|' + identityText)
      : realmText;
  }
  if (personalityText) row['3'] = personalityText;
  if (linggenText) row['5'] = linggenText;
  if (specialConstitutionText) row['6'] = specialConstitutionText;

  console.log('[并发演化][原著人物诊断] cold_start_row_seed', {
    targetId: String(opts.targetId || '').trim(),
    canonicalName,
    candidateRaw: String(candidate && (candidate.raw || candidate.name || candidate.normalized) || '').trim() || canonicalName,
    genderText: genderText || '',
    identityText: identityText || '',
    realmText: realmText || '',
    row1: String(row['1'] || '').trim(),
    row2: String(row['2'] || '').trim(),
    row2Missing: !String(row['2'] || '').trim(),
    willRelyOnModelBackfill: !(realmText || identityText),
    row4: String(row['4'] || '').trim(),
    row16: String(row['16'] || '').trim(),
    row35Preview: ceTruncateOriginalTimelineText(String(row['35'] || ''), 140),
    statusLooksLikeAction: /(?:正在|坐|乘|赶往|抵达|送别|结识|攥着|发呆|停留|跟随|守在|护送|同行|离开|返回|面临|身处)/.test(String(row['4'] || '').trim()),
    seedStatusText,
    eventAnchor,
    nameHintText: [canonicalName, String(candidate.raw || candidate.name || '').trim()].filter(Boolean).join('|'),
    trustedVectorApplied: !!trustedVectorText,
    trustedVectorTitle: String(vectorMatch.title || '').trim(),
    characterEvidenceCount: characterEvidenceSentences.length,
    attributeEvidencePreview: ceTruncateOriginalTimelineText(attributeEvidenceText, 220),
    sourceNarrativePreview: characterEvidenceSentences.slice(0, 4)
  });

  return row;
}

function ceBuildOriginalTimelineDirectActorFallbackVectorContent(sharedContext, candidate) {
  const ctx = sharedContext || {};
  const packet = ctx.originalTimelinePacket || ctx.originalTimelineBasePacket || null;
  const name = String(candidate && (candidate.raw || candidate.name || candidate.normalized) || '未知人物').trim() || '未知人物';
  const variants = Array.isArray(candidate && candidate.variants) && candidate.variants.length > 0
    ? candidate.variants
    : ceBuildOriginalTimelineNameVariants(name);
  const matchedEvents = (Array.isArray(packet && packet.events) ? packet.events : []).filter(function(event) {
    const keyCharacters = Array.isArray(event && event.keyCharacters) ? event.keyCharacters : [];
    const normalizedCharacters = keyCharacters.flatMap(function(item) {
      return ceBuildOriginalTimelineNameVariants(item);
    });
    if (normalizedCharacters.some(function(item) { return variants.includes(item); })) {
      return true;
    }
    const eventText = String(event && (event.text || event.original || event.brief) || '');
    return variants.some(function(variant) {
      return variant && eventText.includes(variant);
    });
  }).slice(0, 3);
  const eventSummary = matchedEvents.map(function(event, index) {
    const resolved = typeof ceResolveOriginalTimelineEventDisplayData === 'function'
      ? ceResolveOriginalTimelineEventDisplayData(event)
      : (event || {});
    const title = String(resolved && (resolved.title || resolved.brief || resolved.rawText || event && event.text) || '').trim() || ('事件' + (index + 1));
    const timeLabel = String(resolved && (resolved.timeStart || resolved.timeText || resolved.timeEnd) || '').trim();
    return (index + 1) + '. ' + [timeLabel, title].filter(Boolean).join(' ｜ ');
  }).filter(Boolean).join('\n');
  return [
    '### ' + name,
    '来源: 当前命中原著事件的直列角色回填建档',
    ctx.originalTimelineAnchor ? ('时间锚点: ' + ctx.originalTimelineAnchor) : '',
    ctx.originalTimelineDigest ? ('当前事件摘要: ' + ctx.originalTimelineDigest) : '',
    eventSummary ? ('相关事件:\n' + eventSummary) : '',
    ctx.originalTimelineEvents ? ('事件原文片段:\n' + ceTruncateOriginalTimelineText(String(ctx.originalTimelineEvents || ''), 900)) : ''
  ].filter(Boolean).join('\n\n');
}

function ceBuildOriginalTimelineColdStartSummary(result) {
  const data = result || {};
  const candidates = Array.isArray(data.candidates) ? data.candidates : [];
  const matched = Array.isArray(data.matched) ? data.matched : [];
  const created = Array.isArray(data.created) ? data.created : [];
  const unresolved = Array.isArray(data.unresolved) ? data.unresolved : [];
  const lines = [
    `原著关联人物建档统计：候选${candidates.length}，档案命中${matched.length}，新建${created.length}，暂未匹配${unresolved.length}`
  ];
  if (created.length) {
    lines.push('新建角色: ' + created.slice(0, 8).map(item => `${item.id}(${item.name})`).join('，'));
  }
  const unresolvedSummary = ceBuildOriginalTimelineUnresolvedSummary(data);
  if (unresolvedSummary) {
    lines.push('暂未匹配实体: ' + unresolvedSummary);
  }
  return lines.join('\n');
}

function ceBuildOriginalTimelineDigest(meta) {
  const lines = [];
  if (meta.modeText) lines.push('注入模式: ' + meta.modeText);
  if (meta.anchorTime) lines.push('时间锚点: ' + meta.anchorTime);
  if (meta.sourceLabel) lines.push('锚点来源: ' + meta.sourceLabel);
  if (meta.rangeText) lines.push('命中范围: ' + meta.rangeText);
  if (meta.itemText) lines.push('命中条目: ' + meta.itemText);
  return lines.join('\n');
}

function ceHashOriginalTimelineText(input) {
  const text = String(input || '');
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function ceNormalizeOriginalTimelineRangeEdges(rangeText, anchorTime) {
  const raw = String(rangeText || '').trim();
  const anchor = String(anchorTime || '').trim();
  if (!raw) {
    return { rangeStart: anchor, rangeEnd: anchor };
  }
  const segments = raw
    .split(/\s*(?:->|=>|→|~|～|—|–|至|到)\s*/)
    .map(item => String(item || '').trim())
    .filter(Boolean);
  if (segments.length >= 2) {
    return { rangeStart: segments[0], rangeEnd: segments[segments.length - 1] };
  }
  return { rangeStart: raw, rangeEnd: raw };
}

function ceInferOriginalTimelineModeText(modeText, rangeText, rawBlock) {
  const safeMode = String(modeText || '').trim();
  const safeModeLower = safeMode.toLowerCase();
  if (/^(?:batch|区间|批量|闭关|跳时|快进|跨度|skip_time|retreat)$/i.test(safeModeLower)) {
    return 'batch';
  }

  const rawText = String(rawBlock || '');
  const explicitModeMatch = rawText.match(/注入模式\s*[:：]\s*([^\n\r]+)/);
  const explicitMode = explicitModeMatch && explicitModeMatch[1]
    ? String(explicitModeMatch[1] || '').trim().toLowerCase()
    : '';
  if (/^(?:batch|区间|批量|闭关|跳时|快进|跨度|skip_time|retreat)$/i.test(explicitMode)) {
    return 'batch';
  }

  return 'single';
}

function ceMatchOriginalTimelineCrossMonthIntent(rawText) {
  const text = String(rawText || '').replace(/\s+/g, '');
  if (!text) return null;

  const retreatMatch = text.match(/闭关|出关/i);
  if (retreatMatch) {
    return {
      source: 'retreat',
      reason: 'retreat_keyword',
      matchedText: retreatMatch[0] || ''
    };
  }

  const skipMatch = text.match(/时光流转|时间跳跃|跳过时间|时间快进|跳时|快进|批量补演|区间补演|skip_time|timeskip|time_skip|(?:[一二三四五六七八九十百千万两俩0-9]+(?:年|个月|月|日|天))(?:后|之后)/i);
  if (skipMatch) {
    return {
      source: 'skip_time',
      reason: 'skip_keyword',
      matchedText: skipMatch[0] || ''
    };
  }

  return null;
}

function ceBuildOriginalTimelineYearText(year) {
  const numeric = Number(year || 0);
  if (!Number.isFinite(numeric)) return String(year || '').trim();
  const sign = numeric < 0 ? '-' : '';
  return sign + String(Math.abs(Math.trunc(numeric))).padStart(4, '0');
}

function ceBuildOriginalTimelineMonthText(year, month) {
  const numericMonth = Math.max(1, Math.min(12, parseInt(month, 10) || 1));
  return ceBuildOriginalTimelineYearText(year) + '.' + String(numericMonth).padStart(2, '0');
}

function ceBuildOriginalTimelineComparableText(parts = {}) {
  const yearText = ceBuildOriginalTimelineYearText(parts.year || 0);
  const monthText = String(parts.month || '').trim().padStart(2, '0');
  if (!yearText || !monthText) return '';
  let text = yearText + '.' + monthText;
  if (parts.hasDay && parts.day) {
    text += '.' + String(parts.day || '').trim().padStart(2, '0');
  }
  if (parts.hasTime && parts.hour) {
    text += ' ' + String(parts.hour || '').trim().padStart(2, '0')
      + ':' + String(parts.minute || '00').trim().padStart(2, '0');
  }
  return text;
}

function ceBuildOriginalTimelineUtcDate(parts = {}) {
  const date = new Date(Date.UTC(0, 0, 1, 0, 0, 0, 0));
  date.setUTCFullYear(
    Number(parts.year || 0) || 0,
    Math.max(0, (Number(parts.month || 1) || 1) - 1),
    Math.max(1, Number(parts.day || 1) || 1)
  );
  date.setUTCHours(Number(parts.hour || 0) || 0, Number(parts.minute || 0) || 0, 0, 0);
  return date;
}

function ceNormalizeOriginalTimelineComparableTimeText(rawTime) {
  const info = ceExtractOriginalTimelineComparableTimeInfo(rawTime);
  if (!info || !info.monthValue) return String(rawTime || '').trim();
  return ceBuildOriginalTimelineComparableText({
    year: info.year || '',
    month: info.month || '',
    hasDay: !!info.hasDay,
    day: info.day || '',
    hasTime: !!info.hasTime,
    hour: info.hour || '',
    minute: info.minute || ''
  });
}

function ceExtractOriginalTimelineTimeLocationInfoFromStateLike(stateLike) {
  const state = stateLike && typeof stateLike === 'object' ? stateLike : null;
  if (!state || !state['4']) {
    return {
      timeText: '',
      locationText: '',
      fullText: ''
    };
  }
  const rows=state['4'];
  const row=Array.isArray(rows)?rows.find(r=>r?.id===TIME_LOCATION_ROW_ID)||rows[0]:rows[TIME_LOCATION_ROW_ID]||rows;
  return ceParseAuthoritativeTimeLocation(row?.['0'],row?.['1']);
}

function ceBuildOriginalTimelineReplayMonthPoint(rawText) {
  const info = ceExtractOriginalTimelineComparableTimeInfo(rawText);
  if (!info || !info.monthValue) return null;
  const year = Number(info.year || 0);
  const month = Math.max(1, Math.min(12, Number(info.month || 1) || 1));
  if (!Number.isFinite(year) || !Number.isFinite(month)) return null;
  return {
    year,
    month,
    index: year * 12 + (month - 1),
    text: ceBuildOriginalTimelineMonthText(year, month)
  };
}

function ceShiftOriginalTimelineComparableTime(rawTime, delta = {}) {
  const info = ceExtractOriginalTimelineComparableTimeInfo(rawTime);
  if (!info || !info.monthValue) return '';
  const monthShift = parseInt(delta.months, 10) || 0;
  const dayShift = parseInt(delta.days, 10) || 0;
  const hasDay = !!info.hasDay;
  const hasTime = !!info.hasTime;
  const date = ceBuildOriginalTimelineUtcDate({
    year: info.year || 0,
    month: info.month || 1,
    day: hasDay ? (info.day || 1) : 1,
    hour: hasTime ? (info.hour || 0) : 0,
    minute: hasTime ? (info.minute || 0) : 0
  });
  if (!Number.isFinite(date.getTime())) return '';
  if (monthShift !== 0) date.setUTCMonth(date.getUTCMonth() + monthShift);
  if (dayShift !== 0) date.setUTCDate(date.getUTCDate() + dayShift);
  return ceBuildOriginalTimelineComparableText({
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    hasDay: hasDay || dayShift !== 0,
    day: hasDay || dayShift !== 0 ? date.getUTCDate() : '',
    hasTime,
    hour: hasTime ? date.getUTCHours() : '',
    minute: hasTime ? date.getUTCMinutes() : ''
  });
}

function ceAccumulateOriginalTimelineReplayDuration(segmentText) {
  const text = String(segmentText || '').replace(/\s+/g, '');
  if (!text) return null;
  let months = 0;
  let days = 0;
  const matched = [];
  const tokenRegex = /([零一二两三四五六七八九十百千万俩\d]+)(年|个月|月|天|日)/g;
  let match;
  while ((match = tokenRegex.exec(text)) !== null) {
    const numberText = String(match[1] || '').trim().replace(/俩/g, '两');
    const value = /^\d+$/.test(numberText)
      ? parseInt(numberText, 10)
      : ceParseChineseNumber(numberText);
    if (!Number.isFinite(value) || value <= 0) continue;
    const unit = String(match[2] || '').trim();
    if (unit === '年') months += value * 12;
    else if (unit === '个月' || unit === '月') months += value;
    else if (unit === '天' || unit === '日') days += value;
    matched.push(match[0]);
  }
  if (months <= 0 && days <= 0) return null;
  return {
    months,
    days,
    matchedText: matched.join('') || text
  };
}

function ceResolveOriginalTimelineReplayDurationFromText(rawText) {
  const text = String(rawText || '').replace(/\s+/g, '');
  if (!text) return null;
  const unitPattern = '(?:[零一二两三四五六七八九十百千万俩\\d]+(?:年|个月|月|天|日))+';
  const patterns = [
    new RegExp('闭关[^。；，,\\n]{0,30}?(' + unitPattern + ')'),
    new RegExp('潜修[^。；，,\\n]{0,30}?(' + unitPattern + ')'),
    new RegExp('苦修[^。；，,\\n]{0,30}?(' + unitPattern + ')'),
    new RegExp('(?:时间快进|跳过时间|时间跳跃|跳时|快进|时光流转)[^。；，,\\n]{0,20}?(' + unitPattern + ')'),
    new RegExp('(' + unitPattern + ')(?:后|之后|以后)')
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (!match || !match[1]) continue;
    const parsed = ceAccumulateOriginalTimelineReplayDuration(match[1]);
    if (parsed) return parsed;
  }
  return null;
}

async function ceResolveOriginalTimelineReplayStartFromArchive(sharedContext, currentTime) {
  const currentText = ceNormalizeOriginalTimelineComparableTimeText(currentTime);
  if (!currentText || !db?.archives?.get || !currentArchiveName) return '';
  try {
    const archive = await db.archives.get(currentArchiveName);
    const logs = Array.isArray(archive && archive.data && archive.data.logs) ? archive.data.logs : [];
    for (let i = logs.length - 1; i >= 0; i--) {
      const log = logs[i];
      if (!log || !log.stateSnapshot) continue;
      let parsed = null;
      try {
        parsed = typeof log.stateSnapshot === 'string'
          ? JSON.parse(log.stateSnapshot)
          : log.stateSnapshot;
      } catch (e) {
        continue;
      }
      const stateRoot = parsed && typeof parsed === 'object' && parsed.currentState
        ? parsed.currentState
        : parsed;
      const snapshotInfo = ceExtractOriginalTimelineTimeLocationInfoFromStateLike(stateRoot);
      const snapshotTime = ceNormalizeOriginalTimelineComparableTimeText(snapshotInfo && snapshotInfo.timeText ? snapshotInfo.timeText : '');
      if (!snapshotTime) continue;
      if (ceCompareOriginalTimelineComparableTime(snapshotTime, currentText) < 0) {
        return snapshotTime;
      }
    }
  } catch (e) {
    console.warn('[并发演化] 读取上一时间快照失败，回退用户输入推断:', e);
  }
  return '';
}

function ceResolveOriginalTimelineReplayStartFromIntent(sharedContext, currentTime) {
  const ctx = sharedContext || {};
  const currentText = ceNormalizeOriginalTimelineComparableTimeText(currentTime);
  if (!currentText) return '';
  const lastUserAction = typeof ceGetLastUserAction === 'function' ? ceGetLastUserAction() : null;
  const textCandidates = [
    ctx.userInput || '',
    lastUserAction && lastUserAction.content ? lastUserAction.content : '',
    lastUserAction && lastUserAction.label ? lastUserAction.label : '',
    lastUserAction && lastUserAction.reason ? lastUserAction.reason : ''
  ].filter(Boolean);
  for (const text of textCandidates) {
    const duration = ceResolveOriginalTimelineReplayDurationFromText(text);
    if (!duration) continue;
    const shifted = ceShiftOriginalTimelineComparableTime(currentText, {
      months: -duration.months,
      days: -duration.days
    });
    if (shifted && ceCompareOriginalTimelineComparableTime(shifted, currentText) < 0) {
      return shifted;
    }
  }
  return '';
}

async function ceResolveOriginalTimelineReplayWindow(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const triggerSource = String(options.triggerSource || ceInferOriginalTimelineTriggerSource(ctx) || '').trim();
  if (!['skip_time', 'retreat', 'manual_replay'].includes(triggerSource)) return null;
  const currentTime = ceNormalizeOriginalTimelineComparableTimeText(options.currentTime || ctx.currentTime || '');
  if (!currentTime) return null;
  const archiveStart = ceNormalizeOriginalTimelineComparableTimeText(
    await ceResolveOriginalTimelineReplayStartFromArchive(ctx, currentTime)
  );
  const intentStart = ceNormalizeOriginalTimelineComparableTimeText(
    ceResolveOriginalTimelineReplayStartFromIntent(ctx, currentTime)
  );
  const validCandidates = [archiveStart, intentStart].filter(function(candidate) {
    return !!candidate && ceCompareOriginalTimelineComparableTime(candidate, currentTime) < 0;
  });
  if (validCandidates.length === 0) return null;
  const startTime = validCandidates.reduce(function(best, current) {
    if (!best) return current;
    return ceCompareOriginalTimelineComparableTime(current, best) > 0 ? current : best;
  }, '');
  if (!startTime || ceCompareOriginalTimelineComparableTime(startTime, currentTime) >= 0) return null;
  const sourceLabelMap = {
    retreat: '闭关补演专用',
    skip_time: '跳时补演专用',
    manual_replay: '手动补演专用'
  };
  return {
    triggerSource,
    startTime,
    currentTime,
    sourceLabel: sourceLabelMap[triggerSource] || '区间补演专用',
    startSource: archiveStart && startTime === archiveStart
      ? 'archive_previous_snapshot'
      : (intentStart && startTime === intentStart ? 'user_input_duration' : 'unknown')
  };
}

async function ceLoadOriginalTimelineReplayEntries() {
  const fallbackFieldOrder = ['title', 'content_brief', 'content_original', 'time_start', 'time_end'];
  let entries = [];
  let fieldOrder = fallbackFieldOrder.slice();
  if (typeof worldEvolutionTimelineEntries !== 'undefined'
    && Array.isArray(worldEvolutionTimelineEntries)
    && worldEvolutionTimelineEntries.length > 0) {
    entries = JSON.parse(JSON.stringify(worldEvolutionTimelineEntries));
    if (typeof worldEvolutionTimelineFieldOrder !== 'undefined'
      && Array.isArray(worldEvolutionTimelineFieldOrder)
      && worldEvolutionTimelineFieldOrder.length > 0) {
      fieldOrder = worldEvolutionTimelineFieldOrder.slice();
    }
  } else if (typeof dbGet === 'function' && typeof WORLD_EVOLUTION_TIMELINE_CONFIG_V1 !== 'undefined') {
    try {
      const saved = await dbGet(WORLD_EVOLUTION_TIMELINE_CONFIG_V1);
      if (saved && Array.isArray(saved.entries)) {
        entries = JSON.parse(JSON.stringify(saved.entries));
        if (Array.isArray(saved.fieldOrder) && saved.fieldOrder.length > 0) {
          fieldOrder = saved.fieldOrder.slice();
        }
      }
    } catch (e) {}
  }
  return {
    entries: Array.isArray(entries) ? entries : [],
    fieldOrder: Array.isArray(fieldOrder) && fieldOrder.length > 0 ? fieldOrder : fallbackFieldOrder.slice()
  };
}

function ceBuildOriginalTimelineReplayEntrySpan(entry) {
  const item = entry && typeof entry === 'object' ? entry : {};
  const startPoint = ceBuildOriginalTimelineReplayMonthPoint(item.time_start !== undefined ? item.time_start : item.year_start);
  const endPoint = ceBuildOriginalTimelineReplayMonthPoint(item.time_end !== undefined ? item.time_end : item.year_end);
  if (!startPoint || !endPoint) return null;
  const minPoint = startPoint.index <= endPoint.index ? startPoint : endPoint;
  const maxPoint = startPoint.index <= endPoint.index ? endPoint : startPoint;
  return {
    minIndex: minPoint.index,
    maxIndex: maxPoint.index,
    startText: minPoint.text,
    endText: maxPoint.text
  };
}

function ceGetOriginalTimelineReplayFieldLabel(key) {
  const labelMap = {
    title: '标题',
    content_brief: '简略版',
    content_original: '原著版',
    time_start: '起始时间',
    time_end: '结束时间',
    time_single: '时间点'
  };
  return labelMap[key] || key;
}

function ceFormatOriginalTimelineReplayEntry(entry, fieldOrder) {
  const item = entry && typeof entry === 'object' ? entry : {};
  const span = ceBuildOriginalTimelineReplayEntrySpan(item);
  if (!span) return '';
  const effectiveFieldOrder = Array.isArray(fieldOrder) && fieldOrder.length > 0
    ? fieldOrder
    : ['title', 'content_brief', 'content_original', 'time_start', 'time_end'];
  const lines = [];
  if (span.startText === span.endText) {
    lines.push('时间: ' + span.startText);
  } else {
    lines.push('起始时间: ' + span.startText);
    lines.push('结束时间: ' + span.endText);
  }
  effectiveFieldOrder.forEach(function(key) {
    if (['time_start', 'time_end', 'year_start', 'year_end', 'content'].includes(String(key || ''))) return;
    const value = item[key];
    if (value === undefined || value === null) return;
    const text = String(value || '').trim();
    if (!text) return;
    lines.push(ceGetOriginalTimelineReplayFieldLabel(key) + ': ' + text);
  });
  return lines.length > 0 ? ('- ' + lines.join('\n  ')) : '';
}

async function ceBuildOriginalTimelineReplayPromptBlock(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const replayWindow = await ceResolveOriginalTimelineReplayWindow(ctx, options);
  if (!replayWindow) return '';
  const startPoint = ceBuildOriginalTimelineReplayMonthPoint(replayWindow.startTime);
  const endPoint = ceBuildOriginalTimelineReplayMonthPoint(replayWindow.currentTime);
  if (!startPoint || !endPoint) return '';
  const replayRangeStart = ceNormalizeOriginalTimelineComparableTimeText(replayWindow.startTime);
  const replayRangeEnd = ceNormalizeOriginalTimelineComparableTimeText(replayWindow.currentTime);
  const timelineData = await ceLoadOriginalTimelineReplayEntries();
  const normalizedRows = (Array.isArray(timelineData.entries) ? timelineData.entries : []).map(function(entry) {
    const span = ceBuildOriginalTimelineReplayEntrySpan(entry);
    if (!span) return null;
    return {
      entry,
      span,
      code: ceExtractOriginalTimelineEventDisplayCode(String(entry && entry.title || '').trim())
    };
  }).filter(Boolean).sort(function(a, b) {
    return (a.span.minIndex - b.span.minIndex) || (a.span.maxIndex - b.span.maxIndex);
  });
  const minIndex = Math.min(startPoint.index, endPoint.index);
  const maxIndex = Math.max(startPoint.index, endPoint.index);
  const picked = normalizedRows.filter(function(row) {
    return !(row.span.maxIndex < minIndex || row.span.minIndex > maxIndex);
  });
  const replayContext = Object.assign({}, ctx, {
    originalTimelineAnchor: replayRangeEnd,
    originalTimelineRange: replayRangeStart + ' -> ' + replayRangeEnd,
    originalTimelineMode: 'batch',
    originalTimelineSourceLabel: String(replayWindow.sourceLabel || ctx.originalTimelineSourceLabel || '').trim()
  });
  const replayPacket = {
    mode: 'batch',
    source: String(replayWindow.triggerSource || 'manual_replay').trim() || 'manual_replay',
    anchorTime: replayRangeEnd,
    rangeStart: replayRangeStart,
    rangeEnd: replayRangeEnd,
    timelineSourceLabel: replayContext.originalTimelineSourceLabel || '',
    events: picked.map(function(row) {
      const entry = row && row.entry ? row.entry : {};
      const span = row && row.span ? row.span : ceBuildOriginalTimelineReplayEntrySpan(entry);
      const startText = String(span && span.startText || entry && entry.time_start || '').trim();
      const endText = String(span && span.endText || entry && entry.time_end || '').trim();
      const title = String(entry && entry.title || '').trim();
      return {
        code: row && row.code ? row.code : ceExtractOriginalTimelineEventDisplayCode(title),
        title: title,
        timeText: startText && endText && startText === endText ? startText : '',
        timeStart: startText,
        timeEnd: endText,
        brief: String(entry && entry.content_brief || '').trim(),
        original: String(entry && entry.content_original || '').trim(),
        text: ''
      };
    })
  };
  const promptView = ceBuildOriginalTimelinePacketPromptView(replayPacket, {
    limit: picked.length || 1,
    context: replayContext
  });
  const block = ceBuildOriginalTimelinePacketRawBlock(replayPacket, {
    context: replayContext,
    promptView: promptView
  });
  const pickedItems = Array.from(new Set([
    ...(String(promptView.briefItemsText || '').trim() && promptView.briefItemsText !== '无'
      ? String(promptView.briefItemsText || '').split(',').map(function(item) { return String(item || '').trim(); }).filter(Boolean)
      : []),
    ...(String(promptView.originalItemsText || '').trim() && promptView.originalItemsText !== '无'
      ? String(promptView.originalItemsText || '').split(',').map(function(item) { return String(item || '').trim(); }).filter(Boolean)
      : [])
  ])).slice(0, 24);
  ceTraceDiag('ORIGINAL_TIMELINE_REPLAY_BLOCK', {
    triggerSource: replayWindow.triggerSource,
    startTime: replayRangeStart,
    endTime: replayRangeEnd,
    startSource: replayWindow.startSource,
    totalTimelineRows: normalizedRows.length,
    pickedCount: picked.length,
    pickedItems: pickedItems,
    blockPreview: String(block || '').slice(0, 900)
  });
  return block;
}

function ceInferOriginalTimelineTriggerSource(sharedContext) {
  const ctx = sharedContext || {};
  const lastUserAction = typeof ceGetLastUserAction === 'function' ? ceGetLastUserAction() : null;
  const action = String(lastUserAction && lastUserAction.action || '').trim().toLowerCase();
  const actionHintText = [
    action,
    lastUserAction && lastUserAction.via ? lastUserAction.via : '',
    lastUserAction && lastUserAction.mode ? lastUserAction.mode : '',
    lastUserAction && lastUserAction.label ? lastUserAction.label : '',
    lastUserAction && lastUserAction.reason ? lastUserAction.reason : '',
    lastUserAction && lastUserAction.content ? lastUserAction.content : ''
  ].filter(Boolean).join('\n');
  const userIntentText = [
    ctx.userInput || '',
    actionHintText
  ].filter(Boolean).join('\n');
  const explicitSourceText = [
    ctx.originalTimelineSourceLabel || '',
    ctx.originalTimelineMode || '',
    ctx.originalTimelineRange || '',
    ctx.originalTimelineRawBlock || ''
  ].filter(Boolean).join('\n');

  const userIntent = ceMatchOriginalTimelineCrossMonthIntent(userIntentText);
  if (userIntent) {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: userIntent.source,
      reason: userIntent.reason,
      matchedText: userIntent.matchedText || '',
      sourceFrom: 'user_input_or_action',
      userInputPreview: String(ctx.userInput || '').slice(0, 180),
      actionHintPreview: String(actionHintText || '').slice(0, 180)
    });
    return userIntent.source;
  }

  const explicitSource = ceMatchOriginalTimelineCrossMonthIntent(explicitSourceText);
  if (explicitSource) {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: explicitSource.source,
      reason: explicitSource.reason,
      matchedText: explicitSource.matchedText || '',
      sourceFrom: 'timeline_context',
      sourceLabel: String(ctx.originalTimelineSourceLabel || '').slice(0, 180),
      modeText: String(ctx.originalTimelineMode || '').slice(0, 120),
      rangeText: String(ctx.originalTimelineRange || '').slice(0, 160)
    });
    return explicitSource.source;
  }

  if (action.startsWith('manual_') || action.includes('snapshot') || action.includes('reroll')) {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: 'manual_replay',
      reason: 'manual_action_fallback',
      sourceFrom: 'last_user_action'
    });
    return 'manual_replay';
  }
  if (/timeskip|time_skip|skip_time|jump_time/.test(action)) {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: 'skip_time',
      reason: 'action_keyword_fallback',
      sourceFrom: 'last_user_action'
    });
    return 'skip_time';
  }
  if (/retreat/.test(action)) {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: 'retreat',
      reason: 'action_keyword_fallback',
      sourceFrom: 'last_user_action'
    });
    return 'retreat';
  }
  if (action === 'send_message' || action === 'resend') {
    ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
      action,
      resolvedSource: 'regular_turn',
      reason: 'send_message_fallback',
      sourceFrom: 'last_user_action'
    });
    return 'regular_turn';
  }
  ceTraceDiag('ORIGINAL_TIMELINE_TRIGGER_SOURCE', {
    action,
    resolvedSource: 'regular_turn',
    reason: 'default_fallback',
    sourceFrom: 'default'
  });
  return 'regular_turn';
}

function ceInferOriginalTimelinePlayerInvolved(sharedContext) {
  const ctx = sharedContext || {};
  const impactText = String(ctx.originalTimelinePlayerImpact || '').trim();
  if (!impactText) return false;

  const normalizedText = impactText.replace(/\s+/g, '');
  const hasExplicitPlayerSubject = /(玩家|B1|当前玩家|玩家本人|你自己|\b你\b)/i.test(impactText);
  if (!hasExplicitPlayerSubject) return false;

  if (/(?:玩家|B1|当前玩家|玩家本人|你自己|你)(?:未(?:直接)?(?:参与|介入|影响|卷入|改写)|旁观|未占用原著位|未替代原著|未成为事件角色|未(?:取代|代替|替代))/.test(normalizedText)
    || /无玩家(?:直接)?(?:参与|介入|影响|卷入)/.test(normalizedText)) {
    return false;
  }

  if (/(?:直接)?(?:参与|介入|影响|卷入|改写)|替代原著|成为事件角色|占用原著位|(?:取代|代替|替代)|出现在当前原著区间|已卷入当前原著区间/.test(impactText)) {
    return true;
  }
  return false;
}

function ceExtractOriginalTimelineEventTags(rawText) {
  const text = String(rawText || '');
  if (!text.trim()) return [];
  const rules = [
    { tag: '冲突', regex: /大战|围剿|厮杀|交战|追杀|冲突|斗法/ },
    { tag: '机缘', regex: /奇遇|机缘|传承|机遇|造化|秘藏/ },
    { tag: '突破', regex: /突破|晋升|进阶|结丹|元婴|化神|飞升/ },
    { tag: '探索', regex: /秘境|遗迹|探查|探索|寻宝|潜入/ },
    { tag: '势力', regex: /宗门|家族|势力|联盟|组织|朝廷|宫/ },
    { tag: '物品', regex: /法宝|丹药|灵石|材料|符箓|兵器|宝物|至宝/ },
    { tag: '功法', regex: /功法|秘术|神通|术法|剑诀|心经|阵法/ },
    { tag: '灵兽', regex: /灵兽|妖兽|真灵|神兽|坐骑/ },
    { tag: '闭关', regex: /闭关|出关|潜修|苦修/ },
    { tag: '生死', regex: /陨落|战死|身亡|殒命|重伤/ },
    { tag: '关系', regex: /结盟|联手|收徒|拜师|婚约|背叛|反目/ }
  ];
  return rules.filter(rule => rule.regex.test(text)).map(rule => rule.tag);
}

function ceExtractOriginalTimelineEventDisplayCode(text) {
  const raw = String(text || '').trim();
  if (!raw) return '';
  const codeMatch = raw.match(/\b([A-Z]{1,5}-\d{2,4}[A-Z]?)\b/);
  if (codeMatch && codeMatch[1]) return String(codeMatch[1]).trim();
  const numericMatch = raw.match(/(?:^|[\s【\[])(?:事件\s*)?(\d{1,3})(?=[、.)\]】\s]|$)/)
    || raw.match(/^第\s*(\d{1,3})\s*(?:条|则|段|章)/);
  if (numericMatch && numericMatch[1]) {
    return 'E-' + String(numericMatch[1]).padStart(3, '0');
  }
  return '';
}

function ceExtractOriginalTimelineItemEntries(sharedContext) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const rawText = String(ctx.originalTimelineItemText || originalCtx.itemText || '').trim();
  if (!rawText) return [];

  const matches = [];
  const codeRegex = /\b([A-Z]{1,5}-\d{2,4}[A-Z]?)\b([^；。\n\r]*)/g;
  let match;
  while ((match = codeRegex.exec(rawText)) !== null) {
    const code = String(match[1] || '').trim();
    const suffix = String(match[2] || '').trim();
    const text = (code + (suffix ? (' ' + suffix) : '')).trim();
    if (text) matches.push(text);
  }
  if (matches.length > 1) {
    return Array.from(new Set(matches));
  }

  const directParts = rawText
    .split(/\r?\n|；|;/)
    .map(function(item) { return String(item || '').trim(); })
    .filter(Boolean);
  if (directParts.length > 1) {
    return Array.from(new Set(directParts));
  }

  const datedParts = rawText
    .replace(/([；;。！？])/g, '$1\n')
    .split(/\r?\n|(?=\b\d{4}\.\d{2}(?:\.\d{1,2})?(?:\.\d{1,2})?\b)/)
    .map(function(item) { return String(item || '').trim(); })
    .filter(Boolean);
  if (datedParts.length > 1) {
    return Array.from(new Set(datedParts));
  }

  if (rawText.includes('、')) {
    const commaParts = rawText
      .split(/、/)
      .map(function(item) { return String(item || '').trim(); })
      .filter(Boolean);
    if (commaParts.length > 1) {
      return Array.from(new Set(commaParts));
    }
  }

  return rawText ? [rawText] : [];
}

function ceIsOriginalTimelineEventStartLine(line) {
  const text = String(line || '').trim();
  if (!text) return false;
  return /^(?:[-*•]+|[0-9]+[、.)]|第[一二三四五六七八九十百\d]+(?:条|则|段|章)?[：:]?|\[[^\]\r\n]{1,30}\]|【[^】]{1,20}】|(?:[-*•]+\s*)?时间\s*[:：]|\d{4}\.\d{2}(?:\.\d{1,2})?(?:\.\d{1,2})?(?:\s*(?:[—\-~～→]|至|到)\s*\d{4}\.\d{2}(?:\.\d{1,2})?(?:\.\d{1,2})?)?)/.test(text);
}

function ceSplitOriginalTimelineTextBlocks(text) {
  const blocks = [];
  let buffer = [];
  const flush = function() {
    const blockText = buffer.join('\n').trim();
    if (blockText) blocks.push(blockText);
    buffer = [];
  };

  String(text || '').split(/\r?\n/).forEach(function(line) {
    const trimmed = String(line || '').trim();
    if (!trimmed) return;
    if (ceIsOriginalTimelineEventStartLine(trimmed) && buffer.length > 0) {
      flush();
    }
    buffer.push(trimmed);
  });
  flush();
  return blocks;
}

function ceNormalizeOriginalTimelineStructuredList(value) {
  const text = String(value || '').trim();
  if (!text) return [];
  const rows = [];
  text.split(/\r?\n|；|;/).forEach(function(part) {
    const trimmed = String(part || '').trim();
    if (!trimmed) return;
    if (trimmed.indexOf('|') >= 0) {
      rows.push(trimmed);
      return;
    }
    trimmed.split(/[，,、]/).forEach(function(piece) {
      const normalized = String(piece || '').trim();
      if (normalized) rows.push(normalized);
    });
  });
  return Array.from(new Set(rows));
}

function ceParseOriginalTimelineStructuredFields(text) {
  const sourceText = String(text || '').trim();
  const data = {
    timeText: '',
    timeStart: '',
    timeEnd: '',
    title: '',
    brief: '',
    original: '',
    keyCharacters: [],
    keyItems: [],
    keyLocations: [],
    keyFactions: [],
    keyTechniques: [],
    keyBeasts: [],
    eventTrigger: '',
    expectedResults: [],
    followupState: [],
    mutationFocus: '',
    sourceNotes: ''
  };
  if (!sourceText) return data;

  const labelMap = {
    '时间': 'timeText',
    '起始时间': 'timeStart',
    '结束时间': 'timeEnd',
    '标题': 'title',
    '简略版': 'brief',
    '原著版': 'original',
    '关键人物': 'keyCharacters',
    '关键物品': 'keyItems',
    '关键地点': 'keyLocations',
    '关键势力': 'keyFactions',
    '关键功法': 'keyTechniques',
    '关键灵兽/妖兽': 'keyBeasts',
    '触发条件': 'eventTrigger',
    '预期结果': 'expectedResults',
    '后续状态': 'followupState',
    '变异关注点': 'mutationFocus',
    '来源备注': 'sourceNotes'
  };
  const orderedLabels = [
    '关键灵兽/妖兽',
    '起始时间',
    '结束时间',
    '关键人物',
    '关键物品',
    '关键地点',
    '关键势力',
    '关键功法',
    '触发条件',
    '预期结果',
    '后续状态',
    '变异关注点',
    '来源备注',
    '简略版',
    '原著版',
    '标题',
    '时间'
  ];
  const labelRegex = new RegExp(
    '(' + orderedLabels.map(function(label) {
      return String(label || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }).join('|') + ')\\s*[:：]',
    'g'
  );

  let currentLabel = '';
  let buffer = [];
  const commit = function() {
    if (!currentLabel) return;
    const value = buffer.join('\n').trim();
    buffer = [];
    if (!value) {
      currentLabel = '';
      return;
    }
    const key = labelMap[currentLabel] || '';
    if (!key) {
      currentLabel = '';
      return;
    }
    if (Array.isArray(data[key])) {
      data[key] = ceNormalizeOriginalTimelineStructuredList(value);
    } else {
      data[key] = value;
    }
    currentLabel = '';
  };
  const parseLineLabelSegments = function(lineText) {
    const normalizedLine = String(lineText || '').trim();
    if (!normalizedLine) return [];
    const segments = [];
    labelRegex.lastIndex = 0;
    let match = null;
    while ((match = labelRegex.exec(normalizedLine))) {
      const index = Number(match.index || 0);
      const prevChar = index > 0 ? normalizedLine.charAt(index - 1) : '';
      if (index > 0 && !/\s/.test(prevChar)) continue;
      const label = String(match[1] || '').trim();
      if (!labelMap[label]) continue;
      segments.push({
        label: label,
        index: index,
        valueStart: labelRegex.lastIndex
      });
    }
    if (segments.length === 0) return [];
    return segments.map(function(item, index) {
      const next = index + 1 < segments.length ? segments[index + 1] : null;
      return {
        label: item.label,
        value: normalizedLine.slice(item.valueStart, next ? next.index : normalizedLine.length).trim()
      };
    }).filter(function(item) {
      return item && item.label;
    });
  };

  sourceText.split(/\r?\n/).forEach(function(line) {
    const trimmed = String(line || '').trim();
    if (!trimmed) return;
    const segments = parseLineLabelSegments(trimmed);
    if (segments.length > 0) {
      segments.forEach(function(segment, index) {
        commit();
        currentLabel = segment.label;
        buffer = [String(segment.value || '').trim()];
        if (index < segments.length - 1) {
          commit();
        }
      });
      return;
    }
    if (currentLabel) {
      buffer.push(trimmed);
    }
  });
  commit();
  if (!data.timeText && data.timeStart && data.timeEnd) {
    data.timeText = data.timeStart + ' → ' + data.timeEnd;
  }
  return data;
}

function ceResolveOriginalTimelineEventDisplayData(item) {
  const source = item && typeof item === 'object' ? item : {};
  const reparsed = ceParseOriginalTimelineStructuredFields(source.text || '');
  const pickList = function(primary, fallback) {
    const list = Array.isArray(primary) && primary.length > 0
      ? primary
      : (Array.isArray(fallback) ? fallback : []);
    return Array.from(new Set(list.map(function(entry) {
      return String(entry || '').trim();
    }).filter(Boolean)));
  };
  return {
    code: String(source.code || source.codeHint || ceExtractOriginalTimelineEventDisplayCode(source.text || '') || '').trim(),
    title: String(source.title || reparsed.title || '').trim(),
    timeText: String(source.timeText || reparsed.timeText || '').trim(),
    timeStart: String(source.timeStart || reparsed.timeStart || '').trim(),
    timeEnd: String(source.timeEnd || reparsed.timeEnd || '').trim(),
    brief: String(source.brief || reparsed.brief || '').trim(),
    original: String(source.original || reparsed.original || '').trim(),
    keyCharacters: pickList(source.keyCharacters, reparsed.keyCharacters),
    keyItems: pickList(source.keyItems, reparsed.keyItems),
    keyLocations: pickList(source.keyLocations, reparsed.keyLocations),
    keyFactions: pickList(source.keyFactions, reparsed.keyFactions),
    keyTechniques: pickList(source.keyTechniques, reparsed.keyTechniques),
    keyBeasts: pickList(source.keyBeasts, reparsed.keyBeasts),
    eventTrigger: String(source.eventTrigger || reparsed.eventTrigger || '').trim(),
    expectedResults: pickList(source.expectedResults, reparsed.expectedResults),
    followupState: pickList(source.followupState, reparsed.followupState),
    mutationFocus: String(source.mutationFocus || reparsed.mutationFocus || '').trim(),
    sourceNotes: String(source.sourceNotes || reparsed.sourceNotes || '').trim(),
    rawText: String(source.text || '').trim()
  };
}

function ceBuildOriginalTimelineStructuredExecutionText(packet, options = {}) {
  const rows = Array.isArray(packet && packet.events) ? packet.events : [];
  if (!rows.length) return '';
  const limit = Math.max(1, Number(options.limit || 6));
  return rows.slice(0, limit).map(function(item, index) {
    const resolved = ceResolveOriginalTimelineEventDisplayData(item);
    const hasStructuredSignals = !!(
      resolved.eventTrigger
      || resolved.expectedResults.length
      || resolved.followupState.length
      || resolved.mutationFocus
    );
    if (!hasStructuredSignals) return '';
    const title = resolved.title || '未命名事件';
    const codeText = resolved.code ? ('[' + resolved.code + '] ') : '';
    const timeRangeText = [resolved.timeStart, resolved.timeEnd].filter(Boolean).join(' → ');
    const lines = [(index + 1) + '. ' + codeText + title];
    if (resolved.timeText) lines.push('时间: ' + resolved.timeText);
    else if (timeRangeText) lines.push('时间: ' + timeRangeText);
    if (resolved.eventTrigger) lines.push('触发条件: ' + resolved.eventTrigger);
    if (resolved.expectedResults.length) lines.push('预期结果:\n- ' + resolved.expectedResults.join('\n- '));
    if (resolved.followupState.length) lines.push('后续状态:\n- ' + resolved.followupState.join('\n- '));
    if (resolved.mutationFocus) lines.push('变异关注点: ' + resolved.mutationFocus);
    return lines.join('\n');
  }).filter(Boolean).join('\n\n');
}

function ceParseOriginalTimelineStructuredResultLine(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  const parts = raw.split('|').map(function(part) {
    return String(part || '').trim();
  });
  return {
    raw,
    category: parts[0] || '',
    subject: parts[1] || '',
    action: parts[2] || '',
    detail: parts.slice(3).join('|').trim()
  };
}

function ceBuildOriginalTimelineStructuredResultNote(event, entry, phaseType) {
  const eventCode = event && event.code ? ('[' + event.code + '] ') : '';
  const eventTitle = String(event && (event.title || event.text) || '未命名事件').trim();
  const phaseLabel = phaseType === 'followup' ? '后续状态' : '预期结果';
  const detail = [entry && entry.category, entry && entry.subject, entry && entry.action, entry && entry.detail]
    .filter(Boolean)
    .join('｜');
  return ['原著结构化' + phaseLabel, eventCode + eventTitle, detail].filter(Boolean).join('：');
}

function ceBuildOriginalTimelineStructuredCompactText(entry) {
  const action = String(entry && entry.action || '').trim();
  const detail = String(entry && entry.detail || '').trim();
  if (action && detail) {
    if (detail === action) return action;
    return action + '（' + detail + '）';
  }
  return action || detail || String(entry && entry.subject || '').trim();
}

function ceMergeOriginalTimelineStructuredTextValue(existingValue, incomingValue, options = {}) {
  const separator = String(options.separator || '；');
  const existing = String(existingValue == null ? '' : existingValue).trim();
  const incoming = String(incomingValue == null ? '' : incomingValue).trim();
  if (!incoming) return existing;
  if (!existing) return incoming;

  const normalizePart = function(text) {
    return String(text || '').replace(/^[；;、，,\s]+|[；;、，,\s]+$/g, '').trim();
  };
  const parts = existing.split(/\s*[；;\n]+\s*/).map(normalizePart).filter(Boolean);
  const seen = new Set(parts);
  let changed = false;
  incoming.split(/\s*[；;\n]+\s*/).map(normalizePart).filter(Boolean).forEach(function(part) {
    if (!part || seen.has(part)) return;
    seen.add(part);
    parts.push(part);
    changed = true;
  });
  return changed ? parts.join(separator) : existing;
}

function ceExtractOriginalTimelineStructuredNextStep(detailText) {
  const text = String(detailText || '').trim();
  if (!text) return '';
  const match = text.match(/(?:下一步(?:为|是)?|后续(?:为|是)?|接下来(?:将|需|是)?)[=:：]?\s*([^；;，,\n]+)/);
  return match ? String(match[1] || '').trim() : '';
}

function ceBuildOriginalTimelineStructuredCharacterRecordMap(sharedContext) {
  const ctx = sharedContext || {};
  const recordMap = new Map();
  const upsertRecord = function(id, data, options = {}) {
    const targetId = String(id || '').trim();
    if (!targetId) return;
    const existing = recordMap.get(targetId);
    const rawName = String(options.name || (data && data['1'] ? String(data['1']).split('|')[0] : targetId)).trim() || targetId;
    const nextRecord = {
      id: targetId,
      name: rawName,
      data: data && typeof data === 'object' ? data : {},
      sceneType: String(options.sceneType || (existing && existing.sceneType) || '').trim(),
      source: String(options.source || (existing && existing.source) || '').trim()
    };
    if (existing) {
      recordMap.set(targetId, Object.assign({}, existing, {
        name: existing.name || nextRecord.name,
        data: (existing.data && typeof existing.data === 'object' && Object.keys(existing.data).length > 0)
          ? existing.data
          : nextRecord.data,
        sceneType: existing.sceneType === 'onscene' ? 'onscene' : (nextRecord.sceneType || existing.sceneType),
        source: existing.source || nextRecord.source
      }));
      return;
    }
    recordMap.set(targetId, nextRecord);
  };

  try {
    if (currentState && currentState['0']) {
      Object.entries(currentState['0']).forEach(function(entry) {
        const id = String(entry && entry[0] || '').trim();
        const row = entry && entry[1];
        if (!id || id === 'TIME_LOCATION_ROW' || !row) return;
        upsertRecord(id, row, {
          sceneType: 'onscene',
          source: id === 'B1' ? 'current_state_player' : 'current_state'
        });
      });
    }
  } catch (e) {}

  const archiveIndex = ctx.originalTimelineNpcArchiveIndex && Array.isArray(ctx.originalTimelineNpcArchiveIndex.records)
    ? ctx.originalTimelineNpcArchiveIndex
    : null;
  if (archiveIndex) {
    archiveIndex.records.forEach(function(record) {
      if (!record || !record.id) return;
      upsertRecord(record.id, record.data, {
        name: record.name || '',
        sceneType: record.sceneType || 'offscene',
        source: record.source || 'archive_index'
      });
    });
  }

  return recordMap;
}

function ceBuildOriginalTimelineStructuredCharacterNameMap(sharedContext) {
  const ctx = sharedContext || {};
  const nameMap = new Map();
  const pushName = function(name, id) {
    const targetId = String(id || '').trim();
    if (!targetId) return;
    ceBuildOriginalTimelineNameVariants(name).forEach(function(variant) {
      if (!variant || nameMap.has(variant)) return;
      nameMap.set(variant, targetId);
    });
  };

  try {
    if (currentState && currentState['0']) {
      Object.entries(currentState['0']).forEach(function(entry) {
        const id = String(entry && entry[0] || '').trim();
        const row = entry && entry[1];
        if (!id || id === 'TIME_LOCATION_ROW' || !row) return;
        const rawName = String(row['1'] || '').split('|')[0] || '';
        pushName(rawName, id);
      });
    }
  } catch (e) {}

  const archiveIndex = ctx.originalTimelineNpcArchiveIndex && Array.isArray(ctx.originalTimelineNpcArchiveIndex.records)
    ? ctx.originalTimelineNpcArchiveIndex
    : null;
  if (archiveIndex) {
    archiveIndex.records.forEach(function(record) {
      if (!record || !record.id) return;
      pushName(record.name || '', record.id);
      if (record.aliases instanceof Set) {
        record.aliases.forEach(function(alias) {
          pushName(alias, record.id);
        });
      }
    });
  }

  return nameMap;
}

function ceResolveOriginalTimelineStructuredCharacterIds(text, sharedContext, options = {}) {
  const sourceText = String(text || '').trim();
  if (!sourceText) return [];
  const nameMap = options.nameMap instanceof Map
    ? options.nameMap
    : ceBuildOriginalTimelineStructuredCharacterNameMap(sharedContext);
  if (!(nameMap instanceof Map) || nameMap.size === 0) return [];

  const ids = new Set();
  const normalizedText = ceNormalizeOriginalTimelineName(sourceText);
  const sortedNames = Array.from(nameMap.keys()).sort(function(a, b) {
    return String(b || '').length - String(a || '').length;
  });
  if (normalizedText && nameMap.has(normalizedText)) {
    ids.add(nameMap.get(normalizedText));
  }
  sortedNames.forEach(function(name) {
    if (!name || !normalizedText || !normalizedText.includes(name)) return;
    ids.add(nameMap.get(name));
  });
  String(sourceText).split(/[\-—–~～与和、,，\/]/).forEach(function(piece) {
    const normalizedPiece = ceNormalizeOriginalTimelineName(piece);
    if (!normalizedPiece || !nameMap.has(normalizedPiece)) return;
    ids.add(nameMap.get(normalizedPiece));
  });
  return Array.from(ids).filter(Boolean).slice(0, 4);
}

function ceBuildOriginalTimelineStructuredCharacterOpSignature(op) {
  if (!op || typeof op !== 'object') return '';
  const cloned = Object.assign({}, op);
  delete cloned._structuredLine;
  delete cloned._structuredLines;
  delete cloned._structuredCategory;
  delete cloned._structuredPhase;
  delete cloned._allowNpcSet;
  delete cloned._preferArchiveOnly;
  return JSON.stringify(cloned);
}

function ceGetOriginalTimelineStructuredOpLines(op) {
  if (!op || typeof op !== 'object') return [];
  if (Array.isArray(op._structuredLines) && op._structuredLines.length > 0) {
    return Array.from(new Set(op._structuredLines.map(function(line) {
      return String(line || '').trim();
    }).filter(Boolean)));
  }
  const line = String(op._structuredLine || '').trim();
  return line ? [line] : [];
}

function ceMergeOriginalTimelineStructuredCharacterDelta(structuredDelta, modelDelta) {
  const out = [];
  const seen = new Set();
  [structuredDelta, modelDelta].forEach(function(list) {
    (Array.isArray(list) ? list : []).forEach(function(op) {
      if (!op || typeof op !== 'object') return;
      const signature = ceBuildOriginalTimelineStructuredCharacterOpSignature(op) || JSON.stringify(op);
      if (seen.has(signature)) return;
      seen.add(signature);
      out.push(op);
    });
  });
  return out;
}

function ceMergeOriginalTimelineStructuredItemOperations(structuredOps, modelOps) {
  const out = [];
  const seen = new Set();
  [structuredOps, modelOps].forEach(function(list) {
    (Array.isArray(list) ? list : []).forEach(function(op) {
      if (!op || typeof op !== 'object') return;
      const signature = ceBuildOriginalTimelineItemOperationSignature(op)
        || JSON.stringify(Object.assign({}, op, { _structuredLine: undefined, _structuredCategory: undefined, _structuredPhase: undefined }));
      if (seen.has(signature)) return;
      seen.add(signature);
      out.push(op);
    });
  });
  return out;
}

function ceBuildOriginalTimelinePendingNewCharacterLookup(sharedContext, options = {}) {
  const entries = [];
  const seenIds = new Set();
  const pushEntry = function(item) {
    const id = String(item && item.id || '').trim();
    if (!id || seenIds.has(id) || !(item && item.justCreated)) return;
    seenIds.add(id);
    entries.push(item);
  };

  if (typeof window !== 'undefined' && Array.isArray(window.pendingNewCharacterForConcurrentEvolution)) {
    window.pendingNewCharacterForConcurrentEvolution.forEach(pushEntry);
  }

  const pendingIds = new Set(entries.map(function(entry) {
    return String(entry && entry.id || '').trim();
  }).filter(Boolean));
  const knownTargetIds = new Set(pendingIds);
  if (options.targetMap instanceof Map) {
    options.targetMap.forEach(function(_, key) {
      const normalizedKey = String(key || '').trim();
      if (normalizedKey) knownTargetIds.add(normalizedKey);
    });
  }

  const nameToIds = new Map();
  const pushName = function(name, id) {
    const targetId = String(id || '').trim();
    if (!targetId) return;
    ceBuildOriginalTimelineNameVariants(name).forEach(function(variant) {
      if (!variant) return;
      if (!nameToIds.has(variant)) nameToIds.set(variant, new Set());
      nameToIds.get(variant).add(targetId);
    });
  };

  entries.forEach(function(entry) {
    [entry.name, entry.canonicalName, entry.sourceCandidate, entry.vectorTitle].forEach(function(name) {
      pushName(name, entry.id);
    });
  });

  return {
    entries,
    pendingIds,
    knownTargetIds,
    resolveByName: function(rawName) {
      const variants = ceBuildOriginalTimelineNameVariants(rawName);
      for (const variant of variants) {
        const hitSet = nameToIds.get(variant);
        if (hitSet && hitSet.size === 1) {
          return Array.from(hitSet)[0] || '';
        }
      }
      return '';
    }
  };
}

function ceRelinkOriginalTimelinePendingNewCharacterOps(characterDelta, itemOperations, sharedContext, options = {}) {
  const safeCharacterDelta = Array.isArray(characterDelta) ? characterDelta.slice() : [];
  const safeItemOperations = Array.isArray(itemOperations) ? itemOperations.slice() : [];
  const lookup = ceBuildOriginalTimelinePendingNewCharacterLookup(sharedContext, options);
  if (!lookup.entries.length) {
    return {
      characterDelta: safeCharacterDelta,
      itemOperations: safeItemOperations,
      idAliasMap: new Map()
    };
  }

  const idAliasMap = new Map();
  const tryBindAlias = function(rawId, rawName) {
    const normalizedId = String(rawId || '').trim();
    if (!normalizedId || lookup.knownTargetIds.has(normalizedId) || idAliasMap.has(normalizedId)) return;
    const matchedId = lookup.resolveByName(rawName);
    if (matchedId && matchedId !== normalizedId) {
      idAliasMap.set(normalizedId, matchedId);
    }
  };

  safeCharacterDelta.forEach(function(op) {
    if (!op || typeof op !== 'object') return;
    const opId = String(resolveConcurrentEvolutionOpId(op) || '').trim();
    if (!opId || lookup.knownTargetIds.has(opId)) return;
    const data = op.data && typeof op.data === 'object' ? op.data : null;
    const rawName = data && typeof data['1'] === 'string'
      ? String(data['1']).split('|')[0]
      : (data && typeof data.name === 'string' ? data.name : '');
    if (rawName) tryBindAlias(opId, rawName);
  });

  const rewriteId = function(rawId) {
    const normalizedId = String(rawId || '').trim();
    if (!normalizedId) return normalizedId;
    if (idAliasMap.has(normalizedId)) {
      return idAliasMap.get(normalizedId) || normalizedId;
    }
    if (lookup.knownTargetIds.has(normalizedId)) {
      return normalizedId;
    }
    const mappedByName = lookup.resolveByName(normalizedId);
    if (mappedByName && mappedByName !== normalizedId) {
      idAliasMap.set(normalizedId, mappedByName);
      return mappedByName;
    }
    return normalizedId;
  };

  const rewriteCharacterOp = function(op) {
    if (!op || typeof op !== 'object') return op;
    const next = Object.assign({}, op);
    let changed = false;
    if (typeof next.id === 'string' && next.id) {
      const mappedId = rewriteId(next.id);
      if (mappedId && mappedId !== next.id) {
        next.id = mappedId;
        changed = true;
      }
    }
    if (next.data && typeof next.data === 'object' && typeof next.data['0'] === 'string' && next.data['0']) {
      const mappedDataId = rewriteId(next.data['0']);
      if (mappedDataId && mappedDataId !== next.data['0']) {
        next.data = Object.assign({}, next.data, { '0': mappedDataId });
        changed = true;
      }
    }
    if (changed) {
      next._relinkedFromId = String(resolveConcurrentEvolutionOpId(op) || '').trim();
    }
    return next;
  };

  const rewriteItemOperation = function(op) {
    if (!op || typeof op !== 'object') return op;
    const next = Object.assign({}, op);
    let changed = false;
    ['owner', 'from', 'to'].forEach(function(key) {
      if (typeof next[key] !== 'string' || !next[key]) return;
      const mappedId = rewriteId(next[key]);
      if (mappedId && mappedId !== next[key]) {
        next[key] = mappedId;
        changed = true;
      }
    });
    if (changed) {
      next._relinked = true;
    }
    return next;
  };

  const rewrittenCharacterDelta = [];
  const seenCharacterSignatures = new Set();
  safeCharacterDelta.forEach(function(op) {
    const next = rewriteCharacterOp(op);
    if (!next || typeof next !== 'object') return;
    const signature = ceBuildOriginalTimelineStructuredCharacterOpSignature(next) || JSON.stringify(next);
    if (seenCharacterSignatures.has(signature)) return;
    seenCharacterSignatures.add(signature);
    rewrittenCharacterDelta.push(next);
  });

  const rewrittenItemOperations = [];
  const seenItemSignatures = new Set();
  safeItemOperations.forEach(function(op) {
    const next = rewriteItemOperation(op);
    if (!next || typeof next !== 'object') return;
    const signature = ceBuildOriginalTimelineItemOperationSignature(next)
      || JSON.stringify(Object.assign({}, next, { _structuredLine: undefined, _structuredCategory: undefined, _structuredPhase: undefined }));
    if (seenItemSignatures.has(signature)) return;
    seenItemSignatures.add(signature);
    rewrittenItemOperations.push(next);
  });

  return {
    characterDelta: rewrittenCharacterDelta,
    itemOperations: rewrittenItemOperations,
    idAliasMap
  };
}

function ceBuildOriginalTimelineStructuredExecutionPlan(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const packet = options.packet || ctx.originalTimelinePacket || ctx.originalTimelineBasePacket || null;
  const rows = Array.isArray(packet && packet.events) ? packet.events : [];
  const plan = {
    characterDelta: [],
    itemOperations: [],
    directLines: [],
    pendingLines: []
  };
  if (!rows.length) return plan;

  const nameMap = ceBuildOriginalTimelineStructuredCharacterNameMap(ctx);
  const recordMap = ceBuildOriginalTimelineStructuredCharacterRecordMap(ctx);
  const directLineSet = new Set();
  const pendingLineSet = new Set();
  const characterPatchStateMap = new Map();
  const pushDirectLine = function(line) {
    const text = String(line || '').trim();
    if (!text || directLineSet.has(text)) return;
    directLineSet.add(text);
    plan.directLines.push(text);
  };
  const pushPendingLine = function(line) {
    const text = String(line || '').trim();
    if (!text || pendingLineSet.has(text)) return;
    pendingLineSet.add(text);
    plan.pendingLines.push(text);
  };
  const resolvePrimaryCharacterIds = function(entry) {
    let ids = ceResolveOriginalTimelineStructuredCharacterIds(entry && entry.subject || '', ctx, { nameMap });
    if (ids.length > 0) return ids;
    return ceResolveOriginalTimelineStructuredCharacterIds(
      [entry && entry.subject, entry && entry.action, entry && entry.detail].filter(Boolean).join(' '),
      ctx,
      { nameMap }
    );
  };
  const ensureCharacterPatchState = function(targetId) {
    const normalizedId = String(targetId || '').trim();
    if (!normalizedId) return null;
    if (!characterPatchStateMap.has(normalizedId)) {
      const record = recordMap.get(normalizedId) || {};
      let seedData = {};
      try {
        seedData = record.data && typeof record.data === 'object'
          ? JSON.parse(JSON.stringify(record.data))
          : {};
      } catch (e) {
        seedData = record.data && typeof record.data === 'object' ? Object.assign({}, record.data) : {};
      }
      characterPatchStateMap.set(normalizedId, {
        id: normalizedId,
        sceneType: String(record.sceneType || (currentState && currentState['0'] && currentState['0'][normalizedId] ? 'onscene' : 'offscene')).trim() || 'offscene',
        seedData,
        data: {},
        lines: new Set(),
        categories: new Set(),
        phases: new Set()
      });
    }
    return characterPatchStateMap.get(normalizedId);
  };
  const pushCharacterFieldPatch = function(targetId, fieldKey, fieldText, noteText, meta = {}) {
    const text = String(fieldText || '').trim();
    if (!fieldKey || !text) return false;
    const state = ensureCharacterPatchState(targetId);
    if (!state) return false;
    const hasOwnField = Object.prototype.hasOwnProperty.call(state.data, fieldKey);
    const baseValue = hasOwnField ? state.data[fieldKey] : state.seedData[fieldKey];
    const mergedValue = ceMergeOriginalTimelineStructuredTextValue(baseValue, text, {
      separator: meta.separator || '；'
    });
    const baseText = String(baseValue == null ? '' : baseValue).trim();
    if (!String(mergedValue || '').trim() || String(mergedValue || '').trim() === baseText) {
      return false;
    }
    state.data[fieldKey] = mergedValue;
    if (noteText) state.lines.add(String(noteText).trim());
    if (meta.category) state.categories.add(String(meta.category).trim());
    if (meta.phaseType) state.phases.add(String(meta.phaseType).trim());
    return true;
  };

  rows.forEach(function(event) {
    [
      { phaseType: 'expected', lines: Array.isArray(event && event.expectedResults) ? event.expectedResults : [] },
      { phaseType: 'followup', lines: Array.isArray(event && event.followupState) ? event.followupState : [] }
    ].forEach(function(section) {
      section.lines.forEach(function(line) {
        const entry = ceParseOriginalTimelineStructuredResultLine(line);
        if (!entry) return;
        const noteText = ceBuildOriginalTimelineStructuredResultNote(event, entry, section.phaseType);
        const category = String(entry.category || '').trim();
        const compactText = ceBuildOriginalTimelineStructuredCompactText(entry);
        if (!category) {
          pushPendingLine(noteText + ' —— 缺少结构化类别，保留给模型修正');
          return;
        }
        if (!compactText) {
          pushPendingLine(noteText + ' —— 缺少可执行内容，保留给模型修正');
          return;
        }

        if (['人物', '状态', '冲突', '主线', '关系', '认知', '情报'].includes(category)) {
          const targetIds = resolvePrimaryCharacterIds(entry);
          if (!targetIds.length) {
            pushPendingLine(noteText + ' —— 未解析到可直落人物，保留给模型修正');
            return;
          }

          let applied = false;
          targetIds.forEach(function(targetId) {
            if (category === '关系') {
              const relationText = [String(entry.subject || '').trim(), compactText].filter(Boolean).join('：');
              applied = pushCharacterFieldPatch(targetId, '13', relationText, noteText, {
                category,
                phaseType: section.phaseType,
                separator: '；'
              }) || applied;
              return;
            }
            if (category === '认知' || category === '情报') {
              const cognitionText = (String(entry.subject || '').trim() ? ('已知' + String(entry.subject || '').trim() + '：') : '') + compactText;
              applied = pushCharacterFieldPatch(targetId, '12', cognitionText, noteText, {
                category,
                phaseType: section.phaseType,
                separator: '；'
              }) || applied;
              return;
            }
            if (category === '主线') {
              applied = pushCharacterFieldPatch(targetId, '4', compactText, noteText, {
                category,
                phaseType: section.phaseType,
                separator: '；'
              }) || applied;
              const nextStep = ceExtractOriginalTimelineStructuredNextStep(entry.detail);
              if (nextStep) {
                applied = pushCharacterFieldPatch(targetId, '28', nextStep, noteText, {
                  category,
                  phaseType: section.phaseType,
                  separator: '；'
                }) || applied;
              }
              return;
            }
            applied = pushCharacterFieldPatch(targetId, '4', compactText, noteText, {
              category,
              phaseType: section.phaseType,
              separator: '；'
            }) || applied;
          });

          if (applied) {
            pushDirectLine(noteText);
          } else {
            pushPendingLine(noteText + ' —— 结构化结果已体现在当前现态，无需重复直落');
          }
          return;
        }

        if (category === '物品') {
          const ownerIds = ceResolveOriginalTimelineStructuredCharacterIds(
            [entry.action, entry.detail].filter(Boolean).join(' '),
            ctx,
            { nameMap }
          );
          if (ownerIds.length !== 1) {
            pushPendingLine(noteText + ' —— 物品归属未能唯一确定，保留给模型修正');
            return;
          }
          const itemName = String(entry.subject || '').trim() || '未命名原著物品';
          pushDirectLine(noteText);
          plan.itemOperations.push({
            type: 'createItem',
            owner: ownerIds[0],
            itemName: itemName,
            item: {
              '1': itemName,
              '2': '原著相关物品',
              '3': noteText,
              '5': '1'
            },
            _structuredLine: noteText,
            _structuredLines: [noteText],
            _structuredCategory: category,
            _structuredPhase: section.phaseType
          });
          return;
        }

        pushPendingLine(noteText + ' —— 暂无安全直落映射，保留给模型修正');
      });
    });
  });

  characterPatchStateMap.forEach(function(state, targetId) {
    if (!state || !state.data || Object.keys(state.data).length === 0) return;
    const structuredLines = Array.from(state.lines).filter(Boolean);
    if (structuredLines.length === 0) return;
    plan.characterDelta.push({
      command: 'set',
      id: targetId,
      data: state.data,
      _structuredLine: structuredLines[0],
      _structuredLines: structuredLines,
      _structuredCategory: Array.from(state.categories).filter(Boolean).join('、'),
      _structuredPhase: Array.from(state.phases).filter(Boolean).join('、'),
      _allowNpcSet: true,
      _preferArchiveOnly: state.sceneType === 'offscene'
    });
  });

  return plan;
}

function ceCollectOriginalTimelineStructuredExecutionTrace(plan, options = {}) {
  const directLineSet = new Set((Array.isArray(plan && plan.directLines) ? plan.directLines : []).map(function(line) {
    return String(line || '').trim();
  }).filter(Boolean));
  const pendingLineSet = new Set((Array.isArray(plan && plan.pendingLines) ? plan.pendingLines : []).map(function(line) {
    return String(line || '').trim();
  }).filter(Boolean));
  const appliedLineSet = new Set();
  const seenLineSet = new Set();
  [options.characterDelta, options.itemOperations].forEach(function(list) {
    (Array.isArray(list) ? list : []).forEach(function(op) {
      ceGetOriginalTimelineStructuredOpLines(op).forEach(function(line) {
        appliedLineSet.add(line);
        seenLineSet.add(line);
      });
    });
  });
  [options.blockedCharacterOps, options.blockedItemOps].forEach(function(list) {
    (Array.isArray(list) ? list : []).forEach(function(op) {
      ceGetOriginalTimelineStructuredOpLines(op).forEach(function(line) {
        seenLineSet.add(line);
        pendingLineSet.add(line + ' —— ' + ceFormatOriginalTimelineBlockedReason(op && op.blockedReason));
      });
    });
  });
  directLineSet.forEach(function(line) {
    if (appliedLineSet.has(line) || seenLineSet.has(line)) return;
    pendingLineSet.add(line + ' —— 已由同轮模型结果覆盖或去重');
  });
  return {
    appliedLines: Array.from(appliedLineSet).slice(0, 24),
    pendingLines: Array.from(pendingLineSet).slice(0, 24)
  };
}

function ceExtractOriginalTimelineEventList(sharedContext) {
  const ctx = sharedContext || {};
  const rawText = String(ctx.originalTimelineEvents || (ctx.originalTimelineContext && ctx.originalTimelineContext.eventTextBlock) || '').trim();
  if (!rawText) return [];

  const sectionText = ceExtractOriginalTimelineSection(rawText);
  const cleaned = String(sectionText || rawText)
    .replace(/^###\s*【世界年表参考】\s*/m, '')
    .replace(/<<<世界年表参考结束>>>/g, '')
    .trim();
  const lines = cleaned
    .split(/\r?\n/)
    .map(line => String(line || '').trim())
    .filter(line => line)
    .filter(line => !ceIsOriginalTimelineBoilerplateLine(line));
  const itemEntries = ceExtractOriginalTimelineItemEntries(ctx);

  const events = [];
  const seenEventTexts = new Set();
  const pushEvent = (text, codeHint = '') => {
    const normalized = String(text || '')
      .split(/\r?\n/)
      .map(function(line) { return String(line || '').trim(); })
      .filter(Boolean)
      .join('\n')
      .replace(/^(?:[-*•]+|[0-9]+[、.)]|第[一二三四五六七八九十百\d]+(?:条|则|段|章)?[：:]?)\s*/, '')
      .trim();
    if (!normalized || ceIsOriginalTimelineBoilerplateBlock(normalized)) return;
    const dedupeKey = normalized.replace(/\s+/g, ' ');
    if (seenEventTexts.has(dedupeKey)) return;
    seenEventTexts.add(dedupeKey);
    const eventIndex = events.length + 1;
    const structured = ceParseOriginalTimelineStructuredFields(normalized);
    const baseTags = ceExtractOriginalTimelineEventTags(normalized);
    const structuredTags = [];
    if (structured.keyItems.length > 0) structuredTags.push('物品');
    if (structured.keyFactions.length > 0) structuredTags.push('势力');
    if (structured.keyTechniques.length > 0) structuredTags.push('功法');
    if (structured.keyBeasts.length > 0) structuredTags.push('灵兽');
    if (structured.expectedResults.length > 0) structuredTags.push('结果');
    events.push({
      index: eventIndex,
      text: normalized,
      codeHint: codeHint || '',
      title: structured.title || '',
      timeText: structured.timeText || '',
      timeStart: structured.timeStart || '',
      timeEnd: structured.timeEnd || '',
      brief: structured.brief || '',
      original: structured.original || '',
      keyCharacters: structured.keyCharacters || [],
      keyItems: structured.keyItems || [],
      keyLocations: structured.keyLocations || [],
      keyFactions: structured.keyFactions || [],
      keyTechniques: structured.keyTechniques || [],
      keyBeasts: structured.keyBeasts || [],
      eventTrigger: structured.eventTrigger || '',
      expectedResults: structured.expectedResults || [],
      followupState: structured.followupState || [],
      mutationFocus: structured.mutationFocus || '',
      sourceNotes: structured.sourceNotes || '',
      hash: ceHashOriginalTimelineText([
        ctx.originalTimelineAnchor || '',
        ctx.originalTimelineRange || '',
        normalized,
        String(eventIndex)
      ].join('|')),
      tags: Array.from(new Set(baseTags.concat(structuredTags)))
    });
  };

  const structuredBlocks = ceSplitOriginalTimelineTextBlocks(cleaned);

  if (structuredBlocks.length > 1) {
    structuredBlocks.forEach(function(blockText) {
      pushEvent(blockText, itemEntries[events.length] || '');
    });
  } else {
    let buffer = '';
    const flush = () => {
      if (!buffer) return;
      pushEvent(buffer, itemEntries[events.length] || '');
      buffer = '';
    };

    lines.forEach(line => {
      const looksLikeNewEvent = ceIsOriginalTimelineEventStartLine(line);
      if (looksLikeNewEvent && buffer) {
        flush();
      } else if (buffer && /[。！？；]$/.test(buffer)) {
        flush();
      }
      buffer = buffer ? (buffer + ' ' + line) : line;
    });
    flush();
  }

  if (events.length === 0 && cleaned) {
    cleaned.split(/[。！？；]/).forEach((item, index) => pushEvent(item, itemEntries[index] || ''));
  }

  const baseLimit = Math.max(1, Number(CONCURRENT_EVOLUTION_ORIGINAL_TIMELINE_MAX_EVENTS || 12));
  const triggerSource = ceInferOriginalTimelineTriggerSource(ctx);
  const modeText = String(ctx.originalTimelineMode || (ctx.originalTimelineContext && ctx.originalTimelineContext.modeText) || '').trim();
  const isBatchReplayContext = /^(?:batch|区间|批量|闭关|跳时|快进|跨度|skip_time|retreat)$/i.test(modeText)
    || ['skip_time', 'retreat', 'manual_replay'].includes(String(triggerSource || '').trim());
  const limit = isBatchReplayContext ? Number.MAX_SAFE_INTEGER : baseLimit;
  if (itemEntries.length > events.length && events.length <= 1) {
    const fallbackEvents = [];
    const seenFallback = new Set();
    itemEntries.forEach(function(item, index) {
      const normalized = String(item || '').trim();
      if (!normalized || ceIsOriginalTimelineBoilerplateBlock(normalized) || seenFallback.has(normalized)) return;
      seenFallback.add(normalized);
      const structured = ceParseOriginalTimelineStructuredFields(normalized);
      const baseTags = ceExtractOriginalTimelineEventTags(normalized);
      const structuredTags = [];
      if (structured.keyItems.length > 0) structuredTags.push('物品');
      if (structured.keyFactions.length > 0) structuredTags.push('势力');
      if (structured.keyTechniques.length > 0) structuredTags.push('功法');
      if (structured.keyBeasts.length > 0) structuredTags.push('灵兽');
      if (structured.expectedResults.length > 0) structuredTags.push('结果');
      fallbackEvents.push({
        index: index + 1,
        text: normalized,
        codeHint: normalized,
        title: structured.title || '',
        timeText: structured.timeText || '',
        timeStart: structured.timeStart || '',
        timeEnd: structured.timeEnd || '',
        brief: structured.brief || '',
        original: structured.original || '',
        keyCharacters: structured.keyCharacters || [],
        keyItems: structured.keyItems || [],
        keyLocations: structured.keyLocations || [],
        keyFactions: structured.keyFactions || [],
        keyTechniques: structured.keyTechniques || [],
        keyBeasts: structured.keyBeasts || [],
        eventTrigger: structured.eventTrigger || '',
        expectedResults: structured.expectedResults || [],
        followupState: structured.followupState || [],
        mutationFocus: structured.mutationFocus || '',
        sourceNotes: structured.sourceNotes || '',
        hash: ceHashOriginalTimelineText([
          ctx.originalTimelineAnchor || '',
          ctx.originalTimelineRange || '',
          normalized,
          String(index + 1)
        ].join('|')),
        tags: Array.from(new Set(baseTags.concat(structuredTags)))
      });
    });
    if (fallbackEvents.length > events.length) {
      const finalFallbackEvents = fallbackEvents.slice(0, limit);
      ceTraceDiag('ORIGINAL_TIMELINE_EXTRACT_EVENTS', {
        source: 'fallback_items',
        anchorTime: ctx.originalTimelineAnchor || '',
        rangeText: ctx.originalTimelineRange || '',
        modeText: ctx.originalTimelineMode || '',
        itemEntries: itemEntries.slice(0, 12),
        rawTextPreview: String(rawText || '').slice(0, 600),
        eventCount: finalFallbackEvents.length,
        eventSummaries: finalFallbackEvents.map(function(item) {
          return {
            index: item && item.index ? item.index : 0,
            codeHint: item && item.codeHint ? item.codeHint : '',
            title: item && item.title ? item.title : '',
            timeStart: item && item.timeStart ? item.timeStart : '',
            timeEnd: item && item.timeEnd ? item.timeEnd : '',
            textPreview: String(item && item.text ? item.text : '').slice(0, 160)
          };
        })
      });
      return finalFallbackEvents;
    }
  }

  const finalEvents = events.slice(0, limit);
  ceTraceDiag('ORIGINAL_TIMELINE_EXTRACT_EVENTS', {
    source: 'event_text_block',
    anchorTime: ctx.originalTimelineAnchor || '',
    rangeText: ctx.originalTimelineRange || '',
    modeText: ctx.originalTimelineMode || '',
    itemEntries: itemEntries.slice(0, 12),
    rawTextPreview: String(rawText || '').slice(0, 600),
    eventCount: finalEvents.length,
    eventSummaries: finalEvents.map(function(item) {
      return {
        index: item && item.index ? item.index : 0,
        codeHint: item && item.codeHint ? item.codeHint : '',
        title: item && item.title ? item.title : '',
        timeStart: item && item.timeStart ? item.timeStart : '',
        timeEnd: item && item.timeEnd ? item.timeEnd : '',
        textPreview: String(item && item.text ? item.text : '').slice(0, 160)
      };
    })
  });
  return finalEvents;
}

function ceBuildOriginalTimelineEventCodes(events, sharedContext) {
  const ctx = sharedContext || {};
  const rows = Array.isArray(events) ? events : [];
  return rows.map((item, index) => {
    const explicitCode = ceExtractOriginalTimelineEventDisplayCode(item && (item.code || item.codeHint || item.text || ''));
    if (explicitCode) return explicitCode;
    const fallbackIndex = Math.max(1, Number(item && item.index ? item.index : (index + 1)) || (index + 1));
    return 'E-' + String(fallbackIndex).padStart(3, '0');
  });
}

function ceBuildOriginalTimelineEventHashes(events) {
  const rows = Array.isArray(events) ? events : [];
  return rows.map(function(item, index) {
    const explicitHash = String(item && item.hash || '').trim();
    if (explicitHash) return explicitHash;
    return ceHashOriginalTimelineText([
      item && item.text ? item.text : '',
      item && (item.timeStart || item.timeText || item.timeEnd) ? (item.timeStart || item.timeText || item.timeEnd) : '',
      String(index + 1)
    ].join('|'));
  });
}

function ceBuildOriginalTimelineProgressKey(packet, archiveId) {
  const safePacket = packet && typeof packet === 'object' ? packet : null;
  if (!safePacket) return '';
  const rows = Array.isArray(safePacket.events) ? safePacket.events : [];
  const firstEvent = rows.length > 0 ? rows[0] : null;
  const lastEvent = rows.length > 0 ? rows[rows.length - 1] : null;
  const comparableMonth = ceExtractOriginalTimelineComparableMonth(
    safePacket.anchorTime || safePacket.rangeStart || safePacket.rangeEnd || ''
  );
  return 'OTP-' + ceHashOriginalTimelineText([
    archiveId || '',
    safePacket.source || '',
    safePacket.timelineSourceLabel || '',
    safePacket.rangeStart || comparableMonth || '',
    safePacket.rangeEnd || comparableMonth || '',
    firstEvent && (firstEvent.code || firstEvent.hash || firstEvent.text) ? (firstEvent.code || firstEvent.hash || firstEvent.text) : '',
    lastEvent && (lastEvent.code || lastEvent.hash || lastEvent.text) ? (lastEvent.code || lastEvent.hash || lastEvent.text) : '',
    safePacket.playerInvolved ? 'player' : 'npc'
  ].join('|')).toUpperCase();
}

function ceNormalizeOriginalTimelineEventCodeList(codes) {
  const seen = new Set();
  let fallbackIndex = 0;
  return (Array.isArray(codes) ? codes : []).map(function(code) {
    const raw = String(code || '').trim();
    if (!raw) return '';
    const explicitCode = ceExtractOriginalTimelineEventDisplayCode(raw);
    if (explicitCode) return explicitCode;
    fallbackIndex += 1;
    return 'E-' + String(fallbackIndex).padStart(3, '0');
  }).filter(function(code) {
    if (!code || seen.has(code)) return false;
    seen.add(code);
    return true;
  });
}

function ceParseOriginalTimelineSortableEventCode(code) {
  const raw = String(code || '').trim();
  if (!raw) return null;
  const match = raw.match(/^([A-Za-z]{1,5})-(\d{2,4})([A-Za-z]?)$/);
  if (!match) return null;
  return {
    code: raw,
    prefix: String(match[1] || '').toUpperCase(),
    number: Number(match[2] || 0),
    width: String(match[2] || '').length,
    suffix: String(match[3] || '').toUpperCase()
  };
}

function ceSortOriginalTimelineEventCodes(codes) {
  return ceNormalizeOriginalTimelineEventCodeList(codes).sort(function(a, b) {
    const left = ceParseOriginalTimelineSortableEventCode(a);
    const right = ceParseOriginalTimelineSortableEventCode(b);
    if (left && right) {
      if (left.prefix !== right.prefix) return left.prefix < right.prefix ? -1 : 1;
      if (left.suffix !== right.suffix) return left.suffix < right.suffix ? -1 : 1;
      if (left.number !== right.number) return left.number - right.number;
      if (left.width !== right.width) return left.width - right.width;
      return a < b ? -1 : (a > b ? 1 : 0);
    }
    if (left) return -1;
    if (right) return 1;
    return a < b ? -1 : (a > b ? 1 : 0);
  });
}

function ceBuildOriginalTimelineEventCodeRanges(codes) {
  const sortedCodes = ceSortOriginalTimelineEventCodes(codes);
  const rows = [];
  let active = null;
  const buildCodeText = function(meta, number) {
    return meta.prefix + '-' + String(number).padStart(meta.width, '0') + meta.suffix;
  };
  const flush = function() {
    if (!active) return;
    const startCode = buildCodeText(active, active.startNumber);
    const endCode = buildCodeText(active, active.endNumber);
    rows.push(active.startNumber === active.endNumber ? startCode : (startCode + ' ~ ' + endCode));
    active = null;
  };
  sortedCodes.forEach(function(code) {
    const parsed = ceParseOriginalTimelineSortableEventCode(code);
    if (!parsed) {
      flush();
      rows.push(code);
      return;
    }
    if (!active) {
      active = {
        prefix: parsed.prefix,
        suffix: parsed.suffix,
        width: parsed.width,
        startNumber: parsed.number,
        endNumber: parsed.number
      };
      return;
    }
    if (parsed.prefix === active.prefix
      && parsed.suffix === active.suffix
      && parsed.width === active.width
      && parsed.number === active.endNumber + 1) {
      active.endNumber = parsed.number;
      return;
    }
    flush();
    active = {
      prefix: parsed.prefix,
      suffix: parsed.suffix,
      width: parsed.width,
      startNumber: parsed.number,
      endNumber: parsed.number
    };
  });
  flush();
  return rows;
}

function ceIsOriginalTimelinePartialProgressRecord(record) {
  const safeRecord = record && typeof record === 'object' ? record : null;
  if (!safeRecord) return false;
  const status = String(safeRecord.status || '').trim();
  if (status === 'partially_resolved') return true;
  if (Math.max(0, Number(safeRecord.progressPartialCount || 0) || 0) > 0) return true;
  const partialCodes = Array.isArray(safeRecord.partialEventCodes)
    ? safeRecord.partialEventCodes.map(function(code) {
        return String(code || '').trim();
      }).filter(Boolean)
    : [];
  return partialCodes.length > 0;
}

function ceCollectOriginalTimelineProcessedEventCodesFromRecord(record) {
  const safeRecord = record && typeof record === 'object' ? record : null;
  if (!safeRecord) return [];
  const status = String(safeRecord.status || '').trim();
  const skipReason = String(safeRecord.skipReason || '').trim();
  if (status === 'covered_by_story' || skipReason === 'story_already_covered') return [];
  const completedPrefixCodes = Array.isArray(safeRecord.completedPrefixEventCodes)
    ? safeRecord.completedPrefixEventCodes
    : [];
  if (ceIsOriginalTimelinePartialProgressRecord(safeRecord)) {
    return ceSortOriginalTimelineEventCodes(completedPrefixCodes);
  }
  if (!['processed', 'replayed'].includes(status)) {
    return ceSortOriginalTimelineEventCodes(completedPrefixCodes);
  }
  const explicitCodes = Array.isArray(safeRecord.processedEventCodes) && safeRecord.processedEventCodes.length > 0
    ? safeRecord.processedEventCodes
    : String(safeRecord.eventCode || '').split('|');
  return ceSortOriginalTimelineEventCodes(completedPrefixCodes.concat(explicitCodes));
}

function ceFinalizeOriginalTimelineHistoricalProgressState(codes, meta = {}) {
  const processedEventCodes = ceSortOriginalTimelineEventCodes(codes);
  const processedDisplayRanges = ceBuildOriginalTimelineEventCodeRanges(processedEventCodes);
  const lastProcessedEventCode = processedEventCodes.length > 0
    ? processedEventCodes[processedEventCodes.length - 1]
    : '';
  return {
    version: 1,
    processedEventCodes: processedEventCodes,
    processedDisplayRanges: processedDisplayRanges,
    processedSummary: processedDisplayRanges.join('、'),
    processedCount: processedEventCodes.length,
    lastProcessedEventCode: lastProcessedEventCode,
    lastUpdatedAt: String(meta.lastUpdatedAt || '').trim(),
    lastLedgerId: String(meta.lastLedgerId || '').trim()
  };
}

function ceBuildOriginalTimelineHistoricalProgressStateFromEntries(entries, options = {}) {
  const rows = Array.isArray(entries) ? entries : [];
  const codes = [];
  rows.forEach(function(entry) {
    codes.push.apply(codes, ceCollectOriginalTimelineProcessedEventCodesFromRecord(entry));
  });
  const lastEntry = rows.length > 0 ? rows[0] : null;
  return ceFinalizeOriginalTimelineHistoricalProgressState(codes, {
    lastUpdatedAt: options.lastUpdatedAt !== undefined
      ? options.lastUpdatedAt
      : (lastEntry && lastEntry.processedAt ? lastEntry.processedAt : ''),
    lastLedgerId: options.lastLedgerId !== undefined
      ? options.lastLedgerId
      : (lastEntry && lastEntry.ledgerId ? lastEntry.ledgerId : '')
  });
}

function ceMergeOriginalTimelineHistoricalProgressState(previousState, record) {
  const previousCodes = Array.isArray(previousState && previousState.processedEventCodes)
    ? previousState.processedEventCodes
    : [];
  const nextCodes = previousCodes.concat(ceCollectOriginalTimelineProcessedEventCodesFromRecord(record));
  return ceFinalizeOriginalTimelineHistoricalProgressState(nextCodes, {
    lastUpdatedAt: record && record.processedAt
      ? record.processedAt
      : (previousState && previousState.lastUpdatedAt ? previousState.lastUpdatedAt : ''),
    lastLedgerId: record && record.ledgerId
      ? record.ledgerId
      : (previousState && previousState.lastLedgerId ? previousState.lastLedgerId : '')
  });
}

function ceCloneOriginalTimelinePacketWithEvents(packet, events, options = {}) {
  const basePacket = packet && typeof packet === 'object' ? packet : null;
  if (!basePacket) return null;
  const opts = options || {};
  const nextEvents = Array.isArray(events)
    ? events.map(function(item) { return item && typeof item === 'object' ? Object.assign({}, item) : item; })
    : [];
  const nextEventCodes = nextEvents.map(function(item) {
    return String(item && item.code || '').trim();
  }).filter(Boolean);
  const nextEventHashes = ceBuildOriginalTimelineEventHashes(nextEvents);
  const progressPointer = opts.progressPointer && typeof opts.progressPointer === 'object'
    ? Object.assign({}, opts.progressPointer)
    : null;
  const totalEventCount = Math.max(0, Number(
    opts.totalCount !== undefined
      ? opts.totalCount
      : (Number(basePacket.totalEventCount || 0) || ((Array.isArray(basePacket.events) ? basePacket.events.length : nextEvents.length)))
  ) || 0);
  const processedCount = Math.max(0, Number(opts.processedCount !== undefined ? opts.processedCount : basePacket.progressProcessedCount || 0) || 0);
  const pendingCount = Math.max(0, Number(opts.pendingCount !== undefined ? opts.pendingCount : nextEvents.length) || 0);
  const cloned = Object.assign({}, basePacket, {
    events: nextEvents,
    eventCodes: nextEventCodes,
    eventHashes: nextEventHashes,
    progressKey: String(opts.progressKey || basePacket.progressKey || ceBuildOriginalTimelineProgressKey(basePacket, currentArchiveName || '') || '').trim(),
    progressPointer: progressPointer,
    progressProcessedCount: processedCount,
    progressPendingCount: pendingCount,
    totalEventCount: totalEventCount,
    dedupeHash: ''
  });
  cloned.dedupeHash = ceHashOriginalTimelineText([
    cloned.mode || '',
    cloned.source || '',
    cloned.anchorTime || '',
    cloned.rangeStart || '',
    cloned.rangeEnd || '',
    nextEventCodes.join('|'),
    nextEventHashes.join('|'),
    cloned.playerInvolved ? 'player' : 'npc',
    cloned.timelineSourceLabel || ''
  ].join('|'));
  return cloned;
}

function ceMatchOriginalTimelineEventByIdentity(left, right) {
  const leftCode = String(left && left.code || '').trim();
  const rightCode = String(right && right.code || '').trim();
  if (leftCode && rightCode) return leftCode === rightCode;
  const leftHash = String(left && left.hash || '').trim();
  const rightHash = String(right && right.hash || '').trim();
  if (leftHash && rightHash) return leftHash === rightHash;
  return false;
}

function ceResolveOriginalTimelineCompressedPendingState(events, anchorTime) {
  const list = Array.isArray(events)
    ? events.map(function(item) { return item && typeof item === 'object' ? Object.assign({}, item) : item; })
    : [];
  if (list.length < 2) {
    return {
      pendingEvents: list,
      completedPrefixEvents: [],
      activeTailEvent: list.length > 0 ? list[0] : null,
      compressed: false
    };
  }
  if (typeof ceResolveOriginalTimelineCurrentAnchoredEvent !== 'function') {
    return {
      pendingEvents: list,
      completedPrefixEvents: [],
      activeTailEvent: list.length > 0 ? list[0] : null,
      compressed: false
    };
  }
  const resolvedTail = ceResolveOriginalTimelineCurrentAnchoredEvent({ events: list }, String(anchorTime || '').trim());
  if (!resolvedTail) {
    return {
      pendingEvents: list,
      completedPrefixEvents: [],
      activeTailEvent: list.length > 0 ? list[0] : null,
      compressed: false
    };
  }
  const tailIndex = list.findIndex(function(item) {
    return ceMatchOriginalTimelineEventByIdentity(item, resolvedTail);
  });
  if (tailIndex <= 0) {
    return {
      pendingEvents: list,
      completedPrefixEvents: [],
      activeTailEvent: list.length > 0 ? list[0] : null,
      compressed: false
    };
  }
  const completedPrefixEvents = list.slice(0, tailIndex).map(function(item) {
    return item && typeof item === 'object' ? Object.assign({}, item) : item;
  });
  const activeTailEvent = list[tailIndex] && typeof list[tailIndex] === 'object'
    ? Object.assign({}, list[tailIndex])
    : list[tailIndex];
  return {
    pendingEvents: activeTailEvent ? [activeTailEvent] : [],
    completedPrefixEvents: completedPrefixEvents,
    activeTailEvent: activeTailEvent || null,
    compressed: completedPrefixEvents.length > 0
  };
}

function ceBuildOriginalTimelineProgressPointer(sharedContext, entries) {
  const ctx = sharedContext || {};
  const basePacket = ctx.originalTimelineBasePacket || ctx.originalTimelinePacket || null;
  if (!basePacket || !Array.isArray(basePacket.events) || basePacket.events.length === 0) return null;
  const progressKey = String(
    basePacket.progressKey || ceBuildOriginalTimelineProgressKey(basePacket, currentArchiveName || '') || ''
  ).trim();
  if (!progressKey) return null;
  const rows = Array.isArray(entries) ? entries : [];
  const processedStatusMap = {
    processed: true,
    replayed: true
  };
  const partialStatusMap = {
    partially_resolved: true
  };
  const matchedEntries = rows.filter(function(entry) {
    const status = String(entry && entry.status || '').trim();
    const skipReason = String(entry && entry.skipReason || '').trim();
    return entry
      && typeof entry === 'object'
      && String(entry.progressKey || '').trim() === progressKey
      && (processedStatusMap[status] || partialStatusMap[status])
      && status !== 'covered_by_story'
      && skipReason !== 'story_already_covered';
  });
  const processedCodeSet = new Set();
  const processedHashSet = new Set();
  const partialCodeSet = new Set();
  const partialHashSet = new Set();
  const collectTextList = function(list, targetSet) {
    (Array.isArray(list) ? list : [])
      .map(function(item) { return String(item || '').trim(); })
      .filter(Boolean)
      .forEach(function(item) { targetSet.add(item); });
  };
  matchedEntries.forEach(function(entry) {
    const completedPrefixCodes = Array.isArray(entry && entry.completedPrefixEventCodes)
      ? entry.completedPrefixEventCodes
      : [];
    const completedPrefixHashes = Array.isArray(entry && entry.completedPrefixEventHashes)
      ? entry.completedPrefixEventHashes
      : [];
    collectTextList(completedPrefixCodes, processedCodeSet);
    collectTextList(completedPrefixHashes, processedHashSet);
    if (ceIsOriginalTimelinePartialProgressRecord(entry)) {
      collectTextList(Array.isArray(entry && entry.partialEventCodes) ? entry.partialEventCodes : String(entry && entry.eventCode || '').split('|'), partialCodeSet);
      collectTextList(Array.isArray(entry && entry.partialEventHashes) ? entry.partialEventHashes : [], partialHashSet);
      return;
    }
    collectTextList(
      Array.isArray(entry && entry.processedEventCodes) && entry.processedEventCodes.length > 0
        ? entry.processedEventCodes
        : String(entry && entry.eventCode || '').split('|'),
      processedCodeSet
    );
    collectTextList(Array.isArray(entry && entry.processedEventHashes) ? entry.processedEventHashes : [], processedHashSet);
  });
  Array.from(processedCodeSet).forEach(function(code) {
    partialCodeSet.delete(code);
  });
  Array.from(processedHashSet).forEach(function(hash) {
    partialHashSet.delete(hash);
  });
  const allEvents = basePacket.events.map(function(item) {
    return item && typeof item === 'object' ? Object.assign({}, item) : item;
  });
  const unresolvedPendingEvents = allEvents.filter(function(item) {
    const code = String(item && item.code || '').trim();
    const hash = String(item && item.hash || '').trim();
    if (code && processedCodeSet.has(code)) return false;
    if (hash && processedHashSet.has(hash)) return false;
    return true;
  });
  const compressedPendingState = ceResolveOriginalTimelineCompressedPendingState(
    unresolvedPendingEvents,
    String(ctx.currentTime || basePacket.anchorTime || ctx.originalTimelineAnchor || '').trim()
  );
  const completedPrefixEvents = Array.isArray(compressedPendingState.completedPrefixEvents)
    ? compressedPendingState.completedPrefixEvents
    : [];
  completedPrefixEvents.forEach(function(item) {
    const code = String(item && item.code || '').trim();
    const hash = String(item && item.hash || '').trim();
    if (code) processedCodeSet.add(code);
    if (hash) processedHashSet.add(hash);
    if (code) partialCodeSet.delete(code);
    if (hash) partialHashSet.delete(hash);
  });
  const pendingEvents = Array.isArray(compressedPendingState.pendingEvents)
    ? compressedPendingState.pendingEvents
    : unresolvedPendingEvents;
  const partialPendingEvents = pendingEvents.filter(function(item) {
    const code = String(item && item.code || '').trim();
    const hash = String(item && item.hash || '').trim();
    return !!((code && partialCodeSet.has(code)) || (hash && partialHashSet.has(hash)));
  });
  const processedCount = Math.max(0, allEvents.length - pendingEvents.length);
  const partialPendingCount = partialPendingEvents.length;
  const untouchedPendingCount = Math.max(0, pendingEvents.length - partialPendingCount);
  const activeTailEvent = compressedPendingState && compressedPendingState.activeTailEvent
    ? compressedPendingState.activeTailEvent
    : (pendingEvents.length > 0 ? pendingEvents[0] : null);
  const activeTailEventCode = String(activeTailEvent && activeTailEvent.code || '').trim();
  const activeTailEventHash = String(activeTailEvent && activeTailEvent.hash || '').trim();
  const tailItemFactSignatureSet = new Set();
  if (activeTailEventCode || activeTailEventHash) {
    matchedEntries.forEach(function(entry) {
      if (!ceIsOriginalTimelinePartialProgressRecord(entry)) return;
      const partialCodes = Array.isArray(entry && entry.partialEventCodes) ? entry.partialEventCodes : [];
      const partialHashes = Array.isArray(entry && entry.partialEventHashes) ? entry.partialEventHashes : [];
      const matched = (activeTailEventCode && partialCodes.some(function(code) {
        return String(code || '').trim() === activeTailEventCode;
      })) || (activeTailEventHash && partialHashes.some(function(hash) {
        return String(hash || '').trim() === activeTailEventHash;
      }));
      if (!matched) return;
      collectTextList(Array.isArray(entry && entry.tailItemFactSignatures) ? entry.tailItemFactSignatures : [], tailItemFactSignatureSet);
    });
  }
  const pointer = {
    progressKey: progressKey,
    totalEventCount: allEvents.length,
    processedCount: processedCount,
    pendingCount: pendingEvents.length,
    untouchedPendingCount: untouchedPendingCount,
    partialPendingCount: partialPendingCount,
    completed: allEvents.length > 0 && pendingEvents.length === 0,
    isIncremental: processedCount > 0 || partialPendingCount > 0,
    processedEventCodes: ceSortOriginalTimelineEventCodes(Array.from(processedCodeSet)),
    processedEventHashes: Array.from(processedHashSet),
    partialEventCodes: partialPendingEvents.map(function(item) {
      return String(item && item.code || '').trim();
    }).filter(Boolean),
    partialEventHashes: partialPendingEvents.map(function(item) {
      return String(item && item.hash || '').trim();
    }).filter(Boolean),
    pendingEventCodes: pendingEvents.map(function(item) {
      return String(item && item.code || '').trim();
    }).filter(Boolean),
    pendingEventHashes: pendingEvents.map(function(item) {
      return String(item && item.hash || '').trim();
    }).filter(Boolean),
    pendingEvents: pendingEvents,
    completedPrefixEventCodes: completedPrefixEvents.map(function(item) {
      return String(item && item.code || '').trim();
    }).filter(Boolean),
    completedPrefixEventHashes: completedPrefixEvents.map(function(item) {
      return String(item && item.hash || '').trim();
    }).filter(Boolean),
    completedPrefixCount: completedPrefixEvents.length,
    activeTailEventCode: activeTailEventCode,
    activeTailEventHash: activeTailEventHash,
    compressedToSingleTail: !!(compressedPendingState && compressedPendingState.compressed),
    tailItemFactSignatures: Array.from(tailItemFactSignatureSet),
    lastProcessedAt: matchedEntries.map(function(entry) {
      return String(entry && entry.processedAt || '').trim();
    }).filter(Boolean).sort().slice(-1)[0] || ''
  };
  pointer.summary = '已归档 ' + pointer.processedCount + ' / ' + pointer.totalEventCount
    + (pointer.completedPrefixCount > 0 ? ('；本轮新归档 ' + pointer.completedPrefixCount) : '')
    + (pointer.partialPendingCount > 0 ? ('；当前尾事件部分推进 ' + pointer.partialPendingCount) : '')
    + (pointer.untouchedPendingCount > 0 ? ('；当前尾事件待继续推进 ' + pointer.untouchedPendingCount) : '；当前已无待推进事件');
  return pointer;
}

function ceApplyOriginalTimelineProgressPointer(sharedContext, pointer) {
  const ctx = sharedContext || {};
  const basePacket = ctx.originalTimelineBasePacket || ctx.originalTimelinePacket || null;
  if (!basePacket) return null;
  const progressPointer = pointer && typeof pointer === 'object' ? pointer : null;
  const pendingEvents = progressPointer && Array.isArray(progressPointer.pendingEvents)
    ? progressPointer.pendingEvents
    : (Array.isArray(basePacket.events) ? basePacket.events.slice() : []);
  const pendingPacket = ceCloneOriginalTimelinePacketWithEvents(basePacket, pendingEvents, {
    progressPointer: progressPointer,
    progressKey: progressPointer && progressPointer.progressKey ? progressPointer.progressKey : (basePacket.progressKey || ''),
    processedCount: progressPointer ? progressPointer.processedCount : 0,
    pendingCount: progressPointer ? progressPointer.pendingCount : pendingEvents.length,
    totalCount: progressPointer ? progressPointer.totalEventCount : pendingEvents.length
  });
  ctx.originalTimelineProgressPointer = progressPointer;
  ctx.originalTimelineProgressKey = progressPointer && progressPointer.progressKey
    ? progressPointer.progressKey
    : String(basePacket.progressKey || '').trim();
  ctx.originalTimelineProgressSummary = progressPointer && progressPointer.summary
    ? progressPointer.summary
    : '';
  ctx.originalTimelinePacket = pendingPacket;
  ctx.originalTimelinePackets = pendingPacket && Array.isArray(pendingPacket.events) && pendingPacket.events.length > 0
    ? ceBuildOriginalTimelinePacketGroups(pendingPacket)
    : [];
  return pendingPacket;
}

function ceBuildOriginalTimelinePacket(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const extractedEvents = ceExtractOriginalTimelineEventList(ctx);
  const mode = ceInferOriginalTimelineModeText(
    ctx.originalTimelineMode || originalCtx.modeText || '',
    ctx.originalTimelineRange || originalCtx.rangeText || '',
    ctx.originalTimelineRawBlock || originalCtx.rawBlock || ''
  );
  const source = ceInferOriginalTimelineTriggerSource(ctx);
  const anchorTime = ctx.originalTimelineAnchor || originalCtx.anchorTime || '';
  const allowCrossMonthReplay = mode === 'batch'
    || ['skip_time', 'retreat', 'manual_replay'].includes(String(source || '').trim());
  let events = extractedEvents;
  if (!allowCrossMonthReplay) {
    events = ceFilterOriginalTimelineRowsByAnchorTime(extractedEvents, anchorTime, function(item) {
      return item && item.text ? item.text : '';
    });
  }
  // 关键修复：普通回合的 standalone 原著补演必须整包一次性处理，
  // 不能因为命中多个事件就拆成逐步 replay；否则会把一轮补演膨胀成多次串行 API 请求，
  // 出现“原著演化中·推演人物与局势...”长时间卡住的假死表现。
  const stepReplay = !!(ctx.originalTimelineStandaloneStepReplayEnabled && !allowCrossMonthReplay && events.length > 1);
  const eventCodes = ceBuildOriginalTimelineEventCodes(events, ctx);
  const rangeEdges = ceNormalizeOriginalTimelineRangeEdges(
    ctx.originalTimelineRange || originalCtx.rangeText || '',
    anchorTime
  );
  const personCandidates = ceGetOriginalTimelineCharacterCandidatesFromContext(ctx, options);
  const referenceCandidates = ceGetOriginalReferenceCandidatesFromContext(ctx, options);
  const byType = referenceCandidates && referenceCandidates.byType ? referenceCandidates.byType : ceBuildEmptyOriginalReferenceBuckets();
  const eventTags = Array.from(new Set(
    events.reduce((acc, item) => {
      if (item && Array.isArray(item.tags)) acc.push(...item.tags);
      return acc;
    }, [])
  ));

  const normalizeEntityRows = (rows) => (Array.isArray(rows) ? rows : []).map(item => ({
    name: item && (item.raw || item.normalized) ? (item.raw || item.normalized) : '',
    normalized: item && item.normalized ? item.normalized : '',
    score: Number(item && (item.score || item.totalScore) || 0),
    sources: Array.isArray(item && item.sources) ? item.sources.slice() : []
  })).filter(item => item.name);

  const packet = {
    mode,
    source,
    anchorTime: anchorTime,
    rangeStart: rangeEdges.rangeStart || '',
    rangeEnd: rangeEdges.rangeEnd || '',
    events: events.map((item, index) => Object.assign({}, item, {
      code: eventCodes[index] || ''
    })),
    eventCodes,
    eventHashes: [],
    stepReplay,
    entityCandidates: {
      persons: normalizeEntityRows(personCandidates),
      items: normalizeEntityRows(byType.item),
      techniques: normalizeEntityRows(byType.technique),
      factions: normalizeEntityRows(byType.faction),
      locations: normalizeEntityRows(byType.location),
      beasts: normalizeEntityRows(byType.beast),
      eventTags
    },
    playerInvolved: ceInferOriginalTimelinePlayerInvolved(ctx),
    timelineSourceLabel: ctx.originalTimelineSourceLabel || originalCtx.sourceLabel || '',
    progressKey: '',
    progressPointer: null,
    progressProcessedCount: 0,
    progressPendingCount: 0,
    totalEventCount: 0,
    dedupeHash: ''
  };

  packet.eventHashes = ceBuildOriginalTimelineEventHashes(packet.events);
  packet.progressKey = ceBuildOriginalTimelineProgressKey(packet, currentArchiveName || '');
  packet.progressProcessedCount = 0;
  packet.progressPendingCount = packet.events.length;
  packet.totalEventCount = packet.events.length;
  packet.dedupeHash = ceHashOriginalTimelineText([
    packet.mode || '',
    packet.source || '',
    packet.anchorTime || '',
    packet.rangeStart || '',
    packet.rangeEnd || '',
    packet.eventCodes.join('|'),
    packet.eventHashes.join('|'),
    packet.playerInvolved ? 'player' : 'npc',
    packet.timelineSourceLabel || ''
  ].join('|'));

  ceTraceDiag('ORIGINAL_TIMELINE_PACKET', {
    mode,
    source,
    anchorTime,
    allowCrossMonthReplay,
    extractedEventCount: extractedEvents.length,
    packetEventCount: packet.events.length,
    rangeStart: packet.rangeStart || '',
    rangeEnd: packet.rangeEnd || '',
    eventCodes,
    events: packet.events.map(function(item, index) {
      const textCode = ceExtractOriginalTimelineEventDisplayCode(item && item.text ? item.text : '');
      return {
        index: item && item.index ? item.index : (index + 1),
        finalCode: eventCodes[index] || '',
        textCode: textCode || '',
        codeHint: item && item.codeHint ? item.codeHint : '',
        title: item && item.title ? item.title : '',
        timeStart: item && item.timeStart ? item.timeStart : '',
        timeEnd: item && item.timeEnd ? item.timeEnd : ''
      };
    }),
    mismatchedCodes: packet.events.map(function(item, index) {
      const textCode = ceExtractOriginalTimelineEventDisplayCode(item && item.text ? item.text : '');
      const finalCode = eventCodes[index] || '';
      if (!textCode || !finalCode || textCode === finalCode) return null;
      return {
        index: item && item.index ? item.index : (index + 1),
        textCode,
        finalCode,
        title: item && item.title ? item.title : ''
      };
    }).filter(Boolean)
  });

  ctx.originalTimelineEventTags = eventTags;
  ctx.originalTimelineTriggerSource = source;
  ctx.originalTimelinePacket = packet;
  ctx.originalTimelineBasePacket = (options && options.preserveBasePacket === true && ctx.originalTimelineBasePacket)
    ? ctx.originalTimelineBasePacket
    : packet;
  ctx.originalTimelineProgressPointer = null;
  ctx.originalTimelineProgressKey = packet.progressKey || '';
  ctx.originalTimelineProgressSummary = '';
  ctx.originalTimelinePackets = (packet.events.length > 0 || packet.anchorTime || packet.rangeStart || packet.rangeEnd)
    ? [packet]
    : [];
  if (!Array.isArray(ctx.originalTimelineBatchReplayHistory)) {
    ctx.originalTimelineBatchReplayHistory = [];
  }
  if (typeof ctx.originalTimelineBatchReplayInstruction !== 'string') {
    ctx.originalTimelineBatchReplayInstruction = '';
  }
  return packet;
}

function ceBuildOriginalTimelineLedgerStateText(sharedContext) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const packet = ctx.originalTimelinePacket || ceBuildOriginalTimelinePacket(ctx);
  const coldStartResult = ctx.originalTimelineColdStartResult || {};
  const personCandidates = ceGetOriginalTimelineCharacterCandidatesFromContext(ctx);
  const referenceCandidates = ceGetOriginalReferenceCandidatesFromContext(ctx);
  const byType = referenceCandidates && referenceCandidates.byType ? referenceCandidates.byType : ceBuildEmptyOriginalReferenceBuckets();
  const matchedCount = Array.isArray(coldStartResult.matched) ? coldStartResult.matched.length : 0;
  const createdCount = Array.isArray(coldStartResult.created) ? coldStartResult.created.length : 0;
  const unresolvedCount = Array.isArray(coldStartResult.unresolved) ? coldStartResult.unresolved.length : 0;
  const packetCodes = Array.isArray(packet && packet.eventCodes) ? packet.eventCodes : [];
  const packetEvents = Array.isArray(packet && packet.events) ? packet.events : [];
  const ledgerSummary = [
    '账本键: ' + [
      ctx.originalTimelineAnchor || originalCtx.anchorTime || '',
      ctx.originalTimelineMode || originalCtx.modeText || '',
      ctx.originalTimelineRange || originalCtx.rangeText || '',
      ctx.originalTimelineAudit || originalCtx.auditSeed || ''
    ].filter(Boolean).join(' | '),
    '触发来源: ' + (packet && packet.source ? packet.source : 'regular_turn'),
    '事件分组: ' + (packet && packet.mode ? packet.mode : 'single') + ' / ' + packetEvents.length + '条',
    packetCodes.length ? ('事件编码: ' + packetCodes.slice(0, 4).join('、') + (packetCodes.length > 4 ? ' …' : '')) : '',
    packet && packet.dedupeHash ? ('去重哈希: ' + packet.dedupeHash) : '',
    '检索作用域: archive优先 / global兜底',
    '人物候选数: ' + personCandidates.length,
    '人物建档状态: 命中' + matchedCount + ' / 新建' + createdCount + ' / 暂未匹配' + unresolvedCount,
    '非人物候选数: 物品' + ((byType.item || []).length) + ' / 功法' + ((byType.technique || []).length) + ' / 势力' + ((byType.faction || []).length) + ' / 地点' + ((byType.location || []).length) + ' / 灵兽' + ((byType.beast || []).length)
  ].filter(Boolean).join('\n');
  ctx.originalTimelineLedgerSummary = ledgerSummary;
  return ledgerSummary;
}

function ceBuildOriginalTimelineNameVariants(raw) {
  const base = ceNormalizeOriginalTimelineName(raw);
  const variants = new Set();
  const pushVariant = (value) => {
    const normalized = ceNormalizeOriginalTimelineName(value);
    if (!normalized) return;
    if (normalized.length < 2 || normalized.length > 8) return;
    if (ceIsOriginalTimelineLikelyNonPersonName(normalized)) return;
    variants.add(normalized);
  };

  pushVariant(base);
  CE_ORIGINAL_TIMELINE_TITLE_SUFFIXES.forEach(suffix => {
    if (base.endsWith(suffix) && base.length > suffix.length + 1) {
      pushVariant(base.slice(0, -suffix.length));
    }
  });
  ['老', '小', '阿', '大'].forEach(prefix => {
    if (base.startsWith(prefix) && base.length > 2) {
      pushVariant(base.slice(1));
    }
  });

  return Array.from(variants);
}

async function ceBuildOriginalTimelineNpcArchiveIndex(options = {}) {
  const opts = options || {};
  const sharedCtx = opts.sharedContext || null;
  const timelineCandidateText = sharedCtx
    ? ceSanitizeOriginalTimelineCandidateText(
        sharedCtx.originalTimelineEvents || (sharedCtx.originalTimelineContext && sharedCtx.originalTimelineContext.eventTextBlock) || ''
      )
    : '';
  const directActorNames = timelineCandidateText
    ? ceCollectOriginalTimelineDirectActorNames(timelineCandidateText)
    : new Set();
  const includePlayer = opts.includePlayer === true
    || (!!sharedCtx && ceInferOriginalTimelinePlayerInvolved(sharedCtx));
  const recordsMap = new Map();
  let maxNpcNumber = 0;

  const upsertRecord = (record) => {
    if (!record || !record.id) return;
    const existing = recordsMap.get(record.id);
    if (existing) {
      if (!existing.name && record.name) existing.name = record.name;
      if (!existing.normalizedName && record.normalizedName) existing.normalizedName = record.normalizedName;
      if (!existing.data && record.data) existing.data = record.data;
      if (record.sceneType === 'onscene') existing.sceneType = 'onscene';
      if (!existing.source && record.source) existing.source = record.source;
      if (!(existing.aliases instanceof Set)) existing.aliases = new Set();
      if (record.aliases instanceof Set) {
        record.aliases.forEach(alias => existing.aliases.add(alias));
      }
      return;
    }
    recordsMap.set(record.id, record);
    const match = /^C(\d+)$/.exec(String(record.id || ''));
    if (match) {
      const num = parseInt(match[1], 10);
      if (!isNaN(num) && num > maxNpcNumber) maxNpcNumber = num;
    }
  };

  if (currentState && currentState['0']) {
    const playerRow = currentState['0']['B1'];
    if (playerRow && typeof playerRow === 'object') {
      const playerRawName = (playerRow['1'] || '').split('|')[0] || 'B1';
      const playerVariants = ceBuildOriginalTimelineNameVariants(playerRawName);
      const playerNormalizedName = playerVariants[0] || ceNormalizeOriginalTimelineName(playerRawName);
      const playerDirectlyMentioned = playerVariants.some(function(name) {
        return directActorNames.has(name);
      });
      if ((includePlayer || playerDirectlyMentioned) && playerNormalizedName) {
        upsertRecord({
          id: 'B1',
          name: ceStripHtmlTagsLite(playerRawName),
          normalizedName: playerNormalizedName,
          aliases: ceExtractOriginalTimelineAliasList(playerRow, { name: playerRawName }),
          data: playerRow,
          sceneType: 'onscene',
          source: playerDirectlyMentioned ? 'current_state_player_direct_actor' : 'current_state_player'
        });
      }
    }
    Object.entries(currentState['0']).forEach(([id, row]) => {
      if (!row || id === 'B1' || id === 'TIME_LOCATION_ROW') return;
      const rawName = (row['1'] || '').split('|')[0] || id;
      const normalizedName = ceBuildOriginalTimelineNameVariants(rawName)[0] || ceNormalizeOriginalTimelineName(rawName);
      if (!normalizedName) return;
      upsertRecord({
        id: String(row['0'] || id),
        name: ceStripHtmlTagsLite(rawName),
        normalizedName,
        aliases: ceExtractOriginalTimelineAliasList(row, { name: rawName }),
        data: row,
        sceneType: 'onscene',
        source: 'current_state'
      });
    });
  }

  try {
    const worldBookEntries = await ceGetAuthoritativeWorldBookEntries({
      context: 'original_timeline_archive_index',
      throwOnMissing: true
    });
    if (Array.isArray(worldBookEntries)) {
      worldBookEntries.forEach(entry => {
        if (!entry || typeof entry !== 'object') return;
        const entryType = (entry.type || entry.category || '').toString().toLowerCase();
        if (entryType && !['人物', 'npc', '角色', 'character', ''].includes(entryType)) return;

        let data = null;
        try {
          if (entry.content && typeof entry.content === 'string') {
            data = JSON.parse(entry.content);
          } else if (entry.content && typeof entry.content === 'object') {
            data = entry.content;
          }
        } catch (e) {
          data = null;
        }
        if (!data || typeof data !== 'object') return;

        const entryId = String(entry.key || entry.id || entry.characterId || entry.charId || data['0'] || '').trim();
        if (!entryId || entryId === 'B1') return;

        const rawName = (data['1'] || '').split('|')[0] || entry.title || entry.name || entry.displayName || entryId;
        const normalizedName = ceBuildOriginalTimelineNameVariants(rawName)[0] || ceNormalizeOriginalTimelineName(rawName);
        if (!normalizedName) return;

        upsertRecord({
          id: entryId,
          name: ceStripHtmlTagsLite(rawName),
          normalizedName,
          aliases: ceExtractOriginalTimelineAliasList(data, entry),
          data,
          sceneType: 'offscene',
          source: 'worldbook'
        });
      });
    }
  } catch (e) {
    if (opts.strict) throw e;
    console.warn('[原著年表] 构建NPC档案索引失败:', e);
  }

  return {
    records: Array.from(recordsMap.values()),
    maxNpcNumber
  };
}

function ceBuildOriginalTimelineNpcRoutingPlan(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const archiveIndex = options.archiveIndex && Array.isArray(options.archiveIndex.records)
    ? options.archiveIndex
    : { records: [] };
  const result = {
    onsceneIds: new Set(),
    offsceneIds: new Set(),
    onsceneCandidates: [],
    offsceneCandidates: [],
    unresolvedCandidates: []
  };
  const candidates = ceExtractOriginalTimelineCharacterCandidates(ctx, Object.assign({}, options, {
    archiveIndex,
    includeOnscene: true
  }));
  candidates.forEach(candidate => {
    const archiveMatch = ceMatchOriginalTimelineCandidateToArchive(candidate, archiveIndex);
    const strictOnsceneMatch = ceMatchOriginalTimelineCandidateToArchive(candidate, archiveIndex, {
      sceneType: 'onscene',
      allowFuzzy: false
    });
    const effectiveMatch = strictOnsceneMatch
      && archiveMatch
      && archiveMatch.record
      && String(archiveMatch.record.sceneType || '').trim() !== 'onscene'
      ? strictOnsceneMatch
      : archiveMatch;
    const candidateSources = Array.isArray(candidate && candidate.sources) ? candidate.sources : [];
    const isDirectActorCandidate = candidateSources.some(function(source) {
      return ceIsOriginalTimelineDirectActorSource(source);
    });
    const storyHandledByCurrentTurn = typeof ceIsOriginalTimelineCandidateExplicitlyMentioned === 'function'
      ? ceIsOriginalTimelineCandidateExplicitlyMentioned(candidate, ctx.storyText || '', ctx.userInput || '')
      : false;
    if (storyHandledByCurrentTurn && !isDirectActorCandidate && effectiveMatch && effectiveMatch.record && effectiveMatch.record.sceneType !== 'onscene') {
      result.unresolvedCandidates.push(Object.assign({}, candidate, {
        blockedReason: 'story_handled_current_turn',
        blockedMatchType: effectiveMatch.matchType,
        blockedTargetId: String(effectiveMatch.record.id || '').trim()
      }));
      return;
    }
    if (!effectiveMatch || !effectiveMatch.record || !effectiveMatch.record.id) {
      result.unresolvedCandidates.push(candidate);
      return;
    }
    const routedCandidate = Object.assign({}, candidate, {
      id: String(effectiveMatch.record.id),
      name: effectiveMatch.record.name || candidate.raw || effectiveMatch.record.id,
      sceneType: effectiveMatch.record.sceneType || 'offscene',
      matchType: effectiveMatch.matchType,
      confidence: effectiveMatch.confidence
    });
    if (routedCandidate.sceneType === 'onscene') {
      result.onsceneIds.add(routedCandidate.id);
      result.onsceneCandidates.push(routedCandidate);
    } else {
      result.offsceneIds.add(routedCandidate.id);
      result.offsceneCandidates.push(routedCandidate);
    }
  });
  return result;
}

function ceApplyOriginalTimelineNpcRoutingState(sharedContext, archiveIndex, options = {}) {
  const ctx = sharedContext || {};
  const opts = options || {};
  try {
    const routingPlan = ceBuildOriginalTimelineNpcRoutingPlan(ctx, {
      archiveIndex: archiveIndex && Array.isArray(archiveIndex.records)
        ? archiveIndex
        : { records: [] }
    });
    ctx.originalTimelineOnsceneTargetIds = routingPlan.onsceneIds;
    ctx.originalTimelineOffsceneTargetIds = routingPlan.offsceneIds;
    ctx.originalTimelineOnsceneCandidates = routingPlan.onsceneCandidates;
    ctx.originalTimelineOffsceneCandidates = routingPlan.offsceneCandidates;
    ctx.originalTimelineUnresolvedCharacterCandidates = routingPlan.unresolvedCandidates;
  } catch (e) {
    console.warn(opts.errorMessage || '[原著年表] 人物分流刷新失败:', e);
    if (opts.resetOnError !== false) {
      ctx.originalTimelineOnsceneTargetIds = new Set();
      ctx.originalTimelineOffsceneTargetIds = new Set();
      ctx.originalTimelineOnsceneCandidates = [];
      ctx.originalTimelineOffsceneCandidates = [];
      ctx.originalTimelineUnresolvedCharacterCandidates = [];
    }
  }
  return {
    archiveIndex: ctx.originalTimelineNpcArchiveIndex,
    onsceneIds: ctx.originalTimelineOnsceneTargetIds,
    offsceneIds: ctx.originalTimelineOffsceneTargetIds,
    onsceneCandidates: ctx.originalTimelineOnsceneCandidates,
    offsceneCandidates: ctx.originalTimelineOffsceneCandidates,
    unresolvedCandidates: ctx.originalTimelineUnresolvedCharacterCandidates
  };
}

function ceRefreshOriginalTimelineReferenceCandidates(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const opts = options || {};
  try {
    ctx.originalTimelineReferenceCandidates = ceExtractOriginalTimelineReferenceCandidates(ctx);
  } catch (e) {
    console.warn(opts.errorMessage || '[原著年表] 非人物实体解析失败:', e);
    ctx.originalTimelineReferenceCandidates = null;
  }
  return ctx.originalTimelineReferenceCandidates;
}

async function ceRefreshOriginalTimelineNpcRoutingState(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const opts = options || {};
  try {
    const archiveIndex = opts.archiveIndex && Array.isArray(opts.archiveIndex.records)
      ? opts.archiveIndex
      : await ceBuildOriginalTimelineNpcArchiveIndex({ sharedContext: ctx });
    ctx.originalTimelineNpcArchiveIndex = archiveIndex;
    if (opts.resetCharacterCandidates === true) {
      ctx.originalTimelineCharacterCandidates = null;
    }
    return ceApplyOriginalTimelineNpcRoutingState(ctx, archiveIndex, opts);
  } catch (e) {
    console.warn(opts.errorMessage || '[原著年表] 人物分流刷新失败:', e);
    if (opts.resetOnError !== false) {
      ctx.originalTimelineNpcArchiveIndex = null;
      ctx.originalTimelineOnsceneTargetIds = new Set();
      ctx.originalTimelineOffsceneTargetIds = new Set();
      ctx.originalTimelineOnsceneCandidates = [];
      ctx.originalTimelineOffsceneCandidates = [];
      ctx.originalTimelineUnresolvedCharacterCandidates = [];
    }
  }
  return {
    archiveIndex: ctx.originalTimelineNpcArchiveIndex,
    onsceneIds: ctx.originalTimelineOnsceneTargetIds,
    offsceneIds: ctx.originalTimelineOffsceneTargetIds,
    onsceneCandidates: ctx.originalTimelineOnsceneCandidates,
    offsceneCandidates: ctx.originalTimelineOffsceneCandidates,
    unresolvedCandidates: ctx.originalTimelineUnresolvedCharacterCandidates
  };
}

function ceRefreshOriginalTimelinePacketState(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const opts = options || {};
  try {
    ctx.originalTimelinePacket = ceBuildOriginalTimelinePacket(ctx, { force: true });
    ctx.originalTimelinePackets = ceBuildOriginalTimelinePacketGroups(ctx.originalTimelinePacket);
    ctx.originalTimelineBasePacket = ctx.originalTimelinePacket || null;
  } catch (e) {
    console.warn(opts.errorMessage || '[原著年表] 原著事件数据包构建失败，继续执行变量演化:', e);
    ctx.originalTimelinePacket = null;
    ctx.originalTimelinePackets = [];
    ctx.originalTimelineBasePacket = null;
  }
  return ctx.originalTimelinePacket;
}

function ceBuildOriginalTimelineUnresolvedSummary(result) {
  const unresolved = Array.isArray(result && result.unresolved) ? result.unresolved : [];
  if (!unresolved.length) return '';
  return unresolved.slice(0, 8).map(item => {
    const candidate = item && item.candidate ? item.candidate : '未知实体';
    const reason = ceFormatOriginalTimelineColdStartReason(item && item.reason);
    return `${candidate}（${reason}）`;
  }).join('，');
}

async function ceEnsureOriginalReferenceVectorContext(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const prompt = String(options.prompt || '');
  const placeholderConfigs = [
    { key: 'original_character_vectors', type: 'character', contextKey: 'originalCharacterVectors', limit: 4, snippetLength: 260, fullText: false },
    { key: 'original_item_vectors', type: 'item', contextKey: 'originalItemVectors', limit: 4, snippetLength: 260, fullText: false },
    { key: 'original_technique_vectors', type: 'technique', contextKey: 'originalTechniqueVectors', limit: 4, snippetLength: 260, fullText: false },
    { key: 'original_faction_vectors', type: 'faction', contextKey: 'originalFactionVectors', limit: 3, snippetLength: 240, fullText: false },
    { key: 'original_location_vectors', type: 'location', contextKey: 'originalLocationVectors', limit: 3, snippetLength: 240, fullText: false },
    { key: 'original_beast_vectors', type: 'beast', contextKey: 'originalBeastVectors', limit: 3, snippetLength: 240, fullText: false },
    { key: 'original_reference_vectors', type: '', contextKey: 'originalReferenceVectors', limit: 6, snippetLength: 220, aggregate: true, fullText: false },
    { key: 'original_character_vectors_full', type: 'character', contextKey: 'originalCharacterVectorsFull', limit: 3, fullText: true },
    { key: 'original_item_vectors_full', type: 'item', contextKey: 'originalItemVectorsFull', limit: 3, fullText: true },
    { key: 'original_technique_vectors_full', type: 'technique', contextKey: 'originalTechniqueVectorsFull', limit: 3, fullText: true },
    { key: 'original_faction_vectors_full', type: 'faction', contextKey: 'originalFactionVectorsFull', limit: 3, fullText: true },
    { key: 'original_location_vectors_full', type: 'location', contextKey: 'originalLocationVectorsFull', limit: 3, fullText: true },
    { key: 'original_beast_vectors_full', type: 'beast', contextKey: 'originalBeastVectorsFull', limit: 3, fullText: true },
    { key: 'original_reference_full_blocks', type: '', contextKey: 'originalReferenceFullBlocks', limit: 4, aggregate: true, fullText: true }
  ];

  const requestedConfigs = options.force
    ? placeholderConfigs
    : placeholderConfigs.filter(item => prompt.includes('${' + item.key + '}'));
  if (!requestedConfigs.length) return ctx;

  if (!ctx.originalTimelineContext) {
    await ceEnsureOriginalTimelineContext(ctx, {
      currentTime: ctx.currentTime || '',
      snapshotText: ctx.stateSnapshot || ''
    });
  }

  const referenceVectorCache = await ceBuildOriginalReferenceVectorCache({
    force: !!options.force,
    referenceVectorCache: ctx._originalReferenceVectorCache
  });
  ctx._originalReferenceVectorCache = referenceVectorCache;

  const parsedCandidates = ceGetOriginalReferenceCandidatesFromContext(ctx, {
    ...options,
    referenceEntries: referenceVectorCache
  });
  const allCandidates = parsedCandidates && Array.isArray(parsedCandidates.all) ? parsedCandidates.all : [];
  const byType = parsedCandidates && parsedCandidates.byType ? parsedCandidates.byType : ceBuildEmptyOriginalReferenceBuckets();

  ctx.originalReferenceVectorResults = (ctx.originalReferenceVectorResults && typeof ctx.originalReferenceVectorResults === 'object')
    ? ctx.originalReferenceVectorResults
    : {};

  for (const config of requestedConfigs) {
    if (!options.force && Object.prototype.hasOwnProperty.call(ctx.originalReferenceVectorResults, config.key)) {
      const cached = ctx.originalReferenceVectorResults[config.key] || {};
      ctx[config.contextKey] = cached.text || '';
      continue;
    }

    let matches = [];
    if (config.aggregate) {
      if (allCandidates.length) {
        matches = await ceSearchOriginalEncyclopediaVectors('', allCandidates, {
          referenceVectorCache,
          limit: config.limit,
          minConfidence: 0.7
        });
      }
    } else if (config.type === 'character') {
      const characterCandidates = ceGetOriginalTimelineCharacterCandidatesFromContext(ctx, options);
      if (characterCandidates.length) {
        matches = await ceSearchOriginalReferenceVectors('character', characterCandidates, {
          biographyCache: ctx._biographyCache,
          limit: config.limit,
          minConfidence: 0.74
        });
      }
    } else {
      const typedCandidates = Array.isArray(byType[config.type]) ? byType[config.type] : [];
      if (typedCandidates.length) {
        matches = await ceSearchOriginalReferenceVectors(config.type, typedCandidates, {
          referenceVectorCache,
          biographyCache: ctx._biographyCache,
          limit: config.limit,
          minConfidence: 0.72
        });
      }
    }

    const text = ceFormatOriginalReferenceVectorMatches(matches, {
      limit: config.limit,
      snippetLength: config.snippetLength,
      fullText: config.fullText === true
    });
    ctx[config.contextKey] = text;
    ctx.originalReferenceVectorResults[config.key] = {
      matches,
      text
    };
  }

  return ctx;
}

async function ceEnsureOriginalTimelineContext(sharedContext, options) {
  const targetContext = sharedContext || {};
  const opts = options || {};
  if (targetContext.originalTimelineContext && !opts.force) {
    return targetContext.originalTimelineContext;
  }

  let rawBlock = typeof opts.rawBlock === 'string' ? opts.rawBlock : '';
  if (!rawBlock) {
    rawBlock = targetContext.worldTimelineContext || targetContext.originalTimelineRawBlock || '';
  }
  if (!rawBlock) {
    rawBlock = await ceBuildWorldTimelinePromptBlock({
      currentTime: opts.currentTime || targetContext.currentTime || '',
      snapshotText: opts.snapshotText || targetContext.stateSnapshot || '',
      userInput: opts.userInput || targetContext.userInput || '',
      sharedContext: targetContext,
      preferReplayBlock: opts.preferReplayBlock === true
    });
  }

  const resolvedCurrentTime = opts.currentTime || targetContext.currentTime || '';
  let parsed = ceParseOriginalTimelinePromptBlock(rawBlock);
  let anchorDrift = ceInspectOriginalTimelineAnchorDrift(parsed.anchorTime || '', resolvedCurrentTime);
  let rebuiltDueToAnchorMismatch = false;

  if (rawBlock && anchorDrift.suspicious) {
    ceTraceDiag('ORIGINAL_TIMELINE_CONTEXT', {
      stage: 'anchor_mismatch_rebuild',
      resolvedCurrentTime,
      rawAnchorTime: parsed.anchorTime || '',
      anchorDriftReason: anchorDrift.reason || '',
      anchorYearDelta: anchorDrift.yearDelta || 0,
      anchorMonthDelta: anchorDrift.monthDelta || 0,
      rawBlockPreview: String(rawBlock || '').slice(0, 700)
    });
    const rebuiltBlock = await ceBuildWorldTimelinePromptBlock({
      currentTime: resolvedCurrentTime,
      snapshotText: opts.snapshotText || targetContext.stateSnapshot || '',
      userInput: opts.userInput || targetContext.userInput || '',
      forceFresh: true,
      sharedContext: targetContext,
      preferReplayBlock: opts.preferReplayBlock === true
    });
    rebuiltDueToAnchorMismatch = true;
    rawBlock = String(rebuiltBlock || '');
    parsed = ceParseOriginalTimelinePromptBlock(rawBlock);
    anchorDrift = ceInspectOriginalTimelineAnchorDrift(parsed.anchorTime || '', resolvedCurrentTime);
  }

  const inferredTriggerSource = ceInferOriginalTimelineTriggerSource(Object.assign({}, targetContext, {
    originalTimelineSourceLabel: parsed.sourceLabel || targetContext.originalTimelineSourceLabel || '',
    originalTimelineMode: parsed.modeText || targetContext.originalTimelineMode || '',
    originalTimelineRange: parsed.rangeText || targetContext.originalTimelineRange || '',
    originalTimelineRawBlock: rawBlock || targetContext.originalTimelineRawBlock || ''
  }));
  const explicitBatchMode = /^(?:batch|区间|批量|闭关|跳时|快进|跨度|skip_time|retreat)$/i.test(String(parsed.modeText || '').trim());
  const preserveFullEventBlock = explicitBatchMode
    || ['skip_time', 'retreat', 'manual_replay'].includes(String(inferredTriggerSource || '').trim());
  const effectiveAnchorTime = ceResolveOriginalTimelineEffectiveAnchorTime(parsed.anchorTime || '', resolvedCurrentTime);
  const effectiveEventTextBlock = preserveFullEventBlock
    ? ceExtractOriginalTimelineSection(rawBlock)
    : ceFilterOriginalTimelineSectionByAnchorTime(
      ceExtractOriginalTimelineSection(rawBlock),
      effectiveAnchorTime || parsed.anchorTime || '',
      parsed.modeText || ''
    );
  const normalizedParsed = Object.assign({}, parsed, {
    modeText: preserveFullEventBlock ? 'batch' : (parsed.modeText || ''),
    anchorTime: effectiveAnchorTime || parsed.anchorTime || '',
    eventTextBlock: effectiveEventTextBlock || parsed.eventTextBlock || ''
  });
  normalizedParsed.eventDigest = ceBuildOriginalTimelineDigest(normalizedParsed);
  normalizedParsed.auditSeed = [
    normalizedParsed.anchorTime || '',
    normalizedParsed.modeText || '',
    normalizedParsed.rangeText || '',
    normalizedParsed.itemText || ''
  ].join('|');
  normalizedParsed.hasTimeline = !!(normalizedParsed.eventTextBlock || normalizedParsed.itemText || normalizedParsed.rangeText);
  ceTraceDiag('ORIGINAL_TIMELINE_CONTEXT', {
    resolvedCurrentTime,
    rawAnchorTime: parsed.anchorTime || '',
    effectiveAnchorTime: effectiveAnchorTime || '',
    anchorDriftReason: anchorDrift.reason || '',
    anchorYearDelta: anchorDrift.yearDelta || 0,
    anchorMonthDelta: anchorDrift.monthDelta || 0,
    anchorSuspicious: !!anchorDrift.suspicious,
    rebuiltDueToAnchorMismatch,
    inferredTriggerSource: inferredTriggerSource || '',
    preserveFullEventBlock,
    modeText: parsed.modeText || '',
    normalizedModeText: normalizedParsed.modeText || '',
    sourceLabel: parsed.sourceLabel || '',
    rangeText: parsed.rangeText || '',
    itemTextPreview: String(parsed.itemText || '').slice(0, 500),
    rawBlockPreview: String(rawBlock || '').slice(0, 700),
    filteredEventBlockPreview: String(normalizedParsed.eventTextBlock || '').slice(0, 700)
  });
  const playerImpactSummary = opts.playerImpactSummary
    || targetContext.originalTimelinePlayerImpact
    || '';

  targetContext.worldTimelineContext = rawBlock || '';
  targetContext.originalTimelineContext = {
    rawBlock: normalizedParsed.rawBlock || '',
    eventTextBlock: normalizedParsed.eventTextBlock || '',
    eventDigest: normalizedParsed.eventDigest || '',
    rangeText: normalizedParsed.rangeText || '',
    modeText: normalizedParsed.modeText || '',
    anchorTime: normalizedParsed.anchorTime || '',
    sourceLabel: normalizedParsed.sourceLabel || '',
    briefRangeText: normalizedParsed.briefRangeText || '',
    originalRangeText: normalizedParsed.originalRangeText || '',
    briefItemsText: normalizedParsed.briefItemsText || '',
    originalItemsText: normalizedParsed.originalItemsText || '',
    itemText: normalizedParsed.itemText || '',
    playerImpactSummary: playerImpactSummary,
    auditSeed: normalizedParsed.auditSeed || '',
    hasTimeline: !!normalizedParsed.hasTimeline
  };
  targetContext.originalTimelineRawBlock = targetContext.originalTimelineContext.rawBlock;
  targetContext.originalTimelineEvents = targetContext.originalTimelineContext.eventTextBlock;
  targetContext.originalTimelineDigest = targetContext.originalTimelineContext.eventDigest;
  targetContext.originalTimelineRange = targetContext.originalTimelineContext.rangeText;
  targetContext.originalTimelineMode = targetContext.originalTimelineContext.modeText;
  targetContext.originalTimelineAnchor = targetContext.originalTimelineContext.anchorTime;
  targetContext.originalTimelineSourceLabel = targetContext.originalTimelineContext.sourceLabel;
  targetContext.originalTimelinePlayerImpact = targetContext.originalTimelineContext.playerImpactSummary;
  targetContext.originalTimelineAudit = targetContext.originalTimelineContext.auditSeed;
  targetContext.originalTimelineEventTags = [];
  targetContext.originalTimelineTriggerSource = '';
  targetContext.originalTimelinePacket = null;
  targetContext.originalTimelinePackets = [];
  targetContext.originalTimelineLedgerSummary = '';
  targetContext.originalTimelineBasePacket = null;
  targetContext.originalTimelineBatchReplayHistory = [];
  targetContext.originalTimelineBatchReplayInstruction = '';
  return targetContext.originalTimelineContext;
}

async function ceEnsureOriginalTimelineNpcColdStart(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const opts = options || {};
  const originalCtx = await ceEnsureOriginalTimelineContext(ctx, {
    currentTime: ctx.currentTime || '',
    snapshotText: ctx.stateSnapshot || '',
    force: false
  });

  const result = {
    candidates: [],
    matched: [],
    created: [],
    unresolved: []
  };
  const applyResultToContext = (payload) => {
    const finalResult = payload || result;
    const coldStartSummary = ceBuildOriginalTimelineColdStartSummary(finalResult);
    const unresolvedSummary = ceBuildOriginalTimelineUnresolvedSummary(finalResult);
    ctx.originalTimelineColdStartResult = finalResult;
    ctx.originalTimelineColdStartSummary = coldStartSummary;
    ctx.originalTimelineUnresolvedEntities = unresolvedSummary;
    if (typeof window !== 'undefined') {
      window._ceOriginalTimelineColdStartResult = finalResult;
      window._ceOriginalTimelineColdStartSummary = coldStartSummary;
      window._ceOriginalTimelineUnresolvedQueue = Array.isArray(finalResult.unresolved)
        ? finalResult.unresolved.slice()
        : [];
    }
  };

  if (!originalCtx || !originalCtx.hasTimeline) {
    applyResultToContext(result);
    return result;
  }

  const biographyCache = ctx._biographyCache instanceof Map
    ? ctx._biographyCache
    : await buildNpcBiographyCacheForEvolution();
  ctx._biographyCache = biographyCache;

  const archiveIndex = await ceBuildOriginalTimelineNpcArchiveIndex({ sharedContext: ctx });
  ctx.originalTimelineNpcArchiveIndex = archiveIndex;
  ctx.originalTimelineCharacterCandidates = null;
  const candidates = ceExtractOriginalTimelineCharacterCandidates(ctx, {
    archiveIndex,
    biographyCache,
    includeOnscene: false,
    excludeDirectActors: false
  });
  result.candidates = candidates;

  if (!candidates.length) {
    applyResultToContext(result);
    return result;
  }

  let nextNpcNumber = (archiveIndex.maxNpcNumber || 0) + 1;
  const pendingMap = new Map();
  if (Array.isArray(window.pendingNewCharacterForConcurrentEvolution)) {
    window.pendingNewCharacterForConcurrentEvolution.forEach(item => {
      if (item && item.id) pendingMap.set(String(item.id), item);
    });
  }
  const findPendingIdByName = function() {
    const rawArgs = Array.prototype.slice.call(arguments);
    const variants = new Set();
    rawArgs.forEach(function(value) {
      ceBuildOriginalTimelineNameVariants(value).forEach(function(name) {
        if (name) variants.add(name);
      });
    });
    if (variants.size === 0) return '';
    for (const entry of pendingMap.values()) {
      const entryVariants = new Set();
      [entry && entry.name, entry && entry.canonicalName, entry && entry.sourceCandidate, entry && entry.vectorTitle].forEach(function(value) {
        ceBuildOriginalTimelineNameVariants(value).forEach(function(name) {
          if (name) entryVariants.add(name);
        });
      });
      for (const name of variants) {
        if (entryVariants.has(name)) {
          return String(entry && entry.id || '').trim();
        }
      }
    }
    return '';
  };
  const storyText = typeof ceStripImagePromptBlocksFromHtml === 'function'
    ? ceStripImagePromptBlocksFromHtml(ctx.storyText || '')
    : String(ctx.storyText || '');
  const userInput = String(ctx.userInput || '');

  for (const candidate of candidates) {
    if (opts.signal && opts.signal.aborted) break;

    const candidateSources = Array.isArray(candidate && candidate.sources) ? candidate.sources : [];
    const isDirectActorCandidate = candidateSources.some(function(source) {
      return ceIsOriginalTimelineDirectActorSource(source);
    });
    const storyHandledByCurrentTurn = typeof ceIsOriginalTimelineCandidateExplicitlyMentioned === 'function'
      ? ceIsOriginalTimelineCandidateExplicitlyMentioned(candidate, storyText, userInput)
      : false;

    const archiveMatch = ceMatchOriginalTimelineCandidateToArchive(candidate, archiveIndex);
    const strictOnsceneMatch = ceMatchOriginalTimelineCandidateToArchive(candidate, archiveIndex, {
      sceneType: 'onscene',
      allowFuzzy: false
    });
    const effectiveArchiveMatch = strictOnsceneMatch
      && archiveMatch
      && archiveMatch.record
      && String(archiveMatch.record.sceneType || '').trim() !== 'onscene'
      ? strictOnsceneMatch
      : archiveMatch;
    if (storyHandledByCurrentTurn && !isDirectActorCandidate && effectiveArchiveMatch && effectiveArchiveMatch.record && effectiveArchiveMatch.record.sceneType !== 'onscene') {
      if (!opts.silent) {
        console.log('[原著年表] 当前正文已直接承接该角色，跳过原著补演分流:', candidate.raw || candidate.normalized || '未知角色', '→', effectiveArchiveMatch.record.name || effectiveArchiveMatch.record.id);
      }
      continue;
    }
    if (effectiveArchiveMatch) {
      if (effectiveArchiveMatch.record && effectiveArchiveMatch.record.sceneType === 'onscene') {
        if (!opts.silent) {
          console.log('[原著年表] 在场人物交由普通变量演化，跳过原著人物补演:', effectiveArchiveMatch.record.name || candidate.raw, '(' + effectiveArchiveMatch.record.id + ')');
        }
        continue;
      }
      result.matched.push({
        candidate: candidate.raw,
        id: effectiveArchiveMatch.record.id,
        name: effectiveArchiveMatch.record.name,
        matchType: effectiveArchiveMatch.matchType,
        confidence: effectiveArchiveMatch.confidence
      });
      continue;
    }

    if (storyHandledByCurrentTurn && !isDirectActorCandidate) {
      if (!opts.silent) {
        console.log('[原著年表] 正文已直接出现该角色，跳过原著新NPC建档:', candidate.raw || candidate.normalized || '未知角色');
      }
      continue;
    }

    let vectorMatch = await ceSearchOriginalCharacterVectors(candidate, { biographyCache });
    if (!vectorMatch) {
      if (isDirectActorCandidate) {
        vectorMatch = {
          canonicalName: candidate.raw || candidate.normalized || '未知人物',
          content: ceBuildOriginalTimelineDirectActorFallbackVectorContent(ctx, candidate),
          source: '原著事件直列角色/' + String(candidate.raw || candidate.normalized || '未知人物').trim(),
          title: '原著事件直列角色/' + String(candidate.raw || candidate.normalized || '未知人物').trim(),
          confidence: 0.58,
          via: 'direct_actor_fallback'
        };
      } else {
        result.unresolved.push({
          candidate: candidate.raw,
          reason: 'vector_not_found',
          score: Number(candidate.score || 0),
          sources: candidateSources.slice()
        });
        continue;
      }
    }

    const canonicalVariants = ceBuildOriginalTimelineNameVariants(vectorMatch.canonicalName || candidate.raw);
    const canonicalCandidate = {
      raw: vectorMatch.canonicalName || candidate.raw,
      normalized: canonicalVariants[0] || '',
      variants: canonicalVariants
    };
    const canonicalArchiveMatch = ceMatchOriginalTimelineCandidateToArchive(canonicalCandidate, archiveIndex);
    const strictOnsceneCanonicalMatch = ceMatchOriginalTimelineCandidateToArchive(canonicalCandidate, archiveIndex, {
      sceneType: 'onscene',
      allowFuzzy: false
    });
    const effectiveCanonicalArchiveMatch = strictOnsceneCanonicalMatch
      && canonicalArchiveMatch
      && canonicalArchiveMatch.record
      && String(canonicalArchiveMatch.record.sceneType || '').trim() !== 'onscene'
      ? strictOnsceneCanonicalMatch
      : canonicalArchiveMatch;
    if (storyHandledByCurrentTurn && !isDirectActorCandidate && effectiveCanonicalArchiveMatch && effectiveCanonicalArchiveMatch.record && effectiveCanonicalArchiveMatch.record.sceneType !== 'onscene') {
      if (!opts.silent) {
        console.log('[原著年表] 当前正文已直接承接该角色，跳过原著补演匹配:', candidate.raw || candidate.normalized || '未知角色', '→', effectiveCanonicalArchiveMatch.record.name || effectiveCanonicalArchiveMatch.record.id);
      }
      continue;
    }
    if (effectiveCanonicalArchiveMatch) {
      if (effectiveCanonicalArchiveMatch.record && effectiveCanonicalArchiveMatch.record.sceneType === 'onscene') {
        if (!opts.silent) {
          console.log('[原著年表] 在场人物交由普通变量演化，跳过原著人物补演:', effectiveCanonicalArchiveMatch.record.name || candidate.raw, '(' + effectiveCanonicalArchiveMatch.record.id + ')');
        }
        continue;
      }
      result.matched.push({
        candidate: candidate.raw,
        id: effectiveCanonicalArchiveMatch.record.id,
        name: effectiveCanonicalArchiveMatch.record.name,
        matchType: effectiveCanonicalArchiveMatch.matchType,
        confidence: effectiveCanonicalArchiveMatch.confidence
      });
      continue;
    }

    const pendingMatchedId = findPendingIdByName(
      vectorMatch.canonicalName || '',
      candidate.raw || '',
      vectorMatch.title || ''
    );
    if (pendingMatchedId) {
      result.matched.push({
        candidate: candidate.raw,
        id: pendingMatchedId,
        name: vectorMatch.canonicalName || candidate.raw,
        matchType: 'pending_cold_start',
        confidence: Number(vectorMatch.confidence || 0)
      });
      continue;
    }

    const targetId = 'C' + nextNpcNumber++;
    const row = ceBuildOriginalTimelineColdStartNpcRow({
      targetId,
      candidate,
      vectorMatch,
      sharedContext: ctx
    });
    const created = await updateConcurrentEvolutionArchiveEntry(targetId, row, {
      silent: true,
      createIfNotExists: true
    });

    if (!created) {
      result.unresolved.push({
        candidate: candidate.raw,
        reason: 'archive_create_failed',
        vectorSource: vectorMatch.source || ''
      });
      continue;
    }

    const archiveAliases = new Set([
      ...ceBuildOriginalTimelineNameVariants(vectorMatch.canonicalName || candidate.raw),
      ...ceBuildOriginalTimelineNameVariants(candidate.raw || vectorMatch.canonicalName)
    ]);
    archiveIndex.records.push({
      id: targetId,
      name: vectorMatch.canonicalName || candidate.raw,
      normalizedName: ceBuildOriginalTimelineNameVariants(vectorMatch.canonicalName || candidate.raw)[0] || ceNormalizeOriginalTimelineName(vectorMatch.canonicalName || candidate.raw),
      aliases: archiveAliases,
      data: row,
      sceneType: 'offscene',
      source: 'original_timeline_cold_start'
    });

    const pendingEntry = {
      id: targetId,
      name: vectorMatch.canonicalName || candidate.raw,
      type: 'new',
      reason: '原著事件补入',
      justCreated: true,
      coldStart: true,
      coldStartConfidence: Number(vectorMatch.confidence || 0),
      vectorSource: vectorMatch.source || '',
      canonicalName: vectorMatch.canonicalName || candidate.raw,
      originalTimelineAnchor: ctx.originalTimelineAnchor || '',
      originalTimelineDigest: ctx.originalTimelineDigest || '',
      originalTimelineAudit: ctx.originalTimelineAudit || '',
      sourceCandidate: candidate.raw || '',
      vectorTitle: vectorMatch.title || '',
      vectorSnippet: ceTruncateOriginalTimelineText(
        String(vectorMatch.content || '').replace(/^###\s+[^\n]+\n?/, ''),
        600
      )
    };
    pendingMap.set(targetId, pendingEntry);

    result.created.push({
      candidate: candidate.raw,
      id: targetId,
      name: pendingEntry.name,
      confidence: pendingEntry.coldStartConfidence,
      source: pendingEntry.vectorSource
    });

    if (!opts.silent) {
      console.log('[原著年表] 新NPC冷启动成功:', pendingEntry.name, `(${targetId})`, 'via', pendingEntry.vectorSource || 'vector');
    }
  }

  const pendingEntries = Array.from(pendingMap.values());
  if (pendingEntries.length > 0) {
    window.pendingNewCharacterForConcurrentEvolution = pendingEntries;
  }
  ctx.originalTimelinePendingNewCharacters = ceGetOriginalTimelinePendingNewCharacterEntries(ctx);
  ctx.originalTimelineCharacterCandidates = null;
  ceApplyOriginalTimelineNpcRoutingState(ctx, archiveIndex, {
    errorMessage: '[原著年表] 冷启动后人物分流刷新失败:',
    resetOnError: false
  });

  applyResultToContext(result);
  return result;
}

function ceExtractOriginalTimelineAliasList(data, entryMeta = {}) {
  const aliasSet = new Set();
  const pushAlias = (value) => {
    if (value === undefined || value === null) return;
    const pieces = Array.isArray(value)
      ? value
      : (typeof value === 'string' ? value.split(/[|,，、/]/) : [value]);
    pieces.forEach(piece => {
      ceBuildOriginalTimelineNameVariants(piece).forEach(name => aliasSet.add(name));
    });
  };

  if (data && typeof data === 'object') {
    pushAlias((data['1'] || '').split('|')[0]);
  }
  pushAlias(entryMeta.title);
  pushAlias(entryMeta.name);
  pushAlias(entryMeta.displayName);

  let remarks = null;
  if (data && typeof data === 'object' && data['9']) {
    try {
      if (typeof parseRemarksString === 'function') {
        remarks = parseRemarksString(data['9'] || '');
      }
    } catch (e) {}
    if (!remarks) {
      try {
        remarks = JSON.parse(data['9']);
      } catch (e) {}
    }
  }

  if (remarks && typeof remarks === 'object') {
    pushAlias(remarks.canonical_name);
    pushAlias(remarks.aliases);
  }

  return aliasSet;
}

function ceExtractOriginalTimelineCharacterCandidates(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const rawText = ceSanitizeOriginalTimelineCandidateText(
    ctx.originalTimelineEvents || originalCtx.eventTextBlock || ''
  );

  if (!rawText.trim()) return [];

  const normalizedText = ceNormalizeOriginalTimelineName(rawText);
  const directActorNames = ceCollectOriginalTimelineDirectActorNames(rawText);
  const candidateMap = new Map();
  const addCandidate = (raw, source, weight = 1) => {
    const variants = ceBuildOriginalTimelineNameVariants(raw).sort((a, b) => b.length - a.length);
    if (!variants.length) return;
    const primary = variants[0];
    const existing = candidateMap.get(primary) || {
      raw: ceNormalizeOriginalTimelineName(raw),
      normalized: primary,
      variants: [],
      score: 0,
      sources: new Set()
    };
    if (raw && String(raw).length > String(existing.raw || '').length) {
      existing.raw = ceNormalizeOriginalTimelineName(raw);
    }
    existing.variants = Array.from(new Set([...(existing.variants || []), ...variants]));
    existing.score += weight;
    existing.sources.add(source);
    candidateMap.set(primary, existing);
  };

  ceExtractOriginalTimelineStructuredCandidates(rawText).forEach(item => {
    addCandidate(item.raw || item.normalized, item.source || 'timeline_structured', item.weight || 0);
  });

  const archiveRecords = Array.isArray(options.archiveIndex && options.archiveIndex.records)
    ? options.archiveIndex.records
    : [];
  const includeOnscene = options.includeOnscene === true;
  archiveRecords.forEach(record => {
    const names = new Set([record.normalizedName]);
    if (record.aliases instanceof Set) {
      record.aliases.forEach(name => names.add(name));
    }
    names.forEach(name => {
      if (name && normalizedText.includes(name)) {
        addCandidate(record.name || name, 'archive_scan', 2.4);
      }
    });
  });

  if (options.biographyCache instanceof Map) {
    Array.from(options.biographyCache.keys()).forEach(name => {
      const variants = ceBuildOriginalTimelineNameVariants(name);
      if (variants.some(variant => normalizedText.includes(variant))) {
        addCandidate(name, 'vector_cache_scan', 1.8);
      }
    });
  }

  const sortedCandidates = Array.from(candidateMap.values())
    .filter(item => item && item.normalized && item.score > 0)
    .sort((a, b) => (b.score - a.score) || (b.normalized.length - a.normalized.length))
    .map(item => ({
      raw: item.raw || item.normalized,
      normalized: item.normalized,
      variants: item.variants,
      score: Number(item.score || 0),
      sources: Array.from(item.sources || [])
    }));
  let extractedCandidates = sortedCandidates.slice(0, 24);
  if (directActorNames instanceof Set && directActorNames.size > 0) {
    const existingKeys = new Set(extractedCandidates.map(function(candidate) {
      return String(candidate && candidate.normalized || '').trim();
    }).filter(Boolean));
    sortedCandidates.forEach(function(candidate) {
      if (!candidate || !candidate.normalized || existingKeys.has(candidate.normalized)) return;
      if (ceDoesOriginalTimelineCandidateMatchDirectActorNames(candidate, directActorNames)) {
        extractedCandidates.push(candidate);
        existingKeys.add(candidate.normalized);
      }
    });
  }

  if (options.excludeDirectActors === true) {
    extractedCandidates = extractedCandidates.filter(candidate => !ceShouldExcludeOriginalTimelineDirectActorCandidate(candidate, {
      excludeDirectActors: true,
      directActorNames,
      rawText
    }));
  }

  if (includeOnscene || !archiveRecords.length) {
    return extractedCandidates;
  }
  const effectiveArchiveIndex = options.archiveIndex && Array.isArray(options.archiveIndex.records)
    ? options.archiveIndex
    : { records: archiveRecords };
  return extractedCandidates.filter(candidate => {
    const archiveMatch = ceMatchOriginalTimelineCandidateToArchive(candidate, effectiveArchiveIndex);
    return !(archiveMatch && archiveMatch.record && archiveMatch.record.sceneType === 'onscene');
  });
}

function ceExtractOriginalTimelineReferenceCandidates(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const originalCtx = ctx.originalTimelineContext || {};
  const rawText = ceSanitizeOriginalTimelineCandidateText(
    ctx.originalTimelineEvents || originalCtx.eventTextBlock || ''
  );

  const emptyResult = {
    rawText,
    all: [],
    byType: ceBuildEmptyOriginalReferenceBuckets()
  };
  if (!rawText.trim()) return emptyResult;

  const normalizedText = ceNormalizeOriginalReferenceName(rawText);
  const candidateMap = new Map();
  const addCandidate = (raw, typeHints, source, weight = 1, extra = {}) => {
    const normalized = ceNormalizeOriginalReferenceName(raw);
    let types = ceNormalizeOriginalReferenceTypes(typeHints);
    if (!types.length) {
      types = ceInferOriginalReferenceTypesFromName(normalized);
    }
    if (ceIsOriginalReferenceLikelyNoise(normalized, types)) return;

    const existing = candidateMap.get(normalized) || {
      raw: String(raw || '').trim() || normalized,
      normalized,
      score: 0,
      typeScores: ceBuildEmptyOriginalReferenceTypeScores(),
      types: new Set(),
      sources: new Set(),
      categoryTokens: new Set(),
      matchedTitles: new Set()
    };

    if (String(raw || '').trim().length > String(existing.raw || '').length) {
      existing.raw = String(raw || '').trim() || normalized;
    }
    existing.score += Number(weight || 0);
    types.forEach(type => {
      existing.types.add(type);
      ceAddOriginalReferenceTypeScore(existing.typeScores, type, weight);
    });
    existing.sources.add(source || 'reference_scan');
    (Array.isArray(extra.categoryTokens) ? extra.categoryTokens : []).forEach(token => {
      if (token) existing.categoryTokens.add(String(token).trim());
    });
    (Array.isArray(extra.matchedTitles) ? extra.matchedTitles : []).forEach(title => {
      if (title) existing.matchedTitles.add(String(title).trim());
    });
    candidateMap.set(normalized, existing);
  };

  ceExtractOriginalTimelineStructuredReferenceCandidates(rawText).forEach(item => {
    addCandidate(item.raw || item.normalized, item.types || [], item.source || 'timeline_reference_marker', item.weight || 0);
  });

  const referenceEntries = Array.isArray(options.referenceEntries)
    ? options.referenceEntries
    : (Array.isArray(options.referenceIndex) ? options.referenceIndex : []);
  referenceEntries.forEach(entry => {
    if (!entry || typeof entry !== 'object') return;
    const entryTitle = entry.title || entry.name || entry.canonicalName || entry.displayName || '';
    const variantSource = Array.isArray(entry.variants) && entry.variants.length
      ? entry.variants
      : [entryTitle, entry.aliases, entry.normalizedTitle];
    const entryVariants = Array.from(new Set(
      variantSource
        .flatMap(item => Array.isArray(item) ? item : [item])
        .map(item => ceNormalizeOriginalReferenceName(item))
        .filter(Boolean)
    ));
    if (!entryVariants.length) return;
    const matchedVariant = entryVariants.find(variant => normalizedText.includes(variant));
    if (!matchedVariant) return;

    const parsedCategory = ceParseOriginalReferenceCategory(entry.content || entry.text || '', entry.source || '', entryTitle);
    const entryTypes = ceNormalizeOriginalReferenceTypes(entry.types || entry.mappedTypes || parsedCategory.types || []);
    addCandidate(entryTitle || matchedVariant, entryTypes, entry.source || 'reference_index_scan', 3.8, {
      categoryTokens: parsedCategory.categoryTokens || [],
      matchedTitles: entryTitle ? [entryTitle] : []
    });
  });


  const totalLimit = Math.max(1, Number(options.limit || 32));
  const perTypeLimit = Math.max(1, Number(options.limitPerType || 12));
  const all = Array.from(candidateMap.values())
    .map(item => {
      const types = CE_ORIGINAL_REFERENCE_TYPE_ORDER.filter(type => (
        item.types instanceof Set ? item.types.has(type) : Number(item.typeScores?.[type] || 0) > 0
      ));
      return {
        raw: item.raw || item.normalized,
        normalized: item.normalized,
        types,
        primaryType: ceResolveOriginalReferencePrimaryType(item.typeScores),
        score: Number(item.score || 0),
        typeScores: item.typeScores || ceBuildEmptyOriginalReferenceTypeScores(),
        sources: Array.from(item.sources || []),
        categoryTokens: Array.from(item.categoryTokens || []),
        matchedTitles: Array.from(item.matchedTitles || [])
      };
    })
    .filter(item => item && item.normalized && item.types.length > 0)
    .sort((a, b) => (b.score - a.score) || (b.normalized.length - a.normalized.length))
    .slice(0, totalLimit);

  const byType = ceBuildEmptyOriginalReferenceBuckets();
  all.forEach(item => {
    item.types.forEach(type => {
      if (!byType[type]) return;
      byType[type].push(Object.assign({}, item, {
        totalScore: item.score,
        score: Number(item.typeScores?.[type] || item.score || 0)
      }));
    });
  });
  Object.keys(byType).forEach(type => {
    byType[type] = byType[type]
      .sort((a, b) => (b.score - a.score) || (b.totalScore - a.totalScore) || (b.normalized.length - a.normalized.length))
      .slice(0, perTypeLimit);
  });

  return {
    rawText,
    all,
    byType,
    vectorEnriched: referenceEntries.length > 0
  };
}

function ceIsOriginalTimelineBoilerplateLine(line) {
  const text = String(line || '').trim();
  if (!text) return true;
  if (/^(世界年表参考注入时间锚点|时间锚点来源|注入模式|简略版范围|原著版范围|命中上限\(简略版\)|命中上限\(原著版\)|纳入范围\(简略版\)|纳入范围\(原著版\)|纳入条目\(简略版\)|纳入条目\(原著版\)|命中范围|命中条目)\s*[:：]/.test(text)) {
    return true;
  }
  if (/^(?:你正在为玩家所在的平行时空生成剧情|下方年表内容是|以下年表内容是|原著联动说明|以下内容仅作原著参考|以下为原著参考年表|请严格依据以下年表|当前事件唯一依据)/.test(text)) {
    return true;
  }
  return false;
}

function ceIsOriginalTimelineBoilerplateBlock(blockText) {
  const text = String(blockText || '').trim();
  if (!text) return true;
  const normalizedLines = text
    .split(/\r?\n/)
    .map(function(line) { return String(line || '').trim(); })
    .filter(Boolean);
  if (normalizedLines.length === 0) return true;
  const joined = normalizedLines.join('\n');
  const hasEventSignals = /\[(?:OTE|E)-[A-Z0-9]+\]|【E-\d+】|(?:^|\n)\s*(?:时间|事件摘要|结构化摘要|关键人物|触发条件|预期结果|后续状态|变异关注点|来源备注)\s*[:：]/.test(joined);
  if (hasEventSignals) return false;
  return normalizedLines.every(function(line) {
    return ceIsOriginalTimelineBoilerplateLine(line);
  }) || /你正在为玩家所在的平行时空生成剧情/.test(joined)
    || /下方年表内容是.+原著主世界时间线参考/.test(joined);
}

function ceExtractOriginalTimelineSection(rawBlock) {
  const text = typeof rawBlock === 'string' ? rawBlock.trim() : '';
  if (!text) return '';
  const startMark = '### 【世界年表参考】';
  const endMark = '<<<世界年表参考结束>>>';
  const startIdx = text.indexOf(startMark);
  const sliced = (startIdx >= 0 ? text.substring(startIdx + startMark.length) : text).trim();
  const endIdx = sliced.indexOf(endMark);
  const bodyText = endIdx >= 0 ? sliced.substring(0, endIdx).trim() : sliced;
  return bodyText
    .split(/\r?\n/)
    .map(line => String(line || '').trim())
    .filter(Boolean)
    .filter(line => !/^(?:###\s*【世界年表参考】|<<<世界年表参考结束>>>)/.test(line))
    .filter(line => !ceIsOriginalTimelineBoilerplateLine(line))
    .join('\n')
    .trim();
}

function ceSanitizeOriginalTimelineCandidateText(rawText) {
  return String(rawText || '')
    .split(/\r?\n/)
    .map(line => {
      const text = String(line || '').trim();
      const titlePeopleMatch = text.match(/\[(?:人物[:：])([^\]\r\n]+)\]/);
      if (titlePeopleMatch && titlePeopleMatch[0]) {
        return titlePeopleMatch[0];
      }
      return text
        .replace(/^\s*-\s*时间\s*[:：]\s*/, '')
        .replace(/^\s*标题\s*[:：]\s*/, '')
        .replace(/^\s*简略版\s*[:：]\s*/, '')
        .replace(/^\s*事件(?:\d+)?\s*[:：]\s*/, '')
        .trim();
    })
    .filter(Boolean)
    .join('\n')
    .trim();
}

function ceIsOriginalTimelineDirectActorSource(source) {
  const normalized = String(source || '').trim();
  return normalized === 'timeline_title_people'
    || normalized === 'timeline_content_people'
    || normalized === 'timeline_structured_people';
}

function ceDoesOriginalTimelineCandidateMatchDirectActorNames(candidate, directActorNames) {
  const nameSet = directActorNames instanceof Set ? directActorNames : new Set();
  if (nameSet.size === 0) return false;
  const variants = Array.isArray(candidate && candidate.variants) && candidate.variants.length > 0
    ? candidate.variants
    : ceBuildOriginalTimelineNameVariants(candidate && (candidate.raw || candidate.normalized || '') || '');
  return variants.some(function(name) {
    return nameSet.has(name);
  });
}

function ceCollectOriginalTimelineDirectActorNames(rawText) {
  const names = new Set();
  ceExtractOriginalTimelineStructuredCandidates(rawText).forEach(item => {
    const source = String(item && item.source || '');
    if (!ceIsOriginalTimelineDirectActorSource(source)) return;
    ceBuildOriginalTimelineNameVariants(item && (item.raw || item.normalized) || '').forEach(name => names.add(name));
  });
  return names;
}

function ceShouldExcludeOriginalTimelineDirectActorCandidate(candidate, options = {}) {
  if (!options || options.excludeDirectActors !== true) return false;
  const sources = Array.isArray(candidate && candidate.sources) ? candidate.sources : [];
  if (sources.some(function(source) { return ceIsOriginalTimelineDirectActorSource(source); })) {
    return true;
  }
  const directActorNames = options.directActorNames instanceof Set
    ? options.directActorNames
    : ceCollectOriginalTimelineDirectActorNames(options.rawText || '');
  return ceDoesOriginalTimelineCandidateMatchDirectActorNames(candidate, directActorNames);
}

function ceExtractOriginalTimelineStructuredCandidates(rawText) {
  const text = String(rawText || '');
  if (!text.trim()) return [];

  const results = [];
  const seen = new Set();
  const pushChunk = (chunk, source, weight) => {
    String(chunk || '')
      .split(/[|,，、/]/)
      .map(item => typeof ceStripHtmlTagsLite === 'function' ? ceStripHtmlTagsLite(item) : item)
      .forEach(item => {
        const normalized = ceNormalizeOriginalTimelineName(item);
        if (!normalized) return;
        if (ceIsOriginalTimelineLikelyNonPersonName(normalized)) return;
        const key = source + '|' + normalized;
        if (seen.has(key)) return;
        seen.add(key);
        results.push({
          raw: String(item || '').trim() || normalized,
          normalized,
          source,
          weight: Number(weight || 0)
        });
      });
  };

  let match;
  const titlePersonRegex = /\[(?:人物[:：])([^\]\r\n]+)\]/g;
  while ((match = titlePersonRegex.exec(text))) {
    pushChunk(match[1], 'timeline_title_people', 4.8);
  }

  const titleBareRegex = /\[([^\]\r\n]{1,80})\]/g;
  while ((match = titleBareRegex.exec(text))) {
    if (/^\s*人物[:：]/.test(match[1])) continue;
    pushChunk(match[1], 'timeline_title_bracket', 4.2);
  }

  const contentPersonRegex = /【人物】[:：]\s*([^\n\r]+)/g;
  while ((match = contentPersonRegex.exec(text))) {
    pushChunk(match[1], 'timeline_content_people', 4.4);
  }

  const structuredPersonFieldRegex = /(?:^|\n)\s*(?:关键人物|参与者|登场人物|涉及人物|相关人物)\s*[:：]\s*([^\n\r]+)/g;
  while ((match = structuredPersonFieldRegex.exec(text))) {
    pushChunk(match[1], 'timeline_structured_people', 4.6);
  }

  return results;
}

function ceExtractOriginalTimelineStructuredReferenceCandidates(rawText) {
  const text = String(rawText || '');
  if (!text.trim()) return [];

  const results = [];
  const seen = new Set();
  const markerKeys = Object.keys(CE_ORIGINAL_REFERENCE_MARKER_TYPE_MAP);
  if (!markerKeys.length) return results;

  const escapedMarkerKeys = markerKeys
    .slice()
    .sort((a, b) => b.length - a.length)
    .map(key => key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
    .join('|');

  const pushChunk = (chunk, marker, source, weight) => {
    const markerTypes = ceNormalizeOriginalReferenceTypes(CE_ORIGINAL_REFERENCE_MARKER_TYPE_MAP[marker] || []);
    String(chunk || '')
      .split(/[|,，、/；;]/)
      .map(item => typeof ceStripHtmlTagsLite === 'function' ? ceStripHtmlTagsLite(item) : item)
      .forEach(item => {
        const normalized = ceNormalizeOriginalReferenceName(item);
        if (ceIsOriginalReferenceLikelyNoise(normalized, markerTypes)) return;
        const key = marker + '|' + normalized;
        if (seen.has(key)) return;
        seen.add(key);
        results.push({
          raw: String(item || '').trim() || normalized,
          normalized,
          types: markerTypes,
          primaryType: markerTypes[0] || '',
          source,
          weight: Number(weight || 0)
        });
      });
  };

  let match;
  const blockRegex = new RegExp(`【(${escapedMarkerKeys})】[:：]?\\s*([^\\n\\r]+)`, 'g');
  while ((match = blockRegex.exec(text))) {
    pushChunk(match[2], match[1], 'timeline_reference_marker', 4.6);
  }

  const bracketRegex = new RegExp(`\\[(${escapedMarkerKeys})[:：]([^\\]\\r\\n]+)\\]`, 'g');
  while ((match = bracketRegex.exec(text))) {
    pushChunk(match[2], match[1], 'timeline_reference_bracket', 4.2);
  }

  return results;
}

function ceFormatOriginalReferenceCandidateList(candidates, options = {}) {
  const rows = Array.isArray(candidates) ? candidates : [];
  if (!rows.length) return '';
  const limit = Math.max(1, Number(options.limit || 8));
  return rows.slice(0, limit).map(item => {
    const name = item && (item.raw || item.normalized) ? (item.raw || item.normalized) : '未知实体';
    const categoryTokens = Array.isArray(item && item.categoryTokens)
      ? item.categoryTokens.filter(Boolean).slice(0, 3)
      : [];
    return categoryTokens.length
      ? `- ${name}（${categoryTokens.join('/')}）`
      : `- ${name}`;
  }).join('\n');
}

function ceFormatOriginalReferenceTypeLabel(type) {
  const labelMap = {
    item: '法宝/丹药/材料',
    technique: '功法/秘术/神通',
    faction: '势力/宗门/组织',
    location: '地点/秘境/区域',
    beast: '灵兽/妖兽/真灵',
    character: '人物'
  };
  return labelMap[type] || type || '参考条目';
}

function ceFormatOriginalReferenceVectorMatches(matches, options = {}) {
  const rows = Array.isArray(matches) ? matches : [];
  if (!rows.length) return '';
  const limit = Math.max(1, Number(options.limit || 4));
  const snippetLength = Number(options.snippetLength || 0);
  const useFullText = options.fullText === true || snippetLength <= 0;
  return rows.slice(0, limit).map(item => {
    const title = item && (item.title || item.canonicalName || item.candidate) ? (item.title || item.canonicalName || item.candidate) : '未命名条目';
    const rawContent = item ? (item.content || item.textBlock || '') : '';
    const fullText = String(rawContent).replace(/^###\s+[^\n]+\n?/, '').trim();
    const bodyText = useFullText
      ? fullText
      : ceTruncateOriginalTimelineText(fullText, snippetLength || 220);
    const meta = [
      '类别: ' + ceFormatOriginalReferenceTypeLabel(item && (item.primaryType || item.entityType) || ''),
      item && item.scope ? ('作用域: ' + item.scope) : '',
      item && item.source ? ('来源: ' + item.source) : '',
      item && item.candidate ? ('命中实体: ' + item.candidate) : '',
      typeof (item && item.confidence) === 'number' ? ('置信度: ' + Number(item.confidence).toFixed(2)) : '',
      item && item.via ? ('匹配方式: ' + item.via) : ''
    ].filter(Boolean).join(' | ');
    return [
      '### ' + title,
      meta,
      bodyText ? ((useFullText ? '全文' : '摘要') + ':\n' + bodyText) : ''
    ].filter(Boolean).join('\n');
  }).join('\n\n');
}

function ceFormatOriginalTimelineCharacterCandidateList(candidates, options = {}) {
  const rows = Array.isArray(candidates) ? candidates : [];
  if (!rows.length) return '';
  const limit = Math.max(1, Number(options.limit || 8));
  return rows.slice(0, limit).map(item => {
    const name = item && (item.raw || item.normalized) ? (item.raw || item.normalized) : '未知人物';
    return '- ' + name;
  }).join('\n');
}

function ceFormatOriginalTimelineColdStartReason(reason) {
  if (reason === 'vector_not_found') return '向量未命中';
  if (reason === 'archive_create_failed') return '建档失败';
  return reason || '暂未匹配';
}

function ceGetOriginalReferenceCandidatesFromContext(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  const cached = ctx.originalTimelineReferenceCandidates;
  const wantsVectorEnriched = (
    Array.isArray(options.referenceEntries) && options.referenceEntries.length > 0
  ) || (
    Array.isArray(options.referenceIndex) && options.referenceIndex.length > 0
  );
  if (!options.force && cached && typeof cached === 'object') {
    if (!wantsVectorEnriched || cached.vectorEnriched) {
      return cached;
    }
  }
  const parsed = ceExtractOriginalTimelineReferenceCandidates(ctx, options);
  ctx.originalTimelineReferenceCandidates = parsed;
  return parsed;
}

function ceGetOriginalReferenceScopePriority(scope) {
  if (scope === 'archive') return 2;
  if (scope === 'global') return 1;
  return 0;
}

function ceGetOriginalTimelineCharacterCandidatesFromContext(sharedContext, options = {}) {
  const ctx = sharedContext || {};
  if (!options.force && Array.isArray(ctx.originalTimelineCharacterCandidates)) {
    return ctx.originalTimelineCharacterCandidates;
  }
  const candidates = ceExtractOriginalTimelineCharacterCandidates(ctx, {
    biographyCache: options.biographyCache || ctx._biographyCache,
    archiveIndex: options.archiveIndex || ctx.originalTimelineNpcArchiveIndex || null,
    includeOnscene: options.includeOnscene === true
  });
  ctx.originalTimelineCharacterCandidates = candidates;
  return candidates;
}

function ceInferOriginalReferenceScope(vector, sourceText) {
  const item = vector || {};
  const directScope = ceNormalizeOriginalReferenceScope(
    item.scope
    || (item.meta && item.meta.scope)
    || (item.metadata && item.metadata.scope)
  );
  if (directScope) return directScope;

  const source = String(sourceText || item.source || '').trim();
  if (!source) return '';
  if (typeof currentArchiveName !== 'undefined' && currentArchiveName && source.indexOf(String(currentArchiveName)) >= 0) {
    return 'archive';
  }
  if (/存档|自定义|补充设定|worldbook|world_book/i.test(source)) {
    return 'archive';
  }
  if (/设定集|百科|全局|global/i.test(source)) {
    return 'global';
  }
  return '';
}

function ceInferOriginalReferenceTypesFromName(name) {
  const normalized = ceNormalizeOriginalReferenceName(name);
  if (!normalized) return [];
  const typeScores = ceBuildEmptyOriginalReferenceTypeScores();
  Object.entries(CE_ORIGINAL_REFERENCE_SUFFIX_HINTS).forEach(([type, suffixes]) => {
    if (!Array.isArray(suffixes)) return;
    if (suffixes.some(suffix => normalized.endsWith(suffix) && normalized.length > String(suffix || '').length)) {
      ceAddOriginalReferenceTypeScore(typeScores, type, 1.4);
    }
  });
  Object.entries(CE_ORIGINAL_REFERENCE_TOKEN_TYPE_MAP).forEach(([token, mappedTypes]) => {
    if (!token || !normalized.includes(token)) return;
    ceNormalizeOriginalReferenceTypes(mappedTypes).forEach(type => {
      ceAddOriginalReferenceTypeScore(typeScores, type, 0.8);
    });
  });
  return CE_ORIGINAL_REFERENCE_TYPE_ORDER.filter(type => Number(typeScores[type] || 0) > 0);
}

function ceIsOriginalReferenceLikelyNoise(name, typeHints) {
  const normalized = ceNormalizeOriginalReferenceName(name);
  if (!normalized) return true;
  if (normalized.length < 2 || normalized.length > 24) return true;
  if (/^\d+$/.test(normalized)) return true;
  if (CE_ORIGINAL_REFERENCE_STOPWORDS.has(normalized)) return true;
  if (/你正在为玩家|所在的平行时|下方年表内容|当前时间点/.test(normalized)) return true;
  const normalizedTypes = ceNormalizeOriginalReferenceTypes(typeHints);
  if (!normalizedTypes.length) {
    const inferred = ceInferOriginalReferenceTypesFromName(normalized);
    if (!inferred.length) return true;
  }
  return false;
}

function ceIsOriginalTimelineLikelyNonPersonName(name) {
  const normalized = ceNormalizeOriginalTimelineName(name);
  if (!normalized) return true;
  if (normalized.length < 2 || normalized.length > 8) return true;
  if (CE_ORIGINAL_TIMELINE_NAME_STOPWORDS.has(normalized)) return true;
  if (/^\d+$/.test(normalized)) return true;
  if (/你正在为玩家|所在的平行时|下方年表内容|当前时间点/.test(normalized)) return true;
  if (CE_ORIGINAL_TIMELINE_TITLE_SUFFIXES.includes(normalized)) return true;
  if (CE_ORIGINAL_TIMELINE_GROUP_SUFFIXES.some(suffix => normalized.endsWith(suffix))) return true;
  return CE_ORIGINAL_TIMELINE_LOCATION_SUFFIXES.some(suffix => (
    normalized.endsWith(suffix) && normalized.length >= suffix.length + 1
  ));
}

function ceMapOriginalReferenceTokensToTypes(tokens) {
  const typeScores = ceBuildEmptyOriginalReferenceTypeScores();
  const normalizedTokens = [];
  const seen = new Set();
  (Array.isArray(tokens) ? tokens : []).forEach(token => {
    const normalizedToken = String(token || '').trim();
    if (!normalizedToken || seen.has(normalizedToken)) return;
    seen.add(normalizedToken);
    normalizedTokens.push(normalizedToken);
    Object.entries(CE_ORIGINAL_REFERENCE_TOKEN_TYPE_MAP).forEach(([marker, mappedTypes]) => {
      if (!(normalizedToken === marker || normalizedToken.includes(marker) || marker.includes(normalizedToken))) return;
      const delta = normalizedToken === marker ? 2.8 : 1.6;
      ceNormalizeOriginalReferenceTypes(mappedTypes).forEach(type => {
        ceAddOriginalReferenceTypeScore(typeScores, type, delta);
      });
    });
  });
  const types = CE_ORIGINAL_REFERENCE_TYPE_ORDER.filter(type => Number(typeScores[type] || 0) > 0);
  return {
    categoryTokens: normalizedTokens,
    typeScores,
    types,
    primaryType: ceResolveOriginalReferencePrimaryType(typeScores)
  };
}

function ceMatchOriginalTimelineCandidateToArchive(candidate, archiveIndex, options = {}) {
  const normalized = candidate && candidate.normalized
    ? candidate.normalized
    : (ceBuildOriginalTimelineNameVariants(candidate && (candidate.raw || candidate.name || candidate))[0] || '');
  if (!normalized) return null;

  const opts = options || {};
  const sceneTypeFilter = String(opts.sceneType || '').trim();
  const allowFuzzy = opts.allowFuzzy !== false;
  let records = archiveIndex && Array.isArray(archiveIndex.records) ? archiveIndex.records : [];
  if (sceneTypeFilter) {
    records = records.filter(record => String(record && record.sceneType || '').trim() === sceneTypeFilter);
  }
  if (records.length === 0) return null;

  const exactMatches = records.filter(record => record.normalizedName === normalized);
  if (exactMatches.length === 1) {
    return {
      matchType: 'archive_exact',
      confidence: 1,
      record: exactMatches[0],
      matchedName: normalized
    };
  }
  if (exactMatches.length > 1) return null;

  const aliasExactMatches = records.filter(record => record.aliases instanceof Set && record.aliases.has(normalized));
  if (aliasExactMatches.length === 1) {
    return {
      matchType: 'archive_alias',
      confidence: 0.96,
      record: aliasExactMatches[0],
      matchedName: normalized
    };
  }
  if (aliasExactMatches.length > 1) return null;
  if (!allowFuzzy) return null;

  const fuzzyMatches = [];
  records.forEach(record => {
    let bestScore = 0;
    let matchedName = '';
    const names = new Set([record.normalizedName]);
    if (record.aliases instanceof Set) {
      record.aliases.forEach(name => names.add(name));
    }
    names.forEach(name => {
      if (!name || name === normalized) return;
      if (name.includes(normalized) || normalized.includes(name)) {
        const shorterLen = Math.min(name.length, normalized.length);
        const longerLen = Math.max(name.length, normalized.length);
        const lengthGap = longerLen - shorterLen;
        if (shorterLen < 3 || lengthGap > 1) return;
        const score = name.length === normalized.length ? 0.9 : 0.84;
        if (score > bestScore) {
          bestScore = score;
          matchedName = name;
        }
      }
    });
    if (bestScore > 0) {
      fuzzyMatches.push({
        matchType: 'archive_fuzzy',
        confidence: bestScore,
        record,
        matchedName
      });
    }
  });

  fuzzyMatches.sort((a, b) => b.confidence - a.confidence || String(b.matchedName || '').length - String(a.matchedName || '').length);
  if (fuzzyMatches.length > 0 && (!fuzzyMatches[1] || (fuzzyMatches[0].confidence - fuzzyMatches[1].confidence) >= 0.08)) {
    return fuzzyMatches[0];
  }
  return null;
}

function ceNormalizeOriginalReferenceName(raw) {
  return ceNormalizeOriginalTimelineName(raw);
}

function ceNormalizeOriginalReferenceScope(raw) {
  const normalized = String(raw || '').trim().toLowerCase();
  return normalized === 'archive' || normalized === 'global' ? normalized : '';
}

function ceNormalizeOriginalReferenceSearchNames(names, defaultTypeHints = []) {
  const queue = Array.isArray(names) ? names.slice() : [names];
  const defaultTypes = ceNormalizeOriginalReferenceTypes(defaultTypeHints);
  const byKey = new Map();

  queue.forEach(item => {
    if (item === undefined || item === null) return;

    let raw = '';
    let variants = [];
    let typeHints = defaultTypes.slice();
    let categoryTokens = [];
    let matchedTitles = [];
    let sources = [];
    let baseScore = 0;

    if (typeof item === 'string') {
      raw = item;
    } else if (typeof item === 'object') {
      raw = item.raw || item.name || item.normalized || '';
      variants = Array.isArray(item.variants) ? item.variants.slice() : [];
      typeHints = ceNormalizeOriginalReferenceTypes([
        ...defaultTypes,
        ...(Array.isArray(item.types) ? item.types : [item.type, item.primaryType])
      ]);
      categoryTokens = Array.isArray(item.categoryTokens) ? item.categoryTokens.slice() : [];
      matchedTitles = Array.isArray(item.matchedTitles) ? item.matchedTitles.slice() : [];
      sources = Array.isArray(item.sources) ? item.sources.slice() : [];
      baseScore = Number(item.score || item.weight || 0);
    }

    const normalized = ceNormalizeOriginalReferenceName(raw);
    const normalizedCategoryTokens = categoryTokens.map(token => ceNormalizeOriginalReferenceName(token)).filter(Boolean);
    const normalizedMatchedTitles = matchedTitles.map(title => ceNormalizeOriginalReferenceName(title)).filter(Boolean);
    const normalizedSources = sources.map(source => String(source || '').trim()).filter(Boolean);
    const normalizedVariants = Array.from(new Set([
      normalized,
      ...variants.map(variant => ceNormalizeOriginalReferenceName(variant)).filter(Boolean),
      ...normalizedMatchedTitles
    ].filter(Boolean)));
    const effectiveTypes = typeHints.length ? typeHints : ceInferOriginalReferenceTypesFromName(normalized);

    if (ceIsOriginalReferenceLikelyNoise(normalized, effectiveTypes.length ? effectiveTypes : defaultTypes)) return;

    const existing = byKey.get(normalized) || {
      raw: String(raw || '').trim() || normalized,
      normalized,
      variants: new Set(),
      typeHints: new Set(),
      categoryTokens: new Set(),
      matchedTitles: new Set(),
      sources: new Set(),
      score: 0
    };

    if (String(raw || '').trim().length > String(existing.raw || '').length) {
      existing.raw = String(raw || '').trim() || normalized;
    }
    normalizedVariants.forEach(variant => existing.variants.add(variant));
    effectiveTypes.forEach(type => existing.typeHints.add(type));
    normalizedCategoryTokens.forEach(token => existing.categoryTokens.add(token));
    normalizedMatchedTitles.forEach(title => existing.matchedTitles.add(title));
    normalizedSources.forEach(source => existing.sources.add(source));
    existing.score = Math.max(Number(existing.score || 0), baseScore);
    byKey.set(normalized, existing);
  });

  return Array.from(byKey.values()).map(item => {
    const normalizedItem = {
      raw: item.raw || item.normalized,
      normalized: item.normalized,
      variants: Array.from(item.variants || []),
      typeHints: Array.from(item.typeHints || []),
      categoryTokens: Array.from(item.categoryTokens || []),
      matchedTitles: Array.from(item.matchedTitles || []),
      sources: Array.from(item.sources || []),
      score: Number(item.score || 0)
    };
    normalizedItem.semanticTokens = ceBuildOriginalReferenceSemanticTokens([
      normalizedItem.raw,
      normalizedItem.normalized,
      normalizedItem.variants,
      normalizedItem.categoryTokens,
      normalizedItem.matchedTitles
    ], { maxTokens: 32 });
    return normalizedItem;
  });
}

function ceNormalizeOriginalReferenceTypes(typeOrTypes) {
  const input = Array.isArray(typeOrTypes) ? typeOrTypes : [typeOrTypes];
  const seen = new Set();
  input.forEach(item => {
    const normalized = String(item || '').trim().toLowerCase();
    if (!normalized) return;
    if (!CE_ORIGINAL_REFERENCE_TYPE_ORDER.includes(normalized)) return;
    seen.add(normalized);
  });
  return Array.from(seen);
}

function ceNormalizeOriginalTimelineName(raw) {
  if (!raw) return '';
  let text = typeof ceStripHtmlTagsLite === 'function'
    ? ceStripHtmlTagsLite(raw)
    : String(raw).replace(/<[^>]*>/g, '');
  text = String(text || '')
    .replace(/[“”"『』「」《》〈〉【】\[\]（）()]/g, '')
    .replace(/[\s·•・:：、，。；,;!！?？]/g, '')
    .trim();
  return text;
}

function ceParseOriginalReferenceCategory(content, source, title) {
  const text = String(content || '');
  const sourceText = String(source || '');
  const titleText = String(title || '');
  const categoryTokens = [];
  const seen = new Set();
  const pushTokenChunk = (chunk) => {
    String(chunk || '')
      .split(/[\/|、，,；;]+/)
      .map(item => String(item || '').replace(/[：:]/g, '').trim())
      .forEach(item => {
        if (!item || seen.has(item)) return;
        seen.add(item);
        categoryTokens.push(item);
      });
  };

  let rawCategoryText = '';
  const match = text.match(/【原著设定】[:：]\s*([^。；，,\n\r]+)/);
  if (match && match[1]) {
    rawCategoryText = String(match[1] || '').trim();
    pushTokenChunk(rawCategoryText);
  }

  const mapped = ceMapOriginalReferenceTokensToTypes(categoryTokens);
  const typeScores = Object.assign(ceBuildEmptyOriginalReferenceTypeScores(), mapped.typeScores || {});
  ceInferOriginalReferenceTypesFromName(titleText).forEach(type => {
    ceAddOriginalReferenceTypeScore(typeScores, type, 0.9);
  });
  ceInferOriginalReferenceTypesFromName(sourceText).forEach(type => {
    ceAddOriginalReferenceTypeScore(typeScores, type, 0.3);
  });

  const types = CE_ORIGINAL_REFERENCE_TYPE_ORDER.filter(type => Number(typeScores[type] || 0) > 0);
  return {
    rawCategoryText,
    categoryTokens,
    typeScores,
    types,
    primaryType: ceResolveOriginalReferencePrimaryType(typeScores)
  };
}

function ceNormalizeOriginalTimelineAsciiText(rawText) {
  return String(rawText || '')
    .replace(/[０-９]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 65248))
    .replace(/：/g, ':')
    .replace(/\s+/g, ' ')
    .trim();
}

function ceExtractOriginalTimelineComparableMonth(rawText) {
  const asciiText = ceNormalizeOriginalTimelineAsciiText(rawText);
  const match = asciiText.match(/(\d{4})\s*(?:年|[.\/-])\s*(\d{1,2})/);
  if (!match) return '';
  const year = String(match[1] || '').padStart(4, '0');
  const month = String(match[2] || '').padStart(2, '0');
  return year + '.' + month;
}

function ceInferOriginalTimelineRelativeDay(asciiText) {
  const text = String(asciiText || '');
  if (!text) return '';
  if (/月初|初旬|上旬|上半月|月前期/.test(text)) return '05';
  if (/月中|中旬|中期/.test(text)) return '15';
  if (/月末|月底|下旬|末旬|下半月|月后期/.test(text)) return '25';
  return '';
}

function ceInferOriginalTimelineRelativeHour(asciiText) {
  const text = String(asciiText || '');
  if (!text) return '';
  if (/凌晨|拂晓/.test(text)) return '03';
  if (/清晨|早晨|一早/.test(text)) return '06';
  if (/上午|早间/.test(text)) return '09';
  if (/中午|午时/.test(text)) return '12';
  if (/下午|午后/.test(text)) return '15';
  if (/傍晚|黄昏/.test(text)) return '18';
  if (/夜间|夜里|晚间/.test(text)) return '21';
  if (/深夜|午夜/.test(text)) return '23';
  return '';
}

function ceExtractOriginalTimelineComparableTimeInfo(rawText) {
  const asciiText = ceNormalizeOriginalTimelineAsciiText(rawText);
  const match = asciiText.match(/(\d{4})\s*(?:年|[.\/-])\s*(\d{1,2})(?:\s*(?:月|[.\/-])\s*(\d{1,2}))?\s*(?:日|号)?/);
  if (!match) {
    return {
      value: '',
      monthValue: '',
      hasDay: false,
      hasTime: false,
      year: '',
      month: '',
      day: '',
      hour: '',
      minute: ''
    };
  }

  const year = String(match[1] || '').padStart(4, '0');
  const month = String(match[2] || '').padStart(2, '0');
  let day = match[3] ? String(match[3] || '').padStart(2, '0') : '';
  if (!day) {
    day = ceInferOriginalTimelineRelativeDay(asciiText);
  }

  const timeMatch = asciiText.match(/(?:\s|^)(\d{1,2})\s*(?::|点|时)\s*(\d{1,2})?/);
  let hour = timeMatch && timeMatch[1] ? String(timeMatch[1] || '').padStart(2, '0') : '';
  let minute = timeMatch && timeMatch[2] ? String(timeMatch[2] || '').padStart(2, '0') : '';
  if (!hour) {
    hour = ceInferOriginalTimelineRelativeHour(asciiText);
  }
  if (hour && !minute) {
    minute = '00';
  }

  return {
    value: [
      year,
      month,
      day || '00',
      hour || '00',
      minute || '00'
    ].join('.'),
    monthValue: year + '.' + month,
    hasDay: !!day,
    hasTime: !!hour,
    year,
    month,
    day: day || '',
    hour: hour || '',
    minute: minute || ''
  };
}

function ceExtractOriginalTimelineComparableTime(rawText) {
  return ceExtractOriginalTimelineComparableTimeInfo(rawText).value;
}

function ceInspectOriginalTimelineAnchorDrift(anchorTime, currentTime) {
  const anchorText = String(anchorTime || '').trim();
  const currentText = String(currentTime || '').trim();
  const anchorInfo = ceExtractOriginalTimelineComparableTimeInfo(anchorText);
  const currentInfo = ceExtractOriginalTimelineComparableTimeInfo(currentText);

  if (!anchorInfo.monthValue || !currentInfo.monthValue) {
    return {
      anchorInfo,
      currentInfo,
      yearDelta: 0,
      monthDelta: 0,
      suspicious: false,
      reason: ''
    };
  }

  const anchorYear = parseInt(anchorInfo.year || '0', 10);
  const currentYear = parseInt(currentInfo.year || '0', 10);
  const anchorMonth = Math.max(1, parseInt(anchorInfo.month || '1', 10) || 1);
  const currentMonth = Math.max(1, parseInt(currentInfo.month || '1', 10) || 1);
  const yearDelta = Math.abs(anchorYear - currentYear);
  const monthDelta = Math.abs((anchorYear * 12 + (anchorMonth - 1)) - (currentYear * 12 + (currentMonth - 1)));

  let suspicious = false;
  let reason = '';
  if (yearDelta >= 100) {
    suspicious = true;
    reason = 'year_century_gap';
  } else if (monthDelta > 240) {
    suspicious = true;
    reason = 'month_gap_exceeds_20y';
  }

  return {
    anchorInfo,
    currentInfo,
    yearDelta,
    monthDelta,
    suspicious,
    reason
  };
}

function ceResolveOriginalTimelineEffectiveAnchorTime(anchorTime, currentTime) {
  const anchorText = String(anchorTime || '').trim();
  const currentText = String(currentTime || '').trim();
  const drift = ceInspectOriginalTimelineAnchorDrift(anchorText, currentText);
  const anchorInfo = drift.anchorInfo || ceExtractOriginalTimelineComparableTimeInfo(anchorText);
  const currentInfo = drift.currentInfo || ceExtractOriginalTimelineComparableTimeInfo(currentText);

  if (!anchorInfo.monthValue) {
    return currentText || anchorText;
  }
  if (drift.suspicious && currentText) {
    return currentText;
  }
  if (!anchorInfo.hasDay && currentInfo.monthValue === anchorInfo.monthValue && currentInfo.hasDay) {
    return currentText;
  }
  return anchorText || currentText;
}

function ceCompareOriginalTimelineComparableMonth(a, b) {
  const left = ceExtractOriginalTimelineComparableMonth(a);
  const right = ceExtractOriginalTimelineComparableMonth(b);
  if (!left || !right) return 0;
  if (left === right) return 0;
  return left < right ? -1 : 1;
}

function ceCompareOriginalTimelineComparableTime(a, b) {
  const leftInfo = a && typeof a === 'object' && a.value !== undefined
    ? a
    : ceExtractOriginalTimelineComparableTimeInfo(a);
  const rightInfo = b && typeof b === 'object' && b.value !== undefined
    ? b
    : ceExtractOriginalTimelineComparableTimeInfo(b);
  if (!leftInfo.monthValue || !rightInfo.monthValue) return 0;
  if (leftInfo.value === rightInfo.value) return 0;
  return leftInfo.value < rightInfo.value ? -1 : 1;
}

function ceFilterOriginalTimelineRowsByAnchorTime(rows, anchorTime, getText) {
  const list = Array.isArray(rows) ? rows : [];
  if (list.length === 0) return [];

  const anchorInfo = ceExtractOriginalTimelineComparableTimeInfo(anchorTime);
  const anchorMonth = anchorInfo.monthValue || ceExtractOriginalTimelineComparableMonth(anchorTime);
  if (!anchorMonth) return list.slice();

  const resolver = typeof getText === 'function'
    ? getText
    : function(item) {
      return item && item.text ? item.text : item;
    };
  const anchorHasDay = !!anchorInfo.hasDay;
  const decorated = list.map(function(row) {
    const text = String(resolver(row) || '');
    return {
      row,
      monthValue: ceExtractOriginalTimelineComparableMonth(text),
      timeInfo: ceExtractOriginalTimelineComparableTimeInfo(text)
    };
  });
  const sameMonthRows = decorated.filter(function(item) {
    return item.monthValue === anchorMonth;
  });

  if (sameMonthRows.length > 0) {
    if (!anchorHasDay) {
      return sameMonthRows.map(function(item) { return item.row; });
    }

    const preciseSameMonthRows = sameMonthRows.filter(function(item) {
      return !!(item.timeInfo && item.timeInfo.hasDay);
    });
    if (preciseSameMonthRows.length === 0) {
      const anchorDayNum = Math.max(1, Math.min(30, parseInt(anchorInfo.day || '1', 10) || 1));
      const inferredCount = Math.max(1, Math.min(
        sameMonthRows.length,
        Math.ceil((anchorDayNum / 30) * sameMonthRows.length)
      ));
      return sameMonthRows.slice(0, inferredCount).map(function(item) {
        return item.row;
      });
    }

    return sameMonthRows.filter(function(item) {
      if (!(item.timeInfo && item.timeInfo.hasDay)) return true;
      return ceCompareOriginalTimelineComparableTime(item.timeInfo || {}, anchorInfo) <= 0;
    }).map(function(item) {
      return item.row;
    });
  }

  return decorated.filter(function(item) {
    if (!item.monthValue) return true;
    const monthCompare = ceCompareOriginalTimelineComparableMonth(item.monthValue, anchorMonth);
    if (monthCompare < 0) return true;
    if (monthCompare > 0) return false;
    if (!anchorHasDay) return true;
    return !!(item.timeInfo && item.timeInfo.hasDay)
      && ceCompareOriginalTimelineComparableTime(item.timeInfo, anchorInfo) <= 0;
  }).map(function(item) {
    return item.row;
  });
}

function ceFilterOriginalTimelineSectionByAnchorTime(sectionText, anchorTime, modeText) {
  const text = String(sectionText || '').trim();
  const anchorMonth = ceExtractOriginalTimelineComparableMonth(anchorTime);
  if (!text || !anchorMonth) return text;
  const normalizedMode = String(modeText || '').trim().toLowerCase();
  if (/^(?:batch|区间|批量|闭关|跳时|快进|跨度|skip_time|retreat)$/i.test(normalizedMode)) {
    return text;
  }

  const blocks = [];
  let buffer = [];
  const flush = () => {
    const blockText = buffer.join('\n').trim();
    if (blockText) blocks.push(blockText);
    buffer = [];
  };

  text.split(/\r?\n/).forEach(line => {
    const trimmed = String(line || '').trim();
    if (!trimmed) return;
    if (ceIsOriginalTimelineEventStartLine(trimmed) && buffer.length > 0) {
      flush();
    }
    buffer.push(trimmed);
  });
  flush();
  if (!blocks.length) return text;

  const filteredBlocks = ceFilterOriginalTimelineRowsByAnchorTime(blocks, anchorTime, function(block) {
    const timeMatch = String(block || '').match(/(?:^|\n)(?:[-*•]+\s*)?时间\s*[:：]\s*([^\n\r]+)/);
    if (timeMatch && timeMatch[1]) return timeMatch[1];
    const firstLine = String(block || '').split(/\r?\n/).map(function(line) {
      return String(line || '').trim();
    }).find(Boolean);
    return firstLine || block;
  });

  return filteredBlocks.join('\n').trim();
}

function ceParseOriginalTimelinePromptBlock(rawBlock) {
  const text = typeof rawBlock === 'string' ? rawBlock.trim() : '';
  const meta = {
    rawBlock: text,
    eventTextBlock: '',
    eventDigest: '',
    rangeText: '',
    modeText: '',
    anchorTime: '',
    sourceLabel: '',
    briefRangeText: '',
    originalRangeText: '',
    briefItemsText: '',
    originalItemsText: '',
    itemText: '',
    auditSeed: '',
    hasTimeline: false
  };
  if (!text) return meta;

  const lines = text.split(/\r?\n/);
  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed) return;
    if (trimmed.indexOf('世界年表参考注入时间锚点: ') === 0) {
      meta.anchorTime = trimmed.substring('世界年表参考注入时间锚点: '.length).trim();
    } else if (trimmed.indexOf('时间锚点来源: ') === 0) {
      meta.sourceLabel = trimmed.substring('时间锚点来源: '.length).trim();
    } else if (trimmed.indexOf('注入模式: ') === 0) {
      meta.modeText = trimmed.substring('注入模式: '.length).trim();
    } else if (trimmed.indexOf('简略版范围: ') === 0) {
      meta.briefRangeText = trimmed.substring('简略版范围: '.length).trim();
    } else if (trimmed.indexOf('原著版范围: ') === 0) {
      meta.originalRangeText = trimmed.substring('原著版范围: '.length).trim();
    } else if (trimmed.indexOf('纳入条目(简略版): ') === 0) {
      meta.briefItemsText = trimmed.substring('纳入条目(简略版): '.length).trim();
    } else if (trimmed.indexOf('纳入条目(原著版): ') === 0) {
      meta.originalItemsText = trimmed.substring('纳入条目(原著版): '.length).trim();
    }
  });

  meta.eventTextBlock = ceFilterOriginalTimelineSectionByAnchorTime(
    ceExtractOriginalTimelineSection(text),
    meta.anchorTime,
    meta.modeText
  );
  meta.rangeText = meta.originalRangeText || meta.briefRangeText || '';
  meta.itemText = meta.originalItemsText || meta.briefItemsText || '';
  meta.eventDigest = ceBuildOriginalTimelineDigest(meta);
  meta.auditSeed = [
    meta.anchorTime || '',
    meta.modeText || '',
    meta.rangeText || '',
    meta.itemText || ''
  ].join('|');
  meta.hasTimeline = !!(meta.eventTextBlock || meta.itemText || meta.rangeText);
  return meta;
}

function cePromptNeedsOriginalReferenceVectorContext(prompt) {
  return /\$\{(?:original_character_vectors|original_item_vectors|original_technique_vectors|original_faction_vectors|original_location_vectors|original_beast_vectors|original_reference_vectors|original_character_vectors_full|original_item_vectors_full|original_technique_vectors_full|original_faction_vectors_full|original_location_vectors_full|original_beast_vectors_full|original_reference_full_blocks)\}/.test(String(prompt || ''));
}

function ceResolveImportantOriginalRoleFromCandidate(entry, data, candidateName, candidateId) {
  if (typeof ceCollectOffscreenCandidateTokens === 'function') {
    try {
      const tokens = ceCollectOffscreenCandidateTokens(entry, data, candidateName, candidateId);
      const matched = ceResolveImportantOriginalRoleFromTokens(tokens);
      if (matched) return matched;
    } catch (e) {}
  }

  const rawName = String(data && data['1'] || '').split('|')[0] || '';
  const fallbacks = [candidateId, candidateName, rawName, entry?.title, entry?.name, entry?.displayName];
  for (const value of fallbacks) {
    const matched = ceResolveImportantOriginalRoleName(value);
    if (matched) return matched;
  }
  return '';
}

function ceResolveOriginalReferencePrimaryType(typeScores) {
  const scores = typeScores || {};
  let bestType = '';
  let bestScore = 0;
  CE_ORIGINAL_REFERENCE_TYPE_ORDER.forEach(type => {
    const score = Number(scores[type] || 0);
    if (score > bestScore) {
      bestType = type;
      bestScore = score;
    }
  });
  return bestType;
}

function ceResolveOriginalReferenceTypesFromSource(source) {
  const sourceText = String(source || '');
  const mappedTypes = [];
  CE_ORIGINAL_REFERENCE_SOURCE_TYPE_RULES.forEach(rule => {
    if (!rule || !(rule.regex instanceof RegExp) || !rule.regex.test(sourceText)) return;
    (Array.isArray(rule.types) ? rule.types : []).forEach(type => mappedTypes.push(type));
  });
  return ceNormalizeOriginalReferenceTypes(mappedTypes);
}

function ceScoreOriginalReferenceVectorEntry(entityType, candidates, entry, options = {}) {
  const requestedTypes = ceNormalizeOriginalReferenceTypes(entityType);
  const candidateRows = Array.isArray(candidates) ? candidates : [];
  if (!entry || !candidateRows.length) return null;
  if (requestedTypes.length && !requestedTypes.some(type => Array.isArray(entry.types) && entry.types.includes(type))) {
    return null;
  }

  const titleText = String(entry.title || '');
  const sourceText = String(entry.source || '');
  const contentText = String(entry.content || '');
  const normalizedTitle = entry.normalizedTitle || ceNormalizeOriginalReferenceName(titleText);
  const normalizedSourceLeaf = ceNormalizeOriginalReferenceName(entry.sourceLeaf || sourceText.split(/[\/\\]/).pop() || '');
  const sourceSegments = Array.isArray(entry.sourceSegments)
    ? entry.sourceSegments.map(item => ceNormalizeOriginalReferenceName(item)).filter(Boolean)
    : [];
  let bestMatch = null;

  candidateRows.forEach(candidate => {
    const candidateVariants = Array.isArray(candidate.variants) && candidate.variants.length
      ? candidate.variants
      : [candidate.normalized];
    const candidateSemanticTokens = Array.isArray(candidate.semanticTokens) ? candidate.semanticTokens : [];
    let candidateBestScore = 0;
    let matchedVariant = '';
    let via = '';

    candidateVariants.forEach(variant => {
      const normalizedVariant = ceNormalizeOriginalReferenceName(variant);
      if (!normalizedVariant) return;

      let score = 0;
      let reason = '';
      if (normalizedVariant === normalizedTitle) {
        score = 0.98;
        reason = 'title_exact';
      } else if (normalizedSourceLeaf && normalizedVariant === normalizedSourceLeaf) {
        score = 0.95;
        reason = 'source_leaf_exact';
      } else if (sourceSegments.includes(normalizedVariant)) {
        score = 0.91;
        reason = 'folder_exact';
      } else if (normalizedTitle && (normalizedTitle.includes(normalizedVariant) || normalizedVariant.includes(normalizedTitle))) {
        score = normalizedTitle.length === normalizedVariant.length ? 0.92 : 0.88;
        reason = 'title_fuzzy';
      } else if (sourceSegments.some(segment => segment && (segment.includes(normalizedVariant) || normalizedVariant.includes(segment)))) {
        score = 0.86;
        reason = 'folder_fuzzy';
      } else if ((candidate.raw && sourceText.includes(candidate.raw)) || sourceText.includes(normalizedVariant)) {
        score = 0.84;
        reason = 'source_match';
      } else if ((candidate.raw && contentText.includes(candidate.raw)) || contentText.includes(normalizedVariant)) {
        score = 0.72;
        reason = 'content_match';
      }

      if (score > candidateBestScore) {
        candidateBestScore = score;
        matchedVariant = normalizedVariant;
        via = reason;
      }
    });

    if (candidateBestScore <= 0) {
      const semanticScore = ceScoreOriginalReferenceSemanticAlignment(candidate, entry, candidateSemanticTokens);
      if (semanticScore > 0) {
        candidateBestScore = semanticScore;
        matchedVariant = candidate.raw || candidate.normalized;
        via = 'semantic_similarity';
      }
    }

    if (candidateBestScore <= 0) return;

    const candidateTypeHints = ceNormalizeOriginalReferenceTypes(candidate.typeHints || []);
    if (requestedTypes.length) {
      if (requestedTypes.some(type => type === entry.primaryType)) {
        candidateBestScore += 0.04;
      } else if (requestedTypes.some(type => Array.isArray(entry.types) && entry.types.includes(type))) {
        candidateBestScore += 0.02;
      }
    }
    if (candidateTypeHints.some(type => Array.isArray(entry.types) && entry.types.includes(type))) {
      candidateBestScore += 0.03;
    }
    const scopePriority = Number(entry.scopePriority || ceGetOriginalReferenceScopePriority(entry.scope) || 0);
    if (scopePriority >= 2) {
      candidateBestScore += 0.04;
    } else if (scopePriority === 1) {
      candidateBestScore += 0.01;
    }
    candidateBestScore += Math.min(Number(candidate.score || 0) / 40, 0.05);
    candidateBestScore = Math.min(candidateBestScore, 0.995);

    if (!bestMatch || candidateBestScore > bestMatch.confidence || (
      candidateBestScore === bestMatch.confidence && scopePriority > Number(bestMatch.scopePriority || 0)
    )) {
      bestMatch = {
        entityType: requestedTypes[0] || entry.primaryType || '',
        confidence: Number(candidateBestScore.toFixed(4)),
        candidate: candidate.raw || candidate.normalized,
        matchedName: matchedVariant || candidate.normalized,
        canonicalName: entry.title || candidate.raw || candidate.normalized,
        title: entry.title || candidate.raw || candidate.normalized,
        source: entry.source || '',
        sourceLeaf: entry.sourceLeaf || '',
        content: entry.textBlock || ('### ' + (entry.title || candidate.raw || candidate.normalized) + '\n' + contentText),
        via,
        primaryType: entry.primaryType || '',
        types: Array.isArray(entry.types) ? entry.types.slice() : [],
        categoryTokens: Array.isArray(entry.categoryTokens) ? entry.categoryTokens.slice() : [],
        scope: entry.scope || '',
        scopePriority
      };
    }
  });

  return bestMatch;
}

async function ceSearchOriginalCharacterVectors(candidate, options = {}) {
  const rawName = candidate && (candidate.raw || candidate.name || candidate.normalized || candidate);
  const variants = Array.isArray(candidate && candidate.variants) && candidate.variants.length > 0
    ? candidate.variants
    : ceBuildOriginalTimelineNameVariants(rawName);
  if (!variants.length) return null;

  const matches = [];
  const pushMatch = (confidence, canonicalName, content, source, title, via, extra = {}) => {
    if (!canonicalName || !content) return;
    matches.push({
      confidence,
      canonicalName,
      content,
      source: source || ('人物传记/' + canonicalName),
      title: title || canonicalName,
      via,
      aliases: variants.filter(v => v !== ceNormalizeOriginalTimelineName(canonicalName)),
      scope: String(extra.scope || '').trim(),
      scopePriority: Number(extra.scopePriority || 0)
    });
  };

  const biographyCache = options.biographyCache;
  if (biographyCache instanceof Map) {
    biographyCache.forEach((content, name) => {
      if (!ceIsOriginalCharacterSettingVectorEntry({
        source: '人物传记/' + name,
        title: name,
        content: content
      })) {
        return;
      }
      const nameVariants = ceBuildOriginalTimelineNameVariants(name);
      const primaryName = nameVariants[0] || ceNormalizeOriginalTimelineName(name);
      let score = 0;
      variants.forEach(variant => {
        if (nameVariants.includes(variant) || primaryName === variant) {
          score = Math.max(score, 0.97);
        } else if (nameVariants.some(item => item && (item.includes(variant) || variant.includes(item)))) {
          score = Math.max(score, 0.88);
        }
      });
      if (score > 0) {
        pushMatch(score, name, content, '人物传记/' + name, name, 'biography_cache');
      }
    });
    const cacheBest = ceSelectOriginalTimelineVectorMatch(matches);
    if (cacheBest) return cacheBest;
  }

  if (typeof db === 'undefined' || !db || !db.vectors) return null;

  try {
    await db.vectors
      .where('source').startsWith('人物传记')
      .each(v => {
        if (!v || v.outdatedTimestamp) return;
        const sourceText = String(v.source || '');
        if (!ceIsOriginalCharacterSettingVectorEntry(v, {
          source: sourceText,
          title: v.title,
          content: v.content
        })) {
          return;
        }
        const sourceName = sourceText.split(/[\/\\]/).pop() || v.title || rawName;
        const sourceVariants = ceBuildOriginalTimelineNameVariants(sourceName);
        const sourcePrimary = sourceVariants[0] || ceNormalizeOriginalTimelineName(sourceName);
        const titlePrimary = ceNormalizeOriginalTimelineName(v.title || '');
        const contentText = String(v.content || '');
        const scope = ceInferOriginalReferenceScope(v, sourceText);
        const scopePriority = Number(ceGetOriginalReferenceScopePriority(scope) || 0);
        let score = 0;

        variants.forEach(variant => {
          if (sourceVariants.includes(variant) || sourcePrimary === variant) {
            score = Math.max(score, 0.95);
          } else if (titlePrimary && titlePrimary === variant) {
            score = Math.max(score, 0.92);
          } else if (sourceVariants.some(item => item && (item.includes(variant) || variant.includes(item)))) {
            score = Math.max(score, 0.86);
          } else if (titlePrimary && (titlePrimary.includes(variant) || variant.includes(titlePrimary))) {
            score = Math.max(score, 0.84);
          }
        });

        if (score > 0) {
          pushMatch(
            score,
            sourceName,
            '### ' + (v.title || sourceName) + '\n' + contentText,
            sourceText,
            v.title || sourceName,
            'vector_db',
            { scope, scopePriority }
          );
        }
      });
  } catch (e) {
    console.warn('[原著年表] 人物向量召回失败:', e);
  }

  return ceSelectOriginalTimelineVectorMatch(matches);
}

async function ceSearchOriginalEncyclopediaVectors(entityType, names, options = {}) {
  const requestedTypes = ceNormalizeOriginalReferenceTypes(entityType);
  const normalizedEntityType = requestedTypes[0] || '';
  const candidates = ceNormalizeOriginalReferenceSearchNames(names, requestedTypes);
  if (!candidates.length) return [];

  const referenceVectorCache = await ceBuildOriginalReferenceVectorCache(options);
  if (!Array.isArray(referenceVectorCache) || !referenceVectorCache.length) return [];

  const matches = [];
  referenceVectorCache.forEach(entry => {
    const match = ceScoreOriginalReferenceVectorEntry(normalizedEntityType, candidates, entry, options);
    if (match) matches.push(match);
  });

  return ceSelectOriginalReferenceVectorMatches(matches, options);
}

async function ceSearchOriginalReferenceVectors(entityType, names, options = {}) {
  const rawEntityType = String(entityType || '').trim().toLowerCase();
  if (['character', 'person', 'npc'].includes(rawEntityType)) {
    const candidates = ceNormalizeOriginalReferenceSearchNames(names);
    if (!candidates.length) return [];

    const matches = [];
    for (const candidate of candidates) {
      const match = await ceSearchOriginalCharacterVectors(candidate, {
        biographyCache: options.biographyCache
      });
      if (!match) continue;
      matches.push(Object.assign({}, match, {
        entityType: 'character',
        primaryType: 'character',
        types: ['character'],
        categoryTokens: []
      }));
    }

    return ceSelectOriginalReferenceVectorMatches(matches, Object.assign({}, options, {
      minConfidence: options.minConfidence !== undefined ? options.minConfidence : 0.74
    }));
  }

  return ceSearchOriginalEncyclopediaVectors(rawEntityType, names, options);
}

function ceSelectOriginalReferenceVectorMatches(matches, options = {}) {
  const rows = Array.isArray(matches) ? matches : [];
  if (!rows.length) return [];

  const limit = Math.max(1, Number(options.limit || 6));
  const minConfidence = Number(options.minConfidence !== undefined ? options.minConfidence : 0.72);
  const sorted = rows.slice().sort((a, b) => {
    return (Number(b.confidence || 0) - Number(a.confidence || 0))
      || (Number(b.scopePriority || 0) - Number(a.scopePriority || 0))
      || (String(b.canonicalName || '').length - String(a.canonicalName || '').length);
  });

  const selected = [];
  const seen = new Set();
  sorted.forEach(match => {
    if (!match || Number(match.confidence || 0) < minConfidence) return;
    const key = [match.source || '', match.title || '', match.primaryType || ''].join('|');
    if (seen.has(key)) return;
    seen.add(key);
    selected.push(match);
  });

  if (!selected.length && sorted[0] && Number(sorted[0].confidence || 0) >= Math.max(0.62, minConfidence - 0.08)) {
    selected.push(sorted[0]);
  }

  return selected.slice(0, limit);
}

function ceSelectOriginalTimelineVectorMatch(matches) {
  if (!Array.isArray(matches) || matches.length === 0) return null;
  const sorted = matches.slice().sort((a, b) => {
    return (Number(b.confidence || 0) - Number(a.confidence || 0))
      || (Number(b.scopePriority || 0) - Number(a.scopePriority || 0))
      || (String(b.canonicalName || '').length - String(a.canonicalName || '').length);
  });
  const best = sorted[0];
  const second = sorted[1] || null;
  if (best.confidence >= 0.95) return best;
  if (best.confidence >= 0.86 && (!second || (best.confidence - second.confidence) >= 0.06)) return best;
  if (best.confidence >= 0.74 && (!second || (best.confidence - second.confidence) >= 0.12)) return best;
  return null;
}

function ceIsOriginalCharacterSettingVectorEntry(vector, options = {}) {
  const item = vector || {};
  const sourceText = String(options.source || item.source || '').trim();
  const titleText = String(options.title || item.title || '').trim();
  const contentText = String(options.content || item.content || '').trim();
  if (!contentText) return false;

  const scope = ceNormalizeOriginalReferenceScope(
    options.scope
      || item.scope
      || (item.meta && item.meta.scope)
      || (item.metadata && item.metadata.scope)
      || ceInferOriginalReferenceScope(item, sourceText)
  );
  if (scope === 'archive') return false;

  const labelText = [sourceText, titleText].join('\n');
  if (/(当前存档|archive|worldbook|world_book|世界档案|自定义|补充设定|快照|snapshot|临时)/i.test(labelText)) {
    return false;
  }
  if (/\[(?:updated|更新时间|last\s*updated)[:：]/i.test(contentText)) return false;
  if (/(当前动机|短期目标|长期目标|查看事迹|生平经历|暂无生平记录|要看更多内容点击下方|点击查看)/.test(contentText)) {
    return false;
  }
  const deedLikeLineCount = (contentText.match(/(?:^|\n)\s*\[[^\]\n]{2,80}@[^^\]\n]{1,80}\][^\n]*/g) || []).length;
  if (deedLikeLineCount > 0) return false;

  return true;
}

function ceTruncateOriginalTimelineText(text, maxLength = 800) {
  const normalized = String(text || '').trim();
  if (!normalized) return '';
  if (normalized.length <= maxLength) return normalized;
  return normalized.slice(0, maxLength) + '...';
}

function ceBuildOriginalTimelineMutationEvidenceDisplayText(inputText, options = {}) {
  const opts = options || {};
  const normalizedInput = String(inputText || '').replace(/\r/g, '').trim();
  const playerImpactText = String(opts.playerImpactSummary || '').replace(/\s+/g, ' ').trim();
  const uiSysText = String(opts.uiSysText || '').replace(/\s+/g, ' ').trim();
  const monitorText = String(opts.monitorText || '').replace(/\s+/g, ' ').trim();

  const fallbackLines = [];
  if (playerImpactText) {
    fallbackLines.push('玩家/正文影响：' + ceTruncateOriginalTimelineText(playerImpactText, 220));
  }
  if (uiSysText) {
    fallbackLines.push('正文锚点：' + ceTruncateOriginalTimelineText(uiSysText, 120));
  } else if (monitorText) {
    fallbackLines.push('监控依据：' + ceTruncateOriginalTimelineText(monitorText, 120));
  }

  if (!normalizedInput) {
    return fallbackLines.join('\n');
  }

  const cleanedLines = normalizedInput
    .split(/\n+/)
    .map(function(line) {
      return String(line || '').replace(/\s+/g, ' ').trim();
    })
    .filter(Boolean)
    .map(function(line) {
      if (/^正文中的年表变异依据[:：]/.test(line)) return '';
      if (/^正文依据：/.test(line)) {
        const body = line.replace(/^正文依据：/, '').trim();
        if (body.length > 160) {
          if (uiSysText) return '正文锚点：' + ceTruncateOriginalTimelineText(uiSysText, 120);
          if (monitorText) return '监控依据：' + ceTruncateOriginalTimelineText(monitorText, 120);
          return '正文依据：当前正文已出现与原著事件相关的场景推进片段。';
        }
        return '正文依据：' + ceTruncateOriginalTimelineText(body, 120);
      }
      return ceTruncateOriginalTimelineText(line, 220);
    })
    .filter(Boolean)
    .filter(function(line, index, array) {
      return array.indexOf(line) === index;
    })
    .slice(0, 4);

  if (cleanedLines.length === 0) {
    return fallbackLines.join('\n');
  }
  return cleanedLines.join('\n');
}


async function resolveWorldFactorsContext() {
  try {
    if (typeof getWorldFactorsContext === 'function') {
      const ctx = await getWorldFactorsContext();
      if (ctx) return ctx;
    }
  } catch (e) {
    console.warn('[并发演化] 获取世界因子失败（全局函数）:', e);
  }

  try {
    if (!currentArchiveName || !db || !db.archives || !db.archives.get) return '无世界因子';
    const archive = await db.archives.get(currentArchiveName);
    const firstLog = archive?.data?.logs?.[0];
    if (!firstLog || !firstLog.content) return '无世界因子';

    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = firstLog.content;
    const summaries = tempDiv.querySelectorAll('details summary');
    let factorList = null;

    for (const summary of summaries) {
      if (summary.textContent.includes('世界规则变动')) {
        const parentDetails = summary.parentElement;
        if (parentDetails) {
          factorList = parentDetails.querySelector('ul');
        }
        break;
      }
    }

    if (factorList) {
      const listItems = factorList.querySelectorAll('li');
      if (listItems.length > 0) {
        return Array.from(listItems)
          .map(li => li.textContent.replace(/\\s+/g, ' ').trim())
          .join('\\n');
      }
    }
  } catch (e) {
    console.warn('[并发演化] 获取世界因子失败（存档解析）:', e);
  }

  return '无世界因子';
}

/**
 * 处理sharedRules，兼容字符串数组和对象数组两种格式
 * @param {Array} sharedRules - 可能是字符串数组或对象数组
 * @returns {string} - 合并后的规则文本
 */
function processSharedRules(sharedRules) {
  if (!sharedRules || !Array.isArray(sharedRules) || sharedRules.length === 0) {
    return '';
  }

  return sharedRules
    .filter(rule => {
      // 对象格式检查enabled
      if (typeof rule === 'object' && rule !== null) {
        return rule.enabled !== false;
      }
      // 字符串格式直接返回true
      return true;
    })
    .map(rule => {
      // 对象格式提取content
      if (typeof rule === 'object' && rule !== null) {
        return rule.content || '';
      }
      // 字符串格式直接返回
      return rule;
    })
    .filter(text => text.trim().length > 0)
    .join('\n\n');
}

function ceNormalizeGenderScope(scope) {
  const raw = String(scope || 'all').trim().toLowerCase();
  if (!raw || raw === 'all' || raw === 'any' || raw === 'both' || raw === 'none') return 'all';
  if (raw === 'male' || raw === 'man' || raw === 'm' || raw === '男' || raw === '男性') return 'male';
  if (raw === 'female' || raw === 'woman' || raw === 'f' || raw === '女' || raw === '女性') return 'female';
  return 'all';
}

function ceNormalizeGenderValue(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return 'unknown';
  if (raw.includes('女性') || raw === '女' || raw === 'female' || raw === 'f') return 'female';
  if (raw.includes('男性') || raw === '男' || raw === 'male' || raw === 'm') return 'male';
  return 'unknown';
}

function ceExtractPlayerGenderFromRow(playerRow) {
  if (!playerRow || typeof playerRow !== 'object') return 'unknown';

  // 首选第1列：名称|性别
  const nameGender = String(playerRow['1'] || '');
  if (nameGender.includes('|')) {
    const parts = nameGender.split('|');
    const tail = parts[parts.length - 1];
    const byColumn1 = ceNormalizeGenderValue(tail);
    if (byColumn1 !== 'unknown') return byColumn1;
  }

  // 兜底：第9列中常见 avatar:男性 / avatar:女性
  const remarks = String(playerRow['9'] || '');
  const avatarMatch = remarks.match(/(?:^|[|,\\s])avatar\\s*:\\s*([^|,\\s]+)/i);
  if (avatarMatch && avatarMatch[1]) {
    const byAvatar = ceNormalizeGenderValue(avatarMatch[1]);
    if (byAvatar !== 'unknown') return byAvatar;
  }

  return 'unknown';
}

function ceResolveTargetGender(target) {
  if (!target || target.type !== 'player') return 'unknown';
  const byTarget = ceExtractPlayerGenderFromRow(target.data || {});
  if (byTarget !== 'unknown') return byTarget;
  const b1Row = currentState && currentState['0'] ? currentState['0']['B1'] : null;
  return ceExtractPlayerGenderFromRow(b1Row || {});
}

function ceIsRuleGenderEnabled(rule, target) {
  if (!rule || rule.enabled === false) return false;
  if (!target || target.type !== 'player') return true;

  const scope = ceNormalizeGenderScope(rule.genderScope || rule.gender_scope || 'all');
  if (scope === 'all') return true;

  const gender = ceResolveTargetGender(target);
  if (scope === 'male') return gender === 'male';
  if (scope === 'female') return gender === 'female';
  return true;
}

function ceIsPlayerOriginalTimelineSection(section) {
  const markerText = [
    String(section && section.id || ''),
    String(section && section.name || ''),
    String(section && section.content || '')
  ].join('\n');
  return /\$\{world_timeline_context\}|\$\{original_timeline_|\$\{original_event_|\$\{original_reference_/i.test(markerText);
}

function ceBuildEnabledMapForTarget(sections, target) {
  const enabledMap = {};
  (sections || []).forEach(section => {
    let enabled = ceIsRuleGenderEnabled(section, target);
    if (enabled && target && target.type === 'player' && ceIsPlayerOriginalTimelineSection(section)) {
      enabled = false;
    }
    enabledMap[section.id] = enabled;
  });
  return enabledMap;
}

async function ceBuildWorldTimelinePromptBlock(options) {
  // 旧补演的CE年表通路已由独立补演接管，不再发送原年表。
  return '';
  const opts = options && typeof options === 'object' ? options : {};
  const currentTimeText = opts.currentTime ? opts.currentTime : '';
  const userInputPreview = String(opts.userInput ? opts.userInput : '').slice(0, 120);
  const forceFresh = !!opts.forceFresh;
  const preferReplayBlock = !!opts.preferReplayBlock;
  const sharedContext = opts.sharedContext && typeof opts.sharedContext === 'object'
    ? opts.sharedContext
    : null;

  if (preferReplayBlock) {
    try {
      const replayContext = Object.assign({}, sharedContext || {}, {
        currentTime: currentTimeText || (sharedContext && sharedContext.currentTime) || '',
        userInput: opts.userInput !== undefined
          ? opts.userInput
          : ((sharedContext && sharedContext.userInput) || ''),
        stateSnapshot: opts.snapshotText !== undefined
          ? opts.snapshotText
          : ((sharedContext && sharedContext.stateSnapshot) || '')
      });
      const replayBlock = await ceBuildOriginalTimelineReplayPromptBlock(replayContext, {
        currentTime: replayContext.currentTime || '',
        userInput: replayContext.userInput || ''
      });
      if (replayBlock) {
        const replayParsed = ceParseOriginalTimelinePromptBlock(replayBlock || '');
        ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
          stage: 'replay',
          currentTime: currentTimeText,
          freshAnchorTime: replayParsed && replayParsed.anchorTime ? replayParsed.anchorTime : '',
          forcedFresh: forceFresh,
          userInputPreview,
          blockPreview: String(replayBlock || '').slice(0, 600)
        });
        return replayBlock;
      }
    } catch (e) {
      console.warn('[并发演化] 原著补演专用年表区间构建失败，回退普通年表注入:', e);
      ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
        stage: 'replay_error',
        currentTime: currentTimeText,
        forcedFresh: forceFresh,
        error: e && e.message ? e.message : String(e)
      });
    }
  }

  const timelinePromptCache = (typeof _wtCachedConcurrentEvolutionTimelinePromptBlock === 'string' && _wtCachedConcurrentEvolutionTimelinePromptBlock)
    ? _wtCachedConcurrentEvolutionTimelinePromptBlock
    : '';

  // 优先复用本轮变量演化专用年表缓存，避免误吃正文请求的普通注入缓存
  if (!preferReplayBlock && !forceFresh && timelinePromptCache) {
    const cachedParsed = ceParseOriginalTimelinePromptBlock(timelinePromptCache);
    const anchorDrift = ceInspectOriginalTimelineAnchorDrift(
      cachedParsed && cachedParsed.anchorTime ? cachedParsed.anchorTime : '',
      currentTimeText
    );
    if (!anchorDrift.suspicious) {
      ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
        stage: 'cached_concurrent_evolution',
        currentTime: currentTimeText,
        cachedAnchorTime: cachedParsed && cachedParsed.anchorTime ? cachedParsed.anchorTime : '',
        anchorDriftReason: anchorDrift.reason || '',
        anchorYearDelta: anchorDrift.yearDelta || 0,
        anchorMonthDelta: anchorDrift.monthDelta || 0,
        userInputPreview,
        blockPreview: String(timelinePromptCache || '').slice(0, 600)
      });
      return timelinePromptCache;
    }
    ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
      stage: 'cached_concurrent_evolution_rejected',
      currentTime: currentTimeText,
      cachedAnchorTime: cachedParsed && cachedParsed.anchorTime ? cachedParsed.anchorTime : '',
      anchorDriftReason: anchorDrift.reason || '',
      anchorYearDelta: anchorDrift.yearDelta || 0,
      anchorMonthDelta: anchorDrift.monthDelta || 0,
      userInputPreview,
      blockPreview: String(timelinePromptCache || '').slice(0, 600)
    });
  }
  if (typeof buildWorldEvolutionTimelinePromptContext !== 'function') return '';
  try {
    const block = await buildWorldEvolutionTimelinePromptContext({
      currentTime: currentTimeText,
      snapshotText: opts.snapshotText ? opts.snapshotText : '',
      userInput: opts.userInput ? opts.userInput : '',
      forConcurrentEvolution: true
    });
    const parsed = ceParseOriginalTimelinePromptBlock(block || '');
    const anchorDrift = ceInspectOriginalTimelineAnchorDrift(
      parsed && parsed.anchorTime ? parsed.anchorTime : '',
      currentTimeText
    );
    ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
      stage: anchorDrift.suspicious ? 'fresh_suspicious' : 'fresh',
      currentTime: currentTimeText,
      freshAnchorTime: parsed && parsed.anchorTime ? parsed.anchorTime : '',
      anchorDriftReason: anchorDrift.reason || '',
      anchorYearDelta: anchorDrift.yearDelta || 0,
      anchorMonthDelta: anchorDrift.monthDelta || 0,
      forcedFresh: forceFresh,
      userInputPreview,
      blockPreview: String(block || '').slice(0, 600)
    });
    return block;
  } catch (e) {
    console.warn('[并发演化] 世界年表注入构建失败:', e);
    ceTraceDiag('ORIGINAL_TIMELINE_BUILD_BLOCK', {
      stage: 'error',
      currentTime: currentTimeText,
      forcedFresh: forceFresh,
      error: e && e.message ? e.message : String(e)
    });
    return '';
  }
}

// ============================================================
// 原著指导（正文前唯一环节）
//
// 位置依据：总设计 §2.1 / §10-10 —— 整个系统只有这一步在正文之前，
// 其余全部在正文之后。它只产出一段约束文字，**不写存档**。
//
// 失败一律降级为「不注入」，正文照常生成（08-13 §6.1）。
// ============================================================
// 正文优化只替换中间故事；时间、UI标记和尾部结构仍由原卡正则处理。
function frReplaceStoryBody(original,body) {
  const source=String(original || ''),text=String(body || '');
  return /<content>[\s\S]*?<\/content>/i.test(source)
    ? source.replace(/(<content>)[\s\S]*?(<\/content>)/i,(_,open,close)=>open+text+close)
    : text;
}

async function ceBuildCanonGuidanceForStory(ctx) {
  try {
    if (typeof ceBridgeRunGuidance !== 'function') return '';
    const options = ctx || {};
    const result = await ceBridgeRunGuidance({
      worldTime: options.currentTime || '',
      targetTime: options.targetTime || '',
      playerInput: options.userInput || '',
      sharedContext: options.sharedContext || null,
      timeline: options.timeline || null,
      storyTimeline: options.storyTimeline || null,
      signal: options.signal || null
    });
    if (!result || result.injectable !== true) return '';
    const text = String(result.text || '').trim();
    if (!text) return '';
    return '\n\n' + text + '\n';
  } catch (e) {
    console.warn('[原著补演] 原著指导失败，正文照常:', e);
    return '';
  }
}

// 年表选定后即可并行取指导材料；独立信号隔离正文缓存与记录。
function ceStartCanonGuidanceForStory(options) {
  // 指导记录只绑定自己的信号，不能把同时进行的正文检索标成补演请求。
  const controller=new AbortController(),parent=options.signal,signal=controller.signal;
  const relay=function(){controller.abort(parent.reason);};
  if(parent){if(parent.aborted)relay();else parent.addEventListener('abort',relay,{once:true});}
  return Promise.resolve(options.timelinePromise).then(function(block){
    signal.throwIfAborted();
    return ceBuildCanonGuidanceForStory({
      currentTime:options.currentTime,targetTime:'',userInput:options.userInput,
      storyTimeline:options.readSelection() || {block:String(block || ''),entries:[]},
      signal,sharedContext:{userInput:options.userInput}
    });
  }).catch(function(error){
    if(error?.name!=='AbortError')console.warn('[原著指导] 并行准备失败',error);
    return '';
  }).finally(function(){
    parent?.removeEventListener('abort',relay);
    // 检索完成后才关联本轮楼层；不把在途正文检索的子信号改成补演。
    if(parent&&typeof frCanonTraceLinkSignal==='function')frCanonTraceLinkSignal(signal,parent);
  });
}

// ============================================================
// 原著补演 · 账本挂载
//
// 用户 2026-10-21 的两条需求：
//   ① 账本能跟着每一轮快照回退
//   ② 下一轮能知道上一轮补到哪了（方方面面）
//
// 做法：账本不是全局单值，而是**挂在这一层快照里**。
// 快照在哪一层，账本就在哪一层；回退换一层快照，账本跟着换。
//
// 挂载点选在「写 log.stateSnapshot」那一行——那是存档落库的唯一入口，
// 账本跟它同生共死，天然同步。
// ============================================================

/** 最近一次算出来的账本（本轮还没落库时挂到这里，落库时取走） */
var _ceCanonLedgerPending = null;

/**
 * 把账本挂进即将保存的快照，返回 JSON 字符串。
 *
 * 没有账本可挂时（这轮没跑补演），原样返回当前状态的快照——
 * 不能因为缺账本就改变快照形态。
 *
 * @param {object} state 当前存档状态
 * @returns {string} 快照 JSON
 */
function ceAttachCanonLedgerToSnapshot(state) {
  try {
    var core = (typeof CE_CORE !== 'undefined' && CE_CORE) ? CE_CORE : null;
    if (!core || !core.ledger) return JSON.stringify(state);

    // 跟随本次状态快照；不能从window拿未来轮次的账本污染回退结果。
    var ledger = state && state[core.ledger.CE_LEDGER_SNAPSHOT_KEY] || null;
    if (!ledger) return JSON.stringify(state);

    // 把账本挂在快照对象上（不污染 currentState 本身）
    var out = Object.assign({}, state);
    out[core.ledger.CE_LEDGER_SNAPSHOT_KEY] = ledger;
    return JSON.stringify(out);
  } catch (e) {
    console.warn('[原著补演] 账本挂载失败，按普通快照保存:', e);
    return JSON.stringify(state);
  }
}

/**
 * 从快照里读账本。
 *
 * @param {object} host CEHost
 * @param {object} [fallback]
 * @returns {Promise<object>} 账本
 */
async function ceLoadCanonLedger(host, fallback) {
  try {
    var core = (typeof CE_CORE !== 'undefined' && CE_CORE) ? CE_CORE : null;
    if (!core || !core.ledger) {
      return { version: 2, worldTime: '', debts: [], openEvents: [], lastTurn: null };
    }
    var loaded = await core.ledger.loadLedger(host || ceBridgeHost(), fallback || {});
    if (loaded && loaded.migrated) {
      console.log('[原著补演] 账本已从旧全局键迁移到快照');
    }
    return loaded.ledger;
  } catch (e) {
    console.warn('[原著补演] 读账本失败，用空账本:', e);
    return { version: 2, worldTime: '', debts: [], openEvents: [], lastTurn: null };
  }
}

/**
 * 记下本轮算出来的账本，等快照落库时挂进去。
 * **只登记，不落库。** 真正落库要等 saveCurrentState 成功。
 *
 * @param {object} ledger
 */
function ceStageCanonLedger(ledger) {
  _ceCanonLedgerPending = ledger || null;
  try {
    if (typeof window !== 'undefined') {
      window._ceCanonLedgerSnapshot = ledger || null;
    }
  } catch (e) {}
}

/** 快照落库成功后清掉 pending */
function ceConfirmCanonLedger() {
  _ceCanonLedgerPending = null;
}

// ============================================================
// 原著补演（正文后）
//
// 位置依据：总设计 §3.1 —— 边界判定必须看到正文，所以整条链在正文之后。
//
// 三步，缺一不可：
//   ① 算差集 → 写散文（由核心包编排器完成）
//   ② 把散文交给既有四阶段落地（复用宿主现有链路，不另造一套）
//   ③ **落地成功后**才提交账本（§4.3.6：模型不能写账本）
//
// 任何一步失败：账本不动，世界时间不推进，本轮等于没发生。
// ============================================================
/**
 * 把生平经历追加进第 35 列。
 *
 * 复用卡里已有的合并逻辑（mergeAppendBiographyForAdd）——
 * 去重、截断、按人清洗全都在里面，不用另造一套。
 *
 * @param {object} biography name -> 要 append 的文本
 * @returns {Promise<number>} 成功写入的人数
 */
/**
 * 真正把第 35 列写进存档。
 *
 * 为什么直接改 currentState 而不是发 op：
 *   四阶段的 op 通路是给「模型自己决定改什么」用的，
 *   这里改什么是代码算出来的，已经确定了，
 *   走 op 只是多绕一圈，还可能被四阶段的清洗规则改掉。
 *
 * 为什么用 currentState['0'] 这个形状：
 *   canon-bridge.js 的读取侧就是 `currentState['0']`，
 *   写侧必须跟读侧同形，否则会写到一个没人读的副本里。
 *
 * @param {string} id 人物行 id
 * @param {string} text 合并好的第 35 列全文
 * @returns {boolean} 有没有真写进去
 */
function ceWriteCanonBiography(id, text) {
  const key = String(id == null ? '' : id).trim();
  const value = String(text == null ? '' : text).trim();
  if (!key || !value) return false;

  try {
    if (typeof currentState === 'undefined' || !currentState) return false;
    const rows = currentState['0'];
    if (!rows || typeof rows !== 'object') return false;

    const row = rows[key];
    if (!row || typeof row !== 'object') return false;

    row['35'] = value;
    return true;
  } catch (e) {
    console.warn('[原著补演] 第35列写入异常:', e);
    return false;
  }
}

async function ceAppendCanonBiography(biography) {
  const src = biography && typeof biography === 'object' ? biography : {};
  const entries = Object.entries(src).filter(([, text]) => String(text || '').trim());
  if (entries.length === 0) return 0;

  // 生平要写的是**人物行对象**，不是给提示词看的文本。
  // 原来这里调 ceBridgeReadCharacterDossiers()，那个函数返回字符串，
  // typeof 恒为 "string"，下面那句 typeof !== "object" 永远成立 → 恒写 0 人。
  let table = null;
  try {
    if (typeof currentState !== 'undefined' && currentState) {
      table = currentState['0'] || null;
    }
  } catch (e) {
    console.warn('[原著补演] 拿不到人物表，生平不写:', e);
    return 0;
  }
  if (!table || typeof table !== 'object') return 0;

  const rows = Array.isArray(table)
    ? table
    : Object.keys(table).map(function (k) {
        var r = table[k];
        if (!r || typeof r !== 'object') return null;
        if (!r['0']) {
          // id 只在键上，补进去（不改原对象，复制一份）
          var copy = {};
          for (var kk in r) { if (Object.prototype.hasOwnProperty.call(r, kk)) copy[kk] = r[kk]; }
          copy['0'] = k;
          return copy;
        }
        return r;
      }).filter(Boolean);
  let wrote = 0;

  for (const [name, text] of entries) {
    // 第 1 列是「名字|性别」，要按 | 切开再比，
    // 否则「韩立|男」永远不等于「韩立」。
    const wantName = String(name).trim();
    const row = rows.find((r) => {
      if (!r) return false;
      const raw = String(r['1'] || r.name || '').trim();
      const bare = raw.split('|')[0].replace(/<[^>]*>/g, '').trim();
      return bare === wantName;
    });
    if (!row) continue;

    const op = { command: 'set', data: { '35': String(text).trim() } };
    if (typeof mergeAppendBiographyForAdd === 'function') {
      if (!mergeAppendBiographyForAdd(op, row)) continue;
    }
    const merged = String(op.data['35'] || '').trim();
    if (!merged) continue;

    const id = String(row['0'] || row.id || '').trim();
    if (!id) continue;

    try {
      if (ceWriteCanonBiography(id, merged)) wrote += 1;
    } catch (e) {
      console.warn('[原著补演] 写生平失败:', name, e);
    }
  }
  return wrote;
}

async function ceRunCanonTurnAfterStory(ctx) {
  const options = ctx || {};
  if (typeof ceBridgeRunTurn !== 'function') return null;
  let boundary = await frCaptureCanonBoundary(options.logId);
  const targetTime = ceResolveCanonTargetTime(options);
  /* ★★★ 2026-11-03 玩家反复报的那件事的最底层原因，就在下面这一个 if。
   *
   * 【现象】局部重跑永远「本次没有可重算的内容」，一次模型调用都没有。
   * 【真因】这里是一道**幂等保护**：
   *     boundary.receipt.worldTime === targetTime && receipt.stateText === stateText
   *   → 判定「这一层已经按当前状态提交过了」→ 直接 return already_committed，
   *     整个补演流程（包括玩家勾的那些阶段）**一步都不执行**。
   *   上层拿到 landed=true、prose=[] 的正常返回，只看到「0 次调用」，
   *   于是弹出「本次没有可重算的内容」——和「真的没内容」完全无法区分。
   *
   * 【为什么两者本来就冲突】
   *   幂等保护的语义 = 「同样的输入不要重复提交第二次」（防双击、防网络重试、
   *   防并发重复提交），它保护的是**同一份输入**。
   *   局部重跑的语义 = 「我勾了这些阶段，**故意丢掉已有结果重新生成**」。
   *   玩家原话：「局部补演并不是只能补演失败的项目，而是即使成功了也要丢弃原有结果
   *   进行补演，只要玩家选择了，你能理解这个意思吗？」
   *   这正是玩家说的「两个逻辑打架，直接罢工」：一个说「已经提交过，不必再跑」，
   *   另一个说「我就是要重跑」，前者赢，后者永远跑不动。
   *
   * 【修法】只在**不是局部重跑**时保留幂等短路。
   *   options.replay 存在 = 玩家主动发起的定点重跑，必须让路。
   *   注意：这里只放宽「幂等短路」这一道，**不**放宽任何安全约束
   *   （备份、回滚、落地校验、账本提交都照旧执行）。
   *   非局部重跑（正常整轮、重启续跑、网络重试）行为完全不变。 */
  const isSelectiveReplay = options.fullTurn===true || !!(options.replay && typeof options.replay === 'object');
  if (!isSelectiveReplay &&
      boundary.receipt && boundary.receipt.worldTime === targetTime && boundary.receipt.stateText === boundary.stateText) {
    try{console.warn('[原著补演] 幂等短路：本轮已按当前状态提交过，跳过重复执行');}catch(_){}
    return { status: 'already_committed', landed: true, duplicate: true };
  }
  if (isSelectiveReplay) {
    try{console.warn('[原著补演] 局部重跑：跳过幂等短路，按玩家勾选强制重算'
      +' ｜阶段='+JSON.stringify((options.replay&&options.replay.stages)||[])
      +' ｜人物='+JSON.stringify((options.replay&&options.replay.scopes)||[])
      +' ｜changed='+String(((options.replay&&options.replay.changed)||[]).length));}catch(_){}
  }
  const pipeline=options.earlyPreparation?.earlyPipeline||(typeof frCreateCanonCharacterPipeline==='function'?frCreateCanonCharacterPipeline({...options,boundary:boundary}):null);
  if(options.earlyPreparation?.requiredBoundary)options.earlyPreparation.activePipeline=pipeline;
  let result;
  try{
    var prepared=typeof frAdoptCanonNarrativePreparation==='function'?await frAdoptCanonNarrativePreparation({...options,targetTime:targetTime,ordinarySettlement:boundary.settlementBase,onProseReady:pipeline?packet=>pipeline.enqueue(packet):null}):null;
    /* ★ 2026-11-06 修：prepared 判断只排除 null，没排除 undefined。
     * 若上游 resolve 出 undefined，undefined !== null 成立 → result 被赋成 undefined
     * → 下一行 if(!result) 直接 return null，整条补演静默失败、界面只留一个 ❌。 */
    var preparedOk=(prepared!==null&&prepared!==undefined&&typeof prepared==='object');
    if(!preparedOk&&prepared!==null&&prepared!==undefined){try{console.warn('[补演·异常] 前置准备工作返回了非对象结果，已忽略：'+String(typeof prepared));}catch(_){}}
    result=preparedOk?prepared:await ceBridgeRunTurn({
    host:typeof frGetCanonEarlyHost==='function'?await frGetCanonEarlyHost(options,ceBridgeHost(options.signal,options.traceRun)):undefined,
    deferCloseStatus: true,
    logId: options.logId || boundary.logId,
    worldTime: '', targetTime: targetTime,
    playerInput: options.userInput || '', storyText: frCanonMainStoryText(options.storyText),
    signal: options.signal || null, sharedContext: options.sharedContext || null,traceRun:options.traceRun||null,
    ordinarySettlement:boundary.settlementBase,
    awaitOrdinaryWrite:options.awaitOrdinaryWrite,floorContent:options.floorContent,archiveName:boundary.archiveName,
    savedActorCommits:boundary.actorCommits,
    replay:options.replay||null,
    onProseReady:pipeline?packet=>pipeline.enqueue(packet):null
  });}catch(error){if(pipeline)await pipeline.stop();throw error;}
  if (!result){try{console.warn('[补演·异常] ceRunCanonTurnAfterStory 拿到空结果，本轮补演无法继续（上游 ceBridgeRunTurn / 前置准备没有返回对象）');}catch(_){}if(pipeline)await pipeline.stop();return null;}
  if(preparedOk&&options.traceRun)frCanonTraceEvent(options.traceRun,'parsed','补演解析与账本计划',result);
  if (result.status !== 'ok'){if(pipeline)await pipeline.stop();return {...result,landed:false,reason:result.reason||result.landReason||('编排返回了非 ok 状态：'+String(result.status))};}
  if(result.route==='prebuilt'&&result.boundaryOnly&&result.pending){
    if(pipeline)await pipeline.stop();
    return {...result,status:'nothing_to_do',landed:false};
  }
  if(result.variableHandoff&&pipeline)return frRunCanonVariableHandoff({options,boundary,result,pipeline,targetTime});
  if(result.actorReplacement&&options.replay?.actorReplacement){
    const picked=options.replay.actorReplacement;
    if(!pipeline)throw new Error('所选人物的变量未启动，原结果保留。');
    await pipeline.finish();
    let revisedLedger;
    await db.transaction('rw',db.archives,async()=>{
      const archive=await db.archives.get(boundary.archiveName);
      const log=archive?.data?.logs?.find(row=>row.id===boundary.logId);
      if(!log||currentArchiveName!==boundary.archiveName||options.signal?.aborted)throw new Error('所选人物写回时楼层已改变。');
      const applied=Object.values(log.canonActorCommits||{});
      if(!picked.names.every(name=>applied.some(receipt=>receipt.name===name&&receipt.status==='saved'&&
        receipt.body===result.prose.find(block=>block.name===name)?.body)))throw new Error('所选人物变量未全部保存，原结果保留。');
      const replaced=new Set(picked.replacedSourceIds||[]), updated=applied.filter(receipt=>picked.names.includes(receipt.name));
      if(archive.data.state.canonLedger&&(replaced.size||updated.some(receipt=>receipt.eventSource||receipt.eventSources?.length))){
        revisedLedger=structuredClone(archive.data.state.canonLedger);
        for(const event of revisedLedger.eventProgress||[])event.nodes=(event.nodes||[]).filter(node=>{
          if(!node.contributions?.length)return true;
          node.contributions=node.contributions.filter(source=>!replaced.has(source.sourceId));
          return node.contributions.length>0;
        });
        frCanonMergeOrdinaryEventSources(revisedLedger,updated);
        frCanonRefreshPrebuiltActorDifferences(revisedLedger,archive,boundary.logId,updated.map(receipt=>receipt.actorId));
        archive.data.state.canonLedger=revisedLedger;
        archive.data.state.currentState.canonLedger=revisedLedger;
        log.stateSnapshot=JSON.stringify({...currentState,canonLedger:revisedLedger});
      }
      if(picked.oldPending)log.canonPending=structuredClone(picked.oldPending);else delete log.canonPending;
      if(log.canonTurnCommit)log.canonTurnCommit.stateText=JSON.stringify(revisedLedger?{...currentState,canonLedger:revisedLedger}:currentState);
      await db.archives.put(archive);
    });
    if(revisedLedger)currentState.canonLedger=structuredClone(revisedLedger);
    return {...result,landed:true,actorProgressSaved:true};
  }
  // 单人成功不能替整轮盖章：失败仍留在同一正文楼层继续，不转成下一轮欠账。
  const unfinished=['debts','backstoryDebts','worldDebts','unowned','unconfirmedEvents'].filter(key=>Array.isArray(result[key]) && result[key].length);
  if(unfinished.length){
    if(pipeline)await pipeline.finish();
    return {...result,status:'incomplete',landed:false,landReason:result.progressFailure||'本轮仍有未完成检查，已保存人物保留，账本未推进：'+unfinished.map(key=>({debts:'人物正文',backstoryDebts:'人物旧账',worldDebts:'世界正文',unowned:'未定位人物',unconfirmedEvents:'事件进度'})[key]).join('、')};
  }
  if(boundary.settlementBase?.partial){if(pipeline)await pipeline.finish();return {...result,status:'incomplete',landed:false,reason:'普通阶段仍有失败，本轮人物成果保留，账本等待同轮恢复'};}
  const plan = result.ledgerPlan;
  /* ★★★ 2026-11-03 排查「局部重跑 0 次调用」用的硬证据（WARN 才能进玩家日志）。
   * 三种结局必须能区分开：
   *   · status 非 ok        → 编排早早失败，看 reason
   *   · 有 unfinished         → 有人没写完（这才是「真的没产出」）
   *   · plan.changed=false    → 散文写完了但账本没推进
   * 打出来才能知道到底卡在哪一段，不再靠猜。 */
  try{
    console.warn('[原著补演·落地] status='+String(result&&result.status)
      +' landed='+String(result&&result.landed)
      +' prose='+String((result&&result.prose||[]).length)
      +' unfinished='+String((['debts','backstoryDebts','worldDebts','unowned','unconfirmedEvents']
          .filter(k=>Array.isArray(result&&result[k])&&result[k].length)).join('/')||'无')
      +' planChanged='+String(!!(plan&&plan.changed))
      +' planNext='+String(!!(plan&&plan.next))
      +' refused='+String((plan&&plan.refused)||''));
  }catch(_){}
  if (!plan || !plan.changed || !plan.next) {
    if(pipeline)await pipeline.stop();
    return {...result,landed:false,landReason:'没有有效账本提交计划：' + String(plan && plan.refused || '')};
  }
  // 变异文字整理不重做边界，也不允许模型改时间、节点或存档。纯落地重跑复用已有结果。
  if(!result.prebuiltProposal)await frPrepareCanonLedgerReview(plan,boundary,options);
  if(result.prebuiltRepair&&plan.next.mutationReview)result.prebuiltRepair.ledgerReview={status:plan.next.mutationReview,notes:plan.next.mutationNotes};
  if(options.traceRun && typeof frCanonTracePublish==='function')frCanonTracePublish(options.traceRun,'账本更新计划',{kind:'ledger',phase:'planned',worldTime:plan.next.worldTime});
  const readyCharacters=pipeline?await pipeline.finish():null;
  boundary=await frCaptureCanonBoundary(options.logId);
  let applied;
  if(result.prebuiltProposal){
    const proposal=result.prebuiltProposal;
    delete result.prebuiltProposal;
    const source={...options,boundary,blocks:result.prose,biography:result.biography,worldForMisc:result.worldForMisc,
      ledger:plan.next,timelineSource:options.traceRun?._timelineSource,
      actorReceipts:proposal.targets.map(target=>frCanonActorReceipt(boundary,target,result.prose.find(block=>block.name===target.name),result.biography))};
    try{
      if(boundary.floorContent!==proposal.floorContent)throw new Error('补演期间正文已变化，拒绝覆盖新状态');
      proposal.biographyCompression=await frPrepareCanonBiographyCompression(source,proposal);
      if(options.traceRun&&typeof frCanonTraceEvent==='function')frCanonTraceEvent(options.traceRun,'stage','保存预制结果');
      applied=await frCommitCanonProposal(source,proposal);
    }catch(error){applied={ok:false,committed:false,reason:String(error.message||error)};}
  }else applied = await ceApplyCanonProseToEvolution({
    sharedContext:options.sharedContext,config:options.config,preset:options.preset,
    prose:result.prose,proseText:result.proseText,worldForMisc:result.worldForMisc,worldNoChanges:result.worldNoChanges,canonReferences:result.canonReferences,
    signal:options.signal,boundary:boundary,ledger:plan.next,biography:result.biography || {},timelineSource:options.traceRun&&options.traceRun._timelineSource,
    preparedCharacters:readyCharacters,preparedMisc:options.earlyPreparation?.preparedMisc,trustedBoundary:options.earlyPreparation?.requiredBoundary===true,needsCommit:true
  });
  const landed = !!(applied && applied.ok && applied.committed);
  if(landed){plan.landed=true;if(applied.ledger)plan.next=applied.ledger;}
  if (!landed && typeof ceBridgePushCanonDiag === 'function') {
    ceBridgePushCanonDiag('error','补演未提交，账本未推进',String(applied && applied.reason || '没有提交凭据'));
  }
  const finalResult = {...result,landed:landed,landReason:applied && applied.reason || '',commit:applied || null};
  if(!landed&&result.prebuiltRepair)finalResult.prebuiltRepair={...result.prebuiltRepair,
    failures:[{stage:'预制成品落地',reason:finalResult.landReason||'没有提交凭据'}]};
  if (typeof ceBridgeLastResult !== 'undefined') ceBridgeLastResult = finalResult;
  if (landed && typeof ceBridgePushCanonDiag === 'function') ceBridgePushCanonDiag('info','补演变量、生平和账本已保存',boundary.logId);
  if (typeof showDanmaku === 'function') showDanmaku(landed ? '原著补演已保存' : '原著补演未提交：' + finalResult.landReason,landed ? 'success' : 'error');
  return finalResult;
}

/** 正文确认结束的世界时间 */
function ceResolveCanonTargetTime(ctx) {
  const options = ctx || {};
  if(options.earlyPreparation?.preparedBoundary?.range?.end)return String(options.earlyPreparation.preparedBoundary.range.end);
  if(options.targetTime)return String(options.targetTime);
  if(options.summary?.currentTime)return String(options.summary.currentTime);
  const adoptedTime = frCanonReadAdoptedStoryHeader(options.storyText)?.time;
  if (adoptedTime) return adoptedTime;
  const legacy = String(options.storyText || '').replace(/<ui_sys>[\s\S]*?<\/ui_sys>/gi, '');
  var body=typeof frCanonMainStoryText==='function'?frCanonMainStoryText(legacy,{includeLayout:true}):legacy;
  var header=body.match(/(?:🕒|时间\s*[:：])\s*(\d{1,6}年\s*\d{1,2}月\s*\d{1,2}日(?:\s*\d{1,2}[:：]\d{2})?)/u);
  return header?header[1].replace('：',':').trim():'';
}

/**
 * 把散文交给既有四阶段落地。
 *
 * 复用宿主现有的「原著事件包 → 四阶段」链路，不另造一套变量写入。
 * 这里只负责把散文格式化成语料，塞进既有入口。
 *
 * @returns {Promise<{ok:boolean, reason:string}>}
 */
async function ceApplyCanonProseToEvolution(input) {
  const src = input || {};
  const prose = Array.isArray(src.prose) ? src.prose : [];
  const worldText = String(src.worldForMisc || '').trim();
  if (prose.length === 0 && !worldText && !src.needsCommit) return { ok: true, reason: '没有散文或世界块可落地' };

  // 散文原文（带骨架行，四阶段能认出事件号与三态）
  const text = String(src.proseText || '').trim();
  if (!text && !worldText && !src.needsCommit) return { ok: false, reason: '散文为空' };

  try {
    // 宿主既有的散文落地入口（若存在则复用）
    if (typeof ceCommitNpcPovProseToEvolution === 'function') {
      return await ceCommitNpcPovProseToEvolution({
        boundary: src.boundary,
        ledger: src.ledger,
        biography: src.biography,
        sharedContext: src.sharedContext,
        summary: src.summary,
        config: src.config,
        preset: src.preset,
        proseText: text,
        worldForMisc: worldText,
        worldNoChanges: src.worldNoChanges,
        blocks: prose,
        canonReferences: src.canonReferences,
        preparedCharacters: src.preparedCharacters,
        timelineSource: src.timelineSource,
        signal: src.signal
      });
    }

    // 这里原来把散文写进 sharedContext.canonProseText / canonProseBlocks
    // 然后返回 ok:true。但那两个字段在整份载荷里没有任何读者，
    // 散文等于写进了黑洞，上层却以为落地成功、继续去记账。
    //
    // 现在：没有真实落地入口，就**如实报告失败**。
    // 上层拿到 ok:false 会走「散文没落地，本轮不记账」，
    // 世界时间不前进、欠账留着，下一轮还能补 —— 这是对的。
    return {
      ok: false,
      reason: '没有可用的散文落地入口（宿主 ceCommitNpcPovProseToEvolution 不存在）'
    };
  } catch (e) {
    return { ok: false, reason: String(e && e.message || e) };
  }
}

function ceAppendNativeEvolutionStageContract(prompt, preset, type, targetId, context = {}) {
  if (![1,2].includes(preset?.frPresetCompat?.nativeOutputVersion) || typeof frNativeEvolutionStageContract !== 'function') return prompt;
  // 独立版模板与别名只投影已有本地资料；最终原生命令合同仍位于末尾。
  const templates = preset.contentTemplates || {};
  for (let pass = 0; pass < 8; pass++) {
    const expanded = prompt.replace(/\{\{template:([^}]+)\}\}/g, (match, key) => {
      if (typeof templates[key] !== 'string') throw new Error('[演化提示词] 未支持的自定义模板: ' + key);
      return templates[key];
    });
    if (expanded === prompt) break;
    prompt = expanded;
  }
  const target = context.target || {};
  const values = Object.assign({}, context.values || {});
  if(context.canonItemRepair){for(const match of prompt.matchAll(/\$\{((?:original_\w+|world_timeline_context))\}/g)){if(!Object.hasOwn(values,match[1]))values[match[1]]='（本次只修末尾列出的物品缺项）';}}
  const unavailable = name => '（当前前端未提供' + name + '；禁止推断、补造或据此改写状态。）';
  const assignMissing = (key, value) => { if (!Object.prototype.hasOwnProperty.call(values, key)) values[key] = value; };
  const readItems = selected => typeof ceBuildManagedCharacterItemState === 'function' ? ceBuildManagedCharacterItemState(selected) : null;
  const stringify = (value, label) => value == null ? unavailable(label) : JSON.stringify(value, null, 2);
  if (!context.canonItemRepair && /\$\{(?:character_(?:equipment|items|gongfa)|player_equipment|owner_(?:items|gongfa))\}/.test(prompt)) {
    const items = target.id ? readItems(target) : null;
    const player = target.id === 'B1' ? items : readItems('B1');
    const gongfa = state => state ? (state.refreshTargets || []).filter(item => item.type === '功法').map(item => item.data) : null;
    assignMissing('character_equipment', stringify(items?.equipment, '该角色装备快照'));
    assignMissing('character_items', stringify(items?.inventory, '该角色库存快照'));
    assignMissing('character_gongfa', stringify(gongfa(items), '该角色已有功法物'));
    assignMissing('player_equipment', stringify(player?.equipment, '主角装备快照'));
    assignMissing('owner_items', stringify(player?.inventory, '主角已有库存快照'));
    assignMissing('owner_gongfa', stringify(gongfa(player), '主角已有功法物'));
  }
  assignMissing('currentTime', values.current_time || context.sharedContext?.currentTime || '未知');
  assignMissing('beast_id', type === 'beast' ? targetId : unavailable('灵兽ID'));
  assignMissing('is_entry_created_target', String(target.justCreated === true || !!window.pendingNewCharacterForConcurrentEvolution?.some(item => item && item.id === targetId && item.justCreated)));
  assignMissing('target_narrative_memory', target.biography?.content || unavailable('本角色已存档叙事记忆；仅可参考当前已提供快照与传记'));
  // 正文是玩家材料，不能冒充每个NPC亲历；当前普通链没有独立视角散文供应者。
  assignMissing('npc_perspective_story', unavailable('本角色本轮已确认的独立视角散文；不得将玩家正文自动视为该角色亲历或知情'));
  const unsupported = {
    identity_transition_context: '独立版身份迁移协议', target_is_explicit_minor: '独立版明确未成年判定标记（不得猜测年龄或将缺失视为成年）',
    linked_humanoid_npc_id: '兽化人形绑定ID', beast_transformation_policy: '独立版兽化绑定策略', converted_beast_mappings: '兽化绑定映射',
    cultivation_naming_rule: '独立版境界命名配置', cultivation_name_examples: '独立版境界命名示例', dead_npc_ids: '完整已死亡NPC名单（删除名单不等于死亡名单）',
    season: '独立季节状态', weather: '独立天气状态', important_item_intake_mode: '独立版重要物品接入模式'
  };
  Object.entries(unsupported).forEach(([key, label]) => assignMissing(key, unavailable(label)));
  if (!context.canonItemRepair && prompt.includes('${player_traits}')) {
    const row = typeof currentState !== 'undefined' ? currentState?.['0']?.B1 : null;
    const remarks = row && typeof ceReadItemManagementRemarks === 'function' ? ceReadItemManagementRemarks(row) : null;
    assignMissing('player_traits', stringify(remarks?.traits, '主角已有词条快照'));
  }
  prompt = replacePlaceholders(prompt, values);
  const unresolved = prompt.match(/\$\{[^}]+\}|\{\{template:[^}]+\}\}/g);
  if (unresolved) throw new Error('[演化提示词] 存在未解析材料，已阻止发送: ' + Array.from(new Set(unresolved)).join('、'));
  // 补演转换沿用自己的最终权限约束，但同样必须完成新预设模板与本地材料适配。
  const sectIncome=['npc','item_management'].includes(type) ?
    window.FrNumericRules?.expand('${numeric_rule:sect-income}') || '' : '';
  if(context.resolveOnly===true)return [prompt,sectIncome].filter(Boolean).join('\n\n');
  const terminalContract=frNativeEvolutionStageContract(type,targetId);
  // 已知适配合同会随阶段规则、共享规则和末尾保护各出现一次。
  // 只移除完整相同的自有合同，最后保留一份；剧情、用户规则和不同段落一律保留。
  prompt=prompt.split(terminalContract).join('').split(frNativeEvolutionStageContract(type,targetId,true)).join('');
  if(typeof frNativeEvolutionCommandContract==='function')prompt=prompt.split(frNativeEvolutionCommandContract()).join('').split(frNativeEvolutionCommandContract(true)).join('');
  if(typeof frEquipmentSlotContract==='function'&&typeof FrEquipmentRuntime==='object'&&['player','npc','beast','item_management'].includes(type)){
    const layoutContract=frEquipmentSlotContract(FrEquipmentRuntime.core(),type==='item_management'?'items':'personal');
    const owned='<!-- fr-equipment-layout-contract v1 -->\n'+layoutContract;
    prompt=prompt.split(owned).join('').trimEnd()+'\n\n'+owned;
  }
  const statusContract = ['player','npc','beast'].includes(type) ? CE_CORE['character-status'].CHARACTER_STATUS_RULE : '';
  const currency = type==='item_management' && !prompt.includes('【货币入账协议】') ? CE_CORE['equipment-layout']?.CURRENCY_SETTLEMENT_RULE : '';
  return [prompt.trimEnd(), statusContract, sectIncome, terminalContract,currency].filter(Boolean).join('\n\n');
}

async function buildCharacterEvolutionPrompt(target, preset, sharedContext) {
  // 确定使用哪个 prompt 配置
  const promptKey = target.type;  // player, npc, beast

  const promptConfig = preset.prompts[promptKey];
  if (!promptConfig || !promptConfig.enabled) {
    console.log(`[并发演化] ${target.name} (${target.id}): promptConfig未启用或不存在`);
    return null;
  }

  // 调试日志：路径选择诊断
  console.log(`[并发演化] 构建提示词: ${target.name} (${target.id}), type=${promptKey}`);
  console.log(`[并发演化] promptConfig.rules存在: ${Array.isArray(promptConfig.rules)}`);
  console.log(`[并发演化] promptConfig.rules长度: ${promptConfig.rules?.length || 0}`);
  console.log(`[并发演化] promptConfig.systemPrompt长度: ${promptConfig.systemPrompt?.length || 0}`);

  let prompt = '';

  // 优先使用 rules 组装（与测试角色演化一致）
  if (Array.isArray(promptConfig.rules) && promptConfig.rules.length > 0) {
    console.log(`[并发演化] ${target.name}: 走rules路径`);

    const sections = parseRulesPreset(preset, promptKey);
    const enabledMap = ceBuildEnabledMapForTarget(sections, target);

    // 调试日志：sections解析详情
    const enabledSections = sections.filter(s => enabledMap[s.id] !== false);
    console.log(`[并发演化] ${target.name}: 解析sections: ${enabledSections.length}/${sections.length} 启用`);
    console.log(`[并发演化] ${target.name}: 启用的sections: [${enabledSections.map(s => s.name || s.id).join(', ')}]`);

    prompt = mergeEnabledSections(sections, enabledMap);

    const values = buildPlaceholderValues(target, sharedContext);
    if ((target.type === 'npc' || target.type === 'beast') && prompt.includes('${npc_biography}')) {
      const npcBio = await getNpcBiographyVectorsForEvolution(target.name, sharedContext._biographyCache);
      values['npc_biography'] = npcBio || '（暂无传记）';
    }

    // 异步获取快速交谈记录 - 主角
    if (target.type === 'player' && prompt.includes('${quick_chat_all}')) {
      const chatContext = await window.getQuickChatContextForStory?.() || '';
      values['quick_chat_all'] = chatContext || '（无快速交谈记录）';
    }

    // 异步获取快速交谈记录 - NPC
    if (target.type === 'npc' && prompt.includes('${quick_chat_npc}')) {
      const chatContext = await window.buildQuickChatContextForNpcEvolution?.(target.id, target.sceneType) || '';
      values['quick_chat_npc'] = chatContext || '（无快速交谈记录）';
    }

    if (prompt.includes('${world_factors}')) {
      if (!sharedContext.worldFactors) {
        sharedContext.worldFactors = await resolveWorldFactorsContext();
      }
      values['world_factors'] = sharedContext.worldFactors || '无世界因子';
    }

    if (
      target.type === 'npc'
      && sharedContext
      && sharedContext.originalTimelinePhaseReuseEnabled === true
      && prompt.includes('${world_timeline_context}')
    ) {
      values['world_timeline_context'] = await ceBuildWorldTimelinePromptBlock({
        currentTime: sharedContext.currentTime || ''
      });
    }

    prompt = replacePlaceholders(prompt, values);

    // 兜底：即使预设未放置 ${deeds_instruction} 占位符，也强制注入列35约束/补写要求
    if (target.type === 'npc' &&
        values['deeds_instruction'] &&
        !prompt.includes('【系统已预生成本轮事迹通知】')) {
      prompt += '\n\n' + values['deeds_instruction'];
      console.log(`[并发演化] ${target.name}: 兜底注入预生成事迹约束`);
    }
    const originalTimelineBiographyInstruction = ceBuildOriginalTimelineBiographyInstructionForTarget(target, sharedContext);
    if (originalTimelineBiographyInstruction &&
        !prompt.includes('【原著补演人物阶段补写要求】')) {
      prompt += '\n\n' + originalTimelineBiographyInstruction;
      console.log(`[并发演化] ${target.name}: 注入原著补演列35补写要求`);
    }

    // 注入返场上下文（轻量add指引）
    if (values['pending_reentry_instruction']) {
      prompt += '\n\n' + values['pending_reentry_instruction'];
      console.log(`[并发演化] ${target.name}: 注入了返场上下文（轻量add指引）`);
    }

    // 注入新角色补全指引
    if (values['pending_new_character_instruction']) {
      prompt += '\n\n' + values['pending_new_character_instruction'];
      console.log(`[并发演化] ${target.name}: 注入了新角色补全指引`);
    }
    if (values['original_timeline_pending_new_characters_instruction']) {
      prompt += '\n\n' + values['original_timeline_pending_new_characters_instruction'];
      console.log(`[并发演化] ${target.name}: 注入了原著冷启动角色ID锁定指引`);
    }

    const cultivationBridgeText = ceBuildIndependentCultivationBridgeText();
    if (cultivationBridgeText && target.type !== 'player') {
      prompt += '\n\n' + cultivationBridgeText;
    }

    // 附加共享规则（兼容字符串数组和对象数组格式）
    const sharedRulesText = processSharedRules(preset.sharedRules);
    if (sharedRulesText && target.type !== 'player') {
      prompt += '\n\n' + sharedRulesText;
    }

    // 调试日志：记录prompt到window变量
    if (sharedContext?.canonProseOnly || sharedContext?.originalTimelinePhaseReuseEnabled !== true) prompt = ceAppendNativeEvolutionStageContract(prompt, preset, target.type, target.id, {target, sharedContext, values,resolveOnly:sharedContext?.canonProseOnly===true});
    console.log(`[并发演化] ${target.name}: rules路径 最终prompt长度: ${prompt.length} 字符`);
    if (window._ceDebugLogs) {
      window._ceDebugLogs.push({
        type: 'prompt',
        targetId: target.id,
        targetName: target.name,
        targetType: target.type,
        pathUsed: 'rules',
        sectionsTotal: sections.length,
        sectionsEnabled: enabledSections.length,
        enabledSectionNames: enabledSections.map(s => s.name || s.id),
        promptLength: prompt.length,
        prompt: prompt,
        timestamp: Date.now()
      });
    }

    return ['player','npc'].includes(promptKey) ? prompt + '\n\n' + frPortraitVariableRule : prompt;
  }

  // 回退：使用 systemPrompt 字符串
  if (promptConfig.systemPrompt) {
    console.log(`[并发演化] ${target.name}: 走systemPrompt路径（rules不存在或为空）`);
    prompt = promptConfig.systemPrompt;
    const presentation = typeof frVariablePresentation === 'function' && frVariablePresentation();
    if (presentation) prompt += '\n\n' + presentation.variableTextRule.content;

    const values = buildPlaceholderValues(target, sharedContext);

    // NPC/灵兽 传记（异步获取向量库）
    if ((target.type === 'npc' || target.type === 'beast') && prompt.includes('${npc_biography}')) {
      const npcBio = await getNpcBiographyVectorsForEvolution(target.name, sharedContext._biographyCache);
      values['npc_biography'] = npcBio || '（暂无传记）';
    }

    // 异步获取快速交谈记录 - 主角
    if (target.type === 'player' && prompt.includes('${quick_chat_all}')) {
      const chatContext = await window.getQuickChatContextForStory?.() || '';
      values['quick_chat_all'] = chatContext || '（无快速交谈记录）';
    }

    // 异步获取快速交谈记录 - NPC
    if (target.type === 'npc' && prompt.includes('${quick_chat_npc}')) {
      const chatContext = await window.buildQuickChatContextForNpcEvolution?.(target.id, target.sceneType) || '';
      values['quick_chat_npc'] = chatContext || '（无快速交谈记录）';
    }

    if (prompt.includes('${world_factors}')) {
      if (!sharedContext.worldFactors) {
        sharedContext.worldFactors = await resolveWorldFactorsContext();
      }
      values['world_factors'] = sharedContext.worldFactors || '无世界因子';
    }

    if (
      target.type === 'npc'
      && sharedContext
      && sharedContext.originalTimelinePhaseReuseEnabled === true
      && prompt.includes('${world_timeline_context}')
    ) {
      values['world_timeline_context'] = await ceBuildWorldTimelinePromptBlock({
        currentTime: sharedContext.currentTime || ''
      });
    }

    prompt = replacePlaceholders(prompt, values);

    // 灵兽专用：主人信息
    if (target.type === 'beast') {
      const ownerData = currentState && currentState['0'] && currentState['0']['B1'];
      const ownerInfo = ownerData ? JSON.stringify(ownerData, null, 2) : '无';
      prompt = prompt.replace(/\${owner_info}/g, ownerInfo);
    }

    // 角色ID管理：提供所有角色ID列表，避免创建新角色时ID冲突
    if (prompt.includes('${all_character_ids}')) {
      prompt = prompt.replace(/\${all_character_ids}/g, buildAllCharacterIds() || '（无角色数据）');
    }

    // 地图POI参考：注入全地图兴趣点坐标
    if (prompt.includes('${world_map_pois}')) {
      prompt = prompt.replace(/\${world_map_pois}/g, buildWorldMapPoiSummary() || '（无地图数据）');
    }
    // 当前小地图：注入当前SCENE_MAP
    if (prompt.includes('${current_scene_map}')) {
      prompt = prompt.replace(/\${current_scene_map}/g, buildCurrentSceneMapSummary() || '（无小地图数据）');
    }

    const deedsInstruction = buildDeedsInstructionForTarget(target);
    if (deedsInstruction && !prompt.includes('【系统已预生成本轮事迹通知】')) {
      prompt += '\n\n' + deedsInstruction;
      console.log(`[并发演化] ${target.name}: 兜底注入预生成事迹约束`);
    }
    const originalTimelineBiographyInstruction = ceBuildOriginalTimelineBiographyInstructionForTarget(target, sharedContext);
    if (originalTimelineBiographyInstruction && !prompt.includes('【原著补演人物阶段补写要求】')) {
      prompt += '\n\n' + originalTimelineBiographyInstruction;
      console.log(`[并发演化] ${target.name}: 注入原著补演列35补写要求`);
    }

    // 注入pending reentry返场上下文
    if (window.pendingReentryForConcurrentEvolution &&
        Array.isArray(window.pendingReentryForConcurrentEvolution)) {
      const pendingEntry = window.pendingReentryForConcurrentEvolution.find(
        e => e.id === target.id && e.justReturned
      );
      if (pendingEntry) {
        prompt += '\n\n' + buildPendingReentryInstruction(pendingEntry);
        console.log(`[并发演化] ${target.name}: 注入了返场上下文（轻量add指引）`);
      }
    }

    // 注入新角色补全指引
    if (target.canonProfileInstruction) {
      prompt += '\n\n' + target.canonProfileInstruction;
    } else if (window.pendingNewCharacterForConcurrentEvolution &&
        Array.isArray(window.pendingNewCharacterForConcurrentEvolution)) {
      const pendingEntry = window.pendingNewCharacterForConcurrentEvolution.find(
        e => e.id === target.id && e.justCreated
      );
      if (pendingEntry) {
        prompt += '\n\n' + buildNewCharacterInstruction(pendingEntry);
        console.log(`[并发演化] ${target.name}: 注入了新角色补全指引`);
      }
      if (target.type === 'original_timeline_evolution') {
        const pendingEntries = window.pendingNewCharacterForConcurrentEvolution.filter(function(e) {
          return e && e.justCreated;
        });
        if (pendingEntries.length > 0) {
          prompt += '\n\n' + buildOriginalTimelinePendingNewCharactersInstruction(pendingEntries);
          console.log(`[并发演化] ${target.name}: 注入了原著冷启动角色ID锁定指引`);
        }
      }
    }

    const cultivationBridgeText = ceBuildIndependentCultivationBridgeText();
    if (cultivationBridgeText && target.type !== 'player') {
      prompt += '\n\n' + cultivationBridgeText;
    }

    // 附加共享规则（兼容字符串数组和对象数组格式）
    const sharedRulesText = processSharedRules(preset.sharedRules);
    if (sharedRulesText && target.type !== 'player') {
      prompt += '\n\n' + sharedRulesText;
    }

    // 调试日志：记录prompt到window变量
    if (sharedContext?.canonProseOnly || sharedContext?.originalTimelinePhaseReuseEnabled !== true) prompt = ceAppendNativeEvolutionStageContract(prompt, preset, target.type, target.id, {target, sharedContext, values,resolveOnly:sharedContext?.canonProseOnly===true});
    console.log(`[并发演化] ${target.name}: systemPrompt路径 最终prompt长度: ${prompt.length} 字符`);
    if (window._ceDebugLogs) {
      window._ceDebugLogs.push({
        type: 'prompt',
        targetId: target.id,
        targetName: target.name,
        targetType: target.type,
        pathUsed: 'systemPrompt',
        sectionsTotal: 0,
        sectionsEnabled: 0,
        enabledSectionNames: [],
        promptLength: prompt.length,
        prompt: prompt,
        timestamp: Date.now()
      });
    }
  }

  return prompt && ['player','npc'].includes(promptKey) ? prompt + '\n\n' + frPortraitVariableRule : prompt || null;
}

// ===== 并发执行函数 =====

function ceResolveConcurrentEvolutionTimelineSendMode(fallback = 'brief') {
  const normalizedFallback = String(fallback || '').trim().toLowerCase();
  const safeFallback = normalizedFallback === 'original' || normalizedFallback === 'both'
    ? normalizedFallback
    : 'brief';
  try {
    const globalConfig = typeof wtPromptConfig !== 'undefined' && wtPromptConfig && typeof wtPromptConfig === 'object'
      ? wtPromptConfig
      : null;
    const rawMode = globalConfig ? globalConfig.concurrent_evolution_send_mode : '';
    if (typeof wtNormalizeConcurrentEvolutionSendMode === 'function') {
      const normalized = String(wtNormalizeConcurrentEvolutionSendMode(rawMode, safeFallback) || '').trim().toLowerCase();
      if (normalized === 'brief' || normalized === 'both' || normalized === 'original') {
        return normalized;
      }
    }
    const direct = String(rawMode || '').trim().toLowerCase();
    if (direct === 'brief' || direct === 'both' || direct === 'original') {
      return direct;
    }
  } catch (e) {}
  return safeFallback;
}

function ceResolveOriginalTimelinePacketEventDisplayMode(options = {}) {
  const explicitMode = String(options.displayMode || options.eventDisplayMode || '').trim().toLowerCase();
  if (explicitMode === 'brief' || explicitMode === 'both' || explicitMode === 'original') {
    return explicitMode;
  }
  const context = options.context && typeof options.context === 'object' ? options.context : null;
  const originalCtx = context && context.originalTimelineContext && typeof context.originalTimelineContext === 'object'
    ? context.originalTimelineContext
    : {};
  const contextMode = String(
    options.concurrentEvolutionSendMode
      || options.sendMode
      || (context && (context.originalTimelineSendMode || context.concurrentEvolutionSendMode))
      || originalCtx.concurrentEvolutionSendMode
      || ''
  ).trim().toLowerCase();
  if (contextMode === 'brief' || contextMode === 'both' || contextMode === 'original') {
    return contextMode;
  }
  const globalMode = ceResolveConcurrentEvolutionTimelineSendMode('brief');
  if (globalMode === 'brief' || globalMode === 'both' || globalMode === 'original') {
    return globalMode;
  }
  const briefRangeText = String(options.briefRangeText !== undefined ? options.briefRangeText : (originalCtx.briefRangeText || '')).trim();
  const originalRangeText = String(options.originalRangeText !== undefined ? options.originalRangeText : (originalCtx.originalRangeText || '')).trim();
  const briefItemsText = String(options.briefItemsText !== undefined ? options.briefItemsText : (originalCtx.briefItemsText || '')).trim();
  const originalItemsText = String(options.originalItemsText !== undefined ? options.originalItemsText : (originalCtx.originalItemsText || '')).trim();
  const hasBrief = !!(briefRangeText || briefItemsText);
  const hasOriginal = !!(originalRangeText || originalItemsText);
  if (hasBrief && hasOriginal) return 'both';
  if (hasOriginal) return 'original';
  return 'brief';
}

function ceBuildOriginalTimelinePacketPromptView(packet, options = {}) {
  const rows = Array.isArray(packet && packet.events) ? packet.events : [];
  const limit = Math.max(1, Number(options.limit || 6));
  const displayMode = ceResolveOriginalTimelinePacketEventDisplayMode(options);
  const eventLines = [];
  const briefRanges = [];
  const originalRanges = [];

  rows.slice(0, limit).forEach(function(item) {
    const resolved = ceResolveOriginalTimelineEventDisplayData(item);
    const title = String(resolved.title || '').trim();
    const briefText = String(resolved.brief || '').trim();
    const originalText = String(resolved.original || '').trim();
    let includeOriginal = false;
    let includeBrief = false;

    if (displayMode === 'both') {
      includeOriginal = !!originalText;
      includeBrief = !!briefText;
    } else if (displayMode === 'original') {
      includeOriginal = !!originalText;
      includeBrief = !!briefText && !includeOriginal;
    } else {
      includeBrief = !!briefText;
      includeOriginal = !includeBrief && !!originalText;
    }

    const lines = [];
    if (resolved.timeStart && resolved.timeEnd && resolved.timeStart !== resolved.timeEnd) {
      lines.push('起始时间: ' + resolved.timeStart);
      lines.push('结束时间: ' + resolved.timeEnd);
    } else {
      const singleTime = String(resolved.timeText || resolved.timeStart || resolved.timeEnd || '').trim();
      if (singleTime) lines.push('时间: ' + singleTime);
    }
    if (title) lines.push('标题: ' + title);
    if (includeBrief && briefText) lines.push('简略版: ' + briefText);
    if (includeOriginal && originalText) lines.push('原著版: ' + originalText);
    if (!lines.length && resolved.rawText) lines.push('原始条目: ' + resolved.rawText);
    if (!lines.length) return;

    eventLines.push('- ' + lines.join('\n  '));

    const itemCode = String(resolved.code || ceExtractOriginalTimelineEventDisplayCode(title || resolved.rawText || '') || '').trim();
    if (!itemCode) return;
    const itemRangeText = resolved.timeStart && resolved.timeEnd
      ? (resolved.timeStart === resolved.timeEnd ? resolved.timeStart : (resolved.timeStart + '~' + resolved.timeEnd))
      : String(resolved.timeText || resolved.timeStart || resolved.timeEnd || '').trim();
    const itemLabel = itemCode + '[' + (itemRangeText || '未知') + ']';
    if (includeBrief) briefRanges.push(itemLabel);
    if (includeOriginal) originalRanges.push(itemLabel);
  });

  return {
    displayMode,
    eventTextBlock: eventLines.join('\n'),
    briefItemsText: briefRanges.length > 0 ? Array.from(new Set(briefRanges)).join(',') : '无',
    originalItemsText: originalRanges.length > 0 ? Array.from(new Set(originalRanges)).join(',') : '无'
  };
}

function ceBuildOriginalTimelinePacketRawBlock(packet, options = {}) {
  const ctx = options.context && typeof options.context === 'object' ? options.context : {};
  const promptView = options.promptView && typeof options.promptView === 'object'
    ? options.promptView
    : ceBuildOriginalTimelinePacketPromptView(packet, options);
  const displayMode = promptView.displayMode || ceResolveOriginalTimelinePacketEventDisplayMode(options);
  const anchorTime = String(packet && packet.anchorTime || ctx.originalTimelineAnchor || ctx.currentTime || '').trim() || '未知';
  const rangeText = [
    String(packet && (packet.rangeStart || packet.anchorTime) || '').trim(),
    String(packet && packet.rangeEnd || '').trim()
  ].filter(Boolean).join(' -> ');
  const effectiveRangeText = rangeText || anchorTime;
  const sourceLabel = String(packet && packet.timelineSourceLabel || ctx.originalTimelineSourceLabel || '未标记').trim() || '未标记';
  const modeText = String(packet && packet.mode || ctx.originalTimelineMode || 'batch').trim() || 'batch';
  const sendModeLabel = displayMode === 'original'
    ? '原著版（无原著时回退简略版）'
    : (displayMode === 'both'
      ? '简略版+原著版（同时发送，互补）'
      : '简略版（默认）');
  let block = '<<<世界年表参考开始>>>\n'
    + '世界年表参考注入时间锚点: ' + anchorTime + '\n'
    + '时间锚点来源: ' + sourceLabel + '\n'
    + '注入模式: ' + modeText + '\n'
    + '变量演化发送模式: ' + sendModeLabel + '\n'
    + '简略版范围: ' + effectiveRangeText + '\n'
    + '原著版范围: ' + (displayMode === 'brief' ? '已关闭' : effectiveRangeText) + '\n'
    + '纳入条目(简略版): ' + (promptView.briefItemsText || '无') + '\n'
    + '纳入条目(原著版): ' + (promptView.originalItemsText || '无') + '\n'
    + '### 【世界年表参考】';
  if (promptView.eventTextBlock) {
    block += '\n' + promptView.eventTextBlock;
  }
  block += '\n<<<世界年表参考结束>>>';
  return block;
}

function ceFormatOriginalTimelinePacketEventsForPrompt(packet, options = {}) {
  const promptView = ceBuildOriginalTimelinePacketPromptView(packet, options);
  return promptView.eventTextBlock || '（无事件）';
}

function ceBuildOriginalTimelineBatchReplayHistoryText(history, options = {}) {
  const rows = Array.isArray(history) ? history : [];
  if (!rows.length) return '（当前为首组，无前序补演结果）';
  const limit = Math.max(1, Number(options.limit || 4));
  return rows.slice(-limit).map(item => {
    const label = item && item.batchLabel ? item.batchLabel : '前序分组';
    const eventCodeText = Array.isArray(item && item.eventCodes) && item.eventCodes.length
      ? (' | 事件: ' + item.eventCodes.join('、'))
      : '';
    const deltaText = ' | 变更: ' + Number(item && item.deltaCount || 0) + '条';
    const statusText = item && item.skipped
      ? ' | 结果: 跳过'
      : (item && item.success === false ? ' | 结果: 失败' : ' | 结果: 已处理');
    return '- ' + label + statusText + deltaText + eventCodeText;
  }).join('\n');
}

function ceShouldUseOriginalTimelineBatchReplay(sharedContext, target = null) {
  const ctx = sharedContext || {};
  const packet = ctx.originalTimelinePacket || null;
  const groups = Array.isArray(ctx.originalTimelinePackets) ? ctx.originalTimelinePackets : [];
  if (!packet || groups.length <= 1) return false;
  if (target) return false;
  if (packet.stepReplay) {
    return true;
  }
  return packet.mode === 'batch'
    || packet.source === 'skip_time'
    || packet.source === 'retreat'
    || packet.source === 'manual_replay';
}

function ceBuildOriginalTimelineBatchReplayInstruction(sharedContext) {
  const ctx = sharedContext || {};
  const currentPacket = ctx.originalTimelinePacket || null;
  const packetGroups = Array.isArray(ctx.originalTimelinePackets) ? ctx.originalTimelinePackets : [];
  if (!currentPacket || packetGroups.length <= 1) return '';
  const basePacket = ctx.originalTimelineBasePacket || currentPacket;
  const isStepReplay = !!currentPacket.stepReplay;
  const totalGroups = currentPacket.batchTotal || packetGroups.length;
  const currentLabel = currentPacket.batchLabel || ('第' + (currentPacket.batchIndex || 1) + (isStepReplay ? '步' : '组'));
  const previousText = ceBuildOriginalTimelineBatchReplayHistoryText(ctx.originalTimelineBatchReplayHistory, { limit: 4 });
  const currentEventText = ceFormatOriginalTimelinePacketEventsForPrompt(currentPacket, { limit: 6, context: ctx });
  const rangeText = [basePacket.rangeStart || basePacket.anchorTime || '', basePacket.rangeEnd || ''].filter(Boolean).join(' → ');
  return [
    '---',
    isStepReplay ? '# 【原著事件逐步补演模式】' : '# 【原著事件批量补演模式】',
    isStepReplay ? '当前处于常规推进下的原著逐步补演流程。' : '当前处于闭关/跳时/时间快进的分组补演流程。',
    (isStepReplay ? '总步数: ' : '总分组数: ') + totalGroups,
    (isStepReplay ? '当前步骤: ' : '当前分组: ') + currentLabel,
    rangeText ? ((isStepReplay ? '当前时间区间: ' : '总时间区间: ') + rangeText) : '',
    isStepReplay ? '前序步骤结果:' : '前序分组结果:',
    previousText,
    isStepReplay ? '当前步骤事件:' : '当前分组事件:',
    currentEventText,
    isStepReplay
      ? '执行要求：只推进当前步骤对应的原著事件；若前序步骤已造成变化，必须在其基础上继续推进，不得把后续步骤一次性提前结算。'
      : '执行要求：仅结算当前分组事件；若前序分组已造成变化，必须在其基础上继续推进，不得重复结算前序分组。',
    '---'
  ].filter(Boolean).join('\n');
}

function ceBuildOriginalTimelineGroupSharedContext(sharedContext, groupPacket, options = {}) {
  const baseCtx = sharedContext || {};
  const packet = groupPacket && typeof groupPacket === 'object' ? Object.assign({}, groupPacket) : null;
  if (!packet) return Object.assign({}, baseCtx);

  const packetGroups = Array.isArray(options.packetGroups) && options.packetGroups.length > 0
    ? options.packetGroups.map(item => Object.assign({}, item))
    : (Array.isArray(baseCtx.originalTimelinePackets)
      ? baseCtx.originalTimelinePackets.map(item => Object.assign({}, item))
      : [Object.assign({}, packet)]);
  const basePacket = baseCtx.originalTimelineBasePacket || baseCtx.originalTimelinePacket || packet;
  const groupLabel = packet.batchLabel || ('第' + (packet.batchIndex || 1) + '组');
  const groupRangeText = [packet.rangeStart || packet.anchorTime || '', packet.rangeEnd || ''].filter(Boolean).join(' → ');
  const eventCodeText = Array.isArray(packet.eventCodes) && packet.eventCodes.length ? packet.eventCodes.join('、') : '';
  const promptView = ceBuildOriginalTimelinePacketPromptView(packet, { limit: 8, context: baseCtx });
  const eventTextBlock = promptView.eventTextBlock || '';
  const groupRawBlock = ceBuildOriginalTimelinePacketRawBlock(packet, {
    context: baseCtx,
    promptView: promptView
  });
  const eventDigest = [
    baseCtx.originalTimelineDigest || '',
    '批量补演分组: ' + groupLabel + ' / 共' + (packet.batchTotal || packetGroups.length || 1) + '组',
    groupRangeText ? ('当前分组范围: ' + groupRangeText) : '',
    eventCodeText ? ('当前分组事件编码: ' + eventCodeText) : '',
    '当前分组事件:\n' + (eventTextBlock || '（无事件）')
  ].filter(Boolean).join('\n');

  const originalCtx = Object.assign({}, baseCtx.originalTimelineContext || {}, {
    rawBlock: groupRawBlock,
    eventTextBlock,
    eventDigest,
    rangeText: groupRangeText || baseCtx.originalTimelineRange || '',
    modeText: packet.mode || baseCtx.originalTimelineMode || '',
    anchorTime: packet.anchorTime || baseCtx.originalTimelineAnchor || '',
    sourceLabel: packet.timelineSourceLabel || baseCtx.originalTimelineSourceLabel || '',
    briefRangeText: groupRangeText || baseCtx.originalTimelineRange || '',
    originalRangeText: promptView.displayMode === 'brief' ? '已关闭' : (groupRangeText || baseCtx.originalTimelineRange || ''),
    briefItemsText: promptView.briefItemsText || '无',
    originalItemsText: promptView.originalItemsText || '无',
    itemText: (promptView.originalItemsText && promptView.originalItemsText !== '无')
      ? promptView.originalItemsText
      : (promptView.briefItemsText || '无'),
    concurrentEvolutionSendMode: promptView.displayMode,
    auditSeed: [baseCtx.originalTimelineAudit || '', groupLabel, eventCodeText].filter(Boolean).join(' | '),
    hasTimeline: Array.isArray(packet.events) && packet.events.length > 0
  });

  const ctx = Object.assign({}, baseCtx, {
    worldTimelineContext: groupRawBlock,
    originalTimelineSendMode: promptView.displayMode,
    originalTimelineContext: originalCtx,
    originalTimelineRawBlock: groupRawBlock,
    originalTimelineEvents: eventTextBlock,
    originalTimelineDigest: eventDigest,
    originalTimelineRange: groupRangeText || baseCtx.originalTimelineRange || '',
    originalTimelineMode: packet.mode || baseCtx.originalTimelineMode || '',
    originalTimelineAnchor: packet.anchorTime || baseCtx.originalTimelineAnchor || '',
    originalTimelineSourceLabel: packet.timelineSourceLabel || baseCtx.originalTimelineSourceLabel || '',
    originalTimelineAudit: originalCtx.auditSeed || baseCtx.originalTimelineAudit || '',
    originalTimelineEventTags: packet.entityCandidates && Array.isArray(packet.entityCandidates.eventTags)
      ? packet.entityCandidates.eventTags.slice()
      : (Array.isArray(baseCtx.originalTimelineEventTags) ? baseCtx.originalTimelineEventTags.slice() : []),
    originalTimelineTriggerSource: packet.source || baseCtx.originalTimelineTriggerSource || '',
    originalTimelinePacket: packet,
    originalTimelinePackets: packetGroups,
    originalTimelineBasePacket: basePacket ? Object.assign({}, basePacket) : null,
    originalTimelineBatchReplayHistory: Array.isArray(options.replayHistory) ? options.replayHistory.slice() : [],
    originalTimelineBatchReplayInstruction: '',
    originalTimelineReferenceCandidates: null,
    originalTimelineCharacterCandidates: null,
    originalReferenceVectorResults: null,
    originalCharacterVectors: '',
    originalItemVectors: '',
    originalTechniqueVectors: '',
    originalFactionVectors: '',
    originalLocationVectors: '',
    originalBeastVectors: '',
    originalReferenceVectors: '',
    originalEventAudit: '',
    originalEventLedgerState: '',
    originalTimelineLedgerSummary: ''
  });
  ctx.originalTimelineBatchReplayInstruction = ceBuildOriginalTimelineBatchReplayInstruction(ctx);
  if (ctx.originalTimelineNpcArchiveIndex && Array.isArray(ctx.originalTimelineNpcArchiveIndex.records)) {
    ceApplyOriginalTimelineNpcRoutingState(ctx, ctx.originalTimelineNpcArchiveIndex, {
      errorMessage: '[原著年表] 分组上下文人物分流刷新失败:'
    });
  }
  return ctx;
}

function ceIsOriginalTimelineWorldEntityId(id) {
  const normalizedId = String(id || '').trim();
  if (!normalizedId) return false;
  return /^M\d+/i.test(normalizedId);
}

// 新登场人物不能把“合法空指令”当成“已补齐”。仅预演自己的候选指令，
// 不修改当前状态；既有人物的合法无变化仍照常接受。
function frGetNewEntryNpcProfileGaps(target, delta) {
  if (!target || target.type !== 'npc') return [];
  const id = String(target.id || '');
  const isNew = target.justCreated === true || (Array.isArray(window.pendingNewCharacterForConcurrentEvolution)
    && window.pendingNewCharacterForConcurrentEvolution.some(item => item && item.id === id && item.justCreated));
  if (!isNew) return [];
  const row = structuredClone(target.data || currentState?.['0']?.[id] || {});
  try {
    for (const op of (Array.isArray(delta) ? delta : [])) {
      if (String(op?.id || op?.data?.['0'] || '') === id) applyConcurrentEvolutionBioChanges(row, op);
    }
  } catch (error) { return ['人物候选指令预演失败：' + String(error?.message || error)]; }
  const gaps = [];
  if (!String(row['1'] || '').trim()) gaps.push('姓名缺失');
  if (!String(row['2'] || '').trim()) gaps.push('境界与身份缺失');
  const remarks = frReadBondedRemarks(row['9']);
  for (const key of ['年龄', '寿元']) {
    const value = remarks[key];
    const valid = typeof value === 'number' ? Number.isFinite(value) && value >= 0
      : typeof value === 'string' && /[\d一二三四五六七八九十百千]/.test(value);
    if (!valid || (key === '寿元' && Number(value) === 0 && !/死亡|陨落|身死/.test(String(row['4'] || '')))) gaps.push(key + '缺失或无效');
  }
  if (frReadBondedFlag(remarks.isBonded) === null) gaps.push('isBonded缺失');
  const attributes = parseNestedJsonString(row['11'], {});
  for (const key of ['血量','法力','物攻','物防','法攻','法防','神识','物理穿透','法术穿透','气运','魅力','脚力','修炼速度']) {
    const value = attributes?.[key];
    if (!value || !Number.isFinite(value.current) || !Number.isFinite(value.max) || value.current < 0 || value.max < value.current) gaps.push(key + '属性缺失或无效');
  }
  return gaps;
}

async function executeConcurrentRequests({
  targets,
  preset,
  config,
  sharedContext,
  signal,
  onProgress,
  onResult
}) {
  if(sharedContext && sharedContext.canonProseOnly && !sharedContext.precomputedCharacterResponses && typeof frExecuteCanonCharacterBatch==='function')return frExecuteCanonCharacterBatch({targets,preset,config,sharedContext,signal});
  const fallbackPreset = preset;
  const results = [];
  const queue = [...targets];
  const inProgress = new Map();
  let completed = 0;

  const executeOne = async (target, apiOverride = null, requestContext = sharedContext, batchOptions = null, retryOptions = null) => {
    if(signal&&signal.aborted)return {target,success:false,error:'cancelled'};
    const effectiveContext = requestContext || sharedContext;
    const targetId = String(target && target.id || '').trim();
    const precomputed = effectiveContext && effectiveContext.precomputedCharacterResponses;
    if (precomputed && Object.prototype.hasOwnProperty.call(precomputed, targetId)) {
      const response = precomputed[targetId];
      const store = typeof response === 'string' && response.match(/^<upstore>([\s\S]*)<\/upstore>$/);
      if (!store) return { target, success: false, error: '合并人物响应格式无效' };
      const parsed = parseConcurrentEvolutionCommands(store[1]);
      const gaps = parsed.errorMessages.length || effectiveContext.canonProseOnly ? [] : frGetNewEntryNpcProfileGaps(target, parsed.delta);
      if (gaps.length) {
        // 日常合并的质量补正已在整包预检中完成。这里是最后防线，不能暗中拆成逐人请求。
        return { target, success: false, error: '合并演化人物资料未完整：' + gaps.join('；'), profileGaps: gaps };
      }
      return { target, response, success: !parsed.errorMessages.length, delta: parsed.delta,
        commandsString: store[1], emptyUpstore: !store[1].trim(),
        parseErrors: parsed.errorMessages.length ? parsed.errorMessages : null, thinkingContent: effectiveContext.mergedThinking || '' };
    }
    if (precomputed && !(config.mergedIndependentTargetIds || []).includes(targetId)) {
      return { target, success: false, error: '合并演化缺少此人物结果，未自动改为单独演化' };
    }
    const isOriginalTimelineReplayTarget = !!(
      effectiveContext
      && effectiveContext.originalTimelinePhaseReuseEnabled === true
      && String(target && target.type || '').trim() === 'npc'
      && targetId
    );
    const getOriginalTimelineCurrentRow = function() {
      if (target && target.data && typeof target.data === 'object' && !Array.isArray(target.data)) {
        return target.data;
      }
      if (currentState && currentState['0'] && currentState['0'][targetId] && typeof currentState['0'][targetId] === 'object') {
        return currentState['0'][targetId];
      }
      return null;
    };
    const buildOriginalTimelineFillDetailForRow = function(row) {
      if (!isOriginalTimelineReplayTarget || typeof ceGetOriginalTimelineColdStartRowCompletionDetail !== 'function') return null;
      const completionDetail = ceGetOriginalTimelineColdStartRowCompletionDetail(row);
      if (!completionDetail || completionDetail.needsModelFill !== true) return null;
      return {
        summaryText: String(completionDetail.summaryText || '').trim(),
        missingNotes: Array.isArray(completionDetail.missingNotes) ? completionDetail.missingNotes.slice() : [],
        missingColumns: Array.isArray(completionDetail.missingColumns) ? completionDetail.missingColumns.slice() : []
      };
    };
    const buildOriginalTimelinePostDeltaState = function(deltaList) {
      const fallbackRow = getOriginalTimelineCurrentRow();
      const fallbackDetail = buildOriginalTimelineFillDetailForRow(fallbackRow);
      if (!isOriginalTimelineReplayTarget || typeof ceBuildOriginalTimelinePostCharacterPreviewTargets !== 'function') {
        return { nextTargets: null, nextRow: fallbackRow, detail: fallbackDetail };
      }
      const baseTargets = Array.isArray(effectiveContext.originalTimelinePreviewTargets)
        ? effectiveContext.originalTimelinePreviewTargets
        : (Array.isArray(effectiveContext.evolutionTargets) ? effectiveContext.evolutionTargets : []);
      if (baseTargets.length === 0) {
        return { nextTargets: null, nextRow: fallbackRow, detail: fallbackDetail };
      }
      const filteredDelta = (Array.isArray(deltaList) ? deltaList : []).filter(function(op) {
        return String(resolveConcurrentEvolutionOpId(op) || '').trim() === targetId;
      });
      const nextTargets = ceBuildOriginalTimelinePostCharacterPreviewTargets(baseTargets, filteredDelta);
      const nextTarget = (Array.isArray(nextTargets) ? nextTargets : []).find(function(item) {
        return String(item && item.id || '').trim() === targetId;
      }) || null;
      const nextRow = nextTarget && nextTarget.data && typeof nextTarget.data === 'object'
        ? nextTarget.data
        : fallbackRow;
      return {
        nextTargets: Array.isArray(nextTargets) ? nextTargets : null,
        nextRow,
        detail: buildOriginalTimelineFillDetailForRow(nextRow)
      };
    };
    const getOriginalTimelineFillRetryLimit = function() {
      if (!isOriginalTimelineReplayTarget) return 0;
      const explicit = Number(config.originalTimelineFillRetryCount);
      if (Number.isFinite(explicit)) return Math.max(0, Math.floor(explicit));
      const fallback = Number(config.parseRetryCount);
      if (Number.isFinite(fallback)) return Math.max(0, Math.floor(fallback));
      return 1;
    };
    if (!(batchOptions && batchOptions.disableBatchReplay) && ceShouldUseOriginalTimelineBatchReplay(effectiveContext, target)) {
      const packetGroups = Array.isArray(effectiveContext.originalTimelinePackets) ? effectiveContext.originalTimelinePackets : [];
      const replayHistory = [];
      const batchResults = [];
      const combinedDelta = [];
      const responseParts = [];
      const commandParts = [];
      const thinkingParts = [];
      for (let i = 0; i < packetGroups.length; i++) {
        if (signal && signal.aborted) {
          return { target, success: false, error: 'cancelled' };
        }
        const groupPacket = packetGroups[i];
        if (!groupPacket || typeof groupPacket !== 'object') continue;

        target.retryCount = 0;
        target.parseRetryCount = 0;
        const groupContext = ceBuildOriginalTimelineGroupSharedContext(effectiveContext, groupPacket, {
          packetGroups,
          replayHistory
        });
        const groupResult = await executeOne(target, apiOverride, groupContext, {
          ...batchOptions,disableBatchReplay: true
        });
        const batchLabel = groupPacket.batchLabel || ('第' + (i + 1) + '组');
        const groupDelta = Array.isArray(groupResult && groupResult.delta) ? groupResult.delta : [];

        batchResults.push({
          batchIndex: groupPacket.batchIndex || (i + 1),
          batchLabel,
          eventCodes: Array.isArray(groupPacket.eventCodes) ? groupPacket.eventCodes.slice() : [],
          success: !!(groupResult && groupResult.success),
          skipped: !!(groupResult && groupResult.skipped),
          error: groupResult && groupResult.error ? String(groupResult.error) : '',
          deltaCount: groupDelta.length
        });

        if (groupResult && groupResult.response) {
          responseParts.push('===== ' + batchLabel + ' =====\n' + groupResult.response);
        }
        if (groupResult && groupResult.commandsString) {
          commandParts.push('[' + batchLabel + ']\n' + groupResult.commandsString);
        }
        if (groupResult && groupResult.thinkingContent) {
          thinkingParts.push('[' + batchLabel + ']\n' + groupResult.thinkingContent);
        }

        replayHistory.push({
          batchIndex: groupPacket.batchIndex || (i + 1),
          batchLabel,
          eventCodes: Array.isArray(groupPacket.eventCodes) ? groupPacket.eventCodes.slice() : [],
          deltaCount: groupDelta.length,
          commandsString: groupResult && groupResult.commandsString ? String(groupResult.commandsString) : '',
          skipped: !!(groupResult && groupResult.skipped),
          success: !!(groupResult && groupResult.success)
        });

        if (groupResult && groupResult.parseErrors) {
          const parseErrors = groupResult.parseErrors.map(err => Object.assign({}, err, {
            title: batchLabel + ' / ' + (err && err.title ? err.title : '解析失败')
          }));
          return {
            target,
            success: false,
            response: responseParts.join('\n\n'),
            parseErrors,
            thinkingContent: thinkingParts.join('\n\n'),
            commandsString: commandParts.join('\n\n'),
            batchResults
          };
        }
        if (groupResult && !groupResult.success && !groupResult.skipped) {
          return {
            target,
            success: false,
            error: batchLabel + ': ' + (groupResult.error || '请求失败'),
            response: responseParts.join('\n\n'),
            thinkingContent: thinkingParts.join('\n\n'),
            commandsString: commandParts.join('\n\n'),
            batchResults
          };
        }
        if (groupDelta.length > 0) {
          combinedDelta.push(...groupDelta);
        }
      }

      const combinedResponse = responseParts.join('\n\n');
      const combinedCommands = commandParts.join('\n\n');
      const combinedThinking = thinkingParts.join('\n\n');
      if (combinedDelta.length === 0) {
        return {
          target,
          success: true,
          response: combinedResponse,
          emptyUpstore: true,
          thinkingContent: combinedThinking,
          commandsString: combinedCommands,
          batchResults
        };
      }
      return {
        target,
        success: true,
        response: combinedResponse,
        delta: combinedDelta,
        commandsString: combinedCommands,
        thinkingContent: combinedThinking,
        batchResults
      };
    }

    const controller = new AbortController();
    // 标记超时abort，区分用户手动abort
    if(typeof frCanonTraceLinkSignal==='function')frCanonTraceLinkSignal(signal,controller.signal,{stageKey:'characters',subject:target.name||target.id,targetId:target.id,targetIds:[target.id]});
    const timeoutMs=config.requestTimeout;
    const timeoutId = typeof frAiQueueTimeout==='function'?frAiQueueTimeout(controller,timeoutMs,function(){controller._isTimeoutAbort=true;controller.abort();}):setTimeout(() => {
      controller._isTimeoutAbort = true;
      controller.abort();
    }, timeoutMs);

    // 链接外部取消信号（用户手动取消不设标记）
    if (signal) {
      if(signal.aborted)controller.abort();else signal.addEventListener('abort', () => controller.abort(),{once:true});
    }

    const _eoApiUrl   = (apiOverride && apiOverride.apiUrl)   ? apiOverride.apiUrl   : config.apiUrl;
    const _eoApiKey   = (apiOverride && apiOverride.apiKey)   ? apiOverride.apiKey   : config.apiKey;
    const _eoApiModel = (apiOverride && apiOverride.apiModel) ? apiOverride.apiModel : config.apiModel;

    try {
      const preset = await ceResolveEvolutionRoutePreset(apiOverride, fallbackPreset, config);
      const prompt = await buildCharacterEvolutionPrompt(target, preset, effectiveContext);
      if (!prompt) {
        return { target, success: false, error: 'Prompt构建失败或该类型未启用', skipped: true };
      }

      const isPlayerTarget = String(target && target.type || '').trim() === 'player';
      const dsWire = typeof frUsesDeepSeekEvolutionWire === 'function' && frUsesDeepSeekEvolutionWire(preset);
      const canonCompletion = effectiveContext?.canonCompletionContext;
      const ownReview = canonCompletion?.byTargetId?.[target.id];
      const completionTools = effectiveContext?.canonProseOnly === true && ownReview?.review &&
        typeof frCanonCompletionTools === 'function' ? frCanonCompletionTools() : null;
      const completionPrompt = completionTools?.prompt({...canonCompletion,byTargetId:{[target.id]:ownReview}},'characters') || '';
      const withCompletion = dsWire && !!completionPrompt;
      // B1 / 玩家始终走普通人物演化链，不参与原著补演复用阶段；为提高协议输出稳定性，玩家请求固定补齐 thinking prefill。
      const commandRepair=retryOptions?.commandRepair;
      const shouldUseThinkingPrefill = !commandRepair && !dsWire && (isPlayerTarget || !!(
        effectiveContext
        && effectiveContext.originalTimelinePhaseReuseEnabled === true
        && effectiveContext.originalTimelineThinkingEnabled !== false
      ));
      // 重试时可以追加一条纠正指令（见上面缺 <upstore> 的分支）。
      // 只在末尾追加，不替换原提示词，避免影响首次请求的正常内容。
      const correctionNote = retryOptions && retryOptions.correctionNote ? String(retryOptions.correctionNote) : '';
      const retryPrompt = prompt + completionPrompt + (correctionNote ? '\n\n' + correctionNote : '');
      const effectivePrompt = commandRepair ? FrMergedEvolution.commandRepairPrompt(commandRepair.issues) :
        dsWire ? frEvolutionWirePrompt(retryPrompt,preset,withCompletion) : retryPrompt;
      const messages = shouldUseThinkingPrefill
        ? [
            { role: 'user', content: effectivePrompt },
            { role: 'assistant', content: FOCUSED_EVOLUTION_THINKING_PREFILL }
          ]
        : [
            { role: 'user', content: effectivePrompt }
          ];

      console.log(`[并发演化] 开始请求: ${target.name} (${target.id})`);

      let response = await genericApiCall(
        _eoApiUrl,
        _eoApiKey,
        _eoApiModel,
        messages,
        controller.signal,{route:apiOverride,purpose:dsWire?'json':undefined,hasNextRoute:batchOptions?.hasNextRoute}
      );

      if(timeoutId && typeof timeoutId.cancel==='function')timeoutId.cancel();else clearTimeout(timeoutId);
      if(signal?.aborted||controller.signal.aborted){var cancelled=new Error('cancelled');cancelled.name='AbortError';throw cancelled;}
      console.log(`[并发演化] 请求完成: ${target.name} (${target.id})`);
      console.log(`[并发演化] ${target.name} 提示词:`, prompt);

      // 拼接 prefill 到响应前面，还原完整 <thinking> 标签
      if (shouldUseThinkingPrefill && response && typeof response === 'string') {
        response = FOCUSED_EVOLUTION_THINKING_PREFILL + response;
      }
      ceThrowIfApiFailureText(response, `并发演化/${target.name}`);
      if(commandRepair){
        try{
          const repaired=FrMergedEvolution.repairCommands(commandRepair.commands,commandRepair.issues,response);
          response=commandRepair.wrap(repaired);
        }catch(error){
          const used=target.parseRetryCount||0;
          if(used<commandRepair.limit){
            target.parseRetryCount=used+1;
            await new Promise(r=>setTimeout(r,config.retryDelay||1000));
            return executeOne(target,apiOverride,effectiveContext,batchOptions,retryOptions);
          }
          return {target,success:false,response,parseErrors:[{title:'局部指令补缺失败',details:error.message}]};
        }
      }

      console.log(`[并发演化] ${target.name} API返回:`, response);

      // 调试日志：记录response到对应的prompt条目
      if (window._ceDebugLogs) {
        const logEntry = window._ceDebugLogs.find(l => l.targetId === target.id && l.type === 'prompt');
        if (logEntry) {
          logEntry.response = response;
          logEntry.responseLength = response?.length || 0;
          logEntry.responseTimestamp = Date.now();
        }
      }

      // === 新增：在 executeOne 中解析指令，解析失败时重新请求 API ===
      // 提取thinking内容
      const wire = dsWire ? frEvolutionWireReply(response,preset,withCompletion) : null;
      if (wire && !wire.error) response = wire.text;
      const thinkingContent = ceExtractThinkingContent(response);
      const dsEnvelope = dsWire && !wire.error ? ceExtractUpstoreEnvelope(withCompletion ? completionTools.strip(response) : response) : null;
      const storeMatch = dsWire ? (dsEnvelope && !dsEnvelope.error ? [response,dsEnvelope.commandsString] : null) :
        response.match(/<upstore>([\s\S]*?)<\/upstore>/);
      if (!storeMatch) {
        const formatError = dsWire ? wire.error || dsEnvelope?.error : '响应缺少 <upstore>';
        const noUpstoreRetryCount = target.parseRetryCount || 0;
        const maxNoUpstoreRetry = Number.isFinite(Number(config.parseRetryCount)) ? Math.max(0, Math.min(10, Math.floor(Number(config.parseRetryCount)))) : 2;

        if (noUpstoreRetryCount < maxNoUpstoreRetry) {
          target.parseRetryCount = noUpstoreRetryCount + 1;
          const retryMsg = `${target.name} ${formatError}，重试 (${target.parseRetryCount}/${maxNoUpstoreRetry})`;
          console.warn(`[并发演化] ${target.name} 响应缺少 <upstore>，重新请求API (${target.parseRetryCount}/${maxNoUpstoreRetry})`);
          if (typeof showDanmaku === 'function') {
            showDanmaku(retryMsg, 'warning');
          }
          await new Promise(r => setTimeout(r, config.retryDelay || 1000));
          /* 2026-11-02 玩家：「已建档的原著人物，在本轮进入变量演化后台活跃人物
           *                    演化的时候总出错」——截图是「模型未按协议输出 <upstore>」。
           *
           * 根因：原来的重试是把**同一个提示词原样再发一遍**。
           * 若提示词本身有冲突（比如某处要求「必须输出完整思维链，否则响应无效」，
           * 另一处又要求「只输出 <upstore>，不输出推理」），模型每次都只吐 thinking，
           * 重试 N 次结果必然一样，最后只能判失败。
           *
           * 修法：重试时在末尾追加一条**纠正指令**，明确告知上一轮缺了什么、
           * 这次必须怎么输出。方向对了一次就过，不再原样撞墙。
           *
           * 注意：只在重试时追加，首次请求不动，避免影响正常的提示词。
           */
          return executeOne(target, apiOverride, effectiveContext, batchOptions, {
            correctionNote: dsWire ? '【上一轮输出不合规】'+formatError+'。按下方 DS JSON 格式重写。' :
              '【上一轮输出不合规】你没有输出 <upstore> 指令块。'
              + '本轮必须输出一个 <upstore>…</upstore>；没有变化也要输出空块 <upstore></upstore>。'
              + '思考内容若有请放在 <upstore> 之前，但**不能只有思考没有 <upstore>**。'
              + '这是最后一条硬要求。'
          });
        }

        console.error(`[并发演化] ${target.name} 响应缺少 <upstore>，已达最大重试次数`);
        return {
          target,
          success: false,
          response,
          noUpstore: true,
          protocolFailure: 'missing_upstore',
          parseErrors: [{ title: '模型未按变量协议返回', details: formatError }],
          thinkingContent
        };
      }

      const commandsString = storeMatch[1].trim();
      if (!commandsString) {
        const gaps = frGetNewEntryNpcProfileGaps(target, []);
        if (gaps.length) return { target, success: false, response, profileGaps: gaps, error: '新登场人物未补齐：' + gaps.join('；'), thinkingContent };
        const emptyUpstoreFillState = buildOriginalTimelinePostDeltaState([]);
        const emptyUpstoreBiographyValidation = isOriginalTimelineReplayTarget && typeof ceValidateOriginalTimelineReplayBiographyDelta === 'function'
          ? ceValidateOriginalTimelineReplayBiographyDelta(target, [])
          : { ok: true, detail: null };
        const emptyUpstoreRetryDetail = typeof ceMergeOriginalTimelineRetryDetail === 'function'
          ? ceMergeOriginalTimelineRetryDetail(emptyUpstoreFillState.detail, emptyUpstoreBiographyValidation.detail)
          : (emptyUpstoreFillState.detail || emptyUpstoreBiographyValidation.detail || null);
        // 空 upstore，不需要重试
        return { target, success: true, response, emptyUpstore: true, thinkingContent };
      }

      // 解析指令
      const { delta, errorMessages } = parseConcurrentEvolutionCommands(commandsString);

      // 如果解析失败且有重试次数，重新发起 API 请求
      if (errorMessages.length > 0) {
        const parseRetryCount = target.parseRetryCount || 0;
        const maxParseRetry = Number.isFinite(Number(config.parseRetryCount)) ? Math.max(0, Math.min(10, Math.floor(Number(config.parseRetryCount)))) : 2;

        if (parseRetryCount < maxParseRetry) {
          target.parseRetryCount = parseRetryCount + 1;
          const parseRetryMsg = `${target.name} 解析失败，重试 (${target.parseRetryCount}/${maxParseRetry})`;
          console.warn(`[并发演化] ${target.name} 指令解析失败，重新请求API (${target.parseRetryCount}/${maxParseRetry})`, errorMessages);
          if (typeof showDanmaku === 'function') {
            showDanmaku(parseRetryMsg, 'warning');
          }
          await new Promise(r => setTimeout(r, config.retryDelay || 1000));
          const local=typeof FrMergedEvolution!=='undefined'&&FrMergedEvolution.characterCommandRepair(
            commandsString,targetId,parseConcurrentEvolutionCommands,resolveConcurrentEvolutionOpId);
          if(local)return executeOne(target,apiOverride,effectiveContext,batchOptions,{commandRepair:{...local,
            limit:maxParseRetry,wrap:repaired=>response.replace(/<upstore>[\s\S]*?<\/upstore>/,()=>'<upstore>'+repaired.join('\n')+'</upstore>')}});
          // 同样追加纠正指令：告诉模型上一轮的哪几条指令没解析通过，这次按格式重写。
          // 原样重发会得到同样结果，等于白重试。
          var parseErrText = errorMessages.map(function (m) { return String((m && (m.detail || m.title)) || m || '').trim(); }).filter(Boolean).join('；');
          return executeOne(target, apiOverride, effectiveContext, batchOptions, {
            correctionNote: '【上一轮指令解析失败】' + (parseErrText ? ('问题：' + parseErrText + '。') : '')
              + (dsWire ? '本轮按 DS 最终格式重写 commands 列表，只写白名单内且参数合法的原生指令；无操作时用空数组。' :
                '本轮必须重新输出一个 <upstore>…</upstore> 指令块，每条指令写成 函数名(一个JSON对象)，只含合法指令；参数不合法、函数名不在白名单、JSON格式错误的都不要写。没有合法指令就输出空块 <upstore></upstore>。')
          });
        }

        // 超过重试次数，返回失败（包含解析错误信息）
        console.error(`[并发演化] ${target.name} 指令解析失败，已达最大重试次数`, errorMessages);
        return { target, success: false, response, parseErrors: errorMessages, thinkingContent };
      }


      const profileGaps = frGetNewEntryNpcProfileGaps(target, delta);
      if (profileGaps.length) return { target, success: false, response, profileGaps, error: '新登场人物未补齐：' + profileGaps.join('；'), thinkingContent };
      // 解析成功且新人核心资料完整，才返回可应用的 delta。
      return { target, success: true, response, delta, commandsString, thinkingContent };

    } catch (error) {
      if(timeoutId && typeof timeoutId.cancel==='function')timeoutId.cancel();else clearTimeout(timeoutId);

      // 检查是否需要重试
      // 超时abort可以重试，用户手动abort不重试
      const isTimeoutAbort = error.name === 'AbortError' && controller._isTimeoutAbort;
      const canRetry = !batchOptions?.hasNextRoute && (error.name !== 'AbortError' || isTimeoutAbort) &&
                       (!target.retryCount || target.retryCount < config.retryCount);
      if (canRetry) {
        target.retryCount = (target.retryCount || 0) + 1;
        const retryMsg = `重试 ${target.name} (${target.retryCount}/${config.retryCount})${isTimeoutAbort ? ' [超时重试]' : ''}`;
        console.log(`[并发演化] ${retryMsg}`);
        if (typeof showDanmaku === 'function') {
          showDanmaku(retryMsg, 'info');
        }
        await new Promise(r => setTimeout(r, config.retryDelay));
        return executeOne(target, apiOverride, effectiveContext, batchOptions, retryOptions);  // 保持相同API重试
      }

      console.error(`[并发演化] 请求失败: ${target.name}`, error.message);
      return { target, success: false, error: error.message };
    }
  };

  // 传输失败后先用下一配置，当前接口的格式修正仍由 executeOne 处理。
  const executeOneWithFallback = async (target) => {
    if(signal?.aborted)return {target,success:false,error:'cancelled'};
    const apiConfigs = getApiConfigsToTry(config);
    let lastResult;
    for (let ci = 0; ci < apiConfigs.length; ci++) {
      target.retryCount = 0;
      target.parseRetryCount = 0;
      target.originalTimelineFillRetryCount = 0;
      let result;
      try {
        result = await executeOne(target, apiConfigs[ci],sharedContext,{hasNextRoute:ci<apiConfigs.length-1});
      } catch (err) {
        // AbortError（用户取消），不切换备用
        if (err && err.name === 'AbortError') throw err;
        if (ci < apiConfigs.length - 1) {
          if (typeof showDanmaku === 'function') showDanmaku(`${target.name}：API ${ci + 1} 异常，切换备用 ${ci + 2}`, 'warning');
        }
        lastResult = { target, success: false, error: err?.message || String(err) };
        continue;
      }
      if(signal?.aborted)return {target,success:false,error:'cancelled'};
      if (result && result.protocolFailure === 'missing_upstore') {
        if (ci < apiConfigs.length - 1) {
          if (typeof showDanmaku === 'function') showDanmaku(`${target.name}：API ${ci + 1} 未按协议输出，切换备用 ${ci + 2}`, 'warning');
          lastResult = result;
          continue;
        }
        return result;
      }
      // 解析失败（parseErrors）或成功 → 不切换备用
      if (result.profileGaps || result.parseErrors || result.emptyUpstore || !result.error) {
        return result;
      }
      // 被取消
      if (result.error === 'cancelled') return result;
      // API失败 → 切换备用
      if (ci < apiConfigs.length - 1) {
        if (typeof showDanmaku === 'function') showDanmaku(`${target.name}：API ${ci + 1} 失败，切换备用 ${ci + 2}`, 'warning');
      }
      lastResult = result;
    }
    return lastResult;
  };

  // Do not return until requests, delayed retries AND their application callbacks settle.
  while(queue.length>0||inProgress.size>0){
    if(signal?.aborted){await Promise.allSettled(Array.from(inProgress.values()));break;}
    while(queue.length>0&&inProgress.size<config.maxConcurrency&&!signal?.aborted){
      const target=queue.shift();
      const promise=executeOneWithFallback(target).then(async result=>{
        results.push(result);completed++;
        if(signal?.aborted)return result;
        if(onProgress)onProgress(completed,targets.length,target);
        if(onResult)await onResult(result);
        return result;
      }).catch(error=>{
        if(typeof frReplayFail==='function'&&error?.name!=='AbortError')frReplayFail('角色请求或应用失败',error, signal);
        const failed={target,success:false,error:signal?.aborted?'cancelled':String(error?.message||error)};
        results.push(failed);return failed;
      }).finally(()=>inProgress.delete(target.id));
      inProgress.set(target.id,promise);
    }
    if(inProgress.size>0)await Promise.race(inProgress.values());
  }
  await Promise.allSettled(Array.from(inProgress.values()));
  return results;
}

// ===== 结果处理函数 =====

function splitConcurrentEvolutionArgs(argsString) {
  const args = [];
  if (!argsString || typeof argsString !== 'string') return args;
  let depth = 0;
  let lastSplit = 0;
  let inString = false;
  for (let i = 0; i < argsString.length; i++) {
    const char = argsString[i];
    if (char === '"' && (i === 0 || argsString[i - 1] !== '\\')) inString = !inString;
    if (!inString) {
      if (char === '{' || char === '[' || char === '(') depth++;
      if (char === '}' || char === ']' || char === ')') depth--;
    }
    if (char === ',' && depth === 0 && !inString) {
      args.push(argsString.substring(lastSplit, i).trim());
      lastSplit = i + 1;
    }
  }
  args.push(argsString.substring(lastSplit).trim());
  return args.filter(Boolean);
}

function extractDeSkillTraitOps(commandsString, errorMessages = []) {
  const ops = [];
  if (typeof commandsString !== 'string') return ops;
  const commandRegex = /(deSkill|deTrait|deGongfa|removeSkill|removeTrait|removeGongfa)\s*\(/g;
  let match;
  while ((match = commandRegex.exec(commandsString)) !== null) {
    const cmd = match[1];
    const argsStart = match.index + match[0].length;
    let openParens = 1;
    let endIndex = -1;

    for (let i = argsStart; i < commandsString.length; i++) {
      const ch = commandsString[i];
      if (ch === '(') openParens++;
      else if (ch === ')') {
        openParens--;
        if (openParens === 0) {
          endIndex = i;
          break;
        }
      }
    }

    if (endIndex === -1) {
      errorMessages.push({ title: `${cmd}解析失败`, details: '未找到匹配的右括号。' });
      break;
    }

    const rawArgs = commandsString.substring(argsStart, endIndex).trim();
    try {
      const args = splitConcurrentEvolutionArgs(rawArgs).map(arg => JSON.parse(arg));
      const id = args[0];
      const subId = args[1];
      if (typeof id !== 'string' || typeof subId !== 'string') {
        throw new Error(`${cmd}参数必须是 ("角色ID", "子ID") 格式`);
      }
      let normalizedCmd = 'deTrait';
      if (cmd === 'deSkill' || cmd === 'removeSkill') normalizedCmd = 'deSkill';
      if (cmd === 'deGongfa' || cmd === 'removeGongfa') normalizedCmd = 'deGongfa';
      ops.push({ command: normalizedCmd, id, subId });
    } catch (e) {
      errorMessages.push({ title: `${cmd}解析失败`, details: e.message });
    }

    commandRegex.lastIndex = endIndex + 1;
  }
  return ops;
}

function extractGongfaOps(commandsString, errorMessages = []) {
  const ops = [];
  if (typeof commandsString !== 'string') return ops;
  const commandRegex = /(addGongfa|setGongfa)\s*\(/g;
  let match;
  while ((match = commandRegex.exec(commandsString)) !== null) {
    const cmd = match[1];
    const argsStart = match.index + match[0].length;
    let openParens = 1;
    let endIndex = -1;

    for (let i = argsStart; i < commandsString.length; i++) {
      const ch = commandsString[i];
      if (ch === '(') openParens++;
      else if (ch === ')') {
        openParens--;
        if (openParens === 0) {
          endIndex = i;
          break;
        }
      }
    }

    if (endIndex === -1) {
      errorMessages.push({ title: `${cmd}解析失败`, details: '未找到匹配的右括号。' });
      break;
    }

    const rawArgs = commandsString.substring(argsStart, endIndex).trim();
    try {
      const args = splitConcurrentEvolutionArgs(rawArgs).map(arg => JSON.parse(arg));
      const id = args[0];
      if (typeof id !== 'string') throw new Error('第一个参数必须是角色ID字符串');

      if (cmd === 'addGongfa') {
        const gongfaData = args[1];
        if (!gongfaData || typeof gongfaData !== 'object' || Array.isArray(gongfaData)) {
          throw new Error('addGongfa参数必须是 ("角色ID", {功法对象})');
        }
        ops.push({ command: 'addGongfa', id, gongfaData });
      } else if (cmd === 'setGongfa') {
        if (args.length === 2) {
          const gongfaData = args[1];
          if (!gongfaData || typeof gongfaData !== 'object' || Array.isArray(gongfaData)) {
            throw new Error('setGongfa参数必须是 ("角色ID", {功法对象}) 或 ("角色ID", "旧功法", {新功法对象})');
          }
          ops.push({ command: 'setGongfa', id, gongfaData });
        } else if (args.length >= 3) {
          const oldSubId = args[1];
          const gongfaData = args[2];
          if (typeof oldSubId !== 'string' || !gongfaData || typeof gongfaData !== 'object' || Array.isArray(gongfaData)) {
            throw new Error('setGongfa三参数格式必须是 ("角色ID", "旧功法ID或名称", {新功法对象})');
          }
          ops.push({ command: 'setGongfa', id, oldSubId, gongfaData });
        } else {
          throw new Error('setGongfa参数不足');
        }
      }
    } catch (e) {
      errorMessages.push({ title: `${cmd}解析失败`, details: e.message });
    }

    commandRegex.lastIndex = endIndex + 1;
  }

  return ops;
}

function extractAppendBiographyOps(commandsString, errorMessages = []) {
  const ops = [];
  if (typeof commandsString !== 'string') return ops;
  const commandRegex = /appendBiography\s*\(/g;
  let match;
  while ((match = commandRegex.exec(commandsString)) !== null) {
    const startIndex = match.index + match[0].length;
    let openParens = 1;
    let endIndex = -1;
    for (let i = startIndex; i < commandsString.length; i++) {
      const ch = commandsString[i];
      if (ch === '(') openParens++;
      else if (ch === ')') {
        openParens--;
        if (openParens === 0) {
          endIndex = i;
          break;
        }
      }
    }

    if (endIndex === -1) {
      errorMessages.push({ title: 'appendBiography解析失败', details: '未找到匹配的右括号。' });
      break;
    }

    const argsString = commandsString.substring(startIndex, endIndex).trim();
    try {
      const rawArgs = splitConcurrentEvolutionArgs(argsString).map(arg => JSON.parse(arg));
      const id = rawArgs[0];
      const biography = rawArgs[1];
      if (typeof id !== 'string' || typeof biography !== 'string') {
        throw new Error('appendBiography参数必须是 (\"角色ID\", \"生平文本\") 格式');
      }
      ops.push({ command: 'appendBiography', id, biography: String(biography || '').trim() });
    } catch (e) {
      errorMessages.push({ title: 'appendBiography解析失败', details: e.message });
    }

    commandRegex.lastIndex = endIndex;
  }
  return ops;
}

/**
 * 解析并发演化指令（不重试 - 重试应该在 API 请求级别处理）
 * @param {string} commandsString - 指令字符串
 * @returns {{ delta: Array, errorMessages: Array, smallSummary: string|null, largeSummary: string|null }} 解析结果
 */
function parseConcurrentEvolutionCommands(commandsString) {
  const errorMessages = [];
  let finalDelta = [];
  let smallSummary = null;
  let largeSummary = null;

  try {
    const parsed = parseTableEditCommands(commandsString, errorMessages);
    const delta = parsed?.delta || [];
    smallSummary = parsed?.smallSummary ?? null;
    largeSummary = parsed?.largeSummary ?? null;
    const appendOps = extractAppendBiographyOps(commandsString, errorMessages);
    const deOps = extractDeSkillTraitOps(commandsString, errorMessages);
    const gongfaOps = extractGongfaOps(commandsString, errorMessages);
    finalDelta = Array.isArray(delta) ? delta.concat(appendOps, deOps, gongfaOps) : appendOps.concat(deOps, gongfaOps);

    if (typeof normalizeEquipItemOps === 'function') {
      normalizeEquipItemOps(finalDelta, { context: 'concurrent-evolution' });
    }
    const b1StripInfo = ceStripForbiddenB1ColumnsOps(finalDelta);
    if (b1StripInfo.removedFields > 0 || b1StripInfo.removedOps > 0) {
      console.log(
        `[并发演化] 已过滤B1的列12/35写入：删字段${b1StripInfo.removedFields}，删空指令${b1StripInfo.removedOps}`
      );
    }
  } catch (e) {
    errorMessages.push({
      title: e?.message || '解析异常',
      details: e?.stack || String(e)
    });
  }

  return { delta: finalDelta, errorMessages, smallSummary, largeSummary };
}

/**
 * 解析并发演化指令（带重试 - 兼容旧调用，但重试无效，仅用于非流式处理）
 * @deprecated 应使用 parseConcurrentEvolutionCommands，重试逻辑已移到 API 请求级别
 */
function parseConcurrentEvolutionCommandsWithRetry(commandsString, retryLimit) {
  // 兼容旧调用，但不再重复解析同一字符串（重试已移到 API 请求级别）
  return parseConcurrentEvolutionCommands(commandsString);
}

function ceGetOriginalTimelineBiographyAllowedIds() {
  if (typeof window === 'undefined') return null;
  return window._ceOriginalTimelineBiographyAllowedIds instanceof Set
    ? window._ceOriginalTimelineBiographyAllowedIds
    : null;
}

function ceShouldSkipBiographyGenerationForId(charId) {
  if (!charId || typeof window === 'undefined') return false;
  const normalizedId = String(charId || '').trim();
  if (!normalizedId) return false;
  const allowedIds = ceGetOriginalTimelineBiographyAllowedIds();
  if (allowedIds && allowedIds.has(normalizedId)) return false;
  const deedsGenerated = window._entryDecisionDeedsUpdated;
  if (deedsGenerated instanceof Set && deedsGenerated.has(normalizedId)) return true;
  // 策略：所有NPC的列35统一由登场判断生成，并发演化阶段一律禁止写入；
  // 但原著补演复用人物阶段允许当前需补演人物顺手写入第35列。
  return /^(C|G)/.test(normalizedId);
}

function ceStripBiographyOpsForPreGeneratedDeeds(delta, fallbackTargetId = '') {
  if (!Array.isArray(delta) || delta.length === 0) {
    return { removedFields: 0, removedOps: 0, ids: [] };
  }

  const touchedIds = new Set();
  let removedFields = 0;
  let removedOps = 0;

  for (let i = delta.length - 1; i >= 0; i--) {
    const op = delta[i];
    if (!op) continue;

    const opId = resolveConcurrentEvolutionOpId(op) || fallbackTargetId;
    if (!opId || !ceShouldSkipBiographyGenerationForId(opId)) continue;

    if (op.command === 'appendBiography') {
      delta.splice(i, 1);
      removedOps++;
      touchedIds.add(opId);
      continue;
    }

    if (!op.data || !Object.prototype.hasOwnProperty.call(op.data, '35')) continue;
    if (op.command !== 'add' && op.command !== 'set') continue;

    delete op.data['35'];
    removedFields++;
    touchedIds.add(opId);

    if (Object.keys(op.data).length === 0) {
      delta.splice(i, 1);
      removedOps++;
    }
  }

  return { removedFields, removedOps, ids: Array.from(touchedIds) };
}

function ceStripForbiddenB1ColumnsOps(delta) {
  if (!Array.isArray(delta) || delta.length === 0) {
    return { removedFields: 0, removedOps: 0 };
  }

  let removedFields = 0;
  let removedOps = 0;

  for (let i = delta.length - 1; i >= 0; i--) {
    const op = delta[i];
    if (!op || typeof op !== 'object') continue;

    const opId = resolveConcurrentEvolutionOpId(op);
    if (opId !== 'B1') continue;

    if (op.command === 'appendBiography') {
      delta.splice(i, 1);
      removedOps++;
      continue;
    }

    if ((op.command === 'add' || op.command === 'set') && op.data && typeof op.data === 'object') {
      if (Object.prototype.hasOwnProperty.call(op.data, '12')) {
        delete op.data['12'];
        removedFields++;
      }
      if (Object.prototype.hasOwnProperty.call(op.data, '35')) {
        delete op.data['35'];
        removedFields++;
      }

      if (Object.keys(op.data).length === 0) {
        delta.splice(i, 1);
        removedOps++;
      }
    }
  }

  return { removedFields, removedOps };
}

const CE_EQUIPMENT_SLOT_TYPE_MAP = Object.freeze({
  weapon: '武器',
  armor: '护甲',
  technique: '功法',
  treasure: '法宝'
});

function ceGetEquipmentSlotLabel(slot) {
  const normalizedSlot = String(slot || '').trim();
  if (!normalizedSlot) return '未知装备栏';
  const typeLabel = CE_EQUIPMENT_SLOT_TYPE_MAP[normalizedSlot] || normalizedSlot;
  return /栏$/.test(typeLabel) ? typeLabel : (typeLabel + '栏');
}

function ceResolveExpectedEquipmentSlotByItemData(itemData) {
  if (!itemData || typeof itemData !== 'object') return '';
  if (typeof FrEquipmentRuntime !== 'undefined' && FrEquipmentRuntime.classify) return FrEquipmentRuntime.classify(itemData).slotKey || '';
  const typeText = String(itemData['2'] || itemData.type || '').trim();
  const nameText = String(itemData['1'] || itemData.name || '').trim();
  const detailText = [
    itemData['3'], itemData.description, itemData.desc,
    itemData['4'], itemData.effect,
    itemData['6'], itemData.grade,
    itemData['7'], itemData.maxRealm,
    itemData['8'], itemData.realmEffects
  ].filter(Boolean).join(' ');
  const fullText = [typeText, nameText, detailText].filter(Boolean).join(' ');
  if (!fullText) return '';
  if (/材料|丹药|灵石|消耗|杂物|任务|道具|货币/.test(typeText)) return '';
  if (/功法|法诀|秘籍|秘术|神通|心经|剑诀|术法|禁制/.test(typeText)
    || (typeText === '' && /功法|法诀|秘籍|秘术|神通|心经|剑诀|术法|禁制/.test(fullText))) {
    return 'technique';
  }
  if (/武器|兵器/.test(typeText)
    || (/剑|刀|枪|戟|斧|锤|鞭|弓|弩|矛|戈|叉|匕|针|刃|棍|棒|杖/.test(nameText)
      && !/法宝|灵宝|古宝|宝器|功法|护甲|防具/.test(fullText))) {
    return 'weapon';
  }
  if (/护甲|防具/.test(typeText)
    || (/甲|铠|衣|袍|盔|冠|靴|履|盾|护腕|护臂/.test(nameText)
      && !/法宝|灵宝|古宝|宝器|功法|武器|兵器/.test(fullText))) {
    return 'armor';
  }
  if (/法宝|灵宝|古宝|宝器|法器|灵器|仙器|圣器|宝物/.test(typeText)
    || (/(印|鼎|幡|旗|镜|珠|盘|轮|塔|尺|瓶|葫|梭|环|链|伞|炉)/.test(nameText)
      && !/材料|丹药|灵石|杂物|任务|道具|功法|武器|兵器|护甲|防具/.test(fullText))) {
    return 'treasure';
  }
  return '';
}

function ceValidateEquipmentSlotAssignment(itemData, slot) {
  const normalizedSlot = String(slot || '').trim();
  const itemName = String(getManagedItemName(itemData) || getManagedItemId(itemData) || '该物品').trim() || '该物品';
  if (!normalizedSlot) {
    return { valid: false, expectedSlot: '', reason: itemName + ' 缺少装备槽。' };
  }
  const expectedSlot = ceResolveExpectedEquipmentSlotByItemData(itemData);
  if (!expectedSlot) {
    return {
      valid: false,
      expectedSlot: '',
      reason: itemName + ' 不是可装备物品，不能放入' + ceGetEquipmentSlotLabel(normalizedSlot) + '。'
    };
  }
  if (expectedSlot !== normalizedSlot) {
    return {
      valid: false,
      expectedSlot,
      reason: itemName + ' 只能放入' + ceGetEquipmentSlotLabel(expectedSlot) + '，不能放入' + ceGetEquipmentSlotLabel(normalizedSlot) + '。'
    };
  }
  return { valid: true, expectedSlot, reason: '' };
}

function normalizeEquipItemOps(delta, options = {}) {
  if (!Array.isArray(delta) || delta.length === 0) return delta;

  const context = options && options.context ? `[${options.context}]` : '';
  const itemCache = new Map();

  const rememberItem = (itemData) => {
    if (!itemData || typeof itemData !== 'object') return;
    const itemId = itemData['0'] || itemData.id || itemData.itemId;
    if (!itemId) return;
    itemCache.set(itemId, itemData);
  };

  delta.forEach(op => {
    if (!op || typeof op !== 'object') return;
    if (op.command === 'addItem' && op.itemData) {
      rememberItem(op.itemData);
    } else if (op.command === 'set' && op.data && typeof op.data === 'object') {
      const itemId = op.data['0'];
      if (itemId && typeof itemId === 'string' && itemId.startsWith('I')) {
        rememberItem(op.data);
      }
    } else if (op.command === 'add' && op.id && typeof op.id === 'string' && op.id.startsWith('I')) {
      const base = itemCache.get(op.id) || (currentState?.['1']?.[op.id] || { '0': op.id });
      itemCache.set(op.id, { ...base, ...(op.data || {}) });
    }
  });

  const normalizeItemData = (data, fallbackId, slot) => {
    if (!data || typeof data !== 'object') return null;
    if (data['0']) {
      if ((data['2'] || data.type || data.category || '') === '功法') {
        if (Object.prototype.hasOwnProperty.call(data, '9')) delete data['9'];
        if (Object.prototype.hasOwnProperty.call(data, 'effect')) delete data.effect;
      }
      return data;
    }
    const id = data.id || data.itemId || fallbackId;
    const normalizedType = data['2'] || data.type || data.category || '';
    const item = {
      ...data,
      '0': id,
      '1': data['1'] || data.name || id,
      '2': normalizedType,
      '3': data['3'] || data.description || '',
      '5': data['5'] || data.quantity || '1',
    };
    if (normalizedType === '功法') {
      item['6'] = data['6'] || data.grade || '';
      item['7'] = data['7'] || data.maxRealm || '';
      item['8'] = data['8'] || data.realmEffects || '';
    } else {
      item['4'] = data['4'] || data.effect || '';
    }
    return item;
  };

  const readRemarks = (row) => {
    if (!row) return {};
    if (typeof parseRemarksString === 'function') {
      return parseRemarksString(row['9'] || '');
    }
    try {
      return JSON.parse(row['9'] || '{}');
    } catch (e) {
      return {};
    }
  };

  const parseNested = (value, fallback) => {
    if (typeof parseNestedJsonString === 'function') {
      return parseNestedJsonString(value, fallback);
    }
    try {
      return JSON.parse(value || JSON.stringify(fallback));
    } catch (e) {
      return fallback;
    }
  };

  const resolveItemData = (itemId, ownerId, slot) => {
    if (!itemId) return null;
    let data = itemCache.get(itemId);
    if (!data) {
      if (ownerId === 'B1') {
        data = currentState?.['1']?.[itemId];
      } else {
        const row = currentState?.['0']?.[ownerId] || currentState?.['7']?.[ownerId];
        if (row) {
          const remarks = readRemarks(row);
          const inventory = parseNested(remarks.inventory, []);
          if (Array.isArray(inventory)) {
            data = inventory.find(item => (item?.['0'] || item?.id) === itemId);
          }
        }
      }
    }
    if (!data) {
      const row = currentState?.['0']?.[ownerId] || currentState?.['7']?.[ownerId];
      if (row) data = Object.values(FrEquipmentRuntime.project(row).equipment).flat().find(item => (item?.['0'] || item?.id) === itemId);
    }
    return normalizeItemData(data, itemId, slot);
  };

  const resolveSlotIndex = (ownerId, slot, itemData) => {
    const row = currentState?.['0']?.[ownerId] || currentState?.['7']?.[ownerId];
    if (!row) return 0;
    const equipment = FrEquipmentRuntime.project(row).equipment;
    let slotArr = equipment?.[slot];
    if (!Array.isArray(slotArr)) slotArr = slotArr ? [slotArr] : [];
    const allowed=FrEquipmentRuntime.allowed(slot,itemData);
    for (const i of allowed) {
      if (!slotArr[i]) return i;
    }
    return allowed[0];
  };

  const resolveEquippedIndexById = (ownerId, slot, itemId) => {
    const row = currentState?.['0']?.[ownerId] || currentState?.['7']?.[ownerId];
    if (!row) return null;
    const equipment = FrEquipmentRuntime.project(row).equipment;
    let slotArr = equipment?.[slot];
    if (!Array.isArray(slotArr)) slotArr = slotArr ? [slotArr] : [];
    for (let i = 0; i < slotArr.length; i++) {
      const entry = slotArr[i];
      const entryId = entry?.id || entry?.['0'];
      if (entryId === itemId) return i;
    }
    return null;
  };
  const markInvalidEquipOp = (op, ownerId, slot, itemData) => {
    const validation = typeof ceValidateEquipmentSlotAssignment === 'function'
      ? ceValidateEquipmentSlotAssignment(itemData, slot)
      : { valid: true, reason: '' };
    if (!itemData) { validation.valid = false; validation.reason = '找不到已持有或本轮新建的物品，拒绝凭空创建装备'; }
    if (validation.valid === true) {
      const row = currentState?.['0']?.[ownerId] || currentState?.['7']?.[ownerId];
      const eligibility = FrEquipmentRuntime.eligibility(row, slot, op.item?.index, itemData);
      if (!eligibility.allowed) { validation.valid = false; validation.reason = eligibility.reason; }
    }
    if (validation.valid === true) return false;
    const itemId = String(getManagedItemId(itemData) || (op && op.item && (op.item.id || op.item.item || op.item['0'])) || '').trim();
    op.__ceDropReason = validation.reason || '物品与装备槽不匹配';
    console.warn(`${context}[equipItem] 已过滤非法装备槽: ${ownerId}/${slot}/${itemId || '?'} -> ${op.__ceDropReason}`);
    return true;
  };

  delta.forEach(op => {
    if (!op || typeof op !== 'object') return;
    if (['equipItem','unequipItem'].includes(op.command) && !['weapon','armor','technique','treasure'].includes(op.slot)) { op.__ceDropReason = '未知装备组'; return; }
    if (op.command === 'equipItem') {
      const slot = op.slot;
      const ownerId = op.id;
      if (!slot || !ownerId) return;
      const item = op.item;
      if (typeof item === 'string') {
        const data = resolveItemData(item, ownerId, slot);
        const index = resolveSlotIndex(ownerId, slot, data);
        op.item = { index, data };
        console.warn(`${context}[equipItem] 已自动补全物品对象: ${ownerId}/${slot}/${item}`);
        markInvalidEquipOp(op, ownerId, slot, data);
        return;
      }
      if (typeof item === 'object' && item) {
        if (typeof item.index !== 'number') {
          item.index = resolveSlotIndex(ownerId, slot, item.data || resolveItemData(item.id || item.item || item['0'],ownerId,slot));
        }
        if (!item.data) {
          const itemId = item.id || item.item || item['0'];
          if (itemId) {
            item.data = resolveItemData(itemId, ownerId, slot);
          } else {
            const fallbackId = `I_${ownerId}_${slot}_${item.index ?? 0}`;
            item.data = normalizeItemData(null, fallbackId, slot);
          }
        } else {
          const fallbackId = item.data['0'] || item.data.id || item.id;
          item.data = normalizeItemData(item.data, fallbackId, slot);
        }
        markInvalidEquipOp(op, ownerId, slot, item.data);
        return;
      }
      if (typeof item === 'number') {
        const fallbackId = `I_${ownerId}_${slot}_${item}`;
        op.item = { index: item, data: normalizeItemData(null, fallbackId, slot) };
        markInvalidEquipOp(op, ownerId, slot, op.item.data);
      }
    } else if (op.command === 'unequipItem') {
      const slot = op.slot;
      const ownerId = op.id;
      if (!slot || !ownerId) return;
      const item = op.item;
      if (typeof item === 'number') {
        op.item = { index: item };
        return;
      }
      if (typeof item === 'string') {
        const idx = resolveEquippedIndexById(ownerId, slot, item);
        if (idx === null) { op.__ceDropReason = '目标物品不在所指装备组，拒绝卸下其他物品'; return; }
        op.item = { index: idx };
        console.warn(`${context}[unequipItem] 已自动补全槽位索引: ${ownerId}/${slot}/${item}`);
        return;
      }
      if (typeof item === 'object' && item) {
        const declaredId = item.id || item.item || item['0'];
        if (declaredId && typeof item.index === 'number' && resolveEquippedIndexById(ownerId,slot,declaredId) !== item.index) { op.__ceDropReason = '卸下物品ID与目标槽不一致'; return; }
        if (typeof item.index !== 'number') {
          const itemId = declaredId;
          const idx = itemId ? resolveEquippedIndexById(ownerId, slot, itemId) : null;
          if (idx === null) { op.__ceDropReason = '缺少可确认的卸下目标'; return; }
          item.index = idx;
        }
      }
    }
  });

  for (let i = delta.length - 1; i >= 0; i--) {
    const op = delta[i];
    if (!op || op.__ceDropReason === undefined) continue;
    delete op.__ceDropReason;
    delta.splice(i, 1);
  }

  return delta;
}

async function applyConcurrentEvolutionDeltaBatch(delta, result, summary, options = {}) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  const strictApply = options.strictApply === true;
  const checkAbort = () => { if (strictApply) ceThrowIfConcurrentEvolutionAborted(options.signal); };
  if (frStrict) frAssertCanonCommit();
  checkAbort();
  if (typeof normalizeEquipItemOps === 'function') {
    normalizeEquipItemOps(delta, { context: 'concurrent-evolution-batch' });
  }

  // === 对delta进行排序，确保 de 指令最后执行 ===
  // 这样其他指令（如 add）可以先同步数据到 worldBook，然后 de 再删除 currentState 中的角色
  delta.sort((a, b) => {
    const aIsDe = a.command === 'de' && !a.subCategory && !a.subId;
    const bIsDe = b.command === 'de' && !b.subCategory && !b.subId;
    if (aIsDe && !bIsDe) return 1;  // a 是整行删除的 de，排到后面
    if (!aIsDe && bIsDe) return -1; // b 是整行删除的 de，a排到前面
    return 0; // 保持原顺序
  });

  const batchedAllowedCommands = new Set([
    'add', 'updateAttribute', 'addItem', 'addSkill', 'addTrait',
    'appendBiography', 'equipItem', 'unequipItem'
    // deItem/deSkill/deTrait 不走批量 applyChanges，走单条 applyConcurrentEvolutionDelta
  ]);

  const canBatchApplyOpConservatively = (op, target) => {
    if (typeof applyChanges !== 'function') return false;
    if (!op || typeof op !== 'object') return false;

    const command = op.command;
    if (!command) return false;
    if (command === 'set') return false;
    if (command === 'de' && !op.subCategory && !op.subId) return false;
    if (!batchedAllowedCommands.has(command)) return false;

    const targetId = resolveConcurrentEvolutionTargetId(op, target.id);
    if (!targetId || targetId !== target.id) return false;
    if (targetId === 'B1' && target.id !== 'B1') return false;

    const isBeastId = ceIsBeastId(targetId);
    const tableKey = typeof getTableIndexFromId === 'function'
      ? getTableIndexFromId(targetId)
      : (isBeastId ? '7' : '0');
    const dataTable = tableKey ? currentState?.[tableKey] : null;
    return !!(dataTable && dataTable[targetId]);
  };

  const applyMergedOps = async (ops, target) => {
    if (!Array.isArray(ops) || ops.length === 0) return false;

    const mergeTargetId = resolveConcurrentEvolutionTargetId(ops[0], target.id);
    const isBeastId = ceIsBeastId(mergeTargetId);

    try {
      ceLogTargetInfoDedup(
        mergeTargetId,
        `[并发演化-Delta][${mergeTargetId}] 开始批量应用: ops=${ops.length}`
      );
      await ceDumpStateAndWorldbookNow('CE_DELTA_BATCH_START', ceGetLastUserAction());

      checkAbort();
      const applyResult = await applyChanges(currentState, ops);
      checkAbort();
      if (strictApply && (!applyResult || !applyResult.newState)) throw new Error('合并人物批量应用未返回状态');
      if (frStrict) { frAssertCanonCommit(); if (!applyResult || !applyResult.newState) throw new Error('补演提交：人物批量应用未返回状态'); }
      if (applyResult && applyResult.newState) {
        currentState = applyResult.newState;
      }
      ceLogTargetInfoDedup(
        mergeTargetId,
        `[并发演化-Delta][${mergeTargetId}] 已通过 applyChanges 批量应用`
      );

      if (!isBeastId && mergeTargetId !== 'B1') {
        const row = currentState?.['0']?.[mergeTargetId];
        if (row) {
          const frArchiveUpdated = await updateConcurrentEvolutionArchiveEntry(mergeTargetId, row, { silent: true });
          checkAbort();
          if (strictApply && !frArchiveUpdated) throw new Error('合并人物档案同步失败');
          if (frStrict) { frAssertCanonCommit(); if (!frArchiveUpdated) throw new Error('补演提交：必要角色档案同步失败'); }
        }
      }

      await ceDumpStateAndWorldbookNow('CE_DELTA_BATCH_APPLY', ceGetLastUserAction());
      return true;
    } catch (e) {
      if (frStrict || strictApply) throw e;
      console.error(`[并发演化][${mergeTargetId}] 批量应用失败，回退到逐条执行`, e);
      return false;
    }
  };

  const canBatchApplyArchiveOpConservatively = (op, target) => {
    if (!op || typeof op !== 'object') return false;

    const command = op.command;
    if (!command) return false;
    if (command === 'set') return false;
    if (command === 'de' && !op.subCategory && !op.subId) return false;
    if (!batchedAllowedCommands.has(command)) return false;

    const targetId = resolveConcurrentEvolutionTargetId(op, target.id);
    if (!targetId || targetId !== target.id) return false;
    if (targetId === 'B1' && target.id !== 'B1') return false;
    if (!target || !target.biography || typeof target.biography.content !== 'string') return false;

    const isBeastId = ceIsBeastId(targetId);
    const tableKey = typeof getTableIndexFromId === 'function'
      ? getTableIndexFromId(targetId)
      : (isBeastId ? '7' : '0');
    const dataTable = tableKey ? currentState?.[tableKey] : null;
    if (!dataTable) return false;
    return !dataTable[targetId];
  };

  const applyMergedArchiveOps = async (ops, target) => {
    if (!Array.isArray(ops) || ops.length === 0) return { ok: false, appliedOps: [] };

    const mergeTargetId = resolveConcurrentEvolutionTargetId(ops[0], target.id);
    let archiveWorkingCharData = null;

    try {
      archiveWorkingCharData = JSON.parse(target.biography.content || '{}');
    } catch (e) {
      if (frStrict || strictApply) throw e;
      console.error(`[并发演化-Delta][${mergeTargetId}] 批量解析离场档案失败`, e);
      return { ok: false, appliedOps: [] };
    }

    try {
      ceLogTargetInfoDedup(
        mergeTargetId,
        `[并发演化-Delta][${mergeTargetId}] 开始离场批量应用: ops=${ops.length}`
      );
      await ceDumpStateAndWorldbookNow('CE_DELTA_ARCHIVE_BATCH_START', ceGetLastUserAction());
      checkAbort();

      const appliedOps = [];
      for (const op of ops) {
        mergeAppendBiographyForAdd(op, archiveWorkingCharData);
        const modified = applyConcurrentEvolutionBioChanges(archiveWorkingCharData, op);
        if (modified) appliedOps.push(op);
      }

      if (appliedOps.length === 0) {
        ceLogTargetInfoDedup(
          mergeTargetId,
          `[并发演化-Delta][${mergeTargetId}] 离场批量应用无实际变更`
        );
        return { ok: true, appliedOps: [] };
      }

      const updated = await updateConcurrentEvolutionArchiveEntry(mergeTargetId, archiveWorkingCharData, { silent: true });
      checkAbort();
      if (!updated) {
        if (frStrict || strictApply) throw new Error('补演提交：离场人物档案写入失败');
        console.warn(`[并发演化-Delta][${mergeTargetId}] 离场批量应用写档案失败，回退逐条执行`);
        return { ok: false, appliedOps: [] };
      }

      target.biography.content = JSON.stringify(archiveWorkingCharData, null, 2);
      ceLogTargetInfoDedup(
        mergeTargetId,
        `[并发演化-Delta][${mergeTargetId}] 离场批量应用完成: applied=${appliedOps.length}`
      );
      await ceDumpStateAndWorldbookNow('CE_DELTA_ARCHIVE_BATCH_APPLY', ceGetLastUserAction());
      return { ok: true, appliedOps };
    } catch (e) {
      if (frStrict || strictApply) throw e;
      console.error(`[并发演化-Delta][${mergeTargetId}] 离场批量应用异常，回退逐条执行`, e);
      return { ok: false, appliedOps: [] };
    }
  };

  let hasChanges = false;
  for (let i = 0; i < delta.length; i++) {
    if (frStrict) frAssertCanonCommit();
    checkAbort();
    const op = delta[i];
    try {
      if (canBatchApplyOpConservatively(op, result.target)) {
        const mergeTargetId = resolveConcurrentEvolutionTargetId(op, result.target.id);
        const run = [op];
        let j = i + 1;
        while (j < delta.length) {
          const nextOp = delta[j];
          if (!canBatchApplyOpConservatively(nextOp, result.target)) break;
          const nextTargetId = resolveConcurrentEvolutionTargetId(nextOp, result.target.id);
          if (nextTargetId !== mergeTargetId) break;
          run.push(nextOp);
          j++;
        }

        if (run.length > 1) {
          const batchedApplied = await applyMergedOps(run, result.target);
          if (batchedApplied) {
            hasChanges = true;
            run.forEach(appliedOp => {
              summary.appliedChanges.push({ target: result.target, operation: appliedOp });
            });
          } else {
            for (const fallbackOp of run) {
              const fallbackApplied = await applyConcurrentEvolutionDelta(fallbackOp, result.target);
              if (fallbackApplied) {
                hasChanges = true;
                summary.appliedChanges.push({ target: result.target, operation: fallbackOp });
              }
            }
          }
          i = j - 1;
          continue;
        }
      }

      if (canBatchApplyArchiveOpConservatively(op, result.target)) {
        const mergeTargetId = resolveConcurrentEvolutionTargetId(op, result.target.id);
        const run = [op];
        let j = i + 1;
        while (j < delta.length) {
          const nextOp = delta[j];
          if (!canBatchApplyArchiveOpConservatively(nextOp, result.target)) break;
          const nextTargetId = resolveConcurrentEvolutionTargetId(nextOp, result.target.id);
          if (nextTargetId !== mergeTargetId) break;
          run.push(nextOp);
          j++;
        }

        if (run.length > 1) {
          const grouped = await applyMergedArchiveOps(run, result.target);
          if (grouped.ok) {
            if (grouped.appliedOps.length > 0) {
              hasChanges = true;
              grouped.appliedOps.forEach(appliedOp => {
                summary.appliedChanges.push({ target: result.target, operation: appliedOp });
              });
            }
          } else {
            for (const fallbackOp of run) {
              const fallbackApplied = await applyConcurrentEvolutionDelta(fallbackOp, result.target);
              if (fallbackApplied) {
                hasChanges = true;
                summary.appliedChanges.push({ target: result.target, operation: fallbackOp });
              }
            }
          }
          i = j - 1;
          continue;
        }
      }

      const applied = await applyConcurrentEvolutionDelta(op, result.target, options);
      checkAbort();
      if (strictApply && !applied) throw new Error('合并人物操作未成功应用：' + op.command);
      if (applied) {
        hasChanges = true;
        summary.appliedChanges.push({ target: result.target, operation: op });
      }
    } catch (e) {
      if (frStrict || strictApply) throw e;
      console.error(`[并发演化] 应用变更失败: ${result.target.id}`, e);
    }
  }

  if (hasChanges) {
    summary.successCount[result.target.type]++;
  } else {
    summary.skippedCount[result.target.type]++;
  }

  return strictApply ? true : hasChanges;
}

async function finalizeConcurrentEvolutionSummary(summary) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  if (frStrict) return summary;
  // 保存状态 - 使用直接保存确保数据持久化
  if (summary.appliedChanges.length > 0) {
    // 优先使用直接保存函数，确保数据立即写入数据库
    // saveCurrentState() 是防抖函数，await 后立即返回而不等待实际保存
    if (typeof _internalSaveCurrentState === 'function') {
      await _internalSaveCurrentState();
      console.log(`[并发演化] 已直接保存状态，应用了 ${summary.appliedChanges.length} 项变更`);
    } else if (typeof saveCurrentState === 'function') {
      // 回退方案：触发防抖保存，并等待防抖完成
      await saveCurrentState();
      await new Promise(r => setTimeout(r, 1100));
      console.log(`[并发演化] 已保存状态（等待防抖），应用了 ${summary.appliedChanges.length} 项变更`);
    }

    // 刷新UI（避免调用 updateUI 重新解析正文）
    await refreshConcurrentEvolutionUI();
  }

  return summary;
}

function createConcurrentEvolutionResultProcessor(config, options = {}) {
  const summary = {
    total: 0,
    successCount: { player: 0, beast: 0, npc: 0 },
    failedCount: { player: 0, beast: 0, npc: 0 },
    skippedCount: { player: 0, beast: 0, npc: 0 },
    errors: [],
    appliedChanges: [],
    batchResults: []
  };

  const applyQueue = [];
  const idleResolvers = [];
  const thinkingResults = [];
  /* ★★★ 2026-11-02 玩家：「还有变量思维这里的变量演化流程展示每次都要跑完才展示，
   *   统一一下和其他一样，一边跑一边陆续展示。就是和现在补演一样，过程流程展示。」
   *
   * 病象：点开始后变量思维 tab 一片空白，直到全部角色跑完才一次性刷出来。
   * 根因：这里只把结果攒进 thinkingResults，渲染只在收尾时调一次
   *      （main.js 里 ceRenderThinkingToStreamTab(processor.thinkingResults, ...)）。
   *
   * 改法：每处理完一个角色就增量渲染一次，和原著补演一样「一边跑一边出」。
   *  · 用 70ms 防抖——补演那边踩过「高频重渲染把面板折叠状态冲掉」的坑，
   *    这里沿用同一套节奏，避免流式期间疯狂重排。
   *  · 面板不可见时直接跳过，不白烧 CPU。
   */
  let thinkingStreamTimer = null;
  const thinkingStreamSoon = function () {
    if (typeof ceRenderThinkingToStreamTab !== 'function') return;
    clearTimeout(thinkingStreamTimer);
    thinkingStreamTimer = setTimeout(function () {
      try {
        const tab = document.getElementById('thinking-stream-content');
        if (!tab) return;
        ceRenderThinkingToStreamTab(thinkingResults, window.lastEntryDecisionResult);
      } catch (e) {
        console.warn('[并发演化] 增量刷新变量思维tab失败:', e);
      }
    }, 70);
  };
  const parseRetryLimit = Number.isFinite(config.parseRetryCount) ? Math.max(0, config.parseRetryCount) : 2;
  const abortController = options.abortController || null;
  const processedIds = options.processedIds || new Set();
  const processedNames = options.processedNames || new Map();
  const targetMap = options.targetMap || null;
  const sharedContext = options.sharedContext || null;
  const requireApplyReceipt = !!(sharedContext && sharedContext.precomputedCharacterResponses);
  let applying = false;
  let halted = false;

  const notifyApplyIdle = () => {
    if (!applying && applyQueue.length === 0 && idleResolvers.length > 0) {
      const resolvers = idleResolvers.splice(0, idleResolvers.length);
      resolvers.forEach(resolve => resolve());
    }
  };

  const waitForApplyIdle = () => {
    if (!applying && applyQueue.length === 0) return Promise.resolve();
    return new Promise(resolve => idleResolvers.push(resolve));
  };

  const runApplyQueue = async () => {
    if (applying) return;
    applying = true;
    while (applyQueue.length > 0) {
      const task = applyQueue.shift();
      if (halted) {
        task.resolve(false);
        continue;
      }
      if (task.type === 'halt') {
        halted = true;
        if (abortController) abortController.abort();
        while(applyQueue.length)applyQueue.shift().resolve(false);
        task.resolve(false);
        break;
      }
      let applied = true;
      try {
        await applyConcurrentEvolutionDeltaBatch(task.delta, task.result, summary, {
          strictApply: requireApplyReceipt, signal: abortController && abortController.signal
        });
      } catch (e) {
        applied = false;
        if (requireApplyReceipt) {
          summary.failedCount[task.result.target.type]++;
          summary.errors.push({ id: task.result.target.id, name: task.result.target.name,
            type: task.result.target.type, error: e.message || String(e) });
        }
        if(typeof frReplayFail==='function')frReplayFail('角色变量应用失败',e, options.abortController?.signal);
        console.error('[并发演化] 队列应用失败:', e);
      } finally {
        task.resolve(requireApplyReceipt ? applied : true);
      }
    }
    applying = false;
    notifyApplyIdle();
  };

  const enqueueApplyTask = (task) => {
    return new Promise(resolve => {
      applyQueue.push({ ...task, resolve });
      runApplyQueue();
    });
  };

  const haltProcessing = () => {
    halted = true;
    if (abortController) abortController.abort();
    while(applyQueue.length)applyQueue.shift().resolve(false);
    notifyApplyIdle();
  };

  const enqueueExitOnlyIfPending = (result) => {
    if (!ceHasPendingExitForTarget(result.target.id)) return false;
    const delta = [];
    ceMaybeAppendExitForTarget(result.target, delta);
    if (delta.length === 0) return false;
    processedIds.add(result.target.id);
    processedNames.set(result.target.id, result.target.name);
    return enqueueApplyTask({ result, delta });
  };

  const handleResult = async (result) => {
    if (halted) return requireApplyReceipt ? false : undefined;
    summary.total++;

    // 收集thinking内容（所有有target的结果都收集）
    if (result.target) {
      thinkingResults.push({
        id: result.target.id,
        name: result.target.name,
        type: result.target.type,
        thinkingContent: result.thinkingContent || '',
        commandsString: result.commandsString || '',
        noUpstore: !!result.noUpstore,
        emptyUpstore: !!result.emptyUpstore,
        parseErrors: result.parseErrors || null,
        success: !!result.success,
        skipped: !!result.skipped,
        error: result.error || ''
      });
      // 2026-11-02 玩家：变量演化要「一边跑一边陆续展示」，不要跑完才出。
      // 每收一个角色就增量刷一次（70ms 防抖），面板立刻能看到进度。
      thinkingStreamSoon();
    }

    if (result.target && Array.isArray(result.batchResults) && result.batchResults.length > 0) {
      summary.batchResults.push({
        targetId: result.target.id,
        targetName: result.target.name,
        targetType: result.target.type,
        batches: result.batchResults.map(function(batch) {
          return {
            batchIndex: batch && batch.batchIndex ? batch.batchIndex : 0,
            batchLabel: batch && batch.batchLabel ? batch.batchLabel : '',
            eventCodes: Array.isArray(batch && batch.eventCodes) ? batch.eventCodes.slice() : [],
            success: !!(batch && batch.success),
            skipped: !!(batch && batch.skipped),
            error: batch && batch.error ? String(batch.error) : '',
            deltaCount: Number(batch && batch.deltaCount || 0)
          };
        })
      });
    }

    if (result.skipped) {
      summary.skippedCount[result.target.type]++;
      return requireApplyReceipt ? true : undefined;
    }

    // === 处理解析错误（executeOne 已完成解析并返回错误）===
    if (result.parseErrors) {
      console.error(`[并发演化] ${result.target.name} 指令解析错误:`, result.parseErrors);

      if (config.showErrorModal) {
        await showConcurrentEvolutionErrorModal(result.target, result.parseErrors, result.response);
      }

      summary.failedCount[result.target.type]++;
      summary.errors.push({
        id: result.target.id,
        name: result.target.name,
        type: result.target.type,
        error: result.parseErrors.map(e => e.title).join('; ')
      });

      if (!config.continueOnError) {
        haltProcessing();
      }
      return requireApplyReceipt ? false : undefined;
    }

    if (!result.success) {
      summary.failedCount[result.target.type]++;
      summary.errors.push({
        id: result.target.id,
        name: result.target.name,
        type: result.target.type,
        error: result.error
      });
      return requireApplyReceipt ? false : undefined;
    }

    // === 处理无 upstore 标签的情况（executeOne 已标记）===
    const pendingCol19Op =
      result && result.target && result.success !== false && !result.parseErrors
        ? cePeekPendingCol19OpForTarget(result.target, targetMap)
        : null;
    const hasPendingCol19 = !!pendingCol19Op;

    if (result.noUpstore) {
      console.warn(`[并发演化] ${result.target.name} 响应无 <upstore> 标签`);
      if (!hasPendingCol19) {
        const exitTask = enqueueExitOnlyIfPending(result);
        if (exitTask) return exitTask;
        summary.skippedCount[result.target.type]++;
        return requireApplyReceipt ? false : undefined;
      }
    }

    // === 处理空 upstore 标签的情况（executeOne 已标记）===
    if (result.emptyUpstore) {
      if (!hasPendingCol19) {
        const exitTask = enqueueExitOnlyIfPending(result);
        if (exitTask) return exitTask;
        // 空的upstore标签，表示无变化
        summary.skippedCount[result.target.type]++;
        processedIds.add(result.target.id);
        processedNames.set(result.target.id, result.target.name);
        return requireApplyReceipt ? true : undefined;
      }
    }

    // === 使用 executeOne 已解析的 delta ===
    let delta = Array.isArray(result.delta) ? result.delta : [];
    if (hasPendingCol19) {
      const takeCol19 = ceTakePendingCol19OpForTarget(result.target, targetMap);
      if (takeCol19) delta.push(takeCol19);
    }
    if (!delta || delta.length === 0) {
      const exitTask = enqueueExitOnlyIfPending(result);
      if (exitTask) return exitTask;
      // 没有有效指令
      summary.skippedCount[result.target.type]++;
      processedIds.add(result.target.id);
      processedNames.set(result.target.id, result.target.name);
      return requireApplyReceipt ? true : undefined;
    }

    // 登场判断已预生成列35的角色，本轮并发演化禁止重复写35（执行层硬兜底）
    const stripInfo = ceStripBiographyOpsForPreGeneratedDeeds(delta, result.target.id);
    if (stripInfo.removedFields > 0) {
      console.log(
        `[并发演化] 已过滤预生成事迹角色的列35写入: ${stripInfo.ids.join(', ')} ` +
        `(删字段${stripInfo.removedFields}，删空指令${stripInfo.removedOps})`
      );
    }

    // 如有pending exit，且未包含de，则自动追加
    ceMaybeAppendExitForTarget(result.target, delta);

    // 标记为已处理
    processedIds.add(result.target.id);
    processedNames.set(result.target.id, result.target.name);

    // 使用已解析的 delta 入队应用
    return enqueueApplyTask({ result, delta });
  };

  const finalize = async () => {
    await waitForApplyIdle();
    summary.processedIds = processedIds;
    return await finalizeConcurrentEvolutionSummary(summary);
  };

  return { summary, handleResult, finalize, processedIds, processedNames, thinkingResults };
}

async function processConcurrentEvolutionResults(results, config) {
  const summary = {
    total: results.length,
    successCount: { player: 0, beast: 0, npc: 0 },
    failedCount: { player: 0, beast: 0, npc: 0 },
    skippedCount: { player: 0, beast: 0, npc: 0 },
    errors: [],
    appliedChanges: []
  };

  for (const result of results) {
    if (result.skipped) {
      summary.skippedCount[result.target.type]++;
      continue;
    }

    if (!result.success) {
      summary.failedCount[result.target.type]++;
      summary.errors.push({
        id: result.target.id,
        name: result.target.name,
        type: result.target.type,
        error: result.error
      });
      continue;
    }

    // 提取 <upstore>...</upstore>
    const storeMatch = result.response.match(/<upstore>([\s\S]*?)<\/upstore>/);
    if (!storeMatch) {
      console.warn(`[并发演化] ${result.target.name} 响应无 <upstore> 标签`);
      summary.skippedCount[result.target.type]++;
      continue;
    }

    const commandsString = storeMatch[1].trim();
    if (!commandsString) {
      // 空的upstore标签，表示无变化
      summary.skippedCount[result.target.type]++;
      continue;
    }

    // 解析指令
    const { delta, errorMessages } = parseConcurrentEvolutionCommandsWithRetry(commandsString, 0);

    if (errorMessages.length > 0) {
      console.error(`[并发演化] ${result.target.name} 指令解析错误:`, errorMessages);

      if (config.showErrorModal) {
        await showConcurrentEvolutionErrorModal(result.target, errorMessages, result.response);
      }

      summary.failedCount[result.target.type]++;
      summary.errors.push({
        id: result.target.id,
        name: result.target.name,
        type: result.target.type,
        error: errorMessages.map(e => e.title).join('; ')
      });

      if (!config.continueOnError) break;
      continue;
    }

    await applyConcurrentEvolutionDeltaBatch(delta, result, summary);
  }

  return await finalizeConcurrentEvolutionSummary(summary);
}

// 并发演化后安全刷新UI（不触发正文解析）
async function refreshConcurrentEvolutionUI(options = {}) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  if (frStrict) return;
  const skipThinkingTab = options && options.skipThinkingTab === true;
  try {
    if (typeof syncStateFromTables === 'function') {
      syncStateFromTables();
      console.log('[并发演化] 已调用 syncStateFromTables 刷新内存状态');
    }
    try {
      if (typeof ceEnsureConcurrentEvolutionAbortButton === 'function') {
        ceEnsureConcurrentEvolutionAbortButton();
      }
    } catch (buttonError) {
      console.warn('[并发演化] 刷新中止按钮失败:', buttonError);
    }

    if (typeof renderPlayerAttributes === 'function') {
      renderPlayerAttributes(typeof currentPlayerData !== 'undefined' ? currentPlayerData : undefined);
    }
    if (typeof renderInventory === 'function') {
      renderInventory(typeof inventoryItems !== 'undefined' ? inventoryItems : undefined);
    }
    if (typeof updateAvatar === 'function') {
      await updateAvatar(typeof currentPlayerData !== 'undefined' ? currentPlayerData : undefined);
    }
    if (typeof updateMiniMap === 'function') {
      await updateMiniMap();
    }
    if (typeof checkPlayerDeath === 'function') {
      checkPlayerDeath();
    }

    const charOverlay = document.getElementById('surrounding-characters-overlay');
    if (charOverlay && charOverlay.classList.contains('visible')) {
      if (typeof currentEditingNpcId !== 'undefined' && currentEditingNpcId && typeof showCharacterDetail === 'function') {
        const updatedCharData =
          typeof characterDatabase !== 'undefined' ? characterDatabase[currentEditingNpcId] : null;
        if (updatedCharData) {
          showCharacterDetail(updatedCharData);
        } else if (typeof renderCharacterList === 'function') {
          renderCharacterList();
        }
      } else if (typeof renderCharacterList === 'function') {
        renderCharacterList();
      }
    }

    if (!skipThinkingTab && typeof ceRenderThinkingToStreamTab === 'function') {
      try {
        const cachedThinkingResults = typeof window !== 'undefined' && Array.isArray(window._ceLastThinkingResults)
          ? window._ceLastThinkingResults
          : [];
        const latestEntryDecisionResult = typeof window !== 'undefined' ? (window.lastEntryDecisionResult || null) : null;
        const latestTagCalibrationResult = typeof window !== 'undefined'
          && window.lastOffscreenTagCalibrationResult
          && typeof window.lastOffscreenTagCalibrationResult === 'object'
          ? window.lastOffscreenTagCalibrationResult
          : null;
        const thinkingStreamEl = document.getElementById('thinking-stream-content');
        const hasRenderableThinkingData = cachedThinkingResults.length > 0
          || !!latestEntryDecisionResult
          || !!latestTagCalibrationResult;
        const hasExistingThinkingHtml = !!(thinkingStreamEl && String(thinkingStreamEl.innerHTML || '').trim());
        if (hasRenderableThinkingData || !hasExistingThinkingHtml) {
          ceRenderThinkingToStreamTab(cachedThinkingResults, latestEntryDecisionResult);
        }
      } catch (thinkingErr) {
        console.warn('[并发演化] 刷新变量思维tab失败:', thinkingErr);
      }
    }
  } catch (e) {
    console.error('[并发演化] 刷新UI失败:', e);
  }
}

function resolveConcurrentEvolutionTargetId(op, fallbackId) {
  if (op?.command === 'set' && op.data && typeof op.data === 'object' && op.data['0']) {
    return op.data['0'];
  }
  return op?.id || fallbackId;
}

function updateConcurrentEvolutionEntryInArray(entries, targetId, serialized, charName = '') {
  if (!Array.isArray(entries)) return false;
  const matchIndex = entries.findIndex(entry => {
    const entryId = entry?.key || entry?.id || entry?.characterId || entry?.charId;
    if (entryId && entryId === targetId) return true;
    if (charName) {
      const entryTitle = entry?.title || entry?.name;
      if (entryTitle && entryTitle === charName) return true;
    }
    return false;
  });
  if (matchIndex === -1) return false;
  const entry = entries[matchIndex];
  const normalizedSerialized = typeof serialized === 'string'
    ? serialized
    : JSON.stringify(serialized && typeof serialized === 'object' ? serialized : {}, null, 2);
  entry.content = normalizedSerialized;
  if (!entry.key) entry.key = targetId;
  if (charName && !entry.title) entry.title = charName;
  if (charName && !entry.name) entry.name = charName;
  if (charName && !entry.displayName) entry.displayName = charName;

  try {
    const suppression = typeof ceResolveWorldBookEntryContextSuppression === 'function'
      ? ceResolveWorldBookEntryContextSuppression(Object.assign({}, entry, { content: normalizedSerialized }))
      : null;
    if (suppression && suppression.suppressContextTrigger) {
      entry.keywords = [];
      entry.triggerMode = 'green';
      entry.ceSuppressWorldBookContext = true;
    } else if (entry.ceSuppressWorldBookContext) {
      delete entry.ceSuppressWorldBookContext;
      if ((!Array.isArray(entry.keywords) || entry.keywords.length === 0) && charName) {
        entry.keywords = [charName];
      }
      if (!entry.triggerMode) entry.triggerMode = 'green';
    }
  } catch (e) {}

  return true;
}

function ceRefreshWorldbookOverlay(reasonTag, userAction) {
  const overlay = document.getElementById('world-book-management-overlay');
  if (!overlay || !overlay.classList.contains('visible')) return false;
  const listEl = document.getElementById('world-book-entries-list');
  const currentCategory = listEl?.dataset?.currentCategory;
  void ceDumpWorldbookUiSourcesNow(reasonTag || 'WORLD_BOOK_UI_REFRESH', userAction, {
    currentCategory,
    overlayVisible: true,
  });

  if (currentCategory && typeof renderWorldBookEntries === 'function') {
    renderWorldBookEntries(currentCategory);
    console.log('[并发演化-WorldBook] 已按当前分类刷新世界档案面板');
    return true;
  }

  if (typeof renderWorldBookCategories === 'function') {
    renderWorldBookCategories();
    console.log('[并发演化-WorldBook] 已刷新世界档案分类面板');
    return true;
  }

  if (typeof renderWorldBookEntries !== 'function') return false;
  renderWorldBookEntries(currentCategory || 'all');
  console.log('[并发演化-WorldBook] 已回退刷新世界档案面板');
  return true;
}

function ceEnsureWorldbookOverlayObserver() {
  if (typeof window === 'undefined') return false;
  if (window._ceWorldbookOverlayObserver) return true;
  const overlay = document.getElementById('world-book-management-overlay');
  if (!overlay || typeof MutationObserver === 'undefined') return false;
  const observer = new MutationObserver(() => {
    if (!overlay.classList.contains('visible')) return;
    if (!window._ceWorldbookRefreshPending) return;
    window._ceWorldbookRefreshPending = false;
    ceTraceDiag('WORLD_BOOK_UI_PENDING_FLUSH', {
      archiveKey: currentArchiveName || null,
      overlayVisible: true,
    });
    ceRefreshWorldbookOverlay('WORLD_BOOK_UI_PENDING_FLUSH', ceGetLastUserAction());
  });
  observer.observe(overlay, { attributes: true, attributeFilter: ['class'] });
  window._ceWorldbookOverlayObserver = observer;
  return true;
}

function scheduleConcurrentEvolutionWorldbookRefresh() {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  if (frStrict) return;
  if (typeof window === 'undefined') return;
  if (window._ceWorldbookRefreshTimer) return;
  window._ceWorldbookRefreshTimer = setTimeout(() => {
    window._ceWorldbookRefreshTimer = null;
    if (ceRefreshWorldbookOverlay('WORLD_BOOK_UI_REFRESH', ceGetLastUserAction())) {
      window._ceWorldbookRefreshPending = false;
      return;
    }
    window._ceWorldbookRefreshPending = true;
    ceTraceDiag('WORLD_BOOK_UI_PENDING', {
      archiveKey: currentArchiveName || null,
      overlayVisible: false,
    });
    ceEnsureWorldbookOverlayObserver();
  }, 100);
}


// [简化] ceGetWorldBookEntriesCandidatesWithKeys 已移除，使用 cePickWorldBookEntriesFromGlobals 替代

async function showConcurrentEvolutionSaveConfirm(presetName, isBuiltIn) {
  const overlay = document.getElementById('concurrent-evo-preset-confirm-overlay');
  const titleEl = document.getElementById('ce-preset-confirm-title');
  const messageEl = document.getElementById('ce-preset-confirm-message');
  const hintEl = document.getElementById('ce-preset-confirm-hint');
  const okBtn = document.getElementById('ce-preset-confirm-ok');
  const cancelBtn = document.getElementById('ce-preset-confirm-cancel');
  const closeBtn = document.getElementById('ce-preset-confirm-close');

  const safeName = String(presetName || '').trim() || '未命名预设';
  const message = `确认保存当前编辑到预设「${safeName}」吗？`;

  if (!overlay || !titleEl || !messageEl || !okBtn || !cancelBtn || !closeBtn) {
    if (typeof showCustomConfirm === 'function') {
      return await showCustomConfirm(message);
    }
    return confirm(message);
  }

  titleEl.textContent = '保存预设';
  messageEl.textContent = message;
  if (hintEl) {
    hintEl.textContent = isBuiltIn
      ? '该预设为内置项，保存后将直接覆盖内容。'
      : '保存后将覆盖当前预设内容。';
  }

  return new Promise(resolve => {
    const handleConfirm = () => finish(true);
    const handleCancel = () => finish(false);
    const handleOverlay = (e) => {
      if (e.target === overlay) {
        finish(false);
      }
    };

    function finish(result) {
      okBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
      closeBtn.removeEventListener('click', handleCancel);
      overlay.removeEventListener('click', handleOverlay);
      hideConcurrentEvolutionOverlay(overlay);
      resolve(result);
    }

    okBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
    closeBtn.addEventListener('click', handleCancel);
    overlay.addEventListener('click', handleOverlay);

    showConcurrentEvolutionOverlay(overlay);
  });
}

// [简化] ceGetWorldBookEntriesCandidates, ceLogWorldBookCacheSource 已移除
// [简化] ceClearWorldBookForcedCache, ceSetWorldBookForcedCache, ceGetWorldBookForcedCache 已移除
// 系统现在直接使用 allBiographyEntries

function ceBuildAuthoritativeWorldBookFilter(archive) {
  let entries = null;
  let sourceKey = '';
  try {
    if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries) && allBiographyEntries.length > 0) {
      entries = allBiographyEntries;
      sourceKey = 'allBiographyEntries(local)';
    }
  } catch (e) {}

  if (!entries && typeof window !== 'undefined') {
    if (Array.isArray(window.allBiographyEntries) && window.allBiographyEntries.length > 0) {
      entries = window.allBiographyEntries;
      sourceKey = 'window.allBiographyEntries';
    }
  }

  if (!entries && Array.isArray(archive?.data?.state?.worldBookEntries) && archive.data.state.worldBookEntries.length > 0) {
    entries = archive.data.state.worldBookEntries;
    sourceKey = 'state.worldBookEntries';
  }

  if (!entries) return null;
  const idSet = new Set();
  const titleSet = new Set();
  entries.forEach(entry => {
    if (!entry || typeof entry !== 'object') return;
    const entryId = entry.key || entry.id || entry.characterId || entry.charId;
    const entryTitle = entry.title || entry.name || entry.displayName;
    if (entryId) idSet.add(String(entryId));
    if (entryTitle) titleSet.add(String(entryTitle));
  });
  if (idSet.size === 0 && titleSet.size === 0) return null;
  return { idSet, titleSet, sourceKey, count: entries.length };
}

function ceCollectWatchHitsInEntries(entries, watchSet) {
  const found = new Set();
  if (!Array.isArray(entries) || !watchSet || watchSet.size === 0) return [];
  entries.forEach(entry => {
    if (!entry || typeof entry !== 'object') return;
    const entryId = entry.key || entry.id || entry.characterId || entry.charId;
    if (entryId && watchSet.has(String(entryId))) found.add(String(entryId));
  });
  return Array.from(found);
}

function ceLogWatchHitsForEntries(tag, entries, watchSet) {
  if (!watchSet || watchSet.size === 0) return;
  const hits = ceCollectWatchHitsInEntries(entries, watchSet);
  console.log(`[${tag}] watchHits=${hits.length > 0 ? hits.join(', ') : '无'}`);
}

function ceAddWorldBookEntryIfMissing(entries, entry, charId, charName) {
  if (!Array.isArray(entries) || !entry) return false;
  const exists = entries.some(item => {
    if (!item || typeof item !== 'object') return false;
    const entryId = item.key || item.id || item.characterId || item.charId;
    if (entryId && entryId === charId) return true;
    if (charName) {
      const entryTitle = item.title || item.name || item.displayName;
      if (entryTitle && entryTitle === charName) return true;
    }
    return false;
  });
  if (exists) return false;
  entries.push(entry);
  return true;
}

// [简化] ceLogWorldBookCacheWatchHits 简化为直接使用 allBiographyEntries
function ceLogWorldBookCacheWatchHits(tag, watchSet) {
  if (!watchSet || watchSet.size === 0) return;
  const entries = cePickWorldBookEntriesFromGlobals();
  if (!Array.isArray(entries) || entries.length === 0) return;
  const hits = ceCollectWatchHitsInEntries(entries, watchSet);
  console.log(`[${tag}][watch][cache] allBiographyEntries: ${hits.length > 0 ? hits.join(', ') : '无'}`);
}

// [收口] 从多个常见前端缓存中挑选当前最可信的世界档案源，避免某一处空数组把基线判断带偏。
function cePickWorldBookEntriesFromGlobalsWithSource() {
  const candidates = [];
  if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)) {
    candidates.push({ entries: allBiographyEntries, sourceKey: 'allBiographyEntries(local)' });
  }
  if (typeof window !== 'undefined' && Array.isArray(window.allBiographyEntries)) {
    candidates.push({ entries: window.allBiographyEntries, sourceKey: 'window.allBiographyEntries' });
  }
  const preferred = candidates.find(function(item) {
    return Array.isArray(item.entries) && item.entries.length > 0;
  });
  if (preferred) return preferred;
  const fallback = candidates.find(function(item) {
    return Array.isArray(item.entries);
  });
  return fallback || { entries: [], sourceKey: 'none' };
}

function cePickWorldBookEntriesFromGlobals() {
  return cePickWorldBookEntriesFromGlobalsWithSource().entries;
}

// [简化] 禁用缓存过滤，让存档成为唯一数据源
// 原版实现依赖 allBiographyEntries 构建过滤集合，但这会导致UI与存档数据不一致
function ceBuildWorldBookCacheIdSet() {
  return null;  // 返回null禁用所有缓存过滤
}

function ceGetDebugWatchIds() {
  try {
    if (typeof window !== 'undefined' && Array.isArray(window.__ceWatchIds) && window.__ceWatchIds.length > 0) {
      return window.__ceWatchIds.map(id => String(id));
    }
  } catch (e) {}
  return null;
}

function ceNormalizeWorldBookId(id) {
  if (id === null || id === undefined) return '';
  const text = String(id).trim();
  return text;
}

function ceGetDeletedWorldBookIdSet() {
  if (typeof window === 'undefined') return null;
  if (!window._ceDeletedWorldBookIds) {
    window._ceDeletedWorldBookIds = new Set();
  }
  return window._ceDeletedWorldBookIds;
}

function ceTrackDeletedWorldBookIds(ids, options = {}) {
  const deletedSet = ceGetDeletedWorldBookIdSet();
  if (!deletedSet) return { added: 0, total: 0 };
  const list = Array.isArray(ids) ? ids : [ids];
  let added = 0;
  list.forEach(id => {
    const normalized = ceNormalizeWorldBookId(id);
    if (!normalized) return;
    if (!deletedSet.has(normalized)) {
      deletedSet.add(normalized);
      added++;
    }
  });
  if (added > 0 && typeof window !== 'undefined') {
    window._ceDeletedWorldBookIdsPendingClear = true;
  }
  if (added > 0 && options?.reason) {
    console.log(`[并发演化][worldbook] 追踪删除ID: ${list.filter(Boolean).join(', ')}`, {
      added,
      total: deletedSet.size,
      reason: options.reason,
    });
  }
  return { added, total: deletedSet.size };
}

function ceUntrackDeletedWorldBookIds(ids) {
  const deletedSet = ceGetDeletedWorldBookIdSet();
  if (!deletedSet || deletedSet.size === 0) return { removed: 0, remaining: 0 };
  const list = Array.isArray(ids) ? ids : [ids];
  let removed = 0;
  list.forEach(id => {
    const normalized = ceNormalizeWorldBookId(id);
    if (normalized && deletedSet.has(normalized)) {
      deletedSet.delete(normalized);
      removed++;
    }
  });
  if (removed > 0) {
    console.log(`[并发演化][worldbook] 从删除追踪中移除ID: ${list.filter(Boolean).join(', ')} (removed=${removed}, remaining=${deletedSet.size})`);
  }
  return { removed, remaining: deletedSet.size };
}

function ceClearDeletedWorldBookIds(options = {}) {
  const deletedSet = ceGetDeletedWorldBookIdSet();
  if (!deletedSet || deletedSet.size === 0) return { cleared: 0 };
  if (typeof window !== 'undefined' && !window._ceDeletedWorldBookIdsPendingClear && !options.force) {
    return { cleared: 0, skipped: true };
  }
  const cleared = deletedSet.size;
  deletedSet.clear();
  if (typeof window !== 'undefined') {
    window._ceDeletedWorldBookIdsPendingClear = false;
  }
  if (!options.silent) {
    console.log(`[并发演化][worldbook] 已清空删除追踪: ${cleared}`, { reason: options.reason || 'unknown' });
  }
  return { cleared };
}

function ceIsDeletedWorldBookId(id) {
  const deletedSet = ceGetDeletedWorldBookIdSet();
  if (!deletedSet || deletedSet.size === 0) return false;
  const normalized = ceNormalizeWorldBookId(id);
  if (!normalized) return false;
  return deletedSet.has(normalized);
}

function ceExtractWorldBookEntryIds(entry) {
  const ids = new Set();
  const add = (value) => {
    const normalized = ceNormalizeWorldBookId(value);
    if (normalized) ids.add(normalized);
  };
  if (!entry || typeof entry !== 'object') return [];
  add(entry.id);
  add(entry.key);
  add(entry.characterId);
  add(entry.charId);
  try {
    const content = ceParseWorldbookEntryContent(entry);
    if (content && (content['0'] || content[0])) {
      add(content['0'] || content[0]);
    }
  } catch (e) {}
  return Array.from(ids);
}

function ceIsWorldBookEntryDeleted(entry, deletedSet) {
  if (!deletedSet || deletedSet.size === 0) return false;
  const ids = ceExtractWorldBookEntryIds(entry);
  return ids.some(id => deletedSet.has(id));
}

function ceFindWorldBookEntryById(entryId, archive) {
  const targetId = ceNormalizeWorldBookId(entryId);
  if (!targetId) return null;
  const matches = (entry) => {
    if (!entry || typeof entry !== 'object') return false;
    const entryIds = ceExtractWorldBookEntryIds(entry);
    return entryIds.includes(targetId);
  };
  const sources = [];
  try {
    if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)) {
      sources.push(allBiographyEntries);
    }
  } catch (e) {}
  if (typeof window !== 'undefined' && Array.isArray(window.allBiographyEntries)) {
    sources.push(window.allBiographyEntries);
  }
  if (Array.isArray(archive?.data?.state?.worldBookEntries)) {
    sources.push(archive.data.state.worldBookEntries);
  }
  if (Array.isArray(archive?.data?.logs)) {
    const latestLog = [...archive.data.logs].reverse().find(log => Array.isArray(log?.biographySnapshot));
    if (latestLog && Array.isArray(latestLog.biographySnapshot)) {
      sources.push(latestLog.biographySnapshot);
    }
  }
  for (const list of sources) {
    const hit = list.find(matches);
    if (hit) return hit;
  }
  return null;
}

async function ceCleanupWorldBookEntriesByDeletedIds(ids, options = {}) {
  const deleteSet = new Set();
  const idList = Array.isArray(ids) ? ids : [ids];
  idList.forEach(id => {
    const normalized = ceNormalizeWorldBookId(id);
    if (normalized) deleteSet.add(normalized);
  });
  if (deleteSet.size === 0) return { skipped: true, reason: 'no_ids' };
  if (!db?.archives?.get || !currentArchiveName) return { skipped: true, reason: 'archive_unavailable' };

  const archive = options.archive || await db.archives.get(currentArchiveName);
  if (!archive) return { skipped: true, reason: 'no_archive' };
  if (!archive.data) archive.data = {};
  if (!archive.data.state) archive.data.state = {};

  const filterEntries = (arr) => {
    if (!Array.isArray(arr)) return { removed: 0, kept: 0 };
    const before = arr.length;
    const filtered = arr.filter(entry => !ceIsWorldBookEntryDeleted(entry, deleteSet));
    if (filtered.length !== arr.length) {
      arr.length = 0;
      filtered.forEach(entry => arr.push(entry));
    }
    return { removed: before - filtered.length, kept: filtered.length };
  };

  let updated = false;
  const summary = {
    worldBookEntries: null,
    logSnapshot: null,
    caches: [],
  };

  if (Array.isArray(archive.data.state.worldBookEntries)) {
    summary.worldBookEntries = filterEntries(archive.data.state.worldBookEntries);
    if (summary.worldBookEntries.removed > 0) updated = true;
  }
  if (Array.isArray(archive.data.logs)) {
    const latestLogIndex = [...archive.data.logs].reverse().findIndex(
      log => Array.isArray(log?.biographySnapshot) && log.biographySnapshot.length > 0
    );
    if (latestLogIndex !== -1) {
      const index = archive.data.logs.length - 1 - latestLogIndex;
      const log = archive.data.logs[index];
      if (log && Array.isArray(log.biographySnapshot)) {
        summary.logSnapshot = filterEntries(log.biographySnapshot);
        if (summary.logSnapshot.removed > 0) updated = true;
      }
    }
  }

  if (updated) {
    await db.archives.put(archive);
  }

  const cacheTargets = [
    { key: 'allBiographyEntries(local)', entries: typeof allBiographyEntries !== 'undefined' ? allBiographyEntries : null },
    { key: 'window.allBiographyEntries', entries: typeof window !== 'undefined' ? window.allBiographyEntries : null },
    { key: 'window.worldBookEntries', entries: typeof window !== 'undefined' ? window.worldBookEntries : null },
    { key: 'window.worldbookEntries', entries: typeof window !== 'undefined' ? window.worldbookEntries : null },
    { key: 'window.worldArchiveEntries', entries: typeof window !== 'undefined' ? window.worldArchiveEntries : null },
    { key: 'window.worldArchiveCharacters', entries: typeof window !== 'undefined' ? window.worldArchiveCharacters : null },
    { key: 'window.worldArchiveList', entries: typeof window !== 'undefined' ? window.worldArchiveList : null },
  ];

  cacheTargets.forEach(target => {
    if (!Array.isArray(target.entries)) return;
    const result = filterEntries(target.entries);
    if (result.removed > 0) summary.caches.push(target.key);
  });

  if (summary.caches.length > 0) {
    scheduleConcurrentEvolutionWorldbookRefresh();
  }

  return { ok: true, ids: Array.from(deleteSet), updated, summary };
}

async function ceHandleWorldBookDelete(entryId, options = {}) {
  if (!entryId) return { skipped: true, reason: 'no_entry_id' };
  const confirmFn = typeof showCustomConfirm === 'function'
    ? showCustomConfirm
    : async (message) => confirm(message);
  const confirmed = await confirmFn('确定要删除这个档案条目吗？');
  if (!confirmed) return { skipped: true, reason: 'user_cancel' };

  if (!db?.archives?.get || !currentArchiveName) {
    showDanmaku('删除失败：存档不可用', 'error');
    return { skipped: true, reason: 'archive_unavailable' };
  }

  const archive = await db.archives.get(currentArchiveName);
  if (!archive) {
    showDanmaku('删除失败：存档不可用', 'error');
    return { skipped: true, reason: 'no_archive' };
  }

  const entry = ceFindWorldBookEntryById(entryId, archive);
  const idsToTrack = new Set([entryId]);
  if (entry) {
    ceExtractWorldBookEntryIds(entry).forEach(id => idsToTrack.add(id));
  }
  ceTrackDeletedWorldBookIds(Array.from(idsToTrack), { reason: 'worldbook_delete' });

  // 清理已删除角色的频率设置
  try {
    const freq = ceGetEvolutionFrequency();
    let freqCleaned = false;
    for (const id of idsToTrack) {
      if (id !== 'B1' && freq[id]) {
        delete freq[id];
        freqCleaned = true;
      }
    }
    if (freqCleaned) {
      ceSetEvolutionFrequency(freq);
    }
  } catch (e) {
    console.warn('[并发演化] 清理频率设置失败:', e);
  }

  // 同步清理变量演化列表
  try {
    const ceConfig = await loadConcurrentEvolutionConfig();
    if (Array.isArray(ceConfig.focusCharacterIds)) {
      const before = ceConfig.focusCharacterIds.length;
      ceConfig.focusCharacterIds = ceConfig.focusCharacterIds.filter(id => !idsToTrack.has(id));
      if (ceConfig.focusCharacterIds.length !== before) {
        await saveConcurrentEvolutionConfig(ceConfig);
      }
    }
  } catch (e) {
    console.warn('[并发演化] 清理重点列表失败:', e);
  }

  const cleanupResult = await ceCleanupWorldBookEntriesByDeletedIds(Array.from(idsToTrack), {
    archive,
    reason: 'worldbook_delete',
  });

  const listContainer = options.listContainer || document.getElementById('world-book-entries-list');
  if (listContainer && typeof renderWorldBookEntries === 'function') {
    const currentCategory = listContainer.dataset.currentCategory;
    renderWorldBookEntries(currentCategory);
  } else {
    scheduleConcurrentEvolutionWorldbookRefresh();
  }

  showDanmaku('条目已删除。', 'success');
  return { ok: true, ids: Array.from(idsToTrack), cleanupResult };
}

function ceInstallWorldBookDeletePatch() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return false;
  if (window.__ceWorldBookDeletePatched) return true;

  document.addEventListener('click', async e => {
    const target = e.target;
    if (!(target instanceof Element)) return;
    const deleteButton = target.closest('.world-book-delete-btn');
    if (!deleteButton) return;
    e.preventDefault();
    e.stopPropagation();
    if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
    const entryId = deleteButton.dataset.id;
    const listContainer = document.getElementById('world-book-entries-list');
    await ceHandleWorldBookDelete(entryId, { listContainer, source: 'worldbook_delete_btn' });
  }, true);

  window.__ceWorldBookDeletePatched = true;
  console.log('[并发演化][worldbook] 已接管世界档案删除按钮');
  return true;
}

function scheduleConcurrentEvolutionWorldBookDeletePatch(retries = 10, delayMs = 800) {
  if (typeof window === 'undefined') return;
  if (ceInstallWorldBookDeletePatch()) return;
  if (retries <= 0) {
    console.warn('[并发演化][worldbook] 删除补丁等待超时，未检测到列表节点');
    return;
  }
  setTimeout(() => scheduleConcurrentEvolutionWorldBookDeletePatch(retries - 1, delayMs), delayMs);
}

function ceInstallWorldBookBatchDeletePatch() {
  if (window.__ceWorldBookBatchDeletePatched) return true;

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('#wb-delete-selected-btn');
    if (!btn || btn.disabled) return;

    const listContainer = document.getElementById('world-book-entries-list');
    if (!listContainer) return;
    const checked = listContainer.querySelectorAll('.summary-checkbox:checked');
    const selectedEntryIds = Array.from(checked).map(cb => cb.dataset.id).filter(Boolean);
    if (selectedEntryIds.length === 0) return;

    // 在基础处理器运行前收集所有关联ID
    const allIdsToTrack = new Set();
    if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)) {
      for (const eid of selectedEntryIds) {
        allIdsToTrack.add(eid);
        const entry = allBiographyEntries.find(e => e.id === eid);
        if (entry) {
          ceExtractWorldBookEntryIds(entry).forEach(id => allIdsToTrack.add(id));
        }
      }
    }

    // 轮询检测基础处理器是否完成删除
    const prevCount = allBiographyEntries.length;
    const pollStart = Date.now();
    const pollForDeletion = async () => {
      if (allBiographyEntries.length < prevCount) {
        // 删除已完成 - 追踪ID + 清理频率
        ceTrackDeletedWorldBookIds(Array.from(allIdsToTrack), { reason: 'worldbook_batch_delete' });
        // @CUSTOM-START: 批量删除后从存档DB物理删除条目并持久化，防止下回合回来
        try {
          await ceCleanupWorldBookEntriesByDeletedIds(Array.from(allIdsToTrack), {
            reason: 'worldbook_batch_delete',
          });
        } catch (e) {
          console.warn('[并发演化][worldbook] 批量删除cleanup失败:', e);
        }
        // @CUSTOM-END
        try {
          const freq = ceGetEvolutionFrequency();
          let freqCleaned = false;
          for (const id of allIdsToTrack) {
            if (id !== 'B1' && freq[id]) { delete freq[id]; freqCleaned = true; }
          }
          if (freqCleaned) ceSetEvolutionFrequency(freq);
        } catch (e) {}
        try {
          const ceConfig = await loadConcurrentEvolutionConfig();
          if (Array.isArray(ceConfig.focusCharacterIds)) {
            const before = ceConfig.focusCharacterIds.length;
            ceConfig.focusCharacterIds = ceConfig.focusCharacterIds.filter(id => !allIdsToTrack.has(id));
            if (ceConfig.focusCharacterIds.length !== before) {
              await saveConcurrentEvolutionConfig(ceConfig);
            }
          }
        } catch (e) {}
        console.log('[并发演化][worldbook] 批量删除已追踪:', allIdsToTrack.size, '个ID');
      } else if (Date.now() - pollStart < 15000) {
        setTimeout(pollForDeletion, 300);
      }
    };
    setTimeout(pollForDeletion, 500);
  }, true);  // capture phase, 不阻止传播

  window.__ceWorldBookBatchDeletePatched = true;
  return true;
}

// [收口] 统一把权威存档 worldBookEntries 广播到常见前端缓存，避免 UI 仍显示 0 条。
function ceResolveWorldBookEntryContextSuppression(entry, parsedContent = null) {
  const base = entry && typeof entry === 'object' ? entry : {};
  let resolvedContent = parsedContent;
  try {
    if (!resolvedContent) {
      if (typeof base.content === 'string' && base.content.trim()) {
        resolvedContent = JSON.parse(base.content);
      } else if (base.content && typeof base.content === 'object') {
        resolvedContent = base.content;
      }
    }
  } catch (e) {}

  const row = resolvedContent && typeof resolvedContent === 'object' ? resolvedContent : {};
  let remarks = {};
  try {
    if (typeof parseRemarks === 'function') {
      remarks = parseRemarks(row['9'] || '');
    } else if (typeof ceParseOffscreenRemarks === 'function') {
      remarks = ceParseOffscreenRemarks(row);
    }
  } catch (e) {
    remarks = {};
  }

  const pendingModelFill = remarks.pending_model_fill === true
    || String(remarks.pending_model_fill || '').trim().toLowerCase() === 'true';
  const originalTimelineColdStart = remarks.original_timeline_cold_start === true
    || String(remarks.original_timeline_cold_start || '').trim().toLowerCase() === 'true';
  const seedMode = String(remarks.original_timeline_seed_mode || '').trim().toLowerCase();
  const sourceOrigin = String(remarks.source_origin || '').trim().toLowerCase();
  const suppressContextTrigger = pendingModelFill || (
    (originalTimelineColdStart || !!seedMode || sourceOrigin === 'original_timeline_seed')
    && seedMode !== 'model_filled'
  );

  return {
    parsedContent: row,
    remarks: remarks && typeof remarks === 'object' ? remarks : {},
    suppressContextTrigger
  };
}

function ceNormalizeWorldBookEntryForFrontend(entry) {
  const base = entry && typeof entry === 'object' ? ceSafeClone(entry) : {};
  let parsedContent = null;
  try {
    if (typeof base.content === 'string' && base.content.trim()) {
      parsedContent = JSON.parse(base.content);
    } else if (base.content && typeof base.content === 'object') {
      parsedContent = base.content;
    }
  } catch (e) {}

  const suppression = ceResolveWorldBookEntryContextSuppression(base, parsedContent);
  parsedContent = suppression.parsedContent;

  const inferredId = String(base.key || base.id || base.characterId || base.charId || (parsedContent && parsedContent['0']) || '').trim();
  const inferredTitle = String(
    base.title
    || base.name
    || base.displayName
    || (parsedContent && parsedContent['1'] ? String(parsedContent['1']).split('|')[0] : '')
    || inferredId
  ).trim();
  const fallbackId = inferredId || String(base.id || '').trim() || (
    typeof crypto !== 'undefined' && crypto && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : ('wb_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8))
  );
  const inferredType = String(base.type || base.category || '').trim()
    || (ceIsLikelyCharacterWorldBookEntry(base) ? '人物' : '人物');
  const normalizedKeywords = suppression.suppressContextTrigger
    ? []
    : (Array.isArray(base.keywords) && base.keywords.length > 0
      ? base.keywords.map(function(item) {
          return String(item || '').trim();
        }).filter(Boolean)
      : (inferredTitle ? [inferredTitle] : []));
  const normalizedContent = typeof base.content === 'string'
    ? base.content
    : JSON.stringify(parsedContent && typeof parsedContent === 'object' ? parsedContent : {}, null, 2);

  return Object.assign({}, base, {
    id: String(base.id || fallbackId).trim() || fallbackId,
    key: String(base.key || inferredId || base.id || fallbackId).trim() || fallbackId,
    title: inferredTitle || '未知条目',
    name: String(base.name || inferredTitle || '未知条目').trim() || '未知条目',
    displayName: String(base.displayName || inferredTitle || '未知条目').trim() || '未知条目',
    content: normalizedContent,
    type: inferredType,
    category: String(base.category || inferredType).trim() || inferredType,
    enabled: base.enabled !== false,
    triggerMode: suppression.suppressContextTrigger
      ? 'green'
      : (String(base.triggerMode || '').trim() || 'green'),
    keywords: normalizedKeywords,
    depth: Number(base.depth || (knowledgeSearchGlobalConfig && knowledgeSearchGlobalConfig.worldBookSearchDepth) || 5) || 5,
    ceSuppressWorldBookContext: suppression.suppressContextTrigger === true
  });
}

function ceNormalizeWorldBookEntriesForFrontend(entries) {
  return (Array.isArray(entries) ? entries : []).filter(function(entry) {
    // Snapshot control records are not worldbook entities and must never acquire random IDs.
    return entry && typeof entry === 'object' && !entry._isFullSnapshot;
  }).map(function(entry) {
    return ceNormalizeWorldBookEntryForFrontend(entry);
  }).filter(function(entry) {
    return !!(entry && typeof entry === 'object');
  });
}

function ceReplaceWorldBookCacheArray(targetEntries, sourceEntries) {
  if (!Array.isArray(targetEntries)) return false;
  const cloned = ceNormalizeWorldBookEntriesForFrontend(sourceEntries);
  targetEntries.splice(0, targetEntries.length, ...cloned);
  return true;
}

function ceHasWorldBookEntriesPayload(entries) {
  return Array.isArray(entries) && entries.some(function(entry) {
    return !!(entry && typeof entry === 'object');
  });
}

function ceExtractWorldBookIdentityKeys(entry) {
  const keys = new Set();
  if (!entry || typeof entry !== 'object') return [];
  ceExtractWorldBookEntryIds(entry).forEach(function(id) {
    const normalized = ceNormalizeWorldBookId(id);
    if (normalized) keys.add(normalized);
  });
  [entry.title, entry.name, entry.displayName].forEach(function(title) {
    const normalized = String(title || '').trim();
    if (normalized) keys.add('title:' + normalized);
  });
  return Array.from(keys);
}

function ceSummarizeWorldBookEntryCoverage(entries) {
  const idSet = new Set();
  let contentTotal = 0;
  (Array.isArray(entries) ? entries : []).forEach(function(entry) {
    ceExtractWorldBookIdentityKeys(entry).forEach(function(id) {
      idSet.add(id);
    });
    if (entry && typeof entry.content === 'string') {
      contentTotal += entry.content.length;
    }
  });
  return {
    idSet,
    count: idSet.size,
    contentTotal,
  };
}

function ceShouldPromoteRecoveredWorldBookEntries(currentEntries, recoveredEntries) {
  const current = ceNormalizeWorldBookEntriesForFrontend(currentEntries);
  const recovered = ceNormalizeWorldBookEntriesForFrontend(recoveredEntries);
  if (recovered.length === 0) return false;
  if (current.length === 0) return true;

  const currentCoverage = ceSummarizeWorldBookEntryCoverage(current);
  const recoveredCoverage = ceSummarizeWorldBookEntryCoverage(recovered);
  let missingCurrentKeyCount = 0;
  currentCoverage.idSet.forEach(function(id) {
    if (!recoveredCoverage.idSet.has(id)) {
      missingCurrentKeyCount++;
    }
  });
  if (missingCurrentKeyCount > 0) return false;
  if (recoveredCoverage.count > currentCoverage.count) return true;
  return recoveredCoverage.contentTotal > currentCoverage.contentTotal + 40;
}

function ceBuildWorldBookEntryFromStateRow(charId, row) {
  if (!row || !charId || charId === 'TIME_LOCATION_ROW') return null;
  const rawName = (row['1'] || '').split('|')[0] || charId;
  let charName = rawName;
  try {
    if (typeof document !== 'undefined' && document && typeof document.createElement === 'function') {
      const div = document.createElement('div');
      div.innerHTML = rawName;
      charName = div.textContent || div.innerText || rawName;
    }
  } catch (e) {}
  charName = String(charName || rawName || charId).replace(/<[^>]*>/g, '').trim() || charId;
  return ceNormalizeWorldBookEntryForFrontend({
    key: charId,
    id: charId,
    title: charName,
    name: charName,
    displayName: charName,
    type: '人物',
    category: '人物',
    content: JSON.stringify(row, null, 2),
    enabled: true,
    triggerMode: 'green',
    keywords: charName ? [charName] : [],
    depth: knowledgeSearchGlobalConfig?.worldBookSearchDepth || 5
  });
}

function ceCollectWorldBookEntriesFromStateLike(stateLike, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const deletedSet = opts.deletedSet instanceof Set ? opts.deletedSet : null;
  const includePlayer = opts.includePlayer === true;
  const root = stateLike && typeof stateLike === 'object' && stateLike.currentState
    ? stateLike.currentState
    : stateLike;
  const table = root && typeof root === 'object' ? root['0'] : null;
  if (!table || typeof table !== 'object') return [];

  const collected = [];
  Object.entries(table).forEach(function([key, row]) {
    const charId = row && row['0'] ? row['0'] : key;
    if (!charId || charId === 'TIME_LOCATION_ROW') return;
    if (!includePlayer && charId === 'B1') return;
    if (deletedSet && deletedSet.has(String(charId))) return;
    const entry = ceBuildWorldBookEntryFromStateRow(charId, row);
    if (entry) collected.push(entry);
  });
  return collected;
}

function ceCollectWorldBookGlobalSourceCandidates() {
  const sources = [];
  const pushSource = function(sourceKey, entries) {
    if (!Array.isArray(entries) || entries.length === 0) return;
    sources.push({ sourceKey, entries });
  };

  try {
    if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)) {
      pushSource('allBiographyEntries(local)', allBiographyEntries);
    }
  } catch (e) {}

  if (typeof window !== 'undefined') {
    [
      'allBiographyEntries',
      'worldBookEntries',
      'worldbookEntries',
      'worldArchiveEntries',
      'worldArchiveCharacters',
      'worldArchiveList'
    ].forEach(function(key) {
      if (Array.isArray(window[key])) {
        pushSource('window.' + key, window[key]);
      }
    });
  }

  return sources;
}

function ceCollectWorldBookSourceCandidates(archive, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const deletedSet = opts.deletedSet instanceof Set ? opts.deletedSet : null;
  const sources = [];
  const pushSource = function(sourceKey, entries) {
    if (!Array.isArray(entries) || entries.length === 0) return;
    sources.push({ sourceKey, entries });
  };

  pushSource('state.worldBookEntries', archive?.data?.state?.worldBookEntries);

  try {
    if (Array.isArray(archive?.data?.logs) && archive.data.logs.length > 0) {
      const accumulatedEntries = ceAccumulateBiographyFromLogs(archive.data.logs, archive.data.logs.length - 1);
      pushSource('logs.accumulatedBiography', accumulatedEntries);
    }
  } catch (e) {}

  pushSource('logs.latestBiographySnapshot', ceGetLatestBiographySnapshot(archive));

  if (Array.isArray(archive?.data?.logs)) {
    let pushedEmbeddedWorldBookEntries = false;
    let pushedStateSnapshotEntries = false;
    for (let i = archive.data.logs.length - 1; i >= 0; i--) {
      const log = archive.data.logs[i];
      if (!log?.stateSnapshot) continue;
      try {
        const parsed = typeof log.stateSnapshot === 'string'
          ? JSON.parse(log.stateSnapshot)
          : log.stateSnapshot;
        if (!parsed || typeof parsed !== 'object') continue;
        if (!pushedEmbeddedWorldBookEntries && Array.isArray(parsed.worldBookEntries) && parsed.worldBookEntries.length > 0) {
          pushSource('logs[' + i + '].stateSnapshot.worldBookEntries', parsed.worldBookEntries);
          pushedEmbeddedWorldBookEntries = true;
        }
        if (!pushedStateSnapshotEntries) {
          const stateSnapshotEntries = ceCollectWorldBookEntriesFromStateLike(parsed, { deletedSet });
          if (Array.isArray(stateSnapshotEntries) && stateSnapshotEntries.length > 0) {
            pushSource('logs[' + i + '].stateSnapshot', stateSnapshotEntries);
            pushedStateSnapshotEntries = true;
          }
        }
        if (pushedEmbeddedWorldBookEntries && pushedStateSnapshotEntries) {
          break;
        }
      } catch (e) {}
    }
  }

  pushSource('archive.data.state.currentState', ceCollectWorldBookEntriesFromStateLike(archive?.data?.state?.currentState, { deletedSet }));
  if (Array.isArray(archive?.data?.state?.currentState?.worldBookEntries)) {
    pushSource('archive.data.state.currentState.worldBookEntries', archive.data.state.currentState.worldBookEntries);
  }

  return sources;
}

function ceResolveWritableWorldBookBaseline(archive, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const respectDeleted = opts.respectDeleted === true;
  const deletedSet = respectDeleted ? ceGetDeletedWorldBookIdSet() : null;
  const normalizeEntries = function(entries) {
    return ceNormalizeWorldBookEntriesForFrontend(entries).filter(function(entry) {
      return !(deletedSet && ceIsWorldBookEntryDeleted(entry, deletedSet));
    });
  };

  let entries = [];
  let source = 'none';

  try {
    if (typeof ceBuildAuthoritativeWorldBookSnapshot === 'function') {
      const snapshotEntries = ceBuildAuthoritativeWorldBookSnapshot(archive, {
        allowLatestLogFallback: true,
        respectDeleted: respectDeleted
      });
      const normalizedSnapshotEntries = normalizeEntries(snapshotEntries);
      if (normalizedSnapshotEntries.length > 0) {
        entries = normalizedSnapshotEntries;
        source = 'authoritative_snapshot';
      }
    }
  } catch (e) {}

  if (entries.length === 0 && typeof cePickWorldBookEntriesFromGlobals === 'function') {
    try {
      const globalEntries = cePickWorldBookEntriesFromGlobals();
      const normalizedGlobalEntries = normalizeEntries(globalEntries);
      if (normalizedGlobalEntries.length > 0) {
        entries = normalizedGlobalEntries;
        source = 'global_cache';
      }
    } catch (e) {}
  }

  if (entries.length === 0) {
    try {
      const runtimeState = typeof currentState !== 'undefined' ? currentState : null;
      const runtimeEntries = normalizeEntries(ceCollectWorldBookEntriesFromStateLike(runtimeState, { deletedSet }));
      if (runtimeEntries.length > 0) {
        entries = runtimeEntries;
        source = 'live_current_state';
      }
    } catch (e) {}
  }

  return {
    entries,
    source
  };
}

function ceCommitWorldBookEntriesToArchiveState(archive, nextEntries, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const reason = String(opts.reason || 'unknown').trim();
  const allowEmpty = opts.allowEmpty === true;
  const allowShrink = opts.allowShrink === true;
  const respectDeleted = opts.respectDeleted === true;
  const deletedSet = respectDeleted ? ceGetDeletedWorldBookIdSet() : null;
  const normalizeEntries = function(entries) {
    return ceNormalizeWorldBookEntriesForFrontend(entries).filter(function(entry) {
      return !(deletedSet && ceIsWorldBookEntryDeleted(entry, deletedSet));
    });
  };

  if (!archive || typeof archive !== 'object') {
    return { written: false, reason: 'invalid_archive', entries: [], missingIds: [] };
  }
  if (!archive.data) archive.data = {};
  if (!archive.data.state) archive.data.state = {};

  const currentEntries = normalizeEntries(Array.isArray(archive.data.state.worldBookEntries)
    ? archive.data.state.worldBookEntries
    : []);
  const normalizedNextEntries = normalizeEntries(nextEntries);

  if (!ceHasWorldBookEntriesPayload(normalizedNextEntries) && !allowEmpty) {
    console.warn(`[并发演化][worldbook] 拒绝写入空 worldBookEntries (${reason || 'unknown'})`);
    return { written: false, reason: 'empty_rejected', entries: currentEntries, missingIds: [] };
  }

  const currentCoverage = ceSummarizeWorldBookEntryCoverage(currentEntries);
  const nextCoverage = ceSummarizeWorldBookEntryCoverage(normalizedNextEntries);
  const missingIds = [];
  currentCoverage.idSet.forEach(function(id) {
    if (!nextCoverage.idSet.has(id)) {
      missingIds.push(id);
    }
  });

  if (!allowShrink && missingIds.length > 0) {
    console.warn(`[并发演化][worldbook] 拒绝缩水写回 worldBookEntries (${reason || 'unknown'})`, {
      currentCount: currentCoverage.count,
      nextCount: nextCoverage.count,
      missingIds: missingIds.slice(0, 20)
    });
    return { written: false, reason: 'shrink_rejected', entries: currentEntries, missingIds };
  }

  archive.data.state.worldBookEntries = JSON.parse(JSON.stringify(normalizedNextEntries));
  return { written: true, reason: 'ok', entries: archive.data.state.worldBookEntries, missingIds: [] };
}

function ceSyncWorldBookCachesFromStateEntries(stateEntries, reason = '', options = {}) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  if (frStrict) return false;
  const sourceEntries = Array.isArray(stateEntries) ? stateEntries : [];
  const opts = options && typeof options === 'object' ? options : {};
  const allowEmpty = opts.allowEmpty === true;
  const touched = [];
  let localBiographyEntries = null;

  if (!ceHasWorldBookEntriesPayload(sourceEntries) && !allowEmpty) {
    let existingCount = 0;
    try {
      const picked = typeof cePickWorldBookEntriesFromGlobals === 'function'
        ? cePickWorldBookEntriesFromGlobals()
        : [];
      existingCount = Array.isArray(picked) ? picked.length : 0;
    } catch (e) {}
    console.warn(`[并发演化][worldbook] 拒绝用空 worldBookEntries 覆盖前端缓存(${reason || 'unknown'})${existingCount > 0 ? ('，当前缓存保留 ' + existingCount + ' 条') : ''}`);
    return false;
  }

  try {
    if (typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)) {
      localBiographyEntries = allBiographyEntries;
      if (ceReplaceWorldBookCacheArray(allBiographyEntries, sourceEntries)) {
        touched.push('allBiographyEntries(local)');
      }
    }
  } catch (e) {}

  if (typeof window !== 'undefined') {
    const cacheKeys = [
      'allBiographyEntries',
      'worldBookEntries',
      'worldbookEntries',
      'worldArchiveEntries',
      'worldArchiveCharacters',
      'worldArchiveList'
    ];
    cacheKeys.forEach(function(key) {
      if (!Array.isArray(window[key])) {
        window[key] = [];
      }
      if (key === 'allBiographyEntries' && localBiographyEntries && window[key] === localBiographyEntries) {
        return;
      }
      if (ceReplaceWorldBookCacheArray(window[key], sourceEntries)) {
        touched.push('window.' + key);
      }
    });
  }

  if (touched.length > 0) {
    console.log(`[并发演化][worldbook] 已从权威存档同步 ${sourceEntries.length} 个条目到缓存(${reason || 'unknown'}): ${touched.join(', ')}`);
    scheduleConcurrentEvolutionWorldbookRefresh();
    return true;
  }
  return false;
}

function syncConcurrentEvolutionWorldbookCache(targetId, charData, serialized) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  if (frStrict) return;
  const charName = (charData?.['1'] || '').split('|')[0] || '';
  const localBiographyEntries = (() => {
    try {
      return typeof allBiographyEntries !== 'undefined' && Array.isArray(allBiographyEntries)
        ? allBiographyEntries
        : null;
    } catch (e) {
      return null;
    }
  })();

  let updated = false;
  const cacheTargets = [
    { key: 'allBiographyEntries(local)', entries: localBiographyEntries },
    { key: 'window.allBiographyEntries', entries: typeof window !== 'undefined' ? window.allBiographyEntries : null },
    { key: 'window.worldBookEntries', entries: typeof window !== 'undefined' ? window.worldBookEntries : null },
    { key: 'window.worldbookEntries', entries: typeof window !== 'undefined' ? window.worldbookEntries : null },
    { key: 'window.worldArchiveEntries', entries: typeof window !== 'undefined' ? window.worldArchiveEntries : null },
    { key: 'window.worldArchiveCharacters', entries: typeof window !== 'undefined' ? window.worldArchiveCharacters : null },
    { key: 'window.worldArchiveList', entries: typeof window !== 'undefined' ? window.worldArchiveList : null }
  ];

  cacheTargets.forEach(function(target) {
    if (!Array.isArray(target.entries)) return;
    if (target.key === 'window.allBiographyEntries' && localBiographyEntries && target.entries === localBiographyEntries) return;
    if (updateConcurrentEvolutionEntryInArray(target.entries, targetId, serialized, charName)) {
      updated = true;
    }
  });

  if (updated) {
    ceLogTargetInfoDedup(targetId, `[并发演化-WorldBook][${targetId}] 已更新`);
    scheduleConcurrentEvolutionWorldbookRefresh();
  }
}

// [简化] ceGetWorldBookOverrideMap, ceRegisterWorldBookOverride, ceApplyWorldBookOverrides 已移除
// 系统现在依赖原版的日志快照机制

// Decode log control records before promoting a biography snapshot into archive state.
function ceResolveBiographySnapshotDataEntries(logs, logIndex, snapshot) {
  const priorLogs = (Array.isArray(logs) ? logs.slice(0, Math.max(0, logIndex)) : []).map(log => ({
    biographySnapshot: JSON.parse(JSON.stringify(Array.isArray(log?.biographySnapshot) ? log.biographySnapshot : []))
  }));
  priorLogs.push({ biographySnapshot: JSON.parse(JSON.stringify(Array.isArray(snapshot) ? snapshot : [])) });
  return ceNormalizeWorldBookEntriesForFrontend(ceAccumulateBiographyFromLogs(priorLogs, priorLogs.length - 1));
}

function ceAccumulateBiographyFromLogs(logs, endIndex) {
  if (!Array.isArray(logs) || logs.length === 0) return [];
  const maxIndex = Math.min(
    typeof endIndex === 'number' && !isNaN(endIndex) ? endIndex : logs.length - 1,
    logs.length - 1
  );
  const merged = new Map();

  for (let i = 0; i <= maxIndex; i++) {
    const log = logs[i];
    const snapshot = log?.biographySnapshot;
    if (!Array.isArray(snapshot)) continue;

    const hasFullMarker = snapshot.some(entry => entry && entry._isFullSnapshot);
    if (hasFullMarker) {
      merged.clear();
    }

    snapshot.forEach(entry => {
      if (!entry || typeof entry !== 'object') return;
      if (entry._isFullSnapshot) return;
      const entryId = entry.key || entry.id || entry.characterId || entry.charId || entry.title || entry.name;
      if (!entryId) return;
      if (entry._deleted) {
        merged.delete(entryId);
        return;
      }
      ceMergeWorldBookEntry(merged, entry);
    });
  }

  return Array.from(merged.values());
}

// [简化] 仅清理并发演化的本轮处理状态，不触碰 allBiographyEntries 等全局变量
// 用于回溯场景：原版 loadStateFromLog 已正确恢复世界档案
function ceResetInternalCachesOnly(options = {}) {
  const { reason = 'rollback', silent = false } = options || {};

  // 清理本轮处理状态缓存
  if (typeof window !== 'undefined') {
    // 并发演化处理状态
    window._concurrentEvolutionProcessedIds = null;
    window._concurrentEvolutionProcessedNames = null;
    window._concurrentEvolutionDeletedIds = null;
    window._concurrentEvolutionRerollStateApplied = false;
    window._concurrentEvolutionPromise = null;
    window._ceLastThinkingResults = null;

    // API跳过标记
    window._ceSkipThinkingApi = false;
    window._ceSkipWorldEvolutionApi = false;
    window._ceSkipSegmentedMemoryStandaloneApi = false;
    window._ceSkipThinkingStatus = false;
    window._ceBiographyCompressionTriggeredThisRun = false;
    window._ceCurrentSummaryWriterMode = 'concurrent_evolution';
    window._cePendingMiscSummary = null;

    // 登场判断结果
    window.lastEntryDecisionResult = null;
    window.pendingReentryForConcurrentEvolution = null;
    window.pendingNewCharacterForConcurrentEvolution = null;
    window._entryDecisionDeedsUpdated = null;

    // 提前发送的请求

    // 回溯后旧的删除标记不再有效
    if (window._ceDeletedWorldBookIds) {
      window._ceDeletedWorldBookIds.clear();
    }
    window._ceDeletedWorldBookIdsPendingClear = false;
  }

  if (!silent) {
    console.log(`[并发演化][简化] 本轮处理状态已清理: reason=${reason}`);
  }
}

// [简化] ceResetWorldBookCachesAfterRollback 已简化为空操作
// 系统现在依赖原版 loadStateFromLog 的回溯机制
async function ceResetWorldBookCachesAfterRollback(options = {}) {
  const { reason = 'rollback', silent = false } = options || {};
  // 仅清理本轮处理状态
  ceResetInternalCachesOnly({ reason, silent });
  return { rebuilt: false, count: 0 };
}

function ceGetLatestBiographySnapshot(archive) {
  try {
    if (!archive?.data?.logs) return null;
    for (let i = archive.data.logs.length - 1; i >= 0; i--) {
      const log = archive.data.logs[i];
      if (Array.isArray(log?.biographySnapshot) && log.biographySnapshot.length > 0) {
        return log.biographySnapshot;
      }
    }
  } catch (e) {}
  return null;
}

function ceMergeWorldBookEntry(map, entry) {
  if (!entry || typeof entry !== 'object') return;
  if (entry._isFullSnapshot) return;

  const entryId = entry.key || entry.id || entry.characterId || entry.charId || '';
  const entryTitle = entry.title || entry.name || entry.displayName || '';
  if (!entryId && !entryTitle) return;

  let existingKey = null;
  if (entryId && map.has(entryId)) {
    existingKey = entryId;
  } else if (entryTitle) {
    for (const [key, value] of map.entries()) {
      const valueTitle = value?.title || value?.name || value?.displayName || '';
      if (valueTitle && valueTitle === entryTitle) {
        existingKey = key;
        break;
      }
    }
  }

  const contentLength = typeof entry.content === 'string' ? entry.content.length : 0;
  if (!existingKey) {
    map.set(entryId || entryTitle, entry);
    return;
  }

  const existing = map.get(existingKey);
  const existingContentLength = typeof existing?.content === 'string' ? existing.content.length : 0;
  if (contentLength > existingContentLength) {
    map.set(existingKey, entry);
    return;
  }
  if (entryId && !existing?.key) existing.key = entryId;
  if (entryTitle && !existing?.title) existing.title = entryTitle;
}

function ceCollectWorldBookEntriesFromSources(archive, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const respectDeleted = opts.respectDeleted === true;
  const watchIds = ceGetDebugWatchIds();
  const watchSet = watchIds ? new Set(watchIds) : null;
  const deletedSet = respectDeleted ? ceGetDeletedWorldBookIdSet() : null;
  const watchHits = watchSet ? new Set() : null;
  let deletedFiltered = 0;
  const merged = new Map();
  const sourceCandidates = ceCollectWorldBookSourceCandidates(archive, { deletedSet });

  if (sourceCandidates.length === 0) {
    console.log('[并发演化][worldbook][source] 未发现可用世界档案源，按空基线处理');
    return [];
  }

  const sourceSummaries = [];
  sourceCandidates.forEach(function(source) {
    const normalizedEntries = ceNormalizeWorldBookEntriesForFrontend(source.entries).filter(function(entry) {
      if (!entry || typeof entry !== 'object') return false;
      if (deletedSet && ceIsWorldBookEntryDeleted(entry, deletedSet)) {
        deletedFiltered++;
        return false;
      }
      return true;
    });
    if (normalizedEntries.length === 0) return;
    sourceSummaries.push(`${source.sourceKey}(${normalizedEntries.length})`);
    normalizedEntries.forEach(function(entry) {
      const entryId = entry.key || entry.id || entry.characterId || entry.charId;
      if (watchSet && entryId && watchSet.has(String(entryId))) {
        watchHits.add(String(entryId));
      }
      ceMergeWorldBookEntry(merged, entry);
    });
  });

  const mergedEntries = Array.from(merged.values());
  const normalizedStateEntries = ceNormalizeWorldBookEntriesForFrontend(
    Array.isArray(archive?.data?.state?.worldBookEntries) ? archive.data.state.worldBookEntries : []
  ).filter(function(entry) {
    return !(deletedSet && ceIsWorldBookEntryDeleted(entry, deletedSet));
  });

  if (ceShouldPromoteRecoveredWorldBookEntries(normalizedStateEntries, mergedEntries)) {
    console.log(`[并发演化][worldbook][source] 检测到 state.worldBookEntries 疑似降级，已采用多源重建结果: state=${normalizedStateEntries.length}, merged=${mergedEntries.length}`);
  }

  const sourceText = sourceSummaries.length > 0 ? sourceSummaries.join(', ') : 'none';
  if (watchSet) {
    const hitList = watchHits && watchHits.size > 0 ? Array.from(watchHits).join(', ') : '无';
    const deletedSuffix = deletedFiltered > 0 ? ` deletedFiltered=${deletedFiltered}` : '';
    console.log(`[并发演化][worldbook][source] ${sourceText} => merged(${mergedEntries.length}) watchHits=${hitList}${deletedSuffix}`);
  } else {
    const deletedSuffix = deletedFiltered > 0 ? ` deletedFiltered=${deletedFiltered}` : '';
    console.log(`[并发演化][worldbook][source] ${sourceText} => merged(${mergedEntries.length})${deletedSuffix}`);
  }

  if (watchSet) {
    ceLogWatchHitsForEntries('[并发演化][worldbook][merged]', mergedEntries, watchSet);
  }
  return mergedEntries;
}

function ceBuildAuthoritativeWorldBookSnapshot(archive, options = {}) {
  const opts = options && typeof options === 'object' ? options : {};
  const deletedSet = opts.respectDeleted === true ? ceGetDeletedWorldBookIdSet() : null;
  const normalizeEntries = function(entries) {
    return ceNormalizeWorldBookEntriesForFrontend(entries).filter(function(entry) {
      return !(deletedSet && ceIsWorldBookEntryDeleted(entry, deletedSet));
    });
  };
  try {
    const mergedEntries = ceCollectWorldBookEntriesFromSources(archive, opts);
    const normalizedMergedEntries = normalizeEntries(mergedEntries);
    if (normalizedMergedEntries.length > 0) {
      return normalizedMergedEntries;
    }
  } catch (e) {}

  const stateEntries = Array.isArray(archive?.data?.state?.worldBookEntries)
    ? archive.data.state.worldBookEntries
    : [];
  const normalizedStateEntries = normalizeEntries(stateEntries);
  if (normalizedStateEntries.length > 0) {
    return normalizedStateEntries;
  }

  if (opts.allowLatestLogFallback === false) {
    return [];
  }

  const latestSnapshot = ceGetLatestBiographySnapshot(archive);
  const normalizedLatestSnapshot = normalizeEntries(latestSnapshot);
  return normalizedLatestSnapshot.length > 0
    ? normalizedLatestSnapshot
    : [];
}

function ceSummarizeWorldBookEntries(entries, limit = 50) {
  const list = [];
  if (Array.isArray(entries)) {
    entries.forEach(entry => {
      if (!entry || typeof entry !== 'object') return;
      const id = entry.key || entry.id || entry.characterId || entry.charId || '';
      const name = entry.title || entry.name || entry.displayName || '';
      const label = name ? `${id || name}:${name}` : id;
      if (label) list.push(label);
    });
  }
  const count = list.length;
  const truncated = count > limit;
  const items = truncated ? list.slice(0, limit) : list;
  return { count, items, truncated };
}

function ceLogWorldBookList(label, entries) {
  const summary = ceSummarizeWorldBookEntries(entries);
  console.log(`[并发演化][worldbook] ${label} count=${summary.count}${summary.truncated ? ' (截断)' : ''}`, summary.items);
}

async function ceLogWorldBookSnapshot(label) {
  try {
    if (!db?.archives?.get || !currentArchiveName) return;
    const archive = await db.archives.get(currentArchiveName);
    const entries = ceCollectWorldBookEntriesFromSources(archive);
    ceLogWorldBookList(label, entries);
  } catch (e) {
    console.warn(`[并发演化][worldbook] ${label} 获取失败:`, e);
  }
}

function ceSafeClone(value) {
  if (typeof structuredClone === 'function') {
    try {
      return structuredClone(value);
    } catch (e) {}
  }
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (e) {
    return value;
  }
}

function ceLogLargeText(tag, label, text, chunkSize = 8000) {
  if (typeof text !== 'string') {
    console.log(`${tag} ${label}`, text);
    return;
  }
  if (!text) {
    console.log(`${tag} ${label} (empty)`);
    return;
  }
  const total = Math.ceil(text.length / chunkSize);
  for (let i = 0; i < total; i++) {
    const start = i * chunkSize;
    const end = Math.min(text.length, start + chunkSize);
    const chunk = text.slice(start, end);
    console.log(`${tag} ${label} [${i + 1}/${total}]`, chunk);
  }
}

function ceIsLikelyCharacterWorldBookEntry(entry) {
  if (!entry || typeof entry !== 'object') return false;
  const id = entry.key || entry.id || entry.characterId || entry.charId || '';
  if (typeof id === 'string') {
    if (id === 'B1' || id.startsWith('C_') || id.startsWith('G_') || ceIsBeastId(id) || id.startsWith('B_')) {
      return true;
    }
  }
  const typeRaw = entry.type || entry.category || '';
  const typeText = typeof typeRaw === 'string' ? typeRaw : String(typeRaw || '');
  if (typeText.includes('人物') || typeText.includes('角色')) return true;
  const typeLower = typeText.toLowerCase();
  if (typeLower.includes('npc') || typeLower.includes('character')) return true;
  return false;
}

function ceFilterWorldBookCharacterEntries(entries) {
  if (!Array.isArray(entries)) return [];
  const filtered = entries.filter(ceIsLikelyCharacterWorldBookEntry);
  return filtered.length > 0 ? filtered : entries;
}

