async function ceExecuteItemOperationsWithUi(operations, options = {}) {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
  const opts = options || {};
  const safeOperations = Array.isArray(operations) ? operations : [];
  if (safeOperations.length === 0 && !opts.npcLoadoutIds?.length) {
    return ceBuildEmptyItemExecutionResult();
  }

  const executedOps = await executeItemOperations(safeOperations, {npcLoadoutIds:opts.npcLoadoutIds,techniqueStory:opts.techniqueStory});
  if (frStrict) frAssertCanonCommit();
  const successCount = executedOps.filter(item => item && item.success).length;
  const failCount = executedOps.filter(item => !item || !item.success).length;
  if (!frStrict && opts.syncState !== false && typeof syncStateFromTables === 'function') {
    syncStateFromTables();
  }
  if (!frStrict && opts.renderInventory !== false && typeof renderInventory === 'function') {
    renderInventory(typeof inventoryItems !== 'undefined' ? inventoryItems : undefined);
  }
  return Object.assign(ceBuildEmptyItemExecutionResult(), {
    executedOps,
    noOperations: executedOps.length === 0,
    successCount,
    failCount
  });
}

