    requiredTargetIds: baseRequiredTargetIds,
    coveredTargetIds: coveredTargetIds,
    missingTargetIds: missingTargetIds,
    replayBoundary: replayBoundary,
    replayMode: sharedContext.originalTimelineReplayMode || (replayBoundary && replayBoundary.replayMode) || '',
    replayDeadline: sharedContext.originalTimelineReplayDeadline || (replayBoundary && replayBoundary.deadlineTime) || '',
    replayStoryReview: sharedContext.originalTimelineReplayStoryReview || '',
    progressKey: sharedContext.originalTimelineProgressKey || '',
