    progressPendingCount: replayBoundary && Number.isFinite(replayBoundary.progressPendingCount) ? replayBoundary.progressPendingCount : 0,
    totalEventCount: replayBoundary && Number.isFinite(replayBoundary.totalEventCount) ? replayBoundary.totalEventCount : 0,
    progressCompleted: !!(replayBoundary && replayBoundary.progressCompleted),
    zeroDeltaSkipped: zeroDeltaSkipped,
    proposalOnly: true,
    committedBySystem: false,
    skipped: !!(phaseResult && phaseResult.skipped) || zeroDeltaSkipped,
    reason: phaseResult && phaseResult.skipped
