            disabledTargetIds: targets.filter(target => !preset.prompts?.[target.type]?.enabled).map(target => target.id),
            disabledTargetTypes: ['player','npc','beast'].filter(type => !preset.prompts?.[type]?.enabled),
            entryTargetIds: options.entryTargetIds || targets.map(target => target.id),
