      let note=document.getElementById('fr-preset-compat-note');
      if(!note){note=document.createElement('p');note.id='fr-preset-compat-note';note.style.cssText='font-size:12px;color:var(--text-secondary);margin:8px 0';presetSelect.insertAdjacentElement('afterend',note);}
      const updatePresetNote=function(){const current=(presetSelect._frPresets||[]).find(p=>p.id===presetSelect.value);const warnings=current?.frPresetCompat?.warnings||[];note.textContent=warnings.length?'保留了 '+warnings.length+' 项自定义规则，请在规则编辑中核对适配。':'已适配独立补演；普通变量演化规则保留。';};
      presetSelect._frUpdateNote=updatePresetNote;
