function renderBeastSkillSection(skillStr) {
  if (!skillStr || !skillStr.trim()) {
    return '<div class="beast-skill-empty">尚未觉醒</div>';
  }
  var skills = skillStr.split('|').map(function(s) { return s.trim(); }).filter(Boolean).map(function(skill) {
    var m = skill.match(/^(.+?)\((.+)\)$/);
    if (m) return { name: m[1].trim(), desc: m[2].trim() };
    return { name: skill, desc: '' };
  });
  if (skills.length === 0) {
    return '<div class="beast-skill-empty">尚未觉醒</div>';
  }
  return '<div class="beast-skills-list">' + skills.map(function(s) {
    return '<div class="beast-skill-item">' +
      '<div class="beast-skill-name"><i class="fas fa-bolt" style="font-size:0.75em;margin-right:4px;"></i>' + s.name + '</div>' +
      (s.desc ? '<div class="beast-skill-desc">' + s.desc + '</div>' : '') +
    '</div>';
  }).join('') + '</div>';
}

