  if (!runtimeGlobal || runtimeGlobal.__MORTAL_TRAIT_ATTR_PROMPT_SNAPSHOT_V1__) return;
  runtimeGlobal.__MORTAL_TRAIT_ATTR_PROMPT_SNAPSHOT_V1__ = true;

