  const originalGeneratePrettySnapshotForAI = generatePrettySnapshotForAI;

  const REQUIRED_NOTE = '（含装备/功法/法宝/词条和生效状态，勿重复计算）';
  const SPEED_EXPLANATION = '（基准效率，200%=双倍速；100=正常效率，200=双倍效率）';

