      if (raw && typeof raw === 'object') {
        const cur = raw.current == null || raw.current === '' ? NaN : Number(raw.current);
        const max = raw.max == null || raw.max === '' ? NaN : Number(raw.max);
        return {
          current: raw.numericValidity?.current==='invalid' ? '非法' : raw.numericMissing || raw.numericValidity?.current==='missing' ? '未知' : Number.isFinite(cur) ? Number(cur.toFixed(6)) : '未知',
          max: raw.numericValidity?.max==='invalid' ? '非法' : raw.numericMissing || raw.numericValidity?.max==='missing' ? '未知' : Number.isFinite(max) ? Number(max.toFixed(6)) : '未知',
        };
      }
