      if (typeof remarkText !== 'string' || !remarkText || !key) return '';
      const segments = remarkText.split('|');
      for (let idx = 0; idx < segments.length; idx += 1) {
        const segment = segments[idx];
        const delimiterIndex = segment.indexOf(':');
        if (delimiterIndex < 0) continue;
        const fieldName = String(segment.slice(0, delimiterIndex) || '').trim();
        if (fieldName !== key) continue;
        return String(segment.slice(delimiterIndex + 1) || '').trim();
      }
