// --- 新增：显示属性详情悬浮窗函数 ---
function showAttrDetailTooltip(event, label, value) {
const tooltip = document.getElementById('attr-detail-tooltip');
if (!tooltip) return;

tooltip.innerHTML = `
<h5>${label}</h5>
<p>${value}</p>
`;

// 计算位置
const rect = event.currentTarget.getBoundingClientRect();
let top = rect.top;
let left = rect.right + 10; // 默认显示在右侧

// 简单的边界检查
if (left + 200 > window.innerWidth) {
left = rect.left - 210; // 如果右边不够，显示在左边
}
if (top + 100 > window.innerHeight) {
top = window.innerHeight - 100;
}

tooltip.style.top = `${top}px`;
tooltip.style.left = `${left}px`;
tooltip.style.opacity = '1';

// 点击任意地方关闭
const closeTooltip = () => {
tooltip.style.opacity = '0';
document.removeEventListener('click', closeTooltip);
};
// 延迟绑定，防止当前点击立即触发关闭
setTimeout(() => document.addEventListener('click', closeTooltip), 0);
}

        function renderInventory(items) {
console.log('【调试】renderInventory 被调用');
            console.log('【调试】传入的 items 数量:', items ? items.length : 'undefined');
            console.log('【调试】全局 inventoryItems 数量:', window.inventoryItems ? window.inventoryItems.length : 'undefined');

            if (!document.getElementById('inventory-header-container')) initInventoryUI();

            const latestItems = getLatestInventoryItems([items, window.inventoryItems, (typeof inventoryItems !== 'undefined' ? inventoryItems : [])]);
            items = latestItems;

            const inventoryGrid = document.getElementById('inventory-grid');
            if (!inventoryGrid) return;
            inventoryGrid.innerHTML = '';
            const fragment = document.createDocumentFragment();

            const equippedItemIds = new Set();
            const api = window.getTheaterAPI ? window.getTheaterAPI() : null;

            let livePlayerData = null;
            if (api && api.getPlayerData) {
                try {
                    livePlayerData = api.getPlayerData();
                } catch(e) {
                    console.warn('【物品分类】实时获取玩家数据失败:', e);
                }
            }
            const playerDataToUse = livePlayerData || (typeof currentPlayerData !== 'undefined' ? currentPlayerData : null);

            if (playerDataToUse) {
                ['weapon', 'armor', 'technique', 'treasure'].forEach(k => {
                    (playerDataToUse[k] || []).forEach(i => i && equippedItemIds.add(i.id));
                });
            }

            const sourceItems = latestItems;
            let itemsToShow = sourceItems.filter(item => !equippedItemIds.has(item.id));

            if (sourceItems.length > 0 && itemsToShow.length === 0 && equippedItemIds.size >= sourceItems.length) {
                console.warn('【物品分类】装备去重后结果为空，疑似把全部库存误判为已装备，已回退显示完整库存。', {
                    sourceCount: sourceItems.length,
                    equippedCount: equippedItemIds.size
                });
                itemsToShow = sourceItems.slice();
            }

            console.log('【调试】当前完整背包渲染数量:', itemsToShow.length, '当前筛选:', window.currentInvFilter || 'all', '已装备ID数:', equippedItemIds.size);

            if (itemsToShow.length === 0) {
                for (let i = 0; i < 15; i++) {
                    const emptySlot = document.createElement('div');
                    emptySlot.className = 'inventory-slot empty-slot';
                    fragment.appendChild(emptySlot);
                }
            } else {
                const defaultIconMap = {
                    '武器': 'fa-sword', '护甲': 'fa-shield-alt', '法宝': 'fa-gem',
                    '丹药': 'fa-flask', '符箓': 'fa-scroll', '消耗品': 'fa-box-open',
                    '功法': 'fa-book', '秘籍': 'fa-book-open', '材料': 'fa-cubes',
                    '珍宝': 'fa-crown', '杂物': 'fa-archive', '默认': 'fa-question-circle'
                };
                const iconMap = (typeof itemIconMap !== 'undefined') ? itemIconMap : defaultIconMap;

                itemsToShow.forEach(item => {
                    const slot = document.createElement('div');
                    slot.className = 'inventory-slot';
                    slot.dataset.itemId = item.id;

                    const presentation = window.FrItemPresentation.rarity(item);
                    const itemQty = item.quantity || item.count || 1;
                    const displayMeta = buildInventoryDisplayName(item.name || '', 5);
                    const plainName = displayMeta.plainName;
                    const accentColor = presentation.color;
                    const displayHtml = '<span style="color:' + accentColor + '">' + escapeInventoryHtml(displayMeta.displayText || plainName) + '</span>';
                    const qtyHtml = itemQty > 1
                        ? '<span class="inventory-slot-quantity" style="background:' + accentColor + '; color:#111;">' + itemQty + '</span>'
                        : '';

                    slot.style.borderColor = accentColor;
                    slot.style.boxShadow = 'inset 0 0 15px rgba(0,0,0,0.5), 0 0 0 1px ' + accentColor + '33';
                    slot.title = plainName + '\n类型: ' + (item.type || '杂物') + (presentation.label ? '\n' + presentation.label : '');
                    slot.style.color = accentColor;

                    window.FrItemPresentation.decorate(slot,item);
              slot.innerHTML = window.FrItemPresentation.icon(item,'inventory-slot-icon') +
                        '<span class="inventory-slot-name">' + displayHtml + '</span>' +
                        qtyHtml;

                    slot.addEventListener('click', (e) => {
                        e.stopPropagation();
                        if (typeof showItemDetail === 'function') {
                            showItemDetail(item);
                        } else if (api && api.showItemDetail) {
                            api.showItemDetail(item);
                        } else {
                            alert('【' + (plainName || '未知物品') + '】');
                        }
                    });

                    fragment.appendChild(slot);
                });

                const currentCount = itemsToShow.length;
                const MIN_TOTAL = 15;
                const COLS = 3;
                let targetCount = currentCount;

                if (targetCount < MIN_TOTAL) {
                    targetCount = MIN_TOTAL;
                } else {
                    const remainder = targetCount % COLS;
                    if (remainder !== 0) {
                        targetCount += (COLS - remainder);
                    }
                }

                const slotsToAdd = targetCount - currentCount;
                for (let i = 0; i < slotsToAdd; i++) {
                    const emptySlot = document.createElement('div');
                    emptySlot.className = 'inventory-slot empty-slot';
                    fragment.appendChild(emptySlot);
                }
            }

            inventoryGrid.appendChild(fragment);
            if (typeof window.applyInventoryFilterToGrid === 'function') {
                setTimeout(function() {
                    try {
                        window.applyInventoryFilterToGrid();
                    } catch(e) {}
                }, 0);
            }
}
        async function loadState(state, fullArchiveData = null) {
          const deepCopy = obj => JSON.parse(JSON.stringify(obj));

          WORLD_MAP_DATA = deepCopy(state.worldMap || DEFAULT_WORLD_MAP_DATA);

          currentState = state.currentState;
          bondedCharacters = state.bondedCharacters || {};

          syncStateFromTables();

          renderInventory(inventoryItems);
          renderPlayerAttributes(currentPlayerData);
          await updateAvatar(currentPlayerData);
          await updateMiniMap();

          await manageImageTaggingApiSettings();
          await loadChatBackgroundSettings();
          await manageKnowledgeSearchApiSettings();

          dailyPaperContextForNextMessage = '';
          lastDailyPaperContent = '';
          lastAiStoryText = '';
          lastUnoptimizedAiStoryText = '';

          if (fullArchiveData && Array.isArray(fullArchiveData.logs)) {
            let foundEmpty = false;
            let lastLogWithBio = [...fullArchiveData.logs].reverse().find(log => {
              if (log.biographySnapshot && Array.isArray(log.biographySnapshot)) {
                if (log.biographySnapshot.length > 0) {
                  return true;
                }
                foundEmpty = true;
              }
              return false;
            });
            if (!lastLogWithBio && foundEmpty) {
              lastLogWithBio = { biographySnapshot: [] };
            }

            if (lastLogWithBio) {
              allBiographyEntries = lastLogWithBio.biographySnapshot;
            } else {
              allBiographyEntries = fullArchiveData.state?.worldBookEntries || [];
            }
          }
        }

        
        // --- 性能优化工具：防抖函数 ---
        function debounce(func,wait){
  let timeout=null,args,context,pending=null;
  function invoke(){timeout=null;var work=Promise.resolve(func.apply(context,args));pending=work;work.finally(()=>{if(pending===work)pending=null;}).catch(e=>console.error('[防抖保存]',e));return work;}
  function wrapped(...values){args=values;context=this;clearTimeout(timeout);timeout=setTimeout(invoke,wait);}
  wrapped.cancel=function(){clearTimeout(timeout);timeout=null;};
  wrapped.flush=function(){if(timeout!==null){clearTimeout(timeout);return invoke();}return pending||Promise.resolve();};
  return wrapped;
}
            

        // 原始保存函数重命名
        async function _internalSaveCurrentState() {
  const frStrict = typeof frInCanonCommit === 'function' && frInCanonCommit();
  if (frStrict) frAssertCanonCommit();
          if (!currentArchiveName) { if (frStrict) throw new Error('补演提交：没有当前存档'); return { ok: false, reason: '没有当前存档' }; }
          const savingArchiveName = currentArchiveName;

          try {
            // 普通防抖保存也会与补演提交交错。读取旧整档后再单独 put，
            // 会抹掉这期间已提交的人物档案和楼层快照；读写必须同笔串行事务。
            const saveArchive = async function() {
            const frExistingArchive = await db.archives.get(savingArchiveName);
            if (frStrict && !frExistingArchive) throw new Error('补演提交：当前存档不存在');
            const archive = frExistingArchive || { name: savingArchiveName, data: {} };
            if (frStrict) frAssertCanonCommit();
            if (currentArchiveName !== savingArchiveName) { if (frStrict) throw new Error('补演提交：保存期间已切换存档'); return { ok: false, reason: '保存期间已切换存档' }; }
            if (!archive.data.state) {
              archive.data.state = {};
            }

            archive.data.state.currentState = currentState;
            archive.data.state.bondedCharacters = bondedCharacters;
            archive.data.state.rpgMaps = {};
            archive.data.state.worldMap = WORLD_MAP_DATA;
            if (!archive.data.state.npcAvatars) archive.data.state.npcAvatars = {};

            if (frStrict) frAssertCanonCommit();
            await db.archives.put(archive);
            if (frStrict) frAssertCanonCommit();
            return { ok: true, archiveName: savingArchiveName };
            };
            // strictApply也可能由事务外的局部重跑设置；始终建立事务，
            // 若已有补演外层事务，Dexie会沿用该事务的原子提交边界。
            const savedResult = await db.transaction('rw', db.archives, saveArchive);
            if (!savedResult.ok) return savedResult;

            // 自动同步到云端
            if (!frStrict && cloudStorageConfig && cloudStorageConfig.enabled && cloudStorageConfig.autoSync) {
              // 异步执行，不阻塞
              uploadArchiveToCloud(savingArchiveName, true).catch(err => {
                console.error('[自动同步] 失败:', err);
              });
            }
            return { ok: true, archiveName: savingArchiveName };
          } catch (e) {
      if (frStrict) throw e;
            console.error('保存当前状态到数据库时出错: ', e);
            showCustomAlert('紧急错误：保存存档失败，请检查控制台！');
            return { ok: false, archiveName: savingArchiveName, reason: String(e && e.message || e) };
          }
        }

