        function processWorldBookEntries(text) {
          if (!text || typeof text !== 'string') return text;

          return text.replace(/```worldbook\s*([\s\S]*?)\s*```/g, (match, jsonContent) => {
            try {
              const data = JSON.parse(jsonContent.trim());
              if (data && data.title) {
                const span = document.createElement('span');
                span.className = 'world-book-entry-link';
                span.textContent = data.title;
                span.style.color = '#ffd700';
                span.style.cursor = 'pointer';
                span.style.textDecoration = 'underline';
                span.dataset.worldbookJson = JSON.stringify(data);
                return span.outerHTML;
              }
            } catch (e) {
              console.error('解析世界书JSON失败:', e, jsonContent);
            }
            return `[世界书条目: ${jsonContent}]`; // 解析失败时回退
          });
        }

        function showWorldBookDetail(data) {
          const modal = document.getElementById('world-book-detail-overlay');
          const iconEl = document.getElementById('wb-detail-icon');
          const nameEl = document.getElementById('wb-detail-name');
          const bodyEl = document.getElementById('wb-detail-body');

          if (!modal || !iconEl || !nameEl || !bodyEl) return;

          const typeConfig = {
            人物: { icon: 'fa-user-circle' },
            区域: { icon: 'fa-map-marked-alt' },
            势力: { icon: 'fa-shield-alt' },
            秘境: { icon: 'fa-dungeon' },
            天材地宝: { icon: 'fa-gem' },
          };
          const config = typeConfig[data.type] || { icon: 'fa-book' };

          iconEl.className = `fas ${config.icon}`;
          nameEl.textContent = data.title;
          bodyEl.innerHTML = '';

          for (const key in data) {
            if (key !== 'type' && key !== 'title' && key !== 'keywords') {
              const row = document.createElement('div');
              row.className = 'wb-detail-row';
              row.innerHTML = `
                <div class="wb-detail-label">${key}</div>
                <div class="wb-detail-value">${data[key].replace(/\n/g, '<br>')}</div>
            `;
              bodyEl.appendChild(row);
            }
          }

          modal.classList.add('visible');
        }

        function showItemDetail(item, context = {}) {
    item = window.FrItemPresentation.projectMiracleBottle(item);
    item = frVariablePresentation()?.cleanVariableItem(item) ?? item;
    /* lucklyjkop_ui_v10_91_guard */
    const { isEquipped = false, slotType = null, slotIndex = 0, isNpcItem = false, isSectItem = false } = context;

    const modal = document.querySelector('.item-detail-modal');
    modal.innerHTML = '';

    const presentation = window.FrItemPresentation;
    const itemPresentation = presentation.rarity(item);
    const type = item.type || item['2'] || '未知类型';
    const quantity = item.quantity ?? item['5'] ?? 1;
    const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const classification = FrEquipmentRuntime.classify(item);
    modal.classList.toggle('fr-item-dossier-chaos', itemPresentation.ornament === 'chaos');
    modal.classList.add('fr-item-dossier');
    const grade = itemPresentation.label;

    const headerHtml = `
    <div class="item-detail-beautiful-header">
        <div class="item-detail-icon-wrapper fr-item-surface" data-fr-item-tier="${window.FrItemPresentation.ornament(item)}" style="color:${itemPresentation.color};--fr-item-aura:${itemPresentation.color}">
            ${window.FrItemPresentation.icon(item,'item-detail-icon-large')}
        </div>
        <div class="item-detail-title-area">
            <div class="item-detail-name-large" style="color:${itemPresentation.color}">${escape(item.name || item['1'])}</div>
            <div class="item-detail-tags">
                <span class="item-tag">${escape(type)}</span>
                <span class="item-tag">数量: ${escape(formatNumber(quantity))}</span>
                ${grade ? `<span class="item-tag rarity">${escape(grade)}</span>` : ''}
            </div>
        </div>
        <button type="button" aria-label="关闭物品详情" class="modal-close-btn" style="top: 20px; right: 20px;">×</button>
    </div>`;

    const ownerId = context.ownerId || context.characterId || context.npcId;
    const owner = context.owner || (ownerId
        ? currentState?.['0']?.[ownerId] || characterDatabase?.[ownerId]
        : !isNpcItem && !isSectItem ? currentPlayerData : null);
    const options = {};
    if (classification.category === 'technique') {
        options.currentEffect = owner
            ? ceComposeTechniqueCurrentEffect(item.realmEffects || item['8'] || '', ceGetCharacterRealmText(owner)) || '当前境界暂无加成'
            : '';
        if (owner) {
            const entries = ceParseTechniqueRealmEffects(item.realmEffects || item['8'] || '');
            const realm = ceGetCharacterRealmText(owner);
            const rank = frCultivationCore()?.techniqueImmortalRealmRank(realm) ?? ceGetRealmRank(realm,'owner');
            const active = entries.filter(entry => entry.rank === -1 || (rank !== -1 && entry.rank <= rank));
            options.techniqueSpeed = (!entries.length || active.length) ? frCultivationCore()?.resolveTechniqueSpeed(item,active) : null;
        }
        if (!isNpcItem && !isSectItem) {
            const clean = name => String(name || '').replace(/<[^>]+>/g,'').replace(/[《》【】]/g,'').trim();
            const name = clean(item.name || item['1']);
            const known = parseNestedJsonString(parseRemarksString(currentState?.['0']?.B1?.['9']).learned_books, []);
            const learned = name && Array.isArray(known) && known.some(entry => {
                const alias = clean(entry); return alias && (alias.includes(name) || name.includes(alias));
            });
            options.status = isEquipped ? '已装备' : learned ? '已参悟 · 未装备' : '需参悟';
        }
    } else if (owner) {
        options.containerResult = frContainerDetailResult(item,owner);
    }
    const contentHtml = '<div class="item-detail-scroll-area fr-item-dossier-content">' + presentation.detailHtml(item,options) + '</div>';

    let footerHtml = '';
    const btns = [];

    if (isSectItem || isNpcItem) {
    } else if (FrEquipmentRuntime.classify(item).category === 'consumable') {
        btns.push({ id: 'use', text: '使用', icon: 'fa-hand-sparkles', class: 'major-action-button' });
    } else if (isEquipped) {
        btns.push({ id: 'replace', text: '更换', icon: 'fa-exchange-alt', class: 'major-action-button' });
        btns.push({ id: 'unequip', text: '卸下', icon: 'fa-arrow-down', class: 'major-action-button', style: 'background: transparent; border: 1px solid #8c7853;' });
    }

    if (btns.length > 0) {
        footerHtml = `<div class="item-detail-footer">`;
        btns.forEach(btn => {
            footerHtml += `<button id="new-item-btn-${btn.id}" class="${btn.class}" style="${btn.style || ''}"><i class="fas ${btn.icon}"></i> ${btn.text}</button>`;
        });
        footerHtml += `</div>`;
    }

    modal.innerHTML = headerHtml + contentHtml + footerHtml;
    if(Array.isArray(item.stockMembers)&&item.stockMembers.length){
        const content=modal.querySelector('.fr-item-dossier-content');
        const title=document.createElement('h4');
        title.textContent='包内物资';
        content.appendChild(title);
        for(const member of item.stockMembers){
            const button=document.createElement('button');
            button.type='button';
            button.textContent=member['1']+' · '+(member.quantityDetail||member['5']);
            button.addEventListener('click',()=>showItemDetail(member,{...context,isNpcItem:true}));
            content.appendChild(button);
        }
    }

    const closeBtn = modal.querySelector('.modal-close-btn');
    closeBtn.addEventListener('click', closeItemDetail);

    if (btns.length > 0) {
        const useBtn = document.getElementById('new-item-btn-use');
        const replaceBtn = document.getElementById('new-item-btn-replace');
        const unequipBtn = document.getElementById('new-item-btn-unequip');

        if (useBtn) useBtn.onclick = () => addAction('use', item);
        if (replaceBtn) replaceBtn.onclick = () => {
            closeItemDetail();
            openEquipmentPicker(slotType, slotIndex);
        };
        if (unequipBtn) unequipBtn.onclick = () => {
            const slotKeyMap = { '武器': 'weapon', '护甲': 'armor', '功法': 'technique', '法宝': 'treasure' };
            const slotKey = slotKeyMap[slotType] || slotType;
            unequipItem(slotKey, slotIndex);
            closeItemDetail();
        };
    }

    if (isNpcItem || isSectItem) {
        document.getElementById('item-detail-overlay').style.zIndex = 2100;
    } else {
        document.getElementById('item-detail-overlay').style.zIndex = 1800;
    }

    document.getElementById('item-detail-overlay').classList.add('visible');
}

