          imageTaggingJsonImportInput.addEventListener('change', async e => {
            const file = e.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = async event => {
              try {
                const textContent = event.target.result;
                imageTaggingJsonFiles = (await dbGet(IMAGE_TAGGING_JSON_FILES_KEY)) || [];
                const existingNames = new Set(imageTaggingJsonFiles.map(f => f.name));
                let entriesToProcess = [];
                let unnamedCounter = 1;

                try {
                  const importedData = JSON.parse(textContent);
                  if (Array.isArray(importedData)) {
                    entriesToProcess = importedData;
                  } else if (
                    importedData &&
                    typeof importedData.entries === 'object' &&
                    importedData.entries !== null
                  ) {
                    entriesToProcess = Object.values(importedData.entries).map(entry => ({
                      name: entry.comment || entry.name || `导入条目 ${unnamedCounter++}`,
                      content: entry.content || '',
                      keywords: entry.key || entry.keys || entry.keywords || [],
                      triggerMode: entry.key && entry.key.length > 0 ? 'green' : 'blue',
                    }));
                  } else if (importedData && importedData.name && importedData.content) {
                    entriesToProcess = [importedData];
                  }
                } catch (jsonError) {
                  const fallbackName = file.name.replace(/\.[^/.]+$/, '');
                  entriesToProcess.push({
                    name: existingNames.has(fallbackName) ? `${fallbackName}_${Date.now()}` : fallbackName,
                    content: textContent,
                    triggerMode: 'green',
                    keywords: [fallbackName],
                  });
                }

                let addedCount = 0;
                entriesToProcess.forEach(entry => {
                  if (entry && entry.name && !existingNames.has(entry.name)) {
                    const newFile = {
                      id: crypto.randomUUID(),
                      name: entry.name,
                      content: entry.content || '',
                      active: entry.active !== false,
                      triggerMode:
                        entry.triggerMode || (entry.keywords && entry.keywords.length > 0 ? 'green' : 'blue'),
                      keywords: entry.keywords || [],
                    };
                    imageTaggingJsonFiles.push(newFile);
                    existingNames.add(entry.name);
                    addedCount++;
                  }
                });

                if (addedCount > 0) {
                  await dbSet(IMAGE_TAGGING_JSON_FILES_KEY, imageTaggingJsonFiles);
                  renderTextImageJsonList();
                  showDanmaku(`成功导入 ${addedCount} 个新规则条目！`, 'success');
                } else {
                  showDanmaku('没有新的内容被导入（可能已存在同名条目）。', 'info');
                }
              } catch (err) {
                await showCustomAlert(`导入失败: ${err.message}`);
              } finally {
                e.target.value = '';
              }
            };
            reader.readAsText(file);
          });

          /* ★★★ 2026-11-04 玩家：「先做一下统一的api接口配置，在系统设置那里」
           *   + 「先填好api接口，然后再由玩家到对应的系统api设置那里进行分配，
           *      就不用反复填写了……并不是说所有地方一定统一一个api」
           *
           * 所以这里打开的是**接口库**：先存若干条接口，
           * 再到各子系统自己的 API 设置里从库里挑一条。
           * 逻辑都在 core/api-library.js，这里只做挂载。 */
          /* ★★★ 2026-11-04 玩家：
           *   「你两边也不能孤立啊，对应的接口我已经手动填写的你要检测到
           *     然后显示在统一接口配置那里啊，不要我手动填了，你统一配置那里还说是空的」
           *
           * 【根因】两套完全不同的存储：
           *   · 各子系统设置页填的配置 → dbSet → **IndexedDB**
           *   · 统一接口配置读的       → localStorage
           *   两者毫无交集，所以接口库永远看不到玩家已经填好的东西。
           *
           * 【修法】在这里（唯一能同时摸到 db 和 CE_CORE 的地方）做桥接：
           *   ① 把 IndexedDB 里各子系统的配置灌进接口库的内存镜像
           *   ② 给接口库注入一个回写函数，让它改完能同步进 IndexedDB
           *   这样两边就是同一份数据，不再是两个孤岛。 */
          (function bridgeApiLibraryStorage() {
            const getPack = () => {
              try {
                return (typeof CE_CORE === 'object' && CE_CORE) ? CE_CORE['api-library'] : null;
              } catch (_) { return null; }
            };

            /** 把所有子系统的配置从 IndexedDB 读进接口库镜像 */
            const hydrate = async () => {
              const pack = getPack();
              if (!pack) return 0;
              const keys = Array.isArray(pack.API_LIBRARY_CONSUMERS)
                ? Array.from(new Set(pack.API_LIBRARY_CONSUMERS.filter(c => c.storage !== 'local').map(c => c.key)))
                : [];
              if (!keys.length) return 0;
              const snap = {};
              const revisions = {};
              for (const k of keys) {
                try {
                  revisions[k] = pack.apiConfigRevision(k);
                  const v = await dbGet(k);
                  if (v && typeof v === 'object') snap[k] = v;
                } catch (_) {}
              }
              try {
                const n = pack.hydrateFromDb ? pack.hydrateFromDb(snap, revisions) : 0;
                pack.migrateApiChains(await dbGet(THINKING_API_CONFIG_KEY));
                if (n) console.warn('[API 接口库] 已从 IndexedDB 载入 ' + n + ' 份子系统配置');
                return n;
              } catch (e) {
                console.warn('[API 接口库] 载入子系统配置失败：' + (e && e.message ? e.message : e));
                return 0;
              }
            };

            /** 注入回写函数：接口库改完配置要落进 IndexedDB */
            const injectWriter = () => {
              const pack = getPack();
              if (!pack || typeof pack.setDbWriter !== 'function') return false;
              return pack.setDbWriter(async (key, value) => {
                await dbSet(key, value, { apiLibraryWrite: true });
              });
            };

            window.__frApiLibraryHydrate = hydrate;
            injectWriter();

            // 启动时桥接一次；db 可能还没就绪，所以失败就重试
            let tries = 0;
            const boot = async () => {
              tries++;
              injectWriter();
              const n = await hydrate();
              if (!n && tries < 20) return setTimeout(boot, 700);
              // 灌完再刷新一次界面，保证打开设置时看到的是真实数据
              try { if (typeof window.__frRefreshApiEmbeds === 'function') window.__frRefreshApiEmbeds(); } catch (_) {}
            };
            setTimeout(boot, 1200);
          })();

          /* ★★★ 2026-11-04 玩家：「每个接口具体用哪个设置的模型应该去每个接口那里选」
           *
           * 各子系统设置页里嵌了「从接口库选择」（HTML 里那些
           * data-fr-api-consumer 占位）。这里做两件事：
           *   ① 打开系统设置时刷新所有嵌入框，保证显示的是最新值
           *      （否则玩家改了库，设置页里还显示旧接口）
           *   ② 把「工具函数」挂到 window 上，方便设置面板重绘后再次同步。
           *
           * 用统一入口而不是每个设置页各写一遍绑定，避免以后新增子系统时漏掉。 */
          (function initApiLibraryEmbeds() {
            const refreshEmbeds = () => {
              try {
                const pack = (typeof CE_CORE === 'object' && CE_CORE) ? CE_CORE['api-library'] : null;
                if (pack && typeof pack.mountAllApiEmbeds === 'function') {
                  pack.mountAllApiEmbeds();
                }
              } catch (e) {
                console.warn('[API 接口库] 嵌入框刷新失败：' + (e && e.message ? e.message : e));
              }
            };
            window.__frRefreshApiEmbeds = refreshEmbeds;
            window.__frResolveLocalApiConfig = (key, config) => {
              const pack = CE_CORE['api-library'];
              return pack.resolveConsumerConfig(key, config);
            };
            window.__frApiRoutes = frApiRoutes;
            window.__frRunApiRoutes = frRunApiRoutes;
            window.__frLocalApiConfigChanged = (key, config) => {
              const pack = CE_CORE['api-library'];
              pack.rememberApiModels(key, config);
              refreshEmbeds();
            };
            // 打开系统设置时刷新一次（设置面板里才有这些嵌入框）
            const sysBtn = document.getElementById('system-settings-button');
            if (sysBtn) {
              sysBtn.addEventListener('click', () => {
                // 先重新灌一次 IndexedDB 数据（玩家可能刚在子页面里填过）
                try {
                  if (typeof window.__frApiLibraryHydrate === 'function') window.__frApiLibraryHydrate();
                } catch (_) {}
                // 等面板里的 DOM 可见后再画，否则宽高都算不准
                setTimeout(refreshEmbeds, 60);
                setTimeout(refreshEmbeds, 300);
              });
            }
            // 首屏也刷一次，覆盖「直接打开某个设置页」的情况
            setTimeout(refreshEmbeds, 800);
          })();

          document.getElementById('open-unified-api-settings-btn').addEventListener('click', async () => {
            const overlay = document.getElementById('unified-api-settings-overlay');
            systemSettingsOverlay.classList.remove('visible');
            // Finish the database read before exposing editable fields.
            if (typeof window.__frApiLibraryHydrate === 'function') await window.__frApiLibraryHydrate();
            try {
              // 模块 id 是去 .js 的文件名（见 build/lib/bundle-core.mjs moduleId），
              // 所以 api-library 挂在 CE_CORE['api-library'] 上。
              var libPack = (typeof CE_CORE === 'object' && CE_CORE) ? CE_CORE['api-library'] : null;
              if (libPack && typeof libPack.bindApiLibraryPanel === 'function') {
                libPack.bindApiLibraryPanel(overlay, {probeImage: async (consumer, config, prompt, signal) => {
                  const provider = consumer?.path?.[1];
                  let image;
                  if (consumer?.path?.[0] === 'imageProviderConfigs') {
                    const saved = await loadConcurrentEvolutionConfig();
                    image = await ceCallImageGenerationOnce(libPack.imageRouteConfig(
                      {...saved.imageProviderConfigs?.[provider],provider},config),prompt,signal);
                  } else if (provider) {
                    const saved = await loadPortraitGenConfig();
                    _portraitEnsureProviderConfigs(saved);
                    image = await callCommercialImageGenOnce({...saved,provider},prompt,signal,
                      libPack.imageRouteConfig(_portraitGetProviderConfig(saved,provider),config));
                  } else if (new URL(config.apiUrl).hostname === 'generativelanguage.googleapis.com' ||
                      /:generateContent$/i.test(new URL(config.apiUrl).pathname)) {
                    image = await _portraitCallGeminiImageGen(config,prompt,signal);
                  } else {
                    const url = new URL(config.apiUrl);
                    image = /\/chat\/completions\/?$/i.test(url.pathname)
                      ? await _portraitCallCustomOpenAiImageGen(config,prompt,signal)
                      : await _portraitCallOpenAiImageGen(libPack.imageRouteConfig({},config),prompt,signal);
                  }
                  if (!image) throw new Error('未收到有效图片');
                }});
              } else {
                console.warn('[API 接口库] 模块未加载（CE_CORE[api-library] 不可用）');
              }
            } catch (e) {
              console.warn('[API 接口库] 面板绑定失败：' + (e && e.message ? e.message : e), e);
            }
            overlay.classList.add('visible');
          });
          document
            .getElementById('unified-api-settings-overlay')
            .querySelector('.modal-close-btn')
            .addEventListener('click', () => {
              const overlay=document.getElementById('unified-api-settings-overlay');
              overlay.classList.remove('visible');
              overlay.style.zIndex='';
            });

          document.getElementById('export-segmented-memory-btn').addEventListener('click', exportSegmentedMemory);
          document.getElementById('import-segmented-memory-btn').addEventListener('click', importSegmentedMemory);


          document.getElementById('npc-avatar-fullscreen-overlay').addEventListener('click', () => {
            document.getElementById('npc-avatar-fullscreen-overlay').classList.remove('visible');
          });

          document.getElementById('ctx-resend-btn').addEventListener('click', async () => {
            /* 2026-11-02：原来这里 if(isMainApiGenerating) return; 是**静默**返回，
             * 玩家点下去没有任何反馈，观感就是"点不动、卡死了"。
             * 现在至少告诉玩家为什么点不了。 */
            if (isMainApiGenerating) {
              hideContextMenu();
              try{showDanmaku('本轮还在生成中，请先点停止再重roll','info');}catch(_){}
              return;
            }
            if (!activeLogEntry) {
              hideContextMenu();
              return;
            }
            const currentActiveLogEntry = activeLogEntry;
            hideContextMenu();

            try {
              const archive = await db.archives.get(currentArchiveName);
              if (!archive) throw new Error('找不到当前存档。');

              const logs = archive.data.logs;
              /* 2026-11-02 玩家：「我无法再右键重roll了」
               *
               * 原来这里直接用当前右键条目的 dataset.logId 去存档里找楼层。
               * 但**页面上的条目不一定都进了存档**：比如中止时那条红色提示、
               * 临时系统提示，它们只是画在 DOM 上的，logs 里根本没有。
               * 那种条目右键后 targetLogIndex === -1，直接抛
               * 「在存档中找不到目标消息」，这轮就重roll不了了。
               *
               * 玩家真正想重roll的是「最后一个真实回合」。所以找不到时
               * 不再报错，而是往下找最近一个真正落库的楼层：
               * 优先 AI 楼层（重roll它的正文），没有 AI 就找 user 楼层
               * （重发那句话）。只有整个存档一条都没有时才报错。
               */
              let targetLogId = currentActiveLogEntry.dataset.logId || '';
              let targetLogIndex = targetLogId ? logs.findIndex((log) => log.id === targetLogId) : -1;
              if (targetLogIndex === -1 && frFailedMainPrompt?.archiveName === currentArchiveName) {
                const cachedIndex = logs.findIndex(log => log.id === frFailedMainPrompt.userLogId);
                if (cachedIndex >= 0 && !logs.slice(cachedIndex + 1).some(log => log.type === 'user')) { targetLogIndex = cachedIndex; targetLogId = logs[cachedIndex].id; }
              }
              if (targetLogIndex === -1) {
                for (let i = logs.length - 1; i >= 0; i--) {
                  if (logs[i].type === 'ai') { targetLogIndex = i; targetLogId = logs[i].id; break; }
                }
                if (targetLogIndex === -1) {
                  for (let i = logs.length - 1; i >= 0; i--) {
                    if (logs[i].type === 'user') { targetLogIndex = i; targetLogId = logs[i].id; break; }
                  }
                }
              }

              if (targetLogIndex === -1) throw new Error('在存档中找不到目标消息。');

              const targetLog = logs[targetLogIndex];

              let userMessageToResend = '';
              let referenceLogIndex = -1;

              if (targetLog.type === 'user') {
                userMessageToResend = targetLog.content;
                referenceLogIndex = targetLogIndex;
              } else {
                let userLogIndex = -1;
                for (let i = targetLogIndex - 1; i >= 0; i--) {
                  if (logs[i].type === 'user') {
                    userLogIndex = i;
                    break;
                  }
                }

                if (userLogIndex === -1) {
                  throw new Error('在此消息之前没有找到任何玩家的输入记录，无法重新发送。');
                }
                userMessageToResend = logs[userLogIndex].content;
                referenceLogIndex = userLogIndex;
              }

              if (await frRetryFailedMainPrompt(logs[referenceLogIndex].id)) return;

              let stateSnapshotIndex = -1;
              for (let i = referenceLogIndex - 1; i >= 0; i--) {
                if (logs[i].stateSnapshot) {
                  stateSnapshotIndex = i;
                  break;
                }
              }

              if (stateSnapshotIndex === -1) {
                throw new Error('无法重新发送：找不到可回溯的状态快照。');
              }

              const logIdToLoad = logs[stateSnapshotIndex].id;

              const rollbackSuccess = await loadStateFromLog(logIdToLoad, true);
              if (!rollbackSuccess) {
                throw new Error('回溯存档状态失败，操作已中止。');
              }

              const cleanMessage = userMessageToResend.replace(/^> /, '');

              await sendMessage(cleanMessage);
            } catch (error) {
              console.error('重新发送时出错:', error.message);
              await showCustomAlert(`操作失败: ${error.message}`);

              isMainApiGenerating = false;
              sendMessageButton.disabled = false;
              sendMessageButton.innerHTML = '<i class="fas fa-paper-plane"></i>';
              sendMessageButton.title = '发送';
              sendMessageButton.onclick = () => sendMessage();

              const latestArchive = await db.archives.get(currentArchiveName);
              if (latestArchive) {
                await loadState(latestArchive.data.state);
                loadChatHistory(latestArchive.data.logs, latestArchive);
              }
            }
          });

