        async function renderRegexPresets() {
          const listEl = document.getElementById('regex-presets-list');
          listEl.innerHTML = '';
          let presets = (await dbGet(REGEX_PRESETS_KEY)) || [];

          // 内置正则预设（2026-10-31）：把包内自带的 199 条做成一个可一键恢复的预设。
          // 玩家删光了也能从这里点回来，不用再手动导入 JSON。
          var bi = null;
          try { bi = window.__FR_BUILTIN_REGEX__ || null; } catch (e) { bi = null; }
          if (bi && Array.isArray(bi.rules) && bi.rules.length) {
            var hasBuiltin = presets.some(function (p) { return p && p.builtin === true; });
            if (!hasBuiltin) {
              presets = [{
                name: '万物有灵适配正文正则（内置）',
                builtin: true,
                rules: bi.rules,
                chainRules: bi.chainRules || []
              }].concat(presets);
            }
          }

          if (presets.length === 0) {
            listEl.innerHTML = '<p style="text-align:center; opacity:0.7;">暂无预设</p>';
            return;
          }

          presets.forEach((preset, index) => {
            const item = document.createElement('div');
            item.className = 'regex-rule-item'; // 复用样式
            // 内置预设不给删除按钮（删了也还在，容易误导），只给「加载」
            const delBtn = preset.builtin
              ? '<span title="内置预设，无法删除" style="opacity:.45;padding:0 8px">内置</span>'
              : `<button data-index="${index}" class="delete-preset-btn" title="删除此预设">删除</button>`;
            item.innerHTML = `
<span class="rule-name">${preset.name}</span>
<div class="rule-actions">
<button data-index="${index}" class="load-preset-btn" title="加载此预设">加载</button>
${delBtn}
</div>
`;
            listEl.appendChild(item);
          });

          listEl.querySelectorAll('.load-preset-btn').forEach(btn => {
            btn.addEventListener('click', async () => {
              const index = parseInt(btn.dataset.index);
              const chosen = presets[index];
              if (!chosen) return;
              regexConfig.rules = frUpgradeStoryRegexRules(JSON.parse(JSON.stringify(chosen.rules || [])), false);
              regexConfig.chainRules = JSON.parse(JSON.stringify(chosen.chainRules || []));
              await dbSet(REGEX_CONFIG_KEY, regexConfig);
              renderRegexRulesUI();
              await showCustomAlert(`预设 "${chosen.name}" 已加载并保存！`);
            });
          });

          listEl.querySelectorAll('.delete-preset-btn').forEach(btn => {
            btn.addEventListener('click', async () => {
              const index = parseInt(btn.dataset.index);
              const chosen = presets[index];
              if (!chosen || chosen.builtin) return;   // 内置预设不可删
              if (!(await showCustomConfirm(`确定要删除预设 "${chosen.name}" 吗？`))) return;
              // 注意：列表里可能混入了内置项，落库前要先剔除，避免把内置项写进数据库
              let allPresets = ((await dbGet(REGEX_PRESETS_KEY)) || []).filter(p => !(p && p.builtin));
              const at = allPresets.findIndex(p => p && p.name === chosen.name);
              if (at >= 0) allPresets.splice(at, 1);
              await dbSet(REGEX_PRESETS_KEY, allPresets);
              await renderRegexPresets();
            });
          });
        }

        async function createRegexPreset() {
          const name = await showCustomPrompt('请输入预设名称：');
          if (!name || !name.trim()) return;

          const newPreset = {
            name: name.trim(),
            rules: JSON.parse(JSON.stringify(regexConfig.rules || [])),
            chainRules: JSON.parse(JSON.stringify(regexConfig.chainRules || [])),
          };

          const presets = (await dbGet(REGEX_PRESETS_KEY)) || [];
          const existingIndex = presets.findIndex(p => p.name === newPreset.name);

          if (existingIndex > -1) {
            if (await showCustomConfirm(`已存在同名预设 "${newPreset.name}"，是否要覆盖？`)) {
              presets[existingIndex] = newPreset;
            } else {
              return;
            }
          } else {
            presets.push(newPreset);
          }

          await dbSet(REGEX_PRESETS_KEY, presets);
          await showCustomAlert('正则预设已保存！');
          await renderRegexPresets();
        }

