          document.getElementById('creation-initial-realm').addEventListener('change', e => {
            const option=frInitialRealmCore().getInitialRealmOption(e.target.value);
            creationState.initialRealm=option.realm;
            document.getElementById('creation-initial-realm-summary').innerHTML=frInitialRealmDescription(option);
          });

          // 【玩家姓名】边输边存；存两处：配置 playerName（垫片预设宏用）与 localStorage
          (function bindPlayerName() {
            var nEl = document.getElementById('player-name-input');
            if (!nEl) return;
            // 首次进入回填：优先 localStorage，其次配置
            if (!nEl.value) {
              var saved = (typeof window.frPlayerNameGet === 'function' ? window.frPlayerNameGet() : '') || '';
              if (!saved) {
                try {
                  var c = window.FRStandaloneConfig?.load?.();
                  saved = (c && c.playerName && c.playerName !== '玩家') ? c.playerName : '';
                } catch (e) { saved = ''; }
              }
              if (saved) { nEl.value = saved; creationState._playerName = saved; }
            }
            function persistName() {
              var v = String(nEl.value || '').trim();
              creationState._playerName = v;
              try {
                if (typeof window.frPlayerNameSave === 'function') window.frPlayerNameSave(v);
              } catch (e) {}
              try {
                if (typeof window.FRStandaloneConfig?.save === 'function') {
                  window.FRStandaloneConfig.save({ playerName: v || '玩家' });
                }
              } catch (e) {}
            }
            nEl.addEventListener('input', persistName);
            nEl.addEventListener('change', persistName);
          })();

          // 【玩家性格】边输边存，避免玩家切页签或点下一步后丢内容
          (function bindPersona() {
            var tEl = document.getElementById('persona-text');
            var onEl = document.getElementById('persona-enabled');
            if (!tEl || !onEl) return;

            // 首次进入：如果玩家还从没填过性格，默认勾选「启用」
            var saved = (typeof frPlayerPersonaGet === 'function' ? frPlayerPersonaGet() : null) || null;
            var hadText = !!(saved && String(saved.text || '').trim());
            if (!hadText) onEl.checked = true;
            else if (typeof saved.enabled === 'boolean') onEl.checked = saved.enabled;

            function persistPersona() {
              creationState._personaEnabled = !!onEl.checked;
              creationState._personaText = String(tEl.value || '');
              if (typeof frPlayerPersonaSave === 'function') {
                try {
                  frPlayerPersonaSave({ enabled: onEl.checked, text: String(tEl.value || '').trim() });
                } catch (e) { console.warn('[性格] 保存失败:', e); }
              }
            }
            tEl.addEventListener('input', persistPersona);
            onEl.addEventListener('change', persistPersona);
            // 初始值同步进 state，供「下一步」用
            creationState._personaEnabled = !!onEl.checked;
            creationState._personaText = String(tEl.value || '');
          })();

          document
            .getElementById('upload-custom-avatar-btn')
